import { hex, mix, scale, type RGB } from '../../../world/biomes';
import type { RegionBuildingKind } from '../../../world/tiles';
import type { Sched } from '../../nightLights';
import { DARK, METAL, SHOP_GLOW, TAU, TRUNK, WARM_GLOW, type Draw, type Kit, type P3 } from '../kit';
import { eastRoof } from './terraces';
import { lump } from './veldt';

/**
 * The Fens: shrimp shack, airboat dock, general store and the plantation house. Weathered grey
 * timber and rusting tin on stilts over black-green water, and one white mansion at the end of an
 * avenue of live oaks hung with moss.
 */

const WEATHERED = hex(0x8a8274), PLANK = hex(0x9a8a6a), PILE = hex(0x5a4a3a), TIN = hex(0xa7abad), RUST = hex(0x9a5a3a);
const BAYOU = hex(0x3f5a4a), NET = hex(0x4a4a42), CREAM = hex(0xefe6cc), SHUTTER = hex(0x3f5a4a), SLATE = hex(0x5a5f66);
const MANOR = hex(0xf6f3ea), OAK = hex(0x4a7a36), OAK_BARK = hex(0x5a4a3a), MOSS = hex(0x9aa08a), HEDGE = hex(0x3f7a3a);
const GRAVEL = hex(0xd9c9a3), BRICK = hex(0xa4583f);
const PORCH: Sched = [17.5, 29, 1.4];

// ---- shared pieces -------------------------------------------------------------------------------

/** Tin roof pitched along z over a w × d box standing at y, with rust streaks. */
function tinRoof(k: Kit, x: number, y: number, z: number, w: number, d: number, h: number, wall: RGB): void {
  k.gable(x, y, z, w, h, d, TIN, wall, true);
  k.box(x + w * 0.22, y + h * 0.5, z, 0.03, 0.01, d * 0.9, RUST);
}

/** A live oak: a short thick trunk, limbs spread wide, a low flat crown with moss hanging from it. */
function liveOak(k: Kit, x: number, z: number, s: number, seed: number): void {
  k.cyl(x, 0, z, 0.1 * s, 0.3 * s, OAK_BARK, 6);
  for (let i = 0; i < 4; i++) {
    const a = (i / 4) * TAU + seed;
    k.bar([x, 0.25 * s, z], [x + Math.cos(a) * 0.55 * s, 0.52 * s, z + Math.sin(a) * 0.55 * s], 0.035 * s, OAK_BARK);
  }
  for (let i = 0; i < 4; i++) {
    const a = (i / 4) * TAU + seed + 0.8, d = i === 0 ? 0 : 0.5 * s;
    lump(k, x + Math.cos(a) * d, 0.62 * s + (i === 0 ? 0.12 * s : 0), z + Math.sin(a) * d, 0.55 * s, 0.24 * s, 0.5 * s, scale(OAK, 0.92 + (i % 2) * 0.1), seed * 5 + i, 7, 4);
  }
  for (let i = 0; i < 7; i++) {
    const a = (i / 7) * TAU + seed * 2, d = (0.55 + (i % 3) * 0.2) * s, len = (0.18 + (i % 2) * 0.1) * s;
    k.box(x + Math.cos(a) * d, 0.5 * s - len, z + Math.sin(a) * d, 0.035 * s, len, 0.035 * s, MOSS);
  }
}

/** A crab pot: a small wire cage. */
function crabPot(k: Kit, x: number, y: number, z: number): void {
  k.box(x, y, z, 0.07, 0.05, 0.07, hex(0x6b7a6a), hex(0x8a9a8a));
  k.box(x, y + 0.05, z, 0.02, 0.005, 0.02, hex(0xe8a030));
}

// ---- 1. shrimp shack -----------------------------------------------------------------------------

const shrimpShack: Draw = (k, _W, _D, b) => {
  const deckY = 0.12;
  // piles down into the water, the deck and the shack on it
  for (const px of [-0.36, 0, 0.36]) for (const pz of [-0.36, 0, 0.36]) k.box(px, -0.8, pz, 0.045, 0.8 + deckY, 0.045, PILE);
  k.box(0, deckY, 0, 0.82, 0.04, 0.82, PLANK);
  const sz = -0.12, wall = scale(WEATHERED, 0.95 + (b.seed % 3) * 0.04);
  k.box(0.06, deckY + 0.04, sz, 0.5, 0.28, 0.42, wall);
  for (let i = 0; i < 5; i++) k.box(0.06, deckY + 0.07 + i * 0.05, sz + 0.2135, 0.5, 0.006, 0.005, scale(wall, 0.8));
  k.box(0.18, deckY + 0.04, sz + 0.217, 0.1, 0.2, 0.01, hex(0x3a4a5a));
  k.pane(-0.08, deckY + 0.14, sz + 0.216, 0.1, 0.08, 1, DARK, PORCH, WARM_GLOW);
  tinRoof(k, 0.06, deckY + 0.32, sz, 0.6, 0.52, 0.14, wall);
  // a porch roof on two posts over the front, a hand-painted sign
  for (const px of [-0.2, 0.32]) k.box(px, deckY + 0.04, 0.33, 0.025, 0.24, 0.025, PILE);
  k.quad([-0.24, deckY + 0.3, sz + 0.24], [0.36, deckY + 0.3, sz + 0.24], [0.36, deckY + 0.26, 0.36], [-0.24, deckY + 0.26, 0.36], TIN, [0, 0, 0]);
  k.quad([-0.24, deckY + 0.3, sz + 0.24], [0.36, deckY + 0.3, sz + 0.24], [0.36, deckY + 0.26, 0.36], [-0.24, deckY + 0.26, 0.36], scale(TIN, 0.6), [0, 1, 0]);
  k.box(0.06, deckY + 0.47, sz + 0.1, 0.34, 0.1, 0.02, hex(0xe8e0c8));
  k.box(0.06, deckY + 0.5, sz + 0.1135, 0.26, 0.03, 0.005, hex(0xc03a2a));
  k.glowBox(-0.2, deckY + 0.26, 0.34, 0.03, 0.03, 0.03, hex(0xf0e0b0), PORCH, WARM_GLOW);
  // a net hung to dry on a pole frame, crab pots stacked, a skiff tied up alongside
  const nx = -0.3;
  for (const pz of [-0.3, 0.1]) k.box(nx, deckY + 0.04, pz, 0.02, 0.34, 0.02, PILE);
  k.bar([nx, deckY + 0.38, -0.3], [nx, deckY + 0.38, 0.1], 0.008, PILE);
  for (let i = 0; i < 6; i++) k.bar([nx, deckY + 0.38, -0.28 + i * 0.07], [nx - 0.02, deckY + 0.1 + (i % 2) * 0.04, -0.28 + i * 0.07], 0.004, NET);
  k.bar([nx - 0.01, deckY + 0.22, -0.3], [nx - 0.01, deckY + 0.24, 0.1], 0.003, NET);
  for (let i = 0; i < 3; i++) crabPot(k, 0.3, deckY + 0.04 + (i === 2 ? 0.05 : 0), 0.22 + (i === 1 ? 0.08 : 0) + (i === 2 ? 0.04 : 0));
  k.box(0.52, -0.02, 0.02, 0.14, 0.05, 0.5, hex(0x6b8a9a), hex(0x5a4a3a));
  k.box(-0.3, deckY + 0.04, 0.3, 0.1, 0.08, 0.08, hex(0x3a6aa8));
};

// ---- 2. airboat dock -----------------------------------------------------------------------------

/** An airboat facing +z: a flat hull, a raised seat and a big caged fan at the stern. */
function airboat(k: Kit, x: number, y: number, z: number, hull: RGB, spinning: boolean): void {
  k.box(x, y, z, 0.3, 0.06, 0.62, hull, hex(0xd8d8d0));
  k.wedge(x, y, z + 0.37, 0.3, 0.06, 0.12, hull);
  for (let i = 0; i < 2; i++) k.box(x, y + 0.06, z + 0.12 - i * 0.14, 0.24, 0.035, 0.05, hex(0x3a3f45));
  k.box(x, y + 0.06, z - 0.12, 0.03, 0.14, 0.03, METAL);
  k.box(x, y + 0.2, z - 0.12, 0.1, 0.04, 0.08, hex(0x3a3f45));
  k.box(x, y + 0.06, z - 0.22, 0.12, 0.08, 0.08, DARK);
  const fy = y + 0.2, fz = z - 0.3;
  k.hoop(x, fy, fz - 0.03, 0.16, 0.006, METAL, 12, 'xy');
  for (let i = 0; i < 4; i++) {
    const a = (i / 4) * TAU + 0.4;
    k.bar([x, fy, fz - 0.03], [x + Math.cos(a) * 0.16, fy + Math.sin(a) * 0.16, fz - 0.03], 0.003, METAL);
  }
  for (const sx of [-1, 1]) k.bar([x + sx * 0.12, y + 0.06, fz + 0.05], [x + sx * 0.12, fy + 0.1, fz - 0.03], 0.006, METAL);
  k.spin(x, fy, fz, 'z', spinning ? 9 : 0, (s) => {
    for (const a of [0.3, 0.3 + Math.PI]) s.bar([0, 0, 0], [Math.cos(a) * 0.14, Math.sin(a) * 0.14, 0], 0.012, hex(0x2a2a2a));
    s.cyl(0, -0.02, 0, 0.02, 0.04, METAL, 6);
  });
  for (const sx of [-0.06, 0.06]) k.box(x + sx, y + 0.08, fz - 0.08, 0.005, 0.18, 0.06, hull);
}

const airboatDock: Draw = (k, W, D, b) => {
  // a boardwalk across the front and two finger piers out to the water behind
  k.box(0, 0.06, 0.35, W - 0.1, 0.03, 0.4, PLANK);
  for (const px of [-W / 2 + 0.1, 0, W / 2 - 0.1]) {
    k.box(px, -0.4, 0.35, 0.04, 0.46, 0.04, PILE);
    k.box(px, 0.06, -0.35, 0.18, 0.03, 0.9, PLANK);
    for (const pz of [-0.1, -0.5, -0.78]) k.box(px, -0.4, pz, 0.04, 0.5, 0.04, PILE);
    k.box(px, 0.09, -D / 2 + 0.2, 0.05, 0.08, 0.05, PILE);
  }
  for (let i = 0; i < 8; i++) k.box(-W / 2 + 0.12 + i * ((W - 0.24) / 7), 0.09, 0.35, 0.005, 0.006, 0.4, scale(PLANK, 0.8));
  // two boats moored between the piers, fans to the water; one idling
  airboat(k, -0.45, -0.04, -0.4, hex(0x3f7a4a), false);
  airboat(k, 0.45, -0.04, -0.45, hex(0xe8e8e0), b.seed % 2 === 0);
  // the ticket hut with its sign, life rings and a gas can
  const hx = -W / 2 + 0.35, hz = 0.72;
  k.box(hx, 0.09, hz, 0.46, 0.3, 0.3, hex(0x5a7a8a));
  k.box(hx + 0.08, 0.2, hz + 0.155, 0.22, 0.12, 0.01, DARK);
  k.glowBox(hx + 0.08, 0.2, hz + 0.16, 0.2, 0.1, 0.012, hex(0x8a9aa0), PORCH, SHOP_GLOW);
  tinRoof(k, hx, 0.39, hz, 0.54, 0.38, 0.1, hex(0x5a7a8a));
  k.box(0.35, 0.09, 0.62, 0.02, 0.36, 0.02, PILE);
  k.box(0.35, 0.36, 0.62, 0.5, 0.12, 0.02, hex(0xf2c14e));
  k.box(0.35, 0.39, 0.6335, 0.4, 0.05, 0.005, hex(0x2a2a2a));
  k.glowBox(0.35, 0.48, 0.62, 0.04, 0.03, 0.04, hex(0xf0e0b0), PORCH, WARM_GLOW);
  for (const px of [-0.05, 0.1]) k.hoop(px + 0.5, 0.2, 0.15, 0.04, 0.008, hex(0xe8452a), 8, 'xy');
  k.box(0.75, 0.09, 0.45, 0.06, 0.08, 0.04, hex(0xc03a2a));
};

// ---- 3. general store ----------------------------------------------------------------------------

const generalStore: Draw = (k, W, D, b, r) => {
  const sy = 0.12, bz = -0.12, bw = W - 0.4, bd = D - 0.4, wall = b.seed % 2 ? CREAM : hex(0xb8a88a), h = 0.34;
  // short stilts and the raised floor
  for (let i = 0; i < 5; i++) for (const pz of [bz - bd / 2 + 0.04, bz + bd / 2 + 0.2]) k.box(-W / 2 + 0.2 + i * ((W - 0.4) / 4), 0, pz, 0.04, sy, 0.04, PILE);
  k.box(0, sy, bz + 0.1, W - 0.3, 0.03, bd + 0.24, PLANK);
  // clapboard walls and a tin roof behind a tall false front
  k.box(0, sy + 0.03, bz, bw, h, bd, wall);
  for (let i = 0; i < 5; i++) k.box(0, sy + 0.08 + i * 0.06, bz + bd / 2 + 0.003, bw, 0.006, 0.006, scale(wall, 0.85));
  tinRoof(k, 0, sy + 0.03 + h, bz - 0.03, bw + 0.06, bd + 0.02, 0.16, wall);
  k.box(0, sy + 0.03 + h, bz + bd / 2 - 0.02, bw, 0.22, 0.04, wall);
  k.box(0, sy + 0.25 + h, bz + bd / 2 - 0.02, bw + 0.04, 0.025, 0.06, hex(0x6b4a2a));
  k.box(0, sy + h + 0.07, bz + bd / 2 + 0.002, bw * 0.8, 0.1, 0.01, hex(0x8a2a2a));
  for (let i = 0; i < 6; i++) k.box(-bw * 0.32 + i * bw * 0.128, sy + h + 0.1, bz + bd / 2 + 0.011, 0.08, 0.04, 0.004, hex(0xf2e8c8));
  // the shop windows and door
  for (const px of [-0.42, 0.42]) k.pane(px, sy + 0.09, bz + bd / 2 + 0.006, 0.36, 0.18, 1, hex(0x4a5a66), [16.5, 21, 1.6], SHOP_GLOW);
  k.box(0, sy + 0.03, bz + bd / 2 + 0.008, 0.14, 0.26, 0.008, hex(0x3f5a4a));
  k.pane(0, sy + 0.16, bz + bd / 2 + 0.012, 0.08, 0.08, 1, hex(0x4a5a66), [16.5, 21, 1.6], SHOP_GLOW);
  // the porch: posts, a lean-to tin roof, a bench, barrels and a soda sign; steps to the road
  const pz = bz + bd / 2 + 0.2;
  for (let i = 0; i < 4; i++) k.box(-W / 2 + 0.2 + i * ((W - 0.4) / 3), sy + 0.03, pz, 0.025, 0.28, 0.025, WEATHERED);
  const ry = sy + 0.33, I: P3 = [0, 0, bz];
  k.quad([-W / 2 + 0.15, ry + 0.04, bz + bd / 2], [W / 2 - 0.15, ry + 0.04, bz + bd / 2], [W / 2 - 0.15, ry - 0.02, pz + 0.04], [-W / 2 + 0.15, ry - 0.02, pz + 0.04], TIN, I);
  k.quad([-W / 2 + 0.15, ry + 0.04, bz + bd / 2], [W / 2 - 0.15, ry + 0.04, bz + bd / 2], [W / 2 - 0.15, ry - 0.02, pz + 0.04], [-W / 2 + 0.15, ry - 0.02, pz + 0.04], scale(TIN, 0.6), [0, 1, bz + 0.3]);
  k.box(-0.3, sy + 0.03, pz - 0.08, 0.26, 0.05, 0.06, WEATHERED);
  for (let i = 0; i < 2; i++) k.cyl(0.62 + i * 0.1, sy + 0.03, pz - 0.08, 0.04, 0.1, TRUNK, 7, hex(0x5a4a3a));
  k.glowBox(0.25, sy + 0.18, bz + bd / 2 + 0.01, 0.1, 0.1, 0.01, hex(0xd8352a), [17, 22, 1.4], hex(0xff6a50));
  for (let i = 0; i < 2; i++) k.box(0, (sy * (1 - i)) / 2, pz + 0.14 + i * 0.06, 0.3, sy * (i ? 0.5 : 1) , 0.06, PLANK);
  // an old gas pump and a pickup out front
  k.box(W / 2 - 0.12, 0, pz + 0.16, 0.08, 0.2, 0.06, hex(0xc03a2a));
  k.glowBox(W / 2 - 0.12, 0.2, pz + 0.16, 0.06, 0.05, 0.05, hex(0xf2e8c8), PORCH, WARM_GLOW);
  if (r() < 0.7) {
    k.box(-W / 2 + 0.35, 0, pz + 0.2, 0.36, 0.09, 0.18, hex(0x6a8aa8));
    k.box(-W / 2 + 0.3, 0.09, pz + 0.2, 0.14, 0.07, 0.16, hex(0x6a8aa8), hex(0x5a7a98));
  }
};

// ---- 4. plantation house (wonder) ----------------------------------------------------------------

const plantationManor: Draw = (k, _W, D, b) => {
  const lit = (i: number): Sched => ((i * 7 + b.seed) % 6 === 0 ? [99, 0, 0] : [17.3 + ((i * 3) % 7) * 0.15, 22.5 + ((i * 5) % 9) * 0.25, 1.5]);
  const zc = -3.6, hw = 2.6, hd = 1.4, base = 0.18, storey = 0.55, wallH = storey * 2;
  const gx = 3.2, gz0 = zc - 2.0, gz1 = zc + 2.0;
  // the raised base under house and gallery, the house itself
  k.box(0, 0, zc, 2 * gx + 0.1, base, gz1 - gz0 + 0.1, hex(0xe8e2d4));
  k.box(0, base, zc, 2 * hw, wallH, 2 * hd, MANOR);
  // tall shuttered windows on both storeys, a fanlit door in the middle
  let n = 0;
  for (let f = 0; f < 2; f++) {
    const y = base + 0.1 + f * storey;
    for (let i = 0; i < 7; i++) {
      const x = -hw + 0.4 + i * ((2 * hw - 0.8) / 6);
      for (const [face, z] of [[1, zc + hd], [3, zc - hd]] as const) {
        if (f === 0 && i === 3) {
          k.pane(x, base, z, 0.3, 0.38, face, hex(0x3f3a36), lit(n++), WARM_GLOW);
          k.pane(x, base + 0.4, z, 0.26, 0.08, face, hex(0x8a9aa0), lit(n++), WARM_GLOW);
          continue;
        }
        k.pane(x, y, z, 0.16, 0.34, face, hex(0x4a5a66), lit(n++), WARM_GLOW);
        const sz = face === 1 ? z + 0.012 : z - 0.012;
        for (const sx of [-1, 1]) k.box(x + sx * 0.13, y, sz, 0.09, 0.34, 0.012, SHUTTER);
      }
    }
    for (let i = 0; i < 3; i++) {
      const z = zc - hd + 0.5 + i * ((2 * hd - 1) / 2);
      for (const sx of [-1, 1]) k.pane(sx * hw, y, z, 0.16, 0.34, sx > 0 ? 0 : 2, hex(0x4a5a66), lit(n++), WARM_GLOW);
    }
  }
  // the gallery: a full-height colonnade on all four sides, with an upper floor and a railing
  const colH = wallH + 0.05;
  const column = (x: number, z: number) => {
    k.box(x, base, z, 0.2, 0.04, 0.2, MANOR);
    k.cyl(x, base + 0.04, z, 0.085, colH - 0.08, hex(0xfbfaf4), 8);
    k.box(x, base + colH - 0.05, z, 0.22, 0.05, 0.22, MANOR);
  };
  const nFront = 11, nSide = 7;
  for (let i = 0; i < nFront; i++) {
    const x = -gx + 0.05 + i * ((2 * gx - 0.1) / (nFront - 1));
    column(x, gz1 - 0.05);
    column(x, gz0 + 0.05);
  }
  for (let i = 1; i < nSide - 1; i++) {
    const z = gz0 + 0.05 + i * ((gz1 - gz0 - 0.1) / (nSide - 1));
    column(-gx + 0.05, z);
    column(gx - 0.05, z);
  }
  const fy = base + storey + 0.02;
  k.box(0, fy, zc, 2 * gx, 0.05, gz1 - gz0, hex(0xe8e4da));
  k.box(0, fy + 0.26, gz1 - 0.05, 2 * gx - 0.1, 0.025, 0.03, MANOR);
  for (let i = 0; i < 44; i++) k.box(-gx + 0.12 + i * ((2 * gx - 0.24) / 43), fy + 0.05, gz1 - 0.05, 0.015, 0.21, 0.015, MANOR);
  for (const sx of [-1, 1]) k.box(sx * (gx - 0.05), fy + 0.26, zc, 0.03, 0.025, gz1 - gz0 - 0.1, MANOR);
  // the entablature and a hipped slate roof with dormers and two chimneys
  const ey = base + colH;
  k.box(0, ey, zc, 2 * gx + 0.12, 0.14, gz1 - gz0 + 0.12, MANOR);
  const ry = ey + 0.14, rh = 1.3, rw = 2 * gx + 0.5, rd = gz1 - gz0 + 0.5;
  eastRoof(k, 0, ry, zc, rw, rd, rh, SLATE, 0.02, scale(SLATE, 0.8));
  for (const sx of [-1, 1]) {
    k.box(sx * 1.4, ry + 0.6, zc, 0.2, 1.05, 0.3, BRICK);
    k.box(sx * 1.4, ry + 1.65, zc, 0.24, 0.05, 0.34, scale(BRICK, 0.8));
  }
  for (const [x, face] of [[-1.6, 1], [0, 1], [1.6, 1], [-1.0, 3], [1.0, 3]] as const) {
    const s = face === 1 ? 1 : -1, dz = zc + s * 1.55;
    k.box(x, ry + 0.2, dz, 0.4, 0.34, 0.55, MANOR);
    k.gable(x, ry + 0.54, dz, 0.48, 0.2, 0.62, SLATE, MANOR, true);
    k.pane(x, ry + 0.26, dz + s * 0.275, 0.18, 0.22, face, hex(0x4a5a66), lit(n++), WARM_GLOW);
  }
  // wide front steps and the back steps down to the lawn
  for (let i = 0; i < 3; i++) k.box(0, 0, gz1 + 0.12 + (2 - i) * 0.12, 1.8 - i * 0.12, 0.06 + i * 0.06, 0.14, hex(0xe8e2d4));
  for (let i = 0; i < 3; i++) k.box(0, 0, gz0 - 0.12 - (2 - i) * 0.12, 1.0 - i * 0.1, 0.06 + i * 0.06, 0.14, hex(0xe8e2d4));
  // the two garçonnières at the back corners
  for (const sx of [-1, 1]) {
    const x = sx * 4.7, z = -5.4;
    k.box(x, 0, z, 1.1, 0.7, 1.1, MANOR);
    for (let f = 0; f < 4; f++) {
      const [px, pz] = f === 0 ? [0.55, 0] : f === 1 ? [0, 0.55] : f === 2 ? [-0.55, 0] : [0, -0.55];
      k.pane(x + px, 0.2, z + pz, 0.16, 0.3, f, hex(0x4a5a66), lit(n++), WARM_GLOW);
    }
    eastRoof(k, x, 0.7, z, 1.4, 1.4, 0.6, SLATE, 0.02);
  }
  // the avenue: a gravel drive under two rows of live oaks, lanterns between them
  const az0 = gz1 + 0.5, az1 = D / 2;
  k.box(0, 0, (az0 + az1) / 2, 1.3, 0.01, az1 - az0, GRAVEL);
  for (let i = 0; i < 6; i++) {
    const z = 0.1 + i * 1.45;
    for (const sx of [-1, 1]) liveOak(k, sx * 2.05, z, 1.35 + ((i + (sx > 0 ? 1 : 0)) % 3) * 0.1, b.seed + i * 2 + (sx > 0 ? 1 : 0));
    if (i % 2 === 0) for (const sx of [-1, 1]) {
      k.box(sx * 0.8, 0, z + 0.7, 0.03, 0.3, 0.03, DARK);
      k.glowBox(sx * 0.8, 0.3, z + 0.7, 0.06, 0.07, 0.06, hex(0xe8e0c0), PORCH, WARM_GLOW);
    }
  }
  // formal parterres either side: a hedge frame, cross paths, flower beds, topiary cones and an urn
  for (const sx of [-1, 1]) {
    const px = sx * 4.6, pz = 2.4, pw = 2.4, pd = 4.6;
    k.box(px, 0, pz, pw, 0.006, pd, GRAVEL);
    for (const [x, z, w, d] of [[0, -pd / 2, pw, 0.12], [0, pd / 2, pw, 0.12], [-pw / 2, 0, 0.12, pd], [pw / 2, 0, 0.12, pd]]) k.box(px + x, 0, pz + z, w, 0.12, d, HEDGE);
    const beds = [0xe88aa8, 0xd8453a, 0xf2e8c8, 0xe88aa8];
    let q = 0;
    for (const bx of [-1, 1]) for (const bz of [-1, 1]) {
      const cx = px + bx * pw * 0.24, cz = pz + bz * pd * 0.25;
      k.box(cx, 0, cz, pw * 0.36, 0.08, pd * 0.38, HEDGE, mix(HEDGE, hex(beds[q++]), 0.6));
      k.cone(px + bx * (pw / 2 - 0.12), 0.12, pz + bz * (pd / 2 - 0.12), 0.12, 0.4, HEDGE, 6);
    }
    k.cyl(px, 0, pz, 0.14, 0.1, hex(0xe8e2d4), 8);
    k.cyl(px, 0.1, pz, 0.05, 0.12, hex(0xe8e2d4), 6);
    k.cyl(px, 0.22, pz, 0.12, 0.06, hex(0xe8e2d4), 8, hex(0x6fa8c0));
  }
  // the lawn path down to the bayou landing at the back: water, a jetty on piles, a pirogue
  const lz = -D / 2;
  k.box(0, 0, (gz0 - 0.5 + lz + 1.1) / 2, 0.8, 0.01, gz0 - 0.5 - lz - 1.1, GRAVEL);
  k.box(0, 0, lz + 0.55, 11.6, 0.012, 1.1, BAYOU);
  k.box(0, 0, lz + 1.12, 11.6, 0.03, 0.08, hex(0x6b6a4a));
  k.box(0, 0.05, lz + 0.8, 0.7, 0.04, 1.3, PLANK);
  for (const sx of [-1, 1]) for (const z of [lz + 0.3, lz + 1.0]) k.box(sx * 0.32, -0.2, z, 0.05, 0.3, 0.05, PILE);
  k.box(0.75, 0.005, lz + 0.6, 0.22, 0.04, 0.9, hex(0x5a4a3a), hex(0x7a6a4a));
  for (const sx of [-1, 1]) {
    k.box(sx * 0.32, 0.09, lz + 1.3, 0.04, 0.3, 0.04, DARK);
    k.glowBox(sx * 0.32, 0.39, lz + 1.3, 0.06, 0.06, 0.06, hex(0xe8e0c0), PORCH, WARM_GLOW);
  }
  liveOak(k, -4.6, lz + 2.0, 1.2, b.seed + 40);
  liveOak(k, 4.4, lz + 2.3, 1.1, b.seed + 41);
};

