/**
 * Shared fleets (docs/sharedfleets.html): several players running one fleet. Imported by the game and the
 * server; nothing here touches the DOM or Node.
 *
 * The server keeps one record per shared fleet (a "crew" on the wire, so it is never confused with the
 * game's own Fleet class): who made it, who is in it, its livery, its purse, every vehicle with the member
 * whose game is driving it, the drivers, the HQ and its terms, and the buildings it owns. Diamonds, the tech
 * trees, the Passport and achievements stay each player's own, in their own career.
 */

import type { Brand, Pid } from './protocol';
import type { CrewPolicy } from './social';

/** The most players one shared fleet may have, its maker included. */
export const CREW_MAX = 8;

/** Invite codes: eight letters and digits nobody misreads (no 0/O, 1/I/L). */
export const INVITE_ALPHABET = '23456789ABCDEFGHJKMNPQRSTUVWXYZ';
export const INVITE_LEN = 8;
const CODE = new RegExp(`^[${INVITE_ALPHABET}]{${INVITE_LEN}}$`);
export const isInviteCode = (s: unknown): s is string => typeof s === 'string' && CODE.test(s);

/**
 * An invite code from whatever was pasted: the code itself (any case, spaces or dashes anywhere), or a link
 * with /join/<code> or ?join=<code> in it. Null when there is none in it.
 */
export function inviteFrom(text: string): string | null {
  const t = String(text ?? '').trim();
  const m = /(?:\/join\/|[?&]join=)([A-Za-z0-9-]+)/.exec(t);
  const raw = (m ? m[1] : t).toUpperCase().replace(/[\s-]/g, '');
  return isInviteCode(raw) ? raw : null;
}

/** The model a player starts with when they leave a shared fleet with no vehicle of their own to drive. */
export const STARTER_MODEL = 'tomato';

/**
 * Vehicle ids are unique across a shared fleet because each member numbers the vehicles (and drivers) they
 * make from a range of their own: the maker keeps the low numbers it always had, every other member counts
 * from its player number × ID_BLOCK.
 */
export const ID_BLOCK = 100000;
export const idRange = (pid: Pid, creator: boolean): [number, number] => {
  if (creator) return [1, ID_BLOCK];
  const n = Math.max(1, Number(pid.slice(2)) || 1);
  return [n * ID_BLOCK, (n + 1) * ID_BLOCK];
};

/** A vehicle as the game saves it (game/fleet.ts SavedUnit), as far as the server needs to read it. */
export interface WireUnit { uid: number; model: string; name: string; where: string; driver: number; cell: [number, number]; x: number; z: number; [k: string]: unknown }
/** A driver as the game saves it (game/drivers.ts Driver), as far as the server needs to read it. */
export interface WireDriver { id: number; unit: number; name: string; [k: string]: unknown }

/**
 * One shared vehicle: as saved, and the member whose game runs it (`by`). Null `by`: nobody's just now, either
 * in the garage (anyone may bring it out) or left on the map by a member who signed out with nobody else on
 * (the next member in picks it up).
 */
export interface CrewUnit { u: WireUnit; by: Pid | null }

/** What of the fleet's game state is shared beyond its vehicles: the HQ, its charter credit, today's hires, dealer purchases. */
export interface CrewMeta { hq?: unknown; charter?: number; hires?: { day: number; taken: number[] }; bought?: number }

export interface CrewMember { id: Pid; name: string; online: boolean; seen: number }

/** A shared fleet as one of its members is told it. */
export interface CrewView {
  id: string;
  /** Who made it: the only one who may rename it, recolour it or boot anyone. */
  creator: Pid;
  brand: Brand | null;
  members: CrewMember[];
  /** The shared purse. */
  cash: number;
  units: CrewUnit[];
  drivers: WireDriver[];
  /** The buildings it owns, as the game saves them (game/estate.ts SavedDeed), by lot key. */
  estate: Record<string, unknown>;
  meta: CrewMeta;
  /** Its invite code (the fleet's, any member may hand it out). */
  code: string;
  /** Its officers (docs/social.html phase 3), how it is joined and who may invite, and each member's takings into the purse this week. */
  officers?: Pid[];
  policy?: CrewPolicy;
  week?: Record<Pid, number>;
}

/** Changes to a shared fleet's roster: from a member's game to the server, and from the server to the others. */
export interface RosterChange {
  units?: CrewUnit[];
  gone?: number[];
  drivers?: WireDriver[];
  fired?: number[];
  estate?: Record<string, unknown>;
  sold?: string[];
  meta?: CrewMeta;
}

/** The fields of a career that belong to a shared fleet while its player is in one: set aside on joining, back on leaving. */
export const CREW_SAVE_FIELDS = ['cash', 'fleet', 'estate', 'brand', 'owned', 'ride'] as const;
