import { hex, scale, type RGB } from '../../world/biomes';
import type { FaithKind } from '../../world/tiles';
import { Vis } from '../nightLights';
import { STONE, TAU, WARM_GLOW, WATER, WHITE, WOOD, pick, row, type Draw, type Kit, type P3 } from './kit';

/**
 * Houses of worship beyond the parish church: a synagogue, an Orthodox church under onion domes, a
 * Norse stave church in tarred timber, a Buddhist stupa, and the golden gurdwara that stands in its
 * pool as an island's wonder.
 */

const GOLD = hex(0xd9a441), BRASS = hex(0xc08b2e);
const SKY_BLUE = hex(0x3f7fb5);

/**
 * An onion dome: a profile of radii swept up from the drum to the point, drawn as a ring of quads so
 * it keeps the low-poly look the rest of the town has.
 */
export function onion(k: Kit, x: number, y: number, z: number, r: number, h: number, col: RGB, seg = 10): void {
  // wide at the shoulder, pinched at the neck, out again and up to a point
  const prof: [number, number][] = [[0, 0.62], [0.16, 0.95], [0.36, 1], [0.58, 0.82], [0.76, 0.5], [0.9, 0.22], [1, 0]];
  const I: P3 = [x, y + h * 0.45, z];
  for (let i = 0; i < prof.length - 1; i++) {
    const [t0, s0] = prof[i], [t1, s1] = prof[i + 1];
    for (let a = 0; a < seg; a++) {
      const a0 = (a / seg) * TAU, a1 = ((a + 1) / seg) * TAU;
      const r0 = r * s0, r1 = r * s1, y0 = y + h * t0, y1 = y + h * t1;
      k.quad(
        [x + Math.cos(a0) * r0, y0, z + Math.sin(a0) * r0],
        [x + Math.cos(a1) * r0, y0, z + Math.sin(a1) * r0],
        [x + Math.cos(a1) * r1, y1, z + Math.sin(a1) * r1],
        [x + Math.cos(a0) * r1, y1, z + Math.sin(a0) * r1],
        col, I,
      );
    }
  }
}

/** A cross on a spike: the Orthodox one has a slanted foot bar. */
function cross(k: Kit, x: number, y: number, z: number, h: number, col: RGB, slanted = false): void {
  k.box(x, y, z, 0.022, h, 0.022, col);
  k.box(x, y + h * 0.72, z, 0.16, 0.022, 0.024, col);
  if (!slanted) return;
  k.box(x, y + h * 0.86, z, 0.1, 0.02, 0.022, col);
  k.bar([x - 0.07, y + h * 0.5, z], [x + 0.07, y + h * 0.58, z], 0.011, col);
}

/** A six-pointed star, flat on a wall facing +z (or -z): two triangles laid over each other. */
function star(k: Kit, x: number, y: number, z: number, r: number, col: RGB, sign: 1 | -1 = 1): void {
  const I: P3 = [x, y, z - sign * 0.1];
  for (const turn of [0, TAU / 6]) {
    for (let i = 0; i < 3; i++) {
      const a = turn + (i / 3) * TAU;
      const b = turn + ((i + 1) / 3) * TAU;
      k.tri([x + Math.cos(a) * r, y + Math.sin(a) * r, z], [x + Math.cos(b) * r, y + Math.sin(b) * r, z], [x, y, z], col, I);
    }
  }
}

// ---- synagogue ---------------------------------------------------------------------------------

/**
 * A city synagogue: a stone hall under a low dome, a round-arched front between two stair towers,
 * a rose window with the star of David over the doors, and the lamp above them lit after dark.
 */
const synagogue: Draw = (k, W, D, b, r) => {
  const stone = pick(r, STONE), trim = scale(stone, 0.88), dome = hex(0x4e7f8c);
  const bw = Math.min(W - 0.3, 2.6), bd = D - 0.4;
  const h = 0.62;
  k.box(0, 0, 0, bw, h, bd, stone, trim);
  // the front: a taller gabled bay between two little towers
  const fz = bd / 2 - 0.06;
  k.box(0, 0, fz, bw * 0.62, h + 0.22, 0.24, scale(stone, 1.03), trim);
  for (const sx of [-1, 1]) {
    const tx = sx * (bw / 2 - 0.13);
    k.box(tx, 0, fz, 0.26, h + 0.34, 0.26, stone, trim);
    k.box(tx, h + 0.34, fz, 0.3, 0.05, 0.3, trim);
    k.dome(tx, h + 0.39, fz, 0.13, dome, 8, 3);
  }
  // the dome over the hall
  k.cyl(0, h, -bd * 0.06, Math.min(0.42, bw * 0.24), 0.16, scale(stone, 1.02), 12);
  k.dome(0, h + 0.16, -bd * 0.06, Math.min(0.42, bw * 0.24), dome, 12, 4);
  k.cone(0, h + 0.16 + Math.min(0.42, bw * 0.24) * 0.9, -bd * 0.06, 0.03, 0.12, GOLD, 6);
  // arched windows down both flanks, the rose window and the doors
  for (const sx of [-1, 1]) row(k, b, r, sx * (bw / 2), 0.2, 0, bd - 0.5, 0.28, 4, sx > 0 ? 0 : 2, hex(0x8ba9c4));
  star(k, 0, h + 0.02, fz + 0.13, 0.13, SKY_BLUE);
  k.box(0, 0, fz + 0.12, 0.34, 0.3, 0.03, hex(0x6b4a2f));
  k.tagged(Vis.Always, () => k.glowBox(0, 0.34, fz + 0.14, 0.07, 0.07, 0.06, GOLD, [17, 23.5, 2.2], WARM_GLOW));
  // a few steps up to the doors
  for (let i = 0; i < 3; i++) k.box(0, i * 0.03, fz + 0.16 + i * 0.05, 0.5 - i * 0.06, 0.03, 0.1, trim);
};

// ---- Orthodox church ---------------------------------------------------------------------------

/**
 * Five onion domes on drums over a white masonry cross-plan church, the big one gilded and the four
 * corner ones blue, with a belfry at the west end.
 */
const orthodoxChurch: Draw = (k, W, D, b, r) => {
  const wall = pick(r, [0xf4f0e6, 0xf2e3c8, 0xe8dfd0]) as unknown as number;
  const body = hex(wall), trim = WHITE, drum = scale(body, 0.97);
  const bw = Math.min(W - 0.3, 2.2), bd = D - 0.35;
  k.box(0, 0, 0, bw, 0.6, bd, body, trim);
  // the transept arms, so it reads as a cross from above
  k.box(0, 0, 0, bw + 0.5, 0.52, bd * 0.36, body, trim);
  // apse at the back
  k.cyl(0, 0, -bd / 2, 0.3, 0.5, body, 8);
  k.dome(0, 0.5, -bd / 2, 0.3, hex(0x6fa89a), 8, 3);
  // the central drum and its gilded onion
  const cy = 0.6;
  k.cyl(0, cy, 0, 0.3, 0.34, drum, 12, trim);
  for (let i = 0; i < 6; i++) {
    const a = (i / 6) * TAU;
    k.glowBox(Math.cos(a) * 0.3, cy + 0.1, Math.sin(a) * 0.3, 0.07, 0.16, 0.07, hex(0x8ba9c4), [17, 23, 2], WARM_GLOW);
  }
  onion(k, 0, cy + 0.34, 0, 0.3, 0.44, GOLD, 12);
  cross(k, 0, cy + 0.78, 0, 0.2, GOLD, true);
  // four smaller domes at the corners
  for (const sx of [-1, 1]) for (const sz of [-1, 1]) {
    const x = sx * (bw / 2 - 0.22), z = sz * (bd / 2 - 0.3);
    k.cyl(x, 0.6, z, 0.11, 0.18, drum, 8);
    onion(k, x, 0.78, z, 0.11, 0.2, SKY_BLUE, 8);
    cross(k, x, 0.98, z, 0.1, GOLD, true);
  }
  // the belfry over the front doors
  const fz = bd / 2 - 0.1;
  k.box(0, 0, fz, 0.6, 0.92, 0.3, body, trim);
  k.cyl(0, 0.92, fz, 0.17, 0.16, drum, 8);
  onion(k, 0, 1.08, fz, 0.17, 0.26, GOLD, 8);
  cross(k, 0, 1.34, fz, 0.13, GOLD, true);
  k.glowBox(0, 0.62, fz + 0.16, 0.18, 0.2, 0.02, hex(0xf2c14e), [16.5, 23, 2.4], WARM_GLOW);
  k.box(0, 0, fz + 0.15, 0.3, 0.32, 0.03, hex(0x7a5230));
  for (const sx of [-1, 1]) row(k, b, r, sx * (bw / 2), 0.16, 0, bd - 0.7, 0.26, 3, sx > 0 ? 0 : 2, hex(0x8ba9c4));
};

// ---- stave church ------------------------------------------------------------------------------

/**
 * A Norse stave church: tarred pine shingles in stacked tiers, each with its own gables, an open
 * gallery round the sill and dragon heads on the ridge ends.
 */
const staveChurch: Draw = (k, W, D, _b, r) => {
  const tar = hex(0x35302c), shingle = hex(0x413a33), post = hex(0x4a4038);
  const base = Math.min(W - 0.5, D - 0.5, 1.5);
  // the gallery: a low deck on posts, with a lean-to roof over it
  const gw = base + 0.7;
  k.box(0, 0, 0, gw, 0.08, gw, WOOD);
  for (const sx of [-1, 1]) for (const sz of [-1, 1]) k.box(sx * (gw / 2 - 0.06), 0.08, sz * (gw / 2 - 0.06), 0.05, 0.26, 0.05, post);
  k.hip(0, 0.34, 0, gw + 0.12, 0.14, gw + 0.12, shingle);
  // three tiers, each a little smaller, each with a shingled hip and a gabled dormer facing front
  let y = 0.34, s = base;
  for (let i = 0; i < 3; i++) {
    k.box(0, y, 0, s, 0.26, s, tar);
    // the upright staves show as ribs
    for (const sx of [-1, 1]) for (let j = -1; j <= 1; j++) k.box(sx * (s / 2), y, j * (s / 3), 0.02, 0.26, 0.05, post);
    k.hip(0, y + 0.26, 0, s + 0.22, 0.2, s + 0.22, shingle);
    // dragon heads on the four eave corners, leaning out
    for (const sx of [-1, 1]) for (const sz of [-1, 1]) {
      const hx = sx * (s / 2 + 0.11), hz = sz * (s / 2 + 0.11);
      k.bar([hx, y + 0.3, hz], [hx + sx * 0.12, y + 0.44, hz + sz * 0.12], 0.015, post);
      k.box(hx + sx * 0.13, y + 0.44, hz + sz * 0.13, 0.05, 0.05, 0.05, post);
    }
    y += 0.4;
    s *= 0.72;
  }
  // the little tower and its spire
  k.box(0, y, 0, s, 0.22, s, tar);
  k.cone(0, y + 0.22, 0, s * 0.8, 0.42, shingle, 4);
  cross(k, 0, y + 0.62, 0, 0.16, hex(0x6b5a42));
  // the porch and a couple of small openings
  k.box(0, 0.08, base / 2 + 0.3, 0.32, 0.3, 0.2, tar);
  k.gable(0, 0.38, base / 2 + 0.3, 0.38, 0.14, 0.26, shingle, tar);
  k.box(0, 0.08, base / 2 + 0.4, 0.18, 0.22, 0.02, hex(0x2a241f));
  for (const sx of [-1, 1]) k.glowBox(sx * (base / 2), 0.5, 0, 0.02, 0.09, 0.07, hex(0xf2c14e), [16.5, 22.5, 1.6], WARM_GLOW);
  void r;
};

// ---- stupa -------------------------------------------------------------------------------------

/**
 * A whitewashed Buddhist stupa: a stepped plinth, the dome, the harmika box with eyes painted on it,
 * thirteen tapering rings up to a gilded parasol, and prayer flags out to a corner post.
 */
const stupa: Draw = (k, W, D, _b, r) => {
  const white = WHITE, band = hex(0xd8cfb8);
  const R = Math.min(W, D) / 2 - 0.25;
  // the plinth, in three shrinking steps
  for (let i = 0; i < 3; i++) k.box(0, i * 0.09, 0, (R + 0.34 - i * 0.1) * 2, 0.09, (R + 0.34 - i * 0.1) * 2, i === 1 ? band : white);
  const y0 = 0.27;
  k.dome(0, y0, 0, R, white, 14, 5);
  // the harmika, with the painted eyes looking out the front
  const hy = y0 + R * 0.78;
  k.box(0, hy, 0, R * 0.62, R * 0.5, R * 0.62, white, GOLD);
  const fz = R * 0.31 + 0.004;
  for (const sx of [-1, 1]) {
    k.box(sx * R * 0.13, hy + R * 0.26, fz, R * 0.16, R * 0.08, 0.008, hex(0x2b2f36));
    k.box(sx * R * 0.13, hy + R * 0.2, fz, R * 0.1, R * 0.05, 0.008, SKY_BLUE);
  }
  k.box(0, hy + R * 0.1, fz, R * 0.08, R * 0.1, 0.008, hex(0xd9a441));
  // the rings, then the parasol and the finial
  let y = hy + R * 0.5, rr = R * 0.34;
  for (let i = 0; i < 9; i++) {
    k.cyl(0, y, 0, rr, 0.035, GOLD, 8);
    y += 0.038;
    rr *= 0.93;
  }
  k.cone(0, y, 0, R * 0.36, 0.1, BRASS, 10);
  k.cyl(0, y + 0.1, 0, 0.02, 0.1, GOLD, 6);
  k.dome(0, y + 0.2, 0, 0.05, GOLD, 8, 2);
  // prayer flags from the finial down to a post at the corner of the plinth
  const px = -(R + 0.3), pz = R + 0.3;
  k.box(px, 0, pz, 0.04, 0.5, 0.04, hex(0x8d6d48));
  const flags = [0xe2412f, 0x3f9b4a, 0xf2c14e, 0x3f7fb5, 0xf4f2ec];
  for (let i = 0; i < 10; i++) {
    const t = 0.1 + i * 0.085;
    const fx = px * t, fy = (y + 0.2) * (1 - t) + 0.5 * t, fzz = pz * t;
    k.box(fx, fy - 0.05, fzz, 0.05, 0.06, 0.008, hex(flags[i % flags.length]));
  }
  void r;
};

// ---- the gurdwara: an island's golden temple ----------------------------------------------------

/**
 * A gurdwara as a wonder: a gilded sanctum on a marble plinth in the middle of its own square pool,
 * a causeway out to it from a gateway, and a marble arcade round the water. Stands on a big flat lot;
 * the mesher draws the pool as water on the lot itself.
 */
const goldenTemple: Draw = (k, W, D, _b, r) => {
  const marble = WHITE, trim = hex(0xe3dccb);
  // the walled compound: a marble arcade round the edge with a gap for the gate at the front
  const hw = W / 2 - 0.4, hd = D / 2 - 0.4;
  for (const sz of [-1, 1]) {
    const z = sz * hd;
    const gap = sz > 0 ? 1.1 : 0;
    for (const sx of [-1, 1]) {
      const len = hw - gap / 2;
      if (len <= 0.2) continue;
      const cx = sx * (gap / 2 + len / 2);
      k.box(cx, 0, z, len * 2 * 0.5, 0.42, 0.34, marble, trim);
      const n = Math.max(2, Math.round(len / 0.45));
      for (let i = 0; i <= n; i++) k.box(cx - len / 2 + (len * i) / n, 0, z + sz * 0.2, 0.06, 0.36, 0.06, trim);
    }
  }
  for (const sx of [-1, 1]) {
    k.box(sx * hw, 0, 0, 0.34, 0.42, hd * 2, marble, trim);
    const n = Math.max(3, Math.round(hd / 0.4));
    for (let i = 0; i <= n; i++) k.box(sx * (hw - 0.2), 0, -hd + (hd * 2 * i) / n, 0.06, 0.36, 0.06, trim);
  }
  // the pool
  k.disc(0, 0.02, 0, 0, WATER, 4);
  k.box(0, 0, 0, hw * 2 - 0.5, 0.05, hd * 2 - 0.5, WATER, WATER);
  // the gateway at the front, with its clock tower
  const gz = hd - 0.1;
  k.box(0, 0, gz, 1.1, 0.75, 0.5, marble, trim);
  k.box(0, 0, gz + 0.1, 0.34, 0.5, 0.34, hex(0x6b4a2f));
  k.box(0, 0.75, gz, 0.5, 0.45, 0.5, marble, trim);
  k.dome(0, 1.2, gz, 0.25, GOLD, 10, 3);
  k.cone(0, 1.42, gz, 0.04, 0.16, GOLD, 6);
  // the causeway out over the water
  k.box(0, 0.05, (gz - 0.3) / 2, 0.42, 0.05, gz - 0.3, marble);
  for (let i = 0; i < 6; i++) {
    const z = 0.3 + i * ((gz - 0.6) / 5);
    for (const sx of [-1, 1]) k.glowBox(sx * 0.23, 0.1, z, 0.05, 0.22, 0.05, GOLD, [17, 24, 2.6], WARM_GLOW);
  }
  // the sanctum: two gilded storeys on a marble plinth, under a dome, with kiosks at its corners
  k.box(0, 0, 0, 1.5, 0.12, 1.5, marble, trim);
  k.box(0, 0.12, 0, 1.15, 0.42, 1.15, GOLD, BRASS);
  for (const sx of [-1, 1]) for (const sz of [-1, 1]) {
    k.box(sx * 0.5, 0.54, sz * 0.5, 0.2, 0.2, 0.2, GOLD, BRASS);
    k.dome(sx * 0.5, 0.74, sz * 0.5, 0.1, GOLD, 8, 3);
  }
  k.box(0, 0.54, 0, 0.8, 0.34, 0.8, GOLD, BRASS);
  k.box(0, 0.88, 0, 0.9, 0.05, 0.9, BRASS);
  k.dome(0, 0.93, 0, 0.36, GOLD, 12, 4);
  k.cone(0, 1.25, 0, 0.05, 0.2, GOLD, 8);
  // the doorway on each side, and the warm light inside after dark
  for (let f = 0; f < 4; f++) {
    const a = (f / 4) * TAU;
    k.glowBox(Math.sin(a) * 0.58, 0.16, Math.cos(a) * 0.58, 0.22, 0.28, 0.02, hex(0xf2c14e), [16, 24, 3], WARM_GLOW);
  }
  void r;
};

export const FAITH_DRAW: Record<FaithKind, Draw> = { synagogue, orthodoxChurch, staveChurch, stupa, goldenTemple };
