/**
 * The offer card (docs/missions.html, The offer card): the prize turning on its plinth, a title, one
 * line of why, a few short objectives, the reward, and two buttons. The same card, in its other mode,
 * says what a finished mission gave. It opens only when the player has stopped by whoever is asking, or
 * picks an offer in the journal; the game waits while it is up.
 */
import { hero } from '../../render/heroStage';
import { KIND_LABEL, THREAD_COLOUR, THREAD_LABEL, type Mission, type Obj } from './model';
import { dayClock, detailsOf, LONG_TPLS, offerLabel, requiredOf, rewardChip, tiles } from './text';
import { isIntro } from './missions';
import { money } from '../cargoHud';

const hex = (n: number) => `#${n.toString(16).padStart(6, '0')}`;
export const esc = (s: string) => s.replace(/[<&>"]/g, (c) => ({ '<': '&lt;', '&': '&amp;', '>': '&gt;', '"': '&quot;' }[c]!));

/** One objective's line: icon, words, and how far (tiles) or how many. */
export function objLine(o: Obj, far: number | null, state: 'done' | 'now' | 'todo' | 'plain' = 'plain', count?: string): string {
  const d = count ?? (far !== null && Number.isFinite(far) ? tiles(far) : '');
  const mark = state === 'done' ? '✓' : state === 'now' ? '▸' : state === 'todo' ? '○' : '';
  return `<li class="${state}"><i>${o.icon}</i><span>${esc(o.label)}</span><em>${esc(d)}</em>${mark ? `<b>${mark}</b>` : ''}</li>`;
}

export function rewardChips(m: Mission): string {
  // someone staying on (`crew`) is the done card's news, never the offer's; a pair of loads shows what each pays
  const chips = m.reward.filter((r) => r.r !== 'crew').map((r) => { const c = rewardChip(r); return `<span class="${c.big ? 'big' : ''}">${c.icon} ${esc(c.text)}</span>`; });
  for (const o of m.objs) {
    if (o.t === 'deliver' && o.also) chips.unshift(`<span class="big">💵 ${esc(money(o.value))} · your load</span>`, `<span>💵 ${esc(money(o.also.value))} · ${Math.round((o.also.value / Math.max(1, o.value)) * 10) * 10}% of hers</span>`);
  }
  return chips.join('');
}

/** What the done card's button says: the helping hand is welcomed aboard, anything else is just nice. */
const DONE_LABEL: Record<string, string> = { 'first:hand': 'Welcome aboard' };

export function threadChip(m: Mission): string {
  return `<span class="th" style="--c:${hex(THREAD_COLOUR[m.thread])}">${THREAD_LABEL[m.thread]}</span>`;
}

interface CardHost {
  /** Tiles from the player to where each objective happens, null when it has no place. */
  far(m: Mission, o: Obj): number | null;
  whyNot(m: Mission): string | null;
  accept(m: Mission): void;
  reject(m: Mission): void;
  /** Open the journal on this mission. */
  journal(m: Mission): void;
  closed(): void;
  /** Skip the whole tutorial (Missions.skipTutorial): offered on its locked cards, after a confirm. */
  skip?(): void;
}

export class MissionCard {
  isOpen = false;
  private el = document.createElement('div');
  private m: Mission | null = null;
  private mode: 'offer' | 'done' = 'offer';
  /** Cards waiting behind the one showing: completions queue, an offer never waits behind another. */
  private queue: { m: Mission; mode: 'offer' | 'done'; gave?: string[] }[] = [];

  constructor(private host: CardHost) {
    this.el.id = 'mission';
    this.el.hidden = true;
    document.body.append(this.el);
    this.el.addEventListener('mousedown', (e) => { if (e.target === this.el && !this.locked) this.close(); });
    this.el.addEventListener('click', (e) => {
      const b = (e.target as HTMLElement).closest<HTMLElement>('[data-act]');
      if (!b || !this.m) return;
      const act = b.dataset.act;
      if (act === 'yes') this.yes();
      else if (act === 'no') this.no();
      else if (act === 'journal') { const m = this.m; this.close(); this.host.journal(m); }
      else if (act === 'ok') this.close();
      else if (act === 'more') this.el.querySelector('.mc-body')?.classList.toggle('more');
      else if (act === 'skip') {
        const acts = this.el.querySelector('.mc-acts');
        if (acts) acts.innerHTML = '<p class="mc-no">Skip the whole tutorial? Its missions end here, and other missions open up.</p><button type="button" class="no" data-act="skipYes">Yes, skip it</button><button type="button" class="yes" data-act="skipNo">Keep going</button>';
      } else if (act === 'skipNo') this.render();
      else if (act === 'skipYes') { this.close(); this.host.skip?.(); }
    });
    window.addEventListener('keydown', (e) => {
      if (!this.isOpen) return;
      if (e.code === 'Enter' || e.code === 'NumpadEnter') { this.mode === 'offer' ? this.yes() : this.close(); e.preventDefault(); e.stopPropagation(); }
      else if (e.code === 'Backspace' || e.code === 'Delete') { if (this.mode === 'offer' && !this.locked) this.no(); e.preventDefault(); e.stopPropagation(); }
      else if (e.code === 'Escape' || e.code === 'Space') { if (!this.locked) this.close(); e.preventDefault(); e.stopPropagation(); }
    }, true);
  }

  /** One of the first drive's offers: Accept is the only way on. */
  private get locked(): boolean { return this.mode === 'offer' && !!this.m && isIntro(this.m.tpl); }

  offer(m: Mission): void {
    if (this.isOpen) { if (this.mode === 'done') this.queue.push({ m, mode: 'offer' }); return; }
    this.m = m;
    this.mode = 'offer';
    this.render();
  }

  done(m: Mission, gave: string[]): void {
    if (this.isOpen) { this.queue.push({ m, mode: 'done', gave }); return; }
    this.m = m;
    this.mode = 'done';
    this.render(gave);
  }

  private yes(): void {
    const m = this.m;
    if (!m || this.host.whyNot(m)) return;
    this.close();
    this.host.accept(m);
  }

  private no(): void {
    const m = this.m;
    if (!m || this.locked) return;
    this.close();
    this.host.reject(m);
  }

  close(): void {
    if (!this.isOpen) return;
    this.isOpen = false;
    this.el.hidden = true;
    this.m = null;
    this.host.closed();
    const next = this.queue.shift();
    if (next) setTimeout(() => (next.mode === 'offer' ? this.offer(next.m) : this.done(next.m, next.gave ?? [])), 250);
  }

  private render(gave?: string[]): void {
    const m = this.m!;
    const tint = hex(THREAD_COLOUR[m.thread]);
    const where = m.giver.town ? m.giver.town.name : m.giver.name;
    const bar = this.mode === 'offer' ? `<div class="mc-bar">${esc(offerLabel(m))}</div>` : `<div class="mc-bar done">Mission complete</div>`;
    const top = `<div class="mc-top">${threadChip(m)}${m.also ? `<span class="th soft" style="--c:${hex(THREAD_COLOUR[m.also])}">${THREAD_LABEL[m.also]}</span>` : ''}<span class="mc-where">${KIND_LABEL[m.kind]} · ${esc(where)}</span></div>`;
    let body: string;
    if (this.mode === 'offer') {
      const why = this.host.whyNot(m);
      const objs = m.objs.map((o) => objLine(o, this.host.far(m, o))).join('');
      // a long story (docs/storychains.html) shows only the four dots of the act it is in, and a faint one after
      const long = !!m.arc && m.arc.of > 6, a0 = long ? Math.floor(m.arc!.i / 4) * 4 : 0;
      const ks = m.arc ? Array.from({ length: long ? 4 : m.arc.of }, (_, j) => a0 + j) : [];
      const arc = m.arc ? `<div class="mc-arc">${ks.map((k) => `<i class="${k < m.arc!.i ? 'd' : k === m.arc!.i ? 'n' : ''}"></i>`).join('')}${long && a0 + 4 < m.arc.of ? '<i class="f" style="opacity:.35;border-style:dashed"></i>' : ''}</div>` : '';
      const due = m.notes?.by !== undefined ? `<span class="mc-due">⏱ ${dayClock(m.notes.by)}</span>` : m.due !== null ? `<span class="mc-due">⏱ ${Math.round(m.due - m.posted)} h</span>` : '';
      const locked = isIntro(m.tpl);
      const need = requiredOf(m);
      const accept = why && !locked ? `<button type="button" class="yes" data-act="journal">Open the journal <kbd>J</kbd></button>` : `<button type="button" class="yes" data-act="yes">Accept <kbd>⏎</kbd></button>`;
      body = `${top}<h2>${esc(m.title)}</h2><p class="mc-why">${esc(m.why)}</p>
        <button type="button" class="mc-more-t" data-act="more"><span class="a">More details</span><span class="b">Fewer details</span> <i>▾</i></button>
        <p class="mc-more">${esc(detailsOf(m))}</p>
        ${need ? `<p class="mc-need"><b>Required:</b> ${esc(need)}</p>` : ''}
        <h4 class="mc-sub">Objectives</h4>
        <ol class="mc-objs">${objs}</ol>
        <h4 class="mc-sub">Rewards</h4>
        <div class="mc-rew">${rewardChips(m)}${due}</div>${arc}
        ${why ? `<p class="mc-no">${esc(why)}</p>` : ''}
        <div class="mc-acts">${accept}${locked ? (this.host.skip ? '<button type="button" class="no" data-act="skip">Skip the tutorial</button>' : '') : `<button type="button" class="no" data-act="no">Reject <kbd>⌫</kbd></button>`}</div>`;
    } else {
      const lines = (gave ?? []).map((g) => `<li><i>✦</i><span>${esc(g)}</span></li>`).join('');
      body = `${top}<h2>${esc(m.title)}</h2>${m.outcome ? `<p class="mc-why">${esc(m.outcome)}</p>` : ''}
        <h4 class="mc-sub">You got</h4>
        <ol class="mc-objs gave">${lines}</ol>
        <div class="mc-acts"><button type="button" class="yes" data-act="ok">${DONE_LABEL[m.tpl] ?? 'Nice'} <kbd>⏎</kbd></button></div>`;
    }
    this.el.innerHTML = `<div class="mc${LONG_TPLS.has(m.tpl) ? ' long' : ''}" style="--tint:${tint}">${bar}<div class="mc-hero"><span class="mc-cap">${esc(m.caption)}</span></div><div class="mc-body">${body}</div></div>`;
    this.el.hidden = false;
    this.isOpen = true;
    const slot = this.el.querySelector<HTMLElement>('.mc-hero')!;
    hero.mount(slot);
    hero.show(m.hero, THREAD_COLOUR[m.thread]);
  }
}
