import { DIRS, EDGE_MINE, Flag, N, STEP, World, idx, maxCorner, waterDepth, type Bridge, type GreatDesign, type Landmark, type Road } from './tiles';
import { deckTiles, dirBetween, rebuildRoadTables, shapeOf } from './roads';
import { siteOf } from './bridgeDesigns';
import { hash2 } from './rng';
import { landformName } from './landforms';
import { NEXT_090 } from './nextWorld';

/**
 * Great crossings (0.8.0, NEXT_080, docs/phonelist.html item 14): out in the country, far from any town, the county's
 * most dramatic crossing is built as a famous kind of bridge and named. A deep gorge is spanned by a steel deck arch
 * springing from its walls (New River Gorge), an open-spandrel concrete arch (Bixby Creek, by the coast) or, when it is
 * long, a high viaduct on slender piers; a wide river by a steel through-truss, its deck down at the banks.
 *
 * 0.9.0 (NEXT_090, the user, 11 Nov 2026): a great crossing is about level, never one whose deck climbs or falls more
 * than GREAT_DROP from bank to bank, and a wide river's may also be a steel tied arch (a run of them on a long river) or,
 * up to STONE_LEN with a step of air over the water, an old stone bridge of many arches on cutwaters, or, with its deck
 * down at the water, a vertical-lift bridge (render/bridges.ts tiedArch, stoneArches, liftBridge).
 *
 * Nothing is moved or rerouted: the crossing is one the county's roads already make, picked once every road is laid
 * (generate.ts, after the roads are mended), so a county that has none is exactly what it was. The bridge carries its
 * design (Bridge.great, which world/bridgeDesigns.ts designOf returns) and a 'crossing' landmark names it, so it is on
 * the map labels, announced as the car drives onto it, and a place sightseers go.
 */

/** A gorge span: at least this much air under the deck (world units) and this many tiles of deck. */
const GORGE_AIR = 3.5, GORGE_LEN = 8;
/** A river span: this many tiles of deck over water at least (0.9.0: a little less, for more great crossings). */
const RIVER_LEN = 12, RIVER_LEN_090 = 10;
/** No town's edge within this many tiles of the deck (0.9.0: a little nearer). */
const TOWN_CLEAR = 8, TOWN_CLEAR_090 = 6;
/** A gorge span this long is a viaduct; one within this many tiles of the sea a concrete arch. */
const VIADUCT_LEN = 30, COAST = 14;
/**
 * 0.9.0 (NEXT_090): a great crossing is about level, its deck climbing or falling at most this much (world units) from
 * one bank to the other (the user, 11 Nov 2026: not dramatically sloped up or down).
 */
export const GREAT_DROP = 1 * STEP;
/** 0.9.0: the longest river span an old stone bridge of many arches is built over. */
const STONE_LEN = 26;

export const GREAT_NAME: Record<GreatDesign, string> = {
  deckArch: 'Steel arch bridge', spandrelArch: 'Concrete arch bridge', highViaduct: 'Viaduct', throughTruss: 'Truss bridge',
  tiedArch: 'Tied arch bridge', stoneArches: 'Stone arch bridge', liftBridge: 'Lift bridge',
};

/** Pick and name the county's great crossing, if it has one. Returns its design, or null. */
export function markGreatCrossing(w: World, seedHash: number): GreatDesign | null {
  let best: { r: Road; br: Bridge; score: number; design: GreatDesign; mid: number; len: number; level: Levelling | null } | null = null;
  for (const r of w.roads) {
    if (r.town !== undefined && r.town >= 0) continue;
    if (r.limited) continue;
    for (const br of r.bridges ?? []) {
      if (br.tunnel || br.level || br.ramp || br.peak !== undefined || br.raised || br.from === br.to) continue;
      // 0.9.0: about level, or brought level by cutting and banking its approaches (levelPlan)
      let level: Levelling | null = null;
      if (NEXT_090 && Math.abs(br.h1 - br.h0) > GREAT_DROP + 1e-6) {
        level = levelPlan(w, r, br);
        if (!level) continue;
      }
      const site = siteOf(w, r, br);
      const a = r.nodes[br.from], b = r.nodes[br.to];
      const tiles = deckTiles(a, b, dirBetween(a, r.nodes[br.from + 1]), shapeOf(r.type));
      if (!tiles.length) continue;
      if (tiles.some(({ tile }) => nearTown(w, tile))) continue;
      let wet = 0, coast = 99;
      for (const { tile } of tiles) { if (waterDepth(w, tile) > 0) wet++; coast = Math.min(coast, w.coastDist[tile]); }
      let design: GreatDesign | null = null, score = 0;
      if (site.height >= GORGE_AIR && site.len >= GORGE_LEN && wet <= tiles.length * 0.5) {
        const roll = hash2(a, b, 7401);
        // 0.9.0: an old stone viaduct of many arches on tall piers, over a gorge up to STONE_LEN
        const stone = NEXT_090 && site.len <= STONE_LEN && hash2(a, b, 7405) < 0.3;
        design = site.len >= VIADUCT_LEN ? 'highViaduct' : stone ? 'stoneArches' : coast <= COAST || roll < 0.45 ? 'spandrelArch' : 'deckArch';
        score = 100 + site.height * 4 + site.len;
      } else if (site.len >= (NEXT_090 ? RIVER_LEN_090 : RIVER_LEN) && wet >= site.len * 0.6) {
        // 0.9.0: a tied arch or an old stone bridge as well as the truss, rolled by the crossing's ends
        const roll = NEXT_090 ? hash2(a, b, 7403) : 1;
        // (the stone bridge only with a step of air over the water, or its arches are drowned to their crowns)
        // and a lift bridge, whose span rises for the boats, where the deck is down at the water
        design = roll < 0.3 && site.len <= STONE_LEN && site.waterAir >= STEP ? 'stoneArches' : roll < 0.55 ? 'tiedArch'
          : roll < 0.78 && site.waterAir < STEP ? 'liftBridge' : 'throughTruss';
        score = site.len;
      }
      if (design && (!best || score > best.score)) best = { r, br, score, design, mid: tiles[tiles.length >> 1].tile, len: site.len, level };
    }
  }
  if (!best) return null;
  best.br.great = best.design;
  if (best.level) {
    // the cutting and the embankment, and the deck laid level between them
    for (const [i, v] of best.level.corners) w.corners[i] = v;
    best.br.h0 = best.br.h1 = best.level.h * STEP;
    rebuildRoadTables(w);
  }
  const x = (best.mid % N) + 0.5, z = Math.floor(best.mid / N) + 0.5;
  // (hashed off the deck's middle and the road's own ends, so neighbouring counties' crossings are not all one name)
  const word = landformName('crossing', seedHash ^ Math.imul(best.r.nodes[0] + 1, 2654435761), w.ox * 3 + x, w.oz * 5 + z);
  const name = best.design === 'stoneArches' ? `the Old ${word} Bridge` : best.design === 'throughTruss' || best.design === 'tiedArch' ? `the ${word} River Bridge`
    : best.design === 'liftBridge' ? `the ${word} Lift Bridge` : best.design === 'highViaduct' ? `the ${word} Viaduct` : `the ${word} Gorge Bridge`;
  const l: Landmark = { kind: 'crossing', name, x, z, r: Math.max(4, Math.ceil(best.len / 2) + 1), data: [GREAT_DESIGNS.indexOf(best.design)] };
  w.landmarks.push(l);
  return best.design;
}

/** In the order a 'crossing' landmark's data[0] counts them: new designs go on the end. */
export const GREAT_DESIGNS: GreatDesign[] = ['deckArch', 'spandrelArch', 'highViaduct', 'throughTruss', 'tiedArch', 'stoneArches', 'liftBridge'];

function nearTown(w: World, tile: number): boolean {
  const x = tile % N, z = (tile - x) / N;
  for (const t of w.towns) {
    const dx = Math.max(t.x0 - x, 0, x - (t.x0 + t.size)), dz = Math.max(t.z0 - z, 0, z - (t.z0 + t.size));
    if (Math.max(dx, dz) < (NEXT_090 ? TOWN_CLEAR_090 : TOWN_CLEAR)) return true;
  }
  return w.townId[idx(x, z)] >= 0;
}

/** The great crossing's label under its name, by its design. */
export function crossingLabel(l: Landmark): string {
  return GREAT_NAME[GREAT_DESIGNS[l.data?.[0] ?? 0] ?? 'deckArch'];
}

// ---- levelling a crossing (0.9.0) -------------------------------------------------------------------------------

/** The most road tiles cut down (or built up) on either side to bring a crossing's ends to one level. */
const LEVEL_REACH = 18;
/** The most rock blasted from under a levelled deck, in steps summed over the corners it lowers. */
const BLAST_MAX = 160;

/**
 * How a sloped crossing is brought level (0.9.0, the user, 11 Nov 2026: "manipulate the terrain a bit … like how humans
 * would use dynamite to blow through the tips of mountains to keep an interstate flatter"): the deck laid level at
 * `h` steps, the road on the high side cut down into its rim and the road on the low side built up on an embankment,
 * each ramping back to the natural ground a step a tile (a tile where the road turns stays level), and the tip of the
 * high rim blasted away where it stands in the deck's way. Only the road's own tiles and the rock under the deck move,
 * so the rock either side stands as the walls of a cutting. Corner index (tile × 4 + q) → new height.
 */
interface Levelling { h: number; corners: Map<number, number> }

/** A narrow generated road's crossing re-laid level, the cheapest way that stands, or null where none does. */
function levelPlan(w: World, r: Road, br: Bridge): Levelling | null {
  if (shapeOf(r.type)) return null;
  const n = r.nodes, d = dirBetween(n[br.from], n[br.from + 1]);
  const ea = Math.round(br.h0 / STEP), eb = Math.round(br.h1 / STEP);
  if (Math.abs(ea * STEP - br.h0) > 1e-6 || Math.abs(eb * STEP - br.h1) > 1e-6) return null;
  const tiles = deckTiles(n[br.from], n[br.to], d, false);
  let best: Levelling | null = null, bestCost = Infinity;
  for (let h = Math.min(ea, eb); h <= Math.max(ea, eb); h++) {
    // the level deck must still clear what is under it, as a bridge's would (world/roads.ts bridgeBetween); dry rock in
    // its way, the tip of the higher rim, is blasted down a step under it
    const corners = new Map<number, number>();
    let cost = 0;
    if (!tiles.every(({ tile }) => {
      const wl = w.water[tile], under = wl >= 0 ? Math.max(wl, maxCorner(w, tile)) : maxCorner(w, tile) + (w.road[tile] || w.rail[tile] ? 2 : 1);
      if (under <= h) return true;
      if (wl >= 0 || w.road[tile] || w.rail[tile] || w.blocked[tile] || (w.flags[tile] & (Flag.Poi | Flag.Corridor))) return false;
      for (let q = 0; q < 4; q++) {
        const v = w.corners[tile * 4 + q];
        if (v > h - 1) { corners.set(tile * 4 + q, h - 1); cost += v - (h - 1); }
      }
      return cost <= BLAST_MAX;
    })) continue;
    const ok = [[br.from, -1, d], [br.to, 1, (d + 2) & 3]].every(([k0, step, side]) => {
      const c = rampTo(w, r, br, k0, step, side, h, corners);
      if (c < 0) return false;
      cost += c;
      return true;
    });
    if (ok && cost < bestCost) { best = { h, corners }; bestCost = cost; }
  }
  return best;
}

/** The side of tile a that tile b is on (they are neighbours), or -1. */
function sideTo(a: number, b: number): number {
  const dx = (b % N) - (a % N), dz = Math.floor(b / N) - Math.floor(a / N);
  for (let s = 0; s < 4; s++) if (DIRS[s][0] === dx && DIRS[s][1] === dz) return s;
  return -1;
}

/** Height of tile t's edge on side s, in steps, or NaN where its two corners differ. */
function edgeOf(w: World, t: number, s: number): number {
  const [p, q] = EDGE_MINE[s];
  const a = w.corners[t * 4 + p], b = w.corners[t * 4 + q];
  return a === b ? a : NaN;
}

/**
 * Re-shape the road out from abutment node k0 (walking `step` along the nodes, the deck on the abutment's side `side`)
 * so its edge on the deck is at h and it runs back to the ground at most a step a tile. Adds the new corners to `out`
 * and returns how much ground it moved (steps summed over corners), 0 when nothing need move, or -1 where it can't.
 */
function rampTo(w: World, r: Road, br: Bridge, k0: number, step: number, side: number, h: number, out: Map<number, number>): number {
  const n = r.nodes;
  if (edgeOf(w, n[k0], side) === h) return 0;
  let moved = 0, eIn = h, inSide = side;
  const own = new Set(r.tiles);
  for (let j = 0; j <= LEVEL_REACH; j++) {
    const k = k0 + step * j, t = n[k];
    if (k < 0 || k >= n.length) return -1;
    // not into another span, and only the road's own plain tile: no junction, rail, building, water or landmark
    if (j > 0 && r.bridges?.some((o) => o !== br && k >= Math.min(o.from, o.to) && k <= Math.max(o.from, o.to))) return -1;
    if (w.rail[t] || w.blocked[t] || w.water[t] >= 0 || w.deckAxis[t] || (w.flags[t] & (Flag.Poi | Flag.Corridor))) return -1;
    const next = n[k + step];
    if (next === undefined) return -1;
    const outSide = sideTo(t, next);
    if (outSide < 0) return -1;
    const tx = t % N, tz = (t - tx) / N;
    for (let s = 0; s < 4; s++) {
      if (s === inSide || s === outSide) continue;
      const nx = tx + DIRS[s][0], nz = tz + DIRS[s][1];
      // another road meeting it here would be left on a step; the road's own next bend beside it (a switchback up the
      // canyon wall) is another stretch of it, with no way between them, and may stand above or below the cutting
      const nb = nz * N + nx;
      if (nx >= 0 && nz >= 0 && nx < N && nz < N && w.road[nb] && !own.has(nb)) return -1;
    }
    const natural = edgeOf(w, t, outSide);
    const straight = outSide === ((inSide + 2) & 3);
    // the ground met: this tile ramps (or, turning, lies level) onto it, and the road runs on as it was
    let eOut: number;
    let done = false;
    if (!Number.isNaN(natural) && (straight ? Math.abs(natural - eIn) <= 1 : natural === eIn)) { eOut = natural; done = true; }
    else if (!straight) eOut = eIn;
    else {
      // a step toward the ground: its edge here, or the middle of a sloping one
      const [p, q] = EDGE_MINE[outSide];
      const ground = Number.isNaN(natural) ? (w.corners[t * 4 + p] + w.corners[t * 4 + q]) / 2 : natural;
      eOut = eIn + Math.sign(ground - eIn);
    }
    const set = (q: number, v: number) => {
      const i = t * 4 + q;
      if (w.corners[i] !== v) { moved += Math.abs(w.corners[i] - v); out.set(i, v); }
    };
    if (straight) {
      for (const q of EDGE_MINE[inSide]) set(q, eIn);
      for (const q of EDGE_MINE[outSide]) set(q, eOut);
    } else for (let q = 0; q < 4; q++) set(q, eIn);
    if (done) return moved;
    eIn = eOut;
    inSide = (outSide + 2) & 3;
  }
  return -1;
}
