/**
 * The World tab of the social window (docs/social.html): the map's records, every one somewhere and
 * somebody's. A grouped picker on the left (This week: the picks and your postcards; Records: the
 * Explorers' range boards, the Challenges, the Rushes; Works: the most loved, busiest and newest things
 * players built, and those near you) and the picked board or list on the right, as its own module draws it
 * (net/marks.ts, net/postcards.ts, net/explorers.ts, game/challenges, game/rushes, net/community.ts).
 * Offline only the records that work offline are offered.
 */
import type { SocialTabBody } from '../game/socialWindow';
import { scopeChips, scopePress } from './boardScope';
import type { BoardRow } from '../../shared/protocol';

export type WorldPick = 'week' | 'titles' | 'explorers' | 'challenges' | 'rushes' | 'cargo' | 'culture' | 'vehicles' | 'earnings' | 'lifetime' | 'loved' | 'busy' | 'fresh' | 'near' | 'friends';
type WorksPick = 'loved' | 'busy' | 'fresh' | 'near' | 'friends';
const isWorks = (p: WorldPick): p is WorksPick => p === 'loved' || p === 'busy' || p === 'fresh' || p === 'near' || p === 'friends';
const PICK_KEY = 'tinyfleet-world-pick';

/** A board module as the old Standings tabs had them: a body, a press, shown, and every few seconds. */
export interface BoardBody {
  html(rows: () => BoardRow[], me: string | null): string;
  press(target: HTMLElement): boolean;
  opened(): void;
  tick(): void;
}

export interface WorldHost {
  online(): boolean;
  rows(): BoardRow[];
  me(): string | null;
  /** The week's picks (net/marks.ts) and your postcards (net/postcards.ts): body, press, shown. */
  picksHtml(): string;
  picksPress(t: HTMLElement): boolean;
  picksOpened(): void;
  /** The players' works lists (net/community.ts): body for the list picked, press, shown. */
  worksHtml(tab: WorksPick): string;
  worksPress(t: HTMLElement): boolean;
  worksOpened(): void;
  explorers: BoardBody | null;
  /** Phase 4 (docs/social.html): the week's titles and the lifetime board, and the cargo and culture boards. */
  titlesWeek?: BoardBody | null;
  titlesLife?: BoardBody | null;
  cargo?: BoardBody | null;
  culture?: BoardBody | null;
  /** The vehicle boards (5 Nov 2026): most loads delivered, and most earned, in each model. */
  vehicles?: BoardBody | null;
  earnings?: BoardBody | null;
  challenges: BoardBody | null;
  rushes: BoardBody | null;
  /** Your own counts for the picker's rows: works built, hearts on them. */
  myWorks(): { works: number; loved: number } | null;
}

export class WorldTab implements SocialTabBody {
  private pick: WorldPick = 'week';

  constructor(private host: WorldHost) {
    try {
      const p = localStorage.getItem(PICK_KEY) as WorldPick | null;
      if (p) this.pick = p;
    } catch { /* not remembered */ }
  }

  private picks(): { group: string; items: { id: WorldPick; label: string; sub: string }[] }[] {
    const on = this.host.online();
    const my = this.host.myWorks();
    const groups: { group: string; items: { id: WorldPick; label: string; sub: string }[] }[] = [];
    if (on) groups.push({ group: 'This week', items: [{ id: 'week', label: 'The week’s picks', sub: 'most loved, longest road, lap and drift records, best sign…' },
      ...(this.host.titlesWeek ? [{ id: 'titles' as WorldPick, label: 'Titles', sub: 'Best Host, Road Warden, Convoy Captain… held and leading' }] : [])] });
    const records: { id: WorldPick; label: string; sub: string }[] = [];
    if (this.host.explorers) records.push({ id: 'explorers', label: 'Explorers', sub: 'furthest from home, by vehicle' });
    if (this.host.challenges) records.push({ id: 'challenges', label: 'Challenges', sub: 'the chequered lines, by road, air and sea' });
    if (this.host.rushes) records.push({ id: 'rushes', label: 'Rushes', sub: 'five minutes, every load that lands before the bell' });
    if (on && this.host.cargo) records.push({ id: 'cargo', label: 'Cargo delivered', sub: 'who has delivered the most of each cargo kind' });
    if (on && this.host.culture) records.push({ id: 'culture', label: 'Culture collected', sub: 'who has brought home the most of each culture' });
    if (on && this.host.vehicles) records.push({ id: 'vehicles', label: 'Loads by vehicle', sub: 'who has delivered the most in each vehicle' });
    if (on && this.host.earnings) records.push({ id: 'earnings', label: 'Earnings by vehicle', sub: 'who has earned the most in each vehicle' });
    if (on && this.host.titlesLife) records.push({ id: 'lifetime', label: 'Lifetime titles', sub: 'every fleet’s weekly titles over all time' });
    if (records.length) groups.push({ group: 'Records', items: records });
    if (on) groups.push({ group: 'Works', items: [
      { id: 'loved', label: 'Most loved', sub: 'bridges, roads and earthworks with the most hearts' },
      { id: 'busy', label: 'Busiest', sub: 'crossed most by other fleets' },
      { id: 'fresh', label: 'Newest', sub: 'just built' },
      { id: 'near', label: 'Near me', sub: `in the counties round you${my ? ` · yours: ${my.works} built, ♥ ${my.loved}` : ''}` },
      { id: 'friends', label: 'By friends', sub: 'what the players you have added have built' },
    ] });
    return groups;
  }

  private available(): WorldPick[] { return this.picks().flatMap((g) => g.items.map((i) => i.id)); }

  private body(id: WorldPick): BoardBody | null {
    const h = this.host;
    return id === 'explorers' ? h.explorers : id === 'challenges' ? h.challenges : id === 'rushes' ? h.rushes
      : id === 'titles' ? h.titlesWeek ?? null : id === 'lifetime' ? h.titlesLife ?? null : id === 'cargo' ? h.cargo ?? null : id === 'culture' ? h.culture ?? null : id === 'vehicles' ? h.vehicles ?? null : id === 'earnings' ? h.earnings ?? null : null;
  }

  opened(): void {
    const ok = this.available();
    if (!ok.includes(this.pick)) this.pick = ok[0] ?? 'week';
    this.wake();
  }

  private wake(): void {
    if (this.pick === 'week') this.host.picksOpened();
    else if (isWorks(this.pick)) this.host.worksOpened();
    else this.body(this.pick)?.opened();
  }

  tick(): void { this.body(this.pick)?.tick(); }

  press(target: HTMLElement): boolean {
    const p = target.closest('[data-wpick]') as HTMLElement | null;
    if (p) {
      this.pick = p.dataset.wpick as WorldPick;
      try { localStorage.setItem(PICK_KEY, this.pick); } catch { /* not remembered */ }
      this.wake();
      return true;
    }
    if (this.pick === 'week') return this.host.picksPress(target);
    if (isWorks(this.pick)) return this.host.worksPress(target);
    if (scopePress(target)) return true;
    return this.body(this.pick)?.press(target) ?? false;
  }

  html(): { left: string; right: string } {
    const groups = this.picks();
    if (!this.available().includes(this.pick)) this.pick = this.available()[0] ?? 'week';
    const left = groups.map((g) => `<div class="wgroup"><h4>${g.group}</h4><ul class="wpicks">${g.items.map((i) =>
      `<li class="${this.pick === i.id ? 'on' : ''}"><button type="button" class="pick" data-wpick="${i.id}"><span class="what"><b>${i.label}</b><small>${i.sub}</small></span></button></li>`).join('')}</ul></div>`).join('')
      || '<p class="none">Nothing to show offline.</p>';
    let right: string;
    const rows = () => this.host.rows(), me = this.host.me();
    if (this.pick === 'week') right = `<div class="worldtab">${this.host.picksHtml() || '<p class="none">No picks yet this week.</p>'}</div>`;
    else if (isWorks(this.pick)) right = this.host.worksHtml(this.pick);
    // the records: every board under the scope chips, among everyone, your friends or your neighbours
    else right = (this.host.online() && this.pick !== 'titles' && this.pick !== 'lifetime' ? scopeChips() : '') + (this.body(this.pick)?.html(rows, me) ?? '');
    return { left, right };
  }
}
