import { hex, scale, type RGB } from '../../world/biomes';
import { FLOOR } from '../../world/towns';
import type { Rng } from '../../world/rng';
import { DARK, NEON_HOURS, type Kit, type P3 } from './kit';
import { BULB, BULB_HOURS, SIGN_BACK, bladeName, bulbRow, frontText, letters, roofName } from './neon';

/**
 * The Strip's signs (a Las Vegas, world/towns.ts `vegas`), hung on every street building that fronts it (kit.ts
 * styleDress; world/strip.ts frontsStrip) and on nothing else in the town. Not Tokyo's blade signs: the Strip's are
 * pylons out on the pavement — a pole, a big sign head lettered in Latin capitals on both faces, chaser bulbs
 * round its edge, a starburst on top and an arrow of bulbs pointing in at the door — over a fascia lettered with
 * what is inside (SLOTS, BUFFET, WEDDINGS), a name down the front of a tall one and on a rack over the roof.
 *
 * Everything lit is a glowing box or quad on the night schedule, or a glyph from the sign atlas tinted its tube's
 * colour (render/buildings/signGlyphs.ts), so no light is added and no shader compiled (see neon.ts).
 */

/** The Strip's tube colours: gold, red, hot pink, cyan, white, violet, orange. */
const TUBES = [0xffc83a, 0xff3a3a, 0xff4ab0, 0x2ee0ff, 0xf4f6ff, 0xb45aff, 0xff8a2a].map(hex);
const tubeOf = (r: Rng): RGB => TUBES[Math.floor(r() * TUBES.length) % TUBES.length];

/** What a pylon's head says: a line or two, none longer than the head is wide. */
const HEADS: string[][] = [
  ['LUCKY', 'STAR'], ['GOLD', 'RUSH'], ['DESERT', 'SUN'], ['ACE', 'HIGH'], ['BIG', 'WIN'], ['SILVER', 'SPUR'], ['STAR', 'LITE'],
  ['OASIS'], ['JACKPOT'], ['LUCKY 7'], ['HI-HO'], ['TOP', 'HAT'], ['WILD', 'CARD'], ['BLUE', 'MOON'], ['COPPER', 'KING'],
  ['SAND', 'DOLLAR'], ['RED', 'ROCK'], ['ROYAL', 'FLUSH'], ['DOUBLE', 'DOWN'], ['MOON', 'GLOW'], ['CACTUS', 'JACK'], ['DIAMOND'],
];
/** What a fascia says: what is inside. */
const FASCIAS = [
  'CASINO', 'SLOTS', 'POKER', 'KENO', 'BINGO', 'BUFFET', 'LOUNGE', 'SHOWS', 'HOTEL', 'WEDDINGS', 'GIFTS', 'CHIPS', 'DICE',
  '24 HRS', 'CABARET', 'ARCADE', 'STEAKS', 'COCKTAILS', 'LIVE', 'MAGIC', 'COMEDY', 'VACANCY',
];
/** Down the front of a tall one. */
const BLADES = ['HOTEL', 'CASINO', 'SLOTS', 'SHOWS', 'RESORT', 'TOWER'];

const pickOf = <T>(r: Rng, list: readonly T[]): T => list[Math.floor(r() * list.length) % list.length];

/**
 * The signs on one building fronting the Strip, in its own frame (front +z): the building w wide and d deep (walls
 * inside its lot), `floors` storeys.
 */
export function stripSigns(k: Kit, r: Rng, w: number, d: number, floors: number): void {
  const h = floors * FLOOR, front = d / 2;
  // the fascia over the ground floor: a dark board, the word in neon on it, bulbs chasing along both its edges
  const fw = Math.max(0.3, w * 0.88), fy = FLOOR * 0.66, fh = 0.12;
  k.box(0, fy, front + 0.015, fw, fh, 0.03, SIGN_BACK);
  const words = FASCIAS.filter((s) => s.length * 0.075 * 0.66 <= fw - 0.06);
  const fc = tubeOf(r);
  if (words.length) frontText(k, pickOf(r, words), 0, fy + 0.02, front + 0.03, 0.075, fc);
  const nb = Math.max(4, Math.round(fw / 0.07));
  bulbRow(k, [-fw / 2 + 0.02, fy + fh - 0.01, front + 0.034], [fw / 2 - 0.02, fy + fh - 0.01, front + 0.034], nb, BULB, BULB_HOURS, 'z');
  bulbRow(k, [-fw / 2 + 0.02, fy + 0.012, front + 0.034], [fw / 2 - 0.02, fy + 0.012, front + 0.034], nb, BULB, BULB_HOURS, 'z');
  // the pylon, at one front corner, out on the pavement
  const side = r() < 0.5 ? -1 : 1;
  pylon(k, r, side * Math.max(0, w / 2 - 0.07), front + 0.06, Math.min(1.75, 0.95 + floors * 0.06));
  // a name down the front of a tall one, at the other corner
  if (floors >= 4) {
    const word = pickOf(r, BLADES), n = word.length;
    const cellH = Math.min(0.17, (h - FLOOR * 1.5) / (n + 0.7));
    if (cellH >= 0.07) bladeName(k, word, -side * Math.max(0, w / 2 - 0.08), FLOOR * 1.2, front, 0.2, cellH, SIGN_BACK, tubeOf(r), tubeOf(r), { bulbs: true, crown: 'star' });
  }
  // and its name on a rack over the roof
  if (floors >= 3 && floors <= 30 && r() < 0.55) {
    const lines = pickOf(r, HEADS), name = lines.join(' ');
    const lh = Math.min(0.16, (w * 0.8) / (name.length * 0.66 + 0.5));
    if (lh >= 0.06) roofName(k, name, 0, h, -d * 0.1, lh, tubeOf(r), tubeOf(r));
  }
}

/** A glowing quad both ways in the plane x = `x`, four points given as (y, z): a starburst's ray, an arrowhead. */
function vane(k: Kit, x: number, pts: [number, number][], day: RGB, glow: RGB): void {
  const [a, b, c, e] = pts.map(([y, z]): P3 => [x, y, z]);
  const my = (a[1] + b[1] + c[1] + e[1]) / 4, mz = (a[2] + b[2] + c[2] + e[2]) / 4;
  k.glowQuad(a, b, c, e, [x - 0.05, my, mz], day, NEON_HOURS, glow);
  k.glowQuad(a, b, c, e, [x + 0.05, my, mz], day, NEON_HOURS, glow);
}

/**
 * A Strip pylon standing at (x, z) to height H: a steel pole, the sign head square on to the street (in the plane
 * x = `x`, so it reads to the traffic both ways), its name on both faces, chaser bulbs round it, a starburst on top
 * and an arrow of bulbs under it pointing back in at the door.
 */
function pylon(k: Kit, r: Rng, x: number, z: number, H: number): void {
  const t = 0.05, HW = 0.46, HH = 0.4, zc = z + HW / 2 - 0.02, y0 = H - HH;
  const edge = tubeOf(r), letter = tubeOf(r), back = scale(tubeOf(r), 0.35);
  // the pole and its footing
  k.box(x, 0, z, 0.07, 0.04, 0.07, hex(0x8a8e92));
  k.box(x, 0, z, 0.035, H, 0.035, DARK);
  // the head: an enamelled box, its tube round both faces, the name in two lines at most
  k.box(x, y0, zc, t, HH, HW, back);
  if (k.mode === 'derelict') return;
  const g = 0.014;
  for (const sx of [1, -1]) {
    const fx = x + sx * (t / 2 + g / 2);
    k.glowBox(fx, y0 + 0.012, zc, g, g, HW - 0.03, scale(edge, 0.6), NEON_HOURS, edge);
    k.glowBox(fx, H - 0.012 - g, zc, g, g, HW - 0.03, scale(edge, 0.6), NEON_HOURS, edge);
    k.glowBox(fx, y0 + 0.012, zc - HW / 2 + 0.02, g, HH - 0.024, g, scale(edge, 0.6), NEON_HOURS, edge);
    k.glowBox(fx, y0 + 0.012, zc + HW / 2 - 0.02, g, HH - 0.024, g, scale(edge, 0.6), NEON_HOURS, edge);
  }
  const lines = pickOf(r, HEADS);
  const most = Math.max(...lines.map((s) => s.length));
  const lh = Math.min(0.13, (HW - 0.1) / (most * 0.66), (HH - 0.12) / (lines.length * 1.25));
  lines.forEach((line, i) => {
    const y = y0 + HH / 2 + (lines.length / 2 - i - 1) * lh * 1.25 + lh * 0.12;
    // read from outside each face: the right hand runs toward -z on the +x face, +z on the other
    letters(k, line, [x + t / 2 + 0.004, y, zc], [0, -1], lh, letter);
    letters(k, line, [x - t / 2 - 0.004, y, zc], [0, 1], lh, letter);
  });
  // chaser bulbs all round the head, both faces
  const s = t / 2 + 0.008, zl = zc - HW / 2 + 0.035, zr = zc + HW / 2 - 0.035, yb = y0 + 0.035, yt = H - 0.035;
  bulbRow(k, [x, yt, zl], [x, yt, zr], 8, BULB, BULB_HOURS, 'x', s);
  bulbRow(k, [x, yb, zl], [x, yb, zr], 8, BULB, BULB_HOURS, 'x', s);
  bulbRow(k, [x, yb + 0.05, zr], [x, yt - 0.05, zr], 6, BULB, BULB_HOURS, 'x', s);
  bulbRow(k, [x, yb + 0.05, zl], [x, yt - 0.05, zl], 6, BULB, BULB_HOURS, 'x', s);
  // the starburst on top: a hub and eight rays, long and short, on a short mast
  const star = tubeOf(r), cy = H + 0.17;
  k.box(x, H, zc, 0.02, 0.1, 0.02, DARK);
  k.glowBox(x, cy - 0.025, zc, t, 0.05, 0.05, star, NEON_HOURS, star);
  for (let i = 0; i < 8; i++) {
    const a = (i / 8) * Math.PI * 2 + Math.PI / 8, L = i % 2 ? 0.09 : 0.15;
    const cy0 = Math.sin(a), cz0 = Math.cos(a), py = -cz0 * 0.012, pz = cy0 * 0.012;
    vane(k, x, [
      [cy + cy0 * 0.03 + py, zc + cz0 * 0.03 + pz], [cy + cy0 * 0.03 - py, zc + cz0 * 0.03 - pz],
      [cy + cy0 * L - py * 0.3, zc + cz0 * L - pz * 0.3], [cy + cy0 * L + py * 0.3, zc + cz0 * L + pz * 0.3],
    ], scale(star, 0.7), star);
  }
  // the arrow under the head, out over the pavement and pointing back in at the door (-z)
  const ay = y0 - 0.1, a0 = zc + HW / 2 - 0.04, a1 = z - 0.02, arrow = tubeOf(r);
  k.box(x, ay - 0.03, (a0 + a1) / 2, t * 0.8, 0.06, a0 - a1, back);
  bulbRow(k, [x, ay, a0 - 0.02], [x, ay, a1 + 0.08], 6, arrow, BULB_HOURS, 'x', t * 0.4 + 0.006);
  vane(k, x, [[ay + 0.07, a1 + 0.1], [ay, a1 - 0.02], [ay - 0.014, a1 + 0.002], [ay + 0.056, a1 + 0.122]], scale(arrow, 0.7), arrow);
  vane(k, x, [[ay - 0.07, a1 + 0.1], [ay - 0.056, a1 + 0.122], [ay + 0.014, a1 + 0.002], [ay, a1 - 0.02]], scale(arrow, 0.7), arrow);
}
