import { hex, scale, type RGB } from '../../world/biomes';
import { FLOOR } from '../../world/towns';
import type { Rng } from '../../world/rng';
import type { LakeKind } from '../../world/lakeKinds';
import { Vis } from '../nightLights';
import { TAU, WARM_GLOW, WHITE, cur, curArch, pick, styleWall, win, type Draw, type Kit } from './kit';
import {
  CHROME, IRON, LAMPS, PLANK, PLANK_DARK, ROOMS, SAND, STONE, STONE_DARK, beachgoer, bench, bollard, cypress, deck,
  dockBoat, flagpole, lakeLamp, lakePalm, pontoon, riva, rowboat, sailboat, stroller, swimmer, toWater, umbrella,
} from './lakeKit';

/**
 * What stands along every lake town's shore, drawn in the frame `toWater` turns to (the lake past +z, the lot's edge
 * on the water at z = Dp / 2, the water's surface a step under the bank at y), each in its town's manner:
 *
 * - **Steamer landing** (steamerPier): a ticket kiosk on the quay, steps down to a pier on piles and the landing stage
 *   at its end where the steamer ties up; a glass-roofed shelter on it at Léman and Como, the town's flag on a staff.
 * - **Boat dock** (lakeDock): a dock and its finger piers with the boats in their slips: Okoboji's pontoons under
 *   their lift canopies, Léman's sailing boats, a Como darsena's stone steps and striped mooring poles with the Rivas.
 * - **Boathouse** (lakeBoathouse): two storeys, its slip at the water with a boat inside, a sundeck or a loggia on top.
 * - **Bathing beach** (swimBeach): sand down into the water, umbrellas, a lifeguard's chair and the snack shack, and the
 *   swimming raft anchored offshore with swimmers round it; a Léman bains is a sunbathing deck and a little lighthouse,
 *   a Como lido a paved terrace of loungers. Only in summer.
 * - **Lake cottage** (lakeCottage): a painted clapboard cottage with its screened porch, Adirondack chairs, a canoe.
 * - **Lake estate** (lakeEstate): a Gilded Age house (a Queen Anne with its tower, a Georgian, a shingle-style) at the
 *   top of a lawn running down to the shore path along the water, a pier and its launch.
 * - **Grand hotel** (grandHotel): Léman's belle époque palace under mansards and domes, Como's long yellow villa-hotel,
 *   the American lakes' white wooden resort hotel with its veranda the length of the front.
 */

const TICKET = hex(0x2f5a3a);
const FLAGS: Record<string, { stripes: number[]; swiss?: boolean }> = {
  lakeside: { stripes: [0xb22234, 0xf4f2ec, 0xb22234, 0xf4f2ec, 0x3c3b6e] },
  victorian: { stripes: [0xb22234, 0xf4f2ec, 0xb22234, 0xf4f2ec, 0x3c3b6e] },
  leman: { stripes: [], swiss: true },
  como: { stripes: [0x009246, 0xf4f2ec, 0xce2b37] },
};
const flagHere = (k: Kit, x: number, y: number, z: number, h: number) => {
  const f = FLAGS[curArch] ?? FLAGS.lakeside;
  if (curArch === 'como') {
    // the tricolore hangs vertical stripes: drawn as three narrow bands side by side
    k.cyl(x, y, z, 0.007, h, hex(0xe8e8ea), 4);
    f.stripes.forEach((c, i) => k.box(x + 0.024 + i * 0.047, y + h - 0.09, z, 0.047, 0.09, 0.004, hex(c)));
    return;
  }
  flagpole(k, x, y, z, h, f.stripes, f.swiss);
};

/** Steps from the bank (y 0, at z0) down to a dock at y1, `w` wide, running out along +z. */
function steps(k: Kit, x: number, z0: number, y1: number, w: number, col: RGB): number {
  const n = Math.max(3, Math.round(-y1 / 0.07)), run = 0.05;
  for (let i = 0; i < n; i++) {
    const top = (-y1 * (n - 1 - i)) / n;
    k.box(x, y1 - 0.03, z0 + i * run + run / 2, w, top + 0.03, run, col);
  }
  return z0 + n * run;
}

// ---- the steamer landing ------------------------------------------------------------------------

const steamerPier: Draw = (k, W, D, b, r) => {
  toWater(k, b, W, D, (L, Dp, wy, reach) => {
    const qz = Dp / 2, dy = wy + 0.1, out = Math.max(0.9, Math.min(1.8, reach - 0.6));
    const stone = curArch === 'leman' || curArch === 'como';
    // the quay: paving (stone at Léman and Como, planks on the American lakes) with its kerb along the water
    k.box(0, 0, 0, L - 0.04, 0.02, Dp - 0.04, stone ? STONE : PLANK, stone ? scale(STONE, 1.04) : PLANK);
    k.box(0, wy, qz + 0.02, L - 0.04, -wy + 0.02, 0.04, STONE_DARK);
    // the ticket kiosk and its little roof, a bench and the timetable board
    const kx = -L / 2 + 0.35, kz = -Dp / 2 + 0.4, kc = curArch === 'lakeside' ? hex(0xf4f2ec) : curArch === 'victorian' ? hex(0x8a3a2a) : TICKET;
    k.box(kx, 0.02, kz, 0.34, 0.24, 0.26, kc);
    k.pane(kx, 0.1, kz + 0.13, 0.2, 0.09, 1, hex(0x3a4a56), ROOMS, WARM_GLOW);
    k.box(kx, 0.26, kz, 0.42, 0.015, 0.34, scale(kc, 0.8));
    k.hip(kx, 0.275, kz, 0.42, 0.1, 0.34, pick(r, cur.roofs));
    k.box(kx + 0.3, 0.02, kz + 0.04, 0.02, 0.2, 0.02, IRON);
    k.box(kx + 0.3, 0.16, kz + 0.04, 0.16, 0.1, 0.012, hex(0xf2ead6));
    bench(k, L / 2 - 0.4, 0.02, -Dp / 2 + 0.3);
    lakeLamp(k, curArch, L / 2 - 0.2, 0.02, qz - 0.15);
    flagHere(k, -L / 2 + 0.15, 0.02, qz - 0.12, 0.55);
    // down to the pier, then out on its piles, and the landing stage across its end
    const px = L * 0.12;
    const z1 = steps(k, px, qz - 0.05, dy, 0.34, stone ? STONE_DARK : PLANK_DARK);
    deck(k, px, (z1 + qz + out) / 2, 0.36, qz + out - z1, dy, wy);
    const sz = qz + out + 0.17;
    deck(k, px, sz, Math.min(L * 0.9, 1.5), 0.34, dy, wy, scale(PLANK, 0.92));
    for (const sx of [-0.6, 0.6]) bollard(k, px + sx, dy, sz + 0.12);
    // rails along the pier, a life ring
    for (const sd of [-1, 1]) k.box(px + sd * 0.17, dy, (z1 + qz + out) / 2, 0.01, 0.06, qz + out - z1, hex(0xf4f2ec));
    k.hoop(px + 0.19, dy + 0.07, (z1 + qz + out) / 2, 0.035, 0.008, hex(0xe8402e), 8, 'zy');
    // the shelter on the landing stage: glass and iron at Léman and Como, a striped canopy elsewhere
    if (stone) {
      for (const sx of [-0.35, 0.35]) k.cyl(px + sx, dy, sz - 0.08, 0.01, 0.26, IRON, 5);
      k.box(px, dy + 0.26, sz - 0.08, 0.86, 0.012, 0.22, hex(0x9ab8c0));
      k.box(px, dy + 0.272, sz - 0.08, 0.9, 0.02, 0.02, IRON);
      bench(k, px, dy, sz - 0.14, IRON);
    } else {
      for (const sx of [-0.3, 0.3]) k.cyl(px + sx, dy, sz - 0.08, 0.008, 0.22, hex(0xf4f2ec), 4);
      for (let i = 0; i < 5; i++) k.box(px - 0.3 + i * 0.15, dy + 0.22, sz - 0.08, 0.15, 0.01, 0.2, i % 2 ? hex(0xf4f2ec) : hex(curArch === 'victorian' ? 0x2a4a7a : 0x2f6a4a));
    }
    k.glowBox(px - 0.6, dy + 0.02, sz + 0.12, 0.03, 0.03, 0.03, hex(0x3fbf5a), LAMPS, hex(0x6aff8a));
    // passengers waiting
    k.tagged(Vis.NotWinter, () => { for (let i = 0; i < 3; i++) stroller(k, r, px - 0.25 + i * 0.2, dy, sz - 0.02); });
  });
};

// ---- the boat dock ------------------------------------------------------------------------------

const lakeDock: Draw = (k, W, D, b, r) => {
  toWater(k, b, W, D, (L, Dp, wy, reach) => {
    const qz = Dp / 2, dy = wy + 0.08, out = Math.max(0.7, Math.min(1.3, reach - 0.5));
    if (curArch === 'como') {
      // a darsena: stone steps down to the water, the landing along it, the blue-and-white poles the boats tie to
      k.box(0, 0, -0.1, L - 0.06, 0.02, Dp - 0.3, STONE);
      k.box(0, wy, qz + 0.02, L - 0.04, -wy + 0.02, 0.04, STONE_DARK);
      steps(k, 0, qz - 0.1, dy, L - 0.4, STONE_DARK);
      k.box(0, dy - 0.04, qz + 0.32, L - 0.2, 0.04, 0.22, STONE_DARK);
      for (let i = 0; i < 3; i++) {
        const bx = -L / 2 + 0.45 + i * ((L - 0.9) / 2);
        for (const pz of [qz + 0.55, qz + 1.05]) {
          for (let s = 0; s < 4; s++) k.cyl(bx + 0.13, wy - 0.05 + s * 0.08, pz, 0.014, 0.08, s % 2 ? hex(0xf4f2ec) : hex(0x2a5aa8), 5);
        }
        if (r() < 0.85) {
          k.turned(Math.PI / 2, () => riva(k, -(qz + 0.78), wy, bx, 1));
        }
      }
      for (const sx of [-1, 1]) lakeLamp(k, 'como', sx * (L / 2 - 0.15), 0.02, qz - 0.15);
      cypress(k, -L / 2 + 0.2, 0.02, -Dp / 2 + 0.25, 0.7);
      return;
    }
    // planks on the bank, steps down, the dock out along the shore and its finger piers between the slips
    k.box(0, 0, 0, L - 0.06, 0.02, Dp - 0.06, scale(PLANK, 0.95));
    k.box(0, wy, qz + 0.02, L - 0.04, -wy + 0.02, 0.04, curArch === 'leman' ? STONE_DARK : hex(0x8a7a62));
    const z1 = steps(k, -L / 2 + 0.3, qz - 0.05, dy, 0.3, PLANK_DARK);
    deck(k, -L / 2 + 0.3, (z1 + qz + out) / 2, 0.3, qz + out - z1, dy, wy);
    deck(k, 0, qz + out + 0.12, L - 0.2, 0.24, dy, wy);
    const slips = Math.max(2, Math.round((L - 0.6) / 0.42));
    for (let i = 0; i < slips; i++) {
      const fx = -L / 2 + 0.6 + i * ((L - 0.8) / slips);
      deck(k, fx, qz + out - 0.25, 0.08, 0.5, dy, wy);
      const bx = fx + (L - 0.8) / slips / 2;
      if (r() < 0.85) k.turned(Math.PI / 2, () => dockBoat(k, curArch, -(qz + out - 0.25), wy, bx, r));
      // an Okoboji boat lift and its canopy over the slip
      if (curArch === 'lakeside' && r() < 0.6) {
        for (const [dx, dz] of [[-0.12, -0.22], [0.12, -0.22], [-0.12, 0.22], [0.12, 0.22]]) k.cyl(bx + dx, wy - 0.05, qz + out - 0.25 + dz, 0.006, 0.36, CHROME, 4);
        k.box(bx, wy + 0.31, qz + out - 0.25, 0.28, 0.012, 0.5, hex([0x2f5f9a, 0xe8e2d4, 0x3a7a5a][Math.floor(r() * 3)]));
      }
    }
    for (let i = 0; i < 3; i++) bollard(k, -L / 2 + 0.4 + i * ((L - 0.8) / 2), dy, qz + out + 0.22);
    // on the bank: Adirondack chairs and a fire ring in Okoboji, a bench elsewhere
    if (curArch === 'lakeside') {
      for (const sx of [-0.2, 0.05]) {
        const ch = hex([0xe2412f, 0x2f7fb5, 0x3f9b4a, 0xf2c14e][Math.floor(r() * 4)]);
        k.box(L / 2 - 0.5 + sx, 0.02, -0.1, 0.07, 0.03, 0.08, ch);
        k.box(L / 2 - 0.5 + sx, 0.05, -0.135, 0.07, 0.06, 0.012, ch);
      }
      k.cyl(L / 2 - 0.5, 0.02, 0.15, 0.06, 0.02, hex(0x6a6058), 8, hex(0x3a3430));
    } else bench(k, L / 2 - 0.45, 0.02, -0.1);
    k.tagged(Vis.Summer, () => { if (r() < 0.6) stroller(k, r, 0, dy, qz + out + 0.12); });
  });
};

// ---- the boathouse ------------------------------------------------------------------------------

const lakeBoathouse: Draw = (k, W, D, b, r) => {
  toWater(k, b, W, D, (L, Dp, wy) => {
    const qz = Dp / 2, w = Math.min(L - 0.1, 0.8), z0 = -0.2, z1 = qz + 0.55, d = z1 - z0, zc = (z0 + z1) / 2;
    const como = curArch === 'como', geneva = curArch === 'victorian';
    const wall = como ? hex(0xe8d8b8) : geneva ? pick(r, [0xf2ece0, 0x6a4a34, 0x8a3a2a, 0xe8e0c8]) : styleWall(r);
    const trim = hex(cur.trim), roof = pick(r, cur.roofs);
    // the slip: walls standing in the water, open to the lake with the boat inside
    k.box(0, wy - 0.12, zc, w, -wy + 0.12, d, como ? STONE : wall);
    k.box(0, wy - 0.0, z1 + 0.001, w * 0.7, -wy * 0.82, 0.004, hex(0x1e2226));
    if (como) {
      // a stone water gate under a round arch
      for (let i = 0; i < 4; i++) k.box(0, wy - wy * 0.82 + i * 0.02, z1 + 0.004, w * 0.7 - i * 0.07, 0.02, 0.008, STONE_DARK);
    } else {
      k.box(0, -0.02, z1 + 0.004, w * 0.78, 0.04, 0.012, trim);
    }
    k.turned(Math.PI / 2, () => (como ? riva(k, -(z1 - 0.25), wy, 0, 0.9) : geneva ? riva(k, -(z1 - 0.25), wy, 0, 0.95) : pontoon(k, -(z1 - 0.25), wy, 0, r, false)));
    // the room over it, and its roof
    const h = 0.3;
    k.box(0, 0, zc, w, h, d, wall);
    for (const zz of [z0 + d * 0.3, z0 + d * 0.7]) for (const sd of [0, 2]) win(k, b, r, sd === 0 ? w / 2 : -w / 2, 0.08, zz, 0.12, 0.12, sd);
    win(k, b, r, -w * 0.2, 0.08, z1, 0.14, 0.13, 1);
    win(k, b, r, w * 0.2, 0.08, z1, 0.14, 0.13, 1);
    if (geneva || como) {
      // a flat sundeck (Geneva) or a terrace (Como) on top, railed, an umbrella or a pergola on it
      k.box(0, h, zc, w + 0.04, 0.02, d + 0.04, como ? STONE : trim);
      for (const sd of [-1, 1]) k.box(sd * (w / 2), h + 0.02, zc, 0.01, 0.06, d, como ? STONE_DARK : trim);
      k.box(0, h + 0.02, z1, w, 0.06, 0.01, como ? STONE_DARK : trim);
      if (como) { for (const [x, z] of [[-w / 2 + 0.06, z0 + 0.08], [w / 2 - 0.06, z1 - 0.08]]) k.box(x, h + 0.02, z, 0.06, 0.06, 0.06, hex(0xc8784a)); }
      else k.tagged(Vis.Summer, () => umbrella(k, w * 0.15, h + 0.02, zc + 0.1, hex(0x2a4a7a)));
    } else {
      k.gable(0, h, zc, w + 0.08, 0.22, d + 0.08, roof, wall, true);
      k.box(0, h + 0.05, z1 + 0.04, 0.12, 0.08, 0.01, trim);
    }
    // the gangway from the bank
    k.box(-w / 2 - 0.08, 0, z0 + 0.1, 0.14, 0.02, 0.3, PLANK);
  });
};

// ---- the bathing beach --------------------------------------------------------------------------

const swimBeach: Draw = (k, W, D, b, r) => {
  toWater(k, b, W, D, (L, Dp, wy, reach) => {
    const qz = Dp / 2, raftZ = qz + Math.max(0.8, Math.min(1.6, reach - 0.8));
    if (curArch === 'leman') {
      // les bains: a sunbathing deck out over the water on its piles, a changing block, a little lighthouse
      k.box(0, 0, -0.2, L - 0.06, 0.02, Dp - 0.5, STONE);
      deck(k, 0, qz + 0.35, L - 0.3, 0.7, 0.02, wy);
      k.box(-L / 2 + 0.45, 0.02, -Dp / 2 + 0.35, 0.7, 0.24, 0.3, hex(0xf0ece0));
      for (let i = 0; i < 4; i++) k.box(-L / 2 + 0.2 + i * 0.16, 0.02, -Dp / 2 + 0.51, 0.1, 0.18, 0.006, hex(i % 2 ? 0x2f6a8a : 0xf4f2ec));
      const lx = L / 2 - 0.25, lz = qz + 0.55;
      k.cyl(lx, 0.02, lz, 0.06, 0.4, WHITE, 8);
      for (let i = 0; i < 3; i++) k.cyl(lx, 0.06 + i * 0.12, lz, 0.062, 0.04, hex(0x2f8a4a), 8);
      k.glowBox(lx, 0.42, lz, 0.07, 0.07, 0.07, hex(0xe8e8d8), [18, 30, 1.6], hex(0xfff2c0));
      k.cone(lx, 0.49, lz, 0.07, 0.07, hex(0x2f8a4a), 8);
      for (let i = 0; i < 4; i++) k.cyl(-0.4 + i * 0.25, 0.02 - 0.02, qz + 0.68, 0.005, 0.09, IRON, 4);
    } else if (curArch === 'como') {
      // a lido: a paved terrace with rows of loungers under umbrellas, a ladder down into the lake
      k.box(0, 0, 0, L - 0.06, 0.02, Dp - 0.06, hex(0xe8dcc4));
      k.box(0, wy, qz + 0.02, L - 0.04, -wy + 0.02, 0.04, STONE_DARK);
      for (const sd of [-0.18, 0.18]) k.cyl(sd, wy, qz + 0.08, 0.008, -wy + 0.12, CHROME, 4);
      k.tagged(Vis.Summer, () => {
        for (let i = 0; i < 5; i++) for (const rz of [-0.3, 0.25]) {
          const x = -L / 2 + 0.35 + i * ((L - 0.7) / 4);
          k.box(x, 0.02, rz, 0.07, 0.025, 0.17, WHITE);
          umbrella(k, x + 0.06, 0.02, rz - 0.05, hex(i % 2 ? 0xf2c14e : 0xf4f2ec));
        }
      });
      lakePalm(k, -L / 2 + 0.15, 0.02, -Dp / 2 + 0.15, 0.55, r);
    } else {
      // sand down into the water, the snack shack, the lifeguard on his high chair
      k.box(0, 0, -0.05, L - 0.04, 0.02, Dp - 0.1, SAND);
      // the sand running down into the shallows: a ramp from the bank's edge to under the water's surface
      k.turned(Math.PI, () => k.wedge(0, wy - 0.06, -(qz + 0.3), L - 0.04, -wy + 0.08, 0.7, SAND));
      k.box(0, wy - 0.065, qz + 0.75, L - 0.04, 0.03, 0.3, scale(SAND, 0.82));
      const sx = -L / 2 + 0.35, sz = -Dp / 2 + 0.32;
      k.box(sx, 0.02, sz, 0.5, 0.22, 0.3, hex(curArch === 'victorian' ? 0xf4f2ec : 0x8ac0d8));
      k.box(sx, 0.24, sz + 0.02, 0.6, 0.015, 0.4, hex(0xe2412f));
      k.box(sx, 0.08, sz + 0.151, 0.36, 0.1, 0.004, hex(0x2a3a44));
      const gx = L / 2 - 0.35, gz = qz - 0.2;
      for (const [dx, dz] of [[-0.05, -0.05], [0.05, -0.05], [-0.05, 0.05], [0.05, 0.05]]) k.bar([gx + dx * 1.6, 0.02, gz + dz * 1.6], [gx + dx, 0.32, gz + dz], 0.008, WHITE);
      k.box(gx, 0.32, gz, 0.12, 0.012, 0.12, WHITE);
      k.box(gx, 0.332, gz - 0.05, 0.12, 0.08, 0.01, WHITE);
      k.tagged(Vis.Summer, () => {
        k.box(gx, 0.333, gz, 0.03, 0.06, 0.02, hex(0xe2412f));
        k.box(gx, 0.393, gz, 0.02, 0.02, 0.02, hex(0xe0b080));
        umbrella(k, gx + 0.08, 0.332, gz, hex(0xe2412f));
        for (let i = 0; i < 4; i++) umbrella(k, -L / 2 + 0.9 + i * ((L - 1.4) / 3), 0.02, -0.15 + (i % 2) * 0.2, hex([0xe2412f, 0x2f7fb5, 0xf2c14e, 0x3f9b4a][i]));
        for (let i = 0; i < 6; i++) beachgoer(k, r, -L / 2 + 0.75 + r() * (L - 1.3), 0.02, -0.25 + r() * 0.5, r() < 0.65);
        for (let i = 0; i < 3; i++) beachgoer(k, r, -L / 2 + 0.6 + r() * (L - 1.2), wy + 0.01, qz + 0.3, false);
      });
    }
    // the swimming raft anchored offshore, its ladder, and the line of buoys marking the swim area
    k.tagged(Vis.NotWinter, () => {
      const rx = (r() - 0.5) * L * 0.3;
      k.box(rx, wy - 0.02, raftZ, 0.42, 0.05, 0.42, scale(PLANK, 0.9));
      for (const dx of [-0.17, 0.17]) for (const dz of [-0.17, 0.17]) k.cyl(rx + dx, wy - 0.05, raftZ + dz, 0.035, 0.04, hex(0xd8d8d0), 6);
      for (const sd of [-0.05, 0.05]) k.box(rx + sd, wy - 0.08, raftZ + 0.215, 0.008, 0.11, 0.008, CHROME);
      for (let i = 0; i < 7; i++) k.disc(-L / 2 + 0.2 + (i * (L - 0.4)) / 6, wy + 0.002, raftZ + 0.5, 0.025, i % 2 ? WHITE : hex(0xe2412f), 6);
    });
    // swimmers round the raft, sunbathers on it, now and then one diving in (summer days)
    k.tagged(Vis.Summer, () => {
      const rx = 0, n = 6, seeds = Array.from({ length: n }, () => r());
      const parts: ((sk: Kit) => void)[] = seeds.map((q) => (sk: Kit) => swimmer(sk, () => q, 0, 0, 0));
      parts.push((sk) => beachgoer(sk, r, 0, 0, 0, true));
      parts.push((sk) => beachgoer(sk, r, 0, 0, 0, false));
      let t = r() * 50;
      k.rig(rx, wy, raftZ, parts, (ps, dt, hour) => {
        t += dt;
        const day = hour > 9.5 && hour < 19;
        for (let i = 0; i < n; i++) {
          const o = ps[i], a = seeds[i] * TAU + t * (0.08 + seeds[i] * 0.06) * (i % 2 ? 1 : -1), rad = 0.35 + seeds[i] * 0.55;
          o.position.set(Math.cos(a) * rad, Math.sin(t * 1.7 + i) * 0.006, Math.sin(a) * rad * 0.7 - 0.2);
          o.rotation.y = -a;
          o.visible = day;
        }
        // someone lying out on the raft, and someone on its edge who dives in and swims back to the ladder
        const lie = ps[n], dive = ps[n + 1], ph = (t * 0.07) % 1;
        lie.position.set(-0.06, 0.03, -0.05);
        lie.rotation.y = 0.4;
        lie.visible = day;
        if (ph < 0.6) { dive.position.set(0.12, 0.03, 0.1); dive.rotation.set(0, Math.PI, 0); }
        else if (ph < 0.68) {
          const u = (ph - 0.6) / 0.08;
          dive.position.set(0.12, 0.03 + Math.sin(u * Math.PI) * 0.12 - u * 0.08, 0.1 + u * 0.3);
          dive.rotation.set(u * 2.2, Math.PI, 0);
        } else dive.position.set(0.12, -0.2, 0.4);
        dive.visible = day && ph < 0.68;
      });
    });
  });
};

// ---- the lake cottage ---------------------------------------------------------------------------

const lakeCottage: Draw = (k, W, D, b, r) => {
  const wall = styleWall(r), trim = hex(cur.trim), roof = pick(r, cur.roofs), two = b.floors >= 2;
  const w = 0.6, d = 0.5, z = -0.08, h = two ? FLOOR * 2 + 0.02 : FLOOR + 0.06;
  k.box(0, 0, z, w, h, d, wall);
  // the clapboard: a darker line every course
  k.detail(() => { for (let y = 0.04; y < h; y += 0.035) { k.box(0, y, z + d / 2 + 0.003, w, 0.004, 0.002, scale(wall, 0.86)); k.box(0, y, z - d / 2 - 0.003, w, 0.004, 0.002, scale(wall, 0.86)); } });
  for (const sx of [-1, 1]) k.box(sx * (w / 2), 0, z + d / 2, 0.02, h, 0.02, trim);
  k.gable(0, h, z, w + 0.1, 0.24, d + 0.1, roof, wall, true);
  k.box(0.16, h + 0.06, z - 0.1, 0.06, 0.18, 0.06, hex(0x9a6a54));
  // the screened porch across the front: posts, the dark screens, the steps
  const pz = z + d / 2 + 0.12;
  k.box(0, 0, pz, w + 0.04, 0.05, 0.24, PLANK);
  for (let i = 0; i <= 4; i++) k.box(-w / 2 + (w * i) / 4, 0.05, pz + 0.11, 0.016, 0.2, 0.016, trim);
  k.box(0, 0.12, pz + 0.115, w - 0.02, 0.12, 0.004, hex(0x3a4246));
  k.box(0, 0.25, pz, w + 0.06, 0.02, 0.28, scale(roof, 1.05));
  k.box(0, 0, pz + 0.16, 0.16, 0.025, 0.06, PLANK_DARK);
  win(k, b, r, -0.15, 0.08, z + d / 2, 0.12, 0.12, 1);
  win(k, b, r, 0.17, 0.08, z + d / 2, 0.12, 0.12, 1);
  win(k, b, r, w / 2, 0.08, z, 0.12, 0.12, 0);
  win(k, b, r, -w / 2, 0.08, z, 0.12, 0.12, 2);
  if (two) for (const sx of [-0.15, 0.15]) win(k, b, r, sx, FLOOR + 0.08, z + d / 2, 0.11, 0.11, 1);
  // Adirondack chairs on the lawn, a canoe on its rack, the flag
  const ch = hex([0xe2412f, 0x2f7fb5, 0x3f9b4a, 0xf2c14e, 0xf4f2ec][Math.floor(r() * 5)]);
  for (const sx of [-0.28, -0.14]) { k.box(sx, 0, 0.42, 0.07, 0.03, 0.08, ch); k.box(sx, 0.03, 0.385, 0.07, 0.06, 0.012, ch); }
  if (r() < 0.6) {
    k.box(0.32, 0, -0.42, 0.02, 0.08, 0.02, PLANK_DARK); k.box(0.32, 0, -0.22, 0.02, 0.08, 0.02, PLANK_DARK);
    k.turned(Math.PI / 2, () => rowboat(k, 0.32, 0.1, 0.32, () => 0.2));
  }
  if (r() < 0.35) flagHere(k, -0.4, 0, 0.35, 0.42);
};

// ---- the lake estate ----------------------------------------------------------------------------

const lakeEstate: Draw = (k, W, D, b, r) => {
  const v = (b.seed >>> 3) % 3;
  toWater(k, b, W, D, (L, Dp, wy, reach) => {
    const qz = Dp / 2, hz = -Dp / 2 + 0.75, floors = Math.max(2, b.floors), H = floors * FLOOR + 0.06;
    // the lawn down to the water, the shore path along it, the bank wall
    k.box(0, 0, 0, L - 0.04, 0.012, Dp - 0.04, hex(0x6aa04a));
    k.box(0, 0.012, qz - 0.14, L - 0.04, 0.004, 0.12, hex(0xd8c8a0));
    k.box(0, wy, qz + 0.02, L - 0.04, -wy + 0.02, 0.04, STONE_DARK);
    k.box(-0.3, 0.012, (hz + qz) / 2 + 0.2, 0.12, 0.004, qz - hz - 0.4, hex(0xd8c8a0));
    // flower borders and the hedge along the road side
    for (const sx of [-1, 1]) {
      k.box(sx * (L / 2 - 0.08), 0.012, 0, 0.1, 0.08, Dp - 0.3, hex(0x3f6a34));
      for (let i = 0; i < 4; i++) k.box(sx * 0.7, 0.012, hz + 0.6 + i * 0.12, 0.08, 0.03, 0.08, FLOWERS_[i % FLOWERS_.length]);
    }
    const hw = Math.min(L - 0.6, 1.6), hd = 0.85;
    if (v === 0) {
      // a Queen Anne (Black Point): painted clapboard, wraparound porch, steep gables and the round corner tower
      const wall = hex(pickOf(r, [0xf2e2a8, 0xe8e0cc, 0xc8d8c0, 0xe8c8b8])), trimC = hex(0x2f5a3a), roof = hex(0x5a4a44);
      k.box(0, 0, hz, hw, H, hd, wall);
      k.gable(0, H, hz, hw + 0.08, 0.45, hd + 0.08, roof, wall, false);
      k.gable(hw * 0.2, H - 0.05, hz + hd / 2, 0.42, 0.42, 0.3, roof, wall, true);
      const tx = -hw / 2 + 0.08, tz = hz + hd / 2 - 0.04;
      k.cyl(tx, 0, tz, 0.17, H + 0.18, wall, 10);
      k.cone(tx, H + 0.18, tz, 0.2, 0.42, roof, 10);
      k.box(tx, H + 0.6, tz, 0.012, 0.08, 0.012, IRON);
      k.box(0, 0, hz + hd / 2 + 0.12, hw + 0.08, 0.04, 0.24, PLANK);
      for (let i = 0; i <= 7; i++) k.box(-hw / 2 + (hw * i) / 7, 0.04, hz + hd / 2 + 0.22, 0.016, FLOOR - 0.02, 0.016, WHITE);
      k.box(0, FLOOR + 0.02, hz + hd / 2 + 0.12, hw + 0.12, 0.02, 0.28, trimC);
      for (let f = 0; f < floors; f++) for (let i = 0; i < 5; i++) win(k, b, r, -hw / 2 + 0.28 + i * ((hw - 0.5) / 4), 0.07 + f * FLOOR, hz + hd / 2, 0.11, 0.14, 1);
    } else if (v === 1) {
      // a Georgian house (Wadsworth Hall, Stone Manor): limestone, a pillared portico to the lake, a hipped roof with dormers
      const wall = hex(pickOf(r, [0xe8e0cc, 0xd8ccb0, 0xa8543f])), roof = hex(0x4a4e54);
      k.box(0, 0, hz, hw, H, hd, wall);
      k.box(0, H, hz, hw + 0.04, 0.05, hd + 0.04, WHITE);
      k.hip(0, H + 0.05, hz, hw + 0.06, 0.3, hd + 0.06, roof);
      for (const sx of [-0.4, 0, 0.4]) { k.box(sx * hw * 0.8, H + 0.08, hz + hd / 2 - 0.05, 0.1, 0.1, 0.1, WHITE); k.gable(sx * hw * 0.8, H + 0.18, hz + hd / 2 - 0.05, 0.12, 0.06, 0.12, roof, WHITE, true); }
      for (const sx of [-1, 1]) k.box(sx * (hw / 2 - 0.12), H + 0.05, hz - 0.1, 0.1, 0.25, 0.1, scale(wall, 0.9));
      const cols = 4, pw = hw * 0.45;
      k.box(0, 0, hz + hd / 2 + 0.14, pw + 0.1, 0.05, 0.3, WHITE);
      for (let i = 0; i < cols; i++) k.cyl(-pw / 2 + (pw * i) / (cols - 1), 0.05, hz + hd / 2 + 0.24, 0.025, H - 0.12, WHITE, 6);
      k.box(0, H - 0.07, hz + hd / 2 + 0.14, pw + 0.12, 0.07, 0.3, WHITE);
      k.gable(0, H, hz + hd / 2 + 0.14, pw + 0.12, 0.14, 0.3, roof, WHITE, true);
      for (let f = 0; f < floors; f++) for (let i = 0; i < 6; i++) { const x = -hw / 2 + 0.16 + i * ((hw - 0.32) / 5); if (Math.abs(x) > pw / 2 + 0.04 || f > 0) win(k, b, r, x, 0.07 + f * FLOOR, hz + hd / 2, 0.1, 0.15, 1); }
    } else {
      // a shingle-style cottage of the rich: brown shingles, a gambrel roof, a long porch, white trim
      const wall = hex(pickOf(r, [0x8a6a4a, 0x7a5a3e, 0x9a8a6a])), roof = hex(0x4a3a30);
      k.box(0, 0, hz, hw, FLOOR + 0.04, hd, wall);
      k.box(0, FLOOR + 0.04, hz, hw + 0.06, 0.18, hd + 0.06, roof);
      k.gable(0, FLOOR + 0.22, hz, hw + 0.06, 0.24, hd * 0.7, roof, wall, false);
      for (const sx of [-0.35, 0, 0.35]) { k.box(sx * hw, FLOOR + 0.08, hz + hd / 2 + 0.02, 0.18, 0.13, 0.06, wall); win(k, b, r, sx * hw, FLOOR + 0.1, hz + hd / 2 + 0.05, 0.12, 0.09, 1); }
      k.box(0, 0, hz + hd / 2 + 0.14, hw + 0.1, 0.04, 0.28, PLANK);
      for (let i = 0; i <= 6; i++) k.box(-hw / 2 + (hw * i) / 6, 0.04, hz + hd / 2 + 0.26, 0.02, FLOOR - 0.04, 0.02, WHITE);
      k.box(0, FLOOR, hz + hd / 2 + 0.14, hw + 0.14, 0.03, 0.32, roof);
      for (let i = 0; i < 5; i++) win(k, b, r, -hw / 2 + 0.2 + i * ((hw - 0.4) / 4), 0.07, hz + hd / 2, 0.12, 0.14, 1);
      k.box(hw / 2 - 0.2, FLOOR + 0.3, hz - 0.15, 0.08, 0.2, 0.08, hex(0x8a5a44));
    }
    // a gazebo on the lawn, the pier and its launch, a boathouse at the water's edge
    const gx = L / 2 - 0.45, gz = (hz + qz) / 2 + 0.25;
    k.box(gx, 0.012, gz, 0.3, 0.03, 0.3, WHITE);
    for (let i = 0; i < 6; i++) { const a = (i / 6) * TAU; k.cyl(gx + Math.cos(a) * 0.12, 0.04, gz + Math.sin(a) * 0.12, 0.008, 0.16, WHITE, 4); }
    k.cone(gx, 0.2, gz, 0.19, 0.12, hex(0x5a6a5a), 6);
    const dy = wy + 0.1, px = -L / 2 + 0.5, out = Math.max(0.6, Math.min(1.2, reach - 0.6));
    const z1 = steps(k, px, qz - 0.05, dy, 0.24, STONE_DARK);
    deck(k, px, (z1 + qz + out) / 2, 0.24, qz + out - z1, dy, wy);
    deck(k, px + 0.2, qz + out - 0.05, 0.6, 0.2, dy, wy);
    k.turned(Math.PI / 2, () => (r() < 0.6 ? riva(k, -(qz + out - 0.3), wy, px + 0.32, 1.05) : sailboat(k, -(qz + out - 0.3), wy, px + 0.32, r)));
    for (const sx of [-0.3, 0.3]) lakeLamp(k, 'victorian', sx * L, 0.012, hz + hd / 2 + 0.5);
    // people on the shore path
    k.tagged(Vis.NotWinter, () => { for (let i = 0; i < 2; i++) stroller(k, r, -L / 2 + 0.6 + r() * (L - 1.2), 0.016, qz - 0.14); });
  });
};
const FLOWERS_ = [0xe2412f, 0xf2c14e, 0xe85a9a, 0xf4f2ec].map(hex);
const pickOf = (r: Rng, a: number[]) => a[Math.floor(r() * a.length)];

// ---- the grand hotel ----------------------------------------------------------------------------

const grandHotel: Draw = (k, W, D, b, r) => {
  const floors = Math.max(3, b.floors), w = W - 0.24, d = Math.min(D - 0.5, 1.2), z = -0.1, H = floors * FLOOR + 0.08;
  if (curArch === 'leman') {
    // a belle époque palace on the quay (the Beau-Rivage, the Montreux Palace): cream stucco, an iron balcony along
    // every floor, the mansard and its dormers, a domed pavilion at each end and one in the middle, the flags
    const wall = hex(pickOf(r, [0xf2e8d0, 0xf0e2c8, 0xf4e6dc])), roofC = hex(0x5e6870), trim = hex(0xfaf6ec);
    k.box(0, 0, z, w, H, d, wall);
    k.box(0, 0, z, w + 0.02, FLOOR, d + 0.02, scale(wall, 0.92));
    k.box(0, H, z, w + 0.04, 0.04, d + 0.04, trim);
    k.box(0, H + 0.04, z, w - 0.02, 0.2, d - 0.06, roofC);
    k.hip(0, H + 0.24, z, w - 0.06, 0.08, d - 0.1, roofC);
    const bays = Math.max(6, Math.round(w / 0.24));
    for (let f = 0; f < floors; f++) for (let i = 0; i < bays; i++) {
      const x = -w / 2 + (w * (i + 0.5)) / bays;
      win(k, b, r, x, 0.06 + f * FLOOR, z + d / 2, 0.1, f ? 0.15 : 0.18, 1);
      if (f) k.box(x, f * FLOOR + 0.04, z + d / 2 + 0.03, 0.15, 0.04, 0.05, IRON);
    }
    for (let i = 0; i < bays; i += 2) { const x = -w / 2 + (w * (i + 0.5)) / bays; k.box(x, H + 0.1, z + d / 2 - 0.02, 0.08, 0.09, 0.05, trim); }
    for (const px of [-w / 2 + 0.2, 0, w / 2 - 0.2]) {
      const pw = px === 0 ? 0.55 : 0.4;
      k.box(px, 0, z + 0.02, pw, H + 0.16, d + 0.06, wall);
      k.box(px, H + 0.16, z + 0.02, pw + 0.03, 0.03, d + 0.09, trim);
      k.dome(px, H + 0.19, z + 0.02, pw * 0.45, roofC, 10, 3);
      k.cyl(px, H + 0.19 + pw * 0.45, z + 0.02, 0.006, 0.18, IRON, 4);
      if (px !== 0) flagpole(k, px, H + 0.19 + pw * 0.45 + 0.02, z + 0.02, 0.2, [], true);
    }
    // the ground-floor awnings and the lakeside terrace with its tables
    for (let i = 0; i < bays; i++) k.box(-w / 2 + (w * (i + 0.5)) / bays, FLOOR - 0.04, z + d / 2 + 0.06, 0.18, 0.012, 0.12, hex(0x2f5a3a));
    k.box(0, 0, z + d / 2 + 0.3, w, 0.02, 0.36, STONE);
    k.tagged(Vis.Summer, () => { for (let i = 0; i < 4; i++) umbrella(k, -w / 2 + 0.4 + i * ((w - 0.8) / 3), 0.02, z + d / 2 + 0.32, hex(0xf4f2ec)); });
    for (const sx of [-1, 1]) k.box(sx * 0.18, 0.02, z + d / 2 + 0.48, 0.04, 0.06, 0.04, hex(0x3f6a34));
    return;
  }
  // (an Adriatic town's hotel draws this one too, in 0.7.0: render/buildings/models070.ts)
  if (curArch === 'como' || curArch === 'adriatic') {
    // Villa d'Este, the Serbelloni: a long villa-hotel in yellow or cream under a low terracotta hip, green shutters,
    // a balustraded terrace on the lake with its stair down, palms and cypress
    const wall = hex(pickOf(r, [0xf2cf78, 0xf4e2b8, 0xeec08a])), roofC = hex(0xb85a36), trim = hex(0xf6f0e2);
    k.box(0, 0, z, w, H, d, wall);
    k.box(0, 0, z, w + 0.02, 0.06, d + 0.02, trim);
    k.box(0, H - 0.04, z, w + 0.06, 0.05, d + 0.06, trim);
    k.hip(0, H + 0.01, z, w + 0.14, 0.24, d + 0.14, roofC);
    const bays = Math.max(6, Math.round(w / 0.26));
    for (let f = 0; f < floors; f++) for (let i = 0; i < bays; i++) win(k, b, r, -w / 2 + (w * (i + 0.5)) / bays, 0.06 + f * FLOOR, z + d / 2, 0.1, 0.15, 1);
    // the middle three bays: a portico of arches under a pediment
    k.box(0, 0, z + d / 2 + 0.05, 0.6, FLOOR + 0.06, 0.1, trim);
    k.gable(0, H, z + d / 2 + 0.02, 0.62, 0.16, 0.06, roofC, trim, true);
    k.box(0, 0, z + d / 2 + 0.3, w + 0.1, 0.06, 0.4, STONE);
    for (let i = 0; i <= 14; i++) k.cyl(-w / 2 + (w * i) / 14, 0.06, z + d / 2 + 0.49, 0.012, 0.06, WHITE, 4);
    k.box(0, 0.12, z + d / 2 + 0.49, w + 0.1, 0.015, 0.03, WHITE);
    for (const sx of [-1, 1]) { lakePalm(k, sx * (w / 2 + 0.05), 0.06, z + d / 2 + 0.35, 0.6, r); cypress(k, sx * (w / 2 - 0.25), 0.06, z - d / 2 - 0.1, 0.9); }
    k.tagged(Vis.Summer, () => { for (let i = 0; i < 4; i++) umbrella(k, -w / 2 + 0.5 + i * ((w - 1) / 3), 0.06, z + d / 2 + 0.3, hex(0xf4f2ec)); });
    return;
  }
  // the American lakes' white wooden resort hotel (the Grand Hotel on Mackinac): white clapboard, a columned veranda
  // the whole length of the front, a green roof full of dormers, flags along the ridge, yellow awnings
  const wall = WHITE, roofC = hex(0x3f5a46), awn = hex(0xf2c14e);
  const fl = Math.min(floors, 4), Hh = fl * FLOOR + 0.06;
  k.box(0, 0, z, w, Hh, d, wall);
  k.detail(() => { for (let y = 0.05; y < Hh; y += 0.04) k.box(0, y, z + d / 2 + 0.003, w, 0.004, 0.002, hex(0xdcdad2)); });
  k.box(0, Hh, z, w + 0.06, 0.03, d + 0.06, wall);
  k.gable(0, Hh + 0.03, z, w + 0.06, 0.34, d + 0.06, roofC, wall, false);
  const bays = Math.max(7, Math.round(w / 0.22));
  for (let f = 0; f < fl; f++) for (let i = 0; i < bays; i++) win(k, b, r, -w / 2 + (w * (i + 0.5)) / bays, 0.07 + f * FLOOR, z + d / 2, 0.09, 0.14, 1);
  for (let i = 0; i < bays; i += 2) { const x = -w / 2 + (w * (i + 0.5)) / bays; k.box(x, Hh + 0.06, z + d / 4, 0.1, 0.1, 0.12, wall); k.gable(x, Hh + 0.16, z + d / 4, 0.12, 0.06, 0.14, roofC, wall, true); }
  // the veranda: a deck, the tall white columns two storeys high, its roof, the awnings over the windows above
  k.box(0, 0, z + d / 2 + 0.18, w + 0.04, 0.05, 0.36, PLANK);
  const cols = Math.max(8, Math.round(w / 0.2));
  for (let i = 0; i <= cols; i++) k.cyl(-w / 2 + (w * i) / cols, 0.05, z + d / 2 + 0.33, 0.016, FLOOR * 2 - 0.05, WHITE, 6);
  k.box(0, FLOOR * 2, z + d / 2 + 0.18, w + 0.08, 0.03, 0.4, wall);
  for (let i = 0; i < bays; i++) k.box(-w / 2 + (w * (i + 0.5)) / bays, FLOOR * 3 - 0.02, z + d / 2 + 0.04, 0.13, 0.012, 0.08, awn);
  for (const px of [-0.3, 0, 0.3]) flagHere(k, px * w, Hh + 0.33, z, 0.24);
  k.tagged(Vis.Summer, () => { for (let i = 0; i < 5; i++) { const x = -w / 2 + 0.3 + i * ((w - 0.6) / 4); k.box(x, 0.05, z + d / 2 + 0.2, 0.06, 0.04, 0.06, WHITE); } });
};

export const LAKE_SHORE_DRAW: Record<Extract<LakeKind, 'steamerPier' | 'lakeDock' | 'lakeBoathouse' | 'swimBeach' | 'lakeCottage' | 'lakeEstate' | 'grandHotel'>, Draw> = {
  steamerPier, lakeDock, lakeBoathouse, swimBeach, lakeCottage, lakeEstate, grandHotel,
};

