import type { Input } from './input';
import { LOOK_PLAYED, type TiltShift } from '../render/tiltshift';
import { PLAY_ADDRESS, PLAY_URL, recordType, type Dressing, type Mark, type Rect, type Recorder, type Shot, type Take } from './recorder';
import { POSTCARD, type CardPose } from '../../shared/postcards';
import { BORDERS, isBorder, type Border, type StampLook } from './postcardFrame';

/** The game's official subreddit: where Post to Reddit opens a new post, and what Settings links to. */
export const SUBREDDIT = 'https://www.reddit.com/r/TinyFleet/';

/**
 * The camera mode (docs/postcards.html, phase 1): C online, or the 📷 button. The HUD goes, the world
 * keeps running, and the player frames a still or a clip of whatever the camera is on: their own
 * vehicle (which they may go on driving), or anything clicked, which the camera then follows.
 *
 *   1 2     a slow 10-second zoom in, out
 *   3 4 5 6 a slow 10-second pan left, right, up, down (pressed again, stopped; it keeps going while a clip records)
 *   [ ]     the sharp band down and up the frame
 *   Tab     the frame: 16:9, 1:1, 9:16
 *   O       a slow orbit round the subject; again the other way; again stops
 *   N       the fleet's name on the mark, or not (the address stays)
 *   Space   a still
 *   Enter   a 10-second clip; held, a clip until it is let go (30 s at most); pressed again, stopped
 *   Esc, C  out (Esc while recording stops the clip)
 *
 * What is taken comes up on a card, where the player picks its border (game/postcardFrame.ts): Airmail, White
 * border or Deckle edge, each a postcard with a stamp for the place and the TinyFleet postmark, or Clean, the
 * picture with just the wordmark; the last one picked is remembered. Then Save, Post to Reddit (saves, copies the
 * link for the first comment and opens a new post on r/TinyFleet, the game's subreddit), Copy link. A clip is
 * dressed in its border by playing it through once (recorder.dress), begun as the card opens and again when the
 * border changes, so a Save straight away waits a few seconds for it.
 *
 * Online, each take is a postcard (phase 2): the server keeps where the camera stood under a short id, and
 * the clip's corner says tinyfleet…/p/k3x9q, which brings whoever opens it to the same spot. Takes within
 * POSTCARD.apart tiles of each other in one camera session share a postcard (it moves to the latest).
 */

interface PhotoHost {
  /** The town or county the camera is looking at, for the bar and the file's name. */
  place(): string;
  /** The world's hour, and real seconds to a game hour (the online clock can't be changed, so the bar says when the light is best). */
  hour(): number;
  secondsPerHour(): number;
  /** The fleet's badge and name. */
  mark(): Mark;
  say(title: string, body: string): void;
  /** Where the camera stands, for a postcard. */
  pose(): CardPose;
  /** Online: a postcard made (no `id`) or moved and retitled; its id, or null and why. Offline: always null. */
  postcard(pose: CardPose | null, title: string | null, id?: string): Promise<{ id: string | null; why?: string }>;
  /** A postcard's link, in full; null offline. */
  link(id: string): string | null;
  /** A postcard's picture, its link's preview (base64 JPEG). */
  picture(id: string, jpg: string): void;
  /** The postage stamp for where the camera is looking (game/stampLooks.ts). */
  stamp(): StampLook;
}

/** The camera's one look: the miniature tilt-shift (the postcard's pose still records it as look 1). */
const LOOK = { band: 0.06, saturation: 1.3, vignette: 0.55 };
const LOOK_ID = 1;
/** The slow moves: a zoom (the camera's distance halved or doubled) or a pan across the ground, each over MOVE_SECS. */
type MoveKey = 'zin' | 'zout' | 'pl' | 'pr' | 'pu' | 'pd';
const MOVES: { k: MoveKey; label: string; key: string }[] = [
  { k: 'zin', label: 'Zoom in', key: '1' }, { k: 'zout', label: 'Zoom out', key: '2' },
  { k: 'pl', label: '←', key: '3' }, { k: 'pr', label: '→', key: '4' }, { k: 'pu', label: '↑', key: '5' }, { k: 'pd', label: '↓', key: '6' },
];
const MOVE_SECS = 10;
/** A move eases in and out: the share of it done at p (0..1) of its time. */
const ease = (p: number): number => { const q = Math.min(1, Math.max(0, p)); return q * q * (3 - 2 * q); };
const FRAMES = [{ label: '16:9', a: 16 / 9 }, { label: '1:1', a: 1 }, { label: '9:16', a: 9 / 16 }];
/** A tap of Enter records this long; held, as long as it is held, up to HOLD_MAX. */
const CLIP = 10, HOLD_MAX = 30;
/** Enter held past this is a hold. */
const HOLD_AFTER = 0.4;
/** Orbit speed in the camera's own units (90° a second): one turn in 40 s. */
const SPIN = 0.1;
/** The warm light: hours of the day when the sun is low. The sun rises at 6 and sets at 18 (render/daynight.ts). */
const GOLDEN: [number, number][] = [[5.4, 7], [17, 18.6]];
const NAME_KEY = 'tinyfleet-photo-name';
const CLEAN_KEY = 'tinyfleet-photo-clean';
const BORDER_KEY = 'tinyfleet-photo-border';

const esc = (s: string): string => s.replace(/[&<>"]/g, (c) => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;' }[c]!));
const mmss = (s: number): string => `${Math.floor(s / 60)}:${String(Math.floor(s % 60)).padStart(2, '0')}`;
const clock = (h: number): string => `${String(Math.floor(h) % 24).padStart(2, '0')}:${String(Math.floor((h % 1) * 60)).padStart(2, '0')}`;
const fileSafe = (s: string): string => s.replace(/[^\p{L}\p{N}]+/gu, '-').replace(/^-+|-+$/g, '').slice(0, 40) || 'TinyFleet';

export class PhotoMode {
  active = false;
  /** The slow move under way: which, when it started (ms), and how much of it was done last frame. */
  private move: { k: MoveKey; t0: number; done: number } | null = null;
  private frameK = 0;
  private focus = 0;
  private spinDir = 0;
  private showName = true;
  /** The clean shot: cargo and mission rings, shop and tavern rings and signs, and fleet badges are out of the picture. */
  private clean = true;
  private hold = false;
  private busy = false;
  /** The take on the card as taken, its files (one per border it has been dressed in), and the dressing under way. */
  private shot: Shot | null = null;
  private dressed = new Map<Border, Take>();
  private job: { border: Border; d: Dressing; pct: number } | null = null;
  /** The border the card shows and saves in. */
  private border: Border = 'airmail';
  /** The card's live picture: the bare clip playing, drawn dressed into the preview canvas each frame. */
  private previewVideo: HTMLVideoElement | null = null;
  private previewRaf = 0;
  /** A save or post waiting for its file. */
  private pending: 'save' | 'reddit' | null = null;
  private title = '';
  /** The border the take on the card was last saved in, and whether the link was copied for Reddit. */
  private savedAs: Border | null = null;
  private copied = false;
  /** When the take was made, for its file's name. */
  private stamp = '';
  /** This camera session's postcard and where it was taken; the one the take on the card carries, and the title it was sent with. */
  private cardId: string | null = null;
  private cardAt: { x: number; z: number } | null = null;
  private takeCard: string | null = null;
  private sentTitle = '';

  private root = document.createElement('div');
  private box = document.createElement('div');
  private bar = document.createElement('div');
  private recChip = document.createElement('div');
  private card = document.createElement('div');
  private barHtml = '';

  constructor(private recorder: Recorder, private input: Input, private post: TiltShift, private host: PhotoHost) {
    try { this.showName = localStorage.getItem(NAME_KEY) !== '0'; } catch { /* storage blocked: the name shows */ }
    try { this.clean = localStorage.getItem(CLEAN_KEY) !== '0'; } catch { /* storage blocked: the shot is clean */ }
    try { const b = localStorage.getItem(BORDER_KEY); if (isBorder(b)) this.border = b; } catch { /* storage blocked: airmail */ }
    this.root.id = 'photo-ui';
    this.root.hidden = true;
    this.box.className = 'ph-box';
    this.bar.className = 'ph-bar';
    this.recChip.className = 'ph-rec';
    this.recChip.hidden = true;
    this.card.className = 'ph-card';
    this.card.hidden = true;
    this.root.append(this.box, this.recChip, this.bar, this.card);
    document.body.append(this.root);
    this.bar.addEventListener('click', (e) => {
      const b = (e.target as HTMLElement).closest('button[data-k]') as HTMLElement | null;
      if (b) this.press(b.dataset.k!);
    });
    // the clean-shot checkbox: a real checkbox, so it reads as one
    this.bar.addEventListener('change', (e) => {
      const c = e.target as HTMLInputElement;
      if (c.dataset?.c !== 'clean') return;
      this.clean = c.checked;
      try { localStorage.setItem(CLEAN_KEY, this.clean ? '1' : '0'); } catch { /* for this visit only */ }
      c.blur();
      this.barHtml = '';
      this.drawBar();
    });
    this.card.addEventListener('click', (e) => {
      const pick = (e.target as HTMLElement).closest('button[data-b]') as HTMLElement | null;
      if (pick && isBorder(pick.dataset.b)) { this.pickBorder(pick.dataset.b); return; }
      const b = (e.target as HTMLElement).closest('button[data-a]') as HTMLElement | null;
      if (b) void this.act(b.dataset.a!);
    });
    // Tab is the frame's here, not the browser's focus
    window.addEventListener('keydown', (e) => { if (this.active && !this.cardOpen && e.code === 'Tab') e.preventDefault(); });
    window.addEventListener('resize', () => { if (this.active) this.place(); });
  }

  get cardOpen(): boolean { return !this.card.hidden; }
  /** Whether the game's markers are to be left out of the picture: the camera is up and its checkbox is ticked. */
  get hideMarkers(): boolean { return this.active && this.clean; }
  /** The orbit to add to the camera's turn this frame. */
  get spin(): number { return this.active && !this.cardOpen ? this.spinDir * SPIN : 0; }

  open(): void {
    if (this.active) return;
    this.active = true;
    this.root.hidden = false;
    document.body.classList.add('photo');
    // the badge's picture loads now, so the first take already has it
    this.recorder.setMark(this.markNow());
    this.place();
    this.barHtml = '';
  }

  close(): void {
    if (!this.active) return;
    if (this.recorder.recording >= 0) void this.recorder.stop();
    this.recorder.cancelStill();
    this.root.classList.remove('recording');
    this.closeCard();
    this.active = false;
    this.spinDir = 0;
    this.move = null;
    // the next camera session makes postcards of its own
    this.cardId = null;
    this.cardAt = null;
    this.root.hidden = true;
    this.recChip.hidden = true;
    document.body.classList.remove('photo');
    this.post.setLook(LOOK_PLAYED.saturation, LOOK_PLAYED.vignette);
  }

  /** The crop being framed, in CSS pixels: the largest of the frame's shape that fits the window, centred. */
  rect(): Rect {
    const W = window.innerWidth, H = window.innerHeight, a = FRAMES[this.frameK].a;
    const w = Math.min(W, H * a), h = w / a;
    return { x: (W - w) / 2, y: (H - h) / 2, w, h };
  }

  private place(): void {
    const r = this.rect();
    Object.assign(this.box.style, { left: `${r.x}px`, top: `${r.y}px`, width: `${r.w}px`, height: `${r.h}px` });
  }

  /** The tilt-shift as this look wants it, this frame. Called before the frame is drawn. */
  apply(): void {
    if (!this.active) return;
    this.post.setFocus(0.5 + this.focus);
    this.post.setBand(LOOK.band);
    this.post.setLook(LOOK.saturation, LOOK.vignette);
  }

  /**
   * This frame's share of the slow move: `zoom` in doublings of the camera's distance (negative in), `panX`
   * and `panY` in shares of the pan's length (right and up the screen positive). Zero when nothing moves.
   */
  step(): { zoom: number; panX: number; panY: number } {
    const m = this.active && !this.cardOpen ? this.move : null;
    if (!m) return { zoom: 0, panX: 0, panY: 0 };
    const p = (performance.now() - m.t0) / (MOVE_SECS * 1000);
    const done = ease(p), d = done - m.done;
    m.done = done;
    if (p >= 1) { this.move = null; this.barHtml = ''; }
    return {
      zoom: m.k === 'zin' ? -d : m.k === 'zout' ? d : 0,
      panX: m.k === 'pl' ? -d : m.k === 'pr' ? d : 0,
      panY: m.k === 'pu' ? d : m.k === 'pd' ? -d : 0,
    };
  }

  /** After the frame is drawn: the recorder takes it while it wants it. */
  frame(): void {
    if (this.active) this.recorder.frame(this.rect());
  }

  /** Keys, once a frame, before anything else reads them. */
  update(): void {
    if (!this.active) return;
    const inp = this.input;
    if (this.cardOpen) {
      if (inp.justPressed('Escape')) this.closeCard();
      return;
    }
    const secs = this.recorder.recording;
    if (secs >= 0) {
      // a tap of Enter records CLIP seconds; held, until it is let go
      if (!this.hold && inp.down('Enter') && inp.heldFor('Enter') > HOLD_AFTER) this.hold = true;
      if (inp.justPressed('Escape') || inp.justPressed('Enter') || inp.justPressed('NumpadEnter')
        || (this.hold && !inp.down('Enter')) || secs >= (this.hold ? HOLD_MAX : CLIP)) void this.finish();
      else this.recChip.innerHTML = `<i></i> ${mmss(secs)} <small>/ ${this.hold ? `let go to stop · ${mmss(HOLD_MAX)} at most` : mmss(CLIP)}</small>`;
      for (const [code, k] of [['Digit1', 'zin'], ['Digit2', 'zout'], ['Digit3', 'pl'], ['Digit4', 'pr'], ['Digit5', 'pu'], ['Digit6', 'pd']] as const) if (inp.justPressed(code)) this.startMove(k);
      return;
    }
    if (inp.justPressed('Escape') || inp.justPressed('KeyC')) { this.close(); return; }
    for (const [code, k] of [['Digit1', 'zin'], ['Digit2', 'zout'], ['Digit3', 'pl'], ['Digit4', 'pr'], ['Digit5', 'pu'], ['Digit6', 'pd'], ['BracketLeft', 'down'], ['BracketRight', 'up'],
      ['Tab', 'frame'], ['KeyO', 'orbit'], ['KeyN', 'name'], ['Space', 'still'], ['Enter', 'rec'], ['NumpadEnter', 'rec']] as const) {
      if (inp.justPressed(code)) this.press(k);
    }
    this.drawBar();
  }

  /** Start a slow move, or stop it if it is the one under way. */
  private startMove(k: MoveKey): void {
    this.move = this.move?.k === k ? null : { k, t0: performance.now(), done: 0 };
    this.barHtml = '';
    this.drawBar();
  }

  private press(k: string): void {
    if (MOVES.some((m) => m.k === k)) { this.startMove(k as MoveKey); return; }
    if (this.busy || this.recorder.recording >= 0) return;
    if (k === 'down') this.focus = Math.max(-0.3, this.focus - 0.04);
    else if (k === 'up') this.focus = Math.min(0.3, this.focus + 0.04);
    else if (k === 'frame') { this.frameK = (this.frameK + 1) % FRAMES.length; this.place(); }
    else if (k === 'orbit') this.spinDir = this.spinDir === 0 ? 1 : this.spinDir === 1 ? -1 : 0;
    else if (k === 'name') {
      this.showName = !this.showName;
      try { localStorage.setItem(NAME_KEY, this.showName ? '1' : '0'); } catch { /* for this visit only */ }
    } else if (k === 'still') void this.shoot();
    else if (k === 'rec') void this.record();
    else if (k === 'exit') this.close();
    this.barHtml = '';
    this.drawBar();
  }

  private markNow(): Mark {
    const m = this.host.mark();
    const url = this.takeCard ? this.host.link(this.takeCard) : null;
    return { badge: m.badge, name: this.showName ? m.name : null, address: url ? url.replace(/^https?:\/\//, '') : PLAY_ADDRESS, stamp: this.host.stamp(), place: this.host.place() };
  }

  /**
   * The postcard this take carries: the session's, moved here, when it is near; otherwise a new one, waited
   * for (a moment at most) so its link can go in the corner. Offline, or refused, the take carries the game's address.
   */
  private async ready(): Promise<void> {
    const pose = { ...this.host.pose(), look: LOOK_ID };
    this.title = this.host.place();
    if (this.cardId && this.cardAt && Math.hypot(pose.x - this.cardAt.x, pose.z - this.cardAt.z) < POSTCARD.apart) {
      void this.host.postcard(pose, null, this.cardId);
      this.takeCard = this.cardId;
      this.cardAt = { x: pose.x, z: pose.z };
    } else {
      const r = await this.host.postcard(pose, this.title);
      this.takeCard = r.id;
      if (r.id) { this.cardId = r.id; this.cardAt = { x: pose.x, z: pose.z }; this.sentTitle = this.title; }
      else if (r.why) this.host.say('Postcard', r.why);
    }
    this.recorder.setMark(this.markNow());
  }

  private async shoot(): Promise<void> {
    this.busy = true;
    await this.ready();
    if (!this.active) { this.busy = false; return; }
    const t = await this.recorder.still();
    this.busy = false;
    if (!this.active) return;
    if (t) this.showCard(t);
    else this.host.say('Camera', 'The still couldn’t be taken');
  }

  private async record(): Promise<void> {
    if (!recordType()) { this.host.say('Camera', 'This browser can’t record video: Space still takes a picture'); return; }
    this.busy = true;
    await this.ready();
    this.busy = false;
    if (!this.active) return;
    this.hold = false;
    if (!this.recorder.start(this.rect())) { this.host.say('Camera', 'Recording couldn’t start'); return; }
    this.root.classList.add('recording');
    this.recChip.hidden = false;
    this.recChip.innerHTML = '<i></i> 0:00';
  }

  private async finish(): Promise<void> {
    this.busy = true;
    this.root.classList.remove('recording');
    this.recChip.innerHTML = '<i></i> Saving…';
    const t = await this.recorder.stop();
    this.recChip.hidden = true;
    this.busy = false;
    if (!this.active) { if (t?.kind === 'clip') URL.revokeObjectURL(t.url); return; }
    if (t) this.showCard(t);
    else this.host.say('Camera', 'Nothing was recorded');
  }

  private drawBar(): void {
    const h = this.host.hour(), sph = this.host.secondsPerHour();
    const inGold = GOLDEN.some(([a, b]) => h >= a && h < b);
    let until = Infinity;
    for (const [a] of GOLDEN) until = Math.min(until, ((a - h + 24) % 24) * sph);
    const light = inGold ? '<b class="gold">golden hour now</b>' : `golden hour in ${mmss(until)}`;
    const btn = (k: string, label: string, on = false, key = '') => `<button type="button" data-k="${k}" class="${on ? 'on' : ''}" tabindex="-1">${key ? `<kbd>${key}</kbd>` : ''}${label}</button>`;
    const html = `<div class="ph-head"><b>📷 Camera</b> · ${esc(this.host.place())} · ${clock(h)} · ${light}</div>`
      + `<div class="ph-row"><span class="ph-lbl">Move</span>${MOVES.map((m) => btn(m.k, m.label, this.move?.k === m.k, m.key)).join('')}`
      + `<span class="ph-lbl">Frame</span>${btn('frame', FRAMES[this.frameK].label, false, 'Tab')}`
      + `${btn('orbit', this.spinDir === 0 ? 'Orbit' : this.spinDir > 0 ? 'Orbit ↺' : 'Orbit ↻', this.spinDir !== 0, 'O')}`
      + `${btn('name', 'Fleet name', this.showName, 'N')}`
      + `<label class="ph-check" title="Leave out cargo and mission rings, shop and tavern rings and signs, and the fleet badges over buildings and vehicles"><input type="checkbox" data-c="clean" tabindex="-1"${this.clean ? ' checked' : ''}>Hide rings, signs and badges</label></div>`
      + `<div class="ph-row">${btn('still', 'Still', false, 'Space')}${btn('rec', 'Record 10 s', false, 'Enter')}`
      + `<span class="ph-tip">hold Enter to record longer · <kbd>[</kbd> <kbd>]</kbd> move the sharp band · drag to turn · click a vehicle to follow it</span>`
      + `${btn('exit', 'Done', false, 'Esc')}</div>`;
    if (html !== this.barHtml) { this.barHtml = html; this.bar.innerHTML = html; }
  }

  // ---- the card -------------------------------------------------------------------------------------

  private fileName(): string {
    const ext = !this.shot || this.shot.kind === 'still' ? 'png' : this.shot.ext;
    const tag = this.border === 'airmail' ? '' : `-${this.border}`;
    return `TinyFleet-${fileSafe(this.title)}-${this.stamp}${tag}.${ext}`;
  }

  private showCard(shot: Shot): void {
    this.closeCard();
    // the take as its postcard's picture, in the border last chosen: what its link shows when it is posted
    if (this.takeCard) {
      let jpg = this.recorder.thumb(POSTCARD.picSide, this.border);
      for (let q = 0.6; jpg && jpg.length > POSTCARD.picMax && q > 0.3; q -= 0.12) jpg = this.recorder.thumb(POSTCARD.picSide * 0.8, this.border, q);
      if (jpg && jpg.length <= POSTCARD.picMax) this.host.picture(this.takeCard, jpg);
    }
    this.shot = shot;
    this.savedAs = null;
    const d = shot.at, two = (n: number) => String(n).padStart(2, '0');
    this.stamp = `${d.getFullYear()}${two(d.getMonth() + 1)}${two(d.getDate())}-${two(d.getHours())}${two(d.getMinutes())}${two(d.getSeconds())}`;
    const video = shot.kind === 'clip';
    const webm = video && shot.ext === 'webm' ? '<p class="ph-warn">This browser records WebM, which Reddit and X may not take. Chrome and Edge record MP4.</p>' : '';
    const borders = BORDERS.map((b) => `<button type="button" data-b="${b.k}" title="${esc(b.tip)}" class="${b.k === this.border ? 'on' : ''}">${b.label}</button>`).join('');
    this.card.innerHTML = `<div class="ph-media"><canvas class="ph-preview" width="${shot.w}" height="${shot.h}"></canvas></div>`
      + `<div class="ph-side"><label>Title<input type="text" maxlength="120" value="${esc(this.title)}"></label>`
      + `<label>Border</label><div class="ph-borders" role="group" aria-label="Border">${borders}</div>`
      + `<p class="ph-what"></p>${webm}`
      + `<button type="button" data-a="save" class="go">⬇ Save ${video ? 'video' : 'picture'}</button>`
      + `<button type="button" data-a="reddit" class="go reddit">Post to Reddit</button>`
      + `<p class="ph-hint">Opens a new post on r/TinyFleet: upload the ${video ? 'video' : 'picture'} from your downloads, then hit <b>Post</b>.</p>`
      + `<button type="button" data-a="link">Copy ${this.takeCard ? 'postcard' : 'game'} link</button>`
      + `<p class="ph-note" hidden></p>`
      + `<button type="button" data-a="close" class="quiet">Back to the camera <kbd>Esc</kbd></button></div>`;
    const field = this.card.querySelector('input')!;
    // typing a title is not driving: the keys stay in the field
    for (const ev of ['keydown', 'keyup'] as const) field.addEventListener(ev, (e) => { if ((e as KeyboardEvent).code !== 'Escape') e.stopPropagation(); });
    field.addEventListener('input', () => { this.title = field.value; });
    this.card.hidden = false;
    this.bar.hidden = true;
    this.startPreview();
    this.dressNow();
  }

  /** The card's picture, dressed in the chosen border: drawn once for a still, every frame of the bare clip as it loops. */
  private startPreview(): void {
    const shot = this.shot, c = this.card.querySelector('canvas.ph-preview') as HTMLCanvasElement | null;
    if (!shot || !c) return;
    if (shot.kind === 'still') { this.recorder.compose(c, shot.canvas, shot.w, shot.h, this.border); return; }
    const v = document.createElement('video');
    v.muted = true;
    v.loop = true;
    v.playsInline = true;
    v.src = shot.url;
    this.previewVideo = v;
    let last = -1, lastBorder: Border | null = null;
    const tick = () => {
      if (this.previewVideo !== v) return;
      if (v.readyState >= 2 && (v.currentTime !== last || lastBorder !== this.border)) {
        last = v.currentTime;
        lastBorder = this.border;
        this.recorder.compose(c, v, v.videoWidth, v.videoHeight, this.border);
      }
      this.previewRaf = requestAnimationFrame(tick);
    };
    void v.play().catch(() => { /* drawn from its first frame all the same */ });
    this.previewRaf = requestAnimationFrame(tick);
  }

  private stopPreview(): void {
    cancelAnimationFrame(this.previewRaf);
    const v = this.previewVideo;
    this.previewVideo = null;
    if (v) { v.pause(); v.removeAttribute('src'); v.load(); }
  }

  /** A border picked on the card: shown at once, remembered for the next take, and its file made. */
  private pickBorder(b: Border): void {
    if (!this.shot || b === this.border) return;
    this.border = b;
    try { localStorage.setItem(BORDER_KEY, b); } catch { /* for this visit only */ }
    for (const el of Array.from(this.card.querySelectorAll<HTMLElement>('button[data-b]'))) el.classList.toggle('on', el.dataset.b === b);
    const shot = this.shot, c = this.card.querySelector('canvas.ph-preview') as HTMLCanvasElement | null;
    if (shot.kind === 'still' && c) this.recorder.compose(c, shot.canvas, shot.w, shot.h, b);
    this.dressNow();
  }

  /** The take's file in the chosen border: kept if made already, otherwise made now (whatever was being made for another border is dropped). */
  private dressNow(): void {
    const shot = this.shot, b = this.border;
    if (!shot) return;
    if (this.dressed.has(b) || this.job?.border === b) { this.drawSave(); return; }
    this.job?.d.cancel();
    const job = { border: b, d: null as unknown as Dressing, pct: 0 };
    job.d = this.recorder.dress(shot, b, (f) => { job.pct = f; if (this.job === job) this.drawSave(); });
    this.job = job;
    void job.d.done.then((t) => {
      const current = this.job === job;
      if (current) this.job = null;
      if (this.shot !== shot) { if (t) URL.revokeObjectURL(t.url); return; }
      if (!t) {
        // dropped for another border: nothing to say; failed: say so, and nothing waits on it any more
        if (current && this.border === b && this.pending) { this.pending = null; this.note('The file couldn’t be made in that border: try another, or take it again.'); }
        this.drawSave();
        return;
      }
      this.dressed.set(b, t);
      this.drawSave();
      if (this.border === b && this.pending) {
        const p = this.pending;
        this.pending = null;
        this.save(t);
        if (p === 'save') this.note(`Saved as <b>${esc(this.fileName())}</b> in your downloads.`);
        else this.redditNote();
      }
    });
    this.drawSave();
  }

  /** The save button and the file's line, as the chosen border's file stands: ready, or being made. */
  private drawSave(): void {
    const shot = this.shot;
    if (!shot) return;
    const btn = this.card.querySelector('button[data-a="save"]') as HTMLElement | null;
    const what = this.card.querySelector('.ph-what') as HTMLElement | null;
    const t = this.dressed.get(this.border), video = shot.kind === 'clip';
    const making = !t && this.job?.border === this.border;
    if (btn) btn.textContent = making && video ? `Preparing video… ${Math.round(this.job!.pct * 100)}%` : `⬇ Save ${video ? 'video' : 'picture'}`;
    if (what) {
      const size = t ? ` · ${(t.blob.size / 1048576).toFixed(1)} MB` : '';
      what.textContent = video ? `${Math.round(shot.seconds)} s · ${shot.w}×${shot.h} · ${shot.ext.toUpperCase()}${size}` : `${shot.w}×${shot.h} · PNG${size}`;
    }
  }

  private closeCard(): void {
    this.stopPreview();
    this.job?.d.cancel();
    this.job = null;
    this.pending = null;
    // a download just started may still be reading them
    const urls = [...this.dressed.values()].map((t) => t.url);
    if (this.shot?.kind === 'clip') urls.push(this.shot.url);
    if (urls.length) setTimeout(() => urls.forEach((u) => URL.revokeObjectURL(u)), 60_000);
    this.dressed = new Map();
    this.shot = null;
    this.card.hidden = true;
    this.card.innerHTML = '';
    this.bar.hidden = false;
    (document.activeElement as HTMLElement | null)?.blur?.();
  }

  private note(html: string): void {
    const p = this.card.querySelector('.ph-note') as HTMLElement | null;
    if (p) { p.innerHTML = html; p.hidden = false; }
  }

  private save(t: Take): void {
    const a = document.createElement('a');
    a.href = t.url;
    a.download = this.fileName();
    document.body.append(a);
    a.click();
    a.remove();
    this.savedAs = this.border;
  }

  /** Where the take's link goes: its postcard, or the game. */
  private url(): string { return (this.takeCard ? this.host.link(this.takeCard) : null) ?? PLAY_URL; }

  private async copyLink(): Promise<boolean> {
    try { await navigator.clipboard.writeText(this.url()); return true; } catch { return false; }
  }

  /** What to do in the Reddit tab once the file is saved. */
  private redditNote(): void {
    const url = this.url();
    this.note(`1. In the Reddit tab, upload <b>${esc(this.fileName())}</b> from your downloads (drag it in, or click to browse).<br>`
      + `2. Hit <b>Post</b>.<br>`
      + `3. ${this.copied ? `The ${this.takeCard ? 'postcard’s' : 'game’s'} link is copied: paste it` : `Paste <b>${esc(url)}</b>`} as the first comment, so people can jump to the spot.`);
  }

  private async act(a: string): Promise<void> {
    if (a === 'close') { this.closeCard(); return; }
    if (!this.shot) return;
    // a title typed on the card is the postcard's too, once something is done with it
    const title = this.title.trim();
    if (this.takeCard && title && title !== this.sentTitle) { this.sentTitle = title; void this.host.postcard(null, title, this.takeCard); }
    const url = this.url();
    const t = this.dressed.get(this.border);
    if (a === 'save') {
      if (!t) {
        // the clip is still being put in its border: it saves itself when it is done
        this.pending = 'save';
        this.dressNow();
        this.note('Putting the video in its border: it saves to your downloads by itself in a moment.');
        return;
      }
      this.save(t);
      this.note(`Saved as <b>${esc(this.fileName())}</b> in your downloads.`);
    } else if (a === 'link') {
      const ok = await this.copyLink();
      this.note(ok ? `Copied: <b>${esc(url)}</b>` : `Couldn’t copy. The link is <b>${esc(url)}</b>`);
    } else if (a === 'reddit') {
      // Reddit won't take a file handed over by another site: the player drags the saved one in, and the
      // game's link goes in the first comment, since a video post carries no link of its own. The new tab opens
      // now, while the click still counts, even if the file is a moment from ready.
      if (t && this.savedAs !== this.border) this.save(t);
      this.copied = await this.copyLink();
      window.open(`${SUBREDDIT}submit?type=IMAGE&title=${encodeURIComponent(this.title.trim() || 'TinyFleet')}`, '_blank', 'noopener');
      if (t) { this.redditNote(); return; }
      this.pending = 'reddit';
      this.dressNow();
      this.note('Putting the video in its border: it saves to your downloads by itself in a moment, and the steps for Reddit show here.');
    }
  }
}
