import { FACTIONS, type FactionId } from './factions/factions';
import type { CargoLook } from '../render/cargoMarkers';

/**
 * What colour a load is on the ground (docs/cargolook.html, the user, 22 Oct 2026): who it is for, not what
 * it is. Worked out top rule first, the first that fits:
 *   1. the vehicle being driven can't carry it: a very dull grey (render/cargoMarkers setCargoMarkerGrey, live);
 *   2. a mission's load (town requests too): yellow, the route arrows' yellow, with its thread or chain's
 *      own colour as a badge over the gem;
 *   3. a cultural good, on its way to the HQ: royal violet;
 *   3½. long-haul work (five counties or more, $5,000 and up): gold banded in black, with a pillar of light over it;
 *   3¾. Ultra-Bulk work (50–100 units, for the four biggest holds): lime banded in black, a black hazard halo
 *       turning round the ring and the load drawn outsized;
 *   4. it raises a faction's standing: the colour of the faction it raises most (reputation.favours);
 *   5. it raises nobody's: plain white.
 * Yellow means a path or a mission and nothing else.
 */

/** Missions and paths (render/routeArrows.ts draws the routes in it already). */
export const MISSION_YELLOW = 0xffd24a;
/** Every cultural good, whatever it is. */
export const CULTURE_VIOLET = 0xbe4af2;
/** Loads that move nobody's standing. */
export const NO_FACTION_WHITE = 0xffffff;
/** Long-haul work (game/cargo.ts LONG_HAUL): deeper than mission yellow, with a dark rim and a beacon, so it can't be taken for one. */
export const LONG_HAUL_GOLD = 0xffa514;
const LONG_HAUL_RIM = 0x2a1a04;
/** Ultra-Bulk work (game/cargo.ts ULTRA_BULK): hazard lime on black, no faction's colour and no destination's green. */
export const ULTRA_LIME = 0xb4f20a;
const ULTRA_RIM = 0x101408;

/**
 * Each faction's look on the ground: six bright colours, the Ministry's light grey, the Press white banded in
 * black like print, and the Family and the Army kept dark with a glowing rim (`edge`) so they show at night.
 * Only for cargo: crests, paint and cards keep FACTIONS' own colours.
 */
export const FACTION_LOOK: Record<FactionId, { color: number; edge?: number }> = {
  police: { color: 0x146df0 },
  post: { color: 0xfd1a44 },
  unions: { color: 0xfe993b },
  press: { color: 0xffffff, edge: 0x15161a },
  visitors: { color: 0x39f9ce },
  guild: { color: 0x36b7f2 },
  ministry: { color: 0xc4c9ce },
  studios: { color: 0xf23795 },
  family: { color: 0x15161a, edge: 0xd9b34a },
  army: { color: 0x4b5320, edge: 0xc9b98a },
};

const lum = (c: number) => 0.299 * ((c >> 16) & 255) + 0.587 * ((c >> 8) & 255) + 0.114 * (c & 255);

/** The colour a faction's loads read as in text (a price tag): the brighter of its colour and its rim. */
export function factionInk(f: FactionId): number {
  const l = FACTION_LOOK[f];
  return l.edge !== undefined && lum(l.edge) > lum(l.color) ? l.edge : l.color;
}

/** What a load is, as far as its colour goes. */
interface LookOf {
  /** A mission's or a town request's step: its thread's or chain's own colour, for the badge. */
  chainColour?: number;
  /** A cultural good. */
  culture?: boolean;
  /** Long-haul work. */
  longHaul?: boolean;
  /** Ultra-Bulk work. */
  ultra?: boolean;
  /** Who delivering it would please most now (and cost, in a contest). */
  favours?: { f: FactionId; loses?: FactionId } | null;
}

/** A load's look on the ground (rules 2–5; rule 1, the dull grey, is applied live by the marker). */
export function cargoLook(it: LookOf): CargoLook & { key: string; faction?: FactionId; loses?: FactionId } {
  if (it.chainColour !== undefined) return { color: MISSION_YELLOW, badge: it.chainColour, key: `m${it.chainColour}` };
  if (it.culture) return { color: CULTURE_VIOLET, key: 'c' };
  if (it.longHaul) return { color: LONG_HAUL_GOLD, edge: LONG_HAUL_RIM, beacon: true, key: 'L' };
  if (it.ultra) return { color: ULTRA_LIME, edge: ULTRA_RIM, halo: true, key: 'U' };
  const fav = it.favours;
  if (fav) return { ...FACTION_LOOK[fav.f], key: `f${fav.f}${fav.loses ? `-${fav.loses}` : ''}`, faction: fav.f, ...(fav.loses ? { loses: fav.loses } : {}) };
  return { color: NO_FACTION_WHITE, key: 'w' };
}

/** "📯 " before a load's price when it pleases a faction, and " −🎩" after it when a contest costs another. */
export function tagMarks(look: { faction?: FactionId; loses?: FactionId }): { pre: string; post: string } {
  return { pre: look.faction ? `${FACTIONS[look.faction].icon} ` : '', post: look.loses ? ` −${FACTIONS[look.loses].icon}` : '' };
}
