import { hex, scale, type RGB } from '../../world/biomes';
import type { Rng } from '../../world/rng';
import type { Sched } from '../nightLights';
import type { Kit, P3 } from './kit';

/**
 * Osaka's giant shop signs, the ones Dōtonbori is known for: a crab working its legs over a crab restaurant,
 * a puffer fish blown up into a lantern, an octopus in a headband over a takoyaki counter, a dragon coiled
 * across a ramen shop's front and a hand holding out a piece of sushi. Each is drawn on a front facing +z, its
 * middle at (x, y) on the wall at z, `s` across. The `osaka` style hangs one on about a third of its street
 * buildings (StyleSpec.bigSigns, kit.ts styleDress), and the Dōtonbori lot (osaka.ts) hangs them over its canal.
 *
 * Nothing here imports kit.ts's values (only its types), so kit.ts can call it without an import cycle.
 */

type BigSign = 'crab' | 'fugu' | 'octopus' | 'dragon' | 'sushi';
const BIG_SIGNS: readonly BigSign[] = ['crab', 'fugu', 'octopus', 'dragon', 'sushi'];

const SIGN_HOURS: Sched = [17, 30.5, 1.35], ALL_DAY: Sched = [0, 36, 1.4];
const BRACKET = hex(0x2a2c30), EYE_WHITE = hex(0xf6f4ee), PUPIL = hex(0x16161a), GOLD = hex(0xe0b040);
const CRAB = hex(0xd8382a), CRAB_DARK = hex(0xa82a20), FUGU = hex(0xf0dc8a), FUGU_SPOT = hex(0x6a5a3a), FUGU_BELLY = hex(0xfaf4e0);
const OCTO = hex(0xe0483a), OCTO_DARK = hex(0xb83428), BAND = hex(0xf4f2ec), DRAGON = hex(0x3a9a4a), DRAGON_DARK = hex(0x2a7036);
const MANE = hex(0xd8302a), SKIN = hex(0xf0c8a0), SLEEVE = hex(0x2f4a8a), RICE = hex(0xf6f4ec), SALMON = hex(0xf08a5a), BALL = hex(0xb07a3a);

/** A round body built up of stacked drums, profile [radius, height] pairs from the bottom, all times s. */
function roundBody(k: Kit, x: number, y: number, z: number, s: number, prof: readonly [number, number][], col: RGB, seg = 10): void {
  for (let i = 0; i + 1 < prof.length; i++) {
    const r = Math.max(prof[i][0], prof[i + 1][0]);
    k.cyl(x, y + prof[i][1] * s, z, r * s, (prof[i + 1][1] - prof[i][1]) * s, col, seg);
  }
}

/** A pair of googly eyes facing +z, lit after dark so the sign still looks at you. */
function eyes(k: Kit, x: number, y: number, z: number, apart: number, size: number): void {
  for (const sx of [-1, 1]) {
    k.glowBox(x + sx * apart, y, z, size, size, size * 0.5, EYE_WHITE, SIGN_HOURS, hex(0xffffff));
    k.box(x + sx * apart, y + size * 0.25, z + size * 0.26, size * 0.45, size * 0.45, size * 0.06, PUPIL);
  }
}

function crab(k: Kit, x: number, y: number, z: number, s: number): void {
  k.box(x, y - 0.2 * s, z + 0.01, 0.5 * s, 0.4 * s, 0.02, BRACKET);
  // the shell, its eyes up on their stalks
  k.box(x, y - 0.12 * s, z + 0.11 * s, 0.5 * s, 0.22 * s, 0.2 * s, CRAB);
  k.box(x, y + 0.1 * s, z + 0.11 * s, 0.4 * s, 0.05 * s, 0.15 * s, CRAB_DARK);
  for (const sx of [-1, 1]) k.box(x + sx * 0.07 * s, y + 0.1 * s, z + 0.18 * s, 0.025 * s, 0.09 * s, 0.025 * s, CRAB);
  eyes(k, x, y + 0.19 * s, z + 0.18 * s, 0.07 * s, 0.05 * s);
  // four legs a side, bent at the knee, splayed out over the wall
  for (const sx of [-1, 1]) {
    for (let j = 0; j < 4; j++) {
      const th = -0.75 + j * 0.42;
      const hip: P3 = [x + sx * 0.24 * s, y - 0.08 * s + j * 0.035 * s, z + 0.1 * s];
      const knee: P3 = [hip[0] + sx * 0.22 * s * Math.cos(th), hip[1] + 0.22 * s * Math.sin(th) + 0.08 * s, z + 0.15 * s];
      const foot: P3 = [knee[0] + sx * 0.15 * s, knee[1] - 0.2 * s, z + 0.1 * s];
      k.bar(hip, knee, 0.022 * s, CRAB);
      k.bar(knee, foot, 0.017 * s, CRAB_DARK);
    }
    // and the claws, held up in front
    const arm0: P3 = [x + sx * 0.12 * s, y - 0.04 * s, z + 0.2 * s], arm1: P3 = [x + sx * 0.2 * s, y + 0.17 * s, z + 0.32 * s];
    k.bar(arm0, arm1, 0.03 * s, CRAB);
    k.box(arm1[0], arm1[1], arm1[2], 0.11 * s, 0.12 * s, 0.08 * s, CRAB);
    k.box(arm1[0] + sx * 0.035 * s, arm1[1] + 0.12 * s, arm1[2], 0.04 * s, 0.09 * s, 0.05 * s, CRAB_DARK);
    k.box(arm1[0] - sx * 0.03 * s, arm1[1] + 0.12 * s, arm1[2], 0.035 * s, 0.06 * s, 0.05 * s, CRAB);
  }
}

function fugu(k: Kit, x: number, y: number, z: number, s: number): void {
  // hung out from the wall on a bracket like a lantern
  const fz = z + 0.32 * s;
  k.bar([x, y + 0.34 * s, z], [x, y + 0.34 * s, fz], 0.014 * s, BRACKET);
  k.box(x, y + 0.2 * s, fz, 0.012 * s, 0.14 * s, 0.012 * s, BRACKET);
  roundBody(k, x, y, fz, s, [[0.07, -0.21], [0.15, -0.16], [0.2, -0.08], [0.21, 0.02], [0.18, 0.11], [0.1, 0.18], [0.03, 0.21]], FUGU, 12);
  k.cyl(x, y - 0.17 * s, fz + 0.02 * s, 0.13 * s, 0.1 * s, FUGU_BELLY, 10);
  // the spots and the prickles, the fins, the pursed mouth and the eyes
  for (let i = 0; i < 10; i++) {
    const a = (i / 10) * Math.PI * 2, rr = 0.205 * s;
    k.box(x + Math.cos(a) * rr, y + (i % 2 ? 0.05 : -0.04) * s, fz + Math.sin(a) * rr, 0.035 * s, 0.035 * s, 0.035 * s, FUGU_SPOT);
  }
  for (const sx of [-1, 1]) k.box(x + sx * 0.23 * s, y - 0.04 * s, fz, 0.06 * s, 0.1 * s, 0.02 * s, scale(FUGU, 0.85));
  k.box(x, y + 0.08 * s, fz - 0.24 * s, 0.03 * s, 0.14 * s, 0.1 * s, scale(FUGU, 0.85));
  k.box(x, y - 0.08 * s, fz + 0.2 * s, 0.07 * s, 0.05 * s, 0.05 * s, hex(0xd87a5a));
  eyes(k, x, y + 0.04 * s, fz + 0.17 * s, 0.08 * s, 0.07 * s);
  // lit from inside after dark: a warm glow under the belly
  k.glowBox(x, y - 0.22 * s, fz, 0.1 * s, 0.02 * s, 0.1 * s, FUGU_BELLY, SIGN_HOURS, hex(0xffe8a0));
}

function octopus(k: Kit, x: number, y: number, z: number, s: number): void {
  const oz = z + 0.22 * s;
  k.box(x, y - 0.1 * s, z + 0.01, 0.4 * s, 0.4 * s, 0.02, BRACKET);
  roundBody(k, x, y, oz, s, [[0.12, -0.04], [0.18, 0.02], [0.2, 0.12], [0.18, 0.22], [0.12, 0.3], [0.04, 0.34]], OCTO, 12);
  // the headband, knotted at the side
  k.cyl(x, y + 0.08 * s, oz, 0.205 * s, 0.05 * s, BAND, 12);
  k.box(x + 0.2 * s, y + 0.08 * s, oz, 0.06 * s, 0.07 * s, 0.05 * s, MANE);
  eyes(k, x, y + 0.0, oz + 0.17 * s, 0.08 * s, 0.07 * s);
  k.bar([x, y - 0.07 * s, oz + 0.15 * s], [x, y - 0.09 * s, oz + 0.25 * s], 0.035 * s, OCTO_DARK);
  // eight arms curling out under it
  for (let i = 0; i < 8; i++) {
    const a = -Math.PI + 0.25 + (i * (Math.PI - 0.5)) / 7, curl = i < 4 ? -0.9 : 0.9;
    const p0: P3 = [x + 0.1 * s * Math.cos(a), y - 0.06 * s + 0.08 * s * Math.sin(a), oz + 0.08 * s];
    const p1: P3 = [p0[0] + 0.18 * s * Math.cos(a), p0[1] + 0.16 * s * Math.sin(a), oz + 0.12 * s];
    const p2: P3 = [p1[0] + 0.1 * s * Math.cos(a + curl), p1[1] + 0.1 * s * Math.sin(a + curl), oz + 0.14 * s];
    k.bar(p0, p1, 0.032 * s, OCTO);
    k.bar(p1, p2, 0.022 * s, OCTO_DARK);
  }
  // and a boat of takoyaki held up in one of them
  k.box(x + 0.3 * s, y + 0.02 * s, oz + 0.12 * s, 0.16 * s, 0.025 * s, 0.1 * s, hex(0xe8dcc0));
  for (const [bx, bz] of [[-0.04, -0.02], [0, 0.02], [0.04, -0.02]]) k.box(x + (0.3 + bx) * s, y + 0.045 * s, oz + (0.12 + bz) * s, 0.04 * s, 0.035 * s, 0.04 * s, BALL);
}

function dragon(k: Kit, x: number, y: number, z: number, s: number): void {
  // the body coiling along the front in a wave, spines along its back
  const n = 9, pts: P3[] = [];
  for (let i = 0; i <= n; i++) pts.push([x - 0.46 * s + (0.86 * s * i) / n, y + 0.11 * s * Math.sin(i * 0.95), z + 0.12 * s + 0.03 * s * Math.cos(i * 0.95)]);
  for (let i = 0; i < n; i++) {
    const rr = (0.035 + 0.025 * (i / n)) * s;
    k.bar(pts[i], pts[i + 1], rr, i % 2 ? DRAGON : DRAGON_DARK);
    k.box(pts[i][0], pts[i][1] + rr * 0.9, pts[i][2], 0.025 * s, 0.045 * s, 0.02 * s, GOLD);
  }
  // the tail's flame, and two clawed legs
  k.box(pts[0][0] - 0.04 * s, pts[0][1] - 0.02 * s, pts[0][2], 0.07 * s, 0.07 * s, 0.03 * s, MANE);
  for (const i of [3, 6]) {
    const [px, py, pz] = pts[i];
    k.bar([px, py, pz], [px + 0.03 * s, py - 0.13 * s, pz + 0.05 * s], 0.02 * s, DRAGON);
    k.box(px + 0.03 * s, py - 0.16 * s, pz + 0.06 * s, 0.06 * s, 0.03 * s, 0.04 * s, GOLD);
  }
  // the head at the far end, looking out at the street: snout, jaw, horns, whiskers, the red mane, lit eyes
  const [hx, hy, hz] = pts[n];
  k.box(hx + 0.06 * s, hy - 0.06 * s, hz + 0.02 * s, 0.17 * s, 0.13 * s, 0.15 * s, DRAGON);
  k.box(hx + 0.08 * s, hy - 0.05 * s, hz + 0.12 * s, 0.11 * s, 0.07 * s, 0.1 * s, DRAGON);
  k.box(hx + 0.08 * s, hy - 0.1 * s, hz + 0.1 * s, 0.1 * s, 0.03 * s, 0.1 * s, MANE);
  for (const sx of [-1, 1]) {
    k.bar([hx + (0.06 + sx * 0.05) * s, hy + 0.06 * s, hz], [hx + (0.04 + sx * 0.1) * s, hy + 0.18 * s, hz - 0.06 * s], 0.012 * s, GOLD);
    k.bar([hx + (0.08 + sx * 0.04) * s, hy - 0.04 * s, hz + 0.17 * s], [hx + (0.08 + sx * 0.2) * s, hy - 0.1 * s, hz + 0.2 * s], 0.006 * s, GOLD);
    k.glowBox(hx + (0.08 + sx * 0.045) * s, hy + 0.02 * s, hz + 0.095 * s, 0.035 * s, 0.025 * s, 0.01 * s, hex(0xf0d040), ALL_DAY, hex(0xffe060));
  }
  for (let i = 0; i < 4; i++) k.box(hx - 0.02 * s - i * 0.03 * s, hy + 0.02 * s - i * 0.02 * s, hz - 0.02 * s, 0.05 * s, 0.1 * s, 0.1 * s, MANE);
}

function sushi(k: Kit, x: number, y: number, z: number, s: number): void {
  // an arm in a happi coat's sleeve reaching out of the wall, the hand palm up holding out a piece of nigiri
  k.box(x - 0.22 * s, y - 0.12 * s, z + 0.1 * s, 0.26 * s, 0.2 * s, 0.2 * s, SLEEVE);
  k.box(x - 0.22 * s, y - 0.12 * s, z + 0.205 * s, 0.24 * s, 0.03 * s, 0.01 * s, BAND);
  k.box(x + 0.02 * s, y - 0.1 * s, z + 0.16 * s, 0.26 * s, 0.07 * s, 0.22 * s, SKIN);
  for (let i = 0; i < 4; i++) k.box(x + 0.17 * s, y - 0.09 * s, z + (0.08 + i * 0.05) * s, 0.06 * s, 0.1 * s, 0.04 * s, SKIN);
  k.box(x - 0.04 * s, y - 0.07 * s, z + 0.29 * s, 0.1 * s, 0.05 * s, 0.05 * s, SKIN);
  k.box(x + 0.03 * s, y - 0.03 * s, z + 0.16 * s, 0.22 * s, 0.08 * s, 0.13 * s, RICE);
  k.box(x + 0.03 * s, y + 0.05 * s, z + 0.16 * s, 0.27 * s, 0.045 * s, 0.16 * s, SALMON);
  for (let i = 0; i < 3; i++) k.box(x + (-0.06 + i * 0.09) * s, y + 0.095 * s, z + 0.16 * s, 0.015 * s, 0.003 * s, 0.15 * s, hex(0xfad2b8));
  k.glowBox(x + 0.03 * s, y - 0.2 * s, z + 0.02, 0.4 * s, 0.05 * s, 0.02, scale(MANE, 0.7), SIGN_HOURS, hex(0xff5a40));
}

const DRAW_SIGN: Record<BigSign, (k: Kit, x: number, y: number, z: number, s: number) => void> = { crab, fugu, octopus, dragon, sushi };

/** One giant sign, `which` of them, its middle at (x, y) on the front at z and `s` across. */
export function bigSign(k: Kit, which: BigSign, x: number, y: number, z: number, s: number): void {
  if (k.mode === 'derelict') return;
  DRAW_SIGN[which](k, x, y, z, s);
}

/**
 * A street building's giant sign in an Osaka street (kit.ts styleDress): over the shop on its ground floor,
 * sized to its front, a kind picked from its own seed. `w` and `d` are the building's front and depth, `floor`
 * a storey's height.
 */
export function osakaDress(k: Kit, r: Rng, w: number, d: number, floors: number, floor: number): void {
  const s = Math.min(w * 0.9, floors * floor * 0.95, 1.1);
  if (s < 0.4) return;
  bigSign(k, BIG_SIGNS[Math.floor(r() * BIG_SIGNS.length)], 0, floor * 1.05 + s * 0.3, d / 2, s);
}
