import type * as THREE from 'three';
import { hex, scale, type RGB } from '../../world/biomes';
import type { PlayKind } from '../../world/playKinds';
import type { Rng } from '../../world/rng';
import type { Sched } from '../nightLights';
import { BRIGHT, DARK, METAL, SHOP_GLOW, WARM_GLOW, WHITE, WOOD, pick, tree, type Draw, type Kit, type P3 } from './kit';

/**
 * The go-kart track and the archery range (world/playKinds.ts). Both are lawn lots with something
 * going on in them by day: karts racing round a twisty little circuit (one rig, each kart at its own
 * pace, passing and bunching), and archers loosing arrows that arc down the range and stick in the
 * targets. After hours the karts stand in the pit lane and the range is empty.
 */

// ---- shared bits ---------------------------------------------------------------------------------

const GRASS = hex(0x8fcf6a), GRASS_C = hex(0x86c463), HEDGE = hex(0x3f7d3a);
const ASPHALT = hex(0x4a4e54), GRAVEL = hex(0xd9c79a), TYRE = hex(0x26282b), CONCRETE = hex(0xc9c6bd);
const SKINS = [0xf1c9a5, 0xd9a982, 0xa8714a, 0x7a4e2e].map(hex);
const TOPS = [0xe2412f, 0x2f7fb5, 0xf2c14e, 0x3f9b4a, 0xf4f2ec, 0x8e5cc7, 0xf28c38, 0x2bb3a3].map(hex);
const LEGS = [0x3a4a6a, 0x2e3440, 0x5a4a3a, 0x6b6f75].map(hex);
const LAMP_GLOW = hex(0xe8e0c8);

/** A flat rectangle facing up, centred on (x, z), at height y. */
function flat(k: Kit, x: number, z: number, w: number, d: number, y: number, col: RGB): void {
  const x0 = x - w / 2, x1 = x + w / 2, z0 = z - d / 2, z1 = z + d / 2;
  k.quad([x0, y, z0], [x1, y, z0], [x1, y, z1], [x0, y, z1], col, [x, y - 1, z]);
}

/** A flat strip from one point to another, `w` wide, facing up. */
function strip(k: Kit, x0: number, z0: number, x1: number, z1: number, w: number, y: number, col: RGB): void {
  const dx = x1 - x0, dz = z1 - z0, l = Math.hypot(dx, dz) || 1, nx = (dz / l) * (w / 2), nz = (-dx / l) * (w / 2);
  k.quad([x0 + nx, y, z0 + nz], [x1 + nx, y, z1 + nz], [x1 - nx, y, z1 - nz], [x0 - nx, y, z0 - nz], col, [(x0 + x1) / 2, y - 1, (z0 + z1) / 2]);
}

/** Someone standing (or sitting, on y) at (x, z), about 0.12 tall. */
function person(k: Kit, r: Rng, x: number, y: number, z: number, sit = false): void {
  if (!sit) k.box(x, y, z, 0.03, 0.05, 0.022, LEGS[Math.floor(r() * LEGS.length)]);
  const by = y + (sit ? 0.005 : 0.05);
  k.box(x, by, z, 0.036, 0.045, 0.026, TOPS[Math.floor(r() * TOPS.length)]);
  k.box(x, by + 0.045, z, 0.026, 0.026, 0.026, SKINS[Math.floor(r() * SKINS.length)]);
}

/** Capitals and digits on a sign face, centred on (x, z): facing +z (`face` 1) or -z (-1). */
function word(k: Kit, text: string, x: number, y: number, z: number, cell: number, face: 1 | -1, col: RGB = WHITE): void {
  const n = text.length, ax = face;
  const start = x - ax * (n * cell) / 2;
  [...text].forEach((ch, i) => {
    if (ch === ' ') return;
    const xa = start + ax * (i * cell + cell * 0.06), xb = xa + ax * cell * 0.88;
    k.glyph(ch, [xa, y, z], [xb, y, z], [xb, y + cell * 0.9, z], [xa, y + cell * 0.9, z], col);
  });
}

/** A lamp post with a glowing head. */
function floodlight(k: Kit, x: number, z: number, h: number, s: Sched): void {
  k.box(x, 0, z, 0.035, h, 0.035, DARK);
  k.box(x, h, z, 0.14, 0.03, 0.05, DARK);
  k.glowBox(x, h - 0.025, z, 0.12, 0.025, 0.04, LAMP_GLOW, s, WARM_GLOW);
}

/** A low post-and-rail fence round the lot with a gate gap in the front between gx0 and gx1. */
function lotFence(k: Kit, W: number, D: number, col: RGB, gx0: number, gx1: number, h = 0.11): void {
  const hw = W / 2 - 0.07, hd = D / 2 - 0.07;
  const side = (x0: number, z0: number, x1: number, z1: number) => {
    const len = Math.hypot(x1 - x0, z1 - z0), n = Math.max(1, Math.round(len / 0.5));
    for (let i = 0; i <= n; i++) k.box(x0 + ((x1 - x0) * i) / n, 0, z0 + ((z1 - z0) * i) / n, 0.022, h, 0.022, col);
    k.bar([x0, h * 0.85, z0], [x1, h * 0.85, z1], 0.007, col);
    k.bar([x0, h * 0.45, z0], [x1, h * 0.45, z1], 0.007, col);
  };
  side(-hw, -hd, hw, -hd);
  side(-hw, -hd, -hw, hd);
  side(hw, -hd, hw, hd);
  side(-hw, hd, gx0, hd);
  side(gx1, hd, hw, hd);
}

// ---- the kart track ------------------------------------------------------------------------------

type V2 = [number, number];

/** A closed centre line, resampled to even steps: points, unit tangents and signed curvature (toward +normal). */
interface Loop { n: number; L: number; step: number; x: number[]; z: number[]; tx: number[]; tz: number[]; k: number[] }

/** Centripetal Catmull–Rom between p1 and p2 (Barry–Goldman), so uneven point spacing never loops. */
function catmull(p0: V2, p1: V2, p2: V2, p3: V2, t: number): V2 {
  const kn = (a: V2, b: V2) => Math.max(1e-3, Math.sqrt(Math.hypot(b[0] - a[0], b[1] - a[1])));
  const t1 = kn(p0, p1), t2 = t1 + kn(p1, p2), t3 = t2 + kn(p2, p3);
  const u = t1 + (t2 - t1) * t;
  const L = (a: V2, b: V2, ta: number, tb: number): V2 => {
    const f = (u - ta) / (tb - ta);
    return [a[0] + (b[0] - a[0]) * f, a[1] + (b[1] - a[1]) * f];
  };
  const A1 = L(p0, p1, 0, t1), A2 = L(p1, p2, t1, t2), A3 = L(p2, p3, t2, t3);
  return L(L(A1, A2, 0, t2), L(A2, A3, t1, t3), t1, t2);
}

function makeLoop(pts: V2[], want: number): Loop {
  const m = pts.length, dx: number[] = [], dz: number[] = [];
  for (let i = 0; i < m; i++) {
    const p0 = pts[(i - 1 + m) % m], p1 = pts[i], p2 = pts[(i + 1) % m], p3 = pts[(i + 2) % m];
    for (let j = 0; j < 16; j++) { const p = catmull(p0, p1, p2, p3, j / 16); dx.push(p[0]); dz.push(p[1]); }
  }
  const cum = [0];
  for (let i = 1; i <= dx.length; i++) {
    const a = i - 1, b = i % dx.length;
    cum.push(cum[a] + Math.hypot(dx[b] - dx[a], dz[b] - dz[a]));
  }
  const L = cum[dx.length], n = Math.max(24, Math.round(L / want)), step = L / n;
  const x: number[] = [], z: number[] = [];
  let j = 0;
  for (let i = 0; i < n; i++) {
    const s = i * step;
    while (cum[j + 1] < s) j++;
    const f = (s - cum[j]) / Math.max(1e-6, cum[j + 1] - cum[j]), b = (j + 1) % dx.length;
    x.push(dx[j] + (dx[b] - dx[j]) * f);
    z.push(dz[j] + (dz[b] - dz[j]) * f);
  }
  const tx: number[] = [], tz: number[] = [], k: number[] = [];
  for (let i = 0; i < n; i++) {
    const a = (i - 1 + n) % n, b = (i + 1) % n, ex = x[b] - x[a], ez = z[b] - z[a], l = Math.hypot(ex, ez) || 1;
    tx.push(ex / l); tz.push(ez / l);
  }
  for (let i = 0; i < n; i++) {
    const a = (i - 1 + n) % n, b = (i + 1) % n;
    // normal (tz, -tx): positive curvature turns toward it
    k.push(((tx[b] - tx[a]) * tz[i] - (tz[b] - tz[a]) * tx[i]) / (2 * step));
  }
  return { n, L, step, x, z, tx, tz, k };
}

/** Where on the loop arc length s falls: the point, its tangent, and the sample index before it. */
function along(lp: Loop, s: number): { x: number; z: number; tx: number; tz: number; i: number } {
  const ss = ((s % lp.L) + lp.L) % lp.L, f0 = ss / lp.step, i = Math.floor(f0) % lp.n, b = (i + 1) % lp.n, f = f0 - Math.floor(f0);
  const tx = lp.tx[i] + (lp.tx[b] - lp.tx[i]) * f, tz = lp.tz[i] + (lp.tz[b] - lp.tz[i]) * f, l = Math.hypot(tx, tz) || 1;
  return { x: lp.x[i] + (lp.x[b] - lp.x[i]) * f, z: lp.z[i] + (lp.z[b] - lp.z[i]) * f, tx: tx / l, tz: tz / l, i };
}

/**
 * The layouts, for a 6×4 lot, front straight along +z (by the pit lane). A: a snake of three passes, the
 * back straight with a chicane and an S through the middle. B: two left-hand hairpins stacked at one end,
 * a long hairpin into the infield and an S down the far side. Either can be flipped end for end.
 */
const LAYOUTS: V2[][] = [
  [
    [1.6, 0.85], [0.4, 0.85], [-0.8, 0.85], [-1.9, 0.8],
    [-2.38, 0.4], [-2.45, -0.4], [-2.38, -1.2],
    [-1.9, -1.58], [-1.0, -1.6], [-0.6, -1.45], [-0.25, -1.6], [0.4, -1.62], [1.4, -1.6],
    [2.05, -1.5], [2.38, -1.2], [2.2, -0.85], [1.7, -0.78],
    [0.9, -0.8], [0.0, -0.8], [-0.6, -0.75],
    [-1.05, -0.55], [-1.1, -0.2], [-0.8, 0.02],
    [-0.2, 0.08], [0.3, -0.08], [0.8, 0.1], [1.3, 0.05],
    [1.9, 0.1], [2.33, 0.4], [2.2, 0.75],
  ],
  [
    [1.6, 0.85], [0.4, 0.85], [-0.8, 0.85], [-1.8, 0.82],
    [-2.33, 0.5], [-2.2, 0.08], [-1.7, 0.0],
    [-0.8, 0.0], [0.0, 0.02], [0.55, -0.1], [0.78, -0.42], [0.5, -0.76], [-0.1, -0.8],
    [-1.0, -0.8], [-1.8, -0.82], [-2.33, -1.12], [-2.15, -1.55], [-1.6, -1.6],
    [-0.65, -1.6], [-0.3, -1.46], [0.05, -1.6], [1.2, -1.6], [2.0, -1.55],
    [2.38, -1.18], [2.38, -0.62], [2.05, -0.22], [2.05, 0.12], [2.36, 0.48], [2.15, 0.82],
  ],
];

const HALF = 0.17;
/** How the track is dressed: kerb pair, tyre accent, hut walls, roof, sign, fence. */
const KART_SCHEMES = [
  { kerb: [0xd8392b, 0xf4f2ec], tyre: 0xf4f2ec, wall: 0xf1f0ea, roof: 0xd8392b, sign: 0xd8392b, fence: 0xf4f2ec, seat: 0xd8392b },
  { kerb: [0x2f5fb5, 0xf4f2ec], tyre: 0xf2c14e, wall: 0xf6e7a8, roof: 0x2f5fb5, sign: 0x2f5fb5, fence: 0x8a8f94, seat: 0x2f5fb5 },
  { kerb: [0xd8392b, 0xf2c14e], tyre: 0xd8392b, wall: 0xdbe8c9, roof: 0x3f5a73, sign: 0x2a2d31, fence: 0xf4f2ec, seat: 0x3f9b4a },
].map((s) => ({ kerb: s.kerb.map(hex), tyre: hex(s.tyre), wall: hex(s.wall), roof: hex(s.roof), sign: hex(s.sign), fence: hex(s.fence), seat: hex(s.seat) }));

/** A go-kart facing +z, wheels on y = 0: low tray, side pods, a driver in a helmet. About 0.2 long. */
function kart(s: Kit, body: RGB, suit: RGB, helmet: RGB): void {
  for (const [x, z] of [[-0.06, 0.065], [0.06, 0.065], [-0.064, -0.07], [0.064, -0.07]]) s.box(x, 0, z, 0.026, 0.03, 0.04, TYRE);
  s.box(0, 0.01, 0, 0.1, 0.008, 0.19, DARK);
  s.box(0, 0.012, 0.085, 0.085, 0.024, 0.04, body);
  for (const x of [-0.048, 0.048]) s.box(x, 0.012, 0, 0.022, 0.02, 0.085, body);
  s.box(0, 0.012, -0.104, 0.11, 0.014, 0.012, body);
  s.box(0.032, 0.014, -0.075, 0.03, 0.03, 0.03, METAL);
  s.box(0, 0.018, -0.03, 0.046, 0.03, 0.04, DARK);
  s.box(0, 0.02, -0.012, 0.04, 0.044, 0.03, suit);
  s.box(0, 0.064, -0.012, 0.034, 0.032, 0.036, helmet);
  s.box(0, 0.07, 0.008, 0.026, 0.012, 0.006, DARK);
}

/** The cars' pace: slow in tight bends, looking a few steps ahead so they brake before them. */
function paceOf(lp: Loop): number[] {
  const f = lp.k.map((c) => Math.max(0.55, Math.min(1, 1.08 - 0.16 * Math.abs(c))));
  return f.map((_, i) => {
    let m = 1;
    for (let j = 0; j < 6; j++) m = Math.min(m, f[(i + j) % lp.n]);
    return m;
  });
}

const kartTrack: Draw = (k, W, D, _b, r) => {
  const hw = W / 2, hd = D / 2;
  const sch = KART_SCHEMES[Math.floor(r() * KART_SCHEMES.length)];
  const flip = r() < 0.5 ? 1 : -1;
  const pts = LAYOUTS[Math.floor(r() * LAYOUTS.length)].map(([x, z]) => [x * flip, z] as V2);
  const lp = makeLoop(pts, 0.09);
  const nrm = (i: number): V2 => [lp.tz[i], -lp.tx[i]];
  const off = (i: number, u: number): P3 => { const [nx, nz] = nrm(i); return [lp.x[i] + nx * u, 0, lp.z[i] + nz * u]; };
  const minDist = (x: number, z: number) => {
    let m = Infinity;
    for (let i = 0; i < lp.n; i++) m = Math.min(m, Math.hypot(lp.x[i] - x, lp.z[i] - z));
    return m;
  };
  const PZ = 1.27, inLot = (x: number, z: number) => Math.abs(x) < hw - 0.16 && Math.abs(z) < hd - 0.16 && !(z > 1.0 && Math.abs(x) < 2.25);

  // ground: mown lawn, a gravel apron at the front for the hut and the stand
  k.box(0, 0, 0, W - 0.04, 0.004, D - 0.04, GRASS, GRASS);
  flat(k, 0, (PZ + 0.12 + hd) / 2 + 0.04, W - 0.3, hd - PZ - 0.1, 0.008, GRAVEL);

  // the tarmac ribbon, gravel traps and kerbs on the bends, tyre walls round their outsides
  const Y_TAR = 0.012, Y_PAINT = 0.017;
  const tyres: V2[] = [], TYRE_GAP = 0.066;
  let prevT: V2 | null = null, carry = 0;
  for (let i = 0; i < lp.n; i++) {
    const j = (i + 1) % lp.n;
    const a = off(i, -HALF), b = off(i, HALF), c = off(j, HALF), d = off(j, -HALF);
    k.quad([a[0], Y_TAR, a[2]], [b[0], Y_TAR, b[2]], [c[0], Y_TAR, c[2]], [d[0], Y_TAR, d[2]], ASPHALT, [lp.x[i], -1, lp.z[i]]);
    const bend = Math.max(Math.abs(lp.k[i]), Math.abs(lp.k[j]));
    if (bend > 1.4) {
      const col = sch.kerb[i % 2];
      for (const sd of [-1, 1]) {
        const p = off(i, sd * HALF), q = off(i, sd * (HALF + 0.05)), s2 = off(j, sd * (HALF + 0.05)), t2 = off(j, sd * HALF);
        const y = Y_PAINT + (i % 2) * 0.0006; // each colour its own plane: they only meet at edges, and settle has less to sort
        k.quad([p[0], y, p[2]], [q[0], y, q[2]], [s2[0], y, s2[2]], [t2[0], y, t2[2]], col, [lp.x[i], -1, lp.z[i]]);
      }
    }
    if (bend > 2.0) {
      // the outside of the bend: away from the way it turns
      const out = lp.k[i] > 0 ? -1 : 1;
      const g0 = off(i, out * (HALF + 0.05)), g1 = off(i, out * (HALF + 0.21)), g2 = off(j, out * (HALF + 0.21)), g3 = off(j, out * (HALF + 0.05));
      if (inLot(g1[0], g1[2]) && inLot(g2[0], g2[2]) && minDist(g1[0], g1[2]) > HALF + 0.12 && minDist(g2[0], g2[2]) > HALF + 0.12) {
        k.quad([g0[0], 0.008, g0[2]], [g1[0], 0.008, g1[2]], [g2[0], 0.008, g2[2]], [g3[0], 0.008, g3[2]], GRAVEL, [lp.x[i], -1, lp.z[i]]);
      }
      const t = off(i, out * (HALF + 0.27));
      if (inLot(t[0], t[2]) && minDist(t[0], t[2]) > HALF + 0.2) {
        // a continuous wall: stacks every TYRE_GAP along the outside line, the gaps between samples filled in
        if (prevT) {
          const ex = t[0] - prevT[0], ez = t[2] - prevT[1], el = Math.hypot(ex, ez);
          if (el < 0.5) {
            let d = TYRE_GAP - carry;
            for (; d <= el; d += TYRE_GAP) {
              const px = prevT[0] + (ex * d) / el, pz = prevT[1] + (ez * d) / el;
              if (tyres.every(([x, z]) => Math.hypot(x - px, z - pz) > TYRE_GAP * 0.8)) tyres.push([px, pz]);
            }
            carry = el - (d - TYRE_GAP);
          }
        } else if (tyres.every(([x, z]) => Math.hypot(x - t[0], z - t[2]) > TYRE_GAP * 0.8)) { tyres.push([t[0], t[2]]); carry = 0; }
        prevT = [t[0], t[2]];
      } else prevT = null;
    } else prevT = null;
  }
  // (a lone stack where a wall barely started is dropped)
  tyres.filter(([x, z]) => tyres.some(([x2, z2]) => x2 !== x && Math.hypot(x2 - x, z2 - z) < TYRE_GAP * 1.6)).forEach(([x, z], i) => (i % 4 < 2 ? k.cyl(x, 0, z, 0.032, 0.058, TYRE, 6, scale(TYRE, 1.5)) : k.cyl(x, 0, z, 0.032, 0.052, sch.tyre, 6, TYRE)));

  // the pit lane alongside the front straight, its wall, and the slip roads at each end
  flat(k, 0, PZ, 2.9, 0.2, Y_TAR, ASPHALT);
  for (const sx of [-1, 1]) strip(k, sx * 1.45, PZ, sx * 1.95, 0.86, 0.2, Y_TAR, ASPHALT);
  k.box(0, 0, 1.12, 2.6, 0.04, 0.03, WHITE, sch.kerb[0]);
  for (let i = 0; i < 6; i++) flat(k, -1.1 + i * 0.44, PZ + 0.085, 0.22, 0.012, Y_PAINT + 0.0006, WHITE);

  // the start line: a chequered band across the straight, a gantry over it with its lights, grid slots behind
  const gx = 0.35;
  let best = 0, bd = Infinity;
  for (let i = 0; i < lp.n; i++) { const dd = Math.hypot(lp.x[i] - gx, lp.z[i] - 0.85); if (dd < bd) { bd = dd; best = i; } }
  const dirX = lp.tx[best] > 0 ? 1 : -1, lz = lp.z[best];
  for (let c = 0; c < 2; c++) {
    for (let row = 0; row < 6; row++) {
      flat(k, gx + (c - 0.5) * 0.05, lz - HALF + 0.0283 + row * 0.0567, 0.05, 0.0567, Y_PAINT + ((c + row) % 2 ? 0.0012 : 0.0006), (c + row) % 2 ? DARK : WHITE);
    }
  }
  for (let g = 0; g < 4; g++) {
    const sx = gx - dirX * (0.22 + g * 0.24), sz = lz + (g % 2 ? -0.07 : 0.07);
    flat(k, sx, sz, 0.012, 0.09, Y_PAINT + 0.0006, WHITE);
  }
  const gz0 = lz - 0.25, gz1 = lz + 0.23, gh = 0.32;
  for (const z of [gz0, gz1]) k.box(gx, 0, z, 0.03, gh, 0.03, METAL);
  k.box(gx, gh, (gz0 + gz1) / 2, 0.045, 0.05, gz1 - gz0 + 0.03, DARK);
  for (let i = 0; i < 8; i++) {
    const z = gz0 - 0.015 + ((i + 0.5) * (gz1 - gz0 + 0.03)) / 8, col = i % 2 ? DARK : WHITE;
    k.box(gx, gh + 0.05, z, 0.04, 0.035, (gz1 - gz0 + 0.03) / 8, col);
    k.box(gx, gh + 0.085, z, 0.04, 0.035, (gz1 - gz0 + 0.03) / 8, i % 2 ? WHITE : DARK);
  }
  for (let i = 0; i < 4; i++) {
    const z = (gz0 + gz1) / 2 + (i - 1.5) * 0.07;
    k.glowBox(gx + dirX * 0.026, gh + 0.01, z, 0.012, 0.03, 0.03, hex(0xb02a20), [9, 21, 1.4], hex(0xff3b30));
  }

  // the pit hut: a booth with a counter to the street, an awning and a sign on the roof
  const hx = -0.6, hz = 1.67, hwid = 0.95, hdep = 0.32, hh = 0.24;
  k.box(hx, 0, hz, hwid, hh, hdep, sch.wall);
  k.pane(hx + 0.12, 0.1, hz + hdep / 2, 0.5, 0.1, 1, hex(0x3a3f45), [17.5, 21.5, 1], SHOP_GLOW);
  k.box(hx + 0.12, 0.085, hz + hdep / 2 + 0.03, 0.56, 0.018, 0.06, WOOD);
  k.box(hx - 0.33, 0, hz + hdep / 2 + 0.003, 0.14, 0.19, 0.008, scale(sch.roof, 0.8));
  k.pane(hx - 0.1, 0.11, hz - hdep / 2, 0.55, 0.08, 3, hex(0x5f8aa3), [17.5, 21.5, 1], SHOP_GLOW);
  k.box(hx, hh, hz, hwid + 0.1, 0.03, hdep + 0.12, sch.roof, WHITE);
  // a striped awning over the counter
  for (let i = 0; i < 6; i++) {
    const x0 = hx + 0.12 - 0.3 + i * 0.1;
    const zf = hz + hdep / 2 + 0.06, z1 = zf + 0.12;
    k.quad([x0, hh - 0.005, zf], [x0 + 0.1, hh - 0.005, zf], [x0 + 0.1, hh - 0.06, z1], [x0, hh - 0.06, z1], i % 2 ? WHITE : sch.roof, [x0 + 0.05, 0, zf]);
  }
  const sw = 0.62, sy = hh + 0.03;
  for (const sx of [-0.25, 0.25]) k.box(hx + sx, sy, hz, 0.02, 0.05, 0.02, DARK);
  k.box(hx, sy + 0.05, hz, sw, 0.13, 0.03, sch.sign);
  const label = r() < 0.5 ? 'GO KARTS' : 'KARTS';
  const cell = label.length > 5 ? 0.066 : 0.09;
  word(k, label, hx, sy + 0.05 + (0.13 - cell * 0.9) / 2, hz + 0.017, cell, 1);
  word(k, label, hx, sy + 0.05 + (0.13 - cell * 0.9) / 2, hz - 0.017, cell, -1);
  // helmets on a rack by the hut, a spare kart parked at its end
  k.box(hx + 0.62, 0, hz - 0.02, 0.18, 0.1, 0.06, WOOD);
  for (let i = 0; i < 3; i++) k.box(hx + 0.56 + i * 0.06, 0.1, hz - 0.02, 0.034, 0.03, 0.036, pick(r, BRIGHT));

  // a small stand of benches facing the straight, with people on it
  const sx0 = 0.7, sx1 = 2.3, smx = (sx0 + sx1) / 2;
  for (let t = 0; t < 3; t++) {
    const z = 1.55 + t * 0.11, h = 0.035 + t * 0.04;
    k.box(smx, 0, z, sx1 - sx0, h, 0.11, CONCRETE, t % 2 ? sch.seat : scale(sch.seat, 0.85));
    const nP = 2 + Math.floor(r() * 3);
    for (let p = 0; p < nP; p++) person(k, r, sx0 + 0.1 + r() * (sx1 - sx0 - 0.2), h, z - 0.01, true);
  }
  k.bar([sx0, 0.23, 1.86], [sx1, 0.23, 1.86], 0.008, METAL);
  for (const x of [sx0, smx, sx1]) k.box(x, 0, 1.86, 0.02, 0.23, 0.02, METAL);
  // a couple watching at the pit wall end, a marshal by the gantry
  person(k, r, -1.75, 0.008, 1.5);
  person(k, r, -1.62, 0.008, 1.52);
  person(k, r, gx, 0.004, gz0 - 0.08);

  // trees in the open infield
  const spots: V2[] = [];
  for (let z = -1.6; z <= 0.9; z += 0.2) {
    for (let x = -hw + 0.4; x <= hw - 0.4; x += 0.2) if (minDist(x, z) > 0.55) spots.push([x, z]);
  }
  const trees: V2[] = [];
  for (let tries = 0; tries < 20 && trees.length < 3 && spots.length; tries++) {
    const s = spots[Math.floor(r() * spots.length)];
    if (trees.every(([x, z]) => Math.hypot(x - s[0], z - s[1]) > 0.7)) trees.push(s);
  }
  for (const [x, z] of trees) tree(k, x, 0, z, 0.55 + r() * 0.25, r() < 0.3);

  // floodlights for the evening sessions, the fence round it all
  const lit: Sched = [18, 21.5, 1.4];
  floodlight(k, -hw + 0.22, -hd + 0.22, 0.5, lit);
  floodlight(k, hw - 0.22, -hd + 0.22, 0.5, lit);
  floodlight(k, -hw + 0.22, hd - 0.4, 0.45, lit);
  lotFence(k, W, D, sch.fence, -2.3, -1.85);

  // the karts: racing round from nine till nine, otherwise lined up in the pit lane
  const nk = 4 + Math.floor(r() * 3);
  const pace = paceOf(lp);
  const cols = BRIGHT.map(hex);
  const offset = Math.floor(r() * cols.length);
  const base = Array.from({ length: nk }, () => 0.78 + r() * 0.2);
  const wob = Array.from({ length: nk }, () => [0.15 + r() * 0.25, r() * 6.3] as const);
  const sPos = Array.from({ length: nk }, (_, i) => (i * lp.L) / nk + r() * 0.4);
  const sp = base.map((v) => v * 0.7), lane = Array(nk).fill(0) as number[], laneT = Array(nk).fill(0) as number[];
  let clock = r() * 100;
  const parts = Array.from({ length: nk }, (_, i) => (s: Kit) => kart(s, cols[(i + offset) % cols.length], TOPS[Math.floor(r() * TOPS.length)], i % 3 === 0 ? WHITE : TOPS[Math.floor(r() * TOPS.length)]));
  k.rig(0, 0, 0, parts, (objs: THREE.Object3D[], dt, hour) => {
    const open = hour >= 9 && hour < 21;
    if (!open) {
      objs.forEach((o, i) => {
        o.position.set(-dirX * (-0.95 + i * 0.36), Y_TAR, PZ);
        o.rotation.y = Math.atan2(dirX, 0);
      });
      return;
    }
    clock += dt;
    for (let i = 0; i < nk; i++) {
      const here = along(lp, sPos[i]);
      let v = base[i] * (1 + 0.1 * Math.sin(clock * wob[i][0] + wob[i][1])) * pace[here.i];
      // the kart ahead, if any is close
      let gap = Infinity, lead = -1;
      for (let j = 0; j < nk; j++) {
        if (j === i) continue;
        const g = (((sPos[j] - sPos[i]) % lp.L) + lp.L) % lp.L;
        if (g < gap) { gap = g; lead = j; }
      }
      // the racing line: in toward the apex of a bend
      const apex = Math.max(-0.07, Math.min(0.07, lp.k[here.i] * 0.03));
      laneT[i] = apex;
      if (lead >= 0 && gap < 0.34) {
        const side = Math.abs(lane[i] - lane[lead]) < 0.1;
        if (v > sp[lead] + 0.02 && pace[here.i] > 0.8) laneT[i] = lane[lead] > 0 ? -0.085 : 0.085; // pull out and pass on a straight
        else if (side) v = Math.min(v, sp[lead] * (gap < 0.22 ? 0.9 : 0.99)); // stuck behind: follow
      }
      sp[i] += Math.max(-1.2 * dt, Math.min(0.6 * dt, v - sp[i]));
      sPos[i] += sp[i] * dt;
      lane[i] += Math.max(-0.22 * dt, Math.min(0.22 * dt, laneT[i] - lane[i]));
      const p = along(lp, sPos[i]);
      objs[i].position.set(p.x + p.tz * lane[i], Y_TAR, p.z - p.tx * lane[i]);
      objs[i].rotation.y = Math.atan2(p.tx, p.tz);
    }
  });
};

// ---- the archery range ---------------------------------------------------------------------------

const STRAW = hex(0xd9b85c), STRAW_TOP = hex(0xe8cb78), GOLD = hex(0xf2c81e), RED = hex(0xe0362b), BLUE = hex(0x2f8fd8);
const LANE_A = hex(0x7cc25a), LANE_B = hex(0xa8de84), BLACK = hex(0x2a2a2c), FLETCH = [0xe2412f, 0xf2c14e, 0x2bb3a3, 0xf4f2ec, 0x8e5cc7].map(hex);

/** A frame tilted back by `tilt` about x at (cx, cy, cz): u across, v up the face, w out of it (toward +z, a little up). */
type Fr = (u: number, v: number, w: number) => P3;
function tilted(cx: number, cy: number, cz: number, tilt: number): Fr {
  const c = Math.cos(tilt), s = Math.sin(tilt);
  return (u, v, w) => [cx + u, cy + v * c + w * s, cz - v * s + w * c];
}

function tbox(k: Kit, f: Fr, w: number, h: number, d: number, col: RGB, front: RGB = col): void {
  const a = w / 2, b = h / 2, c = d / 2, I = f(0, 0, 0);
  const p = (x: number, y: number, z: number) => f(x * a, y * b, z * c);
  k.quad(p(-1, -1, 1), p(1, -1, 1), p(1, 1, 1), p(-1, 1, 1), front, I);
  k.quad(p(-1, -1, -1), p(1, -1, -1), p(1, 1, -1), p(-1, 1, -1), col, I);
  k.quad(p(-1, 1, -1), p(1, 1, -1), p(1, 1, 1), p(-1, 1, 1), col, I);
  k.quad(p(-1, -1, -1), p(1, -1, -1), p(1, -1, 1), p(-1, -1, 1), col, I);
  k.quad(p(-1, -1, -1), p(-1, 1, -1), p(-1, 1, 1), p(-1, -1, 1), col, I);
  k.quad(p(1, -1, -1), p(1, 1, -1), p(1, 1, 1), p(1, -1, 1), col, I);
}

/** A round boss: a short cylinder along w. */
function tdrum(k: Kit, f: Fr, rad: number, d: number, col: RGB, seg = 10): void {
  const I = f(0, 0, 0);
  for (let i = 0; i < seg; i++) {
    const a0 = (i / seg) * Math.PI * 2, a1 = ((i + 1) / seg) * Math.PI * 2;
    const u0 = Math.cos(a0) * rad, v0 = Math.sin(a0) * rad, u1 = Math.cos(a1) * rad, v1 = Math.sin(a1) * rad;
    k.quad(f(u0, v0, -d / 2), f(u1, v1, -d / 2), f(u1, v1, d / 2), f(u0, v0, d / 2), col, I);
    k.tri(f(0, 0, d / 2), f(u0, v0, d / 2), f(u1, v1, d / 2), col, I);
    k.tri(f(0, 0, -d / 2), f(u0, v0, -d / 2), f(u1, v1, -d / 2), col, I);
  }
}

/** A flat coloured disc on the face plane w. */
function ring(k: Kit, f: Fr, rad: number, w: number, col: RGB, seg = 14): void {
  const I = f(0, 0, w - 0.05);
  for (let i = 0; i < seg; i++) {
    const a0 = (i / seg) * Math.PI * 2, a1 = ((i + 1) / seg) * Math.PI * 2;
    k.tri(f(0, 0, w), f(Math.cos(a0) * rad, Math.sin(a0) * rad, w), f(Math.cos(a1) * rad, Math.sin(a1) * rad, w), col, I);
  }
}

const TILT = 0.24, TY = 0.22;
const FACES: { rings: [number, RGB][] }[] = [
  { rings: [[0.15, WHITE], [0.12, BLACK], [0.09, BLUE], [0.06, RED], [0.03, GOLD]] }, // the coloured face
  { rings: [[0.15, BLACK], [0.112, WHITE], [0.104, BLACK], [0.06, GOLD], [0.022, BLACK]] }, // a field face
];

/** An archer side-on at the line, facing -z down the range, bow raised and drawn. */
function archer(k: Kit, r: Rng, x: number, z: number, hand: number): void {
  const coat = TOPS[Math.floor(r() * TOPS.length)];
  k.box(x, 0, z, 0.03, 0.052, 0.024, LEGS[Math.floor(r() * LEGS.length)]);
  k.box(x, 0.052, z, 0.03, 0.045, 0.036, coat);
  k.box(x, 0.097, z, 0.026, 0.026, 0.026, SKINS[Math.floor(r() * SKINS.length)]);
  const sy = 0.088, bz = z - 0.08;
  k.bar([x, sy, z - 0.012], [x, sy + 0.004, bz], 0.006, coat); // bow arm
  k.bar([x, sy, z + 0.01], [x, sy + 0.008, z - 0.012], 0.006, coat); // drawing arm at the chin
  const bow = hand ? hex(0x2a2d31) : WOOD;
  k.bar([x, sy, bz], [x, sy + 0.065, bz + 0.016], 0.005, bow);
  k.bar([x, sy, bz], [x, sy - 0.065, bz + 0.016], 0.005, bow);
  k.bar([x, sy + 0.065, bz + 0.016], [x, sy + 0.006, z - 0.01], 0.0015, WHITE);
  k.bar([x, sy - 0.065, bz + 0.016], [x, sy + 0.006, z - 0.01], 0.0015, WHITE);
  // a quiver stuck in the ground beside them
  k.cyl(x + 0.06, 0, z + 0.02, 0.012, 0.07, scale(coat, 0.7), 5);
  for (let i = 0; i < 3; i++) k.box(x + 0.055 + i * 0.005, 0.07, z + 0.015 + (i % 2) * 0.01, 0.006, 0.02, 0.006, FLETCH[i]);
}

/** An arrow along +z about its middle, 0.13 long. */
function arrow(s: Kit, fl: RGB): void {
  s.bar([0, 0, -0.065], [0, 0, 0.065], 0.0035, hex(0xc9a36a));
  s.box(0, -0.009, -0.06, 0.004, 0.018, 0.028, fl);
  s.box(0, -0.003, -0.06, 0.018, 0.006, 0.028, fl);
  s.box(0, -0.004, 0.062, 0.008, 0.008, 0.012, METAL);
}

/** A windsock along +x from its pivot, sagging a little. */
function windsock(s: Kit): void {
  const OR = hex(0xf28c38);
  s.bar([0, 0, 0], [0.065, -0.006, 0], 0.024, OR);
  s.bar([0.065, -0.006, 0], [0.125, -0.014, 0], 0.019, WHITE);
  s.bar([0.125, -0.014, 0], [0.18, -0.024, 0], 0.014, OR);
}

const hash = (a: number, b: number) => { const v = Math.sin(a * 127.1 + b * 311.7) * 43758.5453; return v - Math.floor(v); };

const archeryRange: Draw = (k, W, D, _b, r) => {
  const hw = W / 2, hd = D / 2;
  const v = r() < 0.5 ? 0 : 1;
  const n = v === 0 ? (r() < 0.6 ? 5 : 6) : (r() < 0.5 ? 4 : 6);
  const ZT = -hd + 0.52, ZL = hd - 0.86, x0 = -hw + 0.45, x1 = hw - 0.45, lw = (x1 - x0) / n;
  const laneX = (i: number) => x0 + (i + 0.5) * lw;

  // rough grass, mown lanes in two greens, the shooting line, the waiting line
  k.box(0, 0, 0, W - 0.04, 0.004, D - 0.04, GRASS_C, GRASS_C);
  for (let i = 0; i < n; i++) flat(k, laneX(i), (ZT - 0.3 + ZL + 0.05) / 2, lw, ZL + 0.05 - (ZT - 0.3), 0.008, i % 2 ? LANE_A : LANE_B);
  flat(k, 0, ZL, x1 - x0 + 0.1, 0.025, 0.012, WHITE);
  // pegs on the lane lines at ten and twenty, boards with the distances at the sides
  for (let i = 0; i <= n; i++) {
    for (const z of [ZL - 0.6, ZL - 1.2]) k.box(x0 + i * lw, 0, z, 0.025, 0.03, 0.025, WHITE);
  }
  const marks: [number, string][] = [[ZL, '30'], [ZL - 0.6, '20'], [ZL - 1.2, '10']];
  for (const [z, t] of marks) {
    for (const x of [-hw + 0.22, hw - 0.22]) {
      k.box(x, 0, z, 0.02, 0.1, 0.02, WOOD);
      k.box(x, 0.1, z, 0.13, 0.08, 0.016, WHITE);
      word(k, t, x, 0.112, z + 0.009, 0.06, 1, hex(0x2a2d31) as RGB);
    }
  }

  // the targets at the back, a lane number in front of each, and a backstop behind
  const face = FACES[v];
  const foam = pick(r, [0x3f6fb5, 0x3f9b4a, 0xd8592b]);
  const tf: Fr[] = [];
  for (let i = 0; i < n; i++) {
    const cx = laneX(i), f = tilted(cx, TY, ZT, TILT);
    tf.push(f);
    let w0: number;
    if (v === 0) {
      tbox(k, f, 0.34, 0.34, 0.08, STRAW, STRAW_TOP);
      w0 = 0.04;
      // a wooden easel: two legs in front, one behind
      for (const su of [-1, 1]) k.bar(f(su * 0.13, -0.15, 0.0), [cx + su * 0.16, 0, ZT + 0.06], 0.009, WOOD);
      k.bar(f(0, 0.1, -0.04), [cx, 0, ZT - 0.2], 0.009, WOOD);
    } else {
      tdrum(k, f, 0.17, 0.07, foam);
      w0 = 0.035;
      for (const su of [-1, 1]) k.bar(f(su * 0.12, -0.12, 0.0), [cx + su * 0.17, 0, ZT + 0.07], 0.007, DARK);
      k.bar(f(0, 0.08, -0.035), [cx, 0, ZT - 0.2], 0.007, DARK);
    }
    face.rings.forEach(([rad, col], j) => ring(k, f, rad, w0 + 0.0045 * (j + 1), col));
    // the lane number, on a little board on stakes in front of the target
    const nz = ZT + 0.3;
    k.box(cx, 0, nz, 0.015, 0.05, 0.015, WOOD);
    k.box(cx, 0.05, nz, 0.09, 0.07, 0.014, WHITE);
    word(k, String(i + 1), cx, 0.058, nz + 0.0075, 0.055, 1, hex(0x2a2d31) as RGB);
  }
  if (v === 0) {
    // straw bales behind each target
    for (let i = 0; i < n; i++) {
      for (const du of [-0.12, 0.12]) k.box(laneX(i) + du, 0, ZT - 0.3, 0.22, 0.13, 0.12, STRAW, STRAW_TOP);
      k.box(laneX(i), 0.13, ZT - 0.3, 0.22, 0.12, 0.12, STRAW, STRAW_TOP);
    }
  } else {
    // a netted backstop on poles
    const nz = ZT - 0.3;
    k.box(0, 0.03, nz, x1 - x0 + 0.2, 0.32, 0.012, hex(0x2f5a3a));
    for (let i = 0; i <= 4; i++) k.box(x0 - 0.1 + ((x1 - x0 + 0.2) * i) / 4, 0, nz - 0.02, 0.025, 0.38, 0.025, DARK);
  }

  // hedges down the sides and along the back
  k.box(0, 0, -hd + 0.08, W - 0.12, 0.11, 0.1, HEDGE);
  for (const sx of [-1, 1]) k.box(sx * (hw - 0.08), 0, -0.15, 0.1, 0.11, D - 0.62, HEDGE);

  // the shelter behind the shooting line: a concrete pad, benches, a rack of bows and arrows
  // set well back and kept low, so from above the roof never hides the archers at the line
  const zs0 = ZL + 0.45, zs1 = hd - 0.08, zsm = (zs0 + zs1) / 2, sx0 = -hw + 0.4, sx1 = hw - 0.4;
  k.box(0, 0, zsm, sx1 - sx0, 0.016, zs1 - zs0, CONCRETE);
  const nb = Math.round((sx1 - sx0) / 1.1), benches: number[] = [];
  for (let i = v; i < nb; i++) {
    const bx = sx0 + ((i + 0.5) * (sx1 - sx0)) / nb;
    benches.push(bx);
    k.box(bx, 0.016, zsm + 0.06, 0.4, 0.04, 0.07, WOOD);
  }
  const rx = sx1 - 0.35, rz = zs0 + 0.1;
  k.box(rx, 0.016, rz, 0.28, 0.012, 0.05, WOOD);
  for (const d of [-0.12, 0.12]) k.box(rx + d, 0.016, rz, 0.02, 0.15, 0.04, WOOD);
  k.box(rx, 0.15, rz, 0.28, 0.018, 0.03, WOOD);
  for (let i = 0; i < 5; i++) {
    const ax = rx - 0.1 + i * 0.05;
    k.bar([ax, 0.03, rz], [ax + 0.008, 0.2, rz - 0.01], 0.003, hex(0xc9a36a));
    k.box(ax + 0.008, 0.18, rz - 0.01, 0.006, 0.025, 0.006, FLETCH[i % FLETCH.length]);
  }
  const roofY = 0.27, backY = 0.21;
  if (v === 0) {
    // a timber lean-to, high side open to the range, a plank back wall
    const roof = pick(r, [0x4f6b4a, 0x8a4a3a, 0x5a5f6b]);
    const nPost = 5;
    for (let i = 0; i < nPost; i++) {
      const px = sx0 + 0.04 + (i * (sx1 - sx0 - 0.08)) / (nPost - 1);
      k.box(px, 0, zs0 + 0.03, 0.035, roofY, 0.035, WOOD);
    }
    k.box(0, 0, zs1 - 0.02, sx1 - sx0, backY, 0.035, scale(WOOD, 1.25));
    const e = 0.08, y0 = roofY, y1 = backY, th = 0.025;
    const a: P3 = [sx0 - e, y0, zs0 - e], b: P3 = [sx1 + e, y0, zs0 - e], c: P3 = [sx1 + e, y1, zs1 + 0.02], d: P3 = [sx0 - e, y1, zs1 + 0.02];
    const I: P3 = [0, (y0 + y1) / 2 - th / 2, zsm];
    k.quad([a[0], a[1] + th, a[2]], [b[0], b[1] + th, b[2]], [c[0], c[1] + th, c[2]], [d[0], d[1] + th, d[2]], roof, I);
    k.quad(a, b, c, d, scale(roof, 0.7), I);
    k.quad(a, b, [b[0], b[1] + th, b[2]], [a[0], a[1] + th, a[2]], scale(WOOD, 0.9), I);
    k.quad(d, c, [c[0], c[1] + th, c[2]], [d[0], d[1] + th, d[2]], scale(WOOD, 0.9), I);
    k.quad(a, d, [d[0], d[1] + th, d[2]], [a[0], a[1] + th, a[2]], scale(WOOD, 0.9), I);
    k.quad(b, c, [c[0], c[1] + th, c[2]], [b[0], b[1] + th, b[2]], scale(WOOD, 0.9), I);
    // the club's name board along the back wall's top
    k.box(0, backY + 0.02, zs1 + 0.01, 0.9, 0.09, 0.02, hex(0x2f5a3a));
    word(k, 'ARCHERY', 0, backY + 0.035, zs1 + 0.021, 0.075, 1, hex(0xf2c14e) as RGB);
  } else {
    // a modern shelter: steel posts, a flat roof with a coloured fascia, a store room at one end
    const accent = pick(r, [0xd8392b, 0x2f7fb5, 0x2bb3a3]);
    for (let i = 0; i < 4; i++) {
      const px = sx0 + 0.04 + (i * (sx1 - sx0 - 0.08)) / 3;
      for (const z of [zs0 + 0.03, zs1 - 0.03]) k.box(px, 0, z, 0.025, roofY, 0.025, DARK);
    }
    k.box(0, roofY, zsm, sx1 - sx0 + 0.16, 0.03, zs1 - zs0 + 0.12, hex(0xe8e6e0), hex(0xd5d3cc));
    k.box(0, roofY - 0.035, zs0 - 0.06, sx1 - sx0 + 0.18, 0.07, 0.02, accent);
    k.box(-0.3, 0.016, zs1 - 0.03, sx1 - sx0 - 0.9, 0.13, 0.02, scale(accent, 0.75));
    const sr = sx0 + 0.3;
    k.box(sr, 0.016, zsm, 0.5, roofY - 0.016, zs1 - zs0 - 0.02, hex(0xcfd3d6));
    k.box(sr + 0.08, 0.016, zs0 + 0.005, 0.12, 0.2, 0.008, DARK);
    k.pane(sr - 0.12, 0.17, zs0 + 0.005, 0.14, 0.08, 3, hex(0x5f8aa3), [18, 21, 1], SHOP_GLOW);
    k.box(0.4, roofY + 0.03, zs0 - 0.04, 0.9, 0.1, 0.02, accent);
    word(k, 'ARCHERY', 0.4, roofY + 0.042, zs0 - 0.03 + 0.002, 0.075, 1);
    word(k, 'ARCHERY', 0.4, roofY + 0.042, zs0 - 0.05 - 0.002, 0.075, -1);
  }
  // a flag at one end, the windsock's pole at the back corner
  const fx = -hw + 0.22, fz = zs0 - 0.04;
  k.cyl(fx, 0, fz, 0.012, 0.5, METAL, 5);
  k.box(fx + 0.07, 0.42, fz, 0.13, 0.08, 0.006, pick(r, [0x2f5a3a, 0xd8392b, 0x2f5fb5]));
  const wx = hw - 0.22, wz = -hd + 0.24, wh = 0.46;
  k.cyl(wx, 0, wz, 0.01, wh, METAL, 5);
  // the gate in the front fence at one end
  lotFence(k, W, D, v ? hex(0x5a5f6b) : WHITE, -hw + 0.12, -hw + 0.4, 0.09);
  // a hint of woodland at the back corners
  tree(k, -hw + 0.3, 0, -hd + 0.3, 0.6, r() < 0.5);
  if (r() < 0.6) tree(k, -hw + 0.3, 0, 0.0, 0.5, false);

  // archers, shooting nine till seven; the arrows they loose; the windsock swinging in the breeze
  const lanes = Array.from({ length: n }, (_, i) => i);
  const skip = n >= 5 && r() < 0.5 ? Math.floor(r() * n) : -1;
  const at = lanes.filter((i) => i !== skip);
  const handed = r() < 0.5 ? 0 : 1;
  const people = (s: Kit) => {
    for (const i of at) archer(s, r, laneX(i) - 0.04, ZL + 0.03, (i + handed) % 2);
    // someone on a bench waiting their turn, a coach watching
    for (let i = 0; i < 2 && benches.length; i++) person(s, r, benches[(i * 2 + Math.floor(r() * 2)) % benches.length] + (r() - 0.5) * 0.25, 0.056, zsm + 0.07, true);
    person(s, r, laneX(at[0]) + 0.25, 0.004, ZL + 0.2);
  };
  const shots = at.map((i) => ({ lane: i, period: 3.4 + r() * 3, phase: r() * 10, fl: FLETCH[Math.floor(r() * FLETCH.length)] }));
  const FLY = 0.85, STICK = 1.8;
  let clock = 0, wind = r() * Math.PI * 2;
  const parts = [people, ...shots.map((sh) => (s: Kit) => arrow(s, sh.fl)), windsock];
  k.rig(0, 0, 0, parts, (objs, dt, hour) => {
    clock += dt;
    const open = hour >= 9 && hour < 19;
    objs[0].visible = open;
    shots.forEach((sh, j) => {
      const o = objs[j + 1];
      const t = clock + sh.phase, shot = Math.floor(t / sh.period), tt = t - shot * sh.period;
      if (!open || tt > FLY + STICK) { o.visible = false; return; }
      o.visible = true;
      // where this shot lands: mostly in the gold and red
      const ha = hash(sh.lane, shot) * Math.PI * 2, hr = 0.1 * Math.pow(hash(shot, sh.lane + 7), 1.6);
      const f = tf[sh.lane];
      const hit = f(Math.cos(ha) * hr, Math.sin(ha) * hr, 0.06);
      const S: P3 = [laneX(sh.lane) - 0.04, 0.095, ZL + 0.03 - 0.085];
      // aimed so the arrow's point ends up buried in the boss: its middle stops short of the face
      const gx = hit[0] - S[0], gy = hit[1] - S[1], gz = hit[2] - S[2], gl = Math.hypot(gx, gy, gz) || 1;
      const ex = gx - (gx / gl) * 0.035, ey = gy - (gy / gl) * 0.035, ez = gz - (gz / gl) * 0.035, arc = 0.11;
      const u = Math.min(1, tt / FLY);
      const vy = ey + 4 * arc * (1 - 2 * u), hz = Math.hypot(ex, ez);
      o.position.set(S[0] + ex * u, S[1] + ey * u + 4 * arc * u * (1 - u), S[2] + ez * u);
      o.rotation.order = 'YXZ';
      o.rotation.y = Math.atan2(ex, ez);
      o.rotation.x = -Math.atan2(vy, hz);
    });
    const sock = objs[objs.length - 1];
    wind += (Math.sin(clock * 0.05) * 0.02) * dt;
    sock.position.set(wx, wh - 0.01, wz);
    sock.rotation.y = wind + Math.sin(clock * 0.6) * 0.25 + Math.sin(clock * 1.9) * 0.07;
    sock.rotation.z = Math.sin(clock * 1.3) * 0.08;
  });
};

export const PLAY_A_DRAW: Partial<Record<PlayKind, Draw>> = { kartTrack, archeryRange };
