import { hex } from '../../world/biomes';
import { FACTION_INFO, FACTION_KINDS, type FactionKind } from '../../world/factionKinds';
import type { Draw } from './kit';
import { FACTION_A_DRAW } from './factionsA';
import { FACTION_B_DRAW } from './factionsB';
import { FACTION_C_DRAW } from './factionsC';

/**
 * The factions' own buildings (docs/factions.html, "New buildings"), gathered from the three files that draw
 * them: A the Constabulary, the Family, the Ministry and the Visitors; B the Brotherhood, the Post and the
 * Army; C the Studios, the Guild and the Press. A kind not drawn yet stands as a plain block.
 */
const placeholder: Draw = (k, W, D, b) => {
  const h = Math.max(0.1, FACTION_INFO[b.kind as FactionKind]?.h ?? 0.5);
  k.box(0, 0, 0, Math.max(0.4, W - 0.3), h, Math.max(0.4, D - 0.3), hex(0xd8d0c0));
};

const parts: Partial<Record<FactionKind, Draw>> = { ...FACTION_A_DRAW, ...FACTION_B_DRAW, ...FACTION_C_DRAW };

export const FACTION_DRAW = Object.fromEntries(FACTION_KINDS.map((k) => [k, parts[k] ?? placeholder])) as Record<FactionKind, Draw>;

const groupOf = (list: Partial<Record<FactionKind, Draw>>, kinds: readonly FactionKind[]): Record<string, Draw> =>
  Object.fromEntries(kinds.map((k) => [k, list[k] ?? placeholder]));

/** gallery.html?group=factions (all), factionsA|factionsB|factionsC (one file's). */
export const FACTION_GALLERY: Record<string, Record<string, Draw>> = {
  factions: FACTION_DRAW,
  factionsA: groupOf(FACTION_A_DRAW, ['highwayPatrol', 'impoundYard', 'socialClub', 'chopShop', 'bossVilla', 'embassy', 'motorPool', 'mint', 'hangar18', 'crashSite', 'landingRing', 'cropCircle']),
  factionsB: groupOf(FACTION_B_DRAW, ['unionHall', 'buildersYard', 'asphaltPlant', 'sortingOffice', 'mailDock', 'mailboxRow', 'airbase', 'armyDepot', 'checkpoint']),
  factionsC: groupOf(FACTION_C_DRAW, ['backlot', 'studioGate', 'premiereTheatre', 'starMansion', 'fishMarket', 'netLoft', 'lifeboatStation', 'guildHall', 'printworks', 'broadcastCentre', 'newsstand']),
};
