/**
 * Towing (docs/missions.html, Tows): a load too heavy for one vehicle, on ropes, dragged by two or more.
 *
 * Nothing here knows who is on the other end of a rope. A `Puller` is anything with a hitch and a pull:
 * the player's car, one of their fleet driven by its hired driver, or — later — another player's car on
 * another machine, whose hitch arrives over the wire and whose tug is sent back. The load's step reads
 * every hitch, works out each rope's tension, moves the load, and tells each puller how the rope held it.
 * `snapshot()` / `apply()` are the whole state as plain data, so whoever owns the load can share it.
 *
 * The model, in the game's own units (tiles, seconds, and "pull" — a vehicle's strength, see pullOf):
 *
 * - A rope is slack until its puller is more than ROPE tiles from the load; past that its tension rises
 *   to the puller's full pull over TAUT tiles of stretch. A puller that keeps going with the load not
 *   following is held on the rope (its speed is taken away, its tyres spin); one that jerks away hard
 *   snaps the rope.
 * - The load resists with its `need` times the ground's drag (a road least, sand and marsh most) plus
 *   the climb. It sits until the ropes between them out-pull that, then slides, turning to face the way
 *   it goes, and sideways only grudgingly.
 * - It stops dead at a wall, at water and at a bridge deck (no span in the county was built for a bell).
 */

/** Tiles of rope before it takes up, and the stretch over which it comes to full tension. */
export const ROPE = 2.6, TAUT = 0.35;
/** The most a rope stretches before it holds its puller outright. */
const HOLD_AT = 0.6;
/**
 * A rope parts when its puller keeps hauling against it: held at full stretch for SNAP_SECONDS while
 * still trying to go away faster than SNAP_SPEED (tiles a second). A pull-away that finds the rope taut
 * is only held back; flooring it for a second or more against a load that won't come is what snaps it.
 */
const SNAP_SPEED = 0.5, SNAP_SECONDS = 1.3;
/**
 * Held against a load that has stopped dead (a wall, water, a deck), still trying to go: the hold takes the
 * speed away every step, so the puller never reaches SNAP_SPEED and would be pinned for good, its controls
 * dead (the user, 29 Oct 2026). Pressing on like that parts the rope after this long instead.
 */
const STUCK_SECONDS = 4;
/** Taking a run at it: a puller that hits the end of a slack rope faster than this (tiles a second) parts it there and then. */
const JERK_SPEED = 3.2;
/** The load's top speed, and how quickly it turns to face the way it is going. */
const MAX_V = 3.2, TURN = 1.4;
/** How hard sideways sliding is resisted, per second. */
const SIDE_GRIP = 5;
/** How much the climb adds to the drag, per step of grade. */
const GRADE_DRAG = 0.22;
/** The load's radius, for walls. */
export const LOAD_R = 0.55;
/** How far its runners reach for a wall: less than a lane, so it can be dragged down a street between buildings. */
const WALL_R = 0.15;

type PullerKind = 'local' | 'fleet' | 'remote';

export interface Puller {
  id: string;
  name: string;
  kind: PullerKind;
  /** Strength, in pull. */
  pull: number;
  /** Where the rope ties on, in world tiles, and which way the vehicle faces and how fast it goes. */
  hitch(): { x: number; z: number; heading: number; v: number } | null;
  /** The rope held it: move it by (dx, dz) world tiles and keep this share of its speed. */
  tug(dx: number, dz: number, keep: number): void;
  /**
   * Where it has driven since it hitched, oldest first (world tiles; only ever added to). The load is
   * hauled along this track rather than straight at the hitch, so it follows the street round a corner
   * instead of being dragged across the inside of it into a wall.
   */
  trail?(): { x: number; z: number }[];
}

export interface Rope {
  id: string;
  on: boolean;
  /** 0..1 of the puller's pull. */
  tension: number;
  /** Seconds it has held its puller outright. */
  strain: number;
  /** How far along its puller's trail the load has come. */
  k?: number;
}

export interface Ground {
  /** The ground's drag at (x, z) world tiles: 1 on a road. Infinity where the load can't go. */
  drag(x: number, z: number): number;
  /** Height in steps (for the climb), at (x, z). */
  height(x: number, z: number): number;
  /** Why the load can't go to (x, z), or null. */
  wall(x: number, z: number): string | null;
}

interface LoadState { x: number; z: number; vx: number; vz: number; heading: number; need: number }

interface HaulSnapshot { load: LoadState; ropes: Rope[]; snaps: number; scrapes: number }

export interface StepResult { snapped: string[]; stopped: string | null; scraped: boolean }

/**
 * How strong a vehicle is on a rope: its shove off the line, its size, a trailer's weight behind it and a
 * bull bar's heft, on a scale where the Tomato pulls about 3.
 */
export function pullOf(def: { accel: number; halfLen?: number; halfWid?: number; trailer?: unknown; heft?: number; weight?: number }): number {
  const area = ((def.halfLen ?? 0.27) * (def.halfWid ?? 0.18)) / (0.27 * 0.18);
  const p = 2.1 * Math.sqrt(def.accel) * Math.sqrt(area) * (def.trailer ? 1.5 : 1) * (def.heft ?? 1) * (1 + 0.4 * (def.weight ?? 0.5));
  return Math.round(p * 10) / 10;
}

/**
 * The need for a load dragged by these pullers: more than the strongest of them can manage alone, less
 * than all of them together, so it takes a team and it takes the whole team.
 */
export function needFor(pulls: number[]): number {
  const sorted = [...pulls].sort((a, b) => b - a);
  const best = sorted[0] ?? 3, sum = sorted.reduce((s, v) => s + v, 0);
  const lo = best * 1.18, hi = sum * 0.72;
  return Math.round((lo <= hi ? Math.max(lo, hi * 0.9) : (lo + sum * 0.92) / 2) * 10) / 10;
}

export class HaulSim {
  ropes = new Map<string, Rope>();
  snaps = 0;
  scrapes = 0;

  constructor(public load: LoadState, private ground: Ground) {}

  hitch(p: Puller): void { this.ropes.set(p.id, { id: p.id, on: true, tension: 0, strain: 0 }); }
  unhitch(id: string): void { const r = this.ropes.get(id); if (r) r.on = false; }
  hitched(id: string): boolean { return !!this.ropes.get(id)?.on; }

  /** Where a rope ties onto the load: its edge, on the side toward the puller. */
  anchor(hx: number, hz: number): { x: number; z: number } {
    const dx = hx - this.load.x, dz = hz - this.load.z, d = Math.hypot(dx, dz) || 1;
    return { x: this.load.x + (dx / d) * LOAD_R, z: this.load.z + (dz / d) * LOAD_R };
  }

  /** How far along the lead's track the load has come. */
  private guideK = 0;
  private guideId = '';

  /** The way the lead's track goes from the load: toward the next point of it the load has not yet reached. */
  private guide(pullers: Puller[]): { x: number; z: number } | null {
    const L = this.load;
    const lead = pullers.find((p) => this.ropes.get(p.id)?.on && p.trail);
    const tr = lead?.trail?.();
    if (!lead || !tr || !tr.length) return null;
    if (lead.id !== this.guideId) { this.guideId = lead.id; this.guideK = 0; }
    let k = Math.min(this.guideK, tr.length - 1);
    // a crumb or two further on that the load is nearer than the one it is making for (it cut the corner): skip to it
    let best = k, bd = Math.hypot(tr[k].x - L.x, tr[k].z - L.z);
    for (let j = k + 1; j < Math.min(tr.length, k + 10); j++) { const d = Math.hypot(tr[j].x - L.x, tr[j].z - L.z); if (d < bd) { bd = d; best = j; } }
    k = best;
    // a short look along it, so it keeps to the track round a corner rather than cutting across the inside;
    // further the faster it slides, as the ropes already round the corner start swinging it before it gets
    // there — a load that came at a bend at speed overran it, off the road and down the bank beside it
    const look = 0.6 + 0.45 * Math.hypot(L.vx, L.vz);
    while (k < tr.length - 1 && Math.hypot(tr[k].x - L.x, tr[k].z - L.z) < look) k++;
    this.guideK = k;
    const q = tr[k], d = Math.hypot(q.x - L.x, q.z - L.z);
    return d > 0.2 ? { x: (q.x - L.x) / d, z: (q.z - L.z) / d } : null;
  }

  step(dt: number, pullers: Puller[]): StepResult {
    const L = this.load;
    const out: StepResult = { snapped: [], stopped: null, scraped: false };
    let fx = 0, fz = 0;
    const guide = this.guide(pullers);
    const still = Math.hypot(L.vx, L.vz) < 0.05;
    for (const p of pullers) {
      const r = this.ropes.get(p.id);
      const h = p.hitch();
      if (!r || !r.on || !h) { if (r) r.tension = 0; continue; }
      const a = this.anchor(h.x, h.z);
      const dx = h.x - a.x, dz = h.z - a.z, d = Math.hypot(dx, dz);
      const ext = d - ROPE;
      if (ext <= 0 || d < 1e-4) { r.tension = 0; r.strain = Math.max(0, r.strain - dt); continue; }
      const ux = dx / d, uz = dz / d;
      const t = Math.min(1, ext / TAUT);
      r.tension = t;
      // every rope's pull goes along the lead's track (the player's, in the game): the load follows the
      // road they drove, whatever line the helpers alongside are taking
      const g = guide ?? { x: ux, z: uz };
      fx += g.x * t * p.pull;
      fz += g.z * t * p.pull;
      if (ext > HOLD_AT) {
        // past its stretch: the puller is going somewhere the load isn't. How fast it is going away
        // decides between the rope holding it (tyres spinning) and the rope parting.
        const away = Math.sin(h.heading) * h.v * ux + Math.cos(h.heading) * h.v * uz;
        r.strain += away > SNAP_SPEED ? dt : still && away > 0.02 ? dt * (SNAP_SECONDS / STUCK_SECONDS) : -dt * 0.5;
        if (r.strain > SNAP_SECONDS || away > JERK_SPEED) {
          r.on = false;
          r.tension = 0;
          r.strain = 0;
          this.snaps++;
          out.snapped.push(p.id);
          continue;
        }
        const over = ext - HOLD_AT;
        p.tug(-ux * over, -uz * over, 0.35);
      } else r.strain = Math.max(0, r.strain - dt);
    }
    // the ground holds it back: its drag, and the climb in the way it is going (or being pulled)
    const drag = this.ground.drag(L.x, L.z);
    const sp = Math.hypot(L.vx, L.vz);
    const f = Math.hypot(fx, fz);
    const dirx = sp > 0.05 ? L.vx / sp : f > 0 ? fx / f : 0, dirz = sp > 0.05 ? L.vz / sp : f > 0 ? fz / f : 0;
    const climb = this.ground.height(L.x + dirx * 0.7, L.z + dirz * 0.7) - this.ground.height(L.x - dirx * 0.7, L.z - dirz * 0.7);
    const resist = Math.max(0, L.need * (Number.isFinite(drag) ? drag : 50) + L.need * GRADE_DRAG * (climb / 1.4));
    const mass = L.need * 0.8;
    if (sp < 0.05) {
      if (f > resist * 1.04) {
        // breaking free: it swings round to face the pull (whichever end is nearer), then gathers way
        let want = Math.atan2(fx, fz);
        if (Math.abs(wrap(want - L.heading)) > Math.PI / 2) want = wrap(want + Math.PI);
        if (sp < 0.01) L.heading = want;
        const a = (f - resist) / mass;
        L.vx += (fx / f) * a * dt;
        L.vz += (fz / f) * a * dt;
      } else { L.vx = 0; L.vz = 0; }
    } else {
      L.vx += ((fx - dirx * resist) / mass) * dt;
      L.vz += ((fz - dirz * resist) / mass) * dt;
      // it can't be dragged backwards through its own friction
      if (L.vx * dirx + L.vz * dirz < 0) { L.vx = 0; L.vz = 0; }
    }
    // sideways it slides only grudgingly: the part of its travel across its runners dies away
    const hx = Math.sin(L.heading), hz = Math.cos(L.heading);
    const fwd = L.vx * hx + L.vz * hz, side = L.vx * hz - L.vz * hx;
    const keptSide = side * Math.exp(-SIDE_GRIP * dt);
    L.vx = hx * fwd + hz * keptSide;
    L.vz = hz * fwd - hx * keptSide;
    const s2 = Math.hypot(L.vx, L.vz);
    if (s2 > MAX_V) { L.vx *= MAX_V / s2; L.vz *= MAX_V / s2; }
    // it turns to face the way it is going (either end first, whichever is nearer)
    if (s2 > 0.05) {
      let want = Math.atan2(L.vx, L.vz);
      if (Math.abs(wrap(want - L.heading)) > Math.PI / 2) want = wrap(want + Math.PI);
      L.heading += wrap(want - L.heading) * Math.min(1, dt * TURN * s2);
    }
    // move it, one axis at a time, stopping at anything it can't go into
    for (const axis of [0, 1]) {
      const d = (axis === 0 ? L.vx : L.vz) * dt;
      if (!d) continue;
      const nx = axis === 0 ? L.x + d : L.x, nz = axis === 1 ? L.z + d : L.z;
      const edge = axis === 0 ? nx + Math.sign(d) * WALL_R : nx;
      const edgeZ = axis === 1 ? nz + Math.sign(d) * WALL_R : nz;
      const why = this.ground.wall(edge, edgeZ);
      if (why) {
        if (Math.abs(axis === 0 ? L.vx : L.vz) > 0.4) { this.scrapes++; out.scraped = true; }
        if (axis === 0) L.vx = 0; else L.vz = 0;
        out.stopped = why;
        // rubbing along a wall it eases back into the middle of its lane, so it slides past a corner rather than hanging on it
        if (axis === 0) L.x += (Math.floor(L.x) + 0.5 - L.x) * Math.min(1, dt * 3);
        else L.z += (Math.floor(L.z) + 0.5 - L.z) * Math.min(1, dt * 3);
        continue;
      }
      L.x = nx;
      L.z = nz;
    }
    return out;
  }

  snapshot(): HaulSnapshot { return { load: { ...this.load }, ropes: [...this.ropes.values()].map((r) => ({ ...r })), snaps: this.snaps, scrapes: this.scrapes }; }

  apply(s: HaulSnapshot): void {
    Object.assign(this.load, s.load);
    this.ropes = new Map(s.ropes.map((r) => [r.id, { ...r }]));
    this.snaps = s.snaps;
    this.scrapes = s.scrapes;
  }
}

const wrap = (a: number) => Math.atan2(Math.sin(a), Math.cos(a));

/**
 * A puller on another machine (docs/multiplayer.html): its hitch is whatever last arrived over the wire,
 * and the tugs the rope gives it are queued to be sent back, for that machine to apply to its own car.
 * The load's owner runs `HaulSim.step` with these in the list exactly as it does with its own.
 */
class RemotePuller implements Puller {
  kind: PullerKind = 'remote';
  last: { x: number; z: number; heading: number; v: number } | null = null;
  /** Tugs to send back: move by (dx, dz), keep this share of speed. */
  outbox: { dx: number; dz: number; keep: number }[] = [];
  constructor(public id: string, public name: string, public pull: number) {}
  hitch() { return this.last; }
  tug(dx: number, dz: number, keep: number): void { this.outbox.push({ dx, dz, keep }); }
}
