/**
 * The social window (docs/social.html): what a player chooses to show on their fleet card, and the limits
 * the game and the server both hold it to. Imported by both; nothing here touches the DOM or Node.
 */

/** The most characters in a motto, and in a pronoun line. */
export const MOTTO_MAX = 60;
export const PRONOUNS_MAX = 16;
/** The most metrics a card may pin. */
export const PINS_MAX = 3;
/** The vehicles a board line lists of a fleet, and the cargo kinds it names. */
export const FLEET_LIST_MAX = 12;
export const GOODS_MAX = 8;

export const BACKDROPS = ['county', 'dusk', 'night', 'harbour', 'high', 'plain'] as const;
export const MESSAGES = ['anyone', 'known', 'nobody'] as const;
export type Messages = (typeof MESSAGES)[number];
export const JOINING = ['open', 'ask', 'invite'] as const;
export type Joining = (typeof JOINING)[number];
export const INVITERS = ['founder', 'officers', 'anyone'] as const;
export const WHERE = ['shown', 'friends', 'hidden'] as const;
export type Where = (typeof WHERE)[number];
export type Inviters = (typeof INVITERS)[number];
export type Backdrop = (typeof BACKDROPS)[number];

/**
 * How others see a fleet (the card's owner sets it; a shared fleet's founder or officer sets the fleet's
 * part). Every field is optional: a fresh fleet's card is complete without any of them.
 */
export interface Profile {
  /** A line under the fleet's name. */
  motto?: string;
  /** The vehicle turning on the card: one the fleet owns, by uid, with its model named so a sold one still shows as its model. */
  showcase?: { uid: number; model: string } | null;
  /** Metric keys (game/metrics.ts) the card shows as extra tiles. */
  pins?: string[];
  backdrop?: Backdrop;
  pronouns?: string;
  /** The card's sections: the goods moved most, the vehicles, the fleets dealt with most. All on unless said. */
  show?: { goods?: boolean; fleet?: boolean; neighbours?: boolean };
  /** Who may leave notes (phase 3): anyone, friends and neighbours, or nobody. Anyone unless said. */
  messages?: Messages;
  /** How a fleet of one is joined (a shared fleet keeps its own on its record): by asking unless said. */
  joining?: Joining;
  /** Phase 4: the building on the card's left-hand stage (a lot key of a door the fleet holds; the HQ unless said), and who sees where you are. */
  building?: string | null;
  where?: Where;
}

/** The characters a motto or a pronoun line may not carry: markup, quotes and controls (the deed names' filter). */
const STRIP = /[<>&"`\u0000-\u001f]/g;

/** A profile as sent, cleaned to what may be kept; unknown fields dropped, long ones cut, wrong ones left out. */
export function cleanProfile(x: unknown): Profile {
  const out: Profile = {};
  if (!x || typeof x !== 'object') return out;
  const p = x as Record<string, unknown>;
  if (typeof p.motto === 'string') out.motto = p.motto.replace(STRIP, '').replace(/\s+/g, ' ').trim().slice(0, MOTTO_MAX);
  if (typeof p.pronouns === 'string') out.pronouns = p.pronouns.replace(STRIP, '').replace(/\s+/g, ' ').trim().slice(0, PRONOUNS_MAX);
  if (p.showcase === null) out.showcase = null;
  else if (p.showcase && typeof p.showcase === 'object') {
    const s = p.showcase as Record<string, unknown>;
    if (typeof s.uid === 'number' && Number.isFinite(s.uid) && typeof s.model === 'string' && /^[a-z0-9_-]{1,32}$/i.test(s.model)) out.showcase = { uid: Math.round(s.uid), model: s.model };
  }
  if (Array.isArray(p.pins)) out.pins = p.pins.filter((k): k is string => typeof k === 'string' && /^[a-zA-Z]{1,16}$/.test(k)).slice(0, PINS_MAX);
  if (typeof p.backdrop === 'string' && (BACKDROPS as readonly string[]).includes(p.backdrop)) out.backdrop = p.backdrop as Backdrop;
  if (typeof p.messages === 'string' && (MESSAGES as readonly string[]).includes(p.messages)) out.messages = p.messages as Messages;
  if (typeof p.joining === 'string' && (JOINING as readonly string[]).includes(p.joining)) out.joining = p.joining as Joining;
  if (typeof p.where === 'string' && (WHERE as readonly string[]).includes(p.where)) out.where = p.where as Where;
  if (p.building === null) out.building = null;
  else if (typeof p.building === 'string' && /^-?\d{1,5},-?\d{1,5}#b\d{1,7}$/.test(p.building)) out.building = p.building;
  if (p.show && typeof p.show === 'object') {
    const s = p.show as Record<string, unknown>;
    out.show = {};
    for (const k of ['goods', 'fleet', 'neighbours'] as const) if (typeof s[k] === 'boolean') out.show[k] = s[k] as boolean;
  }
  return out;
}

/** A card's section is shown unless its owner turned it off. */
export const shows = (p: Profile | null | undefined, k: 'goods' | 'fleet' | 'neighbours'): boolean => p?.show?.[k] !== false;

/** The goods a board line names: [kind name, loads], the most carried first, as sent, cleaned. */
export function cleanGoods(x: unknown): [string, number][] | undefined {
  if (!Array.isArray(x)) return undefined;
  const out: [string, number][] = [];
  for (const e of x) {
    if (out.length >= GOODS_MAX) break;
    if (!Array.isArray(e) || typeof e[0] !== 'string' || typeof e[1] !== 'number' || !Number.isFinite(e[1])) continue;
    out.push([e[0].replace(STRIP, '').slice(0, 32), Math.max(0, Math.round(e[1]))]);
  }
  return out.length ? out : undefined;
}

/** The vehicles a board line lists: {m: model, n: name}, as sent, cleaned. */
export function cleanFleetList(x: unknown): { m: string; n: string }[] | undefined {
  if (!Array.isArray(x)) return undefined;
  const out: { m: string; n: string }[] = [];
  for (const e of x) {
    if (out.length >= FLEET_LIST_MAX) break;
    if (!e || typeof e !== 'object') continue;
    const u = e as Record<string, unknown>;
    if (typeof u.m !== 'string' || !/^[a-z0-9_-]{1,32}$/i.test(u.m)) continue;
    out.push({ m: u.m, n: typeof u.n === 'string' ? u.n.replace(STRIP, '').slice(0, 32) : '' });
  }
  return out.length ? out : undefined;
}

// ---- the dealings ledger (phase 2) -------------------------------------------------------------------------

/**
 * What one fleet did toward another, by kind: dollars paid at their doors (p), crossings of their works (x),
 * game days calling at their doors (c), hearts and thumbs-up on their things (h), whispers to them (s), records
 * of theirs taken (r), minutes driven beside them (b).
 */
export const COUNTERS = ['p', 'x', 'c', 'h', 's', 'r', 'b'] as const;
export type Counter = (typeof COUNTERS)[number];
export type Counts = Partial<Record<Counter, number>>;

export const COUNTER_LABEL: Record<Counter, { name: string; mine: string; theirs: string; money?: boolean }> = {
  p: { name: 'Paid at doors', mine: 'paid at their doors', theirs: 'paid at your doors', money: true },
  x: { name: 'Crossings', mine: 'crossings of their works', theirs: 'crossings of your works' },
  c: { name: 'Calls', mine: 'days calling at their doors', theirs: 'days calling at yours' },
  h: { name: 'Hearts', mine: 'hearts you gave them', theirs: 'hearts they gave you' },
  s: { name: 'Whispers', mine: 'whispers to them', theirs: 'whispers to you' },
  r: { name: 'Records taken', mine: 'records you took from them', theirs: 'records they took from you' },
  b: { name: 'Driven beside', mine: 'minutes beside them', theirs: 'minutes beside you' },
};

/** Days a "lately" window runs before it rolls (real days): lately is this window and the one before. */
export const LATELY_DAYS = 14;
/** Fleets a player's ledger keeps, by score: past this the weakest go. */
export const LEDGER_KEEP = 150;

/** Two counts added. */
export function addCounts(a: Counts, b: Counts | undefined): Counts {
  const out: Counts = { ...a };
  if (b) for (const k of COUNTERS) if (b[k]) out[k] = (out[k] ?? 0) + b[k]!;
  return out;
}

/**
 * How much two fleets have to do with each other, from both directions: dollars flattened, crossings and minutes
 * beside each other by their square roots, everything else counted, shared towns weighed heaviest. Symmetric.
 */
export function pairScore(o: Counts, i: Counts, towns = 0): number {
  const sum = (k: Counter) => (o[k] ?? 0) + (i[k] ?? 0);
  return Math.log2(1 + Math.max(0, sum('p'))) + 0.5 * Math.sqrt(Math.max(0, sum('x'))) + 2 * (sum('c') + Math.max(0, sum('h')) + sum('s') + sum('r'))
    + Math.sqrt(Math.max(0, sum('b'))) + 3 * towns;
}

/** The two or three biggest reasons two fleets are neighbours, in words, for a list row. */
export function pairWhy(o: Counts, i: Counts, money: (n: number) => string): string[] {
  const parts: { w: number; text: string }[] = [];
  const add = (k: Counter, n: number, theirs: boolean, w: number) => {
    if (!(n > 0)) return;
    const l = COUNTER_LABEL[k];
    // one of a thing reads "1 whisper to you", not "1 whispers"
    const words = theirs ? l.theirs : l.mine;
    const said = !l.money && n === 1 ? words.replace(/^(\w+?)s\b/, '$1') : words;
    parts.push({ w, text: `${l.money ? money(n) : n.toLocaleString('en-US')} ${said}` });
  };
  for (const k of COUNTERS) {
    const wOf = (n: number) => (k === 'p' ? Math.log2(1 + n) : k === 'x' ? 0.5 * Math.sqrt(n) : k === 'b' ? Math.sqrt(n) : 2 * n);
    add(k, i[k] ?? 0, true, wOf(i[k] ?? 0));
    add(k, o[k] ?? 0, false, wOf(o[k] ?? 0));
  }
  return parts.sort((a, b) => b.w - a.w).slice(0, 3).map((p) => p.text);
}

/** One fleet in a player's Neighbours: who (a player to open, every member for filters), and the counts both ways, all time and lately. */
export interface NeighbourRow {
  id: string; name: string; brand: { primary: number; accent: number; logo: string } | null;
  /** Every player in that fleet (one, or a shared fleet's members). */
  ids: string[];
  o: Counts; i: Counts; lo: Counts; li: Counts;
}

// ---- the inbox, asks and roles (phase 3) ------------------------------------------------------------------

/** A note's longest, notes kept, days kept, and the most a player may leave a day. */
export const NOTE_MAX = 200;
export const INBOX_KEEP = 100;
export const INBOX_DAYS = 30;
export const NOTES_A_DAY = 20;
/** Players a muted list keeps; asks a player may have open at once; days an ask or a targeted invite stays good. */
export const MUTED_MAX = 100;
export const ASKS_OPEN = 3;
export const ASK_DAYS = 7;
/** Hours a "Not now" bars a second ask to the same fleet. */
export const NOT_NOW_HOURS = 24;
/** The most players in a shared fleet (shared/fleets.ts CREW_MAX), here so the inbox can say a fleet is full. */
export const CREW_MAX_SOCIAL = 8;

/**
 * One thing addressed to a player, kept on their record until read and for INBOX_DAYS after: a note left for them;
 * an invite to a shared fleet (with the code, good for them alone); an ask to join their fleet (for its founder and
 * officers, with the asker's line); the answer to an ask of theirs; a friend add; a word from the server.
 */
export interface InboxItem {
  id: string; t: number;
  k: 'note' | 'invite' | 'ask' | 'answer' | 'friend' | 'sys';
  /** Who it is from, and their name and fleet's name as they were. */
  from?: string; name?: string; fleet?: string;
  text?: string;
  /** An invite's code. */
  code?: string;
  /** An ask's key, "party|asker", shared by the copies its fleet's founder and officers hold. */
  ak?: string;
  /** An ask answered (here or by another officer), or an invite used or let go. */
  done?: 'yes' | 'no' | 'gone';
  read?: 1;
}

/** A shared fleet's ways in and who may hand them out. */
export interface CrewPolicy { joining?: Joining; invites?: Inviters }

/** A note's text as it may be kept: one line, tags dropped and markup characters gone, no longer than NOTE_MAX. */
export const cleanNote = (s: unknown): string => String(s ?? '').replace(/<[^>]*>/g, ' ').replace(/[<>&"`\u0000-\u001f]/g, ' ').replace(/\s+/g, ' ').trim().slice(0, NOTE_MAX);

// ---- titles, fleet hearts, and the cargo and culture boards (phase 4) ---------------------------------------

/**
 * Nine weekly titles (docs/social.html, "Titles and scopes"), one holder each, counted from Monday to Monday (UTC)
 * and worn for the week after on the card, the name tag and the boards. No diamonds: a title is a title.
 */
export const TITLES = ['host', 'patron', 'warden', 'pathfinder', 'convoy', 'neighbour', 'hearted', 'followed', 'fleet'] as const;
export type TitleId = (typeof TITLES)[number];
export const TITLE_INFO: Record<TitleId, { name: string; icon: string; what: string; money?: boolean; unit: string }> = {
  host: { name: 'Best Host', icon: '🏠', what: 'most paid at your doors by other fleets', money: true, unit: 'at their doors' },
  patron: { name: 'Best Patron', icon: '🧾', what: 'most paid at other fleets’ doors', money: true, unit: 'at others’ doors' },
  warden: { name: 'Road Warden', icon: '🛣️', what: 'most crossings of your works by other fleets', unit: 'crossings of their works' },
  pathfinder: { name: 'Pathfinder', icon: '🧭', what: 'most crossings of other fleets’ works', unit: 'crossings of others’ works' },
  convoy: { name: 'Convoy Captain', icon: '🚚', what: 'most minutes driven beside other fleets', unit: 'minutes beside others' },
  neighbour: { name: 'Good Neighbour', icon: '🤝', what: 'most hearts, thumbs-up and fleet hearts given', unit: 'hearts given' },
  hearted: { name: 'Most Hearted Fleet', icon: '⭐', what: 'most fleet hearts received', unit: 'fleet hearts' },
  followed: { name: 'Most Followed', icon: '🎥', what: 'most minutes other players’ cameras followed your vehicles', unit: 'minutes followed' },
  fleet: { name: 'Fleet of the Week', icon: '👥', what: 'the shared fleet whose players brought most into its purse', money: true, unit: 'into the purse' },
};

/** A title's holder (or the one leading it this week): a player to open, every player of that fleet, its name, and the count. */
export interface TitleRow { id: TitleId; who: string; ids: string[]; name: string; n: number }

/** Minutes a player's camera may count following one other player in a real day. */
export const FOLLOWED_A_DAY = 60;

/**
 * The boards: g, loads delivered by cargo kind; c, units of culture brought home by style; v, loads delivered in each
 * vehicle model; e, dollars earned in each vehicle model (the user, 5 Nov 2026: the vehicle boards).
 */
export type GoodsBoardKind = 'g' | 'c' | 'v' | 'e';
/** Every board kind, in the order the crowns walk them. */
export const BOARD_KINDS: GoodsBoardKind[] = ['g', 'c', 'v', 'e'];
/** A board kind from a message, or g. */
export const boardKind = (k: unknown): GoodsBoardKind => (k === 'c' || k === 'v' || k === 'e' ? k : 'g');
/** One fleet on a board: a player to open, every player of the fleet, its name and livery, and its count. */
export interface GoodsRow { id: string; ids: string[]; name: string; brand: { primary: number; accent: number; logo: string } | null; n: number }
/** One kind's line in the summary: its leader, how many fleets have any, and your own count and place. */
export interface GoodsSummary { kind: string; top: GoodsRow | null; fleets: number; you: number; place: number }

/**
 * The crowns (docs/toppers.html phase 2, server/crowns.ts): a board's podium as the server holds it, gold, silver and
 * bronze (null an empty place), this player's count and place on it, and when the podium is due to change (a fleet
 * that has been passed keeps its crown 48 hours). `held`: the crowns this player's fleet holds; `roll`: the boards
 * on its Crown Roll (held thirty days in all) with the best metal held.
 */
export interface CrownHolder { id: string; name: string; n: number }
export interface CrownRow { k: GoodsBoardKind; kind: string; p: (CrownHolder | null)[]; you: number; place: number; due?: number }
export interface CrownMine { k: GoodsBoardKind; kind: string; place: 0 | 1 | 2 }

/** A tally as a game sends it (kind or style → count), cleaned: at most `max` kinds, names short, counts whole. */
export function cleanTally(x: unknown, max = 200): Record<string, number> | undefined {
  if (!x || typeof x !== 'object') return undefined;
  const out: Record<string, number> = {};
  let n = 0;
  for (const [k, v] of Object.entries(x as Record<string, unknown>)) {
    if (n >= max) break;
    if (typeof v !== 'number' || !Number.isFinite(v) || v <= 0 || k.length > 40) continue;
    out[k.replace(/[<>&"`\u0000-\u001f]/g, '')] = Math.round(v);
    n++;
  }
  return n ? out : undefined;
}
