import type { Sfx } from './sfx';
import { job } from '../net/perfJobs';

/**
 * Passport stamps and achievements as they are earned (docs/passport.html). Every one goes into the
 * notification history the moment it is earned; on screen, at most one card every BATCH seconds — the most
 * interesting of what came in since the last one (a wonder over a town style over a style's landmark over an
 * ordinary building), saying how many more there were. Its card slides down into the notice stack when the
 * stage is free, and the stamp itself comes down onto it — big, tilted and faint, then pressed flat with a
 * thud and a ring of ink — the way a clerk stamps a page. In the history the stamp lies still.
 */

interface StampNote {
  /** The stamp's picture (drawn when it is first shown, on the card or in the history). */
  img: () => string;
  title: string;
  body: string;
  /** The history's heading for it. */
  group: string;
  /** How interesting it is: the batch shows its highest. */
  score: number;
  /** A sound for its card, in place of the stamp's thud (an achievement's chime). */
  sound?: () => void;
  /** Shown if it is the best of its batch, but not kept in the history (a milestone on the way to a tier). */
  quiet?: boolean;
  /** A rare one, in gold foil: its card shines. */
  foil?: boolean;
  /** Clicked in the history: opens what it is about (an achievement's page of the Passport). */
  open?: () => void;
  /** Hovered in the history: what it is about (an achievement's description, as the Passport shows it). */
  tip?: string;
}

/** Seconds a card stays down. */
const SHOW = 3.4, SLIDE_OUT = 0.45;
/** At most one stamp or achievement card in this many seconds. */
const BATCH = 15;

/** Run f when the browser has a moment to spare (or within two seconds), where it can say so. */
const idle = (f: () => void): void => {
  if (typeof requestIdleCallback === 'function') requestIdleCallback(f, { timeout: 2000 });
  else setTimeout(f, 200);
};

export class StampCards {
  private el = document.createElement('div');
  private art = document.createElement('img');
  private name = document.createElement('b');
  private line = document.createElement('span');
  /** What has come in since the last card. */
  private pending: StampNote[] = [];
  /** When the next card may come down (performance.now ms). */
  private nextAt = 0;
  private age = 0;
  private up = false;
  private leaving = 0;
  /** Into the notification history, as each is earned. */
  log: (n: StampNote) => void = () => {};

  constructor(private sfx: Sfx) {
    this.el.id = 'stamp-card';
    this.el.className = 'notice';
    this.el.setAttribute('role', 'status');
    this.el.setAttribute('aria-live', 'polite');
    this.art.className = 'sc-art';
    this.art.alt = '';
    const body = document.createElement('div');
    body.className = 'sc-body';
    body.append(this.name, this.line);
    this.el.append(this.art, body);
    const notices = document.getElementById('notices')!;
    notices.insertBefore(this.el, document.getElementById('earnings'));
  }

  /** Is a card down (or going)? */
  get busy(): boolean { return this.up || this.leaving > 0; }

  push(n: StampNote): void {
    if (!n.quiet) this.log(n);
    this.pending.push(n);
    // its picture drawn (and kept: the stamps cache what they draw) while the browser is idle, not in the
    // frame the card slides in on, where the drawing and the PNG encode were a 40–50 ms hitch (Oct 2026)
    if (!n.quiet) idle(() => { try { job('stamp art', () => n.img()); } catch { /* drawn again when shown */ } });
  }

  /** Forget everything waiting (a new game). */
  clear(): void { this.pending = []; }

  /** Every frame. `hold`: a menu is open or a cut has the screen. `free`: nothing else is on the stage. */
  update(dt: number, hold: boolean, free: boolean): void {
    if (this.leaving > 0) {
      this.leaving -= dt;
      if (this.leaving <= 0) this.el.classList.remove('out', 'stamping');
      return;
    }
    if (this.up) {
      this.age += dt;
      if (this.age >= SHOW) { this.up = false; this.el.classList.remove('in'); this.el.classList.add('out'); this.leaving = SLIDE_OUT; }
      return;
    }
    if (hold || !free || !this.pending.length || performance.now() < this.nextAt) return;
    // the batch: its most interesting, and how many more came with it (milestones aren't worth counting)
    const best = this.pending.reduce((a, b) => (b.score > a.score ? b : a));
    const more = this.pending.filter((q) => q !== best && !q.quiet).length;
    this.pending = [];
    this.nextAt = performance.now() + BATCH * 1000;
    this.show(best, more);
  }

  private show(n: StampNote, more: number): void {
    this.art.src = n.img();
    this.el.classList.toggle('foil', !!n.foil);
    this.name.textContent = n.title;
    this.line.textContent = more ? `${n.body} · and ${more} more…` : n.body;
    this.age = 0;
    this.up = true;
    this.el.classList.remove('out', 'stamping');
    void this.el.offsetWidth;
    this.el.classList.add('in', 'stamping');
    // the thud as the stamp meets the card, part-way through its fall (or the achievement's chime)
    setTimeout(() => (n.sound ? n.sound() : this.sfx.nudge()), 330);
  }
}
