import { hex, scale, type RGB } from '../../world/biomes';
import type { NoveltyKind } from '../../world/tiles';
import {
  BRIGHT, CARS, DARK, METAL, PATH, ROOF_GREY, STONE, TAU, WARM_GLOW, WATER, WHITE, WOOD,
  SHOP_GLOW, car, pick, tree, type Draw, type Kit } from './kit';
import { Sec, Train, buildTrack, drawCar, drawTrack, lightsFor, placeCars, rideOpen, type CP, type Track } from './coaster';
import type { Sched } from '../nightLights';

/**
 * Landmarks and roadside fun: the giant doughnut on its post, a drive-in under the stars, a wooden
 * coaster, a working water mill, a campanile that never did stand straight, a stretch of crenellated
 * wall, a stone circle you can drive between, and an airship moored to its mast.
 */

const GRAVEL = hex(0xc8c1b0), MARBLE = hex(0xf0ece0), SHADOW = hex(0xdcd6c6);
const TIMBER = hex(0x7a5a3a), BRASS = hex(0xc08b2e);
const NEON: [number, number, number] = [17, 23, 2.4];

// ---- 1. the roadside giant ----------------------------------------------------------------------

/**
 * The thing you pull over for: a doughnut, a boot or a teapot, twenty times life size on a post in a
 * gravel lay-by, with a hand-painted board underneath and a lamp on it after dark.
 */
const roadsideGiant: Draw = (k, W, D, b, r) => {
  const s = Math.min(W, D);
  const px = -s * 0.06, pz = -s * 0.04;
  // the gravel apron and the post it all stands on
  k.disc(0, 0.012, 0, s * 0.46, GRAVEL, 10);
  k.box(px, 0, pz, 0.12 * s, 0.36 * s, 0.12 * s, WOOD);
  const cy = 0.36 * s;
  if (b.seed % 3 === 0) {
    // a doughnut: a tan ring with a fat collar of pink icing pulled round the front, and sprinkles
    const R = 0.28 * s;
    k.hoop(px, cy + R + 0.04, pz, R, 0.085 * s, hex(0xd8a45e), 12);
    k.hoop(px, cy + R + 0.04, pz + 0.05 * s, R, 0.095 * s, hex(0xf07fae), 12);
    for (let i = 0; i < 12; i++) {
      const a = r() * TAU, d = R + (r() - 0.5) * 0.08 * s;
      k.box(px + Math.cos(a) * d, cy + R + 0.04 + Math.sin(a) * d, pz + 0.14 * s, 0.05 * s, 0.02 * s, 0.02 * s, pick(r, BRIGHT));
    }
  } else if (b.seed % 3 === 1) {
    // a boot: a sole, the foot, the shaft above it and four laces criss-crossed up the front
    const leather = hex(0x8a5a32);
    k.box(px, cy, pz, 0.34 * s, 0.05 * s, 0.52 * s, hex(0x4a3a30));
    k.box(px, cy + 0.05 * s, pz + 0.08 * s, 0.3 * s, 0.2 * s, 0.36 * s, leather);
    k.box(px, cy + 0.05 * s, pz - 0.11 * s, 0.3 * s, 0.62 * s, 0.28 * s, leather, scale(leather, 1.1));
    k.box(px, cy + 0.64 * s, pz - 0.11 * s, 0.32 * s, 0.05 * s, 0.3 * s, scale(leather, 0.8));
    for (let i = 0; i < 4; i++) {
      const y = cy + 0.3 * s + i * 0.08 * s, fz = pz + 0.035 * s;
      k.bar([px - 0.12 * s, y, fz], [px + 0.12 * s, y + 0.06 * s, fz], 0.012 * s, WHITE);
      k.bar([px + 0.12 * s, y, fz], [px - 0.12 * s, y + 0.06 * s, fz], 0.012 * s, WHITE);
    }
  } else {
    // a teapot: a squat body under a domed lid, with a spout and a handle bent out of three bars
    const pot = hex(0x3f8f9a), R = 0.27 * s;
    k.cyl(px, cy, pz, R, 0.26 * s, pot, 12);
    k.dome(px, cy + 0.26 * s, pz, R, pot, 12, 3);
    k.cyl(px, cy + 0.26 * s + R * 0.8, pz, 0.07 * s, 0.05 * s, scale(pot, 0.85), 8);
    k.dome(px, cy + 0.31 * s + R * 0.8, pz, 0.06 * s, BRASS, 8, 2);
    k.bar([px + R * 0.8, cy + 0.1 * s, pz], [px + R * 1.5, cy + 0.34 * s, pz], 0.05 * s, pot);
    const hx = px - R * 0.9;
    k.bar([hx + R * 0.15, cy + 0.06 * s, pz], [hx - R * 0.3, cy + 0.12 * s, pz], 0.035 * s, pot);
    k.bar([hx - R * 0.3, cy + 0.12 * s, pz], [hx - R * 0.3, cy + 0.26 * s, pz], 0.035 * s, pot);
    k.bar([hx - R * 0.3, cy + 0.26 * s, pz], [hx + R * 0.15, cy + 0.3 * s, pz], 0.035 * s, pot);
  }
  // the board at the roadside, its little lamp on after dark
  const bz = D / 2 - 0.16;
  for (const sx of [-1, 1]) k.box(sx * 0.16 * s, 0, bz, 0.03, 0.2 * s, 0.03, WOOD);
  k.box(0, 0.16 * s, bz, 0.44 * s, 0.16 * s, 0.03, WHITE, WHITE);
  k.glowBox(0, 0.22 * s, bz - 0.025, 0.36 * s, 0.07 * s, 0.015, hex(0xe2412f), [17, 23, 2], WARM_GLOW);
};

// ---- 2. the drive-in ----------------------------------------------------------------------------

/**
 * A drive-in cinema: the screen standing on its raking frame at the back, rows of cars parked nose-in
 * with a speaker post between each pair, the snack bar and projection booth in the middle, and the
 * neon sign out at the road. The screen keeps a faint blue glow while the picture is running.
 */
const driveIn: Draw = (k, W, D, _b, r) => {
  const bz = -D / 2 + 0.3;
  const sw = Math.min(W - 0.9, 4.6), sh = 1.15;
  // the screen: two piers, a white panel and the raking struts holding it up from behind
  for (const sx of [-1, 1]) k.box(sx * (sw / 2 - 0.16), 0, bz, 0.18, 0.2, 0.22, hex(0xb0aaa0));
  k.box(0, 0.16, bz, sw, sh, 0.08, WHITE, hex(0xd8d4cc));
  k.box(0, 0.16, bz, sw + 0.1, sh + 0.06, 0.04, hex(0x6a6f76));
  k.glowBox(0, 0.22, bz + 0.05, sw - 0.14, sh - 0.14, 0.02, WHITE, [19, 24.5, 1.2], hex(0xbcd6f0));
  for (const sx of [-1, 0, 1]) {
    k.bar([sx * (sw / 2 - 0.3), 0, bz - 0.5], [sx * (sw / 2 - 0.3), sh + 0.1, bz - 0.04], 0.022, METAL);
    k.bar([sx * (sw / 2 - 0.3), 0.55, bz - 0.28], [sx * (sw / 2 - 0.3), 0.55, bz - 0.04], 0.016, METAL);
  }
  // the ranked cars, each on its little hump, with a speaker post between the bays
  const rows = Math.max(2, Math.floor((D - 1.8) / 0.8));
  for (let row = 0; row < rows; row++) {
    const z = bz + 0.95 + row * 0.8;
    for (let x = -W / 2 + 0.55; x < W / 2 - 0.4; x += 0.62) {
      if (Math.abs(x) < 0.55 && row === rows - 1) continue;
      if (r() < 0.3) continue;
      k.box(x, 0, z - 0.18, 0.44, 0.03, 0.1, hex(0xb8b2a4));
      car(k, x, z, false, pick(r, CARS));
      k.box(x + 0.31, 0, z - 0.06, 0.03, 0.16, 0.03, hex(0x6a6f76));
    }
  }
  // the snack bar and the projection booth on its roof, a lit serving hatch facing the cars
  const hz = D / 2 - 1.15;
  k.box(0, 0, hz, 1.05, 0.28, 0.5, hex(0xf1ece0), ROOF_GREY);
  k.box(0, 0.28, hz, 1.1, 0.03, 0.55, ROOF_GREY);
  k.glowBox(0, 0.1, hz + 0.26, 0.7, 0.12, 0.02, hex(0xf2c14e), [17, 23.5, 2.2], hex(0xfff0c0));
  k.box(-0.28, 0.31, hz, 0.4, 0.26, 0.34, hex(0xe4ded0), ROOF_GREY);
  k.box(-0.28, 0.38, hz - 0.18, 0.14, 0.1, 0.06, DARK);
  // the entrance sign at the road, a marquee board over a neon arrow
  const gx = -W / 2 + 0.45, gz = D / 2 - 0.22;
  for (const sx of [-1, 1]) k.box(gx + sx * 0.18, 0, gz, 0.05, 0.6, 0.05, hex(0x6a6f76));
  k.box(gx, 0.6, gz, 0.56, 0.3, 0.06, hex(0x2f4a6a));
  k.glowBox(gx, 0.66, gz + 0.04, 0.46, 0.18, 0.02, hex(0xf4f2ec), NEON, hex(0xff6fc0));
  k.glowBox(gx, 0.34, gz + 0.03, 0.4, 0.07, 0.02, hex(0xd23a2e), NEON, hex(0xff5a3a));
};

// ---- 3. the roller coaster ----------------------------------------------------------------------

/**
 * The steel coaster's circuit, in the lot's frame (front = +z): out of the station along the front, up
 * the left side, hauled up the lift hill along the back, round a turnaround at the top and down the
 * first drop, through the loop, over a camelback hill and down a helix in the middle of the lot, out
 * underneath its own entry to the brake run.
 */
export function coasterCircuit(W: number, D: number): CP[] {
  const x0 = W / 2 - 0.5, zf = D / 2 - 0.5, zb = -D / 2 + 0.5, zd = zb + 0.65, zm = zf - 0.75;
  const H = 2.3, R = 0.66, cx = -x0 + 1.25, cy = 0.2 + R, off = 0.4;
  const HR = 0.55 + Math.min(0.15, (D - 4) * 0.15), hx = x0 - 0.3 - HR, hz = -0.1;
  const cps: CP[] = [
    { p: [x0 - 1.0, 0.3, zf], sec: Sec.Station },
    { p: [x0 - 1.6, 0.3, zf], sec: Sec.Station },
    { p: [x0 - 2.2, 0.3, zf], sec: Sec.Brake },
    { p: [-x0 + 0.45, 0.33, zf - 0.08], sec: Sec.Brake },
    { p: [-x0, 0.36, zf - 0.6], sec: Sec.Brake },
    { p: [-x0, 0.4, (zf + zb) / 2], sec: Sec.Brake },
    { p: [-x0 + 0.12, 0.43, zb + 0.32], sec: Sec.Lift },
    { p: [-x0 + 0.6, 0.5, zb], sec: Sec.Lift },
    { p: [(x0 - 0.5 - x0 + 0.6) / 2, (0.5 + H) / 2, zb], sec: Sec.Lift },
    { p: [x0 - 0.5, H, zb] },
    { p: [x0 - 0.12, H + 0.02, (zb + zd) / 2] },
    { p: [x0 - 0.5, H - 0.06, zd] },
    { p: [x0 - 1.0, H - 0.5, zd] },
    { p: [cx + 1.25, 0.6, zd] },
    { p: [cx + 0.7, 0.24, zd] },
    { p: [cx + 0.35, 0.2, zd] },
  ];
  // the loop, heading −x: up and over, shifting sideways as it goes so it comes out beside where it went in
  for (let i = 0; i <= 12; i++) {
    const phi = (i / 12) * Math.PI * 2;
    cps.push({ p: [cx - R * Math.sin(phi), cy - R * Math.cos(phi), zd + (off * i) / 12], loop: i < 12 ? { c: [cx, cy, 0], axis: 'z' } : undefined });
  }
  const zl = zd + off;
  cps.push(
    { p: [cx - 0.35, 0.2, zl], sec: Sec.Trim },
    { p: [cx - 0.7, 0.27, zl + 0.05] },
    { p: [cx - 0.8, 0.5, zl + 0.42] },
    { p: [cx - 0.78, 0.7, zm - 0.35] },
    { p: [cx - 0.45, 0.55, zm] },
    { p: [(cx + hx - HR) / 2, 0.85, zm] },
    { p: [hx + 0.05, 0.8, zm] },
  );
  // the helix in the middle of the lot: three quarters of a turn, falling, out under the way in
  for (let i = 0; i <= 6; i++) {
    const th = -(i / 6) * Math.PI * 1.5;
    cps.push({ p: [hx + HR * Math.cos(th), 0.75 - (0.4 * i) / 6, hz + HR * Math.sin(th)] });
  }
  cps.push(
    { p: [hx + HR * 0.75, 0.34, hz + HR + 0.12] },
    { p: [x0 - 0.08, 0.33, (hz + HR + zf) / 2 + 0.15], sec: Sec.Brake },
    { p: [x0 - 0.45, 0.32, zf], sec: Sec.Brake },
  );
  return cps;
}

const COASTER_LOOKS: { rail: number; spine: number; legs: number; train: number[] }[] = [
  { rail: 0xe8eef2, spine: 0x2bb3a3, legs: 0xf2c14e, train: [0xe2412f, 0xf2a93b] },
  { rail: 0xf4f2ec, spine: 0xd23a2e, legs: 0xf4f2ec, train: [0x2f7fb5, 0xf4f2ec] },
  { rail: 0xd8dde2, spine: 0x8e5cc7, legs: 0x5fc25a, train: [0xf2c14e, 0x8e5cc7] },
  { rail: 0xe8eef2, spine: 0x2f7fb5, legs: 0xf2a93b, train: [0x3f9b4a, 0xf4f2ec] },
];
const RIDE_LIGHTS: [number, number, number] = [17.5, 24, 2.4];

/**
 * A steel looping coaster that runs: the track is laid as a smooth spline (coaster.ts), its four-car
 * train goes round it under gravity, waits in the station to load and stops for the night at midnight.
 * Bulbs line the rails after dark, white or rainbow, and the station, the sign and the lamps are lit.
 */
const rollerCoaster: Draw = (k, W, D, b, r) => {
  const look = COASTER_LOOKS[b.seed % COASTER_LOOKS.length];
  const track = buildTrack(coasterCircuit(W, D));
  k.box(0, 0.003, 0, W - 0.1, 0.006, D - 0.1, GRAVEL);
  const bulbs = lightsFor(b.seed);
  drawTrack(k, track, { rail: hex(look.rail), spine: hex(look.spine), legs: hex(look.legs), bulbs: bulbs.bulbs, lit: RIDE_LIGHTS, bulbLit: bulbs.lit, bulbGap: 0.2 });
  // the train
  const cars = 4, gap = 0.22, train = new Train(track, cars, gap, b.seed);
  const parts = Array.from({ length: cars }, (_, c) => (s: Kit) => drawCar(s, hex(look.train[c % 2]), c === 0, r, 1, RIDE_LIGHTS));
  k.rig(0, 0, 0, parts, (objs, dt, hour) => { train.step(dt, rideOpen(hour)); placeCars(train, objs); });
  // the station: a platform on the inside of the track along the front, under a canopy, its sign lit
  const x0 = W / 2 - 0.5, zf = D / 2 - 0.5, sx0 = x0 - 2.3, sx1 = x0 - 0.9, smx = (sx0 + sx1) / 2, sw = sx1 - sx0;
  k.box(smx, 0, zf - 0.22, sw, 0.27, 0.3, hex(0xcfc6b0), hex(0xb9b2a4));
  k.box(smx, 0, zf + 0.17, sw, 0.22, 0.1, hex(0xcfc6b0));
  for (const px of [sx0 + 0.05, smx, sx1 - 0.05]) for (const pz of [zf - 0.33, zf + 0.2]) k.box(px, 0.22, pz, 0.035, 0.42, 0.035, hex(look.spine));
  k.gable(smx, 0.64, zf - 0.06, sw + 0.15, 0.14, 0.75, hex(look.spine), WHITE);
  // strip lights under the canopy edge, and the name board over the platform
  for (const pz of [zf - 0.42, zf + 0.3]) k.glowBox(smx, 0.6, pz, sw, 0.025, 0.02, WHITE, RIDE_LIGHTS, hex(0xfff2c0));
  k.box(smx, 0.78, zf - 0.06, 0.7, 0.18, 0.04, DARK);
  k.glowBox(smx, 0.8, zf - 0.035, 0.62, 0.13, 0.02, hex(0xf2c14e), NEON, hex(0xffe06a));
  // the queue: switchbacks of rail and posts behind the platform, people waiting in the lanes
  const qz = [zf - 0.42, zf - 0.53, zf - 0.64];
  for (const z of qz) {
    k.bar([sx0 + 0.08, 0.1, z], [sx1 - 0.08, 0.1, z], 0.006, METAL);
    for (let x = sx0 + 0.08; x <= sx1 - 0.07; x += 0.2) k.box(x, 0, z, 0.016, 0.11, 0.016, DARK);
  }
  for (let lane = 0; lane < 2; lane++) {
    for (let x = sx0 + 0.14; x < sx1 - 0.1; x += 0.08 + r() * 0.05) if (r() < 0.8) person(k, x, (qz[lane] + qz[lane + 1]) / 2, r);
  }
  // the gift shop by the exit
  const bx = Math.min(sx1 + 0.5, W / 2 - 0.3);
  k.box(bx, 0, D / 2 - 0.2, 0.3, 0.28, 0.24, hex(0xf1ece0), ROOF_GREY);
  k.hip(bx, 0.28, D / 2 - 0.2, 0.38, 0.1, 0.32, hex(look.spine));
  k.glowBox(bx, 0.12, D / 2 - 0.075, 0.18, 0.08, 0.01, hex(0xf2c14e), RIDE_LIGHTS, SHOP_GLOW);
  // the park entrance at the road: two ticket booths, turnstiles between, under an arch with its name in lights
  const left = -x0 + 0.5, ew = Math.min(1.3, sx0 - left), ex = (left + sx0) / 2, ez = D / 2 - 0.14;
  k.box(ex, 0.003, ez - 0.05, ew + 0.1, 0.006, 0.3, PATH);
  for (const sd of [-1, 1]) {
    const px = ex + sd * (ew / 2 - 0.04);
    k.box(px, 0, ez, 0.08, 0.62, 0.08, hex(look.spine));
    k.glowBox(px, 0.62, ez, 0.1, 0.07, 0.1, WHITE, RIDE_LIGHTS, WARM_GLOW);
    const tx = ex + sd * (ew / 2 - 0.2);
    k.box(tx, 0, ez, 0.18, 0.22, 0.16, hex(0xf1ece0));
    k.hip(tx, 0.22, ez, 0.24, 0.08, 0.22, hex(look.spine));
    k.glowBox(tx, 0.1, ez + 0.085, 0.12, 0.06, 0.01, hex(0xf2c14e), RIDE_LIGHTS, SHOP_GLOW);
  }
  k.box(ex, 0.5, ez, ew - 0.06, 0.16, 0.05, DARK);
  k.glowBox(ex, 0.52, ez + 0.03, ew - 0.16, 0.11, 0.015, hex(look.train[0]), NEON, hex(look.train[0]));
  for (let i = 0; i < bulbs.bulbs.length * 2; i++) {
    const f = (i + 0.5) / (bulbs.bulbs.length * 2), c = bulbs.bulbs[i % bulbs.bulbs.length];
    k.glowBox(ex - (ew - 0.06) / 2 + f * (ew - 0.06), 0.67, ez, 0.022, 0.022, 0.022, c, bulbs.lit, c);
  }
  for (let i = -1; i <= 1; i++) k.box(ex + i * 0.1, 0, ez - 0.02, 0.025, 0.08, 0.06, METAL);
  for (let i = 0; i < 4; i++) if (r() < 0.7) person(k, ex + (r() - 0.5) * (ew - 0.5), ez - 0.2 - r() * 0.15, r);
  // lamp posts round the lot
  for (const [lx, lz] of [[-W / 2 + 0.2, D / 2 - 0.2], [W / 2 - 0.2, -D / 2 + 0.2], [-W / 2 + 0.2, -D / 2 + 0.2]] as const) {
    k.cyl(lx, 0, lz, 0.018, 0.42, DARK, 5);
    k.glowBox(lx, 0.42, lz, 0.07, 0.06, 0.07, WHITE, RIDE_LIGHTS, WARM_GLOW);
  }
  // planted beds under the track wherever it runs high, so the ground beneath is gardens, not gravel
  for (let i = 0; i < track.n; i += 6) {
    const x = track.pos[i * 3], y = track.pos[i * 3 + 1], z = track.pos[i * 3 + 2];
    if (y < 0.5 || Math.abs(x) > W / 2 - 0.2 || Math.abs(z) > D / 2 - 0.2) continue;
    k.disc(x, 0.008, z, 0.2, (i / 6) % 2 ? LAWN : LAWN2, 8);
    if (r() < 0.25) k.disc(x + (r() - 0.5) * 0.2, 0.012, z + (r() - 0.5) * 0.2, 0.06, pick(r, FLOWERS), 6);
  }
  // and everything else in the open ground between the track: stands, games, picnic tables, trees, people
  fillGrounds(k, W, D, track, r, bulbs.bulbs, bulbs.lit, [
    { x: smx, z: zf - 0.3, w: sw + 0.3, d: 1.0 },
    { x: ex, z: ez - 0.1, w: ew + 0.2, d: 0.5 },
    { x: bx, z: D / 2 - 0.2, w: 0.45, d: 0.4 },
  ]);
};

const LAWN = hex(0x7cc05e), LAWN2 = hex(0x72b656);
const FLOWERS = [0xe2412f, 0xf2c14e, 0xff8cf0, 0xf4f2ec, 0x8e5cc7];
const PERSON_SKIN = [0xf1c7a1, 0xd9a07a, 0x9a6a48, 0x6a4632, 0xf4d9bf];
const PERSON_TOP = [0xe2412f, 0x2f7fb5, 0xf2c14e, 0x3f9b4a, 0xf4f2ec, 0x8e5cc7, 0xff7fae, 0x2bb3a3];
const STALL_LIGHTS: Sched = [17.5, 24, 1.8];

/** A visitor, standing. */
function person(k: Kit, x: number, z: number, r: () => number): void {
  k.box(x, 0, z, 0.03, 0.045, 0.022, hex(0x3a4a6a));
  k.box(x, 0.045, z, 0.036, 0.045, 0.026, pick(r, PERSON_TOP));
  k.box(x, 0.09, z, 0.026, 0.026, 0.026, pick(r, PERSON_SKIN));
}

type Spot = { x: number; z: number; w: number; d: number };

/**
 * Lay out the open ground of a coaster lot: try each thing in turn at seeded spots, keeping it clear of
 * the track in plan (so nothing stands in a leg or under a low rail), the lot edge, what is reserved and
 * what has been placed; then fill what is left with trees and people.
 */
function fillGrounds(k: Kit, W: number, D: number, t: Track, r: () => number, bulbs: RGB[], lit: Sched, reserved: Spot[]): void {
  const pts: number[] = [];
  for (let i = 0; i < t.n; i += 2) pts.push(t.pos[i * 3], t.pos[i * 3 + 2]);
  const placed: [number, number, number][] = [];
  const free = (x: number, z: number, rad: number): boolean => {
    if (Math.abs(x) > W / 2 - 0.12 - rad || Math.abs(z) > D / 2 - 0.12 - rad) return false;
    for (let i = 0; i < pts.length; i += 2) if (Math.hypot(pts[i] - x, pts[i + 1] - z) < rad + 0.11) return false;
    for (const q of reserved) if (Math.abs(q.x - x) < q.w / 2 + rad && Math.abs(q.z - z) < q.d / 2 + rad) return false;
    for (const [px, pz, pr] of placed) if (Math.hypot(px - x, pz - z) < pr + rad + 0.06) return false;
    return true;
  };
  const spots: [number, number][] = [];
  for (let x = -W / 2 + 0.2; x < W / 2 - 0.2; x += 0.1) for (let z = -D / 2 + 0.2; z < D / 2 - 0.2; z += 0.1) spots.push([x, z]);
  for (let i = spots.length - 1; i > 0; i--) { const j = Math.floor(r() * (i + 1)); [spots[i], spots[j]] = [spots[j], spots[i]]; }
  const put = (rad: number, draw: (x: number, z: number, yaw: number) => void): boolean => {
    for (const [x, z] of spots) {
      if (!free(x, z, rad)) continue;
      placed.push([x, z, rad]);
      // face the middle of the lot, in quarter turns
      const yaw = Math.round(Math.atan2(-x, -z) / (Math.PI / 2)) * (Math.PI / 2);
      draw(x, z, yaw);
      return true;
    }
    return false;
  };
  // draw something at (x, z) in the lot frame, facing +z turned by yaw
  const at = (x: number, z: number, yaw: number, draw: (lx: number, lz: number) => void) => {
    const c = Math.cos(yaw), s = Math.sin(yaw);
    k.turned(yaw, () => draw(x * c - z * s, x * s + z * c));
  };
  const plan = ['stand', 'games', 'lamp', 'stand', 'picnic', 'lamp', 'stand', 'games', 'picnic', 'lamp', 'stand', 'picnic', 'bench', 'games', 'lamp', 'stand', 'picnic', 'bench', 'lamp'];
  let n = 0;
  for (const kind of plan) {
    if (kind === 'stand') put(0.2, (x, z, yaw) => { at(x, z, yaw, (lx, lz) => stand(k, lx, lz, n++, r)); crowd(k, x, z, yaw, r); });
    else if (kind === 'games') put(0.2, (x, z, yaw) => { at(x, z, yaw, (lx, lz) => gameBooth(k, lx, lz, r, bulbs, lit)); crowd(k, x, z, yaw, r); });
    else if (kind === 'picnic') put(0.15, (x, z) => picnic(k, x, z, r));
    else if (kind === 'lamp') put(0.06, (x, z) => { k.cyl(x, 0, z, 0.014, 0.36, DARK, 5); k.glowBox(x, 0.36, z, 0.055, 0.05, 0.055, WHITE, [17.5, 24, 2.4], WARM_GLOW); });
    else put(0.1, (x, z, yaw) => at(x, z, yaw, (lx, lz) => { k.box(lx, 0, lz, 0.16, 0.05, 0.05, WOOD); k.box(lx, 0.05, lz - 0.02, 0.16, 0.04, 0.012, WOOD); }));
  }
  // trees in what room is left, then people about the paths
  for (let i = 0; i < 14; i++) if (!put(0.09, (x, z) => tree(k, x, 0, z, 0.4 + r() * 0.15, r() < 0.2))) break;
  for (let i = 0; i < 24; i++) if (!put(0.04, (x, z) => person(k, x, z, r))) break;
}

/** A paved patch and a few people in front of a stall. */
function crowd(k: Kit, x: number, z: number, yaw: number, r: () => number): void {
  const fx = Math.sin(yaw), fz = Math.cos(yaw);
  k.disc(x + fx * 0.12, 0.007, z + fz * 0.12, 0.2, PATH, 10);
  for (let i = 0; i < 3; i++) {
    if (r() < 0.3) continue;
    const out = 0.2 + r() * 0.08, side = (r() - 0.5) * 0.2;
    person(k, x + fx * out + fz * side, z + fz * out - fx * side, r);
  }
}

/** A food stall facing +z: white hut, striped awning over a lit counter, and what it sells on the roof. */
function stand(k: Kit, x: number, z: number, n: number, r: () => number): void {
  const kinds = [0xe2412f, 0x2f7fb5, 0xf2a93b, 0x8e5cc7, 0x3f9b4a];
  const c = hex(kinds[(n + Math.floor(r() * 5)) % kinds.length]);
  k.box(x, 0, z, 0.26, 0.2, 0.2, WHITE, scale(c, 0.9));
  for (let i = 0; i < 4; i++) {
    const a = x - 0.13 + i * 0.065;
    k.quad([a, 0.2, z + 0.1], [a + 0.065, 0.2, z + 0.1], [a + 0.065, 0.15, z + 0.19], [a, 0.15, z + 0.19], i % 2 ? WHITE : c, [a + 0.03, 0.1, z]);
  }
  k.glowBox(x, 0.07, z + 0.105, 0.2, 0.05, 0.01, hex(0xf4e3b0), STALL_LIGHTS, SHOP_GLOW);
  k.box(x, 0.06, z + 0.12, 0.24, 0.015, 0.04, scale(c, 0.8));
  const sell = n % 4;
  if (sell === 0) {
    // ice cream: a cone with a scoop
    k.cyl(x, 0.2, z, 0.012, 0.1, hex(0xd8a45e), 6);
    k.dome(x, 0.3, z, 0.05, hex(0xff9ad0), 8, 2);
  } else if (sell === 1) {
    // a drink: a cup with a straw
    k.cyl(x, 0.2, z, 0.045, 0.1, hex(0xe2412f), 8, WHITE);
    k.bar([x + 0.01, 0.3, z], [x + 0.03, 0.36, z], 0.006, WHITE);
  } else if (sell === 2) {
    // popcorn: a tub heaped up
    k.cyl(x, 0.2, z, 0.05, 0.08, WHITE, 8);
    k.dome(x, 0.28, z, 0.05, hex(0xfff2c0), 8, 2);
  } else {
    // a hot dog sign, lit after dark
    k.box(x, 0.2, z, 0.02, 0.06, 0.02, DARK);
    k.glowBox(x, 0.26, z, 0.16, 0.06, 0.02, hex(0xf2c14e), STALL_LIGHTS, hex(0xffd34f));
  }
}

/** A game booth facing +z: an open front, shelves of prizes, and a row of bulbs along its front. */
function gameBooth(k: Kit, x: number, z: number, r: () => number, bulbs: RGB[], lit: Sched): void {
  const c = pick(r, BRIGHT);
  k.box(x, 0, z - 0.08, 0.3, 0.24, 0.04, c);
  for (const sx of [-1, 1]) k.box(x + sx * 0.14, 0, z, 0.02, 0.24, 0.2, c);
  k.box(x, 0.24, z, 0.32, 0.03, 0.22, WHITE, c);
  k.box(x, 0, z + 0.07, 0.28, 0.08, 0.04, scale(c, 0.8));
  for (let row = 0; row < 2; row++) for (let i = 0; i < 5; i++) k.box(x - 0.1 + i * 0.05, 0.1 + row * 0.07, z - 0.05, 0.035, 0.04, 0.03, pick(r, BRIGHT));
  for (let i = 0; i < 6; i++) k.glowBox(x - 0.125 + i * 0.05, 0.225, z + 0.1, 0.018, 0.018, 0.018, bulbs[i % bulbs.length], lit, bulbs[i % bulbs.length]);
}

/** A picnic table under a striped umbrella. */
function picnic(k: Kit, x: number, z: number, r: () => number): void {
  k.box(x, 0.06, z, 0.16, 0.015, 0.1, WOOD);
  for (const sz of [-1, 1]) k.box(x, 0.03, z + sz * 0.08, 0.16, 0.012, 0.035, WOOD);
  for (const sx of [-1, 1]) k.box(x + sx * 0.06, 0, z, 0.012, 0.06, 0.08, WOOD);
  k.cyl(x, 0.075, z, 0.006, 0.17, WHITE, 4);
  const c = pick(r, BRIGHT);
  for (let i = 0; i < 8; i++) {
    const a0 = (i / 8) * TAU, a1 = ((i + 1) / 8) * TAU;
    k.tri([x, 0.27, z], [x + Math.cos(a0) * 0.13, 0.22, z + Math.sin(a0) * 0.13], [x + Math.cos(a1) * 0.13, 0.22, z + Math.sin(a1) * 0.13], i % 2 ? WHITE : c, [x, 0.15, z]);
  }
  if (r() < 0.6) person(k, x + 0.11, z, r);
}

// ---- 4. the water mill --------------------------------------------------------------------------

/**
 * A stone-and-timber mill on its leat: the wheel turns on the seaward flank, fed over the top by a
 * plank sluice from the pond behind, and the water runs away down a kerbed channel past the lot.
 */
const waterMill: Draw = (k, W, D, _b, r) => {
  const s = Math.min(W, D);
  const wall = pick(r, STONE), roof = hex(0x6a5a4a);
  const mw = s * 0.62, md = s * 0.64, mx = -s * 0.14;
  // the mill: a stone ground floor, a boarded upper storey and a shingled gable over both
  k.box(mx, 0, 0, mw, 0.3, md, wall, scale(wall, 0.9));
  k.box(mx, 0.3, 0, mw * 0.98, 0.26, md * 0.98, TIMBER, scale(TIMBER, 1.1));
  k.gable(mx, 0.56, 0, mw + 0.12, 0.24, md + 0.12, roof, TIMBER, true);
  k.box(mx, 0, md / 2 + 0.005, 0.16, 0.24, 0.02, hex(0x4a3222));
  k.glowBox(mx - mw / 2 - 0.005, 0.36, 0, 0.02, 0.12, 0.14, hex(0xf2c14e), [17, 22.5, 1.8], WARM_GLOW);
  // the hoist beam out of the gable and a couple of sacks by the door
  k.bar([mx, 0.66, md / 2], [mx, 0.66, md / 2 + 0.18], 0.02, TIMBER);
  for (let i = 0; i < 2; i++) k.box(mx + 0.16 + i * 0.1, 0, md / 2 + 0.14, 0.08, 0.1, 0.08, hex(0xd8c9a8));
  // the leat: a kerbed channel down the near flank, with the pond behind it
  const lx = s * 0.36;
  k.box(lx, -0.04, 0, 0.3, 0.08, D - 0.2, WATER, WATER);
  for (const sd of [-1, 1]) k.box(lx + sd * 0.19, -0.04, 0, 0.08, 0.14, D - 0.2, scale(wall, 0.85));
  k.disc(lx - 0.05, 0.03, -D / 2 + 0.36, 0.3, WATER, 10, 0.26);
  // the sluice: a plank trough on two posts, running out over the top of the wheel
  const wy = 0.34, wr = 0.28;
  for (const pz of [-0.34, -0.1]) k.box(lx - 0.02, 0, pz, 0.05, wy + wr + 0.1, 0.05, TIMBER);
  k.box(lx - 0.02, wy + wr + 0.06, -0.18, 0.18, 0.05, 0.5, TIMBER);
  for (const sd of [-1, 1]) k.box(lx - 0.02 + sd * 0.1, wy + wr + 0.06, -0.18, 0.03, 0.1, 0.5, scale(TIMBER, 0.85));
  // the wheel itself, turning slowly on its axle
  k.bar([lx - 0.18, wy, 0], [lx + 0.18, wy, 0], 0.03, TIMBER);
  k.spin(lx, wy, 0, 'x', 0.55, (sp) => {
    for (const sd of [-1, 1]) {
      sp.hoop(sd * 0.07, 0, 0, wr, 0.018, TIMBER, 10, 'zy');
      sp.hoop(sd * 0.07, 0, 0, wr * 0.55, 0.012, TIMBER, 8, 'zy');
      for (let i = 0; i < 8; i++) {
        const a = (i / 8) * TAU;
        sp.bar([sd * 0.07, 0, 0], [sd * 0.07, Math.sin(a) * wr, Math.cos(a) * wr], 0.012, TIMBER);
      }
    }
    // the paddles between the rims, and the hub on the axle
    for (let i = 0; i < 8; i++) {
      const a = (i / 8) * TAU, py = Math.sin(a) * wr, pz = Math.cos(a) * wr;
      sp.bar([-0.09, py, pz], [0.09, py, pz], 0.035, scale(TIMBER, 0.9));
    }
    sp.bar([-0.12, 0, 0], [0.12, 0, 0], 0.035, DARK);
  });
};

// ---- 5. the leaning tower -----------------------------------------------------------------------

/**
 * A marble campanile of stacked arcaded tiers that has been going over since the day it was built:
 * every ring is set a little further along the lean than the one below, about six degrees off true,
 * with a bell hanging in the open stage at the top.
 */
const leaningTower: Draw = (k, W, D, _b, r) => {
  const s = Math.min(W, D);
  const R = 0.22 * s, TIER = 0.15, TIERS = 7;
  // the lean: a little over a tenth of the height, off toward the front-left corner
  const LEAN = 0.105, lx = -0.78 * LEAN, lz = 0.62 * LEAN;
  const at = (y: number): [number, number] => [lx * y, lz * y];
  // the plinth and the blind arcade of the ground storey
  k.disc(0, 0.01, 0, R + 0.12, SHADOW, 14);
  k.cyl(0, 0, 0, R, TIER, MARBLE, 14, SHADOW);
  for (let j = 0; j < 12; j++) {
    const a = (j / 12) * TAU;
    k.box(Math.cos(a) * R * 0.99, 0.02, Math.sin(a) * R * 0.99, 0.03, TIER - 0.05, 0.03, SHADOW);
  }
  // the arcaded tiers: a cornice, a slim core and a ring of colonnettes round the outside
  for (let i = 1; i <= TIERS; i++) {
    const y = i * TIER, [cx, cz] = at(y);
    k.cyl(cx, y, cz, R + 0.018, 0.028, SHADOW, 14, MARBLE);
    k.cyl(cx, y + 0.028, cz, R * 0.78, TIER - 0.05, scale(MARBLE, 0.94), 12);
    for (let j = 0; j < 10; j++) {
      const a = (j / 10) * TAU + i * 0.1;
      k.cyl(cx + Math.cos(a) * R * 0.94, y + 0.028, cz + Math.sin(a) * R * 0.94, 0.017, TIER - 0.05, MARBLE, 5);
    }
  }
  // the bell stage: a narrower open ring under its own cornice, with the bell on a beam
  const by = (TIERS + 1) * TIER, [bx, bz] = at(by);
  const br = R * 0.66;
  k.cyl(bx, by, bz, R + 0.018, 0.028, SHADOW, 14, MARBLE);
  k.cyl(bx, by + 0.028, bz, br * 0.5, 0.2, scale(MARBLE, 0.9), 10);
  for (let j = 0; j < 8; j++) {
    const a = (j / 8) * TAU;
    k.cyl(bx + Math.cos(a) * br, by + 0.028, bz + Math.sin(a) * br, 0.019, 0.2, MARBLE, 5);
  }
  k.cyl(bx, by + 0.228, bz, br + 0.03, 0.03, SHADOW, 12, MARBLE);
  k.bar([bx - br * 0.7, by + 0.2, bz], [bx + br * 0.7, by + 0.2, bz], 0.014, TIMBER);
  k.cyl(bx, by + 0.09, bz, 0.05, 0.08, BRASS, 8);
  k.dome(bx, by + 0.17, bz, 0.05, BRASS, 8, 2);
  void r;
};

// ---- 6. the great wall --------------------------------------------------------------------------

/**
 * A stretch of crenellated wall running the length of the lot, riding whatever ridge is under it: each
 * span takes its foot from the ground below, so the walk climbs and dips. A square watchtower stands
 * in the middle, with a flight of steps up to the walk beside it.
 */
const greatWall: Draw = (k, W, D, _b, r) => {
  const alongX = W >= D;
  const L = (alongX ? W : D) - 0.1, T = Math.min(alongX ? D : W, 1.4) * 0.62;
  const stone = pick(r, STONE), face = scale(stone, 0.88), walk = scale(stone, 0.8);
  // the wall runs along u, and sits across v; everything below is laid out in those two
  const put = (u: number, v: number, lu: number, lv: number, y: number, h: number, col: RGB, top: RGB = col): void => {
    if (alongX) k.box(u, y, v, lu, h, lv, col, top);
    else k.box(v, y, u, lv, h, lu, col, top);
  };
  const gnd = (u: number, v = 0): number => (alongX ? k.ground(u, v) : k.ground(v, u));
  const H = 0.5, spans = Math.max(6, Math.round(L / 0.45)), step = L / spans;
  for (let i = 0; i < spans; i++) {
    const u0 = -L / 2 + i * step, u = u0 + step / 2;
    // the foot of the span is the lowest of the ground under it, so nothing floats over a dip
    const foot = Math.min(gnd(u0), gnd(u0 + step), gnd(u)) - 0.06;
    put(u, 0, step + 0.01, T, foot, H, face, walk);
    put(u, 0, step + 0.01, T * 0.78, foot + H, 0.02, walk);
    // merlons along both edges, every other bay so the gaps read from a distance
    if (i % 2) continue;
    for (const sd of [-1, 1]) put(u, sd * (T / 2 - 0.05), step * 0.5, 0.1, foot + H, 0.12, stone);
  }
  // the watchtower: a taller block with its own battlements, a lit window and a low tiled roof
  const tf = gnd(0) - 0.06, ts = T * 1.55;
  put(0, 0, ts, ts, tf, H + 0.4, stone, walk);
  for (const sd of [-1, 1]) {
    put(0, sd * (ts / 2 - 0.05), ts * 0.72, 0.1, tf + H + 0.4, 0.13, face);
    put(sd * (ts / 2 - 0.05), 0, 0.1, ts * 0.72, tf + H + 0.4, 0.13, face);
  }
  // a lit window on the face that looks out over the country, and a low tiled roof on the tower
  if (alongX) k.glowBox(0, tf + H + 0.12, ts / 2 + 0.005, 0.14, 0.16, 0.02, hex(0x3a3f45), [17, 24, 2], WARM_GLOW);
  else k.glowBox(ts / 2 + 0.005, tf + H + 0.12, 0, 0.02, 0.16, 0.14, hex(0x3a3f45), [17, 24, 2], WARM_GLOW);
  k.hip(0, tf + H + 0.53, 0, ts + 0.2, 0.22, ts + 0.2, hex(0x8a4a34));
  // the steps up to the walk from the inside face
  const su = ts / 2 + 0.1, sf = gnd(su) - 0.06;
  for (let i = 0; i < 6; i++) {
    put(su + i * 0.12, -(T / 2 + 0.1), 0.12, 0.3, sf, 0.06 + i * ((H - 0.06) / 5), walk);
  }
};

// ---- 7. the stone circle ------------------------------------------------------------------------

/**
 * A ring of rough sarsens on the open ground, two of them carrying lintels, a heel stone leaning out
 * beyond the ditch and the grass worn to dirt where everyone walks. Nothing here is solid: the lot is
 * drivable and the gaps between the stones are wide enough to take it at speed.
 */
const stoneCircle: Draw = (k, W, D, _b, r) => {
  const R = Math.min(W, D) / 2 - 0.34;
  const sarsen = hex(0x9e9a90), lichen = hex(0x8e9284);
  // the worn ring of grass and the scuffed middle
  k.hoop(0, 0.012, 0, R, 0.07, PATH, 18, 'xz');
  k.disc(0, 0.01, 0, R * 0.45, scale(PATH, 1.04), 12);
  const n = 9;
  for (let i = 0; i < n; i++) {
    const a = (i / n) * TAU + 0.2;
    const h = 0.42 + r() * 0.26, w = 0.17 + r() * 0.08;
    const trilithon = i === 1 || i === 5;
    // each stone is drawn in a frame turned to face the middle, so it stands square to the ring
    k.turned(-a + r() * 0.12 - 0.06, () => {
      if (trilithon) {
        // two uprights with a lintel dropped across them
        for (const sd of [-1, 1]) k.box(R, 0, sd * 0.17, w * 0.9, h, 0.14, i % 2 ? sarsen : lichen, scale(sarsen, 0.86));
        k.box(R, h, 0, w * 0.8, 0.1, 0.5, lichen, scale(lichen, 1.05));
      } else {
        k.box(R, 0, 0, w, h, 0.13, i % 3 ? sarsen : lichen, scale(sarsen, 0.86));
        // a shoulder knocked off the top of about half of them
        if (i % 2) k.box(R, h - 0.04, 0.03, w * 0.55, 0.07, 0.1, scale(sarsen, 0.92));
      }
    });
  }
  // the heel stone outside the ring, leaning away, on its own patch of dirt
  const ha = 0.2 + TAU * 0.24, hx = Math.cos(ha) * (R + 0.42), hz = Math.sin(ha) * (R + 0.42);
  k.disc(hx, 0.012, hz, 0.2, PATH, 8);
  k.bar([hx, 0, hz], [hx + 0.1, 0.52, hz + 0.06], 0.085, sarsen);
};

// ---- 8. the airship mast ------------------------------------------------------------------------

/**
 * A lattice mooring mast with a small airship nosed on to the top of it, swinging round with the wind.
 * A red beacon burns on the mast head all night, and the ship's envelope is high enough to read from
 * halfway across the county.
 */
const airshipMast: Draw = (k, W, D, _b, r) => {
  const s = Math.min(W, D), H = 2.3;
  const base = 0.19 * s, tip = 0.05 * s, sections = 5;
  const half = (y: number): number => base + (tip - base) * (y / H);
  // the concrete raft and four legs tapering in, cross-braced on every face
  k.box(0, 0, 0, 0.62 * s, 0.05, 0.62 * s, hex(0xb8b4ac));
  for (let sN = 0; sN < sections; sN++) {
    const y0 = 0.05 + ((H - 0.05) * sN) / sections, y1 = 0.05 + ((H - 0.05) * (sN + 1)) / sections;
    const a = half(y0), b2 = half(y1);
    const c0: [number, number][] = [[-a, -a], [a, -a], [a, a], [-a, a]];
    const c1: [number, number][] = [[-b2, -b2], [b2, -b2], [b2, b2], [-b2, b2]];
    for (let i = 0; i < 4; i++) {
      const nx = (i + 1) % 4;
      k.bar([c0[i][0], y0, c0[i][1]], [c1[i][0], y1, c1[i][1]], 0.022, METAL);
      k.bar([c0[i][0], y0, c0[i][1]], [c1[nx][0], y1, c1[nx][1]], 0.009, hex(0x8e959c));
      k.bar([c1[i][0], y1, c1[i][1]], [c1[nx][0], y1, c1[nx][1]], 0.011, METAL);
    }
  }
  // the mooring head: a little platform, the cone the ship's nose sits in, and the beacon
  k.cyl(0, H, 0, tip + 0.04, 0.05, hex(0x6a6f76), 8);
  k.cone(0, H + 0.05, 0, tip + 0.02, 0.1, hex(0xd23a2e), 8);
  k.glowBox(0, H + 0.16, 0, 0.05, 0.05, 0.05, hex(0x882222), [17, 30.5, 3.2], hex(0xff3a2a));
  for (const sd of [-1, 1]) k.glowBox(sd * (half(H * 0.5) + 0.03), H * 0.5, 0, 0.04, 0.04, 0.04, hex(0x882222), [17, 30.5, 3.2], hex(0xff3a2a));
  // the ship, moored nose-on and swinging round the mast head all day
  const len = Math.max(1.0, s * 0.95), skin = pick(r, [0xe4e0d4, 0xd8d2c0, 0xe8c9a0]);
  k.spin(0, H + 0.12, 0, 'y', 0.035, (sp) => {
    const segs = 7;
    for (let i = 0; i < segs; i++) {
      const t0 = (i + 0.5) / segs, w = Math.sin(Math.PI * Math.min(1, t0 * 1.05)) * 0.3 * s;
      sp.box(0, -w / 2, 0.06 + len * (i / segs) + len / (segs * 2), w, w, len / segs + 0.004, skin, scale(skin, 1.05));
    }
    // a band round the middle, the tail fins and the gondola slung underneath
    sp.box(0, -0.15 * s, 0.06 + len * 0.45, 0.31 * s, 0.05 * s, 0.1, hex(0xd23a2e));
    const tz = 0.06 + len * 0.94;
    sp.box(0, -0.3 * s, tz, 0.03, 0.34 * s, 0.22, hex(0xd23a2e));
    sp.box(0, -0.16 * s, tz, 0.36 * s, 0.03, 0.22, hex(0xd23a2e));
    sp.box(0, -0.34 * s, 0.06 + len * 0.3, 0.1 * s, 0.09 * s, 0.24, hex(0x4a4e54), DARK);
    sp.glowBox(0, -0.31 * s, 0.06 + len * 0.3 + 0.12, 0.07 * s, 0.05 * s, 0.02, hex(0xf2c14e), [17, 24, 1.8], WARM_GLOW);
    // the mooring line back to the mast head
    sp.bar([0, -0.14 * s, 0.05], [0, 0, 0], 0.008, DARK);
  });
};

