/**
 * The camera mode's recorder (docs/postcards.html, phase 1): stills and short clips of the game's own
 * canvas, cropped to the chosen frame, and then dressed in the border the player picks on the save card
 * (game/postcardFrame.ts): one of three postcards, with the fleet's mark in one corner and the game's address
 * in the other, or clean, the picture with just the wordmark.
 *
 * The main renderer keeps no drawing buffer, so every frame is copied out straight after it is drawn
 * (main.ts calls `frame` after `post.render()`), into a 2D canvas: the bare picture, undressed. A still keeps a
 * copy of it; a clip is recorded from it by a MediaRecorder. Dressing a still is one draw. Dressing a clip plays
 * it back through a second canvas with the border laid over each frame and records that (`dress`), in real time,
 * so the card starts it as soon as the take is shown and again whenever the border is changed.
 * Nothing is uploaded: the file is the player's to post.
 */

import { drawOverlay, photoRect, type Border, type StampLook } from './postcardFrame';

/** Where the game is played, as the clip's corner says it. */
export const PLAY_ADDRESS = 'tinyfleet.up.railway.app/play';
export const PLAY_URL = `https://${PLAY_ADDRESS}/`;

/** The longest side of what is saved, in pixels. */
const MAX_SIDE = 1920;
const BITRATE = 8_000_000;
/** The bare clip is recorded richer, since it is encoded a second time when it is dressed. */
const RAW_BITRATE = 16_000_000;
/** What to ask the browser for, best first: MP4 is what every site takes; WebM where MP4 can't be made. */
const TYPES = ['video/mp4;codecs=avc1.640028', 'video/mp4;codecs=avc1.4d002a', 'video/mp4;codecs=avc1', 'video/mp4',
  'video/webm;codecs=vp9', 'video/webm;codecs=vp8', 'video/webm'];
const FALLBACK_STAMP: StampLook = { icon: '🚗', label: 'TinyFleet', colour: '#2f7a5a' };

/**
 * The fleet's mark: its badge (a data URL) and name, or null to leave the name off; the address in the other
 * corner (a postcard's link, or PLAY_ADDRESS); the postage stamp for where it was taken; and the place, the
 * vintage cards' caption.
 */
export interface Mark { badge: string | null; name: string | null; address?: string; stamp?: StampLook; place?: string }

/** A crop of the screen, in CSS pixels. */
export interface Rect { x: number; y: number; w: number; h: number }

/** A file ready to save: a take dressed in its border. */
export interface Take { blob: Blob; url: string; type: string; ext: 'mp4' | 'webm' | 'png'; seconds: number; w: number; h: number }

/** A take as taken, not yet dressed: a still's picture, or a clip's bare recording. */
export type Shot =
  | { kind: 'still'; canvas: HTMLCanvasElement; w: number; h: number; at: Date }
  | { kind: 'clip'; blob: Blob; url: string; type: string; ext: 'mp4' | 'webm'; seconds: number; w: number; h: number; at: Date };

/** A take being dressed: its file once ready (null if it couldn't be made, or was cancelled), and how to stop it. */
export interface Dressing { done: Promise<Take | null>; cancel(): void }

export function recordType(): string | null {
  if (typeof MediaRecorder === 'undefined') return null;
  return TYPES.find((t) => MediaRecorder.isTypeSupported(t)) ?? null;
}

/** A canvas's frames as a stream, handed over one at a time where the browser allows it, else sampled 30 a second. */
function frameStream(c: HTMLCanvasElement): { stream: MediaStream; track: MediaStreamTrack & { requestFrame?: () => void } } {
  let stream = c.captureStream(0);
  let track = stream.getVideoTracks()[0] as MediaStreamTrack & { requestFrame?: () => void };
  if (!track?.requestFrame) { stream.getTracks().forEach((t) => t.stop()); stream = c.captureStream(30); track = stream.getVideoTracks()[0]; }
  return { stream, track };
}

export class Recorder {
  /** The bare picture, the crop of the frame just drawn. */
  private out = document.createElement('canvas');
  private g = this.out.getContext('2d')!;
  private badge: HTMLImageElement | null = null;
  /** The dressing for each border at the current size and mark, drawn once and laid over every frame. */
  private overlays = new Map<string, HTMLCanvasElement>();
  private overlayBase = '';
  private badgeSrc = '';
  private rec: MediaRecorder | null = null;
  private track: (MediaStreamTrack & { requestFrame?: () => void }) | null = null;
  private chunks: Blob[] = [];
  private started = 0;
  private wantStill: ((t: Shot | null) => void) | null = null;
  private done: ((t: Shot | null) => void) | null = null;
  private type = '';
  /**
   * A clip asked for, waiting for the game's next frame to begin on. Started at once, the recorder's first frame
   * was copied from the game's canvas outside its frame, when WebGL hands back nothing: drawn over the last
   * take's frame still in the output, that left the previous clip's picture as this one's first frame, and its
   * thumbnail on Reddit.
   */
  private starting: Rect | null = null;
  /** Seconds recorded so far, or -1 when not recording. */
  get recording(): number { return this.rec ? (performance.now() - this.started) / 1000 : this.starting ? 0 : -1; }

  constructor(private source: HTMLCanvasElement) {}

  /** The mark for what is taken next. */
  private mark: Mark = { badge: null, name: null };
  setMark(m: Mark): void {
    this.mark = m;
    if (m.badge && m.badge !== this.badgeSrc) {
      this.badgeSrc = m.badge;
      const img = new Image();
      img.onload = () => { if (this.badgeSrc === m.badge) { this.badge = img; this.overlayBase = ''; } };
      img.src = m.badge;
    } else if (!m.badge) { this.badge = null; this.badgeSrc = ''; }
  }

  /** Size the output to a crop of the screen: the largest that fits MAX_SIDE, in even pixels (H.264 wants them even). */
  private size(r: Rect): { sx: number; sy: number; sw: number; sh: number } {
    const kx = this.source.width / Math.max(1, this.source.clientWidth || window.innerWidth);
    const ky = this.source.height / Math.max(1, this.source.clientHeight || window.innerHeight);
    const sx = Math.round(r.x * kx), sy = Math.round(r.y * ky), sw = Math.round(r.w * kx), sh = Math.round(r.h * ky);
    const k = Math.min(1, MAX_SIDE / Math.max(sw, sh));
    const w = Math.max(2, Math.round((sw * k) / 2) * 2), h = Math.max(2, Math.round((sh * k) / 2) * 2);
    if (this.out.width !== w || this.out.height !== h) { this.out.width = w; this.out.height = h; }
    return { sx, sy, sw, sh };
  }

  /** The frame just drawn, cropped to the frame being taken: the bare picture. */
  private draw(r: Rect): void {
    const { sx, sy, sw, sh } = this.size(r);
    this.g.drawImage(this.source, sx, sy, sw, sh, 0, 0, this.out.width, this.out.height);
  }

  /** The dressing for a W×H frame in a border, drawn once for the size, mark and day. */
  private overlay(W: number, H: number, border: Border): HTMLCanvasElement {
    const m = this.mark;
    // the wordmark is set in the title's Fredoka: asked for here, and the card drawn again once it has come
    const font = typeof document !== 'undefined' && !!document.fonts?.check('700 40px "Fredoka"');
    if (!font) void document.fonts?.load('700 40px "Fredoka"');
    const base = `${m.name}|${m.address}|${m.place}|${m.stamp?.label}|${m.stamp?.icon}|${!!this.badge}|${font}|${new Date().toDateString()}`;
    if (base !== this.overlayBase) { this.overlayBase = base; this.overlays.clear(); }
    const key = `${W}x${H}|${border}`;
    let o = this.overlays.get(key);
    if (!o) {
      o = drawOverlay(W, H, border, m.stamp ?? FALLBACK_STAMP, new Date(), m.place ?? 'TinyFleet', (g, y, u, photo) => this.marks(g, y, u, photo));
      this.overlays.set(key, o);
    }
    return o;
  }

  /**
   * A picture dressed in a border, into `target` (sized to the take): the picture fills the border's window,
   * cropped round its middle to the window's shape, with the card laid over it. `sw`×`sh` is the picture's size.
   */
  compose(target: HTMLCanvasElement, src: CanvasImageSource, sw: number, sh: number, border: Border): void {
    const W = target.width, H = target.height, g = target.getContext('2d')!;
    if (!sw || !sh) return;
    const p = photoRect(W, H, border);
    const k = Math.max(p.w / sw, p.h / sh), cw = p.w / k, ch = p.h / k;
    if (border !== 'clean') g.clearRect(0, 0, W, H);
    g.drawImage(src, (sw - cw) / 2, (sh - ch) / 2, cw, ch, p.x, p.y, p.w, p.h);
    g.drawImage(this.overlay(W, H, border), 0, 0);
  }

  /** The fleet's badge and name in a pill at the picture's bottom left, and where to play at its bottom right. */
  private marks(g: CanvasRenderingContext2D, y: number, u: number, p: { x: number; y: number; w: number; h: number }): void {
    const pad = Math.round(20 * u), ph = Math.round(52 * u), fs = Math.round(25 * u);
    g.font = `600 ${fs}px "IBM Plex Sans", "Segoe UI", system-ui, sans-serif`;
    g.textBaseline = 'middle';
    g.textAlign = 'left';
    const pill = (x: number, w: number) => {
      g.fillStyle = 'rgba(20,28,34,0.55)';
      g.beginPath();
      g.roundRect(x, y, w, ph, ph / 2);
      g.fill();
    };
    const name = this.mark.name, bh = Math.round(ph * 0.8);
    const bw = this.badge ? Math.round((bh * this.badge.width) / Math.max(1, this.badge.height)) : 0;
    if (this.badge || name) {
      const tw = name ? g.measureText(name).width : 0;
      const w = Math.round((this.badge ? bw + 10 * u : 0) + tw + (name ? 32 * u : 14 * u));
      pill(p.x + pad, w);
      let x = p.x + pad + 12 * u;
      if (this.badge) { g.drawImage(this.badge, x, y + (ph - bh) / 2, bw, bh); x += bw + 10 * u; }
      if (name) { g.fillStyle = '#fff'; g.fillText(name, x, y + ph / 2 + 1); }
    }
    const addr = this.mark.address ?? PLAY_ADDRESS;
    const aw = g.measureText(addr).width + 32 * u;
    pill(p.x + p.w - pad - aw, aw);
    g.fillStyle = '#fff';
    g.fillText(addr, p.x + p.w - pad - aw + 16 * u, y + ph / 2 + 1);
  }

  /** Called by the game once a frame, straight after the frame is drawn, with the crop to take. */
  frame(r: Rect): void {
    if (!this.rec && !this.wantStill && !this.starting) return;
    // a window with nothing to show (minimised, or a hidden pane): nothing to copy this frame
    if (!this.source.width || !this.source.height || r.w < 2 || r.h < 2) return;
    this.draw(r);
    // a clip waiting to begin begins on this frame, drawn fresh just now
    if (this.starting) { this.starting = null; this.begin(); }
    if (this.wantStill) {
      const cb = this.wantStill;
      this.wantStill = null;
      const c = document.createElement('canvas');
      c.width = this.out.width; c.height = this.out.height;
      c.getContext('2d')!.drawImage(this.out, 0, 0);
      cb({ kind: 'still', canvas: c, w: c.width, h: c.height, at: new Date() });
    }
    if (this.rec) this.track?.requestFrame?.();
  }

  /**
   * The last frame taken, dressed in `border`, as a small JPEG (base64, no prefix): a postcard's picture, its
   * link's preview. The longest side `side` pixels; null when nothing has been drawn.
   */
  thumb(side: number, border: Border, quality = 0.72): string | null {
    const W = this.out.width, H = this.out.height;
    if (W < 4 || H < 4) return null;
    const full = document.createElement('canvas');
    full.width = W; full.height = H;
    this.compose(full, this.out, W, H, border);
    const k = Math.min(1, side / Math.max(W, H));
    const c = document.createElement('canvas');
    c.width = Math.round(W * k); c.height = Math.round(H * k);
    c.getContext('2d')!.drawImage(full, 0, 0, c.width, c.height);
    const url = c.toDataURL('image/jpeg', quality);
    return url.startsWith('data:image/jpeg;base64,') ? url.slice('data:image/jpeg;base64,'.length) : null;
  }

  /** A still of the next frame drawn. */
  still(): Promise<Shot | null> {
    return new Promise((res) => { this.wantStill = res; });
  }

  /** A still asked for and not yet taken: given up (the camera closed first). */
  cancelStill(): void {
    const cb = this.wantStill;
    this.wantStill = null;
    cb?.(null);
  }

  /** Start a clip, on the game's next frame. False when this browser can't record one. */
  start(r: Rect): boolean {
    if (this.rec || this.starting) return true;
    const type = recordType();
    if (!type || !this.out.captureStream || !this.source.width || !this.source.height) return false;
    // nothing of the last take left in the output: the first frame recorded is the next one the game draws
    this.size(r);
    this.g.clearRect(0, 0, this.out.width, this.out.height);
    this.starting = r;
    return true;
  }

  /** The recorder itself, once the first frame of the clip is in the output. */
  private begin(): void {
    const type = recordType();
    if (!type) return;
    // frames are handed over one at a time as they are drawn, where the browser allows it, so the clip
    // runs at the game's own frame rate; otherwise the canvas is sampled at 30 a second
    const { stream, track } = frameStream(this.out);
    let rec: MediaRecorder;
    try { rec = new MediaRecorder(stream, { mimeType: type, videoBitsPerSecond: RAW_BITRATE }); } catch { stream.getTracks().forEach((t) => t.stop()); this.done?.(null); this.done = null; return; }
    this.type = type;
    this.track = track;
    this.chunks = [];
    rec.ondataavailable = (e) => { if (e.data.size) this.chunks.push(e.data); };
    rec.onstop = () => {
      const seconds = (performance.now() - this.started) / 1000;
      const blob = new Blob(this.chunks, { type: this.type.split(';')[0] });
      this.chunks = [];
      stream.getTracks().forEach((t) => t.stop());
      const cb = this.done;
      this.done = null;
      cb?.(blob.size ? { kind: 'clip', blob, url: URL.createObjectURL(blob), type: blob.type, ext: this.type.startsWith('video/mp4') ? 'mp4' : 'webm', seconds, w: this.out.width, h: this.out.height, at: new Date() } : null);
    };
    rec.start(1000);
    this.rec = rec;
    this.started = performance.now();
    track.requestFrame?.();
  }

  /** Stop the clip; the bare take comes back once the browser has finished the file. */
  stop(): Promise<Shot | null> {
    // stopped before its first frame: nothing was recorded
    if (this.starting) { this.starting = null; return Promise.resolve(null); }
    const rec = this.rec;
    if (!rec) return Promise.resolve(null);
    this.rec = null;
    this.track = null;
    return new Promise((res) => { this.done = res; rec.stop(); });
  }

  /**
   * A take dressed in a border, as a file. A still is drawn once. A clip is played back from the start and
   * recorded again with the border over every frame: it takes as long as the clip, `progress` hearing how far
   * (0..1) it has got.
   */
  dress(shot: Shot, border: Border, progress?: (f: number) => void): Dressing {
    const c = document.createElement('canvas');
    c.width = shot.w; c.height = shot.h;
    if (shot.kind === 'still') {
      this.compose(c, shot.canvas, shot.w, shot.h, border);
      const done = new Promise<Take | null>((res) => c.toBlob((blob) => res(blob ? { blob, url: URL.createObjectURL(blob), type: 'image/png', ext: 'png', seconds: 0, w: shot.w, h: shot.h } : null), 'image/png'));
      return { done, cancel: () => { /* a still is made in one go */ } };
    }
    const type = recordType();
    const v = document.createElement('video');
    v.muted = true;
    v.playsInline = true;
    v.preload = 'auto';
    let stopped = false, raf = 0;
    let rec: MediaRecorder | null = null;
    let stream: MediaStream | null = null;
    let finish: (t: Take | null) => void = () => {};
    const done = new Promise<Take | null>((res) => {
      let ended = false;
      const end = (t: Take | null) => {
        if (ended) return;
        ended = true;
        cancelAnimationFrame(raf);
        stream?.getTracks().forEach((tr) => tr.stop());
        v.removeAttribute('src');
        v.load();
        if (stopped && t) URL.revokeObjectURL(t.url);
        res(stopped ? null : t);
      };
      finish = end;
      if (!type || !c.captureStream) { end(null); return; }
      v.onerror = () => { if (rec && rec.state !== 'inactive') rec.stop(); else end(null); };
      v.addEventListener('loadeddata', () => {
        if (stopped) { end(null); return; }
        const fs = frameStream(c);
        stream = fs.stream;
        const track = fs.track;
        try { rec = new MediaRecorder(stream, { mimeType: type, videoBitsPerSecond: BITRATE }); } catch { end(null); return; }
        const chunks: Blob[] = [];
        rec.ondataavailable = (e) => { if (e.data.size) chunks.push(e.data); };
        rec.onstop = () => {
          const blob = new Blob(chunks, { type: type.split(';')[0] });
          end(blob.size ? { blob, url: URL.createObjectURL(blob), type: blob.type, ext: type.startsWith('video/mp4') ? 'mp4' : 'webm', seconds: shot.seconds, w: shot.w, h: shot.h } : null);
        };
        let last = -1;
        const draw = () => {
          // a frame is handed over only when the clip has moved on, so the dressed clip keeps the bare one's frames
          if (v.currentTime !== last) {
            last = v.currentTime;
            this.compose(c, v, v.videoWidth, v.videoHeight, border);
            track.requestFrame?.();
            progress?.(Math.min(1, v.currentTime / Math.max(0.1, shot.seconds)));
          }
        };
        const tick = () => { if (stopped || !rec) return; draw(); raf = requestAnimationFrame(tick); };
        v.onended = () => { cancelAnimationFrame(raf); draw(); progress?.(1); if (rec && rec.state !== 'inactive') rec.stop(); };
        draw();
        rec.start(1000);
        track.requestFrame?.();
        v.play().then(() => { raf = requestAnimationFrame(tick); }).catch(() => { if (rec && rec.state !== 'inactive') rec.stop(); });
      }, { once: true });
      v.src = shot.url;
    });
    return {
      done,
      cancel: () => {
        if (stopped) return;
        stopped = true;
        v.pause();
        const r = rec as MediaRecorder | null;
        if (r && r.state !== 'inactive') r.stop();
        else finish(null);
      },
    };
  }
}
