import { hashString, mulberry32 } from '../world/rng';
import { personName } from './mayor';
import type { CargoClass, VehicleDef } from './vehicles';
import type { Urgency } from './cargoTypes';

/**
 * Drivers: people with a name and a dial. A driver is hash-generated like a mayor, so a candidate is
 * the same person on reload; once hired they keep a licence, a temperament, a nose for one class of
 * cargo, a rank earned by deliveries and a mood that your cut pulls up or down.
 */

/** 'rail' (docs/crewtrains.html, 4 Nov 2026): a driver who can take a fleet train out on its beat. */
export type Licence = 'road' | 'sea' | 'air' | 'rail';
export type Temper = 'careful' | 'steady' | 'quick';
export type Rank = 'rookie' | 'regular' | 'veteran' | 'ace';
/** How the cut makes a driver work. */
type CutMode = 'hustle' | 'steady' | 'coasting';

export interface Driver {
  id: number;
  name: string;
  licences: Licence[];
  temper: Temper;
  nose: CargoClass | null;
  /** Deliveries made, which is what ranks them up; a hired veteran starts at the threshold. */
  deliveries: number;
  /** What their share has come to, for the pleasure of it. */
  kept: number;
  mood: number;
  /** Your share of every delivery, 0.2..0.6. */
  cut: number;
  /** The unit they are in, or 0 on the bench. */
  unit: number;
  /** Told the player they are restless on the bench (Fleet.tick): said once until they cheer up again. */
  warned?: boolean;
  /**
   * Their life with the fleet, for the crew card (the user, 6 Nov 2026): tiles driven, what their deliveries paid
   * you, incidents (tows), and the game day they joined. Optional: a driver from an older save counts from now.
   */
  tiles?: number;
  earned?: number;
  incidents?: number;
  since?: number;
}

/** Put to work, a driver's mood comes up to at least this: being given a vehicle is what a bored driver wanted. */
export const PUT_TO_WORK = 0.5;
/** Below this on the bench, the player hears they are restless; at nothing, they go. */
export const BENCH_WARN = 0.2;

const LICENCE_FEE: Record<Licence, number> = { road: 300, sea: 900, air: 2500, rail: 1500 };
const LICENCE_LABEL: Record<Licence, string> = { road: 'road licence', sea: 'sea licence', air: 'air licence', rail: 'rail licence' };
/** Of the day's second and third candidates, the share who hold a rail licence, once the fleet owns a train (docs/crewtrains.html). */
export const RAIL_SHARE = 0.12;

export const TEMPER: Record<Temper, { pace: number; incident: number; label: string }> = {
  careful: { pace: 0.9, incident: 0.5, label: 'careful' },
  steady: { pace: 1, incident: 1, label: 'steady' },
  quick: { pace: 1.12, incident: 2, label: 'quick' },
};

const RANKS: Rank[] = ['rookie', 'regular', 'veteran', 'ace'];
const RANK_AT = [0, 25, 100, 300];
/** A candidate above a rookie costs this many times the licence fee. */
const RANK_FEE = [1, 1.5, 2.5, 2.5];

export const CUT_MIN = 0.2, CUT_MAX = 0.6, CUT_DEFAULT = 0.4;

export const MODE_LABEL: Record<CutMode, string> = { hustle: 'Hustle', steady: 'Steady', coasting: 'Coasting' };

/** What the cut does to how they work: pace offset, game hours idle before moving on, urgencies they'll take. */
export const MODES: Record<CutMode, { pace: number; idle: number; takes: Urgency[] | null; urgentFit: number }> = {
  hustle: { pace: 0.06, idle: 0.5, takes: null, urgentFit: 1.5 },
  steady: { pace: 0, idle: 2, takes: null, urgentFit: 1 },
  coasting: { pace: -0.08, idle: 0, takes: ['relaxed', 'none'], urgentFit: 1 },
};

export const rankIndex = (d: Driver): number => {
  let r = 0;
  for (let k = 0; k < RANK_AT.length; k++) if (d.deliveries >= RANK_AT[k]) r = k;
  return r;
};
export const rankOf = (d: Driver): Rank => RANKS[rankIndex(d)];
/** The next rank up and the deliveries still to make for it, or null for an ace. */
export function nextRank(d: Driver): { rank: Rank; left: number } | null {
  const k = rankIndex(d) + 1;
  return k < RANKS.length ? { rank: RANKS[k], left: RANK_AT[k] - d.deliveries } : null;
}

/**
 * The tricks a driver trusts themselves with once the parts are on the vehicle (game/cpuTricks.ts): a
 * nitrous bottle on the straights and the handbrake round sharp bends. Never a rookie, and never the
 * careful sort; the steady and the quick from regular up.
 */
export function tricksOf(_d: Driver): { nitrous: boolean; drift: boolean } {
  // a working driver uses what the vehicle has fitted, whoever they are (the user, Oct 2026): the parts
  // were bought to be used, and the town's own traffic is the only traffic that drives like a learner
  return { nitrous: true, drift: true };
}

export function modeOf(cut: number): CutMode {
  return cut <= 0.3 + 1e-6 ? 'hustle' : cut <= 0.45 + 1e-6 ? 'steady' : 'coasting';
}

/** The mood the cut pulls a driver toward. */
function moodTarget(cut: number): number {
  const m = modeOf(cut);
  if (m === 'hustle') return 1;
  if (m === 'steady') return 0.7;
  return cut >= 0.6 - 1e-6 ? 0.1 : cut >= 0.55 - 1e-6 ? 0.2 : 0.3;
}

export function moodWord(mood: number): string {
  return mood >= 0.75 ? 'content' : mood >= 0.5 ? 'fine' : mood >= 0.2 ? 'restless' : 'leaving';
}

/** Which licence a vehicle needs. */
export function licenceFor(def: VehicleDef): Licence | null {
  if (def.licence) return def.licence;
  return def.kind === 'land' ? 'road' : def.kind === 'water' ? 'sea' : def.kind === 'air' ? 'air' : def.kind === 'rail' ? 'rail' : null;
}

export const mayDrive = (d: Driver, def: VehicleDef): boolean => {
  const l = licenceFor(def);
  return !!l && d.licences.includes(l);
};

/** What hiring them costs: each licence's fee, times their rank's premium. */
export function feeOf(d: Driver): number {
  const base = d.licences.reduce((s, l) => s + LICENCE_FEE[l], 0);
  return Math.round((base * RANK_FEE[rankIndex(d)]) / 10) * 10;
}

/** How long the cut and the rank give them, per game hour, to drift. */
export function driftMood(d: Driver, hours: number): void {
  if (!d.unit) {
    // a bench is not a store
    d.mood = Math.max(0, d.mood - 0.01 * hours);
    return;
  }
  const target = moodTarget(d.cut);
  if (modeOf(d.cut) === 'coasting') {
    // it only slides: at 60% a rookie goes in about three game days from content, an ace twice that
    const slide = ((d.cut - 0.45) / 0.15) * (0.75 / 72) / (rankOf(d) === 'ace' ? 2 : 1);
    d.mood = Math.max(0, d.mood - slide * hours);
  } else {
    d.mood += (target - d.mood) * Math.min(1, 0.08 * hours);
  }
}

const TEMPERS: Temper[] = ['careful', 'steady', 'steady', 'quick'];
const NOSES: (CargoClass | null)[] = ['people', 'parcel', 'freight', 'bulk', 'container', null, null];

/**
 * The day's three candidates: the same three for this world and day on every reload; the first always drives a road vehicle.
 * `trains`: the fleet owns a train, so a rail licence may turn up (docs/crewtrains.html). The rail roll is a stream of its own,
 * and a veteran's second licence is drawn from the same three as ever, so a fleet with no train meets exactly the people it
 * always did, and one with a train meets the same faces with a rail licence now and then in place of their own.
 */
export function candidates(seed: string, day: number, trains = false): Driver[] {
  const out: Driver[] = [];
  for (let k = 0; k < 3; k++) {
    const rng = mulberry32(hashString(`driver|${seed}|${day}|${k}`));
    let lic: Licence = k === 0 ? 'road' : rng() < 0.55 ? 'road' : rng() < 0.7 ? 'sea' : 'air';
    const railRng = mulberry32(hashString(`rail|${seed}|${day}|${k}`));
    const rail = trains && k > 0 && railRng() < RAIL_SHARE;
    if (rail) lic = 'rail';
    const roll = rng();
    const rank = roll < 0.6 ? 0 : roll < 0.9 ? 1 : 2;
    const licences: Licence[] = [lic];
    if (rank === 2 && rng() < 0.5) {
      const other = (['road', 'sea', 'air'] as Licence[]).filter((l) => l !== lic);
      const second = other[Math.floor(rng() * other.length)];
      if (second) licences.push(second);
    } else if (trains && rank === 2 && !rail && railRng() < 0.5) {
      // (a veteran with one licence, now and then, holds a rail one too)
      licences.push('rail');
    }
    out.push({
      id: -(day * 10 + k + 1),
      name: personName(`${seed}|${day}|${k}`),
      licences,
      temper: TEMPERS[Math.floor(rng() * TEMPERS.length)],
      nose: NOSES[Math.floor(rng() * NOSES.length)],
      deliveries: RANK_AT[rank],
      kept: 0,
      mood: 0.75,
      cut: CUT_DEFAULT,
      unit: 0,
    });
  }
  return out;
}

/** The cheats menu's full roster: every licence at every rank, and an ace holding all four. */
const ROSTER: Licence[][] = [['road'], ['sea'], ['air'], ['rail']];
const ROSTER_SIZE = ROSTER.length * 4 + 1;

/**
 * The full roster (cheats menu): one of every licence at every rank, and an ace who holds all three,
 * always there. `signed` counts how many have been hired from it, so a new face stands in each slot
 * after a hire.
 */
export function roster(seed: string, signed: number): Driver[] {
  const out: Driver[] = [];
  for (let k = 0; k < ROSTER_SIZE; k++) {
    const lic = k < ROSTER.length * 4 ? ROSTER[Math.floor(k / 4)] : ['road', 'sea', 'air', 'rail'] as Licence[];
    const rank = k < ROSTER.length * 4 ? k % 4 : 3;
    const rng = mulberry32(hashString(`roster|${seed}|${signed}|${k}`));
    out.push({
      id: -(1_000_000 + k),
      name: personName(`roster|${seed}|${signed}|${k}`),
      licences: [...lic],
      temper: TEMPERS[Math.floor(rng() * TEMPERS.length)],
      nose: NOSES[Math.floor(rng() * NOSES.length)],
      deliveries: RANK_AT[rank],
      kept: 0,
      mood: 0.75,
      cut: CUT_DEFAULT,
      unit: 0,
    });
  }
  return out;
}

/** One line for a card: "road licence · quick · veteran". */
export function driverLine(d: Driver): string {
  return `${d.licences.map((l) => LICENCE_LABEL[l]).join(' + ')} · ${TEMPER[d.temper].label} · ${rankOf(d)}`;
}
