import * as THREE from 'three';
import { ALL_VEHICLES, type VehicleDef } from './vehicles';
import { buildVehicleMesh, disposeVehicleMesh, type VehicleMesh } from '../render/vehicleMeshes';
import { railThumb } from './garageMenu';
import { speedText } from './units';
import { TECH, type Tree } from './tech';

/**
 * What the tech trees show about a model (docs/territory.html), shared by the HQ window's Tech tab
 * (game/techTab.ts): its numbers as bars against the best in its tree, and what it does for the fleet.
 * Also the little Turntable the title menu turns a model on.
 */

export const DEFS = new Map(ALL_VEHICLES.map((d) => [d.id, d]));
export const nameOf = (id: string) => DEFS.get(id)?.name ?? id;

/** The selected model on a little turntable: one small renderer, made when the window opens and let go on close. */
export class Turntable {
  canvas = document.createElement('canvas');
  private renderer: THREE.WebGLRenderer | null = null;
  private scene = new THREE.Scene();
  private cam: THREE.PerspectiveCamera;
  private held: { id: string; pivot: THREE.Object3D; mesh: VehicleMesh | null } | null = null;
  private yaw = 0.6;
  private raf = 0;
  private last = 0;
  /** How many cars of a train to stand: 1 is the engine alone, near enough to see its topper (game/toppersTab.ts). */
  railCars = 4;
  /**
   * Framed close, by the vehicle alone (game/toppersTab.ts's stands; the user, 6 Nov 2026): its length side on across
   * the stand's width, measured without any topper so every stand's zoom is the same whatever is worn, with headroom
   * above it for one. Off: far enough back for the whole model, topper and all, to fit at every angle.
   */
  tight = false;

  constructor(private w = 270, private h = 160, cls = 'stage') {
    this.cam = new THREE.PerspectiveCamera(26, w / h, 0.05, 100);
    this.canvas.className = cls;
    this.scene.add(new THREE.HemisphereLight(0xd8ecff, 0x8fb37a, 1.15));
    const sun = new THREE.DirectionalLight(0xfff1d6, 2.4);
    sun.position.set(3, 5, 4);
    this.scene.add(sun);
  }

  start(): void {
    if (!this.renderer) {
      this.renderer = new THREE.WebGLRenderer({ canvas: this.canvas, antialias: true, alpha: true });
      this.renderer.setPixelRatio(Math.min(2, window.devicePixelRatio || 1));
      this.renderer.setSize(this.w, this.h, false);
      this.renderer.toneMapping = THREE.NeutralToneMapping;
      this.renderer.toneMappingExposure = 1.05;
    }
    const loop = (now: number) => {
      this.raf = requestAnimationFrame(loop);
      this.frame(now);
    };
    cancelAnimationFrame(this.raf);
    this.raf = requestAnimationFrame(loop);
  }

  /** One turn of the stage: also called by hand when the page isn't drawing frames. */
  frame(now = performance.now()): void {
    const dt = this.last ? Math.min(0.05, (now - this.last) / 1000) : 0;
    this.last = now;
    this.yaw += dt * 0.7;
    if (this.held) this.held.pivot.rotation.y = this.yaw;
    this.renderer?.render(this.scene, this.cam);
  }

  /** Stop turning without letting the renderer go: the hover card, put away between hovers. */
  pause(): void { cancelAnimationFrame(this.raf); this.raf = 0; this.last = 0; }

  get running(): boolean { return this.raf !== 0; }

  stop(): void {
    this.pause();
    this.drop();
    this.renderer?.dispose();
    this.renderer?.forceContextLoss();
    this.renderer = null;
    // a lost context can't be had again from the same canvas: the next opening gets a fresh one
    const fresh = document.createElement('canvas');
    fresh.className = this.canvas.className;
    this.canvas.replaceWith(fresh);
    this.canvas = fresh;
  }

  /** `key`: what makes this showing different from the last (its topper, say); the model's id by default. */
  show(def: VehicleDef | undefined, key = def?.id): void {
    if (!def || this.held?.id === key) return;
    this.drop();
    let holder: THREE.Object3D, mesh: VehicleMesh | null = null;
    // with the def, so a train wears its topper as a road vehicle does (render/treats.ts dressTrainTreats)
    if (def.kind === 'rail') holder = railThumb(def.id, def, this.railCars).holder;
    else { mesh = buildVehicleMesh(def); mesh.body.position.y = mesh.lift ?? 0; holder = mesh.holder; }
    // stood on a pivot under its own middle, so it turns in place
    const pivot = new THREE.Group();
    pivot.add(holder);
    pivot.updateMatrixWorld(true);
    const box = new THREE.Box3().setFromObject(holder), c = new THREE.Vector3(), size = new THREE.Vector3();
    box.getCenter(c);
    box.getSize(size);
    holder.position.sub(new THREE.Vector3(c.x, box.min.y, c.z));
    this.scene.add(pivot);
    const tanV = Math.tan(THREE.MathUtils.degToRad(13)), tanH = tanV * (this.w / this.h);
    let dist: number, aim: number;
    if (this.tight) {
      // the vehicle alone, measured on a copy without its topper: the same zoom whatever is worn
      const copy = def.kind === 'rail' ? null : buildVehicleMesh({ ...def, topper: undefined });
      const bare = copy ? copy.holder : railThumb(def.id, undefined, this.railCars).holder;
      const vb = new THREE.Box3().setFromObject(bare), v = new THREE.Vector3();
      vb.getSize(v);
      // let the copy go as the stand lets its own go (drop): a vehicle's own way, a train's geometry
      if (copy) disposeVehicleMesh(copy);
      else bare.traverse((o) => { (o as THREE.Mesh).geometry?.dispose?.(); });
      // its length side on across the width; its height and most as much again above it, for a topper, in the height
      const len = Math.max(v.x, v.z);
      dist = Math.max((len * 0.5) / tanH, (v.y * 2.1 * 0.5) / tanV) * 1.2 + Math.min(v.x, v.z) * 0.5;
      aim = v.y * 0.85;
    } else {
      // far enough that it fits at every angle of the turn: its whole sphere inside the frame's height
      dist = (size.length() * 0.5) / Math.sin(THREE.MathUtils.degToRad(13)) * 1.08;
      aim = size.y * 0.5;
    }
    this.cam.position.set(0, aim, 0).addScaledVector(new THREE.Vector3(0, 0.42, 1).normalize(), dist);
    this.cam.lookAt(0, aim, 0);
    this.held = { id: key ?? def.id, pivot, mesh };
  }

  private drop(): void {
    if (!this.held) return;
    this.scene.remove(this.held.pivot);
    if (this.held.mesh) disposeVehicleMesh(this.held.mesh);
    else this.held.pivot.traverse((o) => { (o as THREE.Mesh).geometry?.dispose?.(); });
    this.held = null;
  }
}


// ---- the hover card: a model's numbers, as bars against the best in its own tree ----

/** One bar on the card: the number it's drawn from (bigger is better), and how a player reads it. */
export interface Stat { label: string; get: (d: VehicleDef) => number | undefined; text: (d: VehicleDef, v: number, max: number) => string }

const score = (_d: VehicleDef, v: number, max: number) => `${Math.max(1, Math.round((v / max) * 10))}/10`;
export const STATS: Stat[] = [
  { label: 'Top speed', get: (d) => d.topSpeed, text: (_d, v) => speedText(v * 12) },
  { label: 'Pick-up', get: (d) => d.accel, text: (d, v) => `0–top ${(d.topSpeed / v).toFixed(1)} s` },
  { label: 'Brakes', get: (d) => (d.kind === 'air' ? undefined : d.brake), text: score },
  { label: 'Handling', get: (d) => (d.kind === 'rail' ? undefined : d.steerRate), text: (_d, v) => `${Math.round(THREE.MathUtils.radToDeg(v))}°/s` },
  { label: 'Grip', get: (d) => (d.kind === 'water' ? d.grip : undefined), text: score },
  { label: 'Climb', get: (d) => (d.kind === 'air' ? d.climbRate : undefined), text: score },
  { label: 'Hold', get: (d) => d.capacity, text: (_d, v) => `${v} unit${v === 1 ? '' : 's'}` },
];

export const HOLD_WORD: Record<string, string> = { people: '🧍 people', parcel: '📦 parcels', freight: '📦 freight', bulk: '⛏ bulk', container: '🚢 containers' };
const SURFACE_WORD: Record<string, string> = { track: 'dirt tracks', offroad: 'grass and rough', sand: 'sand', snow: 'snow', farm: 'farm fields' };
const pct = (x: number) => `${Math.round(x * 100)}%`;

/**
 * Every bar's best in each tree, worked out once: the defs don't change in play. The trains at the top of
 * the land tree are measured against each other, or a train's hold would make every car's look empty.
 */
const BEST = new Map<string, number>();
export function best(tree: Tree, s: Stat, rail: boolean): number {
  const key = `${tree}:${rail}:${s.label}`;
  let v = BEST.get(key);
  if (v === undefined) {
    v = 0;
    for (const n of TECH) {
      const d = n.tree === tree ? DEFS.get(n.id) : undefined;
      if (!d || (d.kind === 'rail') !== rail) continue;
      const x = s.get(d);
      if (x !== undefined && x > v) v = x;
    }
    BEST.set(key, v);
  }
  return v;
}

/** What it does for you, a line each: the knacks, the ground it covers, the licence its driver needs. */
export function modifiers(d: VehicleDef): [string, string, string][] {
  const rows: [string, string, string][] = [];
  if (d.convertible) rows.push(['☀️', 'People pay more with the roof down', '+25%']);
  if (d.fareBox) rows.push(['🎟', 'Each fare pays more for every other one aboard', `+${pct(d.fareBox)} ea.`]);
  if (d.vip) rows.push(['🥂', 'VIP fares pay more; a hard knock takes a tenth off', `+${pct(d.vip)}`]);
  if (d.siren) rows.push(['🚨', 'Loads aboard lose value slower', `−${pct(d.siren)}`]);
  if (d.tipper) rows.push(['⛏', 'Bulk it delivers pays more', `+${pct(d.tipper)}`]);
  if (d.postal) rows.push(['✉️', 'Parcels pay more, and more per parcel aboard', `+${pct(d.postal)}`]);
  if (d.wrecker) rows.push(['🪝', 'Owned: your hired drivers’ tow bills cut', `−${pct(d.wrecker)}`]);
  if (d.dozer) rows.push(['🚜', 'Owned: the bulldoze tool (X) costs less', `−${pct(d.dozer)}`]);
  if (d.kind === 'land') {
    rows.push(['⛰', 'Steepest ground it climbs', d.maxGrade >= 2 ? 'steep' : 'slopes']);
    rows.push(['↗', 'Speed lost per step uphill', `−${speedText(d.uphillPenalty * 12)}`]);
    rows.push(['🪜', 'Curbs and ledges it hops', d.curb ? `${d.curb} step${d.curb === 1 ? '' : 's'}` : 'none']);
    rows.push(['💧', d.wade >= 99 ? `Swims, at ${speedText((d.swimSpeed ?? 0) * 12)} afloat` : 'Water it fords', d.wade >= 99 ? 'amphibious' : d.wade ? `${d.wade} step${d.wade === 1 ? '' : 's'} deep` : 'keep dry']);
    for (const [k, m] of Object.entries(d.surface ?? {})) if (m && m !== 1) rows.push([m > 1 ? '⚡' : '🐢', `${m > 1 ? 'Faster' : 'Slower'} on ${SURFACE_WORD[k] ?? k}`, `×${m}`]);
    if (d.trailer) rows.push(['🚛', 'Pulls a trailer: swing wide at corners', 'trailer']);
    if (d.drift) rows.push(['🌀', 'Handbrake slides as stock (Space)', 'drift']);
    if (d.burnout) rows.push(['🏁', 'Race gearbox and brakes', 'stock']);
  } else if (d.kind === 'water') {
    rows.push(['⚓', 'Shallowest water it floats in', `${d.minDepth} step${d.minDepth === 1 ? '' : 's'}`]);
    if (d.sail) rows.push(['⛵', 'Sails: the wind sets its pace', 'wind']);
  } else if (d.kind === 'air') {
    const wheels = d.jet ?? d.gear;
    if (d.rotor) rows.push(['🚁', 'Hovers, turns on the spot, lands on helipads', 'VTOL']);
    else if (!wheels) rows.push(['🎈', 'Hovers and sets down anywhere', 'anywhere']);
    if (wheels) rows.push(['🛬', d.jet ? 'Takes off from airports only' : 'Lands on any airfield’s runway', `${wheels.runway}-tile strip`]);
    if (d.minSpeed > 0) rows.push(['⚠️', 'Stalls below', speedText(d.minSpeed * 12)]);
  } else {
    rows.push(['🛤', 'Runs on rails, sold only by train dealers at the bigger stations', 'rail']);
  }
  const lic = d.licence ?? (d.kind === 'land' ? 'road' : d.kind === 'water' ? 'sea' : d.kind === 'air' ? 'air' : null);
  rows.push(['🪪', 'Licence a hired driver needs', lic ? `${lic}` : 'none']);
  return rows;
}
