import * as THREE from 'three';
import { N, STEP, heightAt, type World } from '../../world/tiles';
import { surfaceNear } from '../../world/surface';
import { VEHICLES, type VehicleDef, type VehicleState } from '../vehicles';
import { disposeVehicleMesh, poseVehicleMesh, setVehicleLod, trafficVehicleMesh, type VehicleMesh } from '../../render/vehicleMeshes';
import { TRAFFIC_VIEW } from '../traffic';
import type { Pt } from './venues';

/**
 * What the events are made of (docs/events.html): crowds of townsfolk (the pedestrians' little spheres, standing,
 * cheering, wandering a lot), vehicles that follow a way through the streets at the event's pace rather than
 * driving themselves, and a few simple props. Everything is in world tiles, in a group at the scene's origin.
 */

// ---- people -------------------------------------------------------------------------------------------------

const RADIUS = 0.045;
const COLOURS = [0xe2412f, 0x2f7fb5, 0xf2c14e, 0x3f9b4a, 0x8e5cc7, 0xf28c38, 0x2bb3a3, 0xf49ab5, 0xf4f2ec, 0x3a3f45, 0xc9463d, 0x6fb8e0];
const PERSON = new THREE.IcosahedronGeometry(RADIUS, 1);
const PERSON_MAT = new THREE.MeshStandardMaterial({ roughness: 0.6, metalness: 0 });
/** Most townsfolk an event brings out (docs/events.html budgets). */
const MAX_CROWD = 64;

interface Person { x: number; z: number; y: number; tx: number; tz: number; phase: number; speed: number; wait: number }

/**
 * A crowd: up to MAX_CROWD people, each standing at a spot (lining a street, round a square) or wandering an
 * area. `shown` is how many of them are out (they come and go one by one); `cheer` how hard they bounce.
 */
export class Crowd {
  readonly mesh: THREE.InstancedMesh;
  private people: Person[] = [];
  private m = new THREE.Matrix4();
  private t = 0;
  shown = 0;
  cheer = 0;
  /** Wanderers: the area they wander, in world tiles (null: they stand still). */
  roam: { x0: number; z0: number; x1: number; z1: number } | null = null;

  /** Members placed by hand each frame (a marching column) rather than standing or wandering. */
  manual = false;

  constructor(parent: THREE.Object3D, private ground: (x: number, z: number) => number, seed: number, colours: number[] = COLOURS) {
    this.mesh = new THREE.InstancedMesh(PERSON, PERSON_MAT, MAX_CROWD);
    this.mesh.count = 0;
    this.mesh.frustumCulled = false;
    const c = new THREE.Color();
    for (let i = 0; i < MAX_CROWD; i++) this.mesh.setColorAt(i, c.setHex(colours[(i * 7 + seed) % colours.length]).offsetHSL(0, 0, ((i * 37 + seed) % 13) / 13 * 0.12 - 0.06));
    parent.add(this.mesh);
  }

  /** Put member i at (x, z) world tiles this frame (a column on the march), stepping as it goes. */
  setAt(i: number, x: number, z: number, dt: number): void {
    const p = this.people[i];
    if (!p) return;
    const moved = Math.hypot(x - p.x, z - p.z);
    p.x = x; p.z = z; p.y = this.ground(x, z);
    p.phase += moved > 1e-4 ? dt * 9 : 0;
  }

  get size(): number { return this.people.length; }

  /** Someone standing at (x, z), world tiles (at height `y`, world units, if given: a seat in the stands). */
  add(x: number, z: number, y?: number): void {
    if (this.people.length >= MAX_CROWD) return;
    this.people.push({ x, z, y: y ?? this.ground(x, z), tx: x, tz: z, phase: (this.people.length * 2.39) % 6.28, speed: 0.12 + (this.people.length % 5) * 0.03, wait: (this.people.length % 7) * 0.6 });
  }

  update(dt: number): void {
    this.t += dt;
    const n = Math.min(this.people.length, Math.max(0, Math.round(this.shown)));
    const r = this.roam;
    for (let i = 0; i < n; i++) {
      const p = this.people[i];
      if (r && !this.manual) {
        // wander: a few steps to somewhere else on the ground, a pause, again
        const dx = p.tx - p.x, dz = p.tz - p.z, d = Math.hypot(dx, dz);
        if (d < 0.05) {
          p.wait -= dt;
          if (p.wait <= 0) {
            p.tx = r.x0 + ((Math.sin(this.t * 1.7 + i * 12.9898) * 43758.5453) % 1 + 1) % 1 * (r.x1 - r.x0);
            p.tz = r.z0 + ((Math.sin(this.t * 2.3 + i * 78.233) * 12543.123) % 1 + 1) % 1 * (r.z1 - r.z0);
            p.wait = 1.5 + (i % 5);
          }
        } else {
          const step = Math.min(d, p.speed * dt);
          p.x += (dx / d) * step; p.z += (dz / d) * step;
          p.y = this.ground(p.x, p.z);
          p.phase += dt * 8;
        }
      }
      const bob = this.cheer > 0 ? Math.abs(Math.sin(this.t * (6 + (i % 3)) + p.phase)) * 0.05 * this.cheer : r || this.manual ? Math.abs(Math.sin(p.phase)) * 0.015 : 0;
      this.m.makeTranslation(p.x, p.y + RADIUS + bob, p.z);
      this.mesh.setMatrixAt(i, this.m);
    }
    this.mesh.count = n;
    if (n) this.mesh.instanceMatrix.needsUpdate = true;
  }

  dispose(): void { this.mesh.removeFromParent(); this.mesh.dispose(); }
}

// ---- vehicles on a way --------------------------------------------------------------------------------------

/** A way: points in world tiles and the distance along it to each. */
export class Way {
  readonly L: number[] = [0];
  constructor(readonly pts: Pt[]) {
    for (let k = 1; k < pts.length; k++) this.L.push(this.L[k - 1] + Math.hypot(pts[k].x - pts[k - 1].x, pts[k].z - pts[k - 1].z));
  }
  get length(): number { return this.L[this.L.length - 1]; }
  /** The point s along it, and its heading (atan2(dx, dz), as the vehicles have it). */
  at(s: number): { x: number; z: number; heading: number } {
    const P = this.pts, L = this.L;
    if (P.length < 2) return { x: P[0].x, z: P[0].z, heading: 0 };
    s = Math.max(0, Math.min(this.length, s));
    let lo = 1, hi = P.length - 1;
    while (lo < hi) { const m = (lo + hi) >> 1; if (L[m] < s) lo = m + 1; else hi = m; }
    const a = P[lo - 1], b = P[lo], seg = L[lo] - L[lo - 1] || 1, t = (s - L[lo - 1]) / seg;
    // ease the heading round a corner over the half tile either side of it
    let heading = Math.atan2(b.x - a.x, b.z - a.z);
    if (t > 0.6 && lo + 1 < P.length) {
      const c = P[lo + 1];
      const next = Math.atan2(c.x - b.x, c.z - b.z);
      heading = lerpAngle(heading, next, (t - 0.6) / 0.8);
    } else if (t < 0.4 && lo >= 2) {
      const z = P[lo - 2];
      const prev = Math.atan2(a.x - z.x, a.z - z.z);
      heading = lerpAngle(prev, heading, 0.5 + t / 0.8);
    }
    return { x: a.x + (b.x - a.x) * t, z: a.z + (b.z - a.z) * t, heading };
  }
}

function lerpAngle(a: number, b: number, t: number): number {
  let d = b - a;
  while (d > Math.PI) d -= Math.PI * 2;
  while (d < -Math.PI) d += Math.PI * 2;
  return a + d * Math.max(0, Math.min(1, t));
}

/** A model in other colours, one definition a colouring so they share a body. */
const DEFS = new Map<string, VehicleDef>();
export function dressed(id: string, color?: number, livery?: number): VehicleDef {
  const base = VEHICLES.find((v) => v.id === id) ?? VEHICLES[0];
  if (color === undefined) return base;
  const key = `${id}|${color}|${livery ?? ''}`;
  let d = DEFS.get(key);
  if (!d) DEFS.set(key, (d = { ...base, color, ...(livery !== undefined ? { livery } : {}) } as VehicleDef));
  return d;
}

/** One of an event's vehicles: its body, and a state that is only ever posed, never stepped. */
export class Rig {
  readonly mesh: VehicleMesh;
  readonly state: VehicleState;
  /** Its county, for the traffic to stop for it (EVENT_OBSTACLES), and its place in that county's frame. */
  w: World | null = null;
  readonly local: VehicleState;
  shown = true;

  constructor(parent: THREE.Object3D, readonly def: VehicleDef, riders = 0) {
    this.mesh = trafficVehicleMesh(def, VEHICLES.includes(def));
    this.mesh.holder.userData.rig = true;
    parent.add(this.mesh.holder);
    const s = { x: 0, y: 0, z: 0, heading: 0, v: 0, pitch: 0, roll: 0, bob: 0, lean: 0, wheelSpin: 0, steerVis: 0, power: 1, blocked: 0, trailerHeading: 0, sailAngle: 0, surfaceY: NaN, riders };
    this.state = s as unknown as VehicleState;
    this.local = { ...s } as unknown as VehicleState;
  }

  /** Put it at (x, z) world tiles, heading `h`, on whatever the road is there, going `v` tiles a second. */
  place(worldAt: (cx: number, cz: number) => World | null, x: number, z: number, h: number, v: number, dt: number): void {
    const s = this.state;
    const w = worldAt(Math.floor(x / N), Math.floor(z / N));
    this.w = w;
    if (!w) { this.hide(); return; }
    const lx = x - w.ox, lz = z - w.oz;
    const y = surfaceNear(w, lx, lz, s.y || heightAt(w, Math.min(N - 0.01, Math.max(0, lx)), Math.min(N - 0.01, Math.max(0, lz))) + 0.3);
    s.x = x; s.z = z; s.y = y; s.heading = h; s.v = v; s.trailerHeading = h;
    s.wheelSpin += (v * dt) / 0.12;
    const l = this.local;
    l.x = lx; l.z = lz; l.y = y; l.heading = h; l.v = v;
    this.mesh.holder.visible = this.shown = true;
    poseVehicleMesh(this.mesh, s, this.def, w);
    // small on screen: the far body, as traffic's
    const V = TRAFFIC_VIEW;
    if (this.mesh.far && V.on && V.lod) {
      const d = Math.max(1, Math.hypot(x - V.x, y - V.y, z - V.z));
      const px = (2 * 0.6 * V.px) / d;
      setVehicleLod(this.mesh, this.mesh.lod ? px < V.lodNear : px < V.lodFar);
    }
  }

  /** Afloat at (x, z) world tiles on the water there, heading `h`, sails set to `sail`, rocking a little. */
  float(worldAt: (cx: number, cz: number) => World | null, x: number, z: number, h: number, v: number, dt: number, sail = 0): void {
    const w = worldAt(Math.floor(x / N), Math.floor(z / N));
    this.w = w;
    if (!w) { this.hide(); return; }
    const lx = Math.min(N - 0.01, Math.max(0, x - w.ox)), lz = Math.min(N - 0.01, Math.max(0, z - w.oz));
    const i = Math.floor(lx) + Math.floor(lz) * N;
    const wl = w.water[i];
    const s = this.state;
    s.x = x; s.z = z; s.y = wl >= 0 ? wl * STEP : heightAt(w, lx, lz);
    s.heading = h; s.v = v; s.sailAngle = sail; s.power = Math.min(1, Math.abs(v));
    this.t += dt;
    s.roll = Math.sin(this.t * 1.3 + this.def.color) * 0.04; s.pitch = Math.sin(this.t * 0.9) * 0.02;
    this.local.x = lx; this.local.z = lz; this.local.y = s.y; this.local.heading = h; this.local.v = v;
    this.mesh.holder.visible = this.shown = true;
    poseVehicleMesh(this.mesh, s, this.def, w);
    for (const sp of this.mesh.spinners) sp.obj.rotation[sp.axis] += sp.speed * s.power * dt;
  }

  /** Aloft at (x, y, z) world units, nose along `h`, pitched and banked, its rotors or propeller turning. */
  fly(x: number, y: number, z: number, h: number, pitch: number, roll: number, dt: number): void {
    const m = this.mesh;
    m.holder.visible = this.shown = true;
    m.root.position.set(x, y, z);
    m.root.rotation.set(pitch, h, roll, 'YXZ');
    for (const sp of m.spinners) sp.obj.rotation[sp.axis] += sp.speed * dt;
    const s = this.state;
    s.x = x; s.y = y; s.z = z; s.heading = h;
  }
  private t = 0;

  hide(): void { this.mesh.holder.visible = this.shown = false; }

  dispose(): void { this.mesh.holder.removeFromParent(); disposeVehicleMesh(this.mesh); }
}

/** Ground height at a world-tile point, through whichever county it falls in (0 off the map in memory). */
export function groundOf(worldAt: (cx: number, cz: number) => World | null): (x: number, z: number) => number {
  return (x, z) => {
    const w = worldAt(Math.floor(x / N), Math.floor(z / N));
    if (!w) return 0;
    return heightAt(w, Math.min(N - 0.01, Math.max(0, x - w.ox)), Math.min(N - 0.01, Math.max(0, z - w.oz)));
  };
}

// ---- props ------------------------------------------------------------------------------------------------------

const box = new THREE.BoxGeometry(1, 1, 1);
const MATS = new Map<number, THREE.MeshStandardMaterial>();
export function flat(colour: number, glow = 0): THREE.MeshStandardMaterial {
  const key = colour * 4 + Math.round(glow * 3);
  let m = MATS.get(key);
  if (!m) MATS.set(key, (m = new THREE.MeshStandardMaterial({ color: colour, roughness: 0.7, flatShading: true, ...(glow ? { emissive: colour, emissiveIntensity: glow } : {}) })));
  return m;
}

/** A box prop standing on y, world units, turned `yaw`. */
export function block(parent: THREE.Object3D, x: number, y: number, z: number, w: number, h: number, d: number, colour: number, yaw = 0, glow = 0): THREE.Mesh {
  const m = new THREE.Mesh(box, flat(colour, glow));
  m.scale.set(w, h, d);
  m.position.set(x, y + h / 2, z);
  m.rotation.y = yaw;
  m.castShadow = h > 0.08;
  parent.add(m);
  return m;
}

/** Take a group's props away: their own geometry and materials go with them, the shared ones (box, flat colours, people) stay. */
export function clearGroup(g: THREE.Object3D): void {
  g.removeFromParent();
  const shared = new Set<THREE.Material>([...MATS.values(), PERSON_MAT]);
  const walk = (o: THREE.Object3D) => {
    // a vehicle's body wears traffic's shared template: never ours to throw away (Rig.dispose lets it go)
    if (o.userData.rig) return;
    const m = o as THREE.Mesh;
    if (m.isMesh || (o as THREE.Points).isPoints) {
      if (m.geometry !== box && m.geometry !== PERSON) m.geometry.dispose();
      for (const mat of Array.isArray(m.material) ? m.material : [m.material]) if (mat && !shared.has(mat)) mat.dispose();
    }
    for (const c of o.children) walk(c);
  };
  walk(g);
}

// ---- lights and water ------------------------------------------------------------------------------------------------

/** The water's surface under a world point (its county in memory), or the ground. */
export function waterY(ctx: { worldAt(cx: number, cz: number): World | null; ground(x: number, z: number): number }, x: number, z: number): number {
  const w = ctx.worldAt(Math.floor(x / N), Math.floor(z / N));
  if (!w) return 0;
  const i = Math.floor(x - w.ox) + Math.floor(z - w.oz) * N;
  return w.water[i] >= 0 ? w.water[i] * STEP : ctx.ground(x, z);
}

/** Bulbs: a pool of small glowing spheres (strung on boats, round a tree), placed by hand each frame. */
export class Bulbs {
  readonly mesh: THREE.InstancedMesh;
  private m = new THREE.Matrix4();
  private n = 0;
  constructor(parent: THREE.Object3D, max: number, colours: number[], r = 0.04) {
    // brighter than white, so the bloom takes them up as it does lit windows
    this.mesh = new THREE.InstancedMesh(new THREE.IcosahedronGeometry(r, 1), new THREE.MeshBasicMaterial({ color: 0xffffff, toneMapped: false }), max);
    this.mesh.frustumCulled = false;
    const c = new THREE.Color();
    for (let i = 0; i < max; i++) this.mesh.setColorAt(i, c.setHex(colours[i % colours.length]).multiplyScalar(2.6));
    this.mesh.count = 0;
    parent.add(this.mesh);
  }
  begin(): void { this.n = 0; }
  at(x: number, y: number, z: number): void {
    if (this.n >= this.mesh.instanceMatrix.count) return;
    this.m.makeTranslation(x, y, z);
    this.mesh.setMatrixAt(this.n++, this.m);
  }
  end(): void { this.mesh.count = this.n; this.mesh.instanceMatrix.needsUpdate = true; }
}

/** A searchlight's beam: a long pale cone, brightest at its foot. */
export function beam(parent: THREE.Object3D): THREE.Group {
  const g = new THREE.Group();
  const geo = new THREE.CylinderGeometry(1.6, 0.06, 26, 14, 1, true).translate(0, 13, 0);
  const col: number[] = [];
  const pos = geo.getAttribute('position');
  for (let i = 0; i < pos.count; i++) { const k = 1 - pos.getY(i) / 26; col.push(k, k, k * 0.95); }
  geo.setAttribute('color', new THREE.Float32BufferAttribute(col, 3));
  const m = new THREE.Mesh(geo, new THREE.MeshBasicMaterial({ color: 0xfff6d8, vertexColors: true, transparent: true, opacity: 0.16, blending: THREE.AdditiveBlending, depthWrite: false, side: THREE.DoubleSide }));
  m.renderOrder = 4;
  g.add(m);
  parent.add(g);
  return g;
}

