import type { TownKind } from '../world/tiles';

/**
 * Carriage (docs/rivals.html, "Standing in a town"; docs/standing.html): who has been carrying each
 * town's trade lately. One decaying dollar figure per carrier per town — 'you' (the player and their
 * hired drivers), a rival firm's id, or '' for the anonymous haulers — written at every delivery beside
 * the town credit the ledger already makes. It is the only measure of a fleet's standing in a town: every
 * rung of the ladder (RUNGS) is read from it. The top rung is the town's territory (once called its
 * preferred carrier): it flies its colours on the town hall, pays half the levy there, and has first
 * refusal on the town's loads; territory.ts judges its property on top.
 *
 * Nothing moves a town's mind but goods carried. Everyone's figure decays on the same game clock, so a
 * town nobody is in keeps the shares it had: nothing catches up off screen.
 */

export const CARRIAGE = {
  /** Game hours for a carrier's figure to halve: standing is about lately. */
  halfLife: 72,
  /** A named carrier needs this share of the town's trade, and this lead over the next named one, to be preferred… */
  prefer: 0.35, lead: 1.25,
  /** …and keeps it until its share falls below this, or someone else meets both bars. */
  keep: 0.28,
  /** Dollars of trade (decayed) a town must have seen before anyone can be preferred there. */
  least: 150,
  /** The preferred carrier pays this share of the town's levy. */
  levy: 0.5,
  /** Seconds a fresh load in the town is held for the preferred carrier's drivers. */
  refusal: 25,
  /** The preferred carrier pays this share of a lot's price in that town. */
  deeds: 0.9,
  /**
   * The momentum of a town's own trade (docs/standing.html): what its anonymous haulers' figure stands at,
   * in dollars, by its size, everywhere. Measured Oct 2026 (the cargo study): a town beside the player sat
   * at 3–12× the old seed, from its real vans, while a far one sat exactly on it, so a far village fell to
   * one long haul and the town next to the HQ never fell at all. Set so that taking a town with no rival
   * firm in it is about 6 / 9 / 12 / 16 / 30 typical ($200) deliveries, wherever it is.
   */
  momentum: { rural: 2200, suburb: 3300, city: 4400, metro: 5900, mega: 11000 } as Record<TownKind, number>,
  /** No one delivery counts for more than this share of a town's momentum: a lucky long haul is a step, never the town. */
  oneLoad: 0.1,
};

/** The player's company, as a town sees it. */
export const YOU = 'you';

/** The rungs of the ladder (docs/standing.html), by index. */
export const RUNG = { stranger: 0, known: 1, regular: 2, trusted: 3, territory: 4 } as const;

/**
 * The fewest of the player's fleet's loads into or out of a town (ever, not decayed) before each rung above Known
 * may be taken there, whatever the share (the user, 2 Nov 2026: one big load made a new game a Regular at once).
 */
export const LOADS_FOR: Record<number, number> = { [RUNG.regular]: 5, [RUNG.trusted]: 10, [RUNG.territory]: 15 };

/**
 * The ladder: a carrier's rung in a town, from its share of the town's carriage alone. Known is any trade
 * lately; Regular and Trusted are taken at `at` and kept down to `keep` (once the town has seen the `least`);
 * Territory is CARRIAGE.prefer with a CARRIAGE.lead over the next fleet, kept down to CARRIAGE.keep.
 */
export const RUNGS: { name: string; at: number; keep: number }[] = [
  { name: 'Stranger', at: 0, keep: 0 },
  { name: 'Known', at: 0, keep: 0 },
  { name: 'Regular', at: 0.1, keep: 0.08 },
  { name: 'Trusted', at: 0.2, keep: 0.16 },
  { name: 'Territory', at: CARRIAGE.prefer, keep: CARRIAGE.keep },
];

/**
 * Online: the other players' fleets are carriers too, named "p:<id>" (shared/protocol.ts). Whoever knows
 * them (src/net) says here what each is called and what colour it flies.
 */
export const OTHERS: { name: (who: string) => string | null; colour: (who: string) => number | null } = { name: () => null, colour: () => null };

interface Tally {
  /** Decayed dollars by carrier. */
  v: Record<string, number>;
  /** The game hour those were last brought up to date. */
  at: number;
  /** The preferred carrier ('' for none), and the game day it took the town. */
  pref: string;
  since: number;
  /** Each named carrier's rung below Territory (Known to Trusted), remembered for the keep. */
  r: Record<string, number>;
  /** The player's fleet's loads into or out of the town, ever (LOADS_FOR). */
  n: number;
}

export interface Share { who: string; v: number; share: number }

/** The saved form: per town key, [hour, preferred, since, { carrier: dollars to the dime }, { carrier: rung }, the player's loads]. */
type SavedCarriage = Record<string, [number, string, number, Record<string, number>, Record<string, number>?, number?]>;

export class Carriage {
  private towns = new Map<string, Tally>();
  /** A town's preferred carrier has changed: `was` and `now` are carriers, '' for none. */
  onChange: ((townKey: string, was: string, now: string) => void) | null = null;
  /** A carrier's rung in a town has changed (RUNG indices, Territory included). */
  onRung: ((townKey: string, who: string, was: number, now: number) => void) | null = null;
  /** Whether the town's holder pays no levy there at all (strong territory, judged by territory.ts). */
  levyFree: (key: string, who: string) => boolean = () => false;
  /**
   * The town's background trade (docs/territory.html, "When you leave"): dollars a game hour the anonymous
   * haulers carry for a town whose island isn't being simulated, 0 where real traffic is doing it. Without
   * it a town nobody is in would keep its shares for ever; with it, a town you stop serving slips away.
   */
  background: (key: string) => number = () => 0;
  /**
   * What the anonymous haulers usually carry for a town, dollars a game hour, wherever it is. A town is
   * first counted with that already on its books (rate × τ, where the decaying figure settles), so it
   * has had trade all along: one load from a driver who happens by is a sliver of it, not all of it.
   */
  usual: (key: string) => number = () => 0;
  /** Towns from a save made before they were seeded with their usual trade: topped up when next seen. */
  private unseeded = new Set<string>();

  constructor(private clock: () => number) {}

  /** Game hours a figure's trade adds up to, in the steady state: rate × this is where it settles. */
  static readonly TAU = CARRIAGE.halfLife / Math.LN2;
  /** How many times longer than usual a town remembers the player's trade (the Press, game/factions): 1 as a rule. */
  static memory: (key: string) => number = () => 1;

  private roll(t: Tally, key: string): void {
    const now = this.clock();
    if (now <= t.at) return;
    const k = 0.5 ** ((now - t.at) / CARRIAGE.halfLife);
    // the press's say in how long a town remembers the player's trade (docs/factions.html)
    const mine = Carriage.memory(key);
    const kYou = mine === 1 ? k : 0.5 ** ((now - t.at) / (CARRIAGE.halfLife * mine));
    for (const c of Object.keys(t.v)) {
      t.v[c] *= c === YOU ? kYou : k;
      if (t.v[c] < 0.5) delete t.v[c];
    }
    // the background trade credited every hour in between, summed exactly: c·τ·(1 − k)
    const bg = this.background(key);
    if (bg > 0) t.v[''] = (t.v[''] ?? 0) + bg * Carriage.TAU * (1 - k);
    // and never below the town's own momentum: its haulers are always at it, watched or not
    const base = this.usual(key) * Carriage.TAU;
    if (base > 0 && (t.v[''] ?? 0) < base) t.v[''] = base;
    t.at = now;
  }

  private tally(key: string, make: boolean): Tally | null {
    let t = this.towns.get(key);
    if (!t && make) {
      t = { v: {}, at: this.clock(), pref: '', since: 0, r: {}, n: 0 };
      this.towns.set(key, t);
      this.unseeded.add(key);
    }
    if (t) this.roll(t, key);
    if (t && this.unseeded.delete(key)) {
      const base = this.usual(key) * Carriage.TAU;
      if ((t.v[''] ?? 0) < base) t.v[''] = base;
    }
    return t ?? null;
  }

  /** Every town with a tally. */
  keys(): string[] { return [...this.towns.keys()]; }

  /** Bring a town up to the hour, and let it choose again if the background trade has moved it. */
  touch(key: string): void {
    const t = this.tally(key, false);
    if (t) this.decide(key, t);
  }

  /** Goods carried for a town: `amount` dollars of its trade, by `who`. */
  credit(key: string, who: string, amount: number, load = false): void {
    if (!(amount > 0)) return;
    // a load into or out of the town by the player's fleet counts toward the rungs' least (LOADS_FOR)
    if (load && who === YOU) { const t0 = this.tally(key, true)!; t0.n = (t0.n ?? 0) + 1; }
    // a named carrier's one delivery is at most CARRIAGE.oneLoad of the town's momentum
    const base = this.usual(key) * Carriage.TAU;
    if (who && base > 0) amount = Math.min(amount, base * CARRIAGE.oneLoad);
    const t = this.tally(key, true)!;
    t.v[who] = (t.v[who] ?? 0) + amount;
    this.decide(key, t);
  }

  /** Knock a carrier's figure down by a share (the bulldozer's penalty on a rival's building). */
  dent(key: string, who: string, share: number): void {
    const t = this.tally(key, false);
    if (!t || !t.v[who]) return;
    t.v[who] *= 1 - share;
    this.decide(key, t);
  }

  /** Take a carrier out of every town (a firm that has folded), and let the towns choose again. */
  forget(who: string): void {
    for (const [key, t] of this.towns) {
      if (!(who in t.v) && t.pref !== who) continue;
      delete t.v[who];
      this.decide(key, t);
    }
  }

  /**
   * Who holds the town now, with the hysteresis: taken at 35% and a 1.25× lead, kept until 28%; then every
   * named carrier's rung below it, each taken at its bar and kept down to its keep.
   */
  private decide(key: string, t: Tally): void {
    const total = Object.values(t.v).reduce((s, v) => s + v, 0);
    const named = Object.entries(t.v).filter(([c]) => c !== '').sort((a, b) => b[1] - a[1]);
    // the player's fleet must have run enough loads here for a rung, whatever its share; other carriers needn't
    const enough = (c: string, rung: number) => c !== YOU || (t.n ?? 0) >= (LOADS_FOR[rung] ?? 0);
    const before = new Map<string, number>();
    for (const c of new Set([...Object.keys(t.r), ...named.map(([c]) => c), t.pref])) if (c) before.set(c, this.rungIn(t, c));
    let pref = t.pref;
    if (total < CARRIAGE.least) pref = '';
    else {
      const [top, second] = named;
      const takes = top && top[1] / total >= CARRIAGE.prefer && top[1] >= CARRIAGE.lead * (second?.[1] ?? 0) && enough(top[0], RUNG.territory);
      if (takes) pref = top[0];
      else if (pref && (t.v[pref] ?? 0) / total < CARRIAGE.keep) pref = '';
    }
    const r: Record<string, number> = {};
    for (const [c, v] of named) {
      if (c === pref || v < 0.5) continue;
      const s = total > 0 ? v / total : 0;
      let k = t.r[c] ?? RUNG.known;
      while (k > RUNG.known && s < RUNGS[k].keep) k--;
      if (total >= CARRIAGE.least) for (let j = RUNG.regular; j <= RUNG.trusted; j++) if (s >= RUNGS[j].at && enough(c, j)) k = Math.max(k, j);
      r[c] = Math.min(RUNG.trusted, k);
    }
    t.r = r;
    if (pref !== t.pref) {
      const was = t.pref;
      t.pref = pref;
      t.since = Math.floor(this.clock() / 24);
      this.onChange?.(key, was, pref);
    }
    if (!this.onRung) return;
    for (const c of new Set([...before.keys(), ...Object.keys(r), pref])) {
      if (!c) continue;
      const was = before.get(c) ?? 0, now = this.rungIn(t, c);
      if (was !== now) this.onRung(key, c, was, now);
    }
  }

  private rungIn(t: Tally, who: string): number {
    return who && t.pref === who ? RUNG.territory : t.r[who] ?? 0;
  }

  /** The player's fleet's loads into or out of a town, ever (LOADS_FOR); `add` counts more (the gates). */
  loadsIn(key: string, add = 0): number {
    const t = this.tally(key, add > 0);
    if (t && add > 0) t.n = (t.n ?? 0) + add;
    return t?.n ?? 0;
  }

  /** A carrier's rung in a town (RUNG): Stranger to Territory. */
  rungOf(key: string, who: string): number {
    const t = this.tally(key, false);
    return t ? this.rungIn(t, who) : 0;
  }

  /** Every town where a carrier stands above Stranger, with its rung, highest first. */
  rungs(who: string): { key: string; rung: number }[] {
    const out: { key: string; rung: number }[] = [];
    for (const key of this.towns.keys()) {
      const rung = this.rungOf(key, who);
      if (rung > 0) out.push({ key, rung });
    }
    return out.sort((a, b) => b.rung - a.rung);
  }

  /** The town's preferred carrier, '' for none. */
  preferred(key: string): string { return this.towns.get(key)?.pref ?? ''; }
  /** The game day the preferred carrier took the town. */
  since(key: string): number { return this.towns.get(key)?.since ?? 0; }

  /** The levy multiplier for `who` in this town: half for its territory's holder, nothing when that is strong. */
  levyMul(key: string, who: string): number {
    if (!who || this.preferred(key) !== who) return 1;
    return this.levyFree(key, who) ? 0 : CARRIAGE.levy;
  }

  /** Everyone's share of the town's trade lately, biggest first; the anonymous haulers are ''. */
  shares(key: string): Share[] {
    const t = this.tally(key, false);
    if (!t) return [];
    const total = Object.values(t.v).reduce((s, v) => s + v, 0);
    if (total <= 0) return [];
    return Object.entries(t.v).map(([who, v]) => ({ who, v, share: v / total })).sort((a, b) => b.v - a.v);
  }

  /**
   * A carrier's say in what the town builds (docs/lobbying.html): its share of the town's trade lately,
   * or nothing until the town has seen the `least` a preferred carrier needs. It is a probability.
   */
  influence(key: string, who: string): number {
    const t = this.tally(key, false);
    if (!t) return 0;
    const total = Object.values(t.v).reduce((s, v) => s + v, 0);
    return total < CARRIAGE.least ? 0 : Math.max(0, Math.min(1, (t.v[who] ?? 0) / total));
  }

  /** A carrier's share of the town's trade lately. */
  shareOf(key: string, who: string): number {
    return this.shares(key).find((s) => s.who === who)?.share ?? 0;
  }

  /**
   * Dollars more trade `who` would have to carry for the town (on top of everyone as they are) to take
   * it: enough for 35% of the whole and a 1.25× lead over every other named carrier. 0 when it is theirs.
   */
  gap(key: string, who: string): number {
    if (this.preferred(key) === who) return 0;
    return this.need(key, who, CARRIAGE.prefer, CARRIAGE.lead);
  }

  /**
   * Dollars more trade `who` would have to carry for the town (everyone else as they are) for `share` of the
   * whole and, when `lead` is given, that many times the next named carrier's figure; and the `least` the
   * town must have seen (just a dollar of figure for Known, `share` 0). 0 when already there.
   */
  need(key: string, who: string, share: number, lead = 0): number {
    const t = this.tally(key, false);
    const v = t?.v[who] ?? 0;
    const total = t ? Object.values(t.v).reduce((s, x) => s + x, 0) : 0;
    const rival = t ? Math.max(0, ...Object.entries(t.v).filter(([c]) => c && c !== who).map(([, x]) => x)) : 0;
    const bySh = (share * total - v) / (1 - share);
    const byLead = lead ? lead * rival - v : 0;
    const byLeast = share > 0 ? CARRIAGE.least - total : 1 - v;
    return Math.max(0, Math.ceil(Math.max(bySh, byLead, byLeast)));
  }

  /** The named carrier with the biggest figure in the town other than `who`, with its share; null if none. */
  nextFleet(key: string, who: string): Share | null {
    return this.shares(key).find((s) => s.who && s.who !== who) ?? null;
  }

  /**
   * Game hours until `who`'s share falls below `keep` with no more trade from them: everyone's figure decays
   * on the one half-life while the town's background trade tops the haulers up. Infinity when the town has no
   * background trade (its island is ticking: real traffic decides), 0 when already below.
   */
  outlook(key: string, who: string, keep: number): number {
    const sh = this.shares(key);
    const p = sh.find((x) => x.who === who)?.v ?? 0;
    const rest = sh.reduce((s, x) => s + x.v, 0) - p;
    const bg = this.background(key) * Carriage.TAU;
    if (!(p > 0) || p / (p + rest) < keep) return 0;
    if (bg <= 0) return Infinity;
    // p·k < keep·(p·k + rest·k + bg·(1 − k))  ⇔  k < keep·bg / ((1 − keep)·p − keep·rest + keep·bg)
    const den = (1 - keep) * p - keep * rest + keep * bg;
    const k = (keep * bg) / den;
    if (!(k > 0) || k >= 1) return 0;
    return -CARRIAGE.halfLife * Math.log2(k);
  }

  /** Every town a carrier is preferred in. */
  heldBy(who: string): string[] {
    return [...this.towns].filter(([, t]) => t.pref === who).map(([k]) => k);
  }

  /** Towns where `who` has at least this share, with the share. */
  among(who: string, least = 0): { key: string; share: number }[] {
    const out: { key: string; share: number }[] = [];
    for (const key of this.towns.keys()) {
      const s = this.shareOf(key, who);
      if (s > least) out.push({ key, share: s });
    }
    return out.sort((a, b) => b.share - a.share);
  }

  clear(): void { this.towns.clear(); this.unseeded.clear(); }

  /**
   * Online: one town's tally as it is saved, brought up to the hour; null when the town has none. The rungs
   * stay behind (the server takes four fields): the game that takes it judges them again from the shares.
   */
  exportTown(key: string): [number, string, number, Record<string, number>] | null {
    const t = this.tally(key, false);
    if (!t) return null;
    const v: Record<string, number> = {};
    for (const [c, x] of Object.entries(t.v)) if (x >= 0.5) v[c] = Math.round(x * 10) / 10;
    return [Math.round(t.at * 10) / 10, t.pref, t.since, v];
  }

  /**
   * Online: take a town's tally as the game running it has it. The town is already seeded with its usual
   * trade there, and nobody is told of a change of heart: the game that made it told its own player.
   */
  importTown(key: string, row: SavedCarriage[string]): void {
    if (!Array.isArray(row) || row.length < 4) return;
    const [at, pref, since, v] = row;
    const t: Tally = { at: Number(at) || 0, pref: String(pref ?? ''), since: Number(since) || 0, v: { ...(v ?? {}) }, r: {}, n: this.towns.get(key)?.n ?? (Number(row[5]) || 0) };
    this.towns.set(key, t);
    this.unseeded.delete(key);
    // the rungs, judged here from the shares, quietly, the holder kept as sent: the change of heart was told where it happened
    const told = this.onChange, rung = this.onRung;
    this.onChange = null; this.onRung = null;
    this.decide(key, t);
    t.pref = String(pref ?? '');
    this.onChange = told; this.onRung = rung;
  }

  toSave(): SavedCarriage {
    const out: SavedCarriage = {};
    for (const [k, t] of this.towns) {
      this.roll(t, k);
      const v: Record<string, number> = {};
      for (const [c, x] of Object.entries(t.v)) if (x >= 0.5) v[c] = Math.round(x * 10) / 10;
      if (Object.keys(v).length || t.pref || t.n) out[k] = [Math.round(t.at * 10) / 10, t.pref, t.since, v, { ...t.r }, t.n ?? 0];
    }
    return out;
  }

  fromSave(s: SavedCarriage | undefined): void {
    this.towns.clear();
    this.unseeded.clear();
    for (const [k, row] of Object.entries(s ?? {})) {
      if (!Array.isArray(row) || row.length < 4) continue;
      const [at, pref, since, v, r, n] = row;
      // a save from before the loads were counted: a rung it already holds counts as earned (its loads as that rung's least)
      const held = Math.max(Number(r?.[YOU] ?? 0) || 0, pref === YOU ? RUNG.territory : 0);
      this.towns.set(k, { at: Number(at) || 0, pref: String(pref ?? ''), since: Number(since) || 0, v: { ...(v ?? {}) }, r: { ...(r ?? {}) }, n: Number(n ?? (held >= RUNG.regular ? LOADS_FOR[held] : 0)) || 0 });
      // an older save's towns may hold only a load or two: they get their usual trade too, once
      this.unseeded.add(k);
    }
  }
}
