/**
 * Small least-recently-used caps for the game's picture caches (11 Nov 2026 perf audit): sign faces, liveries,
 * banners and label sprites were painted once per text and kept for the session, textures held climbing from ~10
 * to ~400 over a long one. A cache asks `lruGet` (which marks the entry fresh) and `lruPut` (which lets the oldest
 * go past `max`, through `drop`). Something still drawing a let-go texture or material keeps working: three sends
 * it to the GPU again when it is next drawn.
 */
export function lruGet<K, V>(m: Map<K, V>, k: K): V | undefined {
  const v = m.get(k);
  if (v !== undefined) { m.delete(k); m.set(k, v); }
  return v;
}

export function lruPut<K, V>(m: Map<K, V>, k: K, v: V, max: number, drop: (v: V, k: K) => void): void {
  m.set(k, v);
  for (const [ok, ov] of m) {
    if (m.size <= max) break;
    m.delete(ok);
    drop(ov, ok);
  }
}
