import { hex, scale, type RGB } from '../../../world/biomes';
import type { RegionBuildingKind } from '../../../world/tiles';
import type { Sched } from '../../nightLights';
import { DARK, TAU, TRUNK, WARM_GLOW, type Draw, type Kit, type P3 } from '../kit';
import { lump } from './veldt';

/**
 * The Whitewash: blue-domed chapel, windmill row, taverna, stone amphitheatre and the temple on the
 * cape. Pure white cubes with blue doors and shutters, pale gold stone, and marble ruins that glow
 * faintly under their floodlights.
 */

const LIME = hex(0xfbfbf8), BLUE = hex(0x2a62b8), BLUE_DEEP = hex(0x1f4f9a), STONE = hex(0xe2d6bc), MARBLE = hex(0xeee8da);
const THATCH = hex(0x8a6a44), VINE = hex(0x5f8f3a), MAGENTA = hex(0xc8328a), ROCK = hex(0xcdb88a), OLIVE = hex(0x8a9a78);
const GRAVEL = hex(0xd8ccb0), CYPRESS = hex(0x2f5a3a);
const EVENING: Sched = [18, 24.5, 1.5];
const FLOOD: Sched = [19, 25.5, 0.9];

// ---- shared pieces -------------------------------------------------------------------------------

/** A round log from a to b (a column drum lying down, a mill axle). */
export function log(k: Kit, a: P3, b: P3, rad: number, col: RGB, seg = 7): void {
  const dx = b[0] - a[0], dy = b[1] - a[1], dz = b[2] - a[2], len = Math.hypot(dx, dy, dz);
  if (len < 1e-5) return;
  const ux = dx / len, uy = dy / len, uz = dz / len;
  let px = -uz, py = 0, pz = ux, pl = Math.hypot(px, pz);
  if (pl < 1e-4) { px = 1; pz = 0; pl = 1; }
  px /= pl; pz /= pl;
  const qx = uy * pz - uz * py, qy = uz * px - ux * pz, qz = ux * py - uy * px;
  const at = (o: P3, t: number): P3 => [o[0] + (px * Math.cos(t) + qx * Math.sin(t)) * rad, o[1] + (py * Math.cos(t) + qy * Math.sin(t)) * rad, o[2] + (pz * Math.cos(t) + qz * Math.sin(t)) * rad];
  const mid: P3 = [a[0] + dx / 2, a[1] + dy / 2, a[2] + dz / 2], end = scale(col, 0.9);
  for (let s = 0; s < seg; s++) {
    const t0 = (s / seg) * TAU, t1 = ((s + 1) / seg) * TAU;
    k.quad(at(a, t0), at(a, t1), at(b, t1), at(b, t0), col, mid);
    k.tri(a, at(a, t0), at(a, t1), end, mid);
    k.tri(b, at(b, t0), at(b, t1), end, mid);
  }
}

/** A column shaft tapering from r0 to r1, standing on y. */
function shaft(k: Kit, x: number, y: number, z: number, r0: number, r1: number, h: number, col: RGB, seg = 8): void {
  const I: P3 = [x, y + h / 2, z];
  for (let s = 0; s < seg; s++) {
    const a0 = (s / seg) * TAU, a1 = ((s + 1) / seg) * TAU;
    k.quad([x + Math.cos(a0) * r0, y, z + Math.sin(a0) * r0], [x + Math.cos(a1) * r0, y, z + Math.sin(a1) * r0],
      [x + Math.cos(a1) * r1, y + h, z + Math.sin(a1) * r1], [x + Math.cos(a0) * r1, y + h, z + Math.sin(a0) * r1], s % 2 ? col : scale(col, 0.95), I);
    k.tri([x, y + h, z], [x + Math.cos(a0) * r1, y + h, z + Math.sin(a0) * r1], [x + Math.cos(a1) * r1, y + h, z + Math.sin(a1) * r1], scale(col, 0.92), I);
  }
}

/** A cypress spire. */
function cypress(k: Kit, x: number, y: number, z: number, s: number): void {
  k.box(x, y, z, 0.04 * s, 0.1 * s, 0.04 * s, TRUNK);
  k.cone(x, y + 0.06 * s, z, 0.12 * s, 0.75 * s, CYPRESS, 6);
}

/** A white Cycladic tower mill with a thatched cap and eight triangular cloth sails facing +z. */
function cycladicMill(k: Kit, x: number, z: number, speed: number): void {
  const H = 0.9;
  k.cyl(x, 0, z, 0.27, H, LIME, 10);
  k.box(x, 0, z, 0.62, 0.05, 0.62, scale(STONE, 0.95));
  k.box(x, 0.05, z + 0.26, 0.12, 0.2, 0.04, BLUE);
  k.pane(x, 0.55, z + 0.262, 0.08, 0.1, 1, BLUE_DEEP, EVENING, WARM_GLOW);
  k.cone(x, H, z, 0.32, 0.28, THATCH, 10);
  k.bar([x, H + 0.12, z - 0.1], [x, H + 0.1, z + 0.36], 0.02, TRUNK);
  k.spin(x, H + 0.1, z + 0.36, 'z', speed, (s) => {
    const sail = hex(0xf6f0e0), spar = hex(0x6b5038);
    s.cyl(0, -0.03, 0, 0.035, 0.06, DARK, 6);
    for (let i = 0; i < 8; i++) {
      const a = (i / 8) * TAU, c = Math.cos(a), sn = Math.sin(a);
      s.bar([0, 0, 0.02], [c * 0.48, sn * 0.48, 0.02], 0.008, spar);
      // a triangle of cloth from the spar's tip back to the next spar, both sides
      const b = a + 0.5;
      const p0: P3 = [c * 0.12, sn * 0.12, 0.025], p1: P3 = [c * 0.48, sn * 0.48, 0.025], p2: P3 = [Math.cos(b) * 0.3, Math.sin(b) * 0.3, 0.025];
      s.tri(p0, p1, p2, sail, [0, 0, -0.1]);
      s.tri(p0, p1, p2, scale(sail, 0.9), [0, 0, 0.1]);
      // the rigging from the bowsprit to the tip
      s.bar([0, 0, 0.14], [c * 0.48, sn * 0.48, 0.02], 0.003, spar);
    }
    s.bar([0, 0, 0], [0, 0, 0.14], 0.01, spar);
  });
}

// ---- 1. blue chapel ------------------------------------------------------------------------------

const blueChapel: Draw = (k) => {
  const bz = -0.08;
  k.box(0, 0, 0.1, 0.8, 0.02, 0.8, hex(0xe8e0d0));
  for (let i = 0; i < 3; i++) k.box(0, 0, 0.33 + i * 0.05, 0.3 - i * 0.03, 0.06 - i * 0.02, 0.06, LIME);
  k.box(0, 0.02, bz, 0.42, 0.32, 0.5, LIME);
  k.box(0, 0.34, bz, 0.44, 0.03, 0.52, LIME);
  // drum, blue dome and a white cross
  k.cyl(0, 0.37, bz, 0.15, 0.09, LIME, 12);
  k.dome(0, 0.46, bz, 0.15, BLUE, 12, 4);
  k.box(0, 0.6, bz, 0.012, 0.09, 0.012, LIME);
  k.box(0, 0.65, bz, 0.05, 0.012, 0.012, LIME);
  // the blue door and a small lit window
  k.box(0, 0.02, bz + 0.255, 0.1, 0.17, 0.01, BLUE);
  k.pane(0.211, 0.16, bz - 0.06, 0.06, 0.08, 0, BLUE_DEEP, [18, 21.5, 1.3], WARM_GLOW);
  k.pane(-0.211, 0.16, bz - 0.06, 0.06, 0.08, 2, BLUE_DEEP, [18, 21.5, 1.3], WARM_GLOW);
  // the bell arch on the front corner: a pierced white screen with a bell in the opening
  const ax = 0.14, az = bz + 0.23;
  for (const sx of [-1, 1]) k.box(ax + sx * 0.06, 0.34, az, 0.03, 0.16, 0.04, LIME);
  k.box(ax, 0.5, az, 0.15, 0.04, 0.04, LIME);
  k.hip(ax, 0.54, az, 0.15, 0.05, 0.04, LIME);
  k.box(ax, 0.55, az, 0.01, 0.07, 0.01, LIME);
  k.cone(ax, 0.41, az, 0.025, 0.06, hex(0xb08a3a), 6);
};

// ---- 2. windmill row -----------------------------------------------------------------------------

const windmillRow: Draw = (k, W, _D, b) => {
  const n = 3, step = W / n;
  for (let i = 0; i < n; i++) cycladicMill(k, -W / 2 + step * (i + 0.5), -0.05, 0.5 + ((b.seed + i * 7) % 5) * 0.08);
  k.box(0, 0, 0.36, W - 0.3, 0.012, 0.12, GRAVEL);
  lump(k, W / 2 - 0.15, 0, 0.3, 0.1, 0.06, 0.08, ROCK, b.seed, 6, 3);
  lump(k, -W / 2 + 0.2, 0, -0.35, 0.12, 0.07, 0.1, ROCK, b.seed + 1, 6, 3);
};

// ---- 3. taverna ----------------------------------------------------------------------------------

const taverna: Draw = (k, W, D, b) => {
  const hx = -W / 2 + 0.5, hz = -D / 2 + 0.3;
  // the white cube with its blue shutters and a smaller stepped block beside it
  k.box(hx, 0, hz, 0.86, 0.36, 0.52, LIME);
  k.box(hx, 0.36, hz, 0.9, 0.03, 0.56, LIME);
  k.box(hx - 0.2, 0.39, hz - 0.08, 0.4, 0.2, 0.34, LIME);
  k.box(hx - 0.2, 0.59, hz - 0.08, 0.43, 0.025, 0.37, LIME);
  k.box(hx + 0.1, 0, hz + 0.265, 0.12, 0.22, 0.01, BLUE);
  for (const px of [-0.22, 0.34]) {
    k.pane(hx + px, 0.13, hz + 0.26, 0.1, 0.12, 1, hex(0x3a4a5a), EVENING, WARM_GLOW);
    for (const sx of [-1, 1]) k.box(hx + px + sx * 0.075, 0.12, hz + 0.265, 0.05, 0.14, 0.012, BLUE);
  }
  k.pane(hx - 0.2, 0.44, hz + 0.09, 0.1, 0.1, 1, hex(0x3a4a5a), EVENING, WARM_GLOW);
  // bougainvillea spilling over the corner
  for (let i = 0; i < 4; i++) k.box(hx - 0.43, 0.16 + i * 0.05, hz + 0.1 + (i % 2) * 0.05, 0.05, 0.08, 0.14 - i * 0.02, MAGENTA);
  // the pergola terrace across the front and right, vine overhead, tables below
  const tz = D / 2 - 0.24, px0 = -W / 2 + 0.1, px1 = W / 2 - 0.1, py = 0.32;
  k.box(0, 0, tz, W - 0.1, 0.02, 0.46, hex(0xd8c8a8));
  for (let i = 0; i < 5; i++) {
    const x = px0 + (i * (px1 - px0)) / 4;
    k.box(x, 0.02, tz + 0.2, 0.04, py - 0.02, 0.04, LIME);
  }
  for (const zz of [-0.35, -0.05]) k.box(px1, 0.02, zz, 0.04, py - 0.02, 0.04, LIME);
  k.box(0, py, tz + 0.2, W - 0.12, 0.03, 0.03, hex(0x8a6a44));
  for (let i = 0; i < 9; i++) k.box(px0 + i * ((px1 - px0) / 8), py + 0.03, tz - 0.02, 0.02, 0.02, 0.5, hex(0x8a6a44));
  for (let i = 0; i < 7; i++) {
    const x = px0 + 0.12 + i * 0.26, w = 0.2 + ((i * 5 + b.seed) % 3) * 0.04;
    k.box(x, py + 0.05, tz + ((i * 3) % 2) * 0.08 - 0.04, w, 0.03, 0.26, i % 2 ? VINE : scale(VINE, 0.85));
  }
  // string lights along the front beam
  for (let i = 0; i < 8; i++) k.glowBox(px0 + 0.1 + i * ((px1 - px0 - 0.2) / 7), py - 0.03 - (i % 2) * 0.015, tz + 0.21, 0.02, 0.02, 0.02, hex(0xf0e8c8), EVENING, WARM_GLOW);
  for (let i = 0; i < 3; i++) {
    const x = px0 + 0.3 + i * 0.6;
    k.cyl(x, 0.02, tz, 0.07, 0.1, LIME, 8, i === 1 ? BLUE : LIME);
    for (const sx of [-1, 1]) k.box(x + sx * 0.11, 0.02, tz, 0.05, 0.06, 0.05, BLUE);
  }
  // a pot of basil and a chalkboard
  k.cyl(W / 2 - 0.15, 0, -D / 2 + 0.14, 0.05, 0.06, hex(0xb8683a), 6);
  k.dome(W / 2 - 0.15, 0.06, -D / 2 + 0.14, 0.05, VINE, 6, 2);
  k.box(W / 2 - 0.3, 0, -D / 2 + 0.16, 0.1, 0.14, 0.02, hex(0x3a3f3a));
};

// ---- 4. stone amphitheatre -----------------------------------------------------------------------

const stoneAmphitheatre: Draw = (k, W, D, b) => {
  const cz = D / 2 - 1.05, seg = 14, tiers = 7, th = 0.075, r0 = 0.72, step = (W / 2 - 0.08 - r0) / tiers;
  const stretch = (cz + D / 2 - 0.08) / (W / 2 - 0.08);
  const P = (a: number, rr: number, y: number): P3 => [Math.cos(a) * rr, y, cz + Math.sin(a) * rr * stretch];
  for (let t = 0; t < tiers; t++) {
    const ri = r0 + t * step, ro = ri + step, y0 = t * th, y1 = y0 + th, col = scale(STONE, t % 2 ? 0.94 : 1);
    for (let s = 0; s < seg; s++) {
      // the top tiers crumble away at the ends
      if (t >= tiers - 2 && ((s === 0 && t === tiers - 1) || (s === seg - 1 && (b.seed + t) % 2 === 0))) continue;
      const a0 = Math.PI + (s / seg) * Math.PI, a1 = Math.PI + ((s + 1) / seg) * Math.PI, am = (a0 + a1) / 2;
      k.quad(P(a0, ri, y1), P(a1, ri, y1), P(a1, ro, y1), P(a0, ro, y1), col, P(am, (ri + ro) / 2, y1 - 0.3));
      k.quad(P(a0, ri, y0), P(a1, ri, y0), P(a1, ri, y1), P(a0, ri, y1), scale(col, 0.86), P(am, ri + 0.2, y0));
      k.quad(P(a0, ro, 0), P(a1, ro, 0), P(a1, ro, y1), P(a0, ro, y1), scale(col, 0.8), P(am, ro - 0.2, y0));
      if (s === 0 || s === seg - 1) {
        const a = s === 0 ? a0 : a1, inner: P3 = P(am, (ri + ro) / 2, y1 / 2);
        k.quad(P(a, ri, 0), P(a, ro, 0), P(a, ro, y1), P(a, ri, y1), scale(col, 0.88), inner);
      }
    }
  }
  // stair aisles as darker radial lines
  const rmax = r0 + tiers * step;
  for (const a of [Math.PI * 1.33, Math.PI * 1.67]) {
    for (let t = 0; t < tiers; t++) {
      const [x, , z] = P(a, r0 + (t + 0.5) * step, 0);
      k.box(x, (t + 1) * th, z, 0.07, 0.008, 0.07, scale(STONE, 0.75));
    }
  }
  void rmax;
  // the round orchestra and the broken stage wall across the front
  k.cyl(0, 0, cz, 0.66, 0.02, scale(STONE, 0.9), 16);
  k.disc(0, 0.021, cz, 0.58, hex(0xd8ccb0), 16);
  const sz = D / 2 - 0.22;
  k.box(0, 0, sz, W - 0.9, 0.1, 0.24, scale(STONE, 0.92));
  const hs = [0.55, 0.18, 0.62, 0.3, 0.08, 0.45];
  for (let i = 0; i < hs.length; i++) shaft(k, -1.2 + i * 0.48, 0.1, sz, 0.065, 0.058, hs[(i + b.seed) % hs.length], MARBLE, 7);
  k.box(-1.2 + 0.24, 0.1 + 0.55, sz, 0.62, 0.08, 0.14, MARBLE);
  log(k, [0.2, 0.065, sz + 0.3], [0.45, 0.065, sz + 0.42], 0.065, MARBLE);
  log(k, [-1.6, 0.06, sz + 0.1], [-1.55, 0.06, sz + 0.34], 0.06, MARBLE);
};

// ---- 5. temple on the cape (wonder) --------------------------------------------------------------

const capeTemple: Draw = (k, _W, D, b) => {
  const zc = -0.6, gold = hex(0xfff0d0);
  // the rocky headland: pale boulders and scrub
  const rocks = [[-5, -4.8, 0.7], [4.6, -5.1, 0.9], [-5.1, 2.6, 0.6], [5.0, 1.2, 0.5], [3.9, 5.2, 0.4], [-4.5, 5.0, 0.55], [-5.4, -1.0, 0.45]];
  rocks.forEach(([x, z, s], i) => lump(k, x, 0, z, s, s * 0.55, s * 0.8, ROCK, b.seed + i, 7, 4));
  for (const [x, z] of [[4.8, -2.8], [-4.6, -3.0], [4.4, 3.4], [-5.2, 0.6], [2.6, 5.4]]) k.dome(x, 0, z, 0.22, OLIVE, 6, 2);
  cypress(k, -4.2, 0, 3.8, 1.6);
  cypress(k, 4.9, 0, -0.6, 1.3);
  k.box(0, 0, (zc + 5.1 + D / 2) / 2, 1.3, 0.012, D / 2 - zc - 5.1, GRAVEL);
  // the stepped marble plinth
  const pw = 6.2, pd = 10.2, stepH = 0.18;
  for (let i = 0; i < 3; i++) k.box(0, i * stepH, zc, pw - i * 0.6, stepH, pd - i * 0.6, scale(MARBLE, 0.9 + i * 0.04));
  const top = stepH * 3, colH = 1.9, xs = [-2.2, -1.32, -0.44, 0.44, 1.32, 2.2];
  const zOf = (j: number) => zc - 4.2 + j * 0.84;
  // the cella's low walls inside
  k.box(0, top, zc - 0.3, 2.8, 0.55, 0.18, MARBLE);
  for (const sx of [-1, 1]) k.box(sx * 1.31, top, zc - 0.3, 0.18, sx > 0 ? 0.8 : 0.35, 5.2, scale(MARBLE, 0.97));
  k.box(-0.9, top, zc + 2.3, 1.0, 0.7, 0.18, MARBLE);
  k.box(0.9, top, zc + 2.3, 1.0, 0.9, 0.18, MARBLE);
  // thirty columns: the front and the seaward (+x) side stand; the back and -x side are broken
  const glowX: number[] = [];
  for (let j = 0; j <= 10; j++) for (let i = 0; i < 6; i++) {
    if (!(i === 0 || i === 5 || j === 0 || j === 10)) continue;
    const x = xs[i], z = zOf(j);
    const broken = (i === 0 && j < 8 && j % 3 !== 1) || (j === 0 && i > 0 && i < 4);
    const h = broken ? colH * (0.12 + (((i * 7 + j * 13 + b.seed) % 10) / 10) * 0.5) : colH;
    shaft(k, x, top, z, 0.21, broken ? 0.21 - 0.04 * (h / colH) : 0.17, h, MARBLE);
    if (!broken) {
      k.cyl(x, top + colH, z, 0.24, 0.06, MARBLE, 8);
      k.box(x, top + colH + 0.06, z, 0.52, 0.06, 0.52, MARBLE);
      if (j === 10) k.glowBox(x, top + 0.2, z + 0.215, 0.14, colH - 0.3, 0.008, MARBLE, FLOOD, gold);
      if (i === 5) k.glowBox(x + 0.215, top + 0.2, z, 0.008, colH - 0.3, 0.14, MARBLE, FLOOD, gold);
      glowX.push(x);
    }
  }
  // the entablature where it survives: the front, the +x side, the front of the -x side
  const eY = top + colH + 0.12;
  const beam = (x: number, z: number, w: number, d: number) => {
    k.box(x, eY, z, w, 0.22, d, MARBLE);
    k.box(x, eY + 0.22, z, w, 0.2, d, scale(MARBLE, 0.9));
    k.box(x, eY + 0.42, z, w + 0.12, 0.07, d + 0.12, MARBLE);
  };
  beam(0, zOf(10), 4.9, 0.5);
  beam(2.2, zc, 0.5, 8.9);
  beam(-2.2, (zOf(10) + zOf(8)) / 2, 0.5, 2.18);
  beam(1.76, zOf(0), 1.38, 0.5);
  // triglyphs on the front frieze
  for (let i = 0; i < 11; i++) k.box(-2.2 + i * 0.44, eY + 0.24, zOf(10) + 0.255, 0.1, 0.16, 0.01, scale(MARBLE, 0.72));
  // half a roof and the front pediment
  const rz0 = zOf(10) + 0.3, rz1 = zc + 0.6;
  k.gable(0, eY + 0.49, (rz0 + rz1) / 2, 5.0, 0.72, rz0 - rz1, scale(MARBLE, 0.82), MARBLE, true);
  // ceiling beams left bare where the roof has gone
  for (let i = 0; i < 4; i++) k.bar([2.2, eY + 0.4, zc - i * 0.9], [-1.0 + i * 0.2, eY + 0.4 - (i % 2) * 0.05, zc - i * 0.9], 0.05, scale(MARBLE, 0.85));
  // fallen drums and blocks on the ground to the -x side and behind
  const fallen: [number, number, number][] = [[-3.4, -3.2, 0.4], [-3.9, -1.6, 1.2], [-3.5, 0.2, 2.1], [-2.8, -5.8, 0.2], [-1.2, -5.7, 1.4], [-4.3, -4.2, 2.6]];
  for (const [x, z, a] of fallen) log(k, [x, 0.19, z], [x + Math.cos(a) * 0.36, 0.19, z + Math.sin(a) * 0.36], 0.19, scale(MARBLE, 0.92));
  k.bar([-3.0, 0.14, 1.8], [-3.6, 0.2, 2.8], 0.14, scale(MARBLE, 0.9));
  k.bar([-1.7, top + 0.12, -4.6], [-0.4, top + 0.1, -4.9], 0.12, scale(MARBLE, 0.9));
  log(k, [-1.6, top + 0.19, -2.0], [-1.95, top + 0.19, -2.3], 0.19, MARBLE);
  // floodlights at the plinth's foot
  for (let i = 0; i < 4; i++) k.glowBox(-2.4 + i * 1.6, 0, zc + pd / 2 + 0.2, 0.12, 0.06, 0.08, DARK, FLOOD, gold);
  for (let i = 0; i < 5; i++) k.glowBox(pw / 2 + 0.2, 0, zc - 4 + i * 2, 0.08, 0.06, 0.12, DARK, FLOOD, gold);
};

export const WHITEWASH_DRAW: Partial<Record<RegionBuildingKind, Draw>> = {
  blueChapel, windmillRow, taverna, stoneAmphitheatre, capeTemple,
};
