import { Under, type RailPath, type World } from '../world/tiles';

/**
 * A double-track bridge is two paths side by side (world/railPlan.ts twinPath, or a parallel the player laid), each
 * once drawn as a bridge of its own: two narrow viaducts a tile apart with a slot of sky between them (the user,
 * 11 Nov 2026: visible gaps in the rail bridges). Here the deck beside one, so the slab, the piers and the arches
 * of each run out to the line between the two and the pair stands as one bridge.
 */

/** What a twin is looked for on: decks, and the banks that carry double track up to them. */
const BRIDGES = new Set<number>([Under.Viaduct, Under.Sea, Under.Embank]);
/** How far apart a twin's centre line may stand: double track is laid 1.1 apart. */
const NEAR = 0.75, FAR = 1.45;

interface Index { rev: string; tiles: Map<number, number[]> }
const cache = new WeakMap<World, Index>();
const key = (tx: number, tz: number): number => (tx + 64) * 8192 + (tz + 64);

/** Every bridge sample on the cell by tile, as (path, sample) pairs flattened. */
function index(w: World): Map<number, number[]> {
  let n = 0;
  for (const p of w.rails) n += p.s.length;
  const rev = `${w.revision}:${w.rails.length}:${n}`;
  const c = cache.get(w);
  if (c && c.rev === rev) return c.tiles;
  const tiles = new Map<number, number[]>();
  w.rails.forEach((p, pi) => {
    for (let i = 0; i < p.s.length; i++) {
      if (!BRIDGES.has(p.under[i])) continue;
      const k = key(Math.floor(p.xz[i * 2]), Math.floor(p.xz[i * 2 + 1]));
      let l = tiles.get(k);
      if (!l) tiles.set(k, (l = []));
      l.push(pi, i);
    }
  });
  cache.set(w, { rev, tiles });
  return tiles;
}

/**
 * The signed offset, along the normal (-tz, tx), of a twin deck of the same kind beside the track at (x, y, z)
 * heading (tx, tz), or 0 where none stands there: its nearest sample within reach of 1.1 either side, running the
 * same way or the other, at much the same height.
 */
export function twinOffset(w: World, p: RailPath, u: Under, x: number, y: number, z: number, tx: number, tz: number): number {
  if (!BRIDGES.has(u)) return 0;
  const tiles = index(w);
  const nx = -tz, nz = tx;
  let best = 0, bestD = 0.3;
  for (const side of [-1, 1]) {
    const px = x + nx * 1.1 * side, pz = z + nz * 1.1 * side;
    const cx = Math.floor(px), cz = Math.floor(pz);
    for (let dz = -1; dz <= 1; dz++) for (let dx = -1; dx <= 1; dx++) {
      const l = tiles.get(key(cx + dx, cz + dz));
      if (!l) continue;
      for (let k = 0; k < l.length; k += 2) {
        const q = w.rails[l[k]];
        if (q === p) continue;
        const i = l[k + 1];
        if (q.under[i] !== u || Math.abs(q.y[i] - y) > 0.2) continue;
        const ox = q.xz[i * 2] - x, oz = q.xz[i * 2 + 1] - z;
        const o = ox * nx + oz * nz, along = ox * tx + oz * tz;
        // square across from us, the nearest sample along the line wins
        if (o * side < NEAR || o * side > FAR) continue;
        const d = Math.abs(along);
        if (d < bestD) { bestD = d; best = o; }
      }
    }
  }
  return best;
}
