// ---- the arcade (2×1) -----------------------------------------------------------------------------------

/** A space invader in pixels (11 × 8), rows top down. */
const INVADER = [
  '..x.....x..',
  '...x...x...',
  '..xxxxxxx..',
  '.xx.xxx.xx.',
  'xxxxxxxxxxx',
  'x.xxxxxxx.x',
  'x.x.....x.x',
  '...xx.xx...',
];

const arcade: Draw = (k, W, _D, b, r) => {
  const hall = hex(one(r, [0x2a1f3d, 0x1e2440, 0x2a2a2e])), edge = hex(one(r, [0xff3ac8, 0x3ae0ff, 0xffd23a]));
  const w = W - 0.16, d = 0.62, z = -0.12, fz = z + d / 2, h = 0.42;
  k.box(0, 0, z, w, h, d, hall);
  k.box(0, h, z, w + 0.02, 0.03, d + 0.02, scale(hall, 0.7));
  // neon along the top and the foot of the front, and up both corners
  tubeRun(k, [-w / 2, h - 0.03, fz + 0.012], [w / 2, h - 0.03, fz + 0.012], edge);
  tubeRun(k, [-w / 2, 0.02, fz + 0.012], [w / 2, 0.02, fz + 0.012], edge);
  for (const sx of [-1, 1]) tubeRun(k, [sx * (w / 2), 0.02, fz + 0.012], [sx * (w / 2), h - 0.03, fz + 0.012], edge);
  // the wide window: dark glass with the machines' screens glowing in a row behind it, and the doors
  k.box(-0.18, 0.04, fz + 0.004, w - 0.66, 0.26, 0.01, hex(0x14141c));
  const n = 7, span = w - 0.76;
  for (let i = 0; i < n; i++) {
    const c = hex(one(r, [0xff3ac8, 0x3ae0ff, 0xffd23a, 0x7aff5a, 0xff7a2a, 0xc05aff]));
    const x = -0.18 - span / 2 + (span * (i + 0.5)) / n;
    k.glowBox(x, 0.12, fz + 0.012, span / n - 0.05, 0.09, 0.006, scale(c, 0.7), ARCADE_HOURS, c);
    k.box(x, 0.05, fz + 0.012, span / n - 0.05, 0.06, 0.006, scale(c, 0.35));
  }
  k.glowBox(w / 2 - 0.24, 0.0, fz + 0.006, 0.26, 0.26, 0.01, hex(0x30284a), ARCADE_HOURS, hex(0xe0c8ff));
  // a claw machine by the doors
  k.box(w / 2 - 0.05, 0, fz + 0.1, 0.1, 0.06, 0.1, hex(0xe2412f));
  k.glowBox(w / 2 - 0.05, 0.06, fz + 0.1, 0.09, 0.12, 0.09, hex(0xbfe8ff), ARCADE_HOURS, hex(0xe8f6ff));
  // the name on its rack over the roof
  const word = one(r, ['ARCADE', 'ARCADE', 'GAMES', 'AMUSEMENTS']);
  roofName(k, word, 0, h + 0.03, z + 0.1, word.length > 7 ? 0.085 : 0.12, edge, edge, 0.06);
  // the invader, pixel by pixel, lit after dark
  const px = 0.034, ix = w / 2 - 0.26, iy = h + 0.06, inv = hex(one(r, [0x7aff5a, 0x3ae0ff, 0xff3ac8]));
  k.box(ix, h + 0.03, z - 0.12, 0.02, 0.04, 0.02, DARK);
  INVADER.forEach((line, j) => [...line].forEach((ch, i) => {
    if (ch !== 'x') return;
    k.glowBox(ix + (i - 5) * px, iy + (7 - j) * px, z - 0.12, px * 0.92, px * 0.92, 0.03, scale(inv, 0.75), ARCADE_HOURS, inv);
  }));
  // pac-man chasing three dots along the back of the roof
  const mx = -w / 2 + 0.2, my = h + 0.18, mz = z - 0.2, R = 0.11;
  slab(k, [[mx, my], ...arc(mx, my, R, R, 0.6, Math.PI * 2 - 0.6, 12)], mz, 0.025, hex(0xffd23a), [mx, my]);
  k.box(mx, h + 0.03, mz, 0.02, my - R - h - 0.02, 0.02, DARK);
  for (let i = 0; i < 3; i++) k.glowBox(mx + 0.2 + i * 0.1, my - 0.02, mz, 0.04, 0.04, 0.04, hex(0xf6f2e8), ARCADE_HOURS, hex(0xffffff));
  // in the neon towns, a blade down the corner too
  if (curArch === 'tokyo' || curArch === 'japanese' || curArch === 'cyberpunk' || curArch === 'osaka') {
    bladeName(k, 'ゲーム', -w / 2 + 0.03, 0.08, fz, 0.12, 0.08, hex(0x1e1a28), WHITE, edge);
  }
  void b;
};

