/**
 * The software-graphics check. A browser with graphics acceleration switched off (or a graphics card it
 * refuses, or no proper driver) still runs WebGL, but on the processor, at a few frames a second. Before
 * the renderer is made, `gpuCheck()` works out whether that is happening and, if so, puts up a card
 * whose steps are written for this browser, its version and its system, saying how to turn the
 * graphics card back on. A second visit still in software mode leads with what to try when the switch
 * is already on. "Play anyway" goes on for this visit; "Don't show again" for this computer.
 */

interface GpuInfo {
  /** WebGL drawn on the processor (SwiftShader, WARP, llvmpipe and the like). */
  software: boolean;
  /** No WebGL at all: the game cannot start. */
  none: boolean;
  /** The renderer string the browser gives, when it gives one. */
  renderer: string;
}

type Key = 'chrome' | 'edge' | 'brave' | 'opera' | 'vivaldi' | 'yandex' | 'samsung' | 'firefox' | 'safari' | 'other';
type Os = 'win' | 'mac' | 'linux' | 'cros' | 'other';
interface Browser { key: Key; name: string; version: number; os: Os }

/** Renderer names of WebGL drawn without a graphics card. */
const SOFT = /SwiftShader|Basic Render Driver|\bWARP\b|llvmpipe|softpipe|Software Rasterizer|Mesa OffScreen|Software Adapter/i;
const SEEN_KEY = 'tinyfleet-gpu-seen';
const NEVER_KEY = 'tinyfleet-gpu-never';
const ANYWAY_KEY = 'tinyfleet-gpu-anyway';

let found: GpuInfo | null = null;
/** What the check found, once it has run (net/perf.ts sends it with the play reports). */
export function gpuInfo(): GpuInfo | null { return found; }

/** Probe WebGL on a throwaway canvas, and show the card if it is drawn in software. */
export function gpuCheck(onVisit?: (kind: string) => void): GpuInfo {
  const info = probe();
  found = info;
  // ?gpucard=soft|none|again shows the card on any machine, to see it (again: as a second visit would)
  const force = new URLSearchParams(location.search).get('gpucard');
  if (force) {
    const shown = { ...info, software: force !== 'none', none: force === 'none' };
    show(shown, browser(), undefined, force === 'again' ? 1 : 0);
    return info;
  }
  if (!info.software && !info.none) { forgetSeen(); return info; }
  // the test harnesses' headless Chrome draws in software too: no card in their way, and not counted
  if (navigator.webdriver || /HeadlessChrome/.test(navigator.userAgent)) return info;
  onVisit?.(info.none ? 'gl-none' : 'gl-soft');
  let skip = false;
  try { skip = !info.none && (localStorage.getItem(NEVER_KEY) === '1' || sessionStorage.getItem(ANYWAY_KEY) === '1'); } catch { /* storage blocked */ }
  if (!skip) show(info, browser(), onVisit);
  return info;
}

function probe(): GpuInfo {
  const make = (strict: boolean): WebGLRenderingContext | WebGL2RenderingContext | null => {
    const c = document.createElement('canvas');
    const opts: WebGLContextAttributes = { failIfMajorPerformanceCaveat: strict, powerPreference: 'high-performance' };
    try { return (c.getContext('webgl2', opts) ?? c.getContext('webgl', opts)) as WebGLRenderingContext | WebGL2RenderingContext | null; } catch { return null; }
  };
  const drop = (gl: WebGLRenderingContext | WebGL2RenderingContext | null): void => { try { gl?.getExtension('WEBGL_lose_context')?.loseContext(); } catch { /* gone anyway */ } };
  const gl = make(false);
  if (!gl) return { software: false, none: true, renderer: '' };
  let renderer = '';
  try {
    const ext = gl.getExtension('WEBGL_debug_renderer_info');
    renderer = String(ext ? gl.getParameter(ext.UNMASKED_RENDERER_WEBGL) : gl.getParameter(gl.RENDERER));
  } catch { /* hidden by the browser */ }
  drop(gl);
  // a browser that would only give software refuses a context that asks to fail on a major slowdown
  const strict = make(true);
  const caveat = !strict;
  drop(strict);
  return { software: SOFT.test(renderer) || caveat, none: false, renderer };
}

function browser(): Browser {
  const ua = navigator.userAgent;
  const ver = (re: RegExp): number => { const m = ua.match(re); return m ? parseInt(m[1], 10) : 0; };
  const plat = ((navigator as Navigator & { userAgentData?: { platform?: string } }).userAgentData?.platform ?? navigator.platform ?? '') + ' ' + ua;
  const os: Os = /CrOS/i.test(plat) ? 'cros' : /Win/i.test(plat) ? 'win' : /Mac/i.test(plat) ? 'mac' : /Linux|X11/i.test(plat) ? 'linux' : 'other';
  const chrome = ver(/Chrom(?:e|ium)\/(\d+)/);
  if (/Edg\//.test(ua)) return { key: 'edge', name: 'Microsoft Edge', version: ver(/Edg\/(\d+)/), os };
  if (/OPR\/|Opera/.test(ua)) return { key: 'opera', name: 'Opera', version: ver(/OPR\/(\d+)/), os };
  if (/YaBrowser\//.test(ua)) return { key: 'yandex', name: 'Yandex Browser', version: ver(/YaBrowser\/(\d+)/), os };
  if (/Vivaldi\//.test(ua)) return { key: 'vivaldi', name: 'Vivaldi', version: ver(/Vivaldi\/(\d+)/), os };
  if (/SamsungBrowser\//.test(ua)) return { key: 'samsung', name: 'Samsung Internet', version: ver(/SamsungBrowser\/(\d+)/), os };
  if ((navigator as Navigator & { brave?: unknown }).brave) return { key: 'brave', name: 'Brave', version: chrome, os };
  if (/Firefox\//.test(ua)) return { key: 'firefox', name: 'Firefox', version: ver(/Firefox\/(\d+)/), os };
  if (chrome) return { key: 'chrome', name: 'Google Chrome', version: chrome, os };
  if (/Safari\//.test(ua)) return { key: 'safari', name: 'Safari', version: ver(/Version\/(\d+)/), os };
  return { key: 'other', name: 'your browser', version: 0, os };
}

/** One step: words, and an address to copy (pages may not open a browser's own settings pages). */
interface Step { html: string; copy?: string }

/** The Chromium browsers: where the switch is, what it is called, what the restart button says. */
const CHROMIUM: Partial<Record<Key, { scheme: string; page: string; label: string; restart: string; flags: string }>> = {
  chrome: { scheme: 'chrome', page: 'System', label: 'Use graphics acceleration when available', restart: 'Relaunch', flags: 'chrome://flags' },
  edge: { scheme: 'edge', page: 'System and performance', label: 'Use graphics acceleration when available', restart: 'Restart', flags: 'edge://flags' },
  brave: { scheme: 'brave', page: 'System', label: 'Use graphics acceleration when available', restart: 'Relaunch', flags: 'brave://flags' },
  opera: { scheme: 'opera', page: 'System', label: 'Use hardware acceleration when available', restart: 'Relaunch', flags: 'opera://flags' },
  vivaldi: { scheme: 'vivaldi', page: 'Webpages', label: 'Use Hardware Acceleration When Available', restart: 'Restart', flags: 'vivaldi://flags' },
  yandex: { scheme: 'browser', page: 'System', label: 'Use hardware acceleration if available', restart: 'Restart', flags: 'browser://flags' },
};

/** The oldest version of each browser these steps were written against. */
const CURRENT: Partial<Record<Key, number>> = { chrome: 110, edge: 110, brave: 110, opera: 95, firefox: 110, safari: 15 };

function steps(b: Browser, info: GpuInfo): { turnOn: Step[]; stillSlow: Step[]; update: Step | null } {
  const c = CHROMIUM[b.key];
  const turnOn: Step[] = [];
  const stillSlow: Step[] = [];
  const r = info.renderer;
  // Windows' own software renderer: what a Chromium browser on Windows falls back to with acceleration off, and all
  // there is with no proper driver, so it only means "no driver" once the switch is known to be on
  const basic = /Basic Render Driver/i.test(r);
  const mesaSoft = /llvmpipe|softpipe/i.test(r);

  if (info.none) {
    // no WebGL at all
    if (c) {
      turnOn.push({ html: 'Copy this address into a new tab:', copy: b.key === 'vivaldi' ? 'vivaldi://settings/webpages' : `${c.scheme}://settings/system` });
      turnOn.push({ html: `Turn on <b>${c.label}</b>.` });
      turnOn.push({ html: `Press <b>${c.restart}</b> when ${b.name} offers it.` });
      turnOn.push({ html: 'If that was already on, open this and press <b>Reset all</b> at the top, then restart:', copy: c.flags });
    } else if (b.key === 'firefox') {
      turnOn.push({ html: 'Copy this address into a new tab and press <b>Accept the Risk and Continue</b>:', copy: 'about:config' });
      turnOn.push({ html: 'Search for <b>webgl.disabled</b> and make sure it is <b>false</b> (double-click it to change it).' });
      turnOn.push({ html: 'Then open <b>about:preferences#general</b>, scroll to <b>Performance</b>, untick <b>Use recommended performance settings</b>, tick <b>Use hardware acceleration when available</b> and restart Firefox.' });
    } else if (b.key === 'safari') {
      turnOn.push({ html: 'Update macOS (System Settings › General › Software Update): older Safari has no WebGL 2.' });
      turnOn.push({ html: 'Or open TinyFleet in Chrome, Edge or Firefox.' });
    } else {
      turnOn.push({ html: 'This browser has no WebGL. Open TinyFleet in Chrome, Edge or Firefox.' });
    }
  } else if (c) {
    turnOn.push({ html: 'Copy this address into a new tab:', copy: b.key === 'vivaldi' ? 'vivaldi://settings/webpages' : `${c.scheme}://settings/system` });
    turnOn.push({ html: `On the <b>${c.page}</b> page, turn on <b>${c.label}</b>.` });
    turnOn.push({ html: `Press <b>${c.restart}</b> next to it. Your tabs come back, this one included.` });
  } else if (b.key === 'firefox') {
    turnOn.push({ html: 'Copy this address into a new tab:', copy: 'about:preferences#general' });
    turnOn.push({ html: 'Scroll to <b>Performance</b> and untick <b>Use recommended performance settings</b>.' });
    turnOn.push({ html: 'Tick <b>Use hardware acceleration when available</b>, then quit Firefox and open it again.' });
  } else if (b.key === 'safari') {
    turnOn.push({ html: 'Safari has no switch for this: it uses the graphics card unless macOS can’t.' });
    turnOn.push({ html: 'Turn off <b>Low Power Mode</b> (System Settings › Battery) and update macOS.' });
    turnOn.push({ html: 'If it’s still slow, open TinyFleet in Chrome or Firefox.' });
  } else {
    turnOn.push({ html: `Look in ${b.name}’s settings for <b>hardware acceleration</b> or <b>graphics acceleration</b>, turn it on and restart the browser.` });
    turnOn.push({ html: 'Or open TinyFleet in Chrome, Edge or Firefox.' });
  }

  // the switch is on and it is still software: the card, the driver or the machine
  if (basic) stillSlow.push({ html: 'If the switch is on and it still says “Microsoft Basic Render Driver” below, Windows has <b>no proper graphics driver</b>. Install one from your graphics card maker (NVIDIA, AMD or Intel) or through <b>Windows Update › Advanced options › Optional updates</b>, then restart the computer.' });
  if (mesaSoft) stillSlow.push({ html: 'Linux is drawing with <b>Mesa’s software renderer</b>. Install your graphics card’s driver (for NVIDIA, the proprietary one; for AMD and Intel, an up-to-date Mesa) and restart.' });
  if (c) {
    stillSlow.push({ html: `${b.name} may have <b>blocked your graphics card</b>. Open this, set <b>Override software rendering list</b> to <b>Enabled</b>, and press ${c.restart}:`, copy: `${c.scheme}://flags/#ignore-gpu-blocklist` });
    stillSlow.push({ html: 'To see what it is using, this page’s <b>WebGL</b> line should say <b>Hardware accelerated</b>:', copy: `${c.scheme}://gpu` });
  } else if (b.key === 'firefox') {
    stillSlow.push({ html: 'Open this and look under <b>Graphics</b>: a “blocklisted” note means Firefox has turned your card off. Updating the graphics driver usually clears it.', copy: 'about:support' });
  }
  if (!basic && !mesaSoft) stillSlow.push({ html: 'Update your <b>graphics driver</b> from NVIDIA, AMD or Intel, then restart the computer.' });
  if (b.os === 'win') stillSlow.push({ html: `On a laptop with two graphics chips: <b>Settings › System › Display › Graphics</b>, find ${b.name}, choose <b>High performance</b>.` });
  stillSlow.push({ html: 'Remote desktop and virtual machines usually have no graphics card to give. Play on the computer itself.' });

  const min = CURRENT[b.key];
  let update: Step | null = null;
  if (min && b.version && b.version < min) {
    update = c ? { html: `${b.name} ${b.version} is out of date. Updating it first may fix this by itself:`, copy: `${c.scheme}://settings/help` }
      : b.key === 'firefox' ? { html: `Firefox ${b.version} is out of date. Updating it first may fix this by itself: menu › Help › About Firefox.` }
        : { html: `${b.name} ${b.version} is out of date: update macOS to update Safari.` };
  }
  return { turnOn, stillSlow, update };
}

function forgetSeen(): void { try { localStorage.removeItem(SEEN_KEY); } catch { /* storage blocked */ } }

/** How many times this browser has come back still in software mode (since it last ran on the card). */
function seenBefore(b: Browser, info: GpuInfo): number {
  let n = 0;
  try {
    const was = JSON.parse(localStorage.getItem(SEEN_KEY) ?? 'null') as { key: string; renderer: string; n: number } | null;
    n = was && was.key === b.key && was.renderer === info.renderer ? was.n : 0;
    localStorage.setItem(SEEN_KEY, JSON.stringify({ key: b.key, renderer: info.renderer, n: n + 1 }));
  } catch { /* storage blocked */ }
  return n;
}

const esc = (s: string): string => s.replace(/[&<>"]/g, (ch) => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;' })[ch]!);

function show(info: GpuInfo, b: Browser, onVisit?: (kind: string) => void, forceAgain?: number): void {
  const again = forceAgain ?? (info.none ? 0 : seenBefore(b, info));
  const { turnOn, stillSlow, update } = steps(b, info);
  const list = (s: Step[]): string => s.map((x) => `<li>${x.html}${x.copy ? `<span class="gc-copy"><code>${esc(x.copy)}</code><button type="button" data-copy="${esc(x.copy)}">Copy</button></span>` : ''}</li>`).join('');
  const title = info.none ? 'Your browser has WebGL turned off'
    : again ? 'Still drawing without your graphics card'
      : `${b.key === 'other' ? 'Your browser' : b.name} isn’t using your graphics card`;
  const lead = info.none ? 'TinyFleet draws its world with WebGL, and this browser isn’t offering it, so the game can’t start.'
    : again ? `The setting may already be on, so something else is stopping ${b.name} using the graphics card. Try these:`
      : 'It’s drawing the game on the processor instead, which makes TinyFleet run at a crawl. Turning graphics acceleration back on fixes it:';
  const el = document.createElement('div');
  el.id = 'gpu-card';
  el.setAttribute('role', 'alertdialog');
  el.setAttribute('aria-labelledby', 'gc-title');
  el.innerHTML = `<style>
    #gpu-card { position: fixed; inset: 0; z-index: 2147483646; display: flex; align-items: center; justify-content: center; padding: 16px; box-sizing: border-box; background: rgba(20,28,34,.55); backdrop-filter: blur(6px); font-family: "IBM Plex Sans", "Segoe UI", system-ui, sans-serif; color: #1f2b33; }
    body.dark-ui > #gpu-card { filter: none !important; }
    #gpu-card .gc { width: min(560px, 100%); max-height: calc(100vh - 32px); overflow: auto; background: #f4f7f1; border-radius: 16px; padding: 24px 26px; box-shadow: 0 20px 60px rgba(0,0,0,.35); }
    #gpu-card .gc-ic { font-size: 34px; line-height: 1; margin-bottom: 8px; }
    #gpu-card h2 { font-family: "Fredoka", "Segoe UI", sans-serif; font-size: 22px; margin: 0 0 8px; }
    #gpu-card p { font-size: 15px; line-height: 1.5; color: #4c5a63; margin: 0 0 12px; }
    #gpu-card ol { margin: 0 0 14px; padding-left: 22px; font-size: 15px; line-height: 1.5; }
    #gpu-card li { margin: 0 0 8px; }
    #gpu-card .gc-copy { display: flex; gap: 6px; align-items: center; margin-top: 5px; }
    #gpu-card code { flex: 1; min-width: 0; padding: 6px 10px; border-radius: 8px; background: #fff; border: 1.5px solid #d5ddd0; font-family: "IBM Plex Mono", monospace; font-size: 13px; overflow-wrap: anywhere; }
    #gpu-card button { font: inherit; font-size: 13px; padding: 6px 12px; border-radius: 8px; border: 0; background: #1f2b33; color: #fff; cursor: pointer; }
    #gpu-card button.gc-done { background: #2f7a4a; }
    #gpu-card details { margin: 0 0 14px; font-size: 14px; }
    #gpu-card summary { cursor: pointer; font-weight: 600; margin-bottom: 8px; }
    #gpu-card .gc-note { font-size: 12px; color: #7d8a92; margin: 0 0 14px; overflow-wrap: anywhere; }
    #gpu-card .gc-row { display: flex; flex-wrap: wrap; gap: 10px; align-items: center; }
    #gpu-card .gc-row .gc-play { font-size: 15px; padding: 9px 16px; background: #e2412f; }
    #gpu-card .gc-row .gc-link { background: none; color: #7d8a92; text-decoration: underline; padding: 0; }
  </style>
  <div class="gc">
    <div class="gc-ic">${info.none ? '🚫' : '🐢'}</div>
    <h2 id="gc-title">${esc(title)}</h2>
    <p>${lead}</p>
    ${update ? `<ol>${list([update])}</ol>` : ''}
    ${again ? `<ol>${list(stillSlow)}</ol><details><summary>Turning graphics acceleration on</summary><ol>${list(turnOn)}</ol></details>`
      : `<ol>${list(turnOn)}</ol>${info.none ? '' : `<details><summary>Still not working?</summary><ol>${list(stillSlow)}</ol></details>`}`}
    <p class="gc-note">${b.name}${b.version ? ` ${b.version}` : ''} · ${info.renderer ? `drawing with: ${esc(info.renderer)}` : 'no WebGL'}</p>
    <div class="gc-row">
      ${info.none ? '<button type="button" class="gc-play" data-act="reload">I’ve changed it: reload</button>'
        : '<button type="button" class="gc-play" data-act="play">Play anyway (slow)</button><button type="button" class="gc-link" data-act="never">Don’t show this again</button>'}
    </div>
  </div>`;
  el.addEventListener('click', (e) => {
    const t = (e.target as HTMLElement).closest('button');
    if (!t) return;
    const text = t.dataset.copy;
    if (text !== undefined) {
      const done = (): void => { t.textContent = 'Copied'; t.classList.add('gc-done'); setTimeout(() => { t.textContent = 'Copy'; t.classList.remove('gc-done'); }, 1600); };
      navigator.clipboard?.writeText(text).then(done, () => selectCode(t));
      if (!navigator.clipboard) selectCode(t);
      return;
    }
    const act = t.dataset.act;
    if (act === 'reload') location.reload();
    if (act === 'play' || act === 'never') {
      try { sessionStorage.setItem(ANYWAY_KEY, '1'); if (act === 'never') localStorage.setItem(NEVER_KEY, '1'); } catch { /* this visit only */ }
      onVisit?.(act === 'never' ? 'gl-never' : 'gl-anyway');
      el.remove();
    }
  });
  // keys typed on the card are not the game's
  el.addEventListener('keydown', (e) => e.stopPropagation());
  document.body.appendChild(el);
}

/** No clipboard: select the address so Ctrl+C copies it. */
function selectCode(btn: HTMLElement): void {
  const code = btn.previousElementSibling;
  if (!code) return;
  const r = document.createRange();
  r.selectNodeContents(code);
  const s = getSelection();
  s?.removeAllRanges();
  s?.addRange(r);
}
