import { hex, scale, type RGB } from '../../../world/biomes';
import type { RegionBuildingKind } from '../../../world/tiles';
import type { Sched } from '../../nightLights';
import { DARK, METAL, RED_LIGHT, TAU, WHITE, WOOD, win, type Draw, type Kit, type P3 } from '../kit';
import { flag } from '../civic';

/**
 * The Icefield: tarred timber and snow — a research station out on the tundra, a sauna by the water,
 * sled kennels, fish-drying racks, and the ice hotel beside its frozen lake.
 */

const SNOW = hex(0xf2f6f8), SNOW_D = hex(0xdfe8ee), TAR = hex(0x3e2e26), TAR_L = hex(0x5a4032), FALU = hex(0x9a3a2c);
const DOME = hex(0xf1f3f4), ORANGE = hex(0xe8672a), STEEL = hex(0x8a9096), STEAM = hex(0xe6ecef);
const ICE = hex(0xc4e6f4), ICE2 = hex(0xa8d6ea), ICE3 = hex(0xdcf2fa), LAKE = hex(0xc8e4ee), LAKE_D = hex(0xa9d2e2);
const ICE_GLOW = hex(0x6ecbff), PANE = hex(0x9fd6ea), FISH = [0xb8a888, 0x9a8a70, 0xc8b898, 0xa88a60];
const NIGHT: Sched = [16.5, 30, 2.2];

// ---- 1. research station -----------------------------------------------------------------------

const researchStation: Draw = (k, W, D, b, r) => {
  for (const [x, z, s] of [[-0.9, 0.9, 0.4], [1.0, 1.0, 0.3], [0.9, -1.1, 0.3], [-1.2, -1.2, 0.25]]) k.disc(x, 0, z, s, SNOW, 9);
  // three domes on drums, joined by tubes
  const domes: [number, number, number, RGB][] = [[-0.7, -0.55, 0.5, DOME], [0.55, -0.7, 0.42, ORANGE], [0.7, 0.45, 0.36, DOME]];
  k.box(-0.08, 0.03, -0.62, 1.2, 0.14, 0.14, STEEL);
  k.box(0.63, 0.03, -0.12, 0.14, 0.14, 1.1, STEEL);
  for (const [x, z, R, c] of domes) {
    k.cyl(x, 0, z, R, 0.16, STEEL, 12);
    k.cyl(x, 0.16, z, R + 0.005, 0.04, c === DOME ? ORANGE : DOME, 12);
    k.dome(x, 0.2, z, R, c, 12, 4);
    // a vestibule on the front with a lit porthole
    k.box(x, 0, z + R - 0.02, 0.18, 0.2, 0.18, c === DOME ? ORANGE : DOME);
    k.box(x, 0, z + R + 0.074, 0.08, 0.14, 0.004, DARK);
    for (const sx of [-1, 1]) win(k, b, r, x + sx * R * 0.72, 0.06, z + R * 0.72, 0.07, 0.06, 1, hex(0x5f8aa3));
  }
  // the mast: a lattice tower with a red beacon on top and one halfway
  const mx = -W / 2 + 0.5, mz = D / 2 - 0.5, H = 2.3;
  for (const [sx, sz] of [[-1, -1], [1, -1], [1, 1], [-1, 1]]) k.bar([mx + sx * 0.13, 0, mz + sz * 0.13], [mx + sx * 0.03, H, mz + sz * 0.03], 0.01, WHITE);
  for (let i = 0; i < 6; i++) {
    const y0 = (H * i) / 6, y1 = (H * (i + 1)) / 6, w0 = 0.13 - (0.1 * i) / 6, w1 = 0.13 - (0.1 * (i + 1)) / 6;
    k.bar([mx - w0, y0, mz + w0], [mx + w1, y1, mz + w1], 0.006, i % 2 ? RED_LIGHT : WHITE);
    k.bar([mx + w0, y0, mz - w0], [mx + w1, y1, mz + w1], 0.006, i % 2 ? RED_LIGHT : WHITE);
  }
  k.cyl(mx, H, mz, 0.01, 0.3, METAL, 4);
  k.glowBox(mx, H + 0.02, mz, 0.06, 0.06, 0.06, RED_LIGHT, [0, 30, 3], RED_LIGHT);
  k.glowBox(mx, H * 0.5, mz + 0.09, 0.04, 0.04, 0.02, RED_LIGHT, [0, 30, 2.4], RED_LIGHT);
  // a dish on its stand, the weather station with its cups turning, fuel drums and a snowcat
  k.box(0.9, 0, -0.1, 0.06, 0.3, 0.06, STEEL);
  for (let i = 0; i < 10; i++) {
    const a0 = (i / 10) * TAU, a1 = ((i + 1) / 10) * TAU;
    k.tri([0.9, 0.3, -0.1], [0.9 + Math.cos(a0) * 0.2, 0.42 + Math.sin(a0) * 0.06, -0.1 + Math.sin(a0) * 0.2], [0.9 + Math.cos(a1) * 0.2, 0.42 + Math.sin(a1) * 0.06, -0.1 + Math.sin(a1) * 0.2], WHITE, [0.9, -1, -0.1]);
  }
  const wx = -1.1, wz = 0.3;
  k.box(wx, 0, wz, 0.12, 0.22, 0.12, WHITE);
  k.cyl(wx, 0.22, wz, 0.008, 0.3, METAL, 4);
  k.spin(wx, 0.52, wz, 'y', 4, (s) => {
    for (let i = 0; i < 3; i++) {
      const a = (i / 3) * TAU;
      s.bar([0, 0, 0], [Math.cos(a) * 0.08, 0, Math.sin(a) * 0.08], 0.004, METAL);
      s.box(Math.cos(a) * 0.08, -0.015, Math.sin(a) * 0.08, 0.03, 0.03, 0.03, WHITE);
    }
  });
  for (let i = 0; i < 5; i++) k.cyl(-0.2 + (i % 3) * 0.1, 0, 0.9 + Math.floor(i / 3) * 0.1, 0.045, 0.13, i % 2 ? hex(0x2f5fa8) : ORANGE, 6);
  k.box(0.3, 0, 1.05, 0.44, 0.06, 0.26, DARK);
  k.box(0.3, 0.06, 1.05, 0.4, 0.12, 0.22, ORANGE);
  k.box(0.38, 0.18, 1.05, 0.18, 0.1, 0.2, scale(ORANGE, 0.9), WHITE);
  flag(k, 1.3, 0, 1.3, 0.55, hex(0x2f6fb5));
  flag(k, 1.1, 0, 1.3, 0.5, hex(0xe2412f));
};

// ---- 2. sauna ----------------------------------------------------------------------------------

const sauna: Draw = (k, _W, _D, b, r) => {
  const z = -0.15;
  k.box(0, 0, z, 0.46, 0.3, 0.38, TAR, TAR);
  k.gable(0, 0.3, z, 0.54, 0.16, 0.46, SNOW, TAR_L);
  k.box(-0.08, 0, z + 0.193, 0.12, 0.22, 0.006, FALU);
  win(k, b, r, 0.12, 0.14, z + 0.19, 0.1, 0.07, 1, hex(0x5f8aa3));
  // the stove pipe and its steam
  k.cyl(0.14, 0.3, z - 0.08, 0.025, 0.34, DARK, 6);
  k.dome(0.14, 0.66, z - 0.08, 0.06, STEAM, 6, 2);
  k.dome(0.18, 0.74, z - 0.1, 0.08, STEAM, 6, 2);
  k.dome(0.24, 0.86, z - 0.12, 0.1, scale(STEAM, 1.02), 6, 2);
  k.glowBox(0.14, 0.62, z - 0.08, 0.03, 0.03, 0.03, hex(0xff8a40), [16, 23.5, 2], hex(0xff8a40));
  // porch, a bench, logs, and the jetty out over the water
  k.box(0, 0, z + 0.26, 0.46, 0.03, 0.14, WOOD);
  k.box(-0.3, 0, z + 0.05, 0.08, 0.1, 0.3, WOOD);
  for (let i = 0; i < 3; i++) k.bar([-0.42, 0.03 + i * 0.05, z - 0.18 + i * 0.02], [-0.42, 0.03 + i * 0.05, z + 0.14 - i * 0.02], 0.025, hex(0xb08a5a));
  const jx = 0.2;
  k.box(jx, 0.02, 0.33, 0.22, 0.03, 0.34, hex(0xa0805a));
  for (const sx of [-1, 1]) for (const jz of [0.2, 0.47]) k.box(jx + sx * 0.09, -0.6, jz, 0.03, 0.66, 0.03, TAR);
  for (const sx of [-1, 1]) k.box(jx + sx * 0.05, -0.4, 0.49, 0.015, 0.44, 0.015, METAL);
  for (let i = 0; i < 3; i++) k.box(jx, -0.33 + i * 0.12, 0.49, 0.1, 0.012, 0.012, METAL);
  k.disc(-0.32, 0, 0.35, 0.12, SNOW, 8);
};

// ---- 3. sled kennels ---------------------------------------------------------------------------

const sledKennels: Draw = (k, W, D, b, r) => {
  k.disc(-0.5, 0, 0.55, 0.3, SNOW, 9);
  k.disc(0.6, 0, -0.1, 0.22, SNOW, 9);
  // the long kennel shed with a row of hatches
  const sz = -D / 2 + 0.35;
  k.box(0, 0, sz, W - 0.3, 0.3, 0.46, FALU);
  k.gable(0, 0.3, sz, W - 0.2, 0.14, 0.54, SNOW, FALU);
  for (let i = 0; i < 5; i++) k.box(-0.6 + i * 0.3, 0, sz + 0.234, 0.12, 0.12, 0.004, TAR);
  win(k, b, r, 0.7, 0.14, sz + 0.23, 0.1, 0.08, 1, hex(0x5f8aa3));
  for (const sx of [-1, 1]) k.box(sx * (W / 2 - 0.15), 0, sz + 0.23, 0.02, 0.3, 0.02, WHITE);
  // dog houses along a stake line, a dog at each
  const dogs = [0xe8e4dc, 0x6a6460, 0x3a3634, 0xc8b8a0];
  k.bar([-0.8, 0.05, 0.25], [0.3, 0.05, 0.25], 0.004, DARK);
  for (let i = 0; i < 4; i++) {
    const x = -0.7 + i * 0.32, c = hex(dogs[i]);
    k.box(x, 0, 0.05, 0.15, 0.1, 0.15, TAR_L);
    k.gable(x, 0.1, 0.05, 0.18, 0.07, 0.18, FALU, TAR_L, true);
    k.box(x, 0, 0.129, 0.06, 0.07, 0.004, DARK);
    k.box(x + 0.02, 0.03, 0.26, 0.04, 0.04, 0.1, c);
    k.box(x + 0.02, 0.06, 0.32, 0.035, 0.04, 0.04, c);
    for (const lz of [0.22, 0.3]) k.box(x + 0.02, 0, lz, 0.03, 0.03, 0.02, c);
  }
  // the sled, ready to go
  const x = 0.6, z = 0.5;
  for (const sx of [-1, 1]) {
    k.bar([x + sx * 0.09, 0.012, z - 0.3], [x + sx * 0.09, 0.012, z + 0.26], 0.01, TAR);
    k.bar([x + sx * 0.09, 0.012, z + 0.26], [x + sx * 0.09, 0.07, z + 0.34], 0.01, TAR);
    k.bar([x + sx * 0.09, 0.02, z - 0.28], [x + sx * 0.09, 0.2, z - 0.3], 0.01, WOOD);
  }
  k.box(x, 0.06, z, 0.2, 0.02, 0.44, hex(0xb08a5a));
  k.box(x, 0.08, z + 0.05, 0.16, 0.08, 0.22, hex(0x2f5fa8));
  k.bar([x - 0.09, 0.2, z - 0.3], [x + 0.09, 0.2, z - 0.3], 0.01, WOOD);
  for (const [px, pz] of [[-0.85, 0.85], [0.95, 0.9], [0.95, -0.3]]) k.box(px, 0, pz, 0.04, 0.24, 0.04, WOOD);
};

// ---- 4. fish racks -----------------------------------------------------------------------------

const fishRacks: Draw = (k, W, _D, _b, r) => {
  for (const xc of [-W / 4, W / 4]) {
    const L = W / 2 - 0.2, H = 0.58;
    for (const xe of [xc - L / 2, xc + L / 2]) for (const sz of [-1, 1]) k.bar([xe, 0, sz * 0.24], [xe, H + 0.04, -sz * 0.02], 0.012, TAR_L);
    k.bar([xc - L / 2 - 0.05, H, 0], [xc + L / 2 + 0.05, H, 0], 0.012, TAR_L);
    for (const sz of [-1, 1]) {
      const zz = sz * 0.1, y = 0.36;
      k.bar([xc - L / 2, y, zz], [xc + L / 2, y, zz], 0.008, WOOD);
      const n = Math.round(L / 0.065);
      for (let i = 0; i < n; i++) {
        const fx = xc - L / 2 + 0.04 + ((L - 0.08) * i) / (n - 1);
        k.box(fx, y - 0.14 - r() * 0.02, zz, 0.018, 0.14, 0.04, hex(FISH[Math.floor(r() * FISH.length)]));
      }
    }
  }
  // barrels and a gull's worth of snow
  k.cyl(-W / 2 + 0.12, 0, 0.36, 0.06, 0.12, WOOD, 7);
  k.cyl(W / 2 - 0.12, 0, -0.36, 0.06, 0.12, WOOD, 7);
  k.disc(0, 0, 0.3, 0.14, SNOW, 8);
};

// ---- 5. ice hotel (wonder) ---------------------------------------------------------------------

/** A barrel vault of ice blocks, span w across, rising h, len long along z (or x); the blocks alternate two tones. */
function vault(k: Kit, x: number, z: number, w: number, h: number, len: number, alongX = false): void {
  const seg = 6, n = Math.max(1, Math.round(len / 0.45));
  const pt = (across: number, up: number, along: number): P3 => alongX ? [x + along, up, z + across] : [x + across, up, z + along];
  const I: P3 = [x, h * 0.3, z];
  for (let j = 0; j < n; j++) {
    const l0 = -len / 2 + (len * j) / n, l1 = -len / 2 + (len * (j + 1)) / n;
    for (let s = 0; s < seg; s++) {
      const a0 = (Math.PI * s) / seg, a1 = (Math.PI * (s + 1)) / seg;
      k.quad(pt(Math.cos(a0) * w / 2, Math.sin(a0) * h, l0), pt(Math.cos(a1) * w / 2, Math.sin(a1) * h, l0), pt(Math.cos(a1) * w / 2, Math.sin(a1) * h, l1), pt(Math.cos(a0) * w / 2, Math.sin(a0) * h, l1), (s + j) % 2 ? ICE : ICE2, I);
    }
  }
  for (const e of [-1, 1]) {
    for (let s = 0; s < seg; s++) {
      const a0 = (Math.PI * s) / seg, a1 = (Math.PI * (s + 1)) / seg;
      k.tri(pt(0, 0, (e * len) / 2), pt(Math.cos(a0) * w / 2, Math.sin(a0) * h, (e * len) / 2), pt(Math.cos(a1) * w / 2, Math.sin(a1) * h, (e * len) / 2), s % 2 ? ICE3 : ICE, I);
    }
  }
}

/** A dome of ice blocks on a low drum. */
function iceDome(k: Kit, x: number, y: number, z: number, R: number): void {
  const seg = 14, rings = 5, I: P3 = [x, y, z];
  k.cyl(x, 0, z, R, y, ICE2, seg);
  for (let j = 0; j < rings; j++) {
    const p0 = (j / rings) * Math.PI / 2, p1 = ((j + 1) / rings) * Math.PI / 2;
    const r0 = Math.cos(p0) * R, r1 = Math.cos(p1) * R, y0 = y + Math.sin(p0) * R * 0.8, y1 = y + Math.sin(p1) * R * 0.8;
    for (let s = 0; s < seg; s++) {
      const a0 = ((s + j * 0.5) / seg) * TAU, a1 = ((s + 1 + j * 0.5) / seg) * TAU;
      k.quad([x + Math.cos(a0) * r0, y0, z + Math.sin(a0) * r0], [x + Math.cos(a1) * r0, y0, z + Math.sin(a1) * r0], [x + Math.cos(a1) * r1, y1, z + Math.sin(a1) * r1], [x + Math.cos(a0) * r1, y1, z + Math.sin(a0) * r1], (s + j) % 2 ? ICE : ICE3, I);
    }
  }
}

const iceHotel: Draw = (k, W, D, _b, r) => {
  // the snowfield, and the frozen lake behind with its fishing holes and a skater or two
  k.disc(0, 0.003, -4.25, 5.85, SNOW, 20, 1.95);
  k.disc(0, 0.006, -4.25, 5.3, LAKE, 20, 1.55);
  k.disc(0.4, 0.013, -4.3, 3.6, LAKE_D, 16, 0.9);
  for (const [x, z] of [[-3.6, -4.6], [-2.9, -3.8], [3.4, -4.9]]) k.disc(x, 0.014, z, 0.09, hex(0x2f5f7a), 8);
  for (const [x, z] of [[-1.5, -4.2], [1.9, -3.9]]) {
    k.box(x, 0.01, z, 0.05, 0.12, 0.04, hex(0x2f3f6a));
    k.box(x, 0.13, z, 0.04, 0.04, 0.04, hex(0xe2412f));
  }
  // the hotel: a domed hall, two long wings of rooms, their cross vaults, and the entrance tunnel
  const hz = -0.2;
  iceDome(k, 0, 0.2, hz, 1.45);
  for (const sx of [-1, 1]) {
    vault(k, sx * 3.05, hz, 1.5, 0.95, 3.5, true);
    vault(k, sx * 4.55, hz, 1.2, 0.85, 3.4);
  }
  vault(k, 0, 1.6, 0.9, 0.72, 1.6);
  vault(k, 0, -1.95, 1.0, 0.7, 1.0);
  // the portal: two ice pillars and a lintel, a glowing sign
  for (const sx of [-1, 1]) k.box(sx * 0.52, 0, 2.45, 0.2, 0.9, 0.2, ICE3);
  k.box(0, 0.9, 2.45, 1.26, 0.14, 0.24, ICE);
  k.glowBox(0, 0.93, 2.58, 0.7, 0.08, 0.02, PANE, NIGHT, ICE_GLOW);
  k.glowBox(0, 0, 2.41, 0.44, 0.5, 0.01, hex(0x7fb8d0), NIGHT, ICE_GLOW);
  // blue windows low along the wings and at the vault ends
  for (const sx of [-1, 1]) {
    for (let i = 0; i < 4; i++) for (const sz of [-1, 1]) k.glowBox(sx * (1.75 + i * 0.8), 0.12, hz + sz * 0.7, 0.22, 0.22, 0.06, PANE, NIGHT, ICE_GLOW);
    for (const ez of [-1, 1]) k.glowBox(sx * 4.55, 0.12, hz + ez * 1.7, 0.3, 0.34, 0.03, PANE, NIGHT, ICE_GLOW);
    k.glowBox(sx * 1.45, 0.24, hz + 0.02, 0.05, 0.4, 0.5, PANE, NIGHT, ICE_GLOW);
  }
  for (let s = 0; s < 6; s++) {
    const a = Math.PI * (0.15 + s * 0.14);
    if (Math.abs(Math.cos(a)) < 0.2) continue;
    k.glowBox(Math.cos(a) * 1.44, 0.26, hz + Math.sin(a) * 1.44, 0.14, 0.24, 0.14, PANE, NIGHT, ICE_GLOW);
  }
  // snow banked against the walls
  for (const sx of [-1, 1]) for (const sz of [-1, 1]) k.hip(sx * 2.2, 0, hz + sz * 1.0, 0.9, 0.18, 0.5, SNOW_D);
  // the path in, lined with ice lanterns
  k.box(0, 0.005, 4.2, 0.7, 0.01, 3.6, SNOW_D);
  for (const sx of [-1, 1]) for (let i = 0; i < 5; i++) k.glowBox(sx * 0.42, 0, 2.8 + i * 0.75, 0.07, 0.1, 0.07, ICE3, NIGHT, hex(0xa8e0ff));
  // the ring of ice sculptures round the forecourt, a star in the middle
  const cx = 0, cz = 3.95, R = 1.75, S = 1.6;
  for (let i = 0; i < 8; i++) {
    const a = ((i + 0.5) / 8) * TAU, x = cx + Math.cos(a) * R, z = cz + Math.sin(a) * R, y = 0.1;
    k.box(x, 0, z, 0.5, 0.08, 0.5, SNOW_D);
    k.glowBox(x, 0.08, z, 0.4, 0.02, 0.4, ICE3, NIGHT, ICE_GLOW);
    switch (i % 4) {
      case 0: // a crystal
        k.hip(x, y + 0.3 * S, z, 0.22 * S, 0.4 * S, 0.22 * S, ICE3);
        k.hip(x, y + 0.3 * S, z, 0.22 * S, -0.3 * S, 0.22 * S, ICE);
        break;
      case 1: // a bear
        k.box(x, y, z, 0.18 * S, 0.2 * S, 0.3 * S, ICE3);
        k.box(x, y + 0.14 * S, z + 0.18 * S, 0.12 * S, 0.12 * S, 0.12 * S, ICE);
        break;
      case 2: // a swan
        k.box(x, y, z, 0.16 * S, 0.12 * S, 0.28 * S, ICE3);
        k.bar([x, y + 0.1 * S, z + 0.1 * S], [x, y + 0.36 * S, z + 0.16 * S], 0.025 * S, ICE);
        k.box(x, y + 0.34 * S, z + 0.2 * S, 0.04 * S, 0.04 * S, 0.08 * S, ICE);
        break;
      default: // a spire of stacked cones
        k.cone(x, y, z, 0.15 * S, 0.3 * S, ICE3, 6);
        k.cone(x, y + 0.2 * S, z, 0.1 * S, 0.3 * S, ICE, 6);
    }
  }
  k.box(cx, 0, cz, 0.36, 0.35, 0.36, ICE2);
  k.hip(cx, 0.8, cz, 0.5, 0.8, 0.5, ICE3);
  k.hip(cx, 0.8, cz, 0.5, -0.45, 0.5, ICE);
  k.glowBox(cx, 0.35, cz, 0.14, 0.14, 0.14, ICE3, NIGHT, ICE_GLOW);
  // birches of frost and drifts at the sides
  for (const [x, z] of [[-5, 3.5], [-4.2, 5], [5.1, 4.2], [4.4, 2.8], [-5.3, 1.6], [5.4, -2]]) {
    k.cyl(x, 0, z, 0.03, 0.55 + r() * 0.2, WHITE, 5);
    k.cone(x, 0.4, z, 0.2, 0.55, hex(0xe0ecf0), 6);
  }
};

export const ICEFIELD_DRAW: Partial<Record<RegionBuildingKind, Draw>> = {
  researchStation, sauna, sledKennels, fishRacks, iceHotel,
};

