import { hex, scale, type RGB } from '../../world/biomes';
import type { Rng } from '../../world/rng';
import type { PlayKind } from '../../world/playKinds';
import type { Building } from '../../world/tiles';
import {
  BRICK, BRIGHT, DARK, GLASS_LIGHT, METAL, ROOF_GREY, STONE, WHITE, WOOD, cur, flatTop, pick, roofOver, row, styleRoof,
  styleTrim, styleWall, tree, win, type Draw, type Kit,
} from './kit';
import { chainFence, clock, flag } from './civic';
import { frontText } from './neon';
import { kidsRig, roll, pickPalette, pickSurface, playBench, playEquipment, schoolDay, type Rect } from './playKit';

/**
 * The elementary school (world/playKinds.ts): a one- or two-storey primary school along the front of a 4 × 3
 * lot (a long block, an L, or two classroom wings either side of a hall), its entrance under a canopy up a
 * couple of steps, a sign by the path, a flag, a bell cupola or a clock; behind it a tarmac yard painted with
 * a hopscotch, a four-square and a running track, a hoop or a little goal, benches and a tree or two, and a
 * fenced jungle gym (playKit.ts). Children pour out at break, at lunch and at home time on school days.
 */

const TARMAC = hex(0x5e6266), LINE = hex(0xf4f2ec), PAINT = [0xf2c14e, 0xe2412f, 0x2f7fb5, 0x3f9b4a, 0xf4f2ec];
const ORANGE = hex(0xe8742a), PAVING = hex(0xcfc6b0);

/** A block of classrooms: walls, roof, rows of windows on every face. Returns the top of its roof. */
function block(k: Kit, b: Building, r: Rng, x: number, z: number, w: number, d: number, H: number, floors: number,
  wall: RGB, roof: RGB, flat: boolean, door?: number): number {
  k.box(x, 0, z, w, H, d, wall, ROOF_GREY);
  let top: number;
  if (flat) top = flatTop(k, r, x, H, z, w, d, wall);
  else if (!cur.form || cur.form === 'gable') {
    // a plain gable, kept low enough that a two-storey school stays under its height
    const e = cur.eaves, alongZ = d > w * 1.2, rh = Math.min(floors > 1 ? 0.34 : 0.42, Math.min(w, d) * Math.max(0.24, cur.pitch) * 0.9);
    k.gable(x, H, z, w + 2 * e, rh, d + 2 * e, roof, wall, alongZ);
    top = H + rh;
  } else top = roofOver(k, r, x, H, z, w, d, wall, roof);
  const fz = z + d / 2, bz = z - d / 2, sh = H / floors;
  for (let f = 0; f < floors; f++) {
    const y = f * sh + sh * 0.3, wh = sh * 0.46;
    if (door !== undefined && f === 0) {
      // leave room for the entrance on the ground floor
      const l0 = x - w / 2 + 0.1, l1 = door - 0.32, r0 = door + 0.32, r1 = x + w / 2 - 0.1;
      if (l1 - l0 > 0.15) row(k, b, r, (l0 + l1) / 2, y, fz, l1 - l0, wh, Math.max(1, Math.round((l1 - l0) / 0.24)), 1);
      if (r1 - r0 > 0.15) row(k, b, r, (r0 + r1) / 2, y, fz, r1 - r0, wh, Math.max(1, Math.round((r1 - r0) / 0.24)), 1);
    } else row(k, b, r, x, y, fz, w - 0.2, wh, Math.max(1, Math.round((w - 0.2) / 0.24)), 1);
    row(k, b, r, x, y, bz, w - 0.2, wh, Math.max(1, Math.round((w - 0.2) / 0.26)), 3);
    if (d > 0.5) for (const [sx, face] of [[1, 0], [-1, 2]] as const) row(k, b, r, x + sx * w / 2, y, z, d - 0.24, wh, Math.max(1, Math.round((d - 0.24) / 0.3)), face);
  }
  return top;
}

/** The entrance on a front facing +z at fz: a glazed door, a canopy on two posts, a landing and a step. */
function entrance(k: Kit, b: Building, r: Rng, x: number, fz: number, trim: RGB, band: RGB): void {
  k.box(x, 0, fz + 0.012, 0.26, 0.23, 0.024, scale(band, 0.7));
  win(k, b, r, x, 0.02, fz + 0.024, 0.2, 0.19, 1, GLASS_LIGHT);
  k.box(x, 0, fz + 0.15, 0.5, 0.03, 0.28, hex(STONE[1]));
  k.box(x, 0, fz + 0.33, 0.4, 0.015, 0.09, hex(STONE[2]));
  for (const s of [-1, 1]) k.box(x + s * 0.22, 0.03, fz + 0.27, 0.02, 0.24, 0.02, trim);
  k.box(x, 0.27, fz + 0.15, 0.56, 0.022, 0.3, trim);
  k.box(x, 0.245, fz + 0.3, 0.56, 0.025, 0.012, band);
}

/** A bell cupola standing on y: a base, four posts, a bell inside and a little pyramid cap; or a clock in its face. */
function cupola(k: Kit, x: number, y: number, z: number, trim: RGB, roof: RGB, withClock: boolean): void {
  const s = 0.14;
  k.box(x, y - 0.04, z, s, 0.1, s, trim);
  if (withClock) {
    k.box(x, y + 0.06, z, s, 0.13, s, trim);
    clock(k, x, y + 0.125, z + s / 2, 0.045, false);
  } else {
    for (const sx of [-1, 1]) for (const sz of [-1, 1]) k.box(x + sx * (s / 2 - 0.01), y + 0.06, z + sz * (s / 2 - 0.01), 0.02, 0.13, 0.02, trim);
    k.cone(x, y + 0.08, z, 0.035, 0.07, hex(0xc9a24a), 6);
  }
  k.box(x, y + 0.19, z, s + 0.03, 0.015, s + 0.03, trim);
  k.hip(x, y + 0.205, z, s + 0.03, 0.12, s + 0.03, roof);
  k.box(x, y + 0.325, z, 0.008, 0.06, 0.008, DARK);
}

/** A row of bike stands along x at (x, z), with a bike or two in them. */
function bikeRack(k: Kit, r: Rng, x: number, z: number, n = 4): void {
  for (let i = 0; i < n; i++) {
    const sx = x + (i - (n - 1) / 2) * 0.09;
    for (const s of [-1, 1]) k.box(sx, 0, z + s * 0.025, 0.008, 0.05, 0.008, METAL);
    k.box(sx, 0.05, z, 0.008, 0.008, 0.058, METAL);
    if (r() < 0.45) {
      const col = pick(r, BRIGHT);
      for (const s of [-1, 1]) k.box(sx + 0.03, 0, z + s * 0.045, 0.008, 0.05, 0.05, DARK);
      k.box(sx + 0.03, 0.035, z, 0.008, 0.012, 0.085, col);
      k.box(sx + 0.03, 0.05, z - 0.03, 0.01, 0.008, 0.02, DARK);
    }
  }
}

/** A hopscotch along x from (x0, z): ones and pairs of squares, as painted on a yard. Returns its far end. */
function hopscotch(k: Kit, r: Rng, x0: number, z: number, dir: number): number {
  const c = 0.075, g = 0.012, col = hex(PAINT[Math.floor(r() * PAINT.length)]), col2 = hex(PAINT[Math.floor(r() * PAINT.length)]);
  const plan = [1, 1, 2, 1, 2, 1];
  let x = x0;
  plan.forEach((n, i) => {
    const xx = x + dir * (c / 2);
    if (n === 1) k.box(xx, 0.008, z, c, 0.003, c, i % 2 ? col2 : col);
    else for (const s of [-1, 1]) k.box(xx, 0.008, z + s * (c / 2 + g / 2), c, 0.003, c, s > 0 ? col : col2);
    x += dir * (c + g);
  });
  return x;
}

/** A four-square at (x, z): a square of four coloured quarters. */
function fourSquare(k: Kit, r: Rng, x: number, z: number, s = 0.2): void {
  const g = 0.012, q = (s - g) / 2;
  let i = Math.floor(r() * 4);
  for (const sx of [-1, 1]) for (const sz of [-1, 1]) k.box(x + sx * (q / 2 + g / 2), 0.008, z + sz * (q / 2 + g / 2), q, 0.003, q, hex(PAINT[i++ % 4]));
}

/** A running track's line round a rectangle: four strips that only meet at their ends. */
function trackLine(k: Kit, R: Rect, inset = 0.07): void {
  const w = R.w - 2 * inset, d = R.d - 2 * inset, t = 0.014;
  for (const s of [-1, 1]) k.box(R.x, 0.008, R.z + s * (d / 2 - t / 2), w, 0.003, t, LINE);
  for (const s of [-1, 1]) k.box(R.x + s * (w / 2 - t / 2), 0.008, R.z, t, 0.003, d - 2 * t, LINE);
}

/** A basketball hoop on a post at (x, z), its board facing `face` along x (+1 faces +x). */
function hoop(k: Kit, x: number, z: number, face: 1 | -1): void {
  k.box(x, 0, z, 0.022, 0.3, 0.022, DARK);
  k.box(x + face * 0.03, 0.27, z, 0.06, 0.014, 0.014, DARK);
  k.box(x + face * 0.065, 0.24, z, 0.01, 0.09, 0.13, WHITE);
  k.hoop(x + face * 0.095, 0.25, z, 0.025, 0.003, ORANGE, 6, 'xz');
}

/** A little goal at (x, z), its mouth facing `face` along x. */
function goal(k: Kit, x: number, z: number, face: 1 | -1): void {
  for (const s of [-1, 1]) k.box(x, 0, z + s * 0.12, 0.012, 0.12, 0.012, WHITE);
  k.box(x, 0.12, z, 0.012, 0.012, 0.252, WHITE);
  for (const s of [-1, 1]) k.bar([x, 0.12, z + s * 0.12], [x - face * 0.08, 0, z + s * 0.12], 0.005, WHITE);
  k.box(x - face * 0.08, 0, z, 0.008, 0.008, 0.24, WHITE);
}

/** A picnic table with its two benches, along x. */
function picnicTable(k: Kit, x: number, z: number): void {
  k.box(x, 0.06, z, 0.24, 0.012, 0.11, WOOD);
  for (const s of [-1, 1]) {
    k.box(x, 0.034, z + s * 0.09, 0.24, 0.01, 0.04, WOOD);
    k.box(x + s * 0.09, 0, z, 0.015, 0.06, 0.2, scale(WOOD, 0.8));
  }
}

type Layout = 'long' | 'ell' | 'wings';

const elementarySchool: Draw = (k, W, D, b, r, t) => {
  const layout: Layout = (['long', 'ell', 'wings'] as const)[roll(r, 3)];
  const floors = roll(r, 2) ? 2 : 1, H = floors === 2 ? 0.56 : 0.32;
  const wall = cur.form ? styleWall(r) : r() < 0.65 ? pick(r, BRICK) : styleWall(r);
  const roof = cur.form ? styleRoof(r) : r() < 0.5 ? hex(0x5a5f6b) : styleRoof(r);
  const trim = cur.form ? styleTrim() : hex(0xe9e2d3);
  const band = pick(r, [0x2f7fb5, 0x3f9b4a, 0xe2412f, 0xf2a93b, 0x2bb3a3]);
  // the older styles that keep their roofs flat do so here too, and some of the rest
  const flat = !cur.form && (cur.pitch < 0.2 || r() < 0.35);
  const hw = W / 2, hd = D / 2;
  const fz = 1.1;                               // the street front of the building
  let doorX = 0, top = 0, cupX = 0, cupZ = 0.7;
  let gym: Rect, yard: Rect[];
  const side = roll(r, 2) ? 1 : -1;            // which side the jungle gym is on
  if (layout === 'long') {
    const w = 3.1;
    top = block(k, b, r, 0, 0.7, w, 0.8, H, floors, wall, roof, flat, 0);
    gym = { x: side * 1.25, z: -0.62, w: 1.3, d: 1.5 };
    yard = [{ x: -side * 0.68, z: -0.62, w: 2.5, d: 1.6 }];
  } else if (layout === 'ell') {
    // the front block, and a wing running back down one side (the far side from the gym)
    const fx0 = -hw + 0.3, fx1 = 0.9;
    const fw = fx1 - fx0, fcx = (fx0 + fx1) / 2;
    const wingX = 1.3, wingW = 0.8, wz0 = -0.75, wz1 = fz, wingD = wz1 - wz0;
    const flip = side;                         // mirror the plan so the wing is away from the gym
    const sx = (v: number) => -flip * v;
    doorX = sx(fcx - 0.2);
    top = block(k, b, r, sx(fcx), 0.7, fw, 0.8, H, floors, wall, roof, flat, doorX);
    block(k, b, r, sx(wingX), (wz0 + wz1) / 2, wingW, wingD, H, floors, wall, roof, flat);
    cupX = sx(fcx);
    gym = { x: side * 1.12, z: -0.6, w: 1.5, d: 1.5 };
    yard = [
      { x: sx(0.27), z: -0.3, w: 1.15, d: 1.0 },
      { x: sx(0.75), z: -1.12, w: 2.15, d: 0.62 },
    ];
  } else {
    // two classroom wings either side of a taller hall with the door
    const ww = 1.15, wx = 1.75 - ww / 2;
    for (const s of [-1, 1]) block(k, b, r, s * wx, 0.62, ww, 0.95, H, floors, wall, roof, flat);
    const hh = floors === 2 ? H + 0.04 : 0.42;
    top = block(k, b, r, 0, 0.75, 1.2, 0.7, hh, 1, scale(wall, 0.96), roof, flat, 0);
    // a tall window over the door to light the hall
    win(k, b, r, 0, hh * 0.72, 1.1, 0.5, hh * 0.2, 1);
    cupZ = 0.75;
    gym = { x: side * 1.22, z: -0.7, w: 1.35, d: 1.35 };
    yard = [{ x: -side * 0.64, z: -0.68, w: 2.6, d: 1.45 }];
  }
  entrance(k, b, r, doorX, fz, trim, band);
  // a door out to the yard at the back
  const bzDoor = layout === 'wings' ? 0.4 : 0.3;
  const yd = layout === 'ell' ? -side * 0.3 : -side * 0.5;
  k.box(yd, 0, bzDoor - 0.012, 0.18, 0.2, 0.024, scale(band, 0.7));
  k.box(yd, 0.22, bzDoor - 0.08, 0.3, 0.018, 0.16, trim);
  // the bell (or a clock) on the main roof, standing on its ridge or its flat top
  cupola(k, cupX, top - (flat ? 0.04 : 0.06), cupZ, trim, roof, r() < 0.35);

  // the front: a path in from the gate, the sign by it, the flag, the bike rack, low hedges
  k.box(doorX, 0, (fz + 0.38 + hd) / 2, 0.3, 0.006, hd - fz - 0.38, PAVING);
  const signX = doorX + (doorX > 0 ? -0.55 : 0.55), name = (t?.name ?? '').toUpperCase().replace(/[^A-Z ]/g, '').trim();
  const text = name && name.length <= 9 && r() < 0.6 ? `${name} SCHOOL` : 'SCHOOL';
  const sw = 0.62;
  for (const s of [-1, 1]) k.box(signX + s * (sw / 2 + 0.013), 0, 1.38, 0.025, 0.15, 0.025, trim);
  k.box(signX, 0.06, 1.38, sw, 0.11, 0.02, band);
  frontText(k, text, signX, 0.08, 1.39, Math.min(0.07, (sw - 0.06) / (text.length * 0.66)), WHITE);
  const flagX = doorX > 0 ? -1.5 : 1.5;
  flag(k, flagX, 0, 1.3, 0.85, pick(r, [0xe2412f, 0x2f7fb5, 0x3f9b4a, 0xf2c14e]));
  bikeRack(k, r, 2 * doorX - signX, 1.33);
  for (const s of [-1, 1]) {
    const hx = s * 1.72;
    if (Math.abs(hx - flagX) > 0.3) tree(k, hx, 0, 1.3, 0.55, cur.pitch > 0.45);
  }

  // the yard: tarmac, its markings, a hoop or a goal, benches by the wall, a tree
  for (const R of yard) k.box(R.x, 0, R.z, R.w, 0.008, R.d, TARMAC);
  const main = yard.reduce((a, c) => (c.w * c.d > a.w * a.d ? c : a));
  trackLine(k, main);
  // the hopscotch along the back edge from the far end, the four-square nearer the middle, the hoop at the far end
  const hx0 = main.x - side * (main.w / 2 - 0.3), hz0 = main.z - main.d / 2 + 0.16;
  const hopEnd = hopscotch(k, r, hx0, hz0, side);
  const fsx = main.x + side * 0.3, fsz = main.z + Math.min(0.2, main.d / 2 - 0.2);
  fourSquare(k, r, fsx, fsz);
  const endX = main.x - side * (main.w / 2 - 0.08);
  if (r() < 0.55) hoop(k, endX, main.z, side > 0 ? 1 : -1);
  else goal(k, endX, main.z, side > 0 ? 1 : -1);
  playBench(k, main.x + side * 0.45, main.z + main.d / 2 - 0.1, Math.PI, WOOD);
  if (main.d > 1) picnicTable(k, main.x - side * 0.35, main.z + main.d / 2 - 0.18);
  tree(k, -side * (hw - 0.2), 0, -hd + 0.2, 0.75, cur.pitch > 0.45);

  // the jungle gym, fenced, on its soft ground
  const surf = pickSurface(r), pal = pickPalette(r);
  k.box(gym.x, 0, gym.z, gym.w - 0.04, 0.01, gym.d - 0.04, surf);
  chainFence(k, gym.x, gym.z, gym.w, gym.d, 0.1, 0.26);
  const spots = playEquipment(k, gym.x, gym.z, gym.w - 0.12, gym.d - 0.12, r, pal, 5, 4);

  // break at a quarter past ten, lunch at noon, home time at three; not at weekends or in the holidays
  kidsRig(k, {
    spots, run: [...yard.map((R) => ({ x: R.x, z: R.z, w: R.w - 0.15, d: R.d - 0.15 })), { x: gym.x, z: gym.z, w: gym.w - 0.2, d: gym.d - 0.2 }].slice(0, 2),
    parts: 8,
    group: { x: fsx, z: fsz, rad: 0.13, n: 3 },
    hop: { a: [hx0, hz0], b: [hopEnd - side * 0.04, hz0] },
    leave: { door: [doorX, fz + 0.12], gate: hd - 0.1, edge: hw - 0.05 },
    when: (h) => {
      if (!schoolDay()) return null;
      if ((h >= 10.25 && h < 10.75) || (h >= 12 && h < 13)) return 'play';
      if (h >= 15 && h < 15.5) return 'leave';
      return null;
    },
  }, r);
};

/** The elementary school (world/playKinds.ts). */
export const PLAY_B_DRAW: Partial<Record<PlayKind, Draw>> = { elementarySchool };
