/**
 * The title reel's director: owns the camera while the title is up, plays a programme of shots
 * found in the real world of this seed, and travels between cells the macro layer promises.
 *
 * A cut is the game's own look used as a wipe: the tilt-shift band closes until the whole frame is
 * blurred, the hour, the season, the camera and the cell change while it is shut, and it opens on
 * the new shot. A stop is kept in memory and its chunks warmed two shots ahead, so the band never
 * opens on coarse ground; a stop that is not ready in time is skipped.
 */
import * as THREE from 'three';
import type { World } from '../world/tiles';
import { findShots, findStops, type Category, type Shot, type Stop } from './shots';

/** What the director needs from the game. main.ts implements it. */
export interface ReelHost {
  seedHash(): number;
  /** The cell the reel stands in. */
  centre(): [number, number];
  worldAt(cx: number, cz: number): World | null;
  /** A cell and all its neighbours are in memory. */
  ready(cx: number, cz: number): boolean;
  keep(cx: number, cz: number): void;
  release(): void;
  /** Make this cell the reel's centre: the traffic and people round it come alive, the rest go. */
  moveTo(cx: number, cz: number): void;
  /** Build chunks round a point that is not the focus yet; returns how many are still missing. */
  warm(gx: number, gz: number, ms: number): number;
  setLight(hour: number, season: number | null): void;
  /** A CPU vehicle of this kind near a point, to follow: a handle that reads its global pose. */
  hero(kind: 'land' | 'water' | 'air' | 'rail', w: World, x: number, z: number, avoid?: string[]): (() => { x: number; y: number; z: number; heading: number } | null) | null;
  pose(yaw: number, pitch: number, dist: number, target: THREE.Vector3): void;
  /** The tilt-shift band: its centre on screen and its half-height (negative blurs everything). */
  setBand(focus: number, band: number): void;
}

type Entry = { shot: Shot } | { stop: Stop; picked?: Shot[] };

const CLOSE = 0.45;
const SHUT = -0.62;
/** The longest a cut waits, blurred, for a stop to be ready before skipping it. */
const WAIT = 1.2;

const ease = (t: number) => t * t * (3 - 2 * t);

export class Director {
  private queue: Entry[] = [];
  private shot: Shot | null = null;
  private t = 0;
  private phase: 'open' | 'play' | 'close' | 'wait' = 'wait';
  private phaseT = 0;
  private waited = 0;
  private follow: (() => { x: number; y: number; z: number; heading: number } | null) | null = null;
  private followYaw = 0;
  private rnd = Math.random;
  private seenPlaces = new Set<string>();
  private readonly target = new THREE.Vector3();
  readonly caption: HTMLDivElement;
  /** The shots played, most recent last, for the console. */
  readonly history: string[] = [];
  active = false;
  /**
   * Where across the screen the subject is framed: 0 the middle, `shift` of the half-width to the right (a menu
   * panel down the left covers that share of the width, and the subject sits in the middle of what's left).
   */
  shift = 0;
  private shiftNow = 0;
  /**
   * The centred sign-in title (title/menu.ts TITLE_LAYOUT 'centre'): its column stands in the middle, so the
   * subject goes beside it, `shift` to the right or as far to the left, changing sides at every cut (the user,
   * 23 Oct 2026: the places shown were hidden behind the sign-in card).
   */
  alternate = false;
  private side = 1;
  /** The shift wanted now: to one side of a centred column or the other, or right of a panel. */
  private get shiftWant(): number { return this.alternate ? this.shift * this.side : this.shift; }
  /** Share of the screen height a menu sheet covers along the bottom (a phone's): the subject is framed above it. */
  lift = 0;
  private liftNow = 0;
  /**
   * How much further back to stand than the shot asks: a narrow or upright screen sees far less of the
   * width than the wide screen the shots were chosen on, so the subject would run off both sides.
   */
  widen = 1;
  private widenNow = 1;
  /** tan of half the camera's vertical field of view (main.ts: 18°): how far up the screen a shift moves the subject. */
  vTan = Math.tan((9 * Math.PI) / 180);

  /** The tilt-shift band's height on the screen (0 bottom, 1 top): on the subject, which a sheet lifts. */
  private get focus(): number { return 0.5 + this.liftNow / 2; }

  constructor(private host: ReelHost) {
    // the title hides the game's chips and shows only its caption, bottom right
    const style = document.createElement('style');
    style.textContent = `
      body.title-mode .hud:not(.reel-caption), body.title-mode .minimap, body.title-mode #toast { display: none !important; }
      .reel-caption { right: 16px; bottom: 16px; font-size: 13px; font-weight: 600; color: #1f2b33; z-index: 5; }
      .reel-caption[hidden] { display: none; }`;
    document.head.appendChild(style);
    this.caption = document.createElement('div');
    this.caption.className = 'reel-caption hud chip';
    this.caption.hidden = true;
    document.body.appendChild(this.caption);
  }

  /** Start (or restart) the reel on the host's current cell. */
  start(): void {
    this.active = true;
    this.queue = [];
    this.shot = null;
    this.phase = 'wait';
    this.phaseT = 0;
    this.waited = 0;
    this.host.setBand(this.focus, SHUT);
  }

  stop(): void {
    this.active = false;
    this.caption.hidden = true;
    this.host.release();
    this.follow = null;
  }

  /** The shot on screen, for the console and for a save's memento. */
  get current(): Shot | null { return this.shot; }

  /** Skip to the next shot. */
  next(): void { if (this.phase === 'play' || this.phase === 'open') { this.phase = 'close'; this.phaseT = 0; } }

  // ---------------------------------------------------------------------------------------------
  // the programme

  /**
   * About fourteen shots: the best of each kind the home neighbourhood holds, with up to three
   * trips out to what the macro layer promises nearby, never two of one kind in a row.
   */
  private plan(): void {
    const [cx, cz] = this.host.centre();
    const home: Shot[] = [];
    for (let dz = -1; dz <= 1; dz++) for (let dx = -1; dx <= 1; dx++) {
      const w = this.host.worldAt(cx + dx, cz + dz);
      if (w) home.push(...findShots(w, this.rnd));
    }
    // the best shot of each kind, a place seen last loop scoring lower, and up to two heroes
    const best = new Map<string, Shot>();
    for (const s of home) {
      const key = s.cat === 'hero' ? `hero-${s.hero}` : s.cat;
      const score = s.score - (this.seenPlaces.has(s.caption) ? 0.8 : 0) + this.rnd() * 0.3;
      const have = best.get(key);
      if (!have || score > have.score) best.set(key, { ...s, score });
    }
    const pool = [...best.values()].sort((a, b) => b.score - a.score).slice(0, 9);
    // open on the cheapest good shot the centre cell has, so the title is up at once
    pool.sort((a, b) => Number(b.cx === cx && b.cz === cz && b.cat !== 'hero') - Number(a.cx === cx && a.cz === cz && a.cat !== 'hero'));
    const ordered: Shot[] = [];
    while (pool.length) {
      const last = ordered[ordered.length - 1];
      const k = pool.findIndex((s) => !last || s.cat !== last.cat);
      ordered.push(pool.splice(k < 0 ? 0 : k, 1)[0]);
    }
    const stops = findStops(this.host.seedHash(), cx, cz).slice(0, 3);
    this.queue = [];
    ordered.forEach((s, i) => {
      this.queue.push({ shot: s });
      const stop = stops[Math.floor(i / 3)];
      if (i % 3 === 2 && stop) this.queue.push({ stop });
    });
    if (!this.queue.length && stops.length) this.queue.push({ stop: stops[0] });
  }

  /** The next entry that is a shot, resolving a stop into its shots once its cell is here. */
  private take(): Shot | null {
    for (let guard = 0; guard < 40; guard++) {
      if (!this.queue.length) this.plan();
      const e = this.queue[0];
      if (!e) return null;
      if ('shot' in e) { this.queue.shift(); return e.shot; }
      // a stop: its cells should have been asked for two shots ago
      if (!this.host.ready(e.stop.cx, e.stop.cz)) return null;
      const w = this.host.worldAt(e.stop.cx, e.stop.cz)!;
      const found = findShots(w, this.rnd).filter((s) => e.stop.want.includes(s.cat as Category));
      const picked: Shot[] = [];
      for (const cat of e.stop.want) {
        const s = found.filter((f) => f.cat === cat).sort((a, b) => b.score - a.score)[0];
        if (s && picked.length < 3) picked.push(s);
      }
      this.queue.shift();
      this.queue.unshift(...picked.map((shot) => ({ shot })));
    }
    return null;
  }

  /** Ask for the stops coming up in the next few entries, so they are generated in time. */
  private lookAhead(): void {
    for (const e of this.queue.slice(0, 3)) if ('stop' in e) this.host.keep(e.stop.cx, e.stop.cz);
  }

  // ---------------------------------------------------------------------------------------------
  // the frame

  update(dt: number): void {
    if (!this.active) return;
    this.phaseT += dt;
    if (this.phase === 'wait') {
      this.host.setBand(this.focus, SHUT);
      const next = this.take();
      if (!next) {
        this.waited += dt;
        // a stop that will not come: skip it
        if (this.waited > WAIT && this.queue[0] && 'stop' in this.queue[0]) { this.queue.shift(); this.waited = 0; }
        if (this.shot) this.pose(this.shot, 1);
        return;
      }
      if (!this.apply(next)) return;
      this.waited = 0;
      this.phase = 'open';
      this.phaseT = 0;
      this.lookAhead();
    }
    const s = this.shot!;
    this.t += dt;
    const k = Math.min(1, this.t / s.len);
    this.pose(s, k);
    if (this.phase === 'open') {
      // hold the band shut until the ground round the shot is built
      const missing = this.host.warm(s.x, s.z, 3);
      if (missing > 0 && this.phaseT < WAIT) { this.host.setBand(this.focus, SHUT); this.t = 0; return; }
      const o = Math.min(1, this.phaseT / CLOSE);
      this.host.setBand(this.focus, SHUT + (s.band - SHUT) * ease(o));
      if (o >= 1) { this.phase = 'play'; this.phaseT = 0; }
    } else if (this.phase === 'play') {
      this.host.setBand(this.focus, s.band);
      if (this.t >= s.len - CLOSE) { this.phase = 'close'; this.phaseT = 0; }
      // warm what is coming while this one plays
      const e = this.queue[0];
      if (e && 'shot' in e) this.host.warm(e.shot.x, e.shot.z, 1.5);
    } else if (this.phase === 'close') {
      const c = Math.min(1, this.phaseT / CLOSE);
      this.host.setBand(this.focus, s.band + (SHUT - s.band) * ease(c));
      if (c >= 1) { this.phase = 'wait'; this.phaseT = 0; this.caption.hidden = true; }
    }
  }

  /** Put a shot on: travel to its cell, set its light, find its hero. False to skip it. */
  private apply(s: Shot): boolean {
    const [cx, cz] = this.host.centre();
    if (s.cx !== cx || s.cz !== cz) {
      // shots in the home neighbourhood are filmed from where the reel stands; a stop moves it
      if (Math.abs(s.cx - cx) > 1 || Math.abs(s.cz - cz) > 1) {
        if (!this.host.ready(s.cx, s.cz)) return false;
        // let the kept cells go first, so moving the centre drops the old neighbourhood at once
        this.host.release();
        this.host.moveTo(s.cx, s.cz);
      }
    }
    this.follow = null;
    if (s.move === 'follow') {
      const w = this.host.worldAt(s.cx, s.cz);
      const handle = w && s.hero ? this.host.hero(s.hero, w, s.x - w.ox, s.z - w.oz) : null;
      const first = handle?.();
      if (!handle || !first) return this.skip();
      this.follow = handle;
      this.followYaw = first.heading + Math.PI;
      s.caption = s.caption || `${s.hero === 'air' ? 'Over' : s.hero === 'water' ? 'Off' : s.hero === 'rail' ? 'By rail through' : 'Through'} ${this.host.worldAt(s.cx, s.cz)?.name ?? ''}`;
    }
    this.shot = s;
    this.t = 0;
    // beside a centred column: the other side this time, taken at once (the cut hides the jump) rather than
    // slid across the screen through the shot's first second
    if (this.alternate) {
      this.side = -this.side;
      this.shiftNow = this.shiftWant;
    }
    this.host.setLight(s.hour, s.season);
    this.seenPlaces.add(s.caption);
    this.history.push(`${s.cat}: ${s.caption}`);
    if (this.history.length > 40) this.history.shift();
    this.caption.textContent = s.caption;
    this.caption.hidden = !s.caption;
    return true;
  }

  private skip(): boolean { return false; }

  private pose(s: Shot, k: number): void {
    this.shiftNow += (this.shiftWant - this.shiftNow) * 0.05;
    this.liftNow += (this.lift - this.liftNow) * 0.05;
    this.widenNow += (this.widen - this.widenNow) * 0.05;
    const e = ease(k);
    const pitch = s.pitch0 + (s.pitch1 - s.pitch0) * e;
    const dist = (s.dist0 + (s.dist1 - s.dist0) * e) * this.widenNow;
    if (this.follow) {
      const p = this.follow();
      if (p) {
        this.target.set(p.x, p.y, p.z);
        const want = p.heading + Math.PI;
        this.followYaw += Math.atan2(Math.sin(want - this.followYaw), Math.cos(want - this.followYaw)) * 0.04;
      }
      this.offset(this.followYaw, dist);
      this.raise(this.followYaw, pitch, dist);
      this.host.pose(this.followYaw, pitch, dist, this.target);
      return;
    }
    const yaw = s.yaw0 + (s.yaw1 - s.yaw0) * k;
    let x = s.x, z = s.z;
    if (s.move === 'dolly') {
      const g = s.glide * (2 * k - 1);
      x += Math.cos(yaw) * g;
      z -= Math.sin(yaw) * g;
    }
    this.target.set(x, s.y, z);
    this.offset(yaw, dist);
    this.raise(yaw, pitch, dist);
    this.host.pose(yaw, pitch, dist, this.target);
  }

  /**
   * Slide the aim point toward the camera, so the subject sits up in the open part of the frame above a
   * sheet: by `lift` of the half-height, which on the ground is that over the sine of the pitch.
   */
  private raise(yaw: number, pitch: number, dist: number): void {
    if (this.liftNow < 0.001) return;
    const k = Math.min(dist * 0.9, (dist * this.liftNow * this.vTan) / Math.max(0.3, Math.sin(pitch)));
    this.target.x += Math.sin(yaw) * k;
    this.target.z += Math.cos(yaw) * k;
  }

  /** Slide the aim point along the camera's right (left for a subject framed right, right for one framed left), so the subject sits in the open part of the frame. */
  private offset(yaw: number, dist: number): void {
    if (Math.abs(this.shiftNow) < 0.001) return;
    // `shift` of the half-width across the screen at the subject's distance: dist × tan(half the field of view
    // across), the vertical one's tan times the aspect (a flat 0.62 here put subjects about 2.4× too far out on a
    // 16:10 screen, off it altogether beside the centred title, 23 Oct 2026)
    const k = dist * this.shiftNow * this.vTan * (innerWidth / Math.max(1, innerHeight));
    this.target.x -= Math.cos(yaw) * k;
    this.target.z += Math.sin(yaw) * k;
  }
}
