/**
 * Toppers (docs/toppers.html, phase 1, the user, 4 Nov 2026): roof ornaments a player earns over a long career and
 * puts on any vehicle of theirs, one a vehicle (`Parts.tp`). The Wonder Ball (game/passportRewards.ts) was the first
 * and is the topper `wonder`. This file is what each one is and what earns it; what it looks like is
 * render/toppers.ts, and where it stands on a body is render/treats.ts.
 *
 * Phase 1 is the kept toppers that read only what the deeds' record already keeps: Sworn factions (`facSworn`),
 * knack jobs done (`knack.<job>`, counted as each finishes, game/missions/wire.ts), the lifetime ladders (the
 * odometer, loads, cash earned, the most vehicles at once, lots held, road laid), deeds reached and toppers kept.
 * Every count only climbs, so a topper earned is never lost; the ones earned are kept in the record's `toppers`
 * set too (like the seals), so each is announced once and the Collector can count them.
 *
 * Phase 2 is the crowns (`CROWNS`): a gold, a silver and a bronze for every cargo kind and culture, held, not kept,
 * by the fleets first, second and third in the world (server/crowns.ts). The server says which this fleet holds
 * (`setCrowns`), and takes a crown it doesn't hold off a look before anyone sees it.
 */

export type TopperFamily = 'passport' | 'faction' | 'knack' | 'milestone' | 'culture' | 'mascot' | 'souvenir' | 'curio' | 'tale' | 'afterDark' | 'season' | 'deeds' | 'collector'
  | 'cargoCrown' | 'cultureCrown' | 'loadsCrown' | 'earnCrown' | 'rush' | 'challenge' | 'record' | 'track';

export const FAMILY_LABEL: Record<TopperFamily, string> = {
  passport: 'Passport', faction: 'Faction Toppers', knack: 'Knack Badges', milestone: 'Milestones', culture: 'Culture Toppers', mascot: 'Mascots', souvenir: 'Souvenirs', curio: 'Curios', tale: 'Tales', afterDark: 'After Dark', season: 'Seasons', deeds: 'Deeds', collector: 'Collector',
  rush: 'Rush Pennants', challenge: 'Challenge Flags', record: 'Range Trophies', track: 'Track Trophies',
  cargoCrown: 'Cargo Crowns', cultureCrown: 'Culture Crowns', loadsCrown: 'Vehicle Load Crowns', earnCrown: 'Vehicle Earnings Crowns',
};
/** The kept families, in the Rack's order (the crowns have their own section). */
export const FAMILIES: TopperFamily[] = ['faction', 'knack', 'milestone', 'culture', 'mascot', 'souvenir', 'curio', 'tale', 'afterDark', 'season', 'deeds', 'collector', 'passport'];
/** The held families besides the crowns (phase 4), shown with them. */
export const HELD_FAMILIES: TopperFamily[] = ['rush', 'challenge', 'record', 'track'];

/** What a topper's progress is read from: the deeds' record (a stand-in for the gate). */
export interface TopperRecord {
  count(stat: Stat): number;
  has(stat: Stat, key: string): boolean;
  keys(stat: Stat): string[];
  /** Deeds reached at any tier. */
  deedsReached(): number;
  /** The Wonder Ball's seal. */
  wonder(): boolean;
}

export interface Topper {
  id: string;
  family: TopperFamily;
  name: string;
  icon: string;
  /** What it is, for its card and tooltip. */
  look: string;
  /** How it is earned, in a few words. */
  how: string;
  /** How far along: [have, need]. Earned when have >= need. */
  progress(r: TopperRecord): [number, number];
  /** A metal step on a ladder (milestones, deeds, collector): 1 bronze … 4 platinum. */
  step?: number;
}

