const short = (n: number): string => (n >= 1e9 ? `${n / 1e9}B` : n >= 1e6 ? `${n / 1e6}M` : n >= 1e3 ? `${n / 1e3}k` : String(n));

function build(): Topper[] {
  const out: Topper[] = [];
  out.push({
    id: 'wonder', family: 'passport', name: 'The Wonder Ball', icon: '🪩', look: 'A mirror ball on a chrome mast, throwing coloured light after dark',
    how: 'Every wonder stamped in the Passport', progress: (r) => [r.wonder() ? 1 : 0, 1],
  });
  for (const f of FACTION_IDS) {
    const l = FACTION_LOOK[f];
    out.push({ id: `fac:${f}`, family: 'faction', name: l.name, icon: l.icon, look: l.look, how: `Sworn to ${FACTIONS[f].name}`, progress: (r) => [r.has('facSworn', f) ? 1 : 0, 1] });
  }
  out.push({
    id: 'fac:council', family: 'faction', name: 'The Council', icon: '⚜️', look: 'Ten seals, one a faction, circling the roof',
    how: 'Sworn to all ten factions, one time or another', progress: (r) => [Math.min(FACTION_IDS.length, FACTION_IDS.filter((f) => r.has('facSworn', f)).length), FACTION_IDS.length],
  });
  for (const k of KNACKS) {
    out.push({ id: `knack:${k.job}`, family: 'knack', name: k.name, icon: k.icon, look: k.look, how: `${KNACK_JOBS} ${k.ride} jobs`, progress: (r) => [Math.min(KNACK_JOBS, r.count(knackStat(k.job))), KNACK_JOBS] });
  }
  for (const l of LADDERS) {
    l.steps.forEach((need, i) => {
      const step = i + 1;
      out.push({
        id: `ms:${l.key}${step}`, family: 'milestone', name: `${METAL[step]} ${l.name}`, icon: l.icon, look: l.look, step,
        how: `${short(need)} ${l.unit}`, progress: (r) => [Math.min(need, r.count(l.stat)), need],
      });
    });
  }
  // phase 3: a culture topper for CULTURE_BUILDS copies of a style finished from blueprints, the Patron's in gold at PATRON_BUILDS
  for (const style of CULTURE_STYLES) {
    const [name, look] = CULTURE_LOOK[style] ?? [ARCH_LABEL[style], 'A small landmark of the style'];
    const label = ARCH_LABEL[style];
    out.push({ id: `cul:${style}`, family: 'culture', name, icon: '🏛️', look, how: `${CULTURE_BUILDS} ${label} buildings put up from blueprints`, progress: (r) => [Math.min(CULTURE_BUILDS, r.count(builtStat(style))), CULTURE_BUILDS] });
    out.push({ id: `cul:${style}:p`, family: 'culture', name: `Patron’s ${name}`, icon: '🏛️', look: `${look}, in gold`, step: 3, how: `${PATRON_BUILDS} ${label} buildings put up from blueprints`, progress: (r) => [Math.min(PATRON_BUILDS, r.count(builtStat(style))), PATRON_BUILDS] });
  }
  // and a mascot for every model, a little copy of it, at MASCOT_LOADS loads delivered in it by anyone in the fleet
  for (const d of MASCOT_MODELS) {
    out.push({
      id: `mas:${d.id}`, family: 'mascot', name: `${d.name} Mascot`, icon: d.kind === 'water' ? '⛵' : d.kind === 'air' ? '✈️' : '🚗', look: `A little ${d.name} on a chrome plinth`,
      how: `${MASCOT_LOADS.toLocaleString('en-GB')} loads delivered in a ${d.name}`, progress: (r) => [Math.min(MASCOT_LOADS, r.count(deliveriesStat(d.id))), MASCOT_LOADS],
    });
  }
  // phase 4, kept: a souvenir for each event, a curio for each wild thing, the two tales, after dark, the seasons
  for (const k of EVENT_KINDS) {
    out.push({ id: `ev:${k.id}`, family: 'souvenir', name: `${k.name} Souvenir`, icon: k.icon, look: `A keepsake from the ${k.name.toLowerCase()}`,
      how: `At ${SOUVENIR_RUNS} ${k.name.toLowerCase()}s while they are on`, progress: (r) => [Math.min(SOUVENIR_RUNS, r.count(eventStat(k.id))), SOUVENIR_RUNS] });
  }
  for (const w of WILD_KINDS) {
    out.push({ id: `wd:${w}`, family: 'curio', name: `Little ${WILD_LABEL[w]}`, icon: WILD_ICON[w], look: `The ${WILD_LABEL[w].toLowerCase()}, shrunk to fit a roof`,
      how: `${CURIO_VISITS} ${WILD_LABEL[w].toLowerCase()}s found`, progress: (r) => [Math.min(CURIO_VISITS, r.count(wildStat(w))), CURIO_VISITS] });
  }
  for (const t of TALES) out.push({ id: `tl:${t.id}`, family: 'tale', name: t.name, icon: t.icon, look: t.look, how: `${t.chain} finished`, progress: (r) => [r.has('tales', t.id) ? 1 : 0, 1] });
  for (const a of AFTER_DARK) {
    out.push({ id: `ad:${a.id}`, family: 'afterDark', name: a.name, icon: a.icon, look: a.look, how: a.how,
      progress: (r) => [Math.min(a.need, a.set ? r.keys(a.stat).length : r.count(a.stat)), a.need] });
  }
  for (const s of SEASON_LIST) out.push({ id: `ss:${s.id}`, family: 'season', name: s.name, icon: s.icon, look: s.look, how: `A whole ${s.id} played through`, progress: (r) => [r.has('seasons', s.id) ? 1 : 0, 1] });
  out.push({ id: 'ss:year', family: 'season', name: 'Carousel of Seasons', icon: '🎠', look: 'The four seasons\' toppers turning on a little carousel', how: 'Every season played through',
    progress: (r) => [SEASON_LIST.filter((s) => r.has('seasons', s.id)).length, SEASON_LIST.length] });
  const all = DEEDS.length;
  ([[50, 1], [100, 2], [all, 3]] as const).forEach(([need, step]) => {
    out.push({
      id: `deeds:${step}`, family: 'deeds', name: `${METAL[step]} Laurel`, icon: '🏅', look: 'A laurel wreath standing on its edge', step,
      how: need === all ? 'Every deed reached' : `${need} deeds reached`, progress: (r) => [Math.min(need, r.deedsReached()), need],
    });
  });
  return out;
}

/** Every topper but the Collector's, which count these. */
