/**
 * Shared pieces for the strongholds' models (render/buildings/strongholdsA.ts, strongholdsB.ts): the wall rings of a
 * plan (world/strongholdPlans.ts) with their gates left open, and a barrier arm across a gate. Everything is in the
 * model's frame, as the plan is.
 */
import type { RGB } from '../../world/biomes';
import type { SPlan } from '../../world/strongholdPlans';
import type { Kit } from './kit';

export interface WallLook {
  /** The wall's face and its coping (or a fence's posts and its mesh). */
  face: RGB; cap: RGB;
  /** Piers every so far along it (0: none). */
  pierEvery?: number; pier?: RGB;
}

/** Draw a straight run of wall from a to b in the model's frame. */
function run(k: Kit, p: SPlan, look: WallLook, ax: number, az: number, bx: number, bz: number, gateA = false, gateB = false): void {
  const ex = bx - ax, ez = bz - az, L = Math.hypot(ex, ez);
  if (L < 0.05) return;
  const yaw = Math.atan2(-ez, ex);
  const { h, t, kind } = p.wall;
  k.within((ax + bx) / 2, (az + bz) / 2, yaw, () => {
    if (kind === 'fence') {
      // posts, two rails and a see-through mesh panel (a thin slab), wire along the top
      const n = Math.max(1, Math.round(L / 1.2));
      for (let i = 0; i <= n; i++) k.box(-L / 2 + (i / n) * L, 0, 0, 0.06, h + 0.08, 0.06, look.cap);
      k.box(0, h * 0.25, 0, L, 0.03, 0.03, look.cap);
      k.box(0, h, 0, L, 0.03, 0.03, look.cap);
      k.box(0, 0.02, 0, L, h * 0.95, 0.012, look.face);
    } else {
      k.box(0, 0, 0, L, h, t, look.face);
      k.box(0, h, 0, L + 0.02, 0.06, t + 0.08, look.cap);
      if (look.pierEvery) {
        const n = Math.max(1, Math.round(L / look.pierEvery));
        // no pier at an end cut by a gate: it would stand out into the gap
        for (let i = 0; i <= n; i++) {
          if ((i === 0 && gateA) || (i === n && gateB)) continue;
          k.box(-L / 2 + (i / n) * L, 0, 0, t + 0.14, h + 0.12, t + 0.14, look.pier ?? look.cap);
        }
      }
    }
  });
}

/** Every ring of the plan's walls, each edge cut where a gate stands in it. */
export function drawWalls(k: Kit, p: SPlan, look: WallLook): void {
  p.rings.forEach((ring, ri) => {
    for (let i = 0; i < ring.length; i++) {
      const [ax, az] = ring[i], [bx, bz] = ring[(i + 1) % ring.length];
      const ex = bx - ax, ez = bz - az, L = Math.hypot(ex, ez);
      // the gates on this edge, as [from, to] along it
      const cuts: [number, number][] = [];
      for (const g of p.gates) {
        if (g.ring !== ri) continue;
        const s = ((g.x - ax) * ex + (g.z - az) * ez) / (L * L);
        const off = Math.abs((g.x - ax) * ez - (g.z - az) * ex) / L;
        if (off > 0.4 || s < -0.05 || s > 1.05) continue;
        cuts.push([s * L - g.w / 2, s * L + g.w / 2]);
      }
      cuts.sort((a, b) => a[0] - b[0]);
      let from = 0;
      for (const [c0, c1] of [...cuts, [L, L] as [number, number]]) {
        const to = Math.max(from, Math.min(L, c0));
        if (to > from) run(k, p, look, ax + (ex * from) / L, az + (ez * from) / L, ax + (ex * to) / L, az + (ez * to) / L, from > 0, to < L);
        from = Math.max(from, c1);
      }
    }
  });
}

/** The outward-facing yaw of the edge a gate is cut in (for gate posts, arms and arches), in `within`'s terms. */
export function gateYaw(p: SPlan, gi: number): number {
  const g = p.gates[gi], ring = p.rings[g.ring];
  let best = Infinity, yaw = 0;
  for (let i = 0; i < ring.length; i++) {
    const [ax, az] = ring[i], [bx, bz] = ring[(i + 1) % ring.length];
    const ex = bx - ax, ez = bz - az, L = Math.hypot(ex, ez);
    const s = Math.max(0, Math.min(1, ((g.x - ax) * ex + (g.z - az) * ez) / (L * L)));
    const d = Math.hypot(ax + ex * s - g.x, az + ez * s - g.z);
    if (d < best) { best = d; yaw = Math.atan2(-ez, ex); }
  }
  return yaw;
}

/** Two posts and a striped barrier arm (down) across gate `gi`, drawn along the wall. */
export function gateArm(k: Kit, p: SPlan, gi: number, post: RGB, stripeA: RGB, stripeB: RGB): void {
  const g = p.gates[gi];
  k.within(g.x, g.z, gateYaw(p, gi), () => {
    const hw = g.w / 2;
    k.box(-hw - 0.12, 0, 0, 0.22, 0.5, 0.22, post);
    k.box(hw + 0.12, 0, 0, 0.12, 0.42, 0.12, post);
    const n = 6;
    for (let i = 0; i < n; i++) k.box(-hw + ((i + 0.5) / n) * g.w, 0.36, 0, g.w / n, 0.06, 0.06, i % 2 ? stripeA : stripeB);
  });
}
