import * as THREE from 'three';
import { mergeGeometries } from 'three/examples/jsm/utils/BufferGeometryUtils.js';
import {
  N, STEP, Biome, Feature, Flag, World, DIRS, idx, inB, heightAt, waterDepth, REGION_KINDS, type Building, type RegionKind,
} from '../world/tiles';
import { REGIONS, type HerdKind } from '../world/regions';
import type { Ranch } from '../world/ranches';
import { rand } from '../util/math';

/**
 * The animals and folk that wander a biome's country: camel trains and sled teams on the tracks,
 * herds and flocks drifting over open ground and scattering from the car, cattle by the barn, a ranch's
 * herd inside its pasture's fence with a rider out among them (world/ranches.ts), goats
 * on the crags, surfers on the shelf, hikers and pilgrims in pairs, skiers on the Icefield's slopes.
 * No pathfinding: everything drifts toward a goal, sampling the ground ahead, and the travelling
 * kinds follow road and track tiles greedily toward where they are going.
 */

type Pt = { x: number; z: number };
type Goal = Pt & { r: number };
export type Look =
  | 'camel' | 'elephant' | 'zebra' | 'giraffe' | 'sheep' | 'cow' | 'goat' | 'dog' | 'sled' | 'horse'
  | 'hiker' | 'pilgrim' | 'surfLie' | 'surfStand' | 'skier' | 'rider';

/** Most instances of each look an island draws. */
const CAP: Record<Look, number> = {
  camel: 24, elephant: 70, zebra: 90, giraffe: 50, sheep: 130, cow: 120, goat: 24, dog: 24, sled: 4, horse: 110,
  hiker: 12, pilgrim: 14, surfLie: 18, surfStand: 18, skier: 30, rider: 8,
};

// ---------------------------------------------------------------- shapes

function paint(g: THREE.BufferGeometry, hex: number): THREE.BufferGeometry {
  const out = g.index ? g.toNonIndexed() : g;
  out.deleteAttribute('uv');
  const n = out.attributes.position.count, c = new THREE.Color(hex), a = new Float32Array(n * 3);
  for (let k = 0; k < n; k++) { a[k * 3] = c.r; a[k * 3 + 1] = c.g; a[k * 3 + 2] = c.b; }
  out.setAttribute('color', new THREE.BufferAttribute(a, 3));
  return out;
}
const box = (w: number, h: number, d: number, x: number, y: number, z: number, hex: number, rx = 0) =>
  paint(new THREE.BoxGeometry(w, h, d).rotateX(rx).translate(x, y, z), hex);
const ball = (r: number, x: number, y: number, z: number, hex: number, sx = 1, sy = 1, sz = 1, detail = 1) =>
  paint(new THREE.IcosahedronGeometry(r, detail).scale(sx, sy, sz).translate(x, y, z), hex);
/** A capsule lying along z. */
const pill = (r: number, len: number, x: number, y: number, z: number, hex: number) =>
  paint(new THREE.CapsuleGeometry(r, len, 2, 6).rotateX(Math.PI / 2).translate(x, y, z), hex);
/** A rod standing up, its top tipped toward +z by `tilt`, centred at (x, y, z). */
const rod = (r: number, len: number, x: number, y: number, z: number, hex: number, tilt = 0) =>
  paint(new THREE.CylinderGeometry(r, r, len, 5).rotateX(tilt).translate(x, y, z), hex);
const legs = (sx: number, sz: number, h: number, t: number, hex: number, zOff = 0) =>
  [-1, 1].flatMap((a) => [-1, 1].map((b) => box(t, h, t, a * sx, h / 2, b * sz + zOff, hex)));
const merge = (parts: THREE.BufferGeometry[]) => mergeGeometries(parts)!;

const SKIN = 0xe0b48a;

