const GEO = new Map<Look, { fixed: THREE.BufferGeometry; coat: THREE.BufferGeometry | null }>();
const MAT = new THREE.MeshStandardMaterial({ vertexColors: true, roughness: 0.85, metalness: 0 });

/** One figure of a look on its own, its coat in this colour (a night op's lost hiker, a stray cow). Dispose its group's geometry when done. */
export function lookMesh(look: Look, coat = 0xffffff): THREE.Group {
  const g = new THREE.Group();
  const b = build(look);
  g.add(new THREE.Mesh(b.fixed, MAT));
  if (b.coat) g.add(new THREE.Mesh(b.coat, new THREE.MeshStandardMaterial({ color: coat, vertexColors: true, roughness: 0.85 })));
  return g;
}

// ---------------------------------------------------------------- helpers

/**
 * A penned beast that stepped off its pen goes back to where it stood (from, which was on it). A step is only
 * tested where it ends up ahead, so one cutting a corner of the fence, or one long step after a slow frame,
 * could otherwise end on the far side.
 */
function penned(f: { pen?: Uint8Array }, b: { x: number; z: number }, fx: number, fz: number): void {
  if (!f.pen || f.pen[idx(Math.floor(b.x), Math.floor(b.z))]) return;
  b.x = fx; b.z = fz;
}

/** A ranch's pen: its pasture's tiles, less its roads, its buildings and its water. */
export function penOf(w: World, r: Ranch): Uint8Array {
  const pen = new Uint8Array(N * N);
  for (const i of r.pasture) if (!w.road[i] && !w.blocked[i] && !(w.water[i] >= 0 && waterDepth(w, i) > 0)) pen[i] = 1;
  return pen;
}

function mulberry(seed: number): () => number {
  let a = seed >>> 0;
  return () => {
    a = (a + 0x6d2b79f5) >>> 0;
    let t = a;
    t = Math.imul(t ^ (t >>> 15), t | 1);
    t ^= t + Math.imul(t ^ (t >>> 7), t | 61);
    return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
  };
}

const isNet = (w: World, i: number) => (w.road[i] > 0 || (w.flags[i] & Flag.Track) !== 0) && !w.deckAxis[i];

/**
 * Can a walker step from (x, z) to (px, pz): dry, open, in the cell, no steeper than `climb` per tile? A ranch's
 * herd has its pen, the tiles of its pasture, and never steps off it; anything else keeps out of a ranch's fences.
 */
function walkable(w: World, x: number, z: number, px: number, pz: number, climb: number, pen?: Uint8Array): boolean {
  if (px < 1 || pz < 1 || px >= N - 1 || pz >= N - 1) return false;
  const i = idx(Math.floor(px), Math.floor(pz));
  if (w.blocked[i] || (w.water[i] >= 0 && waterDepth(w, i) > 0)) return false;
  if (pen ? !pen[i] : w.feature[i] === Feature.Pasture && !w.road[i]) return false;
  const d = Math.hypot(px - x, pz - z) || 1e-3;
  return Math.abs(heightAt(w, px, pz) - heightAt(w, x, z)) <= climb * Math.max(d, 0.25);
}

const dryTile = (w: World, i: number) => !w.blocked[i] && !(w.water[i] >= 0 && waterDepth(w, i) > 0);

/** The nearest open dry tile centre to (x, z), within r tiles. */
function nearLand(w: World, x: number, z: number, r = 8): Pt | null {
  const tx = Math.floor(x), tz = Math.floor(z);
  for (let rr = 0; rr <= r; rr++) {
    for (let dz = -rr; dz <= rr; dz++) {
      for (let dx = -rr; dx <= rr; dx++) {
        if (Math.max(Math.abs(dx), Math.abs(dz)) !== rr) continue;
        const nx = tx + dx, nz = tz + dz;
        if (nx < 2 || nz < 2 || nx >= N - 2 || nz >= N - 2) continue;
        if (dryTile(w, idx(nx, nz))) return { x: nx + 0.5, z: nz + 0.5 };
      }
    }
  }
  return null;
}

/** Something walking toward a goal: along the roads and tracks where it can, across country where it can't. */
interface Mover {
  x: number; z: number; yaw: number;
  wx: number; wz: number; hasWp: boolean;
  recent: number[];
  free: number;          // picks left to go across country before trying the network again
  best: number; stuck: number;
  gaveUp: boolean;
  side: number;          // which side of a road to keep to
  moving: boolean;
}
const mover = (p: Pt): Mover => ({ x: p.x, z: p.z, yaw: Math.random() * 6.28, wx: p.x, wz: p.z, hasWp: false, recent: [], free: 0, best: Infinity, stuck: 0, gaveUp: false, side: Math.random() < 0.5 ? -0.22 : 0.22, moving: false });

const turn = (from: number, to: number, k: number) => {
  let d = to - from;
  while (d > Math.PI) d -= Math.PI * 2;
  while (d < -Math.PI) d += Math.PI * 2;
  return from + d * Math.min(1, k);
};

function pickWp(w: World, m: Mover, g: Goal, net: boolean, climb: number, pen?: Uint8Array): void {
  const dist = Math.hypot(g.x - m.x, g.z - m.z);
  if (dist < m.best - 0.5) { m.best = dist; m.stuck = 0; } else m.stuck++;
  if (m.stuck > 70) {
    if (net && m.free <= 0) { m.free = 30; m.stuck = 0; m.best = dist; } else { m.gaveUp = true; return; }
  }
  const tx = Math.floor(m.x), tz = Math.floor(m.z);
  if (!inB(tx, tz)) { m.gaveUp = true; return; }
  const i = idx(tx, tz);
  if (net && m.free <= 0 && dist > 3) {
    if (isNet(w, i)) {
      let bj = -1, bs = Infinity, bd = 0, any = -1, anyD = 0;
      for (let d = 0; d < 4; d++) {
        const nx = tx + DIRS[d][0], nz = tz + DIRS[d][1];
        if (nx < 1 || nz < 1 || nx >= N - 1 || nz >= N - 1) continue;
        const j = idx(nx, nz);
        if (!isNet(w, j) || w.blocked[j]) continue;
        any = j; anyD = d;
        if (m.recent.includes(j)) continue;
        const s = Math.hypot(nx + 0.5 - g.x, nz + 0.5 - g.z) + Math.random() * 0.8;
        if (s < bs) { bs = s; bj = j; bd = d; }
      }
      if (bj < 0 && any >= 0) { bj = any; bd = anyD; }
      if (bj >= 0) {
        m.recent.push(i);
        if (m.recent.length > 10) m.recent.shift();
        const [dx, dz] = DIRS[bd];
        m.wx = (bj % N) + 0.5 - dz * m.side;
        m.wz = Math.floor(bj / N) + 0.5 + dx * m.side;
        m.hasWp = true;
        return;
      }
    } else {
      let best: Pt | null = null, bs = Infinity;
      for (let dz = -3; dz <= 3; dz++) {
        for (let dx = -3; dx <= 3; dx++) {
          const nx = tx + dx, nz = tz + dz;
          if (nx < 1 || nz < 1 || nx >= N - 1 || nz >= N - 1 || !isNet(w, idx(nx, nz))) continue;
          const p = { x: nx + 0.5, z: nz + 0.5 };
          const toGoal = Math.hypot(p.x - g.x, p.z - g.z);
          const s = Math.hypot(p.x - m.x, p.z - m.z) + toGoal;
          if (toGoal < dist + 2 && s < bs && walkable(w, m.x, m.z, p.x, p.z, climb * 2)) { bs = s; best = p; }
        }
      }
      if (best) { m.wx = best.x; m.wz = best.z; m.hasWp = true; return; }
    }
  }
  if (m.free > 0) m.free--;
  const base = Math.atan2(g.x - m.x, g.z - m.z);
  const reach = Math.min(0.8, Math.max(0.3, dist));
  for (const off of [0, 0.6, -0.6, 1.2, -1.2, 1.9, -1.9, 2.6, -2.6]) {
    const a = base + off + (Math.random() - 0.5) * 0.3;
    const px = m.x + Math.sin(a) * reach, pz = m.z + Math.cos(a) * reach;
    if (walkable(w, m.x, m.z, px, pz, climb, pen)) { m.wx = px; m.wz = pz; m.hasWp = true; return; }
  }
  m.stuck += 6;
}

/** Walk a mover `speed * dt` toward its goal. True once it is there (or has given up trying). */
function travel(w: World, m: Mover, g: Goal, dt: number, speed: number, net: boolean, climb: number, pen?: Uint8Array): boolean {
  let budget = speed * dt;
  m.moving = false;
  for (let guard = 0; guard < 6 && budget > 1e-5; guard++) {
    if (!m.hasWp) {
      if (Math.hypot(g.x - m.x, g.z - m.z) < g.r) return true;
      pickWp(w, m, g, net, climb, pen);
      if (m.gaveUp) { m.gaveUp = false; m.best = Infinity; m.stuck = 0; return true; }
      if (!m.hasWp) return false;
    }
    const dx = m.wx - m.x, dz = m.wz - m.z, d = Math.hypot(dx, dz);
    if (d > 1e-4) m.yaw = turn(m.yaw, Math.atan2(dx, dz), dt * 6);
    m.moving = true;
    if (d <= budget) { m.x = m.wx; m.z = m.wz; budget -= d; m.hasWp = false; } else { m.x += (dx / d) * budget; m.z += (dz / d) * budget; budget = 0; }
  }
  return false;
}

// ---------------------------------------------------------------- the groups

interface Beast {
  x: number; z: number; yaw: number;
  ox: number; oz: number;     // place in the group
  pause: number; phase: number; speed: number;
  look: Look; tint: number;
  flee: number; fx: number; fz: number;
  moving: boolean;
}
const beast = (p: Pt, look: Look, tint = 0xffffff): Beast => ({
  x: p.x, z: p.z, yaw: Math.random() * 6.28, ox: 0, oz: 0, pause: rand(0, 5), phase: Math.random() * 6, speed: rand(0.14, 0.22),
  look, tint, flee: 0, fx: 0, fz: 0, moving: false,
});

interface Flock {
  kind: 'herd' | 'sheep' | 'cattle' | 'goats' | 'horses' | 'rider';
  c: Mover; home: Pt; goal: Goal; rest: number; spread: number; climb: number;
  beasts: Beast[]; goals: Pt[]; fled: boolean; acc: number;
  /** A ranch's herd, or its rider: the pasture tiles it keeps to (world/ranches.ts). */
  pen?: Uint8Array;
}
interface Train {
  kind: 'camels' | 'sledTeam';
  lead: Mover; sets: [Goal[], Goal[]]; side: number; goal: Goal; rest: number;
  trail: Float32Array; head: number; beasts: Beast[]; acc: number;
}
interface Pair {
  kind: 'hikers' | 'pilgrims';
  lead: Mover; from: Goal[]; to: Goal[]; out: boolean; goal: Goal; rest: number; beasts: Beast[]; acc: number;
}
interface Surfer { b: Beast; beach: Pt; state: 'beach' | 'wade' | 'paddle' | 'sit' | 'ride' | 'back'; timer: number; sea: Pt; entry: Pt }
interface Skier { b: Beast; slow: number; t: number }

const TRAIL = 160;
const TRAIL_STEP = 0.025;

const WALKER_COATS = [0xe2412f, 0x2f7fb5, 0xf2c14e, 0x3f9b4a, 0xf28c38, 0x8e5cc7, 0x2bb3a3];
const ROBES = [0xf4f0e6, 0xf4f0e6, 0xe8942c, 0xb0aca4];
const SUITS = [0x1a1a22, 0x223a6a, 0x1a1a22, 0xb03a2a];

export class Herds {
  private parent: THREE.Object3D;
  private w: World | null = null;
  private meshes = new Map<Look, { fixed: THREE.InstancedMesh; coat: THREE.InstancedMesh | null; n: number }>();
  private flocks: Flock[] = [];
  private trains: Train[] = [];
  private pairs: Pair[] = [];
  private surfers: Surfer[] = [];
  private skiers: Skier[] = [];
  private tops: Pt[] = [];
  private icy = false;
  private season = { warm: 0, cold: 0 };
  private player = { x: 0, z: 0, v: 0, set: false };
  private rescanT = 20;
  /** What the island looked like when last scanned, so an empty one is only rescanned after it changes. */
  private sig = '';
  private m = new THREE.Matrix4();
  private col = new THREE.Color();
  private time = 0;
  /** Milliseconds the last update took, for the budget. */
  lastMs = 0;
  budget = 1;

  constructor(parent: THREE.Object3D) { this.parent = parent; }

  setSeason(warm: number, cold: number): void { this.season.warm = warm; this.season.cold = cold; }
  setPlayer(x: number, z: number, speed: number): void { this.player.x = x; this.player.z = z; this.player.v = speed; this.player.set = true; }

  get counts(): Record<string, number> {
    const out: Record<string, number> = {};
    for (const f of this.flocks) out[f.kind] = (out[f.kind] ?? 0) + f.beasts.length;
    for (const t of this.trains) out[t.kind] = (out[t.kind] ?? 0) + t.beasts.length;
    for (const p of this.pairs) out[p.kind] = (out[p.kind] ?? 0) + 2;
    if (this.surfers.length) out.surfers = this.surfers.length;
    if (this.skiers.length) out.skiers = this.skiers.length;
    return out;
  }
  /** Where the groups are, for looking at them from the console. */
  get where(): { kind: string; x: number; z: number }[] {
    return [
      ...this.flocks.map((f) => ({ kind: f.kind, x: +f.c.x.toFixed(1), z: +f.c.z.toFixed(1) })),
      ...this.trains.map((t) => ({ kind: t.kind, x: +t.lead.x.toFixed(1), z: +t.lead.z.toFixed(1) })),
      ...this.pairs.map((p) => ({ kind: p.kind, x: +p.lead.x.toFixed(1), z: +p.lead.z.toFixed(1) })),
      ...this.surfers.map((s) => ({ kind: 'surfer', x: +s.b.x.toFixed(1), z: +s.b.z.toFixed(1) })),
      ...this.skiers.map((s) => ({ kind: 'skier', x: +s.b.x.toFixed(1), z: +s.b.z.toFixed(1) })),
    ];
  }

  dispose(): void {
    this.setWorld(null);
    for (const e of this.meshes.values()) {
      e.fixed.removeFromParent(); e.fixed.dispose();
      if (e.coat) { e.coat.removeFromParent(); e.coat.dispose(); }
    }
    this.meshes.clear();
  }

  setWorld(w: World | null): void {
    this.w = w;
    this.flocks = []; this.trains = []; this.pairs = []; this.surfers = []; this.skiers = []; this.tops = [];
    this.icy = false;
    for (const e of this.meshes.values()) { e.fixed.count = 0; e.fixed.visible = false; if (e.coat) { e.coat.count = 0; e.coat.visible = false; } }
    if (w) {
      this.sig = `${w.revision}:${w.towns.length}:${w.countryside.length}:${w.works.length}:${w.spots.length}:${w.region}`;
      this.spawn(w);
    }
  }

  /** Look again at the island (after the generator or the console has changed what is on it). */
  rescan(): void { this.setWorld(this.w); }

  private mesh(look: Look) {
    let e = this.meshes.get(look);
    if (!e) {
      let g = GEO.get(look);
      if (!g) { g = build(look); GEO.set(look, g); }
      const make = (geo: THREE.BufferGeometry) => {
        const im = new THREE.InstancedMesh(geo, MAT, CAP[look]);
        im.count = 0; im.frustumCulled = false; im.visible = false;
        this.parent.add(im);
        return im;
      };
      const fixed = make(g.fixed);
      const coat = g.coat ? make(g.coat) : null;
      if (coat) for (let k = 0; k < CAP[look]; k++) coat.setColorAt(k, this.col.setHex(0xffffff));
      e = { fixed, coat, n: 0 };
      this.meshes.set(look, e);
    }
    return e;
  }

  // ---------------------------------------------------------------- spawning

  private spawn(w: World): void {
    this.spawnRanches(w);
    const rng = mulberry((w.cx * 73856093) ^ (w.cz * 19349663) ^ 0x5bd1e995);
    const R = (a: number, b: number) => a + rng() * (b - a);
    const Ri = (a: number, b: number) => Math.floor(R(a, b + 1));
    const pickR = <T,>(a: T[]): T => a[Math.floor(rng() * a.length)];

    // what each biome on the cell holds: sampled open land, lake shores, how much of it there is
    interface Scan { land: number[]; seen: number; lakes: Pt[]; lakeTiles: number[] }
    const scans = new Map<RegionKind, Scan>();
    for (let z = 2; z < N - 2; z += 2) {
      for (let x = 2; x < N - 2; x += 2) {
        const i = idx(x, z), k = w.regionK[i];
        if (!k || w.regionW[i] < 150) continue;
        const kind = REGION_KINDS[k - 1];
        let s = scans.get(kind);
        if (!s) { s = { land: [], seen: 0, lakes: [], lakeTiles: [] }; scans.set(kind, s); }
        if (w.water[i] >= 0) {
          if (w.biome[i] !== Biome.Ocean && waterDepth(w, i) > 0 && s.lakeTiles.length < 3000) s.lakeTiles.push(i);
          continue;
        }
        if (w.blocked[i] || w.townId[i] >= 0 || w.feature[i] === Feature.Pasture) continue;
        s.seen++;
        if (s.land.length < 1500) s.land.push(i);
        else { const j = Math.floor(rng() * s.seen); if (j < 1500) s.land[j] = i; }
      }
    }
    for (const s of scans.values()) {
      for (const i of s.lakeTiles) {
        const x = (i % N) + 0.5, z = Math.floor(i / N) + 0.5;
        if (s.lakes.some((p) => Math.hypot(p.x - x, p.z - z) < 10)) continue;
        const shore = nearLand(w, x, z, 6);
        if (shore) s.lakes.push(shore);
        if (s.lakes.length >= 30) break;
      }
    }
    if (!scans.size) return;

    const regionAt = (x: number, z: number): RegionKind | null => {
      const tx = Math.floor(x), tz = Math.floor(z);
      if (!inB(tx, tz)) return null;
      const k = w.regionK[idx(tx, tz)];
      return k ? REGION_KINDS[k - 1] : null;
    };
    const buildings: Building[] = [...w.countryside, ...w.towns.flatMap((t) => t.buildings), ...w.works.flatMap((k) => k.buildings)]
      .filter((b) => !b.gone && w.feature[idx(b.x, b.z)] !== Feature.Pasture);
    const placesOf = (kind: RegionKind, kinds: string[]): Goal[] => buildings
      .filter((b) => kinds.includes(b.kind) && regionAt(b.x + b.w / 2, b.z + b.d / 2) === kind)
      .map((b) => ({ x: b.x + b.w / 2, z: b.z + b.d / 2, r: Math.max(b.w, b.d) / 2 + 1.5 }));
    const townsOf = (kind: RegionKind): Goal[] => w.towns
      .filter((t) => regionAt(t.x0 + t.size / 2, t.z0 + t.size / 2) === kind)
      .map((t) => ({ x: t.x0 + t.size / 2, z: t.z0 + t.size / 2, r: t.size / 2 + 0.5 }));
    const wonders = (kind: RegionKind): Goal[] => w.works
      .filter((k) => k.kind === 'wonder' && regionAt(k.x, k.z) === kind).map((k) => ({ x: k.x, z: k.z, r: 7 }));
    const tilePt = (i: number): Pt => ({ x: (i % N) + 0.2 + rng() * 0.6, z: Math.floor(i / N) + 0.2 + rng() * 0.6 });
    /** Somewhere to stand at a goal: open dry ground near it. */
    const stand = (g: Pt): Pt | null => nearLand(w, g.x + R(-1, 1), g.z + R(-1, 1), 10);

    const done = new Set<HerdKind>();
    for (const [kind, s] of scans) {
      const spec = REGIONS[kind];
      const share = Math.min(1, s.seen / 2500) * this.budget;
      if (s.seen < 150 || share <= 0) continue;
      const n = (lo: number, hi: number) => Math.max(1, Math.round(R(lo, hi) * share));
      for (const hk of spec.herds) {
        if (done.has(hk)) continue;
        done.add(hk);
        switch (hk) {
          case 'camels': {
            const oases = s.lakes.map((p) => ({ ...p, r: 2.5 }));
            const places = [...townsOf(kind), ...placesOf(kind, ['tentCamp', 'caravanserai', 'souk'])];
            if (oases.length + places.length < 2) break;
            const sets: [Goal[], Goal[]] = oases.length && places.length ? [oases, places] : oases.length ? [oases, oases] : [places, places];
            for (let k = n(2, 4); k > 0; k--) this.addTrain(w, 'camels', sets, Ri(3, 5), rng, stand);
            break;
          }
          case 'sledTeam': {
            const places = [...townsOf(kind), ...placesOf(kind, ['researchStation', 'sledKennels'])];
            if (places.length < 2) break;
            for (let k = n(2, 3); k > 0; k--) this.addTrain(w, 'sledTeam', [places, places], 6, rng, stand);
            break;
          }
          case 'herd': {
            const holes = s.lakes.length ? s.lakes : s.land.slice(0, 8).map(tilePt);
            const goals = [...holes, ...holes, ...s.land.slice(0, 6).map(tilePt)];
            const herds = n(3, 6);
            for (let k = 0; k < herds; k++) {
              const look = pickR<Look>(['elephant', 'zebra', 'zebra', 'giraffe']);
              // one herd to a waterhole to start with; the rest out on the plain
              const home = k < holes.length ? stand(holes[k]) : stand(tilePt(pickR(s.land)));
              const size = Ri(8, look === 'elephant' ? 12 : 20);
              if (home) this.addFlock(w, 'herd', home, look, size, 0.4 * Math.sqrt(size), 0.8, goals.length ? goals : holes);
            }
            break;
          }
          case 'horses': {
            // herds of horses loose on the grass, drifting between the lakes and the camps
            const holes = s.lakes.length ? s.lakes : s.land.slice(0, 8).map(tilePt);
            const camps = placesOf(kind, ['yurtCamp', 'horseCorral']);
            const goals = [...holes, ...camps, ...s.land.slice(0, 8).map(tilePt)];
            for (let k = n(4, 7); k > 0; k--) {
              const home = stand(tilePt(pickR(s.land)));
              const size = Ri(6, 14);
              if (home) this.addFlock(w, 'horses', home, 'horse', size, 0.45 * Math.sqrt(size), 0.8, goals);
            }
            break;
          }
          case 'sheep': {
            const heath = s.land.filter((i) => w.biome[i] === Biome.Hills || w.biome[i] === Biome.Plains || w.biome[i] === Biome.Marsh);
            const pool = heath.length > 20 ? heath : s.land;
            for (let k = n(5, 10); k > 0; k--) {
              const home = tilePt(pickR(pool));
              this.addFlock(w, 'sheep', home, 'sheep', Ri(5, 12), 0.8, 0.8, pool.filter((i) => Math.hypot((i % N) - home.x, Math.floor(i / N) - home.z) < 14).slice(0, 12).map(tilePt));
            }
            break;
          }
          case 'cattle': {
            const barns = placesOf(kind, ['barn', 'dairy', 'farmhouse', 'stables']);
            const meadow = s.land.filter((i) => w.biome[i] === Biome.Plains || w.biome[i] === Biome.Farm);
            for (let k = n(3, 6); k > 0; k--) {
              const at = barns.length ? stand({ x: pickR(barns).x + R(-3, 3), z: pickR(barns).z + R(-3, 3) }) : meadow.length ? tilePt(pickR(meadow)) : null;
              if (!at) continue;
              const goals: Pt[] = [];
              for (let g = 0; g < 5; g++) { const p = nearLand(w, at.x + R(-4, 4), at.z + R(-4, 4), 3); if (p) goals.push(p); }
              this.addFlock(w, 'cattle', at, 'cow', Ri(4, 8), 0.6, 0.7, goals);
            }
            break;
          }
          case 'goats': {
            const high = [...s.land].sort((a, b) => heightAt(w, (b % N) + 0.5, Math.floor(b / N) + 0.5) - heightAt(w, (a % N) + 0.5, Math.floor(a / N) + 0.5));
            const crags = high.slice(0, Math.max(10, Math.floor(high.length * 0.25)));
            for (let k = n(4, 8); k > 0; k--) {
              const home = tilePt(pickR(crags));
              this.addFlock(w, 'goats', home, 'goat', 2, 0.18, 1.8, crags.filter((i) => Math.hypot((i % N) - home.x, Math.floor(i / N) - home.z) < 10).slice(0, 10).map(tilePt));
            }
            break;
          }
          case 'hikers': {
            const high = [...s.land].sort((a, b) => heightAt(w, (b % N) + 0.5, Math.floor(b / N) + 0.5) - heightAt(w, (a % N) + 0.5, Math.floor(a / N) + 0.5));
            const huts = placesOf(kind, ['mountainHut', 'bothy', 'cairnField', 'monastery']);
            const to = huts.length ? huts : high.slice(0, 12).map((i) => ({ ...tilePt(i), r: 1.2 }));
            const roads = s.land.filter((i) => isNet(w, i));
            const from = [...townsOf(kind), ...roads.slice(0, 10).map((i) => ({ ...tilePt(i), r: 1 }))];
            if (!to.length || !from.length) break;
            for (let k = n(3, 5); k > 0; k--) this.addPair(w, 'hikers', from, to, rng, stand);
            break;
          }
          case 'pilgrims': {
            const to = [...placesOf(kind, ['shrine', 'temple', 'pagoda', 'hilltopCastle']), ...wonders(kind)];
            const from = townsOf(kind);
            if (!to.length || !from.length) break;
            for (let k = n(3, 6); k > 0; k--) this.addPair(w, 'pilgrims', from, to, rng, stand);
            break;
          }
          case 'surfers': {
            let beaches: Pt[] = w.spots.filter((sp) => sp.kind === 'beach' && regionAt(sp.x, sp.z) === kind);
            if (!beaches.length) beaches = s.land.filter((i) => w.biome[i] === Biome.Beach).slice(0, 8).map(tilePt);
            let left = Math.round(16 * this.budget);
            for (const b of beaches) {
              for (let k = Ri(2, 4); k > 0 && left > 0; k--, left--) {
                const at = nearLand(w, b.x + R(-2, 2), b.z + R(-2, 2), 4);
                if (!at) continue;
                this.surfers.push({ b: beast(at, 'surfStand', pickR(SUITS)), beach: at, state: 'beach', timer: R(0, 20), sea: at, entry: at });
              }
            }
            break;
          }
        }
      }
      // on the Icefield, anyone with skis goes down any long enough slope
      if (kind === 'icefield') {
        this.icy = true;
        for (const i of s.land) {
          if (this.tops.length >= 60) break;
          const x = (i % N) + 0.5, z = Math.floor(i / N) + 0.5, h = heightAt(w, x, z);
          let low = h;
          for (let a = 0; a < 8; a++) low = Math.min(low, heightAt(w, Math.min(N - 1, Math.max(0, x + Math.cos(a * 0.785) * 5)), Math.min(N - 1, Math.max(0, z + Math.sin(a * 0.785) * 5))));
          if (h - low >= 4 * STEP) this.tops.push({ x, z });
        }
        if (this.tops.length) for (let k = Math.round(30 * this.budget * Math.min(1, this.tops.length / 12)); k > 0; k--) {
          const t = pickR(this.tops);
          this.skiers.push({ b: beast(t, 'skier', pickR(WALKER_COATS)), slow: 0, t: R(0, 30) });
        }
      }
    }
  }

  /**
   * Each ranch's herd (world/ranches.ts): cattle or horses in a few groups out on the pasture, drifting between
   * the grass and the troughs under the pump windmills, and a hand or two riding the fence line among them. The
   * pen is the pasture less its roads, so nothing grazes on the tarmac; a road through it can part the herd.
   */
  private spawnRanches(w: World): void {
    if (!w.ranches?.length) return;
    const rng = mulberry((w.cx * 83492791) ^ (w.cz * 2654435761) ^ 0x7a4c11);
    const R = (a: number, b: number) => a + rng() * (b - a);
    for (const r of w.ranches) {
      const pen = penOf(w, r);
      // the pen's pieces, where a road parts it: a group keeps to its own piece's grass and troughs
      const comp = new Int32Array(N * N).fill(-1), size: number[] = [];
      for (const s of r.pasture) {
        if (!pen[s] || comp[s] >= 0) continue;
        const id = size.length, stack = [s];
        comp[s] = id;
        let n = 0;
        while (stack.length) {
          const i = stack.pop()!;
          n++;
          const x = i % N, z = (i - x) / N;
          for (const [dx, dz] of DIRS) {
            const j = idx(x + dx, z + dz);
            if (inB(x + dx, z + dz) && pen[j] && comp[j] < 0) { comp[j] = id; stack.push(j); }
          }
        }
        size.push(n);
      }
      const big = r.pasture.filter((i) => pen[i] && size[comp[i]] >= 60);
      if (!big.length) continue;
      const pt = (i: number): Pt => ({ x: (i % N) + 0.2 + rng() * 0.6, z: Math.floor(i / N) + 0.2 + rng() * 0.6 });
      const goalsIn = (id: number, n: number): Pt[] => {
        const own = big.filter((i) => comp[i] === id);
        const out: Pt[] = [];
        for (let k = 0; k < n; k++) out.push(pt(own[Math.floor(rng() * own.length)]));
        // the troughs, twice over: water draws a herd back again and again
        for (const q of r.water) {
          for (const [dx, dz] of DIRS) {
            const j = idx(Math.floor(q.x) + dx, Math.floor(q.z) + dz);
            if (pen[j] && comp[j] === id) { out.push(pt(j), pt(j)); break; }
          }
        }
        return out;
      };
      const cattle = r.stock === 'cattle';
      const groups = Math.max(1, Math.round(Math.min(cattle ? 5 : 4, Math.max(2, big.length / (cattle ? 300 : 400))) * this.budget));
      for (let g = 0; g < groups; g++) {
        const home = big[Math.floor(rng() * big.length)];
        const n = Math.round(cattle ? R(8, 16) : R(6, 12));
        this.addFlock(w, cattle ? 'cattle' : 'horses', pt(home), cattle ? 'cow' : 'horse', n, 0.7 * Math.sqrt(n), 0.8, goalsIn(comp[home], 10), pen);
      }
      // a hand on horseback, riding the fence line and out to the herd
      const riders = big.length > 1500 ? 2 : 1;
      for (let k = 0; k < riders; k++) {
        const home = big[Math.floor(rng() * big.length)];
        const edge = big.filter((i) => comp[i] === comp[home] && DIRS.some(([dx, dz]) => !pen[i + dx + dz * N]));
        const goals = [...goalsIn(comp[home], 4), ...Array.from({ length: 10 }, () => pt(edge[Math.floor(rng() * edge.length)] ?? home))];
        this.addFlock(w, 'rider', pt(home), 'rider', 1, 0, 0.9, goals, pen);
      }
    }
  }

  /** Every ranch herd's beasts, with whether each stands in its own pen (scripts/ranches.ts). */
  get penned(): { kind: string; x: number; z: number; inside: boolean }[] {
    const out: { kind: string; x: number; z: number; inside: boolean }[] = [];
    for (const f of this.flocks) {
      if (!f.pen) continue;
      for (const b of f.beasts) out.push({ kind: f.kind, x: b.x, z: b.z, inside: !!f.pen[idx(Math.floor(b.x), Math.floor(b.z))] });
    }
    return out;
  }

  /** Step the herds without drawing: for a gate script under node. */
  simulate(dt: number, hour = 12): void {
    const w = this.w;
    if (!w) return;
    const night = hour < 6.5 || hour > 20.5;
    for (const f of this.flocks) if (!(f.kind === 'rider' && night)) this.flock(w, f, dt);
  }

  private addFlock(w: World, kind: Flock['kind'], home: Pt, look: Look, count: number, spread: number, climb: number, goals: Pt[], pen?: Uint8Array): void {
    const cap = CAP[look] - this.flocks.reduce((s, f) => s + f.beasts.filter((b) => b.look === look).length, 0);
    count = Math.min(count, cap);
    if (count < (kind === 'rider' ? 1 : kind === 'goats' ? 2 : 3)) return;
    const beasts: Beast[] = [];
    for (let k = 0; k < count; k++) {
      const a = Math.random() * 6.28, r = Math.sqrt(Math.random()) * spread;
      const p = { x: home.x + Math.cos(a) * r, z: home.z + Math.sin(a) * r };
      const b = beast(walkable(w, home.x, home.z, p.x, p.z, 99, pen) ? p : home, look);
      b.ox = p.x - home.x; b.oz = p.z - home.z;
      if (look === 'cow') b.tint = Math.random() < 0.5 ? 0xffffff : Math.random() < 0.6 ? 0x9a6038 : 0x6a4028;
      if (look === 'goat') b.tint = [0xf0ece2, 0xc8a878, 0x6a5a4a, 0xf0ece2][Math.floor(Math.random() * 4)];
      if (look === 'horse' || look === 'rider') b.tint = [0x7a4a28, 0x5a3420, 0xb08a58, 0x2e2622, 0xd8cfc0, 0x8a5a34][Math.floor(Math.random() * 6)];
      if (look === 'sheep' || look === 'goat') b.speed *= 0.7;
      beasts.push(b);
    }
    this.flocks.push({ kind, c: mover(home), home, goal: { ...home, r: 1 }, rest: rand(5, 40), spread, climb, beasts, goals: goals.length ? goals : [home], fled: false, acc: 0, pen });
  }

  private addTrain(w: World, kind: Train['kind'], sets: [Goal[], Goal[]], count: number, rng: () => number, stand: (p: Pt) => Pt | null): void {
    const side = rng() < 0.5 ? 0 : 1;
    const start = sets[side][Math.floor(rng() * sets[side].length)];
    const at = stand(start);
    if (!at) return;
    const look: Look = kind === 'camels' ? 'camel' : 'dog';
    const used = this.trains.reduce((s, t) => s + t.beasts.filter((b) => b.look === look).length, 0);
    if (used + count > CAP[look]) return;
    const beasts: Beast[] = [];
    for (let k = 0; k < count; k++) beasts.push(beast(at, look, kind === 'sledTeam' ? [0x3a3a40, 0xd8d4cc, 0x6a6a70, 0x2a2a2e][k % 4] : 0xffffff));
    if (kind === 'sledTeam') beasts.push(beast(at, 'sled'));
    const trail = new Float32Array(TRAIL * 2);
    for (let k = 0; k < TRAIL; k++) { trail[k * 2] = at.x; trail[k * 2 + 1] = at.z; }
    const t: Train = { kind, lead: mover(at), sets, side, goal: { ...start }, rest: rand(0, 20), trail, head: 0, beasts, acc: 0 };
    t.lead.side = kind === 'camels' ? 0.3 : 0.15;
    void w;
    this.trains.push(t);
  }

  private addPair(w: World, kind: Pair['kind'], from: Goal[], to: Goal[], rng: () => number, stand: (p: Pt) => Pt | null): void {
    const at = stand(from[Math.floor(rng() * from.length)]);
    if (!at) return;
    const look: Look = kind === 'hikers' ? 'hiker' : 'pilgrim';
    if (this.pairs.filter((p) => p.kind === kind).length * 2 + 2 > CAP[look]) return;
    const tints = kind === 'hikers' ? WALKER_COATS : ROBES;
    const beasts = [beast(at, look, tints[Math.floor(rng() * tints.length)]), beast(at, look, tints[Math.floor(rng() * tints.length)])];
    const goal = to[Math.floor(rng() * to.length)];
    void w;
    this.pairs.push({ kind, lead: mover(at), from, to, out: true, goal, rest: rand(0, 30), beasts, acc: 0 });
  }

  // ---------------------------------------------------------------- simulation

  update(dt: number, hour: number): void {
    const w = this.w;
    if (!w || dt <= 0) return;
    const t0 = performance.now();
    this.time += dt;
    if (!this.flocks.length && !this.trains.length && !this.pairs.length && !this.surfers.length && !this.skiers.length) {
      // nothing here yet: the generator may still be filling the island in
      this.rescanT -= dt;
      const sig = `${w.revision}:${w.towns.length}:${w.countryside.length}:${w.works.length}:${w.spots.length}:${w.region}`;
      if (this.rescanT <= 0 && sig !== this.sig) { this.rescanT = 30; this.sig = sig; this.spawn(w); }
    }
    for (const e of this.meshes.values()) e.n = 0;
    const night = hour < 6.5 || hour > 20.5;

    for (const f of this.flocks) {
      // the hands ride out by day
      if (f.kind === 'rider' && night) continue;
      const step = this.slowed(f, f.c.x, f.c.z, dt);
      if (step > 0) this.flock(w, f, step);
      for (const b of f.beasts) this.put(w, b, b.moving ? 0.01 : 0);
    }
    for (const t of this.trains) {
      const step = this.slowed(t, t.lead.x, t.lead.z, dt);
      if (step > 0) this.train(w, t, step);
      this.drawTrain(w, t);
    }
    for (const p of this.pairs) {
      if (night) continue;
      const step = this.slowed(p, p.lead.x, p.lead.z, dt);
      if (step > 0) this.pair(w, p, step);
      for (const b of p.beasts) this.put(w, b, p.lead.moving ? 0.008 : 0);
    }
    if (hour >= 7 && hour < 19.5) for (const s of this.surfers) this.surf(w, s, dt);
    if (this.icy && this.skiers.length) {
      const day = Math.max(0, Math.min(1, (hour - 8.5) / 1.5)) * Math.max(0, Math.min(1, (17.5 - hour) / 1.5));
      const want = Math.round(this.skiers.length * Math.max(this.season.cold, 0.5) * day);
      for (let k = 0; k < want; k++) this.ski(w, this.skiers[k], dt);
    }

    for (const e of this.meshes.values()) {
      e.fixed.count = e.n; e.fixed.visible = e.n > 0;
      if (e.n) e.fixed.instanceMatrix.needsUpdate = true;
      if (e.coat) {
        e.coat.count = e.n; e.coat.visible = e.n > 0;
        if (e.n) { e.coat.instanceMatrix.needsUpdate = true; e.coat.instanceColor!.needsUpdate = true; }
      }
    }
    this.lastMs = performance.now() - t0;
  }

  /** Far from the player, a group only moves a few times a second. Returns the dt to step by, or 0. */
  private slowed(g: { acc: number }, x: number, z: number, dt: number): number {
    const p = this.player;
    if (!p.set || Math.hypot(p.x - x, p.z - z) < 60) { g.acc = 0; return dt; }
    g.acc += dt;
    if (g.acc < 0.3) return 0;
    const s = g.acc; g.acc = 0;
    return s;
  }

  private flock(w: World, f: Flock, dt: number): void {
    const speed = f.kind === 'herd' ? 0.14 : f.kind === 'horses' ? 0.2 : f.kind === 'rider' ? 0.3 : f.kind === 'cattle' ? 0.06 : 0.08;
    if (f.rest > 0) {
      f.rest -= dt;
      if (f.rest <= 0) {
        const g = f.goals[Math.floor(Math.random() * f.goals.length)];
        f.goal = { x: g.x, z: g.z, r: f.kind === 'herd' || f.kind === 'horses' ? 2.5 : 1 };
        f.c.best = Infinity; f.c.stuck = 0;
      }
    } else if (travel(w, f.c, f.goal, dt, speed, false, f.climb, f.pen)) {
      f.rest = f.kind === 'rider' ? rand(6, 20) : rand(25, 80);
    }
    const p = this.player;
    const fleeR = f.kind === 'rider' ? 0 : f.kind === 'herd' || f.kind === 'horses' ? 2.6 : f.kind === 'sheep' ? 1.9 : f.kind === 'goats' ? 1.6 : 1.2;
    let fleeing = 0;
    for (const b of f.beasts) {
      const pd = p.set ? Math.hypot(b.x - p.x, b.z - p.z) : Infinity;
      if (pd < fleeR && (p.v > 0.15 || pd < fleeR * 0.45)) {
        const a = Math.atan2(b.x - p.x, b.z - p.z) + (Math.random() - 0.5) * 0.8;
        b.fx = Math.sin(a); b.fz = Math.cos(a); b.flee = rand(1.4, 2.4);
      }
      if (b.flee > 0) {
        fleeing++;
        b.flee -= dt;
        const run = b.speed * (f.kind === 'cattle' ? 2.5 : 4.5) * dt;
        const px = b.x + b.fx * Math.max(run, 0.12), pz = b.z + b.fz * Math.max(run, 0.12);
        if (walkable(w, b.x, b.z, px, pz, f.climb, f.pen)) {
          b.x += b.fx * run; b.z += b.fz * run;
          penned(f, b, b.x - b.fx * run, b.z - b.fz * run);
        } else {
          const a = Math.atan2(b.fx, b.fz) + (Math.random() < 0.5 ? 1.57 : -1.57);
          b.fx = Math.sin(a); b.fz = Math.cos(a);
        }
        b.yaw = turn(b.yaw, Math.atan2(b.fx, b.fz), dt * 8);
        b.moving = true;
        b.phase += dt * 22;
        continue;
      }
      b.pause -= dt;
      if (b.pause > 0) { b.moving = false; continue; }
      const tx = f.c.x + b.ox, tz = f.c.z + b.oz;
      const dx = tx - b.x, dz = tz - b.z, d = Math.hypot(dx, dz);
      if (d < 0.06) {
        b.pause = rand(2, 10);
        const a = Math.random() * 6.28, r = Math.sqrt(Math.random()) * f.spread;
        b.ox = Math.cos(a) * r; b.oz = Math.sin(a) * r;
        b.moving = false;
        continue;
      }
      const run = Math.min(d, b.speed * (d > f.spread * 2 ? 2.2 : 1) * dt);
      const ux = dx / d, uz = dz / d;
      if (walkable(w, b.x, b.z, b.x + ux * 0.2, b.z + uz * 0.2, f.climb, f.pen)) {
        b.x += ux * run; b.z += uz * run;
        penned(f, b, b.x - ux * run, b.z - uz * run);
        b.yaw = turn(b.yaw, Math.atan2(ux, uz), dt * 4);
        b.moving = true;
        b.phase += dt * 12;
      } else {
        const a = Math.random() * 6.28, r = Math.sqrt(Math.random()) * f.spread;
        b.ox = Math.cos(a) * r; b.oz = Math.sin(a) * r;
        b.pause = rand(0.5, 2);
        b.moving = false;
      }
    }
    if (fleeing) f.fled = true;
    else if (f.fled) {
      // the scare is over: the group gathers where it ran to
      f.fled = false;
      let sx = 0, sz = 0;
      for (const b of f.beasts) { sx += b.x; sz += b.z; }
      const cx = sx / f.beasts.length, cz = sz / f.beasts.length;
      // (a ranch's herd gathers on its own grass: round the beast nearest the middle, which is on it)
      const at = f.pen
        ? f.beasts.reduce((a, b) => Math.hypot(b.x - cx, b.z - cz) < Math.hypot(a.x - cx, a.z - cz) ? b : a, f.beasts[0])
        : nearLand(w, cx, cz, 3) ?? { x: f.c.x, z: f.c.z };
      f.c.x = at.x; f.c.z = at.z; f.c.hasWp = false;
      for (const b of f.beasts) { b.ox = b.x - cx; b.oz = b.z - cz; b.pause = rand(1, 5); }
    }
  }

  private train(w: World, t: Train, dt: number): void {
    const l = t.lead;
    if (t.rest > 0) {
      t.rest -= dt;
      l.moving = false;
      if (t.rest <= 0) {
        t.side = 1 - t.side;
        const set = t.sets[t.side];
        let g = set[Math.floor(Math.random() * set.length)];
        for (let k = 0; k < 4 && Math.hypot(g.x - l.x, g.z - l.z) < g.r + 3; k++) g = set[Math.floor(Math.random() * set.length)];
        t.goal = g;
        l.best = Infinity; l.stuck = 0; l.free = 0;
      }
    } else {
      const speed = t.kind === 'camels' ? 0.22 : 0.55;
      if (travel(w, l, t.goal, dt, speed, true, 0.9)) t.rest = t.kind === 'camels' ? rand(20, 60) : rand(10, 30);
    }
    const hx = t.trail[t.head * 2], hz = t.trail[t.head * 2 + 1];
    const moved = Math.hypot(l.x - hx, l.z - hz);
    if (moved >= TRAIL_STEP) {
      const steps = Math.min(8, Math.floor(moved / TRAIL_STEP));
      for (let s = 1; s <= steps; s++) {
        t.head = (t.head + 1) % TRAIL;
        const k = s / steps;
        t.trail[t.head * 2] = hx + (l.x - hx) * k;
        t.trail[t.head * 2 + 1] = hz + (l.z - hz) * k;
      }
    }
    for (const b of t.beasts) b.phase += dt * (l.moving ? (t.kind === 'camels' ? 9 : 26) : 0);
  }

  private trailAt(t: Train, back: number): [number, number, number] {
    const n = Math.min(TRAIL - 3, Math.round(back / TRAIL_STEP));
    const a = (t.head - n + TRAIL * 2) % TRAIL, b = (a + 2) % TRAIL;
    const x = t.trail[a * 2], z = t.trail[a * 2 + 1];
    const dx = t.trail[b * 2] - x, dz = t.trail[b * 2 + 1] - z;
    return [x, z, Math.hypot(dx, dz) > 1e-4 ? Math.atan2(dx, dz) : NaN];
  }

  private drawTrain(w: World, t: Train): void {
    const moving = t.lead.moving;
    if (t.kind === 'camels') {
      t.beasts.forEach((b, k) => {
        const [x, z, yaw] = k === 0 ? [t.lead.x, t.lead.z, t.lead.yaw] : this.trailAt(t, k * 0.24);
        b.x = x; b.z = z;
        if (!Number.isNaN(yaw)) b.yaw = yaw;
        this.put(w, b, moving ? 0.008 : 0);
      });
      return;
    }
    // six dogs in pairs ahead of the sled
    const dogs = t.beasts.length - 1;
    for (let k = 0; k < dogs; k++) {
      const row = Math.floor(k / 2), b = t.beasts[k];
      const [x, z, yaw] = row === 0 ? [t.lead.x, t.lead.z, t.lead.yaw] : this.trailAt(t, row * 0.075);
      if (!Number.isNaN(yaw)) b.yaw = yaw;
      const side = k % 2 ? 0.022 : -0.022;
      b.x = x + Math.cos(b.yaw) * side; b.z = z - Math.sin(b.yaw) * side;
      this.put(w, b, moving ? 0.01 : 0);
    }
    const sled = t.beasts[dogs];
    const [x, z, yaw] = this.trailAt(t, Math.ceil(dogs / 2) * 0.075 + 0.07);
    sled.x = x; sled.z = z;
    if (!Number.isNaN(yaw)) sled.yaw = yaw;
    this.put(w, sled, 0);
  }

  private pair(w: World, p: Pair, dt: number): void {
    const l = p.lead;
    if (p.rest > 0) {
      p.rest -= dt;
      l.moving = false;
      if (p.rest <= 0) {
        p.out = !p.out;
        const set = p.out ? p.to : p.from;
        p.goal = set[Math.floor(Math.random() * set.length)];
        l.best = Infinity; l.stuck = 0; l.free = 0;
      }
    } else if (travel(w, l, p.goal, dt, p.kind === 'hikers' ? 0.3 : 0.24, true, 1.1)) {
      p.rest = rand(20, 50);
    }
    const [a, b] = p.beasts;
    const side = 0.045;
    a.x = l.x + Math.cos(l.yaw) * side; a.z = l.z - Math.sin(l.yaw) * side; a.yaw = l.yaw;
    const bx = l.x - Math.cos(l.yaw) * side - Math.sin(l.yaw) * 0.02, bz = l.z + Math.sin(l.yaw) * side - Math.cos(l.yaw) * 0.02;
    b.x += (bx - b.x) * Math.min(1, dt * 10); b.z += (bz - b.z) * Math.min(1, dt * 10); b.yaw = l.yaw;
    if (l.moving) { a.phase += dt * 10; b.phase = a.phase + 1.6; }
  }

  private surf(w: World, s: Surfer, dt: number): void {
    const b = s.b;
    const go = (to: Pt, speed: number): boolean => {
      const dx = to.x - b.x, dz = to.z - b.z, d = Math.hypot(dx, dz);
      if (d < 0.05) return true;
      const run = Math.min(d, speed * dt);
      b.x += (dx / d) * run; b.z += (dz / d) * run;
      b.yaw = turn(b.yaw, Math.atan2(dx, dz), dt * 5);
      b.phase += dt * 9;
      return false;
    };
    s.timer -= dt;
    switch (s.state) {
      case 'beach':
        b.look = 'surfStand';
        if (s.timer <= 0) {
          const out = this.seaFrom(w, s.beach);
          if (out) { s.sea = out.sea; s.entry = out.entry; s.state = 'wade'; } else s.timer = rand(10, 30);
        }
        break;
      case 'wade': if (go(s.entry, 0.3)) s.state = 'paddle'; break;
      case 'paddle': b.look = 'surfLie'; if (go(s.sea, 0.16)) { s.state = 'sit'; s.timer = rand(4, 14); } break;
      case 'sit': b.look = 'surfLie'; b.yaw = turn(b.yaw, Math.atan2(s.entry.x - b.x, s.entry.z - b.z), dt * 2); if (s.timer <= 0) s.state = 'ride'; break;
      case 'ride': b.look = 'surfStand'; if (go(s.entry, 0.85)) s.state = 'back'; break;
      case 'back': b.look = 'surfStand'; if (go(s.beach, 0.3)) { s.state = 'beach'; s.timer = rand(8, 30); } break;
    }
    const tx = Math.min(N - 1, Math.max(0, Math.floor(b.x))), tz = Math.min(N - 1, Math.max(0, Math.floor(b.z)));
    const i = idx(tx, tz);
    const ground = heightAt(w, b.x, b.z);
    const wet = w.water[i] >= 0 && waterDepth(w, i) > 0;
    const surface = wet ? Math.max(ground, w.water[i] * STEP) : ground;
    const bob = wet ? Math.sin(this.time * 2 + b.phase) * 0.012 + (s.state === 'ride' ? 0.02 : 0) : 0;
    this.putAt(b, b.x, surface + bob, b.z, 0);
  }

  /** A spot a few tiles out on the water from a beach, and where the water starts on the way there. */
  private seaFrom(w: World, beach: Pt): { sea: Pt; entry: Pt } | null {
    for (let k = 0; k < 16; k++) {
      const a = Math.random() * 6.28;
      let entry: Pt | null = null;
      for (let r = 0.5; r < 12; r += 0.5) {
        const x = beach.x + Math.sin(a) * r, z = beach.z + Math.cos(a) * r;
        const tx = Math.floor(x), tz = Math.floor(z);
        if (!inB(tx, tz)) break;
        const i = idx(tx, tz);
        const d = w.water[i] >= 0 ? waterDepth(w, i) : 0;
        if (!entry) {
          if (d > 0) entry = { x, z };
          else if (w.blocked[i]) break;
          continue;
        }
        if (d <= 0) break;
        if (Math.hypot(x - entry.x, z - entry.z) >= rand(2.5, 5)) return { sea: { x, z }, entry };
      }
    }
    return null;
  }

  private ski(w: World, s: Skier, dt: number): void {
    const b = s.b;
    s.t += dt;
    const e = 0.25;
    const cx = Math.min(N - 1.3, Math.max(1.3, b.x)), cz = Math.min(N - 1.3, Math.max(1.3, b.z));
    const gx = (heightAt(w, cx + e, cz) - heightAt(w, cx - e, cz)) / (2 * e);
    const gz = (heightAt(w, cx, cz + e) - heightAt(w, cx, cz - e)) / (2 * e);
    const slope = Math.hypot(gx, gz);
    s.slow = slope < 0.12 ? s.slow + dt : 0;
    let respawn = s.slow > 1.2 || s.t > 45;
    if (!respawn && slope > 1e-3) {
      const a = Math.atan2(-gx, -gz) + Math.sin(s.t * 1.4 + b.phase) * 0.75;
      const speed = Math.min(1.1, 0.2 + slope * 0.9);
      const px = b.x + Math.sin(a) * speed * dt, pz = b.z + Math.cos(a) * speed * dt;
      const tx = Math.floor(px), tz = Math.floor(pz);
      if (tx < 1 || tz < 1 || tx >= N - 1 || tz >= N - 1 || !dryTile(w, idx(tx, tz))) respawn = true;
      else { b.x = px; b.z = pz; b.yaw = turn(b.yaw, a, dt * 6); }
    }
    if (respawn) {
      const t = this.tops[Math.floor(Math.random() * this.tops.length)];
      b.x = t.x + rand(-0.4, 0.4); b.z = t.z + rand(-0.4, 0.4);
      s.t = 0; s.slow = 0;
      return;
    }
    this.put(w, b, 0);
  }

  // ---------------------------------------------------------------- drawing

  private put(w: World, b: Beast, bob: number): void {
    const x = Math.min(N - 0.001, Math.max(0, b.x)), z = Math.min(N - 0.001, Math.max(0, b.z));
    this.putAt(b, b.x, heightAt(w, x, z), b.z, bob);
  }

  private putAt(b: Beast, x: number, y: number, z: number, bob: number): void {
    const e = this.mesh(b.look);
    if (e.n >= CAP[b.look]) return;
    const m = this.m.makeRotationY(b.yaw);
    m.setPosition(x, y + (bob ? Math.abs(Math.sin(b.phase)) * bob : 0), z);
    e.fixed.setMatrixAt(e.n, m);
    if (e.coat) {
      e.coat.setMatrixAt(e.n, m);
      e.coat.setColorAt(e.n, this.col.setHex(b.tint));
    }
    e.n++;
  }
}
