import { SEASONS, YEAR_H, DAY_H, type Article, type Boxes, type Issue } from './types';

/**
 * The front page as HTML (docs/newspaper.html, Layouts). Four layouts:
 *
 *   A  the broadsheet: the headline across the page, its body beside its picture, the minors in three columns
 *   B  the tabloid, for a year with a still of the moment: the photo across the page under the masthead with
 *      the headline over its foot, the story in three columns, the minors four across under it
 *   C  the classic: the picture left, the headline and story right, the minors four across
 *   D  the quiet year: two columns, no picture
 *
 * The standing boxes (Sport, Weather, the Ledger, Heard at the Inn) and the briefs sit in a strip across the foot
 * of the page, in every layout. Strings only, so the gate renders every issue it prints; the window
 * (paperWindow.ts) puts the string on the page and the stylesheet in index.html dresses it.
 */

const esc = (s: string): string => s.replace(/[&<>"]/g, (c) => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;' }[c]!));

/** The date line: "Year 3 · Spring · Day 9". */
export function dateLine(t: number): string {
  const day = Math.floor(t / DAY_H);
  const s = SEASONS[day % 4];
  return `Year ${Math.floor(t / YEAR_H) + 1} · ${s[0].toUpperCase()}${s.slice(1)} · Day ${day + 1}`;
}

/** What the year in review is called: "Year 2 in review", or "Years 1 and 2" when one issue covers two. */
export function reviewLine(i: Issue): string {
  return i.from < i.year ? `Years ${i.from}${i.year - i.from > 1 ? '–' : ' and '}${i.year} in review` : `Year ${i.year} in review`;
}

/** An article's picture source: its still of the moment, else what the plinth draws (`pic`), else none. */
const srcOf = (a: Article, pic: (a: Article) => string | null): string | null => (a.photo ? `data:image/jpeg;base64,${a.photo}` : pic(a));

/** A picture's markup: the still or the plinth, else the subject's name as a wordmark block. */
function picture(a: Article, src: string | null, cls: string, caption = true): string {
  const inner = src ? `<img alt="" src="${esc(src)}">` : `<div class="pp-mark"><span>${esc(a.mark)}</span></div>`;
  return `<figure class="${cls}"><div class="pp-photo${a.photo ? ' still' : ''}">${inner}</div>${caption && a.cap ? `<figcaption>${esc(a.cap)}</figcaption>` : ''}</figure>`;
}

function paras(a: Article, dropCap: boolean): string {
  return a.body.map((p, i) => `<p${dropCap && i === 0 ? ' class="pp-drop"' : ''}>${esc(p)}</p>`).join('');
}

const cont = (a: Article) => `<p class="pp-cont">… continued on page ${a.page}</p>`;
const byline = (a: Article) => `<p class="pp-by">By ${esc(a.by)}</p>`;

function minor(a: Article): string {
  return `<article class="pp-minor"><h3>${esc(a.head)}</h3>${byline(a)}${paras(a, false)}${cont(a)}</article>`;
}

const list = (items: string[]) => `<ul>${items.map((b) => `<li>${esc(b)}</li>`).join('')}</ul>`;

/** The standing boxes and the briefs, each only when there is something in it. */
function boxesHtml(b: Boxes | undefined, briefs: string[]): string {
  const out: string[] = [];
  if (briefs.length) out.push(`<section class="pp-box pp-briefs"><h4>In brief</h4>${list(briefs)}</section>`);
  if (b?.sport) {
    const s = b.sport;
    out.push(`<section class="pp-box pp-sport"><h4>Sport · ${esc(s.league)}</h4><p class="pp-sub">Season ${s.season}, final table</p>`
      + `<table>${s.rows.map((r, i) => `<tr><td>${i + 1}. ${esc(r.name)}</td><td>${esc(r.rec)} · ${r.pts}</td></tr>`).join('')}</table>`
      + `${s.home ? `<p class="pp-sub">${esc(s.home)}</p>` : ''}</section>`);
  }
  if (b?.weather) {
    const w = b.weather;
    out.push(`<section class="pp-box pp-wx"><h4>Weather</h4><table>${w.rows.map(([k, h]) => `<tr><td>${esc(k)}</td><td>${h} h</td></tr>`).join('')}</table>`
      + `${w.worst ? `<p class="pp-sub">Worst of it: ${esc(w.worst)}</p>` : ''}</section>`);
  }
  if (b?.ledger) {
    const l = b.ledger;
    out.push(`<section class="pp-box pp-ledger"><h4>The Ledger · ${esc(l.fleet)}</h4><p class="pp-sub">Last edition → this</p>`
      + `<table>${l.rows.map(([k, was, now]) => `<tr><td>${esc(k)}</td><td>${esc(was)} → ${esc(now)}</td></tr>`).join('')}</table>`
      + `${l.rival ? `<p class="pp-sub">${esc(l.rival)}</p>` : ''}</section>`);
  }
  if (b?.inn?.length) out.push(`<section class="pp-box pp-inn"><h4>Heard at the Inn</h4>${list(b.inn)}</section>`);
  if (b?.world?.length) out.push(`<section class="pp-box pp-world"><h4>The World This Week</h4><p class="pp-sub">Every fleet on the roads, together</p>${list(b.world)}</section>`);
  if (b?.afield?.length) out.push(`<section class="pp-box pp-afield"><h4>From Further Afield</h4><p class="pp-sub">The year’s news beyond the county</p>${list(b.afield)}</section>`);
  if (b?.circle?.length) out.push(`<section class="pp-box pp-circle"><h4>The Neighbours’ Year</h4><p class="pp-sub">The fleets dealt with most</p>${list(b.circle)}</section>`);
  if (b?.honours?.length) out.push(`<section class="pp-box pp-honours"><h4>Honours</h4><p class="pp-sub">Last week’s titles</p>${list(b.honours)}</section>`);
  if (b?.ago) out.push(`<section class="pp-box pp-ago"><h4>A Year Ago in These Pages</h4><p class="pp-sub">Year ${b.ago.year}</p><p class="pp-ago-head">${esc(b.ago.head)}</p></section>`);
  return out.join('');
}

function masthead(i: Issue): string {
  const p = i.paper;
  return `<header class="pp-mast">
    <div class="pp-ears"><span>${esc(i.ear)}</span><span>Est. Year ${i.est} · ${i.price}¢</span></div>
    <h1 class="pp-name face-${p.face}">${esc(p.name)}</h1>
    <div class="pp-dateline"><span>${dateLine(i.t)}</span><span>${esc(p.slogan)}</span><span>Issue No. ${i.n}</span></div>
    <div class="pp-rule2"></div>
    <div class="pp-review">${reviewLine(i)}</div>
  </header>`;
}

/** The paper's second page, the year in pictures: its stills of the moment, a line and a date under each. */
export function renderGallery(i: Issue): string {
  const g = i.gallery ?? [];
  return `<div class="pp-paper pp-G">
    <header class="pp-mast pp-mast2"><div class="pp-dateline"><span>${esc(i.paper.name)}</span><span>${dateLine(i.t)}</span><span>Page 2</span></div><div class="pp-rule2"></div></header>
    <h2 class="pp-head pp-gtitle">The year in pictures</h2>
    <div class="pp-gallery n${g.length}">${g.map((p) => `<figure class="pp-fig"><div class="pp-photo still"><img alt="" src="data:image/jpeg;base64,${esc(p.photo)}"></div><figcaption><b>${esc(p.when)}.</b> ${esc(p.cap)}</figcaption></figure>`).join('')}</div>
    <footer class="pp-foot"><span>${esc(i.paper.name)} · pictures by the Press’s own photographers</span><span>${esc(reviewLine(i))}</span></footer></div>`;
}

/** The whole front page. `pic` gives a picture's source for an article (the plinth), or null for the wordmark. */
export function renderIssue(i: Issue, pic: (a: Article) => string | null = () => null): string {
  const l = i.lead;
  const foot = `<footer class="pp-foot"><span>${esc(i.paper.name)} · printed for the Press${i.paper.key ? ` at ${esc(i.paper.city)}` : ''} · ${esc(i.paper.staff[0])}, editor</span><span>${esc(reviewLine(i))}</span></footer>`;
  const boxes = boxesHtml(i.boxes, i.briefs);
  const strip = boxes ? `<div class="pp-rule2"></div><div class="pp-strip">${boxes}</div>` : '';
  const story = `${byline(l)}${paras(l, true)}${cont(l)}`;
  switch (i.layout) {
    case 'D':
      return `<div class="pp-paper pp-D">${masthead(i)}
        <h2 class="pp-head">${esc(l.head)}</h2>
        <div class="pp-two"><div>${story}</div><div>${i.minors.map(minor).join('')}</div></div>${strip}${foot}</div>`;
    case 'B':
      return `<div class="pp-paper pp-B">${masthead(i)}
        <div class="pp-splash">${picture(l, srcOf(l, pic), 'pp-fig', false)}<h2 class="pp-head">${esc(l.head)}</h2></div>
        ${l.cap ? `<p class="pp-splashcap">${esc(l.cap)}</p>` : ''}
        <div class="pp-story">${story}</div>
        <div class="pp-rule2"></div>
        <div class="pp-four">${i.minors.map(minor).join('')}</div>${strip}${foot}</div>`;
    case 'C':
      return `<div class="pp-paper pp-C">${masthead(i)}
        <div class="pp-lead pp-leadC">${picture(l, srcOf(l, pic), 'pp-fig')}<div><h2 class="pp-head">${esc(l.head)}</h2>${story}</div></div>
        <div class="pp-rule2"></div>
        <div class="pp-four">${i.minors.map(minor).join('')}</div>${strip}${foot}</div>`;
    default: {
      // A: three columns under the lead; the minors fill them left to right
      const cols: string[][] = [[], [], []];
      i.minors.forEach((m, k) => cols[k % 3].push(minor(m)));
      return `<div class="pp-paper pp-A">${masthead(i)}
        <h2 class="pp-head">${esc(l.head)}</h2>
        <div class="pp-lead"><div>${story}</div>${picture(l, srcOf(l, pic), 'pp-fig')}</div>
        <div class="pp-rule2"></div>
        <div class="pp-cols">${cols.map((c) => `<div>${c.join('')}</div>`).join('')}</div>${strip}${foot}</div>`;
    }
  }
}
