import type { Pid } from './protocol';

/**
 * Rush boards (docs/rushes.html, phase 3), as the game and the server share them. A board is a rush (its key,
 * `<kind>:<cx>.<cz>:<A's tile>`) in one game year (game hours ÷ RUSH_YEAR_HOURS): the same span as the wait before
 * a player may run it again, so each fleet gets about one go a board. Two columns: Solo (one vehicle, nobody
 * following or on Work with it) and Fleet (anything goes); a Solo run counts in both. Best only, by units.
 * Whoever tops a Fleet board holds it, and is paid ◆ RUSH_HELD_PER_DAY a game day while they do.
 */

/** A game year in game hours (render/season.ts DAYS_PER_YEAR 4). */
export const RUSH_YEAR_HOURS = 96;
export const RUSH_HELD_PER_DAY = 1;
/** Rows a board sends, boards a 'rushBoards' may ask for. */
export const RUSH_TOP = 8;
export const RUSH_ASK_MAX = 40;
/** The countdown before a run's clock, seconds, as the game holds it. */
export const RUSH_COUNT = 3;

export interface RushRow {
  by: Pid; name: string;
  /** Units delivered. */
  s: number;
  at: number;
  /** The vehicle driven, and how many vehicles took part in all. */
  m: string; v: number;
  brand?: { primary: number; accent: number; logo: string };
  place?: number;
}

export interface RushBoard {
  /** `<year>:<rush key>`. */
  id: string;
  key: string; year: number;
  name: string; kind: string;
  solo: RushRow[]; fleet: RushRow[];
  nSolo: number; nFleet: number;
  you: { solo: RushRow | null; fleet: RushRow | null };
  holder: Pid | null;
}

/** A rush's key, as the game makes it (game/rushes/sites.ts). */
export const RUSH_KEY = /^[a-z]+(-long)?:-?\d{1,5}\.-?\d{1,5}:\d{1,6}$/;

export const yearOf = (hours: number): number => Math.floor(hours / RUSH_YEAR_HOURS);
