/** A suspension span costs this much again on top of an ordinary deck: towers, cables and all. */
export const SUSPENSION_MULT = 3;
/** What a CPU vehicle pays the player to cross one of their toll bridges. */
export const TOLL = 3;
/** A tile of bridge deck costs this much more than the road it carries. */
const BRIDGE_MULT = 4;

/**
 * What a stretch of road costs: every tile, with its deck tiles charged extra, and the deck of a
 * suspension span charged extra again.
 */
/** What the Brotherhood makes of the player (docs/factions.html): a road costs this many times its price. */
export const ROAD_MUL = { v: 1 };

export function roadCost(type: RoadType, tiles: number, deck = 0, bigDeck = 0): number {
  const per = (ROAD_PRICE[type] ?? 0) * ROAD_MUL.v;
  return Math.round(per * tiles + per * (BRIDGE_MULT - 1) * deck + per * BRIDGE_MULT * (SUSPENSION_MULT - 1) * bigDeck);
}

/** A tile of built track by the line's period (world/railBuild.ts): steam the cheapest, modern the dearest. */
const RAIL_PRICE: Record<RailEra, number> = { steam: 10, streamline: 12, modern: 15 };
/** What a stretch of track costs: every tile, with its bridge tiles charged extra as a road's are. */
export function railCost(era: RailEra, tiles: number, deck = 0): number {
  const per = RAIL_PRICE[era] * ROAD_MUL.v;
  return Math.round(per * tiles + per * (BRIDGE_MULT - 1) * deck);
}
