/** Everything else: the small stuff. */
const DEMOLISH_SMALL = 199;

export function demolishCost(b: Building): number {
  const base = DEMOLISH_BASE[b.kind] ?? DEMOLISH_SMALL;
  const area = b.w * b.d;
  const cost = base * (1 + 0.25 * Math.sqrt(Math.max(0, area - 1))) + 45 * Math.max(0, b.floors - 1);
  return Math.round(cost / 5) * 5;
}

