/**
 * Deeds: what a lot costs and what it pays. A lot's price is the trade already measured at its door
 * (the ledger's `LotLedger.rate`, dollars an hour with a two-day half-life) turned into takings by
 * `yield` and multiplied out over `payback` game days, floored at twice what it would cost to flatten.
 *
 * `yield` and `payback` are the two numbers the page calls gate constants: how often CPU hauliers
 * actually finish a delivery at one door is measured, not reasoned (see `pr.estate.norms()` and
 * `npm run estate`). These are the page's first guesses, not yet fitted.
 */
export const ESTATE = {
  /** The share of the ledger's credit at a door its owner takes: 0.6 of a load's worth at the drop, 0.3 at the pickup. */
  yield: 0.6,
  /** Game days of trade at today's assessed rate a lot's price stands for. */
  payback: 18,
  /** Nothing is cheaper to buy than this many times what it costs to knock down. */
  floor: 2,
  /** The most a lot can take in a game day is its price over this, fixed when bought: twice the assessed pace. */
  ceilingDays: 9,
  /** By the kind of town whose books a lot rides on; out in the country, or with no town near, `country`. */
  town: { rural: 0.8, suburb: 1, city: 1.15, metro: 1.35, mega: 1.7 } as Record<TownKind, number>,
  country: 0.75,
  /** A boarded-up lot sells at this share, and pays nothing. */
  derelict: 0.45,
  /**
   * Each lot already held in the same town adds this share of the price to the next, flat rather than compounding,
   * up to holdingCap (the user, 5 Nov 2026: it was ×1.06 a lot, compounding without end, so 32 lots made a lot ×6.45).
   */
  holding: 0.05,
  /** The most the lots held in a town can add to the next: +100%, reached at 20 lots. */
  holdingCap: 1,
  /** Selling pays this share of what it would be assessed at now. */
  sell: 0.65,
  /** Mending a boarded-up lot you own costs this many times its demolition. */
  mend: 1.5,
  /** How far from your vehicle a lot may be bought, in tiles. */
  reach: 40,
  /** A CPU car that parks at your door pays this, by the kind of trip it made: footfall. */
  footfall: { dock: 5, leisure: 4, shop: 3, work: 3, depot: 3, poi: 2, field: 2, home: 1, parking: 1 } as Record<string, number>,
  /** Seconds before the same vehicle's footfall at the same lot counts again. */
  footfallGuard: 20,
};

export type PaybackWord = 'A bargain' | 'Fair' | 'Steep' | 'A trophy';

/** What the card calls a payback, in game days. */
export function paybackWord(days: number): PaybackWord {
  return days < 12 ? 'A bargain' : days <= 30 ? 'Fair' : days <= 90 ? 'Steep' : 'A trophy';
}

/** What the lots already held in a town multiply the next one's price by: +5% each, at most +100% (ESTATE.holding, holdingCap). */
export function holdingMul(held: number): number {
  return 1 + Math.min(ESTATE.holdingCap, ESTATE.holding * Math.max(0, held));
}

/** Whether `held` lots already put the next at the holding premium's cap. */
export const holdingCapped = (held: number): boolean => ESTATE.holding * held >= ESTATE.holdingCap;

/** A lot's asking price: `rate` is its trade in dollars an hour, `floor` twice its demolition (summed over a harbour). */
export function lotPrice(rate: number, floor: number, town: TownKind | null, derelict: boolean, held: number): number {
  const earnings = Math.max(floor, 24 * ESTATE.payback * ESTATE.yield * Math.max(0, rate));
  const mult = (town ? ESTATE.town[town] : ESTATE.country) * (derelict ? ESTATE.derelict : 1) * holdingMul(held);
  return Math.max(100, Math.round((earnings * mult) / 100) * 100);
}

/** The floor for one building: twice what the bulldozer would charge for it. */
export const lotFloor = (b: Building): number => ESTATE.floor * demolishCost(b);

/** Who money came in from, so the cash chip can tick in their colour: rent is gold. */
export type CashSource = 'you' | 'fleet' | 'rent';

/**
 * The player's money. Every movement names its line in the books (game/books.ts, docs/hqwindow.html):
 * revenue by who earned it, spend, or capital (sales, refunds, grants), so the HQ window's Books can
 * break it all down. `npm run hqwin` fails on a call without one.
 */
export class Wallet {
  constructor(public cash = 0, private onChange: (cash: number) => void = () => {}) {}

  /** What came in last and from whom, so the cash chip can tick in the fleet's colour. */
  lastSource: CashSource = 'you';

  /** Told about every dollar of revenue (never a sale or a refund), for the lifetime-earned counter the stage is read from. */
  onEarn: (amount: number) => void = () => {};
  /** Told about every movement, for the books. */
  onMove: (kind: 'in' | 'out' | 'cap', line: EarnLine | OutLine, who: Who, amount: number) => void = () => {};

  canAfford(amount: number): boolean { return this.cash >= amount; }

  /** Money in: revenue on an income line (by who earned it), or capital coming back. */
  earn(amount: number, line: EarnLine, who: Who = 'you'): void {
    this.cash += amount;
    const cap = isCap(line);
    if (amount > 0) {
      if (!cap) this.onEarn(amount);
      this.onMove(cap ? 'cap' : 'in', line, who, amount);
    }
    this.lastSource = line === 'rent' ? 'rent' : who === 'crew' ? 'fleet' : 'you';
    this.onChange(this.cash);
  }

  /** A penalty: taken whether or not the money is there, so the wallet can go into the red. */
  fine(amount: number, line: OutLine): void {
    this.cash -= amount;
    if (amount > 0) this.onMove('out', line, 'you', amount);
    this.onChange(this.cash);
  }

  /** Take the money if it's there; returns false and changes nothing if it isn't. */
  spend(amount: number, line: OutLine): boolean {
    if (amount > this.cash) return false;
    this.cash -= amount;
    if (amount > 0) this.onMove('out', line, 'you', amount);
    this.onChange(this.cash);
    return true;
  }
}
