import * as THREE from 'three';
import { DIRS, STEP, OPEN_SEA, type Building, type World } from '../world/tiles';
import { frameOf, pointOf, runwaysOf } from '../world/runways';
import { VEHICLES, type AirDef, type VehicleState } from '../game/vehicles';
import { disposeVehicleMesh, poseVehicleMesh, trafficVehicleMesh, type VehicleMesh } from './vehicleMeshes';

/**
 * The aeroplanes parked round the airfields (the user, 2 Nov 2026): every airport's parked airliner, and the fighter in
 * the Army airbase's revetment, is the real model the dealer sells, not a stand-in drawn into the town mesh. An
 * international's lots mostly hold Jumbos in an airline's colours, now and then a Swift; a country airfield's a
 * Swift, or a Barnstormer. The town mesh draws only what stands round them (render/townMesh.ts `airliner`).
 *
 * None of them stands in the way of the sky's own jets (game/skyTraffic.ts) or a hired pilot's (game/jetPilots.ts):
 * those taxi from either live stand straight across to the taxi line, along it the whole length of the strip, and
 * out onto the runway at either end, and a landing jet leaves the runway for the taxi line anywhere along it. A plane
 * whose footprint comes within reach of a taxiing Jumbo's wings, or of a live stand, slides along the apron to the
 * nearest clear place on its lot's line; failing that the next size down is tried, and failing that the lot is left
 * empty.
 */

/** Airline colours: the Jumbo's cheatline and tail, a Swift's body. */
const AIRLINES = [0x2f7fb5, 0xe2412f, 0x3f9b4a, 0xf2a93b, 0x8e5cc7, 0x1d2a5c, 0x2bb3a3];
const SWIFTS = [0xf4f2ec, 0xf4f2ec, 0x22252a, 0x1d2a5c, 0xc8102e];
/** Tiles kept clear beyond a taxiing plane's wingtip; how far a parked plane may slide along the apron, and back from the strip, to find room. */
const MARGIN = 0.3, SLIDE = 4, BACK = 3;
/**
 * Where to try a plane, nearest its lot's middle first: (sideways along the apron, back or forward along its heading),
 * quarter tiles. Both ways: a lot's facing turns some planes' noses away from the strip, so "back" alone slid them onto
 * the runway (the user, 6 Nov 2026), which nothing kept clear; the runway is swept now, and they go the other way.
 */
const TRIES: [number, number][] = [];
for (let b = -BACK * 4; b <= BACK * 4; b++) for (let d = -SLIDE * 4; d <= SLIDE * 4; d++) TRIES.push([d / 4, b / 4]);
TRIES.sort((a, b) => Math.hypot(a[0], a[1]) - Math.hypot(b[0], b[1]) || Math.abs(a[0]) - Math.abs(b[0]));

const byId = (id: string) => VEHICLES.find((d) => d.id === id) as AirDef;
const DEFS = new Map<string, AirDef>();
/** A model in a colour, kept so every plane in that colour shares one body. */
function painted(id: string, color: number): AirDef {
  const key = `${id}|${color}`;
  let d = DEFS.get(key);
  if (!d) DEFS.set(key, (d = { ...byId(id), color }));
  return d;
}

/** What may be parked on an airliner's lot, the first choice first and then smaller: an international's (two floors) or a country airfield's. */
function choicesFor(b: Building): AirDef[] {
  const r = ((b.seed >>> 0) % 1000) / 1000, c = (b.seed >>> 10) % 97;
  const swift = painted('swift', SWIFTS[c % SWIFTS.length]), barn = painted('barnstormer', AIRLINES[c % AIRLINES.length]);
  if (b.floors > 1) return r < 0.75 ? [painted('jumbo', AIRLINES[c % AIRLINES.length]), swift, barn] : [swift, barn];
  return r < 0.65 ? [swift, barn] : [barn];
}

/** A parked plane's pose: still, wheels down. */
function standing(x: number, y: number, z: number, heading: number): VehicleState {
  const s = { x, y, z, heading, v: 0, pitch: 0, roll: 0, bob: 0, lean: 0, wheelSpin: 0, steerVis: 0, power: 0, blocked: 0, trailerHeading: heading, sailAngle: 0, surfaceY: NaN, gear: 1 };
  return s as unknown as VehicleState;
}

/** Ground a taxiing jet sweeps: a point on one of its routes, and how far either side its wings reach. */
interface Sweep { x: number; z: number; r: number }

/** The ground the airport's own traffic needs, sampled every half tile (world tiles). */
export function sweepsOf(w: World): Sweep[] {
  const out: Sweep[] = [];
  const line = (a: { x: number; z: number }, b: { x: number; z: number }, r: number) => {
    const n = Math.max(1, Math.ceil(Math.hypot(b.x - a.x, b.z - a.z) / 0.5));
    for (let k = 0; k <= n; k++) out.push({ x: a.x + ((b.x - a.x) * k) / n, z: a.z + ((b.z - a.z) * k) / n, r });
  };
  for (const r of runwaysOf(w)) {
    // the biggest thing that taxis here: a Jumbo at an international, a Swift (or a hired Stinger) at a country field
    const big = r.major ? byId('jumbo') : byId('swift');
    const ends = [-1.5, r.len + 1.5];
    // the runway itself and the paved band out to the taxi line (the user, 6 Nov 2026: planes were parked on the
    // runway): lines along the strip from its far edge to the taxi line, so nothing parks short of the apron
    const sgn = Math.sign(r.taxiOff) || 1;
    for (let off = -r.half; off * sgn < Math.abs(r.taxiOff); off += 0.5) line(pointOf(r, ends[0], off * sgn), pointOf(r, ends[1], off * sgn), 0.25);
    // the taxi line end to end, and out onto the runway at each end (a landing jet turns off anywhere between)
    line(pointOf(r, ends[0], r.taxiOff), pointOf(r, ends[1], r.taxiOff), big.halfWid);
    for (const e of ends) line(pointOf(r, e, r.taxiOff), pointOf(r, e, 0), big.halfWid);
    // each live stand, the jet standing on it, and its way straight across to the taxi line
    for (const s of r.stands) {
      const f = frameOf(r, s.x, s.z);
      line({ x: s.x, z: s.z }, pointOf(r, f.along, r.taxiOff), big.halfWid);
      out.push({ x: s.x, z: s.z, r: Math.max(big.halfWid, big.halfLen) });
    }
  }
  return out;
}

/** A building's rectangle, world tiles. */
interface Rect { x0: number; z0: number; x1: number; z1: number }

/** Is a plane of `def` at (x, z) heading `h` clear of every sweep, every solid building and every plane already parked? */
function clear(def: AirDef, x: number, z: number, h: number, sweeps: Sweep[], solids: Rect[], parked: { x: number; z: number; def: AirDef }[]): boolean {
  const s = Math.sin(h), c = Math.cos(h);
  for (const p of sweeps) {
    const dx = p.x - x, dz = p.z - z;
    const along = dx * s + dz * c, across = dx * c - dz * s;
    if (Math.abs(along) < def.halfLen + p.r + MARGIN && Math.abs(across) < def.halfWid + p.r + MARGIN) return false;
  }
  // over a terminal, a hangar or a tower: any point of its footprint inside one
  for (const r of solids) {
    for (let i = -2; i <= 2; i++) for (let j = -2; j <= 2; j++) {
      const a = (i / 2) * def.halfLen, b = (j / 2) * def.halfWid;
      const px = x + s * a + c * b, pz = z + c * a - s * b;
      if (px > r.x0 - 0.1 && px < r.x1 + 0.1 && pz > r.z0 - 0.1 && pz < r.z1 + 0.1) return false;
    }
  }
  // another parked plane: kept a wingspan's worth apart
  for (const q of parked) if (Math.hypot(q.x - x, q.z - z) < Math.max(def.halfWid, def.halfLen) + Math.max(q.def.halfWid, q.def.halfLen) + MARGIN) return false;
  return true;
}

export interface Placement { b: Building; def: AirDef; x: number; y: number; z: number; heading: number; slid: number }

/**
 * Where each parked plane in a county goes, world tiles, and how far it slid from its lot's middle to keep out of the
 * taxiing jets' way; a lot with no clear place for anything is listed as empty.
 */
export function placementsOf(w: World): { placed: Placement[]; empty: Building[] } {
  const placed: Placement[] = [], empty: Building[] = [];
  const sweeps = sweepsOf(w);
  const done: { x: number; z: number; def: AirDef }[] = [];
  const solids: Rect[] = w.allBuildings.filter((b) => !b.gone && b.solid).map((b) => ({ x0: w.ox + b.x, z0: w.oz + b.z, x1: w.ox + b.x + b.w, z1: w.oz + b.z + b.d }));
  for (const b of w.allBuildings) {
    if (b.gone || (b.kind !== 'airliner' && b.kind !== 'airbase')) continue;
    // the lot's middle and the way it faces, as the town mesh frames it (render/buildings/kit.ts place)
    const yaw = Math.atan2(DIRS[b.facing][0], DIRS[b.facing][1]), c = Math.cos(yaw), s = Math.sin(yaw);
    const cx = w.ox + b.x + b.w / 2, cz = w.oz + b.z + b.d / 2, y = b.level * STEP + 0.02;
    if (b.kind === 'airbase') {
      // the airbase's fighter on its apron in the revetment, nose out toward its own taxiway and runway (-z)
      const lx = 0.2, lz = 0.02;
      placed.push({ b, def: byId('fighter'), x: cx + lx * c + lz * s, y, z: cz - lx * s + lz * c, heading: yaw + Math.PI, slid: 0 });
      continue;
    }
    // slide sideways in the lot's frame (along the strip) and back from the strip (the plane's nose is toward it), the
    // nearest clear place first; then the next size down
    const near = solids.filter((r) => r.x1 > cx - 9 && r.x0 < cx + 9 && r.z1 > cz - 9 && r.z0 < cz + 9);
    let got: Placement | null = null;
    for (const def of choicesFor(b)) {
      for (const [d, back] of TRIES) {
        const x = cx + d * c - back * s, z = cz - d * s - back * c;
        if (clear(def, x, z, yaw, sweeps, near, done)) { got = { b, def, x, y, z, heading: yaw, slid: Math.hypot(d, back) }; break; }
      }
      if (got) break;
    }
    if (!got) { empty.push(b); continue; }
    placed.push(got);
    done.push({ x: got.x, z: got.z, def: got.def });
  }
  return { placed, empty };
}

interface Parked { mesh: VehicleMesh; b: Building; kit: THREE.Group | null }

/** The tug and its baggage carts beside a parked airliner or jet, behind its wing on the side away from its door. */
const BOX = new THREE.BoxGeometry(1, 1, 1);
const MATS = new Map<number, THREE.MeshStandardMaterial>();
const mat = (c: number) => { let m = MATS.get(c); if (!m) MATS.set(c, (m = new THREE.MeshStandardMaterial({ color: c, roughness: 0.75, flatShading: true }))); return m; };
function groundKit(p: Placement): THREE.Group {
  const g = new THREE.Group();
  const add = (x: number, y: number, z: number, w: number, h: number, d: number, c: number) => {
    const m = new THREE.Mesh(BOX, mat(c));
    m.scale.set(w, h, d);
    m.position.set(x, y + h / 2, z);
    m.castShadow = true;
    g.add(m);
  };
  const big = p.def.id === 'jumbo';
  // in the plane's frame: +x to its right, +z toward its nose
  const x = p.def.halfWid * 0.75, z = -p.def.halfLen * (big ? 0.55 : 0.75);
  const seed = p.b.seed >>> 0;
  add(x, 0, z, 0.16, 0.1, 0.24, [0xf2c14e, 0xf28c38, 0xe8e6df][seed % 3]);
  add(x, 0.1, z - 0.04, 0.12, 0.08, 0.1, 0x3f4650);
  for (let i = 1; i <= (big ? 3 : 1); i++) {
    add(x, 0.02, z - i * 0.3, 0.16, 0.05, 0.22, 0x9aa0a6);
    add(x, 0.07, z - i * 0.3, 0.12, 0.06, 0.18, [0x2f7fb5, 0x8a5a2b, 0x3f9b4a, 0xe2412f][(seed >>> (i * 2)) % 4]);
  }
  // chocks at the nose wheel
  for (const dz of [-0.06, 0.06]) add(0, 0, p.def.halfLen * 0.7 + dz, 0.06, 0.035, 0.035, 0xf2c14e);
  g.position.set(p.x, p.y - 0.02, p.z);
  g.rotation.y = p.heading;
  return g;
}

export class ParkedPlanes {
  readonly root = new THREE.Group();
  /** Each county's planes, and the revision they were placed at. */
  private worlds = new Map<World, { rev: number; planes: Parked[] }>();

  constructor() { this.root.name = 'parkedPlanes'; }

  update(worlds: World[]): void {
    const live = new Set(worlds);
    for (const w of worlds) {
      const was = this.worlds.get(w);
      if (was && was.rev === w.revision && !was.planes.some((p) => p.b.gone)) continue;
      if (was) this.drop(was.planes);
      this.worlds.set(w, { rev: w.revision, planes: this.place(w) });
    }
    for (const [w, v] of this.worlds) if (!live.has(w)) { this.drop(v.planes); this.worlds.delete(w); }
  }

  private place(w: World): Parked[] {
    return placementsOf(w).placed.map((p) => {
      const mesh = trafficVehicleMesh(p.def, false);
      poseVehicleMesh(mesh, standing(p.x, p.y, p.z, p.heading), p.def, OPEN_SEA);
      this.root.add(mesh.holder);
      const kit = p.b.kind === 'airliner' ? groundKit(p) : null;
      if (kit) this.root.add(kit);
      return { mesh, b: p.b, kit };
    });
  }

  private drop(planes: Parked[]): void {
    for (const p of planes) { this.root.remove(p.mesh.holder); disposeVehicleMesh(p.mesh); if (p.kit) this.root.remove(p.kit); }
  }

  clear(): void {
    for (const v of this.worlds.values()) this.drop(v.planes);
    this.worlds.clear();
  }
}
