import { DIRS, N, STEP, World, type Arch, type Building, type BuildingKind, type RegionKind, type Town, type TownKind } from '../world/tiles';
import { hashString, mulberry32 } from '../world/rng';
import { KIND_SPEC } from '../world/townKinds';
import { Kit, setStyle } from '../render/buildings/kit';
import { drawOf } from '../render/townMesh';
import { CARGO } from './cargoTypes';
import { drawStamp } from './postcardFrame';
import { landStamp, townStamp } from './stampLooks';
import { KIND_OF, type EventKind } from './events/kinds';

/**
 * The Passport's stamps (docs/passport.html), each one particular to what it is for, so a rare one is worth
 * having: a perforated postage stamp for every town style, biome and size of town (the postcards' own stamps,
 * game/stampLooks.ts); a rubber-stamp impression in ink of a building's real model for every kind of building
 * and every wonder; and for a landform or an achievement, its picture pressed in ink inside a stamp's ring.
 * Each is drawn once, the first time it is wanted, and kept as a picture.
 */

const CACHE = new Map<string, string>();
const cached = (key: string, make: () => string): string => { let v = CACHE.get(key); if (!v) CACHE.set(key, (v = make())); return v; };

/** Inks a stamp may be pressed in; a rare one (a style's own building, a wonder) gets a rare ink. */
/**
 * What a building's ink says about it: what sort of place it is. A style's own landmark and a wonder are
 * pressed in gold foil instead, and shine: those are the rare ones.
 */
export type InkClass = 'civic' | 'homes' | 'shops' | 'works' | 'open';
export const INK: Record<InkClass, { ink: string; label: string }> = {
  civic: { ink: '#24408e', label: 'civic' },
  homes: { ink: '#2e6b3a', label: 'homes' },
  shops: { ink: '#7a4a1e', label: 'shops, food & business' },
  works: { ink: '#2b2f36', label: 'industry & farms' },
  open: { ink: '#1f7a78', label: 'parks & open ground' },
};
const HOMES = new Set<string>(['house', 'cottage', 'bungalow', 'duplex', 'townhouse', 'terraceRow', 'apartment', 'towerBlock', 'courtyardBlock', 'condoTower',
  'mansion', 'retirementHome', 'trailerPark', 'stiltHouse', 'croft', 'resortVillas', 'farmhouse', 'rondavel', 'ranchHouse', 'yurt', 'turfHouse', 'rorbu',
  'pueblo', 'bastide', 'hobbitHole', 'megablock', 'gardenTower']);
const MAKES = new Set<string>(CARGO.flatMap((c) => c.from as string[]));
const TAKES = new Set<string>(CARGO.flatMap((c) => c.to as string[]));
/** A building kind's ink class: a home, open ground, somewhere goods are made (industry, farms), somewhere they are sold or used, else civic. */
function inkClass(kind: string): InkClass {
  if (HOMES.has(kind)) return 'homes';
  if (KIND_SPEC[kind as BuildingKind]?.solid === false || kind === 'park' || kind === 'plaza' || kind === 'pitch' || kind === 'field' || kind === 'parking') return 'open';
  if (MAKES.has(kind) && !TAKES.has(kind)) return 'works';
  if (TAKES.has(kind) || MAKES.has(kind)) return 'shops';
  return 'civic';
}
/** Gold foil: a gradient across the stamp from deep gold to near white and back. */
function foil(g: CanvasRenderingContext2D, S: number): CanvasGradient {
  const f = g.createLinearGradient(-S / 2, -S / 2, S / 2, S / 2);
  f.addColorStop(0, '#7d5210');
  f.addColorStop(0.28, '#e8bd4f');
  f.addColorStop(0.45, '#fff1b8');
  f.addColorStop(0.62, '#c99632');
  f.addColorStop(1, '#8a5c14');
  return f;
}
/** Four-pointed glints, the same for the same stamp every time. */
function glints(g: CanvasRenderingContext2D, S: number, seed: string): void {
  const r = mulberry32(hashString(seed + '|glint'));
  for (let k = 0; k < 6; k++) {
    const x = (r() - 0.5) * S * 0.84, y = (r() - 0.5) * S * 0.84, s = 2.5 + r() * 4;
    g.fillStyle = k % 2 ? '#fff8d8' : '#ffffff';
    g.globalAlpha = 0.75 + r() * 0.25;
    g.beginPath();
    g.moveTo(x, y - s); g.quadraticCurveTo(x, y, x + s, y); g.quadraticCurveTo(x, y, x, y + s); g.quadraticCurveTo(x, y, x - s, y); g.quadraticCurveTo(x, y, x, y - s);
    g.fill();
  }
  g.globalAlpha = 1;
}

function canvas(w: number, h: number): [HTMLCanvasElement, CanvasRenderingContext2D] {
  const c = document.createElement('canvas');
  c.width = w; c.height = h;
  return [c, c.getContext('2d')!];
}

/** Rubber-stamp grain: a scatter of tiny gaps where the ink didn't take, the same for the same stamp every time. */
function grain(g: CanvasRenderingContext2D, w: number, h: number, seed: string): void {
  const r = mulberry32(hashString(seed));
  g.save();
  g.globalCompositeOperation = 'destination-out';
  for (let k = 0; k < (w * h) / 55; k++) {
    g.globalAlpha = 0.35 + r() * 0.6;
    g.beginPath();
    g.arc(r() * w, r() * h, 0.4 + r() * 1.3, 0, Math.PI * 2);
    g.fill();
  }
  g.restore();
}

// ---- postage stamps -------------------------------------------------------------------------------

/** Drawn at twice the size they are shown, so the opened stamp is sharp. */
const POST_W = 192, POST_H = 240;

/** A town style's postage stamp. */
function styleStamp(style: Arch, kind: TownKind = 'city'): string {
  return cached(`style:${style}`, () => postage(townStamp(style, kind)));
}
/** A biome's postage stamp. */
function biomeStamp(region: RegionKind): string {
  return cached(`biome:${region}`, () => postage(landStamp(region)));
}
/** A size of town's postage stamp: its own picture, whatever the style. */
function sizeStamp(kind: TownKind): string {
  return cached(`size:${kind}`, () => postage(townStamp('__none__' as Arch, kind)));
}
function postage(look: { icon: string; label: string; colour: string }): string {
  const [c, g] = canvas(POST_W, POST_H);
  drawStamp(g, 8, 8, POST_W - 16, POST_H - 20, look, (POST_W - 16) / 172.8);
  return c.toDataURL('image/png');
}

// ---- ink: a building's own shape -------------------------------------------------------------------

let scratch: World | null = null;

/**
 * A building's rubber stamp: its model drawn from the usual three-quarter view and pressed in one ink, the
 * faces in three tones by how they catch the light and how dark they are painted, framed and named. The ink
 * says what sort of place it is (INK); `rare` (a style's landmark, a wonder) presses it in gold foil, with a
 * triple frame and glints.
 */
function buildingStamp(kind: BuildingKind, style: Arch, label: string, rare: boolean): string {
  return cached(`b:${kind}:${style}:${rare ? 'foil' : 'ink'}`, () => {
    const S = 132, X = 2;
    const [c, g] = canvas(S * X, (S + 22) * X);
    g.scale(X, X);
    const tris = buildingTris(kind, style);
    g.save();
    g.translate(S / 2, S / 2 + 4);
    g.rotate(((hashString(kind) % 9) - 4) * 0.012);
    const ink: string | CanvasGradient = rare ? foil(g, S) : INK[inkClass(kind)].ink;
    // the frame: a rounded rectangle, double ruled (a foil stamp's triple, with a fine inner line)
    g.strokeStyle = ink; g.fillStyle = ink;
    g.lineWidth = rare ? 4 : 3; g.beginPath(); g.roundRect(-S / 2 + 4, -S / 2 + 4, S - 8, S - 8, 12); g.stroke();
    g.lineWidth = 1.2; g.beginPath(); g.roundRect(-S / 2 + 10, -S / 2 + 10, S - 20, S - 20, 8); g.stroke();
    if (rare) { g.lineWidth = 0.7; g.beginPath(); g.roundRect(-S / 2 + 13, -S / 2 + 13, S - 26, S - 26, 6); g.stroke(); }
    if (tris.length) {
      // fit the projected model inside the inner frame
      let x0 = Infinity, x1 = -Infinity, y0 = Infinity, y1 = -Infinity;
      for (const t of tris) for (let v = 0; v < 3; v++) { x0 = Math.min(x0, t.p[v * 2]); x1 = Math.max(x1, t.p[v * 2]); y0 = Math.min(y0, t.p[v * 2 + 1]); y1 = Math.max(y1, t.p[v * 2 + 1]); }
      const room = S - 34, k = room / Math.max(x1 - x0, y1 - y0, 1e-3);
      const ox = -(x0 + x1) / 2 * k, oy = -(y0 + y1) / 2 * k;
      g.lineJoin = 'round';
      for (const t of tris) {
        // foil is pressed harder: its lightest faces still show, and every face keeps a fine dark-gold edge
        g.globalAlpha = rare ? 0.55 + t.tone * 0.45 : t.tone;
        g.beginPath();
        g.moveTo(t.p[0] * k + ox, t.p[1] * k + oy);
        g.lineTo(t.p[2] * k + ox, t.p[3] * k + oy);
        g.lineTo(t.p[4] * k + ox, t.p[5] * k + oy);
        g.closePath();
        g.fill();
        // a hair of stroke in the same tone closes the seams between neighbouring faces
        g.lineWidth = rare ? 0.7 : 0.6;
        g.strokeStyle = rare ? 'rgba(110, 70, 10, 0.75)' : ink;
        g.stroke();
        if (rare) g.strokeStyle = ink;
      }
      g.globalAlpha = 1;
    }
    if (rare) glints(g, S, kind);
    g.restore();
    // the name under it, in the same ink (gold for foil)
    g.fillStyle = rare ? '#a8741a' : ink;
    g.textAlign = 'center';
    g.textBaseline = 'middle';
    let size = 12;
    const text = label.toUpperCase();
    g.font = `700 ${size}px "Fredoka", "Segoe UI", system-ui, sans-serif`;
    while (size > 7 && g.measureText(text).width > S - 6) { size--; g.font = `700 ${size}px "Fredoka", "Segoe UI", system-ui, sans-serif`; }
    g.fillText(text, S / 2, S + 13);
    g.setTransform(1, 0, 0, 1, 0, 0);
    // foil is clean; ink takes the grain of the rubber
    if (!rare) grain(g, S * X, (S + 22) * X, kind);
    return c.toDataURL('image/png');
  });
}

/** Building stamps waiting to be drawn, a few a frame, so a page of them never stalls the game. */
const queue: { key: string; make: () => string; img: HTMLImageElement }[] = [];
let pumping = false;
function pump(): void {
  const t0 = performance.now();
  while (queue.length && performance.now() - t0 < 8) {
    const q = queue.shift()!;
    if (q.img.isConnected) q.img.src = cached(q.key, q.make);
  }
  // a timer, not a frame: it yields to the game just the same, and goes on in a tab the browser isn't drawing
  if (queue.length) setTimeout(pump, 0); else pumping = false;
}

/** A building's stamp into this picture: at once if it has been drawn before, else as soon as its turn comes. */
export function buildingStampInto(img: HTMLImageElement, kind: BuildingKind, style: Arch, label: string, rare: boolean): void {
  const key = `b:${kind}:${style}:${rare ? 'foil' : 'ink'}`;
  const done = CACHE.get(key);
  if (done) { img.src = done; img.classList.toggle('foil', rare); return; }
  img.classList.add('pending');
  if (rare) img.classList.add('foil');
  queue.push({ key, make: () => buildingStamp(kind, style, label, rare), img });
  img.addEventListener('load', () => img.classList.remove('pending'), { once: true });
  if (!pumping) { pumping = true; setTimeout(pump, 0); }
}

/**
 * A building's silhouette for a menu square (the road builder's Buildings side): its real model pressed in
 * its stamp's ink, three tones, no frame and no name, square and transparent. `size` is the lot the town
 * would build it on, so a terrace reads long and a tower tall.
 */
function buildingIcon(kind: BuildingKind, style: Arch, size?: { w: number; d: number; floors?: number }): string {
  return cached(iconKey(kind, style, size), () => {
    const S = 64, X = 2;
    const [c, g] = canvas(S * X, S * X);
    g.scale(X, X);
    const tris = buildingTris(kind, style, size);
    if (tris.length) {
      let x0 = Infinity, x1 = -Infinity, y0 = Infinity, y1 = -Infinity;
      for (const t of tris) for (let v = 0; v < 3; v++) { x0 = Math.min(x0, t.p[v * 2]); x1 = Math.max(x1, t.p[v * 2]); y0 = Math.min(y0, t.p[v * 2 + 1]); y1 = Math.max(y1, t.p[v * 2 + 1]); }
      const room = S - 8, k = room / Math.max(x1 - x0, y1 - y0, 1e-3);
      // stood on the square's floor, centred across it
      const ox = S / 2 - (x0 + x1) / 2 * k, oy = S - 4 - y1 * k;
      // the stamps' way, faces see-through in three tones over each other, so every part of the model shows;
      // but filled only: a stroke round each triangle doubled up down the diagonal of every face
      g.fillStyle = INK[inkClass(kind)].ink;
      for (const t of tris) {
        g.globalAlpha = t.tone;
        g.beginPath();
        g.moveTo(t.p[0] * k + ox, t.p[1] * k + oy);
        g.lineTo(t.p[2] * k + ox, t.p[3] * k + oy);
        g.lineTo(t.p[4] * k + ox, t.p[5] * k + oy);
        g.closePath();
        g.fill();
      }
      g.globalAlpha = 1;
    }
    return c.toDataURL('image/png');
  });
}
const iconKey = (kind: BuildingKind, style: Arch, size?: { w: number; d: number; floors?: number }) => `i:${kind}:${style}:${size ? `${size.w}x${size.d}x${size.floors ?? ''}` : ''}`;

/** A building's silhouette into this picture: at once if drawn before, else a few a frame, as the stamps are. */
export function buildingIconInto(img: HTMLImageElement, kind: BuildingKind, style: Arch, size?: { w: number; d: number; floors?: number }): void {
  const key = iconKey(kind, style, size);
  const done = CACHE.get(key);
  if (done) { img.src = done; return; }
  img.classList.add('pending');
  queue.push({ key, make: () => buildingIcon(kind, style, size), img });
  img.addEventListener('load', () => img.classList.remove('pending'), { once: true });
  if (!pumping) { pumping = true; setTimeout(pump, 0); }
}

/** A model's faces, projected to the stamp's view and sorted far to near, each with the ink tone it takes. */
function buildingTris(kind: BuildingKind, style: Arch, size?: { w: number; d: number; floors?: number }): { p: number[]; tone: number; d: number }[] {
  if (!scratch) { scratch = new World(); scratch.corners.fill(4); }
  const w = scratch;
  const spec = KIND_SPEC[kind];
  const first = (v: number | [number, number] | undefined, d: number) => (v === undefined ? d : typeof v === 'number' ? v : v[0]);
  const b: Building = {
    kind, x: 40, z: 40, w: size?.w ?? first(spec?.w, 1), d: size?.d ?? first(spec?.d, 1), facing: 0,
    floors: Math.max(1, size?.floors ?? first(spec?.floors, 2)), seed: 4242, solid: true, level: 4, uid: -1,
  };
  const town: Town = { id: 0, kind: 'metro', name: 'Stamp', x0: 0, z0: 0, size: N, level: 4, style, buildings: [b], roads: 0, entry: [] };
  w.towns = [town];
  w.allBuildings = [b];
  const draw = drawOf(b);
  if (!draw) return [];
  const k = new Kit(w);
  try {
    setStyle(style, 0.3);
    k.place(b.x + b.w / 2, b.level * STEP, b.z + b.d / 2, Math.atan2(DIRS[b.facing][0], DIRS[b.facing][1]));
    draw(k, b.d, b.w, b, mulberry32(b.seed), town);
  } catch { return []; }
  // the usual camera: from the south-east, a little above
  const yaw = Math.PI * 0.25, cy = Math.cos(yaw), sy = Math.sin(yaw), pitch = 0.55, cp = Math.cos(pitch), sp = Math.sin(pitch);
  const out: { p: number[]; tone: number; d: number }[] = [];
  const pos = k.pos, col = k.col;
  for (let i = 0; i < pos.length; i += 9) {
    const p: number[] = [];
    let depth = 0;
    for (let v = 0; v < 3; v++) {
      const x = pos[i + v * 3] - 40, y = pos[i + v * 3 + 1], z = pos[i + v * 3 + 2] - 40;
      const rx = x * cy - z * sy, rz = x * sy + z * cy;
      p.push(rx, -(y * cp) + rz * sp);
      depth += rz * cp + y * sp;
    }
    // facing away from the eye: never seen
    const ax = p[2] - p[0], ay = p[3] - p[1], bx = p[4] - p[0], by = p[5] - p[1];
    if (ax * by - ay * bx >= 0) continue;
    // its light: the face's normal against a sun from the upper left, and the darkness of its paint
    const ux = pos[i + 3] - pos[i], uy = pos[i + 4] - pos[i + 1], uz = pos[i + 5] - pos[i + 2];
    const vx = pos[i + 6] - pos[i], vy = pos[i + 7] - pos[i + 1], vz = pos[i + 8] - pos[i + 2];
    const nx = uy * vz - uz * vy, ny = uz * vx - ux * vz, nz = ux * vy - uy * vx, nl = Math.hypot(nx, ny, nz) || 1;
    const lit = (nx * -0.4 + ny * 0.8 + nz * 0.45) / nl;
    const j = (i / 9) * 9;
    const lum = 0.3 * col[j] + 0.59 * col[j + 1] + 0.11 * col[j + 2];
    // three tones, as a stamp has: shadow, mid, highlight (the paper shows through the lightest)
    const t = (1 - lum) * 0.55 + (1 - Math.max(0, lit)) * 0.45;
    const tone = t > 0.62 ? 1 : t > 0.4 ? 0.62 : 0.28;
    out.push({ p, tone, d: depth / 3 });
  }
  return out.sort((a, b) => b.d - a.d);
}

// ---- ink: a picture pressed inside a ring ----------------------------------------------------------

/**
 * A round rubber stamp: two rings, the name round the top, and the picture (an emoji, its colours pressed out
 * into one ink) in the middle. `ink` null picks one from the key.
 */
export function ringStamp(key: string, icon: string, label: string, ink: string | null, size = 104): string {
  return cached(`ring:${key}:${icon}:${ink}:${size}`, () => {
    // drawn at twice the size it is shown, so the opened stamp is sharp
    size *= 2;
    const S = size, R = S / 2 - 6;
    const [c, g] = canvas(S, S);
    const colour = ink ?? landInk(key.replace(/^lf:/, ''));
    g.translate(S / 2, S / 2);
    g.rotate(((hashString(key) % 11) - 5) * 0.03);
    g.strokeStyle = colour; g.fillStyle = colour;
    g.lineWidth = Math.max(1.5, S * 0.03); g.beginPath(); g.arc(0, 0, R, 0, Math.PI * 2); g.stroke();
    g.lineWidth = Math.max(1, S * 0.012); g.beginPath(); g.arc(0, 0, R * 0.7, 0, Math.PI * 2); g.stroke();
    // the name round the top, between the rings
    if (label) {
      const f = Math.round(R * 0.2);
      g.font = `700 ${f}px "Fredoka", "Segoe UI", system-ui, sans-serif`;
      g.textAlign = 'center'; g.textBaseline = 'middle';
      const text = label.toUpperCase(), rr = R * 0.85, track = R * 0.02;
      let span = [...text].reduce((s, ch) => s + g.measureText(ch).width + track, 0) / rr;
      const sizeFit = span > Math.PI * 1.5 ? (Math.PI * 1.5) / span : 1;
      if (sizeFit < 1) { g.font = `700 ${Math.round(f * sizeFit)}px "Fredoka", "Segoe UI", system-ui, sans-serif`; span = [...text].reduce((s, ch) => s + g.measureText(ch).width + track, 0) / rr; }
      let a = -span / 2;
      for (const ch of text) {
        const cw = (g.measureText(ch).width + track) / rr;
        a += cw / 2;
        g.save(); g.rotate(a); g.translate(0, -rr); g.fillText(ch, 0, 0); g.restore();
        a += cw / 2;
      }
    }
    // the picture, pressed out in the ink: drawn alone, then everything it covers filled with the ink
    const P = Math.round(R * 1.05);
    const [pc, pg] = canvas(P, P);
    pg.textAlign = 'center'; pg.textBaseline = 'middle';
    pg.font = `${Math.round(P * 0.82)}px "Segoe UI Emoji", "Apple Color Emoji", "Noto Color Emoji", sans-serif`;
    pg.fillText(icon, P / 2, P / 2 + P * 0.04);
    // light parts of the picture press lighter: keep its shading as the ink's strength
    const img = pg.getImageData(0, 0, P, P), d = img.data;
    const ir = parseInt(colour.slice(1, 3), 16), ig = parseInt(colour.slice(3, 5), 16), ib = parseInt(colour.slice(5, 7), 16);
    for (let q = 0; q < d.length; q += 4) {
      const a = d[q + 3];
      if (!a) continue;
      const lum = (0.3 * d[q] + 0.59 * d[q + 1] + 0.11 * d[q + 2]) / 255;
      const strength = lum > 0.78 ? 0.25 : lum > 0.45 ? 0.65 : 1;
      d[q] = ir; d[q + 1] = ig; d[q + 2] = ib; d[q + 3] = a * strength;
    }
    pg.putImageData(img, 0, 0);
    g.drawImage(pc, -P / 2, -P / 2 + R * 0.06);
    g.setTransform(1, 0, 0, 1, 0, 0);
    grain(g, S, S, key);
    return c.toDataURL('image/png');
  });
}

/** The stamp a sight of the Passport is shown by: its page and key (game/sights.ts), and its name. */
export function sightStamp(page: 'arch' | 'biome' | 'size' | 'wonder' | 'landform' | 'kind' | 'event', key: string, label: string, signature?: Arch): string {
  switch (page) {
    // an event (docs/events.html): its picture in a ring, in the carnival's violet
    case 'event': return ringStamp(`ev:${key}`, KIND_OF[key as EventKind]?.icon ?? '🎪', label, '#6b2d8e');
    case 'arch': return styleStamp(key as Arch);
    case 'biome': return biomeStamp(key as RegionKind);
    case 'size': return sizeStamp(key as TownKind);
    case 'wonder': return buildingStamp(key as BuildingKind, 'classic', label, true);
    case 'landform': return ringStamp(`lf:${key}`, LANDFORM_ICON[key] ?? '⛰️', label, null);
    default: return buildingStamp(key as BuildingKind, signature ?? 'classic', label, !!signature);
  }
}

/** A landform's ink, by what it is made of: water blue, volcanic red, glacier ice, otherwise earth. */
const WATERY = new Set(['atoll', 'delta', 'fjordCoast', 'cascade', 'tarn', 'waterfall', 'hotSprings', 'skerries', 'tombolo', 'mangroves', 'seaArch']);
const FIERY = new Set(['volcano', 'caldera', 'lavaField']);
function landInk(kind: string): string {
  return WATERY.has(kind) ? '#24608e' : FIERY.has(kind) ? '#a3201c' : kind === 'glacier' ? '#3f86a8' : '#6b4a2a';
}

/** Each landform's picture, for its ring stamp. */
const LANDFORM_ICON: Record<string, string> = {
  volcano: '🌋', caldera: '🌋', atoll: '🏝️', fjordCoast: '🏔️', riftValley: '🏜️', dunes: '🐪', saltFlat: '🧂', glacier: '🧊', karstTowers: '⛰️',
  badlands: '🏜️', mesaCountry: '🏜️', delta: '🌊', skerries: '🪨', mangroves: '🌴', mountainPass: '🛤️', lavaField: '🔥', gorge: '🏞️',
  cascade: '💧', tarn: '🏞️', hoodoos: '🗿', tombolo: '🏖️', hotSprings: '♨️', seaArch: '🌉', sinkhole: '🕳️', basaltColumns: '🧱',
  caveTunnel: '🦇', naturalBridge: '🌁', erratics: '🪨', grove: '🌳', waterfall: '🌊',
};
