  maple: { label: 'Maple wood', name: (a) => `${a} Maples`, r: [10, 16], trees: [['maple', 5], ['oak', 1]], density: 0.85, second: 0.35, scale: [0.9, 1.25] },
  oldGrowth: {
    label: 'Old-growth forest', name: (a) => `the ${a} Old Growth`, r: [12, 18], trees: [['fir', 4], ['redwood', 1], ['spruce', 1]],
    density: 0.55, second: 0, scale: [1.2, 1.7], floor: ['fern', 0.35], ground: [0x3e5a34, 0.35],
  },
  larch: { label: 'Larch wood', name: (a) => `${a} Larches`, r: [9, 14], trees: [['larch', 5], ['spruce', 1]], density: 0.8, second: 0.3, scale: [0.9, 1.2] },
  cypressSwamp: {
    label: 'Cypress swamp', name: (a) => `${a} Swamp`, r: [9, 14], trees: [['baldCypress', 1]], density: 0.7, second: 0.2, scale: [0.9, 1.2],
    wade: 1, wet: 0.12, ground: [0x55663a, 0.4],
  },
  mangroves: { label: 'Mangrove forest', name: (a) => `${a} Mangroves`, r: [8, 13], trees: [['mangrove', 1]], density: 0.8, second: 0.3, scale: [0.85, 1.15], wade: 1, wet: 0.15 },
  bamboo: { label: 'Bamboo forest', name: (a) => `the ${a} Bamboo Grove`, r: [8, 12], trees: [['bamboo', 1]], density: 0.95, second: 0.85, scale: [1.05, 1.35] },
  eucalyptus: {
    label: 'Eucalyptus forest', name: (a) => `${a} Gums`, r: [9, 15], trees: [['eucalyptus', 1]], density: 0.6, second: 0.15, scale: [1.0, 1.4],
    floor: ['shrub', 0.12], ground: [0xb59a6a, 0.25],
  },
  pineBarrens: {
    label: 'Pine barrens', name: (a) => `the ${a} Barrens`, r: [12, 18], trees: [['pine', 3], ['stonePine', 1]], density: 0.32, second: 0, scale: [0.7, 0.95],
    floor: ['shrub', 0.18], ground: [0xd9c99a, 0.55],
  },
