/** Out of every hundred counties, how many look for woods, and how many woods at most a county. */
const WOOD_CHANCE = 0.55, MAX_WOODS = 2;

/** Ground a wood may grow on: open, unbuilt, gentle, and of the wood's own country (or its water, for those that wade). */
function woodGround(w: World, i: number, sp: WoodSpec): boolean {
  if (w.cleared[i] || w.road[i] || w.deckAxis[i] || w.rail[i] & RAIL_KEEP_CLEAR || w.blocked[i] || w.townId[i] >= 0 || w.portId[i] >= 0 || w.lot[i]) return false;
  if (w.flags[i] & (Flag.Track | Flag.Field | Flag.Poi | Flag.Ramp) || insideCurve(w, i)) return false;
  if (w.water[i] >= 0) return !!sp.wade && waterDepth(w, i) <= sp.wade && w.feature[i] === Feature.None;
  // a drowned wood's dead trees stand in the water and along its very edge, never out on dry ground
  if (sp.wetOnly && !besideWater(w, i)) return false;
  const b = w.biome[i];
  if (b === Biome.Town || b === Biome.Ocean || b === Biome.Farm || b === Biome.Snow) return false;
  if (w.feature[i] !== Feature.None && w.feature[i] !== Feature.Beach) return false;
  const s = w.surface[i];
  if (s === Surface.Salt || s === Surface.Ice || s === Surface.Lava || s === Surface.Cave || s === Surface.Basalt || s === Surface.Rock) return false;
  return steepness(w, i) < 2;
}

function besideWater(w: World, i: number): boolean {
  const x = i % N, z = (i - x) / N;
  for (let dz = -1; dz <= 1; dz++) for (let dx = -1; dx <= 1; dx++) if (inB(x + dx, z + dz) && w.water[idx(x + dx, z + dz)] >= 0) return true;
  return false;
}

/** Which kind of wood, if any, suits a site: its climate, its ground, its water and its biome. */
function kindFor(w: World, x: number, z: number, moist: number, roll: number, near: { water: number; lake: number; sea: number; town: number }): WoodKind | null {
  const i = idx(x, z), t = w.temp[i], b = w.biome[i];
  const wood = b === Biome.Forest, open = b === Biome.Plains || b === Biome.Hills, hill = b === Biome.Hills || b === Biome.Mountain;
  const fits: WoodKind[] = [];
  // (w.temp runs warm: most wooded ground lies about 0.9; the cool north 0.2 to 0.5, the temperate band 0.55 to 0.85)
  if (t < 0.55 && (hill || wood) && w.corners[i * 4] >= 6) fits.push('aspen');
  if (t >= 0.45 && t < 0.88 && moist >= 0.4 && (wood || b === Biome.Hills)) fits.push('maple');
  if (t >= 0.35 && t < 0.88 && moist >= 0.55 && wood) fits.push('oldGrowth');
  if (t < 0.5 && (hill || wood)) fits.push('larch');
  if (t >= 0.8 && near.water >= 6 && near.sea === 0 && (open || wood || b === Biome.Marsh)) fits.push('cypressSwamp');
  if (t >= 0.88 && near.sea >= 4) fits.push('mangroves');
  if (t >= 0.85 && moist >= 0.6 && (wood || b === Biome.Hills)) fits.push('bamboo');
  if (t >= 0.88 && moist >= 0.2 && moist < 0.55 && (open || wood)) fits.push('eucalyptus');
  if (t >= 0.55 && t < 0.9 && moist < 0.5 && b === Biome.Plains) fits.push('pineBarrens');
  if (t >= 0.5 && moist < 0.78 && wood && roll < 0.3) fits.push('burnScar');
  if (t >= 0.4 && t < 0.9 && b === Biome.Plains && near.town > 0) fits.push('treeFarm');
  if (near.lake >= 5 && t < 0.92) fits.push('drowned');
  return fits.length ? fits[Math.floor(hash2(x, z, 7303 + Math.floor(roll * 97)) * fits.length) % fits.length] : null;
}

/**
 * Site this county's woods, if it has any. Called once the county is finished, beside the groves (generate.ts), so a
 * wood lands on none of its roads, towns or works; `moisture` is the generator's per-tile moisture. No rng draws.
 */
export function placeWoods(w: World, moisture: Float32Array, seedHash: number, band: number): void {
  const roll = hashCell(seedHash, w.cx, w.cz, 7301) / 4294967296;
  if (roll >= WOOD_CHANCE) return;
  const want = roll < WOOD_CHANCE * 0.35 ? MAX_WOODS : 1;
  const keep = Math.max(12, band + 12), span = N - 2 * keep;
  if (span < 20) return;
  let placed = 0;
  for (let k = 0; k < 120 && placed < want; k++) {
    const h = hashCell(seedHash, w.cx, w.cz, 7310 + k);
    const x = keep + (h % span), z = keep + ((h >>> 12) % span);
    const i = idx(x, z);
    if (w.water[i] >= 0 && w.coastDist[i] > 0) continue;
    // what lies round the site: fresh and salt water, a lake, a town
    const near = { water: 0, lake: 0, sea: 0, town: 0 };
    for (let dz = -10; dz <= 10; dz += 2) for (let dx = -10; dx <= 10; dx += 2) {
      if (!inB(x + dx, z + dz)) continue;
      const j = idx(x + dx, z + dz);
      if (w.water[j] >= 0) {
        if (w.biome[j] === Biome.Ocean || w.coastDist[j] === 0) near.sea++;
        else { near.water++; if (!(w.flags[j] & (Flag.River | Flag.Stream)) && waterDepth(w, j) >= 2) near.lake++; }
      }
      if (w.flags[j] & (Flag.River | Flag.Stream)) near.water++;
    }
    if (w.towns.some((t) => Math.abs(t.x0 + t.size / 2 - x) < t.size / 2 + 24 && Math.abs(t.z0 + t.size / 2 - z) < t.size / 2 + 24)) near.town = 1;
    const kind = kindFor(w, x, z, moisture[i], hash2(w.cx, w.cz, 7302 + k), near);
    if (!kind) continue;
    const sp = WOOD_SPECS[kind];
    const r = sp.r[0] + Math.floor(hash2(w.ox + x, w.oz + z, 7304) * (sp.r[1] - sp.r[0] + 1));
    // clear of every other named place
    if (w.landmarks.some((o) => Math.hypot(o.x - x, o.z - z) < Math.min(o.r, 40) + r + 4)) continue;
    const l: Landmark = { kind: 'wood', name: '', x: x + 0.5, z: z + 0.5, r, data: [WOOD_KINDS.indexOf(kind)] };
    // enough of it must be ground the wood can grow on
    let good = 0, all = 0, wet = 0;
    eachWoodTile(w, l, (j) => { all++; if (woodGround(w, j, sp)) { good++; if (w.water[j] >= 0) wet++; } });
    if (good < Math.max(40, all * (sp.wetOnly ? 0.3 : 0.45))) continue;
    if (sp.wet && wet < good * sp.wet) continue;
    l.name = sp.name(landformName('wood', seedHash, w.ox + x, w.oz + z));
    w.landmarks.push(l);
    placed++;
  }
}

/** Every tile inside a wood's outline (a blob round its middle, on global hashes so it reads alike from any county). */
function eachWoodTile(w: World, l: Landmark, f: (i: number, x: number, z: number) => void): void {
  const cx = Math.floor(l.x), cz = Math.floor(l.z);
  const shape = blobScale(w.ox + cx, w.oz + cz, 7311, 0.35);
  const R = Math.ceil(l.r * 1.4);
  for (let dz = -R; dz <= R; dz++) for (let dx = -R; dx <= R; dx++) {
    const x = cx + dx, z = cz + dz;
    if (!inB(x, z)) continue;
    if (Math.hypot(dx, dz) > l.r * (dx || dz ? shape(Math.atan2(dz, dx)) : 1)) continue;
    f(idx(x, z), x, z);
  }
}

/** Which wood (1 + its index in w.landmarks among woods' WOOD_KINDS, 0 none) stands on each tile: worked out once a county. */
const MAPS = new WeakMap<World, { map: Uint8Array; woods: Landmark[] } | null>();
function mapOf(w: World): { map: Uint8Array; woods: Landmark[] } | null {
  let m = MAPS.get(w);
  if (m === undefined) {
    const woods = w.landmarks.filter((l) => l.kind === 'wood');
    m = null;
    if (woods.length) {
      const map = new Uint8Array(N * N);
      woods.forEach((l, k) => eachWoodTile(w, l, (i) => { map[i] = k + 1; }));
      m = { map, woods };
    }
    MAPS.set(w, m);
  }
  return m;
}

/** The kind of wood standing on tile i, or null. */
export function woodAt(w: World, i: number): WoodKind | null {
  const m = mapOf(w);
  if (!m || !m.map[i]) return null;
  return WOOD_KINDS[m.woods[m.map[i] - 1].data?.[0] ?? 0] ?? null;
}

/** What a wood grows on tile (x, z): how many trees (0 where the wood can't grow), and its floor. Null outside every wood. */
export function woodOn(w: World, x: number, z: number): { kind: WoodKind; trees: number; floor: WoodFloor | null } | null {
  const i = idx(x, z);
  const kind = woodAt(w, i);
  if (!kind) return null;
  const sp = WOOD_SPECS[kind];
  if (!woodGround(w, i, sp)) return { kind, trees: 0, floor: null };
  let trees: number;
  if (sp.rows) {
    // a tree farm: a tree on every tile of every other row, the rows running east to west
    trees = z % sp.rows === 0 ? 1 : 0;
  } else {
    const r0 = hash2(x, z, 7321), r1 = hash2(x, z, 7322);
    const wet = w.water[i] >= 0;
    trees = r0 < sp.density * (wet ? 0.75 : 1) ? (r1 < sp.second ? 2 : 1) : 0;
  }
  const floor = !trees && sp.floor && w.water[i] < 0 && hash2(x, z, 7323) < sp.floor[1] ? sp.floor[0] : null;
  return { kind, trees, floor };
}

/** The k-th tree on a tile of a wood: its kind and scale. */
export function woodTree(kind: WoodKind, x: number, z: number, k: number): { tree: TreeKind | WoodTree; s: number } {
  const sp = WOOD_SPECS[kind];
  const sum = sp.trees.reduce((a, [, v]) => a + v, 0);
  let pick = hash2(x, z, 7330 + k) * sum;
  let tree = sp.trees[0][0];
  for (const [t, v] of sp.trees) { pick -= v; if (pick < 0) { tree = t; break; } }
  const s = sp.scale[0] + (sp.scale[1] - sp.scale[0]) * hash2(x, z, 7340 + k);
  return { tree, s };
}

/** A wood's ground colour over tile i, and how much of it (render/mesher.ts), or null. */
export function woodGroundTint(w: World, i: number): [number, number] | null {
  const kind = woodAt(w, i);
  if (!kind || w.water[i] >= 0) return null;
  return WOOD_SPECS[kind].ground ?? null;
}

/** The label under a wood's name, by its kind. */
export function woodLabel(l: Landmark): string {
  return WOOD_SPECS[WOOD_KINDS[l.data?.[0] ?? 0] ?? 'aspen'].label;
}
