/**
 * Mission text edited on the developer's page (/dev/missions, server/missionText.ts), applied to each card
 * as it is made. An edit is the line as the code writes it, slots and all — "Your friend {name} at the
 * Auto Shop…" — and what to say instead; the line the card was built with is matched against the first
 * (each slot matching whatever the game filled in) and the slots are carried into the second. No template
 * changes, and a line the code no longer writes simply never matches.
 *
 * The edits come from the server at start (net/missionText.ts) and are kept in localStorage, so the next
 * start has them before the server answers. Cards already made (in a save) keep the words they were made with.
 */
import type { Mission } from './model';
import { ARCS } from './templates';

interface Rule { re: RegExp; groups: string[]; to: string }

let exact = new Map<string, string>();
let rules: Rule[] = [];
const SLOT = /\{([\w.$]+)\}/g;
const HAS_SLOT = /\{[\w.$]+\}/;
const escRe = (s: string): string => s.replace(/[.*+?^${}()|[\]\\]/g, '\\$&');

/** Take a new set of edits: `from` the line as written, `to` what to say instead. */
export function setTextEdits(list: { from: string; to: string }[]): void {
  exact = new Map();
  rules = [];
  for (const { from, to } of list) {
    if (typeof from !== 'string' || typeof to !== 'string' || from === to) continue;
    if (!HAS_SLOT.test(from)) { exact.set(from, to); continue; }
    const groups: string[] = [];
    let src = '^', last = 0;
    for (const m of from.matchAll(SLOT)) {
      src += escRe(from.slice(last, m.index));
      const g = groups.indexOf(m[1]);
      // the same slot twice must say the same thing both times
      if (g >= 0) src += `\\${g + 1}`;
      else { groups.push(m[1]); src += '([\\s\\S]+?)'; }
      last = m.index! + m[0].length;
    }
    src += `${escRe(from.slice(last))}$`;
    try { rules.push({ re: new RegExp(src), groups, to }); } catch { /* a line that won't compile is skipped */ }
  }
  retitleArcs();
}

/** One line, edited if an edit matches it. */
function retext(s: string): string;
function retext(s: string | undefined): string | undefined;
function retext(s: string | undefined): string | undefined {
  if (!s || (!exact.size && !rules.length)) return s;
  const hit = exact.get(s);
  if (hit !== undefined) return hit;
  for (const r of rules) {
    const m = r.re.exec(s);
    if (!m) continue;
    return r.to.replace(SLOT, (all, l: string) => { const g = r.groups.indexOf(l); return g >= 0 ? m[g + 1] : all; });
  }
  return s;
}

/** Every line of a card just made: its title, why, details, caption, objective lines and reward lines. */
export function retextMission(m: Mission): Mission {
  if (!exact.size && !rules.length) return m;
  m.title = retext(m.title);
  m.why = retext(m.why);
  m.details = retext(m.details);
  m.caption = retext(m.caption);
  for (const o of m.objs) {
    o.label = retext(o.label);
    if (o.t === 'reach' && o.ride) o.ride.label = retext(o.ride.label);
  }
  for (const r of m.reward) if ('line' in r) r.line = retext(r.line);
  return m;
}

/** The arcs' names in the journal, from the names they were written with. */
const arcTitles = new Map<string, string>();
function retitleArcs(): void {
  for (const a of ARCS) {
    if (!arcTitles.has(a.id)) arcTitles.set(a.id, a.title);
    a.title = retext(arcTitles.get(a.id)!);
  }
}
