/**
 * The four rivals (docs/missions.html, Races). Each is a fixed character with a livery and one line of
 * voice, and a car for each tier of race: the first race is winnable in a tuned starter car, the last
 * needs something quick. Their loadout climbs with the tier, up to every part the workshop sells, and
 * the last race each of them runs puts that car up as the prize.
 */
import type { Parts, SlotId } from '../parts';

export interface Rival {
  id: string;
  name: string;
  /** First name, for the card. */
  short: string;
  /** The model they race at tier 1, 2 and 3. */
  models: [string, string, string];
  colour: number;
  accent: number;
  /** One line, said on the card. */
  taunt: string;
  /** The line when they lose. */
  loses: string;
}

export const RIVALS: Rival[] = [
  { id: 'vera', name: 'Vera Quill', short: 'Vera', models: ['tomato', 'zippy', 'pip'], colour: 0xe2412f, accent: 0xf4f2ec, taunt: 'She says your car is a shopping trolley.', loses: 'Vera hands over the keys, and a scowl.' },
  { id: 'otto', name: 'Otto Brisket', short: 'Otto', models: ['sandy', 'sandy', 'sandy'], colour: 0x2f4d7a, accent: 0xf5cf3a, taunt: 'Otto never takes the road if a field will do.', loses: 'Otto laughs it off. The dust hasn’t settled.' },
  { id: 'mags', name: 'Mags Ferrow', short: 'Mags', models: ['pip', 'pip', 'pip'], colour: 0x8e5cc7, accent: 0xf7c5d4, taunt: 'Mags has never lost on her own streets.', loses: 'Mags buys you a coffee. First time for everything.' },
  { id: 'duke', name: 'Duke Harrow', short: 'Duke', models: ['sunny', 'sunny', 'wasabi'], colour: 0x2a2a2e, accent: 0xd9b34a, taunt: 'The Duke races for the pink slip, or not at all.', loses: 'The Duke signs the logbook over without a word.' },
  // the story chains' rivals (docs/storychains.html): a haulier after the spaceport's contract, and a salvage firm after the tiles
  { id: 'pike', name: 'Oswin Pike', short: 'Pike', models: ['mule', 'pip', 'wasabi'], colour: 0x3a5f8a, accent: 0xf2b33b, taunt: 'Pike smiles at you the way a tow truck smiles at a ditch.', loses: 'Keep the trophy. I’ll keep the invoice.' },
  { id: 'greywater', name: 'Greywater Salvage', short: 'Greywater', models: ['mule', 'sandy', 'stomper'], colour: 0x5d6b73, accent: 0xd8d3c4, taunt: 'Nobody has ever seen a Greywater driver’s face.', loses: 'The grey van turns round without a word.' },
];

export const rivalById = (id: string): Rival => RIVALS.find((r) => r.id === id) ?? RIVALS[0];
export const rivalModel = (r: Rival, tier: 1 | 2 | 3): string => r.models[tier - 1];

/** The rival's car for a race of this tier (1 lightly tuned .. 3 full works), in their colours. */
export function rivalParts(r: Rival, tier: 1 | 2 | 3): Parts {
  const t: Partial<Record<SlotId, [number, number]>> = {};
  const set = (s: SlotId, n: number) => { if (n > 0) t[s] = [n, n]; };
  set('paint', 3);
  set('engine', tier);
  set('gearbox', tier - 1);
  set('tyres', tier >= 2 ? 1 : 0);
  set('nitrous', tier >= 2 ? tier - 1 : 0);
  set('brakes', tier >= 3 ? 2 : 0);
  return { t, c: r.colour, a: r.accent, spent: 0 };
}
