/**
 * Trains: the railway's CPU traffic, and the train you drive.
 *
 * One system over every cell in memory, rather than one per island as road traffic is, because a train
 * is always crossing a border. The track is read from each cell's `rails` and stitched into a network
 * at the borders and at the joins (passing loops, rung turnouts). A train is its consist and a trail of
 * track pieces from its front back past its last car; every car is posed from two bogie points on that
 * trail, so it leans into curves and tilts on grades without anything else.
 *
 * Single track, passing loops at stations, one direction per stretch of line. A CPU train never runs
 * onto open line without holding it: a run from where it is to the next station with a loop (or off the
 * edge of the cells in memory), which no opposing train may hold at the same time, and a berth at that
 * station (the platform road or the loop) that nobody else has claimed. Trains meet at loops, which is
 * what makes a station look like one. Behind that, every train watches the track ahead and stops short
 * of anything on it, so nothing ever runs into anything else.
 */
import * as THREE from 'three';
import { N, STEP, RailBit, Under, World, type RailPath, type RailStation, type RailEra } from '../world/tiles';
import { buildCar, disposeCar, type CarMesh } from '../render/trainMeshes';
import { CARS, COUPLING_GAP, CPU_SPEED, SPECIALS, fillSet, freightConsist, passengerConsist, specialFor, type SpecialKind, type TrainSet } from './rollingStock';
import { stationsAlong } from '../world/rail';
import { hashString, mulberry32 } from '../world/rng';
import { NEXT_WORLD } from '../world/nextWorld';
import type { Controls, Impact, VehicleState } from './vehicles';
import type { Beat } from './railBeat';

/** Is this track a rack railway's (world/railPlan.ts planRack)? */
const isRack = (p: RailPath): boolean => p.key.startsWith('rack:');

/** Level crossings with their barriers down, as `cx,cz:tile`: road traffic waits at them. */
export const RAIL_ARMED = new Set<string>();

/** CPU trains kept running over the cells in memory, before termini and junctions add their own. */
const BASE_TRAINS = 3;
const MAX_TRAINS = 8;
/** Seconds a CPU train dwells at a platform. */
const DWELL: [number, number] = [8, 14];
/** Speed into a platform, through a loop and over a turnout, tiles per second. */
const PLATFORM_SPEED = 1.0, LOOP_SPEED = 1.2;
/** The throttle lever: how fast W and S move it (share of full a second), and how near the speed it asks for counts as there (tiles/s). */
const LEVER_RATE = 0.6, HOLD = 0.05;
/** Gap kept behind the train ahead, and in front of a stop, in tiles. */
const HEADWAY = 6;
/** A CPU train that has waited this long for the line gives up and is taken off. */
const GIVE_UP = 120;
/** Tiles of a passing loop's taper either end of its platform (see railPlan). */
const TAPER = 11;
/** Seconds nose to nose with your train before a CPU train backs off to the passing place behind it (twice that facing another). */
const BACK_OFF = 1.5;
/** Tiles of line your train holds ahead of it while it runs, to the next passing place if that is nearer. */
const PLAYER_HOLD = 600;
/** Seconds a train asked to give way (K in your train) keeps to its berth. */
const GIVE_WAY_HOLD = 30;
/** Seconds stood still before a train's place in a jam is looked into (Trains.unjam). */
const JAM_AFTER = 8;
/** A CPU train running toward the edge of the cells in memory is taken off once this far from the player. */
const DESPAWN = 330;
/** Gravity along a grade, as for cars: tiles/s² per step of grade. */
const G = 1.2;

// ---------------------------------------------------------------------------------------------
// the network

export interface Switch {
  /** Where on this track it is, and the direction of travel that can take it. */
  s: number; dir: 1 | -1;
  to: Track; toS: number; toDir: 1 | -1;
  /** Which side the branch leaves toward: +1 left of travel, -1 right. */
  side: 1 | -1;
  key: string;
}

export interface Track {
  w: World;
  p: RailPath;
  key: string;
  switches: Switch[];
  /** Stations whose platform is on this track (main) or who own it as their loop. */
  stations: { st: RailStation; index: number; loop: boolean }[];
  /** Arc lengths of level crossings on this track, and the global tile key of each. */
  crossings: { s: number; key: string }[];
  /** The world revision the crossings were read at. */
  rev: number;
  /** A double-track trunk's other track, the one running the other way (0.8.0, world/railPlan.ts). */
  twin?: Track;
}

/** May a train run along this track heading `dir` at s? Anywhere on a two-way track; on a one-way track (0.8.0 double track) its own way, or in a stretch marked both ways. */
export function allowed(t: Track, s: number, dir: 1 | -1): boolean {
  const ow = t.p.oneWay;
  return !ow || dir === ow || inZone(t, s, s);
}

/** Does [lo, hi] reach into a stretch of a one-way track that is run both ways (a single-lead junction's)? */
function inZone(t: Track, lo: number, hi: number): boolean {
  const z = t.p.twoWay;
  if (!z) return false;
  for (let k = 0; k < z.length; k += 2) if (hi >= z[k] && lo <= z[k + 1]) return true;
  return false;
}

/** Tiles off a train's front past which a junction's two-way stretch, or the crossover into it, ends the line it holds for now (Trains.acquire). */
const ZONE_NEAR = 50;

export interface Loc { t: Track; s: number; dir: 1 | -1 }

/** Position and heading on a track at arc length s, in global tiles. */
export function sampleAt(t: Track, s: number, out: { x: number; y: number; z: number; ang: number }): typeof out {
  const p = t.p, S = p.s, n = S.length;
  const c = Math.min(p.length, Math.max(0, s));
  let lo = 0, hi = n - 1;
  // a first guess from the near-uniform spacing, then a short search either way
  let i = Math.min(n - 2, Math.max(0, Math.floor((c / (p.length || 1)) * (n - 1))));
  while (i > 0 && S[i] > c) i--;
  while (i < n - 2 && S[i + 1] < c) i++;
  lo = i; hi = i + 1;
  const span = S[hi] - S[lo] || 1;
  const f = Math.min(1, Math.max(0, (c - S[lo]) / span));
  const x0 = p.xz[lo * 2], z0 = p.xz[lo * 2 + 1], x1 = p.xz[hi * 2], z1 = p.xz[hi * 2 + 1];
  out.x = t.w.ox + x0 + (x1 - x0) * f;
  out.z = t.w.oz + z0 + (z1 - z0) * f;
  out.y = p.y[lo] + (p.y[hi] - p.y[lo]) * f;
  out.ang = Math.atan2(x1 - x0, z1 - z0);
  return out;
}

class RailNet {
  readonly tracks = new Map<string, Track>();
  private byWorld = new Map<World, Track[]>();
  /** The list of paths each cell's tracks were read from: a new list (track laid, world/railBuild.ts) means reading again. */
  private readFrom = new Map<World, World['rails']>();
  private signature = '';

  /** Rebuild the network when the cells in memory change. Returns true when it changed. */
  sync(worlds: World[]): boolean {
    const sig = worlds.map((w) => `${w.cx},${w.cz}`).sort().join('|');
    if (sig === this.signature) return false;
    this.signature = sig;
    const keep = new Set(worlds);
    for (const w of [...this.byWorld.keys()]) {
      if (keep.has(w)) continue;
      for (const t of this.byWorld.get(w)!) this.tracks.delete(t.key);
      this.byWorld.delete(w);
      this.readFrom.delete(w);
    }
    for (const w of worlds) {
      if (this.byWorld.has(w)) continue;
      this.read(w);
    }
    return true;
  }

  /**
   * Read (or read again) one cell's paths into tracks. A track already here for a path is kept, so trains on it
   * run on; one whose path has gone is dropped (the caller takes its trains off); the stations and switches of
   * the whole cell are worked out afresh, since a new path may join an old one.
   */
  private read(w: World): Track[] {
    const had = new Map<RailPath, Track>();
    for (const t of this.byWorld.get(w) ?? []) { had.set(t.p, t); this.tracks.delete(t.key); }
    const list = w.rails.map((p) => {
      const t = had.get(p) ?? ({ w, p, key: `${w.cx},${w.cz}:${p.id}`, switches: [], stations: [], crossings: [], rev: -1 } as Track);
      // (a path taken up mid-list moves the later ones down: their keys follow their new ids)
      t.key = `${w.cx},${w.cz}:${p.id}`;
      t.switches = []; t.stations = []; t.rev = -1;
      return t;
    });
    this.byWorld.set(w, list);
    this.readFrom.set(w, w.rails);
    for (const t of list) this.tracks.set(t.key, t);
    w.stations.forEach((st, index) => {
      list[st.path]?.stations.push({ st, index, loop: false });
      if (st.loop >= 0) list[st.loop]?.stations.push({ st, index, loop: true });
      // double track: the platform on the second track, a stand-in at that track's arc lengths
      if (st.twin) list[st.twin.path]?.stations.push({ st: { ...st, path: st.twin.path, s0: st.twin.s0, s1: st.twin.s1, loop: -1, twin: undefined, of: st }, index, loop: false });
    });
    // a double-track trunk's two tracks know each other: same line, opposite ways
    for (const t of list) {
      if (!t.p.oneWay || t.p.kind !== 'main') { t.twin = undefined; continue; }
      t.twin = list.find((q) => q !== t && q.p.kind === 'main' && q.p.key === t.p.key && q.p.oneWay === -t.p.oneWay!);
    }
    // a track the player laid beside a line and joined to it at both ends is a passing loop (the user, 3 Nov 2026: let
    // the trains use the loops you build): a passing place with no station, on the dispatcher's books as one
    for (const t of list) {
      const a = t.p.start, b = t.p.end;
      if (t.p.kind === 'loop' || a.kind !== 'join' || b.kind !== 'join' || a.path === undefined || a.path !== b.path || a.path === t.p.id) continue;
      if (t.stations.length) continue;
      const q = list[a.path];
      if (!q || q.p.kind === 'loop' || a.s === undefined || b.s === undefined) continue;
      const st: RailStation = {
        kind: 'halt', name: `${q.p.name} passing loop`, path: q.p.id, s0: Math.min(a.s, b.s), s1: Math.max(a.s, b.s),
        loop: t.p.id, side: 1, era: t.p.era, town: -1, building: null, passing: true,
      };
      q.stations.push({ st, index: -1, loop: false });
      t.stations.push({ st, index: -1, loop: true });
    }
    // switches: every join end is a turnout on the track it joins
    for (const t of list) {
      for (const [end, atStart] of [[t.p.start, true], [t.p.end, false]] as const) {
        if (end.kind !== 'join' || end.path === undefined) continue;
        const q = list[end.path];
        if (!q) continue;
        const dir = (end.dir ?? 1) as 1 | -1;
        const sw: Switch = {
          s: end.s ?? 0, dir: -dir as 1 | -1, to: t, toS: atStart ? 0 : t.p.length, toDir: atStart ? 1 : -1, side: 1,
          key: `${t.key}:${atStart ? 's' : 'e'}`,
        };
        // which way the branch leaves: the side of the branch a few tiles in, relative to travel on q
        const a = sampleAt(q, sw.s, { x: 0, y: 0, z: 0, ang: 0 });
        const b = sampleAt(t, atStart ? Math.min(t.p.length, 6) : Math.max(0, t.p.length - 6), { x: 0, y: 0, z: 0, ang: 0 });
        const fx = Math.sin(a.ang) * sw.dir, fz = Math.cos(a.ang) * sw.dir;
        // left of heading (sin h, cos h) is (cos h, -sin h) in this frame
        sw.side = (b.x - a.x) * fz - (b.z - a.z) * fx > 0 ? 1 : -1;
        q.switches.push(sw);
      }
    }
    return list;
  }

  /** Cells whose paths have changed since they were read (a track laid or taken up): read again. Returns them. */
  changed(): World[] {
    const out: World[] = [];
    for (const [w, rails] of this.readFrom) if (w.rails !== rails && this.byWorld.has(w)) { this.read(w); out.push(w); }
    return out;
  }

  tracksOf(w: World): Track[] { return this.byWorld.get(w) ?? []; }

  /** Where the track runs on past one of its ends, or null at buffers or the edge of the cells in memory. */
  next(t: Track, atEnd: boolean): Loc | null {
    const end = atEnd ? t.p.end : t.p.start;
    if (end.kind === 'join' && end.path !== undefined) {
      const q = this.byWorld.get(t.w)?.[end.path];
      return q ? { t: q, s: end.s ?? 0, dir: (end.dir ?? 1) as 1 | -1 } : null;
    }
    if (end.kind !== 'border' || end.side === undefined) return null;
    const nb = t.w.nbr[end.side];
    if (!nb) return null;
    const back = (end.side + 2) % 4;
    for (const q of this.byWorld.get(nb) ?? []) {
      // (a double-track trunk's two tracks share the line's key and border tile: each meets its own way's)
      if (q.p.key !== t.p.key || q.p.oneWay !== t.p.oneWay) continue;
      if (q.p.start.kind === 'border' && q.p.start.side === back && q.p.start.at === end.at) return { t: q, s: 0, dir: 1 };
      if (q.p.end.kind === 'border' && q.p.end.side === back && q.p.end.at === end.at) return { t: q, s: q.p.length, dir: -1 };
    }
    return null;
  }

  /** Level crossings on a track, read again whenever its cell's tiles have changed (a road built or razed). */
  crossingsOf(t: Track): Track['crossings'] {
    // a road laid or cleared changes the count of roads; growth bumps the revision
    const rev = t.w.revision * 65536 + t.w.roads.length;
    if (t.rev === rev) return t.crossings;
    t.rev = rev;
    t.crossings = [];
    if (t.p.kind === 'loop') return t.crossings;
    let last = -1;
    const p = t.p;
    for (let i = 0; i < p.s.length; i += 2) {
      const tx = Math.floor(p.xz[i * 2]), tz = Math.floor(p.xz[i * 2 + 1]);
      if (tx < 0 || tz < 0 || tx >= N || tz >= N) continue;
      const k = tz * N + tx;
      // a road that flies over on a deck is no crossing at all
      if (k === last || !(t.w.rail[k] & RailBit.Track) || !t.w.road[k] || t.w.deckAxis[k]) continue;
      last = k;
      t.crossings.push({ s: p.s[i], key: `${t.w.cx},${t.w.cz}:${k}` });
    }
    return t.crossings;
  }

  /** The nearest track sample to a global point within `range` tiles, or null. */
  nearest(gx: number, gz: number, range: number, rack = false): { loc: Loc; d: number } | null {
    let best: { loc: Loc; d: number } | null = null;
    for (const t of this.tracks.values()) {
      const p = t.p;
      if (t.p.kind === 'loop') continue;
      // a rack railway takes the cog engine and nothing else, and the cog engine runs nowhere else (0.7.0)
      if (NEXT_WORLD && isRack(p) !== rack) continue;
      const ox = t.w.ox, oz = t.w.oz;
      if (gx < ox - range || gz < oz - range || gx > ox + N + range || gz > oz + N + range) continue;
      for (let i = 0; i < p.s.length; i += 2) {
        if (p.under[i] === Under.Tunnel) continue;
        const d = Math.hypot(ox + p.xz[i * 2] - gx, oz + p.xz[i * 2 + 1] - gz);
        if (d < range && (!best || d < best.d)) best = { loc: { t, s: p.s[i], dir: 1 }, d };
      }
    }
    return best;
  }
}

// ---------------------------------------------------------------------------------------------
// trains

interface Piece { t: Track; a: number; b: number; d: 1 | -1 }

interface Car { id: string; length: number; bogie: number; offset: number; mesh: CarMesh | null }

/** A stretch of track a train holds, in the direction it holds it. */
interface Hold { t: Track; lo: number; hi: number; dir: 1 | -1 }

/** A station's platform road or loop, held by one train at a time. */
interface Berth { t: Track; lo: number; hi: number; station: RailStation; loop: boolean; key: string }

export interface Train {
  id: number;
  name: string;
  era: RailEra;
  freight: boolean;
  express: boolean;
  player: boolean;
  cars: Car[];
  length: number;
  trail: Piece[];
  /** Cars placed back to front: a train reversing runs its trail the other way. */
  flipped: boolean;
  v: number;
  vMax: number;
  accel: number;
  state: 'run' | 'dwell' | 'wait';
  timer: number;
  waited: number;
  /** Turnouts the train has decided on: true takes the branch. */
  choices: Map<string, boolean>;
  run: Hold[];
  berth: Berth | null;
  /** The berth the run it holds leads to. */
  nextBerth: Berth | null;
  /** The run it holds stops where the line passes out of sight rather than at a station: taken again as it goes. */
  open: boolean;
  /** The open run stops short of a junction's two-way stretch still a way off: it is not run past until held. */
  zoneStop: boolean;
  retake: number;
  /** Seconds stood nose to nose with a train coming the other way. */
  faceoff: number;
  /** How far its front was from the player last frame. */
  lastD: number;
  /** Why it is waiting, for the console. */
  why: string;
  /** Tiles to where it must next stand (a calling point, the train ahead, the end of the line it holds). */
  stopIn?: number;
  /** Seconds to the steam engine's next puff. */
  puff?: number;
  /** The station it is stopping at next, and where on which track. */
  stop: { t: Track; s: number; station: RailStation } | null;
  /** Where it is bound, for its card. */
  to: string;
  from: string;
  group: THREE.Group;
  /** What the train ahead is, for a HUD line: the obstacle's name, id and distance, or null. */
  ahead: { name: string; d: number; opposing: boolean; id: number } | null;
  /**
   * The train this one is waiting on, 0 for none: the one in front, the one holding the line it wants, or the one in
   * the berth it needs. Followed train to train, it finds a jam that can never clear on its own (Trains.unjam).
   */
  waitOn: number;
  /** Seconds stood still out on the line (not dwelling at a platform): what every give-up is timed by. */
  stood: number;
  /** Backing up to the passing place behind it to let a train coming the other way by (Trains.backOff). */
  backing: { since: number } | null;
  /** Seconds it keeps to its berth before taking the line again: asked to wait there for your train (Trains.giveWay). */
  holdFor: number;
  /** The player's turnout preference: -1 right, +1 left, 0 straight. */
  prefer: number;
  wheelSpin: number;
  /** The last station the train called at, so it never stops at the same one twice in a row. */
  called: string;
  /** The transit railway that runs it (0.7.0, game/firms.ts railOperator): its firm id and name, in its livery. */
  operator?: { id: string; name: string };
  /** One of the rare unannounced specials (0.7.0, rollingStock.ts SPECIALS): the Christmas, rave or stealth train. */
  special?: SpecialKind;
  /** One of the player's trains with a hired driver at the regulator (docs/crewtrains.html): never taken off the line. */
  crew?: Crew;
  /**
   * Crossed over to a double track's other track to turn round (0.8.0, Trains.crewCross): drawn on the track it left
   * until each part of it has run `CROSS_LEN` tiles past where it turned, sliding over as it goes. Tiles run since.
   */
  crossed?: { gone: number };
  /**
   * A stand-in for a fleet's train on a far run (docs/crewtrains.html, Long haul), put where its owner's clock says it
   * is (Trains.phantom): drawn and stood in the way like any train, never driven, never taken off by the dispatcher.
   */
  phantom?: { what: string };
}

/** Tiles over which a train crossing to a double track's other track slides across (a crossover's length). */
const CROSS_LEN = 14;

/** The same place on a double-track trunk's other track: its arc length at the same share between the same two samples. */
export function twinS(t: Track, s: number): number | null {
  const tw = t.twin;
  if (!tw) return null;
  const S = t.p.s, T = tw.p.s, n = Math.min(S.length, T.length);
  if (n < 2) return null;
  let lo = 0, hi = n - 1;
  while (hi - lo > 1) { const m = (lo + hi) >> 1; if (S[m] <= s) lo = m; else hi = m; }
  const f = Math.min(1, Math.max(0, (s - S[lo]) / ((S[hi] - S[lo]) || 1)));
  return T[lo] + (T[hi] - T[lo]) * f;
}

/** What a crewed train keeps: whose it is, its beat, and how its driver is getting on. */
export interface Crew {
  uid: number;
  driver: string;
  beat: Beat;
  /** The station it last called at, as the county keeps it. */
  at: RailStation | null;
  /** Backed off once for this wait already (a second wait that long turns it round). */
  backed: boolean;
  /** Seconds to its next look ahead for a stop on its beat (Trains.crewAhead). */
  look: number;
  /** Seconds to its next ask of the CPU train it waits on to make way (Trains.makeWay). */
  ask: number;
  /** Long haul (docs/crewtrains.html): the end of its beat it runs on past at its next call there, and the far station's name. */
  runOn?: { end: RailStation; to: string } | null;
  /** Times it has found the other track taken, turning round on double track: past twenty, the trains in the way are asked to make way. */
  crossTries?: number;
  /** Running on past that end toward the edge of what is in memory, where it leaves on its far run (onCrewFar). */
  out?: string;
}

/** The longest a crewed train stands at a platform handing loads in and taking them on. */
const CREW_DWELL_MAX = 20;
/** Seconds a crewed train waits on a CPU train before asking it to make way, and between asks. */
const CREW_ASK = 10;

const tmpA = { x: 0, y: 0, z: 0, ang: 0 }, tmpB = { x: 0, y: 0, z: 0, ang: 0 }, tmpC = { x: 0, y: 0, z: 0, ang: 0 };

/** Walk back `d` tiles from a train's front along its trail. Null when the trail is shorter. (game/tail reads where a train's back is.) */
export function pointBehind(tr: Train, d: number): { t: Track; s: number } | null {
  for (const p of tr.trail) {
    const len = Math.abs(p.b - p.a);
    if (d <= len + 1e-6) return { t: p.t, s: p.b - p.d * d };
    d -= len;
  }
  return null;
}

const NAMES_A = ['Flyer', 'Express', 'Limited', 'Mail', 'Belle', 'Rocket', 'Pullman', 'Special', 'Comet', 'Clipper'];

export class Trains {
  readonly net = new RailNet();
  readonly group = new THREE.Group();
  trains: Train[] = [];
  /** Crossing tiles a train is bearing down on (barriers down), and those it is on right now, as `cx,cz:tile`. */
  readonly armed = RAIL_ARMED;
  readonly occupied = new Set<string>();
  private nextId = 1;
  private spawnTimer = 3;
  private berths = new Map<string, number>();
  worlds: World[] = [];
  /** Why trains have come off the line, and how often a loop was used, for the console. */
  /** Counties kept light for the fleet's work far off (docs/farfleet.html): no CPU train starts in them. */
  quiet = new Set<World>();
  readonly stats = { gaveUp: 0, faceoff: 0, despawned: 0, arrived: 0, edge: 0, loops: 0, meets: 0, backed: 0, unjammed: 0, gaveWay: 0, crewTurns: 0, crewRescued: 0, crewLost: 0, crewCalls: 0 };
  /** A crewed train whose track has gone from memory: the fleet takes it back where it stood (game/railCrew.ts). */
  onCrewLost: ((tr: Train) => void) | null = null;
  /** The track in memory has changed: crewed trains work their beats out again. */
  onNetChanged: (() => void) | null = null;
  /** A crewed train running on past its beat's end has reached the edge of what is in memory: taken off, its far run begins. */
  onCrewFar: ((tr: Train, exit: { cx: number; cz: number; side: number }) => boolean) | null = null;
  /** A crewed train has called at a station on its beat: how many loads it handed in and took on, which lengthens its stop. */
  onCrewCall: ((tr: Train, st: RailStation) => number | void) | null = null;
  /** The last few trains taken off for waiting too long, and why, for the console. */
  readonly gaveUpWhy: string[] = [];
  private noteGaveUp(line: string): void {
    this.gaveUpWhy.push(line);
    if (this.gaveUpWhy.length > 20) this.gaveUpWhy.shift();
  }
  /** How many CPU trains to keep; recomputed from the cells in memory. */
  budget = BASE_TRAINS;
  /** Called with a crossing's key and whether its barriers should be down. */
  onCrossing: ((key: string, armed: boolean) => void) | null = null;
  /** What each signal was last set to, so it is only told when it changes. */
  private signals = new Map<string, boolean>();
  /** Called with a signal's key and whether it shows green. */
  onSignal: ((key: string, clear: boolean) => void) | null = null;
  /** The transit railway that runs a county's passenger trains (game/firms.ts railOperator), if one does. */
  operatorFor: ((cx: number, cz: number) => { id: string; name: string; livery: [number, number]; trains: number } | null) | null = null;
  /** One of a railway's trains has called at a station: its fares. */
  onCall: ((operator: string) => void) | null = null;
  /** The season (render/daynight.ts), for the Christmas train: it runs only in winter. */
  season: (() => string) | null = null;
  /** How dark it was last frame, and the clock the specials' lights run on. */
  private night = 0;
  private clock = 0;
  /** Specials put on the line this session, by kind, for the console and the gate. */
  readonly specials: Record<SpecialKind, number> = { christmas: 0, rave: 0, stealth: 0 };

  constructor(parent: THREE.Object3D) { parent.add(this.group); }

  dispose(): void {
    for (const t of [...this.trains]) this.remove(t);
    this.group.removeFromParent();
  }

  /** The cells in memory have changed: rebuild the network, and drop trains whose track has gone. */
  setWorlds(worlds: World[]): void {
    this.worlds = worlds;
    if (!this.net.sync(worlds)) return;
    this.afterNetChange();
  }

  /** Track laid or taken up in a cell in memory (world/railBuild.ts): the network reads that cell again. */
  railsChanged(): void {
    if (this.net.changed().length) this.afterNetChange();
  }

  /** Trains whose track has gone come off (the player's is trimmed), and the CPU budget is counted again. */
  private afterNetChange(): void {
    for (const tr of [...this.trains]) {
      if (tr.trail.some((p) => !this.net.tracks.has(p.t.key) || this.net.tracks.get(p.t.key) !== p.t)) {
        if (tr.player) this.rescue(tr);
        else { if (tr.crew) { this.stats.crewLost++; this.onCrewLost?.(tr); } this.remove(tr); }
        continue;
      }
      // (a crewed train's beat is worked out again below, whatever went)
      if (tr.crew) continue;
      // a station taken down (world/railBuild.ts removeStation): a CPU train berthed at it, or running to it, comes off
      // (a passing loop the player laid is no station: it goes with its track, above)
      const gone = (b: Berth | null) => !!b && !b.station.passing && !b.t.w.stations.includes(b.station.of ?? b.station);
      if (!tr.player && (gone(tr.berth) || gone(tr.nextBerth))) this.remove(tr);
    }

    const worlds = this.worlds;
    let extra = 0;
    for (const w of worlds) {
      extra += w.stations.filter((s) => s.kind === 'terminus').length;
      if (w.rails.some((p) => p.kind === 'stub' && !p.key.startsWith('rack:'))) extra++;
    }
    this.budget = Math.min(MAX_TRAINS, BASE_TRAINS + extra);
    this.onNetChanged?.();
  }

  /** A player's train whose cell has gone: trim its trail to what remains. */
  private rescue(tr: Train): void {
    const i = tr.trail.findIndex((p) => !this.net.tracks.has(p.t.key));
    tr.trail.length = Math.max(1, i);
    if (!this.net.tracks.has(tr.trail[0].t.key)) tr.trail = [];
  }

  // ---- building trains ----

  private consist(ids: string[], seed: number, paint?: [number, number]): { cars: Car[]; length: number } {
    const cars: Car[] = [];
    let off = 0;
    ids.forEach((id, k) => {
      const spec = CARS[id];
      if (!spec) return;
      if (k) off += COUPLING_GAP;
      const mesh = buildCar(id, seed + k * 7, paint);
      cars.push({ id, length: spec.length, bogie: mesh.bogie, offset: off + spec.length / 2, mesh });
      off += spec.length;
    });
    return { cars, length: off };
  }

  private make(ids: string[], era: RailEra, freight: boolean, player: boolean, seed: number, paint?: [number, number]): Train {
    const { cars, length } = this.consist(ids, seed, paint);
    const group = new THREE.Group();
    for (const c of cars) if (c.mesh) group.add(c.mesh.group);
    this.group.add(group);
    const [vMax, accel] = CPU_SPEED[era][freight ? 'freight' : 'passenger'];
    const tr: Train = {
      id: this.nextId++, name: '', era, freight, express: era === 'modern' && !freight, player, cars, length,
      trail: [], flipped: false, v: 0, vMax, accel, state: 'run', timer: 0, waited: 0, choices: new Map(), run: [], berth: null, nextBerth: null, open: false, zoneStop: false, retake: 0, faceoff: 0, lastD: Infinity, why: '',
      stop: null, to: '', from: '', group, ahead: null, prefer: 0, wheelSpin: 0, called: '', waitOn: 0, stood: 0, backing: null, holdFor: 0,
    };
    this.trains.push(tr);
    return tr;
  }

  remove(tr: Train): void {
    this.release(tr);
    for (const b of [tr.berth, tr.nextBerth]) if (b && this.berths.get(b.key) === tr.id) this.berths.delete(b.key);
    tr.berth = null;
    tr.nextBerth = null;
    for (const c of tr.cars) if (c.mesh) disposeCar(c.mesh);
    tr.group.removeFromParent();
    this.trains = this.trains.filter((t) => t !== tr);
  }

  /** Lay a train's trail back from a front position, so every car has track under it where track exists. */
  private layTrail(tr: Train, front: Loc): void {
    // walk backwards from the front: each piece runs from nearer the front (a) to further back (b)
    const back: Piece[] = [];
    let t = front.t, dir = (-front.dir) as 1 | -1, left = tr.length + 1;
    back.push({ t, a: front.s, b: front.s, d: dir });
    for (let guard = 0; guard < 40 && left > 0; guard++) {
      const p = back[back.length - 1];
      const end = dir > 0 ? t.p.length : 0;
      const room = Math.abs(end - p.b);
      if (room >= left) { p.b += dir * left; left = 0; break; }
      p.b = end; left -= room;
      const nx = this.net.next(t, dir > 0);
      if (!nx) break;
      t = nx.t; dir = nx.dir;
      back.push({ t, a: nx.s, b: nx.s, d: dir });
    }
    // the same pieces travelled forward, front piece first
    tr.trail = back.map((p) => ({ t: p.t, a: p.b, b: p.a, d: (-p.d) as 1 | -1 }));
  }

  /** Put a CPU train on the line, from a station platform or coming in from the edge of the cells in memory. */
  spawn(kind: 'passenger' | 'freight' | null = null, player?: { x: number; z: number }, force?: SpecialKind): Train | null {
    // (none in a county kept light for the fleet's work far off: docs/farfleet.html)
    const tracks = [...this.net.tracks.values()].filter((t) => t.p.kind !== 'loop' && !this.quiet.has(t.w));
    if (!tracks.length) return null;
    const rng = mulberry32((Math.random() * 2 ** 31) | 0);
    // candidates: every free berth at a station, and every track end that runs off the cells in memory
    const cands: { front: Loc; weight: number; station: RailStation | null; berth: Berth | null }[] = [];
    for (const t of tracks) {
      for (const [atEnd, end] of [[false, t.p.start], [true, t.p.end]] as const) {
        if (end.kind !== 'border' || end.side === undefined || t.w.nbr[end.side]) continue;
        // coming in over that border, heading inward (on double track, only onto the track that runs that way)
        const front: Loc = { t, s: atEnd ? t.p.length - 1 : 1, dir: atEnd ? -1 : 1 };
        if (!allowed(t, front.s, front.dir)) continue;
        // only an edge near enough that the train will come into sight, not one it would be taken off at
        if (player) { sampleAt(t, front.s, tmpA); if (Math.hypot(tmpA.x - player.x, tmpA.z - player.z) > DESPAWN + 200) continue; }
        cands.push({ front, weight: 2, station: null, berth: null });
      }
      for (const { st } of t.stations) {
        if (st.kind === 'halt' || t.p.id !== st.path) continue;
        for (const dir of [1, -1] as const) {
          if (!allowed(t, (st.s0 + st.s1) / 2, dir)) continue;
          const berth = this.freeBerth(t, st, dir);
          if (!berth) continue;
          const s = dir > 0 ? berth.hi - 2 : berth.lo + 2;
          const w = st.kind === 'terminus' ? 3 : st.kind === 'cityStation' ? 2 : 1;
          cands.push({ front: { t: berth.t, s: berth.loop ? (dir > 0 ? berth.t.p.length - TAPER - 1 : TAPER + 1) : s, dir }, weight: w, station: st, berth });
        }
      }
    }
    // not in view of the player
    const far = cands.filter((c) => {
      if (!player) return true;
      sampleAt(c.front.t, c.front.s, tmpA);
      return Math.hypot(tmpA.x - player.x, tmpA.z - player.z) > 90;
    });
    if (!far.length) return null;
    for (let attempt = 0; attempt < 4; attempt++) {
      let total = 0;
      for (const c of far) total += c.weight;
      let r = rng() * total;
      const c = far.find((x) => (r -= x.weight) <= 0) ?? far[0];
      // now and then (0.7.0) one of the rare specials instead, unannounced: never on a rack railway
      const special = force ?? (NEXT_WORLD && !kind && !isRack(c.front.t.p) ? specialFor(rng(), rng(), this.season?.() ?? 'summer', this.night) : null);
      const era = special ? SPECIALS[special].era : c.front.t.p.era;
      const freight = special ? special === 'stealth' : kind ? kind === 'freight' : rng() < 0.5;
      // nothing already on the stretch it would appear on
      if (this.occupiedNear(c.front, 40)) continue;
      const ids = special ? SPECIALS[special].cars : freight ? freightConsist(era, rng, producersOf(c.front.t.w)) : passengerConsist(era, rng);
      // a county with a transit railway: its passenger trains are the railway's, in its livery, as many as it runs
      const op = freight || special ? null : this.operatorFor?.(c.front.t.w.cx, c.front.t.w.cz) ?? null;
      const runs = op && this.trains.filter((t) => t.operator?.id === op.id).length < op.trains ? op : null;
      const tr = this.make(ids, era, freight, false, (rng() * 1e6) | 0, runs?.livery);
      if (runs) tr.operator = { id: runs.id, name: runs.name };
      if (special) tr.special = special;
      this.layTrail(tr, c.front);
      if (!tr.trail.length) { this.remove(tr); continue; }
      // never onto single line someone is already on or holding against it, up to the next passing place
      // (3 Nov 2026: new trains were put on a long stretch from both ends at once, to meet in the middle)
      if (this.sectionBusy(tr)) { this.remove(tr); continue; }
      if (c.berth) {
        tr.berth = c.berth;
        this.berths.set(c.berth.key, tr.id);
        tr.state = 'dwell';
        tr.timer = DWELL[0] + rng() * (DWELL[1] - DWELL[0]);
        tr.called = c.station!.name;
        tr.from = c.station!.name;
      } else {
        tr.from = c.front.t.w.name;
        // coming in off the edge: only onto line it can have
        if (!this.acquire(tr)) { this.remove(tr); continue; }
      }
      this.name(tr, rng);
      if (special) { tr.name = SPECIALS[special].name; this.specials[special]++; }
      return tr;
    }
    return null;
  }

  /**
   * One CPU train of a set (its own engine and consist) put on the line nearest `near`, a little way back from it,
   * heading its way, to run on as any CPU train does: the trailer shoot's one-shot-per-vehicle series (the user,
   * 7 Nov 2026). A rack set only on a rack railway, any other never on one. Null when no line in memory will take it.
   */
  /** Why the last spawnFilm gave up (spots near, how many each check turned away). */
  filmWhy = '';
  spawnFilm(set: TrainSet, near: { x: number; z: number }, back = 60): Train | null {
    const rng = mulberry32((Math.random() * 2 ** 31) | 0);
    const spots: { t: Track; s: number; d: number }[] = [];
    for (const t of this.net.tracks.values()) {
      if (t.p.kind === 'loop' || this.quiet.has(t.w) || isRack(t.p) !== !!set.rack) continue;
      for (let s = 2; s < t.p.length - 2; s += 6) {
        sampleAt(t, s, tmpA);
        const d = Math.hypot(tmpA.x - near.x, tmpA.z - near.z);
        if (d < 400) spots.push({ t, s, d });
      }
    }
    spots.sort((a, b) => a.d - b.d);
    const why = { spots: spots.length, way: 0, occupied: 0, busy: 0 };
    for (const sp of spots.slice(0, 40)) {
      for (const dir of (rng() < 0.5 ? [1, -1] : [-1, 1]) as (1 | -1)[]) {
        const s = sp.s - dir * back;
        if (s < 2 || s > sp.t.p.length - 2 || !allowed(sp.t, s, dir)) { why.way++; continue; }
        const front: Loc = { t: sp.t, s, dir };
        if (this.occupiedNear(front, 60)) { why.occupied++; continue; }
        const tr = this.make(set.freight ? fillSet(set, rng, producersOf(sp.t.w)) : set.cars, set.era, set.freight, false, (rng() * 1e6) | 0);
        this.layTrail(tr, front);
        if (!tr.trail.length || this.sectionBusy(tr) || !this.acquire(tr)) { why.busy++; this.remove(tr); continue; }
        tr.from = sp.t.w.name;
        this.name(tr, rng);
        tr.name = set.name;
        return tr;
      }
    }
    this.filmWhy = JSON.stringify(why);
    return null;
  }

  private name(tr: Train, rng: () => number): void {
    const line = tr.trail[0].t.p.name;
    const dest = this.destination(tr);
    tr.to = dest;
    tr.name = tr.freight
      ? `Freight, ${tr.cars.filter((c) => CARS[c.id]?.role === 'wagon').length} wagons`
      : tr.operator ? `${tr.operator.name} · ${line.split(' ')[0]} service`
        : `The ${line.split(' ')[0]} ${NAMES_A[Math.floor(rng() * NAMES_A.length)]}`;
  }

  /** Where a train is bound: the last calling point ahead in memory, or up the line past it. */
  private destination(tr: Train): string {
    let name = '';
    const seen = new Set<string>();
    let lastLoc: Loc | null = null;
    this.walk({ t: tr.trail[0].t, s: tr.trail[0].b, dir: tr.trail[0].d }, 2500, tr, (t, s0, s1, dist) => {
      lastLoc = { t, s: s1, dir: s1 >= s0 ? 1 : -1 };
      for (const { st, loop } of t.stations) {
        if (loop || seen.has(st.name) || !this.callsAt(tr, st)) continue;
        const lo = Math.min(s0, s1), hi = Math.max(s0, s1);
        if (st.s1 < lo || st.s0 > hi || dist < 1) continue;
        seen.add(st.name);
        name = st.name;
      }
      return false;
    });
    if (name) return name;
    const end = lastLoc as Loc | null;
    if (end) {
      const e = end.dir > 0 ? end.t.p.end : end.t.p.start;
      if (e.kind === 'border' && e.side !== undefined) {
        const up = stationsAlong(hashString(end.t.w.seed), end.t.w.cx, end.t.w.cz, e.side, 10).filter((st) => tr.freight ? st.kind === 'goodsYard' || st.kind === 'harbourDepot' : st.kind !== 'goodsYard' && st.kind !== 'harbourDepot');
        if (up.length) return up[Math.min(up.length - 1, 1 + Math.floor(Math.random() * 2))].name;
      }
    }
    return tr.freight ? 'the yards' : 'up the line';
  }

  callsAt(tr: Train, st: RailStation): boolean {
    if (tr.player || st.passing) return false;
    // a crewed train calls at the stations of its beat, and only those (its ends always)
    if (tr.crew) { const real = st.of ?? st; return tr.crew.beat.stops.some((b) => b.st === real); }
    if (tr.freight) return st.kind === 'goodsYard' || st.kind === 'harbourDepot';
    if (st.kind === 'goodsYard' || st.kind === 'harbourDepot') return false;
    return !tr.express || st.kind === 'terminus' || st.kind === 'cityStation';
  }

  // ---- walking the line ----

  /** Would this train take this turnout? CPU trains decide once and remember; the player chooses. */
  private takes(tr: Train, sw: Switch, on?: Track): boolean {
    if (tr.player) return tr.prefer !== 0 && tr.prefer === sw.side;
    // double track (0.8.0): never onto a one-way track against its way; and off one, against its way, where its
    // two-way stretch ends at this turnout (a single-lead junction's, crossed over to: the rung's turnout is taken)
    if (!allowed(sw.to, sw.toS, sw.toDir)) return false;
    if (on && !allowed(on, sw.s + sw.dir * 0.5, sw.dir)) return true;
    const have = tr.choices.get(sw.key);
    if (have !== undefined) return have;
    // a crewed train keeps to its beat: the turnouts on the way between its ends as the beat has them, straight on otherwise
    if (tr.crew && sw.to.p.kind !== 'loop' && !sw.to.stations.some((s) => s.loop)) return tr.crew.beat.choices.get(sw.key) ?? false;
    let take: boolean;
    // a passing loop (a station's, or one the player laid) is only taken when a berth on it is claimed
    if (sw.to.p.kind === 'loop' || sw.to.stations.some((s) => s.loop)) take = false;
    else take = Math.random() < 0.35;
    tr.choices.set(sw.key, take);
    return take;
  }

  /**
   * Follow the line forward from `loc` for up to `max` tiles as this train would, calling `visit` with
   * every stretch (track, from s, to s, distance at its start). `visit` returns true to stop.
   */
  walk(loc: Loc, max: number, tr: Train, visit: (t: Track, s0: number, s1: number, dist: number) => boolean): Loc | null {
    let { t, s, dir } = loc;
    let dist = 0;
    for (let guard = 0; guard < 60 && dist < max; guard++) {
      const end = dir > 0 ? t.p.length : 0;
      let stopAt = end, branch: Switch | null = null;
      for (const sw of t.switches) {
        if (sw.dir !== dir) continue;
        const ahead = (sw.s - s) * dir;
        if (ahead <= 1e-6 || ahead >= Math.abs(stopAt - s)) continue;
        if (!this.takes(tr, sw, t)) continue;
        stopAt = sw.s; branch = sw;
      }
      const room = Math.min(Math.abs(stopAt - s), max - dist);
      const s1 = s + dir * room;
      if (visit(t, s, s1, dist)) return { t, s: s1, dir };
      dist += room;
      if (dist >= max) return { t, s: s1, dir };
      if (branch) { t = branch.to; s = branch.toS; dir = branch.toDir; continue; }
      const nx = this.net.next(t, dir > 0);
      if (!nx) return null;
      t = nx.t; s = nx.s; dir = nx.dir;
    }
    return { t, s, dir };
  }

  /**
   * How much the line bends over the next L tiles ahead of a train's front (radians of heading change, summed a tile
   * at a time): a film shot wants a near-straight run ahead, no sharp turns (the user, 7 Nov 2026). Null if no front.
   */
  turnAhead(tr: Train, L: number): number | null {
    const f = tr.trail[0];
    if (!f) return null;
    const at = { x: 0, y: 0, z: 0, ang: 0 };
    let last: number | null = null, turn = 0;
    this.walk({ t: f.t, s: f.b, dir: f.d }, L, tr, (t, s0, s1) => {
      const n = Math.max(1, Math.ceil(Math.abs(s1 - s0)));
      for (let k = 0; k <= n; k++) {
        sampleAt(t, s0 + ((s1 - s0) * k) / n, at);
        const a = at.ang + (s1 < s0 ? Math.PI : 0);
        if (last !== null) turn += Math.abs(Math.atan2(Math.sin(a - last), Math.cos(a - last)));
        last = a;
      }
      return false;
    });
    return turn;
  }

  /** Is any train on the track within `range` tiles either side of a position? */
  private occupiedNear(loc: Loc, range: number): boolean {
    for (const tr of this.trains) {
      for (const p of tr.trail) {
        if (p.t !== loc.t) continue;
        const lo = Math.min(p.a, p.b) - range, hi = Math.max(p.a, p.b) + range;
        if (loc.s >= lo && loc.s <= hi) return true;
      }
    }
    return false;
  }

  /**
   * Whether a train fits a berth heading `dir`: stood where it stops in it (at the platform if it calls
   * there, else a tile or two short of the far turnout), its last car must be clear of the turnout it
   * came in over, or its tail fouls the single line an opposing train is waiting to use.
   */
  private fits(tr: Train, b: Berth, dir: 1 | -1): boolean {
    const st = b.station;
    const calls = this.callsAt(tr, st) && st.name !== tr.called;
    let room: number;
    if (b.loop) room = calls ? b.t.p.length - TAPER - 1 : b.t.p.length - 2;
    else if (calls) room = dir > 0 ? st.s1 - 1 - b.lo : b.hi - (st.s0 + 1);
    else room = b.hi - b.lo - 2;
    return tr.length + 1 <= room;
  }

  /** A station's berth for a train heading `dir` on its main track: the platform road if free, else the loop. */
  private freeBerth(main: Track, st: RailStation, dir: 1 | -1, forTrain = 0, tr: Train | null = null): Berth | null {
    const loopTrack = st.loop >= 0 ? this.net.tracksOf(main.w)[st.loop] : null;
    const [zoneLo, zoneHi] = this.zoneOf(main, st);
    const { mainKey, loopKey } = this.berthKeys(main, st);
    const free = (k: string) => { const h = this.berths.get(k); return h === undefined || h === forTrain; };
    // trains keep left of each other: the platform road for one way, the loop for the other when both are free
    const pref = dir > 0 ? ['main', 'loop'] : ['loop', 'main'];
    for (const which of pref) {
      const b: Berth | null = which === 'main' ? { t: main, lo: zoneLo, hi: zoneHi, station: st, loop: false, key: mainKey }
        : loopTrack ? { t: loopTrack, lo: 0, hi: loopTrack.p.length, station: st, loop: true, key: loopKey } : null;
      if (b && free(b.key) && (!tr || this.fits(tr, b, dir))) return b;
    }
    return null;
  }

  /** Where on the main track a station's loop leaves and rejoins it (either way round, for a loop the player laid), or its platform. */
  private zoneOf(main: Track, st: RailStation): [number, number] {
    const loopTrack = st.loop >= 0 ? this.net.tracksOf(main.w)[st.loop] : null;
    if (!loopTrack) return [st.s0, st.s1];
    const a = loopTrack.p.start.s ?? st.s0, b = loopTrack.p.end.s ?? st.s1;
    return [Math.min(a, b), Math.max(a, b)];
  }

  /** A station's two berths' keys; a passing place the player laid is known by its loop track, having no place in the stations list. */
  private berthKeys(main: Track, st: RailStation): { mainKey: string; loopKey: string } {
    const idx = main.w.stations.indexOf(st);
    // (a platform on a double track's second track is its station's, with a berth of its own)
    const id = idx >= 0 ? String(idx) : st.of ? `${main.w.stations.indexOf(st.of)}b` : `p${st.loop}`;
    return { mainKey: `${main.w.cx},${main.w.cz}:${id}:main`, loopKey: `${main.w.cx},${main.w.cz}:${id}:loop` };
  }

  /** The train holding a berth at this station, if one does (whoever a train waits on for "no free berth ahead"). */
  private berthHolder(main: Track, st: RailStation): number {
    const { mainKey, loopKey } = this.berthKeys(main, st);
    return this.berths.get(mainKey) ?? this.berths.get(loopKey) ?? 0;
  }

  /** Could this train fit either of a station's berths at all, busy or not? If not, it is no place to pass. */
  private anyFits(tr: Train, main: Track, st: RailStation, dir: 1 | -1): boolean {
    const loopTrack = st.loop >= 0 ? this.net.tracksOf(main.w)[st.loop] : null;
    const [zoneLo, zoneHi] = this.zoneOf(main, st);
    if (this.fits(tr, { t: main, lo: zoneLo, hi: zoneHi, station: st, loop: false, key: '' }, dir)) return true;
    return !!loopTrack && this.fits(tr, { t: loopTrack, lo: 0, hi: loopTrack.p.length, station: st, loop: true, key: '' }, dir);
  }

  // ---- holding the line ----

  private release(tr: Train): void { tr.run = []; }

  /** The train whose run held the other way, or who stands on the stretch facing us, clashes with it: its id, or 0. */
  private clashes(tr: Train, h: Hold): number {
    for (const o of this.trains) {
      if (o === tr) continue;
      for (const r of o.run) {
        if (r.t !== h.t || r.dir === h.dir) continue;
        if (r.hi >= h.lo && r.lo <= h.hi && this.opposes(o, h.t, Math.max(r.lo, h.lo), Math.min(r.hi, h.hi))) return o.id;
      }
      for (const p of o.trail) {
        if (p.t !== h.t || p.d === h.dir) continue;
        const lo = Math.max(Math.min(p.a, p.b), h.lo), hi = Math.min(Math.max(p.a, p.b), h.hi);
        if (lo <= hi && this.opposes(o, h.t, lo, hi)) return o.id;
      }
    }
    return 0;
  }

  /**
   * Does a train going the other way over [lo, hi] of this track stand against us? Always on two-way track. On a one-way
   * track (0.8.0 double track) never, outside a junction's two-way stretch: no CPU train runs against its way there, and
   * the way it runs is never in conflict with itself; only your train, reversed down it, is in the way.
   */
  private opposes(o: Train, t: Track, lo: number, hi: number): boolean {
    return !t.p.oneWay || o.player || inZone(t, lo, hi);
  }

  private clashWith(tr: Train, h: Hold): string {
    for (const o of this.trains) {
      if (o === tr) continue;
      if (o.run.some((r) => r.t === h.t && r.dir !== h.dir && r.hi >= h.lo && r.lo <= h.hi)) return `#${o.id} (run)`;
      if (o.trail.some((p) => p.t === h.t && p.d !== h.dir && Math.max(p.a, p.b) >= h.lo && Math.min(p.a, p.b) <= h.hi)) return `#${o.id} (standing)`;
    }
    return '?';
  }

  /** How long a train waits for the line: a long while in sight, not long where nobody can see it give up. */
  private patience(tr: Train): number {
    if (!this.focus || !tr.trail.length) return GIVE_UP;
    sampleAt(tr.trail[0].t, tr.trail[0].b, tmpB);
    return Math.hypot(tmpB.x - this.focus.x, tmpB.z - this.focus.z) > 160 ? 25 : GIVE_UP;
  }

  /** Where the player is (or the title camera looks), which decides what is out of sight. */
  private focus: { x: number; z: number } | null = null;
  /** Seconds to the next look for jams (unjam). */
  private jamT = 1;

  /**
   * Take the line ahead: every stretch from the front to the next station with a loop (claiming a berth
   * there) or to the edge of the cells in memory. All or nothing. A station whose loop is too short for
   * this train is no place to meet another: the run is held on through it to the next one.
   */
  private acquire(tr: Train): boolean {
    const front = tr.trail[0];
    const holds: Hold[] = [];
    let berth: Berth | null = null;
    // the train in the berth it can't have, and the one going its way ahead of it that it follows instead
    let blocked = 0, follows = 0;
    // the first stretch starts just behind the front, so a train pulling out holds its own platform end
    const start: Loc = { t: front.t, s: front.b, dir: front.d };
    let open = false, zoneCut = false;
    let lastT: Track | null = null, lastDir: 1 | -1 = 1;
    // (the whole way to the next passing place, in sight or not: the user, 3 Nov 2026 — held only to the edge of
    // sight, two trains coming in from out of it each held their half and met nose to nose in view)
    const reached = this.walk(start, 3000, tr, (t, s0, s1, dist) => {
      lastT = t;
      const dir = (s1 >= s0 ? 1 : -1) as 1 | -1;
      lastDir = dir;
      const lo = Math.min(s0, s1), hi = Math.max(s0, s1);
      // a train going the same way on this stretch: it is followed, and the berth past it is its to take first
      // (3 Nov 2026: followers took both berths at the station ahead, and the train in front could never get in)
      let near = Infinity, nearS = 0;
      for (const o of this.trains) {
        if (o === tr) continue;
        for (const p of o.trail) {
          if (p.t !== t || p.d !== dir) continue;
          const plo = Math.min(p.a, p.b), phi = Math.max(p.a, p.b);
          if (phi < lo || plo > hi) continue;
          const at = dir > 0 ? Math.max(lo, plo) : Math.min(hi, phi);
          const d = Math.abs(at - s0);
          if (d < near) { near = d; nearS = at; follows = o.id; }
        }
      }
      // a station with a loop ahead (short of any train in front) ends the run
      for (const { st, loop } of t.stations) {
        if (loop || st.loop < 0 || (tr.berth && tr.berth.station === st)) continue;
        const loopTrack = this.net.tracksOf(t.w)[st.loop];
        if (!loopTrack) continue;
        const [zLo, zHi] = this.zoneOf(t, st);
        if (zHi < lo || zLo > hi) continue;
        const entry = dir > 0 ? zLo : zHi;
        if ((entry - s0) * dir < 0) continue;   // we are already past its entry
        if (Math.abs(entry - s0) > near) continue;   // the train in front gets there first
        if (!this.anyFits(tr, t, st, dir)) continue;
        const b = this.freeBerth(t, st, dir, tr.id, tr);
        if (!b) { blocked = this.berthHolder(t, st) || -1; follows = 0; return true; }
        holds.push({ t, lo: Math.min(s0, entry), hi: Math.max(s0, entry), dir });
        berth = b;
        follows = 0;
        return true;
      }
      // double track: a junction's two-way stretch (or the crossover into it) still a way off is held only once near,
      // so a train far up the line never keeps the trains crossing over to the rung waiting
      const cut = this.zoneAhead(t, s0, s1, dist);
      if (cut !== null && Math.abs(cut - s0) < near) {
        holds.push({ t, lo: Math.min(s0, cut), hi: Math.max(s0, cut), dir });
        open = true; zoneCut = true;
        return true;
      }
      if (near < Infinity) {
        // up to the train in front, taken again as it goes (an open run)
        holds.push({ t, lo: Math.min(s0, nearS), hi: Math.max(s0, nearS), dir });
        open = true;
        return true;
      }
      holds.push({ t, lo, hi, dir });
      return false;
    });
    // the line runs on over a border into a cell not in memory yet: hold to the edge and take the
    // rest as it arrives, rather than stopping at the edge for good once the cell beyond is built
    const lt = lastT as Track | null;
    if (!reached && !berth && lt && (lastDir > 0 ? lt.p.end : lt.p.start).kind === 'border') open = true;
    if (blocked) { tr.why = 'no free berth ahead'; tr.waitOn = Math.max(0, blocked); return false; }
    for (const h of holds) {
      const by = this.clashes(tr, h);
      if (!by) continue;
      // double track: stood a while at a crossover over to a rung held against it, a train gives the rung up and runs
      // on along its own track, rather than keeping everyone behind it on the main line waiting too
      if (!tr.player && tr.stood > 4 && this.dropLead(tr)) return this.acquire(tr);
      tr.why = `line held by ${this.clashWith(tr, h)}`; tr.waitOn = by; return false;
    }
    tr.why = '';
    tr.waitOn = follows;
    tr.run = holds;
    tr.open = open && !berth;
    tr.zoneStop = zoneCut && !berth;
    if (berth) {
      const b = berth as Berth;
      this.berths.set(b.key, tr.id);
      tr.nextBerth = b;
      // take the loop's turnout if that is the berth
      if (b.loop) {
        for (const t of this.net.tracksOf(b.t.w)) for (const sw of t.switches) if (sw.to === b.t) tr.choices.set(sw.key, true);
      }
    }
    return true;
  }

  // ---- making way (the user, 3 Nov 2026: trains coming the other way used to sit nose to nose until one vanished) ----

  /** Is there a passing place (a station's loop, or one the player laid) on this stretch, met heading `dir` from s0? Its entry, or null. */
  private passingOn(tr: Train, t: Track, s0: number, s1: number): { st: RailStation; entry: number } | null {
    const dir = (s1 >= s0 ? 1 : -1) as 1 | -1, lo = Math.min(s0, s1), hi = Math.max(s0, s1);
    let best: { st: RailStation; entry: number } | null = null;
    for (const { st, loop } of t.stations) {
      if (loop || st.loop < 0) continue;
      const [zLo, zHi] = this.zoneOf(t, st);
      if (zHi < lo || zLo > hi) continue;
      const entry = dir > 0 ? zLo : zHi;
      if ((entry - s0) * dir < 0 || !this.anyFits(tr, t, st, dir)) continue;
      if (!best || Math.abs(entry - s0) < Math.abs(best.entry - s0)) best = { st, entry };
    }
    return best;
  }

  /**
   * Where on this stretch (from s0 toward s1, `dist` tiles on from the front) a junction's two-way stretch begins, or
   * the crossover that leads into one, when that is more than ZONE_NEAR tiles off: the line is held only to there for now.
   */
  private zoneAhead(t: Track, s0: number, s1: number, dist: number): number | null {
    if (t.p.kind === 'stub' && t.p.oneWay) return dist > ZONE_NEAR ? s0 : null;
    const z = t.p.twoWay;
    if (!z) return null;
    const dir = s1 >= s0 ? 1 : -1, lo = Math.min(s0, s1), hi = Math.max(s0, s1);
    let best: number | null = null;
    for (let k = 0; k < z.length; k += 2) {
      const entry = dir > 0 ? z[k] : z[k + 1];
      if (entry < lo || entry > hi || (entry - s0) * dir < 0 || dist + Math.abs(entry - s0) <= ZONE_NEAR) continue;
      // (held to half a tile short of it, so the hold doesn't touch the stretch and keep the trains crossing over out)
      const stop = (entry - dir * 0.5 - s0) * dir > 0 ? entry - dir * 0.5 : s0;
      if (best === null || Math.abs(stop - s0) < Math.abs(best - s0)) best = stop;
    }
    return best;
  }

  /** Forget a decision to take a junction's crossover not yet reached (zoneAhead): true when there was one. */
  private dropLead(tr: Train): boolean {
    const f = tr.trail[0];
    if (!f || (f.t.p.kind === 'stub' && f.t.p.oneWay)) return false;
    let dropped = false;
    for (const t of this.net.tracks.values()) {
      for (const sw of t.switches) {
        if (sw.to.p.kind !== 'stub' || !sw.to.p.oneWay || tr.choices.get(sw.key) !== true) continue;
        tr.choices.set(sw.key, false);
        dropped = true;
      }
    }
    return dropped;
  }

  /** Tiles back from a CPU train's tail to the nearest passing place behind it with a berth free, or null (none within reach). */
  private wayBack(tr: Train): number | null {
    const l = tr.trail[tr.trail.length - 1];
    if (!l) return null;
    let found: number | null = null;
    this.walk({ t: l.t, s: l.a, dir: (-l.d) as 1 | -1 }, 1500, tr, (t, s0, s1, dist) => {
      const p = this.passingOn(tr, t, s0, s1);
      if (!p) return false;
      const dir = (s1 >= s0 ? 1 : -1) as 1 | -1;
      if (!this.freeBerth(t, p.st, dir, tr.id, tr)) return false;
      found = dist + Math.abs(p.entry - s0);
      return true;
    });
    return found;
  }

  /**
   * Turn a CPU train round and run it back to the nearest free passing place behind it, holding that line as any run
   * is held, so the train it faced can come by; there it turns round again and waits for its own way (arrive). False,
   * with nothing changed, when there is nowhere behind it to go.
   */
  backOff(tr: Train): boolean {
    if (tr.player || tr.backing || !tr.trail.length) return false;
    // never back down a one-way track against its way (0.8.0 double track)
    if (tr.trail.some((p) => !allowed(p.t, p.a, (-p.d) as 1 | -1) || !allowed(p.t, p.b, (-p.d) as 1 | -1))) return false;
    const keepRun = tr.run, keepNext = tr.nextBerth, keepOpen = tr.open, keepState = tr.state;
    if (keepNext && this.berths.get(keepNext.key) === tr.id) this.berths.delete(keepNext.key);
    tr.nextBerth = null;
    tr.run = [];
    this.flip(tr);
    const choices = new Map(tr.choices);
    tr.choices.clear();
    // only to a passing place (a berth claimed) or off the edge of the cells in memory: not just up behind another train
    if (this.acquire(tr) && !tr.waitOn && (tr.nextBerth || tr.open)) {
      tr.backing = { since: this.clock };
      tr.state = 'run';
      tr.stood = 0; tr.faceoff = 0; tr.v = 0;
      this.stats.backed++;
      return true;
    }
    // nowhere to go: just as it was (a berth it claimed on the way back given up again)
    const claimed = tr.nextBerth as Berth | null;
    if (claimed && this.berths.get(claimed.key) === tr.id) this.berths.delete(claimed.key);
    this.flip(tr);
    tr.choices = choices;
    tr.run = keepRun; tr.nextBerth = keepNext; tr.open = keepOpen; tr.state = keepState;
    if (keepNext) this.berths.set(keepNext.key, tr.id);
    return false;
  }

  /**
   * Jams that can never clear by themselves: each train stood still names the one it waits on (waitOn); followed train
   * to train, a ring back to where it started is a deadlock. One train in the ring goes: the one furthest from the
   * player, taken off out of sight, else backed off to a passing place, else (at last) taken off anyway.
   */
  private unjam(): void {
    const byId = new Map(this.trains.map((t) => [t.id, t]));
    const away = (t: Train) => {
      const f = t.trail[0];
      if (!f || !this.focus) return Infinity;
      sampleAt(f.t, f.b, tmpB);
      return Math.hypot(tmpB.x - this.focus.x, tmpB.z - this.focus.z);
    };
    for (const tr of [...this.trains]) {
      if (tr.player || tr.stood < JAM_AFTER || !tr.waitOn || !this.trains.includes(tr)) continue;
      const ring: Train[] = [tr];
      let o = byId.get(tr.waitOn);
      while (o && ring.length < 12 && !ring.includes(o)) { ring.push(o); o = o.waitOn ? byId.get(o.waitOn) : undefined; }
      if (o !== tr) continue;
      const cpu = ring.filter((t) => !t.player && !t.crew && !t.phantom).sort((a, b) => away(b) - away(a));
      const victim = cpu[0];
      // (a ring of crewed trains: one backs off, none is ever taken off)
      if (!victim) { const c = ring.find((t) => t.crew && !t.backing); if (c && this.backOff(c)) this.stats.unjammed++; continue; }
      this.stats.unjammed++;
      if (away(victim) > 140) { this.noteGaveUp(`${victim.name}: taken off to clear a jam of ${ring.length}`); this.remove(victim); continue; }
      if (this.backOff(victim)) continue;
      if (victim.stood > JAM_AFTER * 3) { this.noteGaveUp(`${victim.name}: taken off to clear a jam of ${ring.length} (nowhere to back off)`); this.remove(victim); }
    }
  }

  /** Is anyone already on the single line ahead of a train, up to the next passing place: a new train isn't put there. */
  private sectionBusy(tr: Train): boolean {
    const f = tr.trail[0];
    if (!f) return true;
    let busy = false;
    this.walk({ t: f.t, s: f.b, dir: f.d }, 500, tr, (t, s0, s1) => {
      const dir = (s1 >= s0 ? 1 : -1) as 1 | -1, lo = Math.min(s0, s1), hi = Math.max(s0, s1);
      // (on one-way track only someone against its way counts: following one going the same way is no conflict)
      const oneWay = !!t.p.oneWay && !inZone(t, lo, hi);
      for (const o of this.trains) {
        if (o === tr) continue;
        if (o.trail.some((p) => p.t === t && (!oneWay || (p.d !== dir && o.player)) && Math.max(p.a, p.b) >= lo && Math.min(p.a, p.b) <= hi)) { busy = true; return true; }
        if (o.run.some((r) => r.t === t && r.dir !== dir && r.hi >= lo && r.lo <= hi && this.opposes(o, t, Math.max(lo, r.lo), Math.min(hi, r.hi)))) { busy = true; return true; }
      }
      return !!this.passingOn(tr, t, s0, s1);
    });
    return busy;
  }

  /**
   * The line your train holds (the user, 3 Nov 2026: it used to hold only thirty tiles ahead, so CPU trains took the
   * single line it was about to run onto): what is under it and, while it runs, the way on to the next passing place
   * (or PLAYER_HOLD tiles); stood, only a braking distance. A CPU train never takes line held against it.
   */
  holdLine(tr: Train, running: boolean, v: number): void {
    tr.run = [];
    let held = 0;
    for (const p of tr.trail) {
      tr.run.push({ t: p.t, lo: Math.min(p.a, p.b), hi: Math.max(p.a, p.b), dir: p.d });
      held += Math.abs(p.b - p.a);
      if (held > tr.length) break;
    }
    const f = tr.trail[0];
    if (!f) return;
    this.walk({ t: f.t, s: f.b, dir: f.d }, running ? PLAYER_HOLD : 30 + Math.abs(v) * 8, tr, (t, s0, s1, dist) => {
      const dir = (s1 >= s0 ? 1 : -1) as 1 | -1;
      const p = running ? this.passingOn(tr, t, s0, s1) : null;
      // (nor a junction's two-way stretch on double track while it is still a way off)
      const cut = p ? null : this.zoneAhead(t, s0, s1, dist);
      const end = p ? p.entry : cut ?? s1;
      tr.run.push({ t, lo: Math.min(s0, end), hi: Math.max(s0, end), dir });
      return !!p || cut !== null;
    });
  }

  /** The first train coming the other way on the line ahead of yours (on it, or holding it), within `max` tiles, and how far. */
  private oncoming(me: Train, max: number): { o: Train; d: number } | null {
    const f = me.trail[0];
    if (!f) return null;
    let found: { o: Train; d: number } | null = null;
    this.walk({ t: f.t, s: f.b, dir: f.d }, max, me, (t, s0, s1, dist) => {
      const dir = (s1 >= s0 ? 1 : -1) as 1 | -1, lo = Math.min(s0, s1), hi = Math.max(s0, s1);
      // how far along this stretch the nearest of [a, b] lies, from where the walk came onto it
      const reach = (a: number, b: number) => dist + Math.abs((dir > 0 ? Math.max(lo, Math.min(a, b)) : Math.min(hi, Math.max(a, b))) - s0);
      let best: { o: Train; d: number } | null = null;
      for (const o of this.trains) {
        if (o === me || o.player) continue;
        for (const p of o.trail) if (p.t === t && p.d !== dir && Math.max(p.a, p.b) >= lo && Math.min(p.a, p.b) <= hi) { const d = reach(p.a, p.b); if (!best || d < best.d) best = { o, d }; }
        for (const r of o.run) if (r.t === t && r.dir !== dir && r.hi >= lo && r.lo <= hi) { const d = reach(r.lo, r.hi); if (!best || d < best.d) best = { o, d }; }
      }
      if (best) { found = best; return true; }
      return false;
    });
    return found;
  }

  /**
   * K in your train (the user, 3 Nov 2026): the nearest train coming the other way on the line ahead makes way. One in a
   * berth keeps to it a while; one out on the line backs off to the passing place behind it; one that can do neither
   * out of sight goes back up the line. What it does, for a line on the screen, or null with nobody coming.
   */
  giveWay(me: Train): string | null {
    const c = this.oncoming(me, 1500);
    if (!c) return null;
    const o = c.o;
    if (o.backing) return `${o.name} is already backing off for you`;
    // stood in a berth (dwelling, or waiting for the line): it stays there until you are by
    if (o.berth && o.state !== 'run') {
      this.release(o);
      o.state = 'wait';
      o.holdFor = GIVE_WAY_HOLD;
      this.stats.gaveWay++;
      return `${o.name} waits at ${o.berth.station.passing ? 'the passing loop' : o.berth.station.name} for you`;
    }
    if (this.backOff(o)) { this.stats.gaveWay++; return `${o.name} is backing into the last loop to let you by`; }
    const f = o.trail[0];
    sampleAt(f.t, f.b, tmpB);
    if (!o.crew && (!this.focus || Math.hypot(tmpB.x - this.focus.x, tmpB.z - this.focus.z) > 140)) {
      this.stats.gaveWay++;
      this.remove(o);
      return `${o.name} has been held back up the line`;
    }
    return `${o.name} has nowhere to back off to: reverse to the last loop`;
  }

  /**
   * The line ahead of your train for the HUD: the next passing place, and whether anyone is coming the other way before
   * it (the user, 3 Nov 2026: "Line clear to Harrow Road", or who is coming). Null with no passing place in memory ahead.
   */
  lineAhead(me: Train): { clearTo: string | null; coming: string | null; d: number } {
    const c = this.oncoming(me, 1500);
    let clearTo: string | null = null;
    const f = me.trail[0];
    if (f) {
      this.walk({ t: f.t, s: f.b, dir: f.d }, 1500, me, (t, s0, s1) => {
        const p = this.passingOn(me, t, s0, s1);
        if (p) { clearTo = p.st.passing ? 'the passing loop' : p.st.name; return true; }
        return false;
      });
    }
    return { clearTo, coming: c ? c.o.name : null, d: c ? c.d : Infinity };
  }

  // ---- the frame ----

  update(dt: number, player: { x: number; z: number } | null, night: number): void {
    if (dt <= 0) return;
    this.railsChanged();
    this.focus = player;
    this.night = night;
    this.clock += dt;

    // CPU trains to the budget
    this.spawnTimer -= dt;
    // (each crewed train in memory takes one CPU train's place, so the line doesn't fill up)
    const cpu = this.trains.filter((t) => !t.player && !t.crew && !t.phantom).length;
    const budget = Math.max(1, this.budget - this.trains.filter((t) => t.crew).length);
    if (cpu < budget && this.spawnTimer <= 0) {
      this.spawnTimer = cpu < budget / 2 ? 4 : 14;
      this.spawn(null, player ?? undefined);
    }
    for (const tr of [...this.trains]) {
      if (tr.player) continue;
      if (tr.phantom) { tr.wheelSpin += (tr.v * dt) / 0.05; continue; }
      // a train far out of sight with no station ahead of it in memory has gone up the line
      if (player && !tr.crew && tr.state !== 'dwell' && !tr.nextBerth && (tr.open || !tr.run.length) && tr.trail.length) {
        sampleAt(tr.trail[0].t, tr.trail[0].b, tmpA);
        const d = Math.hypot(tmpA.x - player.x, tmpA.z - player.z);
        const leaving = d > tr.lastD;
        tr.lastD = d;
        if (d > DESPAWN && leaving) { this.stats.despawned++; this.remove(tr); continue; }
      }
      this.drive(tr, dt);
    }
    // jams that can never clear by themselves, looked for once a second
    if ((this.jamT -= dt) <= 0) { this.jamT = 1; this.unjam(); }
    this.crossingsAndSignals();
    for (const tr of this.trains) this.pose(tr, night);
    this.smoke(dt);
  }

  // ---- steam ----

  private puffs: { m: THREE.Mesh; life: number; vx: number; vz: number }[] = [];
  private static puffGeo = new THREE.IcosahedronGeometry(0.09, 0);

  /** Puffs from every steam engine's stack, faster the faster it runs, rising, swelling and thinning away. */
  private smoke(dt: number): void {
    for (const tr of this.trains) {
      const eng = tr.cars[0]?.mesh;
      if (!eng?.smoke || !eng.group.visible) continue;
      const rate = tr.v > 0.2 ? Math.max(0.12, 0.45 - tr.v * 0.12) : tr.state === 'dwell' ? 1.6 : 0;
      if (!rate) continue;
      tr.puff = (tr.puff ?? 0) - dt;
      if (tr.puff > 0) continue;
      tr.puff = rate;
      let p = this.puffs.find((q) => q.life <= 0);
      if (!p) {
        if (this.puffs.length >= 64) continue;
        const mat = new THREE.MeshStandardMaterial({ color: 0xd9d6cf, roughness: 1, transparent: true, opacity: 0.8, flatShading: true, depthWrite: false });
        p = { m: new THREE.Mesh(Trains.puffGeo, mat), life: 0, vx: 0, vz: 0 };
        this.group.add(p.m);
        this.puffs.push(p);
      }
      const at = eng.smoke.clone();
      eng.group.localToWorld(at);
      p.m.position.copy(at);
      p.m.scale.setScalar(1);
      p.m.visible = true;
      p.life = 2.4;
      p.vx = (Math.random() - 0.5) * 0.15;
      p.vz = (Math.random() - 0.5) * 0.15;
    }
    for (const p of this.puffs) {
      if (p.life <= 0) { p.m.visible = false; continue; }
      p.life -= dt;
      const age = 1 - p.life / 2.4;
      p.m.position.x += p.vx * dt;
      p.m.position.z += p.vz * dt;
      p.m.position.y += (0.45 - age * 0.25) * dt;
      p.m.scale.setScalar(1 + age * 3.5);
      (p.m.material as THREE.MeshStandardMaterial).opacity = 0.75 * (1 - age) * (1 - age);
    }
  }

  /** One CPU train's frame: dwell, wait for the line, run to its next stop. */
  private drive(tr: Train, dt: number): void {
    if (!tr.trail.length) { this.remove(tr); return; }
    // stood still out on the line (anywhere but dwelling at a platform), however it came to: every give-up is timed by
    // this (3 Nov 2026: a train that held its line but couldn't move counted neither wait, and stood there for good)
    tr.stood = tr.state !== 'dwell' && tr.v < 0.05 ? tr.stood + dt : 0;
    if (!tr.stood) tr.waitOn = 0;
    if (tr.crew) {
      // a CPU train holding the line it wants, or the berth: asked to make way, as your own train asks it with K
      if (tr.waitOn && tr.stood > CREW_ASK && (tr.crew.ask -= dt) <= 0) {
        tr.crew.ask = CREW_ASK;
        const o = this.trains.find((q) => q.id === tr.waitOn);
        if (o) this.makeWay(o);
      }
      // never taken off: a long wait backs it off to the passing place behind, a second turns it round to work the other way
      if (tr.stood > GIVE_UP * 2) { this.stats.crewRescued++; this.noteGaveUp(`${tr.name} (crewed) at ${tr.trail[0]?.t.w.name}: ${tr.why || 'stood too long'}, turned round`); this.crewTurn(tr); return; }
      if (tr.stood > GIVE_UP && !tr.crew.backed && !tr.backing) { tr.crew.backed = true; if (this.backOff(tr)) return; }
    } else if (tr.stood > this.patience(tr)) { this.stats.gaveUp++; this.noteGaveUp(`${tr.name} at ${tr.trail[0]?.t.w.name}: ${tr.why || 'stood too long'}`); this.remove(tr); return; }
    if (tr.state === 'dwell') {
      tr.timer -= dt;
      if (tr.timer > 0) return;
      // a crewed train at an end of its beat turns round to work back the other way
      if (tr.crew) {
        const c = tr.crew;
        if (c.at && c.beat.ends.some((e) => e.st === c.at)) {
          // long haul: on past this end, toward the edge, instead of turning round
          if (c.runOn && c.runOn.end === c.at) { c.out = c.runOn.to; c.runOn = null; tr.to = c.out; }
          // (on double track, the other platform taken: it stands at this one and tries again in a moment)
          else { if (!this.crewTurn(tr)) { tr.state = 'dwell'; tr.timer = 1; } return; }
        }
      }
      // the end of the line for this train
      else if (tr.berth && tr.berth.station.name === tr.to) { this.stats.arrived++; this.remove(tr); return; }
      tr.state = 'wait';
    }
    if (tr.state === 'wait') {
      // asked to hold where it is for your train (giveWay)
      if (tr.holdFor > 0) { tr.holdFor -= dt; tr.stood = 0; return; }
      if (this.acquire(tr)) { tr.state = 'run'; tr.waited = 0; }
      else { tr.waited += dt; return; }
    }
    // ---- run ----
    const front = tr.trail[0];
    // the berth it pulled out of is free once the last car is clear of it
    if (tr.berth && tr.berth !== tr.nextBerth) {
      const b = tr.berth;
      let inside = false, held = 0;
      for (const p of tr.trail) {
        if (held > tr.length) break;
        if (p.t === b.t && Math.max(p.a, p.b) >= b.lo && Math.min(p.a, p.b) <= b.hi) inside = true;
        held += Math.abs(p.b - p.a);
      }
      if (!inside) {
        if (this.berths.get(b.key) === tr.id) this.berths.delete(b.key);
        tr.berth = null;
      }
    }
    const here = sampleAt(front.t, front.b, tmpA);
    // what is ahead: the end of what we hold, a stop, a train
    const look = 12 + tr.v * tr.v / (tr.accel * 1.2) + HEADWAY * 2;
    let limit = tr.vMax;
    let stopDist = Infinity;
    if (!tr.run.length && !tr.nextBerth && this.acquire(tr)) tr.waited = 0;
    // an open run (up to the train in front, or the edge of the cells in memory) is taken again every so often, so the
    // line held reaches on as the way clears; so is a run that stopped short with no berth. Refused, it keeps what it
    // has and asks again: only the line being held against it (not a full berth) stops it at the end of what it holds
    if ((tr.open || (!tr.nextBerth && tr.run.length && tr.stood > 1)) && (tr.retake -= dt) <= 0) {
      tr.retake = 0.5;
      const keep = tr.run, wasOpen = tr.open;
      if (!this.acquire(tr)) { tr.run = keep; tr.open = wasOpen && !tr.why.startsWith('line held'); }
    }
    let heldTo = this.heldAhead(tr) + (tr.nextBerth ? tr.nextBerth.hi - tr.nextBerth.lo : 0);
    // stood in its own berth with the line on still held against it: draw up to the far end and wait there
    if (!tr.run.length && tr.berth && front.t === tr.berth.t) {
      heldTo = Math.max(heldTo, (front.d > 0 ? tr.berth.hi - front.b : front.b - tr.berth.lo) + 0.5);
    }
    tr.ahead = null;
    let nextStop: { t: Track; s: number; station: RailStation } | null = null;
    let offEdge = false;
    const end = this.walk({ t: front.t, s: front.b, dir: front.d }, Math.max(look, 40), tr, (t, s0, s1, dist) => {
      const lo = Math.min(s0, s1), hi = Math.max(s0, s1), dir = s1 >= s0 ? 1 : -1;
      // calling points
      // (backing up to a passing place, it calls nowhere on the way)
      if (!nextStop && !tr.backing) {
        for (const { st, loop } of t.stations) {
          if (!this.callsAt(tr, st) || st.name === tr.called) continue;
          let sStop: number;
          if (loop) sStop = dir > 0 ? t.p.length - TAPER - 1 : TAPER + 1;
          else sStop = dir > 0 ? st.s1 - 1 : st.s0 + 1;
          if (sStop < lo - 1e-6 || sStop > hi + 1e-6) continue;
          const d = dist + Math.abs(sStop - s0);
          if (d < stopDist) { stopDist = d; nextStop = { t, s: sStop, station: st }; }
        }
      }
      // other trains on this stretch
      for (const o of this.trains) {
        if (o === tr) continue;
        for (const p of o.trail) {
          if (p.t !== t) continue;
          const plo = Math.min(p.a, p.b), phi = Math.max(p.a, p.b);
          if (phi < lo || plo > hi) continue;
          const nearS = dir > 0 ? Math.max(lo, plo) : Math.min(hi, phi);
          const d = dist + Math.abs(nearS - s0);
          if (d - HEADWAY < stopDist) {
            stopDist = Math.max(0, d - HEADWAY);
            tr.ahead = { name: o.name, d, opposing: p.d !== dir, id: o.id };
          }
        }
      }
      // slow through loops
      if (t.p.kind === 'loop' && dist < 8) limit = Math.min(limit, LOOP_SPEED);
      return false;
    });
    if (!end) offEdge = true;
    // don't run past the end of the line we hold (unless it runs off into the cells not in memory)
    // (an open run cut short of a junction's two-way stretch is not run past either, until it reaches on through it)
    if (!offEdge && (!tr.open || tr.zoneStop)) stopDist = Math.min(stopDist, Math.max(0, heldTo - 2));
    // stopped short of a train: that is who it waits on
    const ah = tr.ahead as Train['ahead'];
    if (tr.v < 0.05 && ah && ah.d < HEADWAY + 8) tr.waitOn = ah.id;
    // nose to nose: somebody backs off to a passing place (the user, 3 Nov 2026: everyone used to sit there until one
    // was taken off). Facing your train, this one goes back; facing another CPU train, whichever has less way back.
    if (tr.v < 0.05 && ah && ah.opposing && ah.d < 40) {
      tr.faceoff += dt;
      const other = this.trains.find((o) => o.id === ah.id) ?? null;
      // (facing one of the player's crewed trains, a CPU train makes way as it would for the player's own)
      if ((other?.player || other?.phantom || (other?.crew && !tr.crew)) && tr.faceoff > BACK_OFF && !tr.backing && this.backOff(tr)) return;
      if (other && !other.player && !other.phantom && !!other.crew === !!tr.crew && tr.faceoff > BACK_OFF * 2 && !tr.backing && !other.backing) {
        const mine = this.wayBack(tr), theirs = this.wayBack(other);
        if (mine !== null && (theirs === null || mine < theirs || (mine === theirs && tr.id < other.id)) && this.backOff(tr)) return;
      }
      // nowhere to go back to: out of sight one of them was never really there; in sight, at last, the same
      const far = !this.focus || Math.hypot(here.x - this.focus.x, here.z - this.focus.z) > 140;
      if (!tr.crew && tr.faceoff > (far ? 6 : GIVE_UP / 2)) { this.stats.faceoff++; this.remove(tr); return; }
    } else tr.faceoff = 0;
    tr.stop = nextStop;
    tr.stopIn = stopDist;
    // grade
    const back = pointBehind(tr, Math.min(tr.length, 3));
    let grade = 0;
    if (back) {
      sampleAt(back.t, back.s, tmpB);
      const run = Math.hypot(here.x - tmpB.x, here.z - tmpB.z);
      if (run > 0.5) grade = (here.y - tmpB.y) / STEP / run;
    }
    if (grade > 0) limit *= 1 - Math.min(0.5, (tr.freight ? 0.3 : 0.15) * grade / (1 / 6));
    const decel = tr.accel * 1.4;
    const brakeTo = Math.sqrt(Math.max(0, 2 * decel * Math.max(0, stopDist - 0.3)));
    let target = Math.min(limit, brakeTo);
    if (nextStop && stopDist < 30) target = Math.min(target, Math.max(PLATFORM_SPEED, brakeTo));
    tr.v += Math.max(-decel * dt, Math.min(tr.accel * dt, target - tr.v));
    if (tr.v < 0) tr.v = 0;
    const res = this.advance(tr, tr.v * dt);
    // a crewed train never runs off its beat: buffers, or the edge of what is in memory, turn it round; one running on
    // past its beat's end on a long haul leaves memory at the edge on its far run
    if (tr.crew && res === 'edge' && tr.crew.out && this.onCrewFar) {
      const f = tr.trail[0], e = f.d > 0 ? f.t.p.end : f.t.p.start;
      if (this.onCrewFar(tr, { cx: f.t.w.cx, cz: f.t.w.cz, side: e.side ?? 0 })) { this.remove(tr); return; }
    }
    if (tr.crew && res !== 'ok') { this.crewTurn(tr); return; }
    if (res === 'edge') { this.stats.edge++; this.remove(tr); return; }
    // and one with nothing of its beat ahead (past an end, somehow) turns round too, looked for now and then
    if (tr.crew && !tr.crew.out && tr.state === 'run' && !tr.backing && (tr.crew.look -= dt) <= 0) { tr.crew.look = 1; if (!this.crewAhead(tr)) { this.crewTurn(tr); return; } }
    // arrived at a calling point
    const ns = nextStop as { t: Track; s: number; station: RailStation } | null;
    if (ns && stopDist < 0.6 && tr.v < 0.3) {
      tr.v = 0;
      tr.called = ns.station.name;
      tr.state = 'dwell';
      tr.timer = DWELL[0] + Math.random() * (DWELL[1] - DWELL[0]);
      if (tr.operator) this.onCall?.(tr.operator.id);
      if (tr.crew) {
        tr.crew.at = ns.station.of ?? ns.station; tr.crew.backed = false; this.stats.crewCalls++;
        // two seconds a load handed in or taken on, up to twenty in all
        const n = this.onCrewCall?.(tr, tr.crew.at) ?? 0;
        if (n) tr.timer = Math.max(tr.timer, Math.min(CREW_DWELL_MAX, DWELL[0] + 2 * n));
      }
      // a halt has no loop: the line is still ours
      if (tr.nextBerth && tr.nextBerth.station === ns.station) this.arrive(tr);
    }
    // passing through a loop station without calling: hand over the berth once through it
    if (tr.nextBerth && !ns && (this.pastBerth(tr) || (tr.v < 0.05 && this.pastBerth(tr, false)))) this.arrive(tr);
  }

  /** How much of the line it holds is still ahead of a train's front. */
  private heldAhead(tr: Train): number {
    const f = tr.trail[0];
    let i = tr.run.findIndex((h) => h.t === f.t && f.b >= h.lo - 1e-6 && f.b <= h.hi + 1e-6);
    if (i < 0) return 0;
    const h = tr.run[i];
    let d = h.dir > 0 ? h.hi - f.b : f.b - h.lo;
    for (i++; i < tr.run.length; i++) d += tr.run[i].hi - tr.run[i].lo;
    return Math.max(0, d);
  }

  /** The front is inside the berth it was running to: the run is spent and the berth is its own. */
  private arrive(tr: Train): void {
    if (tr.berth && tr.berth !== tr.nextBerth) this.berths.delete(tr.berth.key);
    tr.berth = tr.nextBerth ?? null;
    if (tr.berth?.loop) this.stats.loops++;
    if (tr.berth && this.trains.some((o) => o !== tr && o.berth && o.berth.station === tr.berth!.station)) this.stats.meets++;
    tr.nextBerth = null;
    tr.run = [];
    // backed into the passing place: turned round again, it waits there for the line on the way it was going
    if (tr.backing) {
      this.flip(tr);
      tr.backing = null;
      tr.choices.clear();
      tr.v = 0;
      tr.state = 'wait';
    }
  }

  /**
   * The whole train is inside the berth it was running to. Only then is the run behind it spent: let
   * it go as the front came in and the train would stop dead with its tail still out on the single
   * line, where the train it was to pass is waiting to come through.
   */
  private pastBerth(tr: Train, whole = true): boolean {
    const b = tr.nextBerth;
    if (!b) return false;
    const f = tr.trail[0];
    if (f.t !== b.t || f.b < b.lo || f.b > b.hi) return false;
    // (stopped short with only the front in, by something in the way: it takes the berth as it is)
    if (!whole) return true;
    const r = pointBehind(tr, tr.length);
    return !!r && r.t === b.t && r.s >= b.lo && r.s <= b.hi;
  }

  /**
   * Move a train's front on along its trail by ds tiles, over turnouts it takes and on across joins and
   * borders. Returns 'edge' when it runs off the cells in memory, 'buffers' at the end of the line.
   */
  advance(tr: Train, ds: number): 'ok' | 'edge' | 'buffers' {
    let rem = ds;
    let result: 'ok' | 'edge' | 'buffers' = 'ok';
    for (let guard = 0; guard < 40 && rem > 1e-9; guard++) {
      const p = tr.trail[0];
      const end = p.d > 0 ? p.t.p.length : 0;
      let dist = Math.abs(end - p.b), branch: Switch | null = null;
      for (const sw of p.t.switches) {
        if (sw.dir !== p.d) continue;
        const ahead = (sw.s - p.b) * p.d;
        if (ahead <= 1e-6 || ahead > dist) continue;
        if (!this.takes(tr, sw, p.t)) continue;
        dist = ahead; branch = sw;
      }
      if (rem < dist) { p.b += p.d * rem; rem = 0; break; }
      p.b += p.d * dist;
      rem -= dist;
      if (branch) { tr.trail.unshift({ t: branch.to, a: branch.toS, b: branch.toS, d: branch.toDir }); continue; }
      const nx = this.net.next(p.t, p.d > 0);
      if (!nx) {
        const e = p.d > 0 ? p.t.p.end : p.t.p.start;
        result = e.kind === 'border' ? 'edge' : 'buffers';
        tr.v = 0;
        break;
      }
      tr.trail.unshift({ t: nx.t, a: nx.s, b: nx.s, d: nx.dir });
    }
    // forget track the last car has left behind
    // (the oldest piece is cut to where the last car ends, so a trail never claims track it has left)
    let total = 0;
    const keep = tr.length + 1;
    for (let i = 0; i < tr.trail.length; i++) {
      const p = tr.trail[i], len = Math.abs(p.b - p.a);
      if (total + len >= keep) { p.a = p.b - p.d * (keep - total); tr.trail.length = i + 1; break; }
      total += len;
    }
    tr.wheelSpin += ds / 0.05;
    if (tr.crossed && (tr.crossed.gone += Math.abs(ds)) > CROSS_LEN + tr.length + 2) tr.crossed = undefined;
    return result;
  }

  /** Turn a train's trail round, so it runs the other way with its last car leading. */
  flip(tr: Train): void {
    // cut the trail to exactly the train's length so the new front is the last car's end
    let left = tr.length;
    const cut: Piece[] = [];
    for (const p of tr.trail) {
      const len = Math.abs(p.b - p.a);
      if (left <= len) { cut.push({ t: p.t, a: p.b - p.d * left, b: p.b, d: p.d }); left = 0; break; }
      cut.push({ ...p });
      left -= len;
    }
    tr.trail = cut.reverse().map((p) => ({ t: p.t, a: p.b, b: p.a, d: (-p.d) as 1 | -1 }));
    tr.flipped = !tr.flipped;
  }

  /** Every car on its two bogie points; hidden where the trail doesn't reach (still coming in from the edge). */
  private pose(tr: Train, night: number): void {
    for (const c of tr.cars) {
      if (!c.mesh) continue;
      const centre = tr.flipped ? tr.length - c.offset : c.offset;
      const fwd = tr.flipped ? centre + c.bogie : centre - c.bogie;
      const rear = tr.flipped ? centre - c.bogie : centre + c.bogie;
      const f = pointBehind(tr, fwd), r = pointBehind(tr, rear);
      const g = c.mesh.group;
      if (!f || !r) { g.visible = false; continue; }
      sampleAt(f.t, f.s, tmpA);
      sampleAt(r.t, r.s, tmpB);
      if (tr.crossed) { this.slideBack(tr, f, fwd, tmpA); this.slideBack(tr, r, rear, tmpB); }
      const hidden = f.t.p.under[Math.min(f.t.p.under.length - 1, Math.round((f.s / (f.t.p.length || 1)) * (f.t.p.under.length - 1)))] === Under.Tunnel
        && r.t.p.under[Math.min(r.t.p.under.length - 1, Math.round((r.s / (r.t.p.length || 1)) * (r.t.p.under.length - 1)))] === Under.Tunnel;
      g.visible = !hidden;
      g.position.set((tmpA.x + tmpB.x) / 2, (tmpA.y + tmpB.y) / 2, (tmpA.z + tmpB.z) / 2);
      const dx = tmpA.x - tmpB.x, dz = tmpA.z - tmpB.z, run = Math.hypot(dx, dz) || 1;
      g.rotation.set(-Math.atan2(tmpA.y - tmpB.y, run), Math.atan2(dx, dz), 0, 'YXZ');
      for (const wh of c.mesh.wheels) wh.rotation.x = tr.flipped ? -tr.wheelSpin : tr.wheelSpin;
      for (const m of c.mesh.lit) {
        if (m.userData.dayEmissive === undefined) m.userData.dayEmissive = m.emissiveIntensity;
        // the stealth train's red lamps are dark by day and only faint after it
        m.emissiveIntensity = m.userData.night ? m.userData.dayEmissive * night : m.userData.dayEmissive * (1 + 4 * night);
      }
      c.mesh.anim?.(this.clock, night);
    }
  }

  /** A point of a train still crossing over, drawn part way back toward the same place on the track it crossed from. */
  private slideBack(tr: Train, p: { t: Track; s: number }, behind: number, out: { x: number; y: number; z: number }): void {
    const ts = twinS(p.t, p.s);
    if (ts === null || !tr.crossed) return;
    // (how far this point has run past where the train turned: none yet is all the way back, CROSS_LEN on is across)
    const u = Math.min(1, Math.max(0, (tr.crossed.gone - behind) / CROSS_LEN));
    const w = 1 - u * u * (3 - 2 * u);
    if (w <= 0) return;
    sampleAt(p.t.twin!, ts, tmpC);
    out.x += (tmpC.x - out.x) * w; out.z += (tmpC.z - out.z) * w; out.y += (tmpC.y - out.y) * w;
  }

  /** Barriers down ahead of every train, the tiles each train covers, and the station signals. */
  private crossingsAndSignals(): void {
    const was = new Set(this.armed);
    this.armed.clear();
    this.occupied.clear();
    for (const tr of this.trains) {
      if (!tr.trail.length) continue;
      // under the train
      for (const p of tr.trail) {
        const lo = Math.min(p.a, p.b), hi = Math.max(p.a, p.b);
        for (const c of this.net.crossingsOf(p.t)) if (c.s >= lo - 0.6 && c.s <= hi + 0.6) { this.occupied.add(c.key); this.armed.add(c.key); }
      }
      // ahead, by time as much as distance: a fast train drops the barriers further out
      const f = tr.trail[0];
      const reach = 3 + Math.abs(tr.v) * 5;
      if (tr.v >= 0) {
        this.walk({ t: f.t, s: f.b, dir: f.d }, reach, tr, (t, s0, s1) => {
          const lo = Math.min(s0, s1), hi = Math.max(s0, s1);
          for (const c of this.net.crossingsOf(t)) if (c.s >= lo && c.s <= hi) this.armed.add(c.key);
          return false;
        });
      }
    }
    if (this.onCrossing) {
      for (const k of this.armed) if (!was.has(k)) this.onCrossing(k, true);
      for (const k of was) if (!this.armed.has(k)) this.onCrossing(k, false);
    }
    if (this.onSignal) {
      for (const w of this.worlds) {
        w.stations.forEach((st, i) => {
          // red when the line beyond that end of the platform is held by a train coming the other way
          const held = (end: 0 | 1) => {
            for (const o of this.trains) {
              for (const r of o.run) {
                if (r.t.w !== w || r.t.p.id !== st.path) continue;
                if (end === 0 ? r.dir > 0 && r.lo < st.s0 : r.dir < 0 && r.hi > st.s1) return true;
              }
            }
            return false;
          };
          for (const end of [0, 1] as const) {
            const key = `${w.cx},${w.cz}:${i}:${end}`, clear = !held(end);
            if (this.signals.get(key) === clear) continue;
            this.signals.set(key, clear);
            this.onSignal!(key, clear);
          }
        });
      }
    }
  }

  // ---- crewed trains (docs/crewtrains.html) ----

  /**
   * Put one of the player's trains on the line with a hired driver: on the track at `at` facing the nearer stop of its
   * beat, its cars laid back along the line. The reason instead when it can't go on there now (something in the way).
   */
  placeCrew(set: TrainSet, at: Loc, beat: Beat, crew: { uid: number; driver: string; name: string; pace: number; paint?: [number, number] }, seed: number, producers?: string[]): Train | string {
    const rng = mulberry32(seed);
    const ids = set.freight ? fillSet(set, rng, producers) : set.cars;
    // (in the fleet's colours, as a transit railway's trains are in theirs)
    const tr = this.make(ids, set.era, set.freight, false, seed, crew.paint);
    tr.vMax = set.topSpeed * crew.pace;
    tr.accel = set.accel;
    tr.name = crew.name;
    tr.crew = { uid: crew.uid, driver: crew.driver, beat, at: null, backed: false, look: 1, ask: 0 };
    // facing whichever way the nearer stop of its beat lies
    let dir: 1 | -1 = at.t.p.oneWay ?? 1, best = Infinity;
    for (const d of [1, -1] as const) {
      // (on double track, only the track's own way)
      if (!allowed(at.t, at.s, d)) continue;
      this.walk({ t: at.t, s: at.s, dir: d }, 3000, tr, (t, s0, s1, dist) => {
        for (const { st, loop } of t.stations) {
          if (loop || !this.callsAt(tr, st)) continue;
          const mid = (st.s0 + st.s1) / 2;
          if (mid < Math.min(s0, s1) || mid > Math.max(s0, s1)) continue;
          const dd = dist + Math.abs(mid - s0);
          if (dd < best) { best = dd; dir = d; }
        }
        return false;
      });
    }
    this.layTrail(tr, { t: at.t, s: at.s, dir });
    if (!tr.trail.length) { this.remove(tr); return 'No track here to stand on'; }
    // never onto track another train is on
    const clash = this.trains.some((o) => o !== tr && o.trail.some((p) => tr.trail.some((q) => q.t === p.t
      && Math.max(q.a, q.b) + HEADWAY >= Math.min(p.a, p.b) && Math.min(q.a, q.b) - HEADWAY <= Math.max(p.a, p.b))));
    if (clash) { this.remove(tr); return 'Waiting for the line to clear'; }
    tr.state = 'wait';
    tr.to = this.crewBound(tr);
    tr.from = beat.ends[0].name;
    return tr;
  }

  /**
   * A crewed train back from its far run, coming in over the border at `front` (heading inward), its cars following on
   * as the track under them comes into memory, the way a CPU train comes in from the edge. Why not, while it can't.
   */
  placeCrewIn(set: TrainSet, front: Loc, beat: Beat, crew: { uid: number; driver: string; name: string; pace: number; paint?: [number, number] }, seed: number, producers?: string[]): Train | string {
    const lo = (p: Piece) => Math.min(p.a, p.b), hi = (p: Piece) => Math.max(p.a, p.b);
    const near = (t: Track, a: number, b: number) => t === front.t && b + HEADWAY * 3 >= front.s && a - HEADWAY * 3 <= front.s;
    const inWay = this.trains.filter((o) => o.trail.some((p) => near(p.t, lo(p), hi(p))) || o.run.some((r) => near(r.t, r.lo, r.hi)));
    if (inWay.length) {
      // a CPU train in the way at the edge makes way for it, as for your own train (out of sight, it goes up the line)
      for (const o of inWay) this.makeWay(o);
      return 'Waiting for the line to clear';
    }
    const rng = mulberry32(seed);
    const ids = set.freight ? fillSet(set, rng, producers) : set.cars;
    const tr = this.make(ids, set.era, set.freight, false, seed, crew.paint);
    tr.vMax = set.topSpeed * crew.pace;
    tr.accel = set.accel;
    tr.name = crew.name;
    tr.crew = { uid: crew.uid, driver: crew.driver, beat, at: null, backed: false, look: 4, ask: 0 };
    tr.trail = [{ t: front.t, a: front.s, b: front.s, d: front.dir }];
    tr.v = Math.min(tr.vMax, 3);
    tr.state = 'wait';
    tr.to = this.crewBound(tr);
    tr.from = beat.ends[0].name;
    return tr;
  }

  /** A crewed train's new beat (the track changed, or the player chose new ends): kept on the line, bound for the end it faces. */
  reBeat(tr: Train, beat: Beat): void {
    if (!tr.crew) return;
    tr.crew.beat = beat;
    tr.choices.clear();
    tr.to = this.crewBound(tr);
  }

  /** The end of its beat a crewed train is running toward, by name: the last end of its beat ahead of it. */
  private crewBound(tr: Train): string {
    const f = tr.trail[0];
    if (!f || !tr.crew) return '';
    let name = '';
    this.walk({ t: f.t, s: f.b, dir: f.d }, 3000, tr, (t) => {
      for (const { st, loop } of t.stations) if (!loop && tr.crew!.beat.ends.some((e) => e.st === (st.of ?? st))) name = (st.of ?? st).name;
      return false;
    });
    return name || tr.crew.beat.ends[1].name;
  }

  /** Is any stop of its beat still ahead of a crewed train (other than the one it has just called at)? */
  private crewAhead(tr: Train): boolean {
    const f = tr.trail[0];
    if (!f || !tr.crew) return false;
    let found = false;
    this.walk({ t: f.t, s: f.b, dir: f.d }, 3000, tr, (t, s0, s1) => {
      for (const { st, loop } of t.stations) {
        const real = st.of ?? st;
        if (real === tr.crew!.at || !tr.crew!.beat.stops.some((b) => b.st === real)) continue;
        // (through a station's loop is through the station: the loop's arc lengths are not the platform's)
        if (loop || (st.s1 >= Math.min(s0, s1) && st.s0 <= Math.max(s0, s1))) { found = true; return true; }
      }
      return false;
    });
    return found;
  }

  /**
   * A CPU train in a crewed train's way makes way for it, the way it does for your own train's K: one stood in a berth
   * keeps to it a while, one out on the line backs off to the passing place behind it, one that can do neither out of
   * sight goes back up the line. True when it did something.
   */
  private makeWay(o: Train): boolean {
    if (o.player || o.crew || o.phantom || o.backing) return false;
    if (o.berth && o.state !== 'run') {
      this.release(o);
      if (o.nextBerth && this.berths.get(o.nextBerth.key) === o.id) this.berths.delete(o.nextBerth.key);
      o.nextBerth = null;
      o.state = 'wait';
      o.holdFor = GIVE_WAY_HOLD;
      this.stats.gaveWay++;
      return true;
    }
    if (this.backOff(o)) { this.stats.gaveWay++; return true; }
    const f = o.trail[0];
    if (!f) return false;
    sampleAt(f.t, f.b, tmpB);
    if (!this.focus || Math.hypot(tmpB.x - this.focus.x, tmpB.z - this.focus.z) > 140) {
      this.stats.gaveWay++;
      this.noteGaveUp(`${o.name}: held back up the line for a crewed train`);
      this.remove(o);
      return true;
    }
    return false;
  }

  /**
   * Turn a crewed train round where it stands, to work back along its beat the other way. On double track (0.8.0) it
   * crosses over to the other track as it does (the user, 4 Nov 2026: hired trains keep to the correct side), and
   * waits where it is while the other track there is taken. False while it waits.
   */
  crewTurn(tr: Train): boolean {
    const f0 = tr.trail[0];
    if (f0 && f0.t.p.oneWay && !allowed(f0.t, f0.b, (-f0.d) as 1 | -1)) return this.crewCross(tr);
    return this.crewTurnPlain(tr);
  }

  /** A crewed train on a one-way track turning round: laid on the other track at the same place, facing its way. */
  private crewCross(tr: Train): boolean {
    // the new front is the old last car's end, on the other track
    let left = tr.length, back: { t: Track; s: number } | null = null;
    for (const p of tr.trail) { const len = Math.abs(p.b - p.a); if (left <= len) { back = { t: p.t, s: p.b - p.d * left }; break; } left -= len; }
    back ??= pointBehind(tr, tr.length);
    const ts = back ? twinS(back.t, back.s) : null;
    const tw = back?.t.twin;
    if (!back || ts === null || !tw || !tw.p.oneWay) {
      // (no other track here, a crossover or a stub: it turns round where it is, as on single track)
      return this.crewTurnPlain(tr);
    }
    const ghost = { ...tr, trail: [] as Piece[] } as Train;
    this.layTrail(ghost, { t: tw, s: ts, dir: tw.p.oneWay });
    if (!ghost.trail.length) return false;
    // never onto track another train is on or holds, nor just ahead of one coming up it
    const lo = (p: Piece) => Math.min(p.a, p.b), hi = (p: Piece) => Math.max(p.a, p.b);
    // never onto track another train stands on; nor into a run held by one close enough behind that it couldn't stop
    // for it (one further back up the line just stops behind it, as for any train ahead)
    sampleAt(ghost.trail[0].t, ghost.trail[0].b, tmpC);
    const close = (o: Train) => { const f = o.trail[0]; if (!f) return false; sampleAt(f.t, f.b, tmpB); return Math.hypot(tmpB.x - tmpC.x, tmpB.z - tmpC.z) < tr.length + 60; };
    const taken = this.trains.filter((o) => o !== tr && (
      o.trail.some((p) => ghost.trail.some((q) => q.t === p.t && hi(q) + HEADWAY * 2 >= lo(p) && lo(q) - HEADWAY * 2 <= hi(p)))
      || (close(o) && o.run.some((r) => ghost.trail.some((q) => q.t === r.t && hi(q) + HEADWAY >= r.lo && lo(q) - HEADWAY <= r.hi)))));
    if (taken.length) {
      // stood a while for it: the CPU trains in the way asked to make way, as your own train asks with K
      if (tr.crew && (tr.crew.crossTries = (tr.crew.crossTries ?? 0) + 1) > 20) for (const o of taken) this.makeWay(o);
      tr.state = 'wait'; tr.v = 0; tr.holdFor = 1; tr.why = 'waiting to cross over';
      return false;
    }
    this.release(tr);
    if (tr.nextBerth && this.berths.get(tr.nextBerth.key) === tr.id) this.berths.delete(tr.nextBerth.key);
    tr.nextBerth = null;
    tr.backing = null;
    tr.trail = ghost.trail;
    tr.flipped = !tr.flipped;
    tr.crossed = { gone: 0 };
    if (tr.crew) tr.crew.crossTries = 0;
    return this.settleTurn(tr);
  }

  private crewTurnPlain(tr: Train): boolean {
    this.release(tr);
    if (tr.nextBerth && this.berths.get(tr.nextBerth.key) === tr.id) this.berths.delete(tr.nextBerth.key);
    tr.nextBerth = null;
    tr.backing = null;
    this.flip(tr);
    return this.settleTurn(tr);
  }

  private settleTurn(tr: Train): boolean {
    tr.choices.clear();
    // (turned back short of the edge, buffers or a long wait: the far run is off for now, tried again next time there)
    if (tr.crew) tr.crew.out = undefined;
    tr.v = 0;
    tr.state = 'wait';
    tr.stood = 0; tr.faceoff = 0;
    if (tr.crew) { tr.crew.backed = false; tr.crew.look = 2; }
    tr.to = this.crewBound(tr);
    this.stats.crewTurns++;
    return true;
  }

  /** The crewed trains on the same connected track as this one, found by walking the network out from it. */
  crewOnNetwork(t0: Track): Train[] {
    const seen = new Set<Track>([t0]);
    const todo = [t0];
    // (a turnout is kept on the track it leaves, so a track is joined to the tracks its turnouts lead to, and to those leading to it)
    const into = new Map<Track, Track[]>();
    for (const t of this.net.tracks.values()) for (const sw of t.switches) { const l = into.get(sw.to) ?? []; l.push(t); into.set(sw.to, l); }
    while (todo.length) {
      const t = todo.pop()!;
      const near: Track[] = [...t.switches.map((sw) => sw.to), ...(into.get(t) ?? [])];
      for (const atEnd of [false, true]) { const nx = this.net.next(t, atEnd); if (nx) near.push(nx.t); }
      for (const q of near) if (!seen.has(q)) { seen.add(q); todo.push(q); }
    }
    return this.trains.filter((tr) => tr.crew && tr.trail.some((p) => seen.has(p.t)));
  }

  // ---- stand-ins for far runs (docs/crewtrains.html, Long haul) ----

  private phantoms = new Map<string, Train>();

  /** A stand-in for one of this player's own crewed trains away on a far run (railCrew keys those `me:<uid>`). */
  minePhantom(tr: Train): boolean {
    if (!tr.phantom) return false;
    for (const [k, t] of this.phantoms) if (t === tr) return k.startsWith('me:');
    return false;
  }

  /**
   * The stand-in for a fleet's train on a far run, its front at `front` facing its way (null: gone from here). Laid on
   * the track afresh each time it is moved, so it follows the line whatever the clock does; a CPU train it runs into
   * (it never waits) comes off the line, as ambient trains come and go.
   */
  phantom(key: string, spec: { ids: string[]; era: RailEra; freight: boolean; paint?: [number, number]; name: string; to: string; what: string; seed: number }, front: Loc | null, v: number): Train | null {
    let tr = this.phantoms.get(key);
    if (tr && !this.trains.includes(tr)) { this.phantoms.delete(key); tr = undefined; }
    if (!front) { if (tr) { this.remove(tr); this.phantoms.delete(key); } return null; }
    if (!tr) {
      tr = this.make(spec.ids, spec.era, spec.freight, false, spec.seed, spec.paint);
      tr.phantom = { what: spec.what };
      tr.name = spec.name;
      this.phantoms.set(key, tr);
    }
    tr.to = spec.to;
    tr.v = v;
    tr.state = v > 0.05 ? 'run' : 'dwell';
    this.layTrail(tr, front);
    const lo = (p: Piece) => Math.min(p.a, p.b), hi = (p: Piece) => Math.max(p.a, p.b);
    for (const o of [...this.trains]) {
      if (o === tr || o.player || o.crew || o.phantom) continue;
      if (o.trail.some((p) => tr!.trail.some((q) => q.t === p.t && hi(q) + 1 >= lo(p) && lo(q) - 1 <= hi(p)))) { this.stats.gaveWay++; this.noteGaveUp(`${o.name}: off the line for a far-run train`); this.remove(o); }
    }
    return tr;
  }

  /** Every stand-in's key, for the callers to drop the ones they no longer keep. */
  phantomKeys(): string[] { return [...this.phantoms.keys()]; }
  /** The stand-in drawn under a key, if it is. */
  phantomOf(key: string): Train | null { const tr = this.phantoms.get(key); return tr && this.trains.includes(tr) ? tr : null; }

  // ---- the player's train ----

  /** Build the player's set on the nearest track to a global point, pointed toward the nearest station. */
  placePlayer(set: TrainSet, gx: number, gz: number, range: number, seed: number, producers?: string[]): Train | null {
    const near = this.net.nearest(gx, gz, range, !!set.rack);
    if (!near) return null;
    const rng = mulberry32(seed);
    const ids = set.freight ? fillSet(set, rng, producers) : set.cars;
    const tr = this.make(ids, set.era, set.freight, true, seed);
    tr.vMax = set.topSpeed;
    tr.accel = set.accel;
    tr.name = set.name;
    // face the nearer station, if one is in memory ahead either way; on double track (0.8.0), on the track that runs
    // that way, beside the one it was put by if that runs the other
    const startOf = (d: 1 | -1): Loc => {
      const t = near.loc.t;
      if (allowed(t, near.loc.s, d) || !t.twin) return { ...near.loc, dir: d };
      sampleAt(t, near.loc.s, tmpA);
      const q = t.twin.p;
      let bs = 0, bd = Infinity;
      for (let i = 0; i < q.s.length; i++) {
        const dd = Math.hypot(t.twin.w.ox + q.xz[i * 2] - tmpA.x, t.twin.w.oz + q.xz[i * 2 + 1] - tmpA.z);
        if (dd < bd) { bd = dd; bs = q.s[i]; }
      }
      return { t: t.twin, s: bs, dir: d };
    };
    let dir: 1 | -1 = 1, best = Infinity;
    for (const d of [1, -1] as const) {
      this.walk(startOf(d), 1500, tr, (t, s0, s1, dist) => {
        for (const { st, loop } of t.stations) {
          if (loop || st.passing) continue;
          const lo = Math.min(s0, s1), hi = Math.max(s0, s1);
          if (st.s0 <= hi && st.s1 >= lo && dist < best) { best = dist; dir = d; }
        }
        return false;
      });
    }
    this.layTrail(tr, startOf(dir));
    if (!tr.trail.length) { this.remove(tr); return null; }
    return tr;
  }

  /** The stations ahead of a train in memory, nearest first, with distances. */
  stationsAhead(tr: Train, max = 1200): { name: string; kind: string; d: number }[] {
    const out: { name: string; kind: string; d: number }[] = [];
    const f = tr.trail[0];
    if (!f) return out;
    const seen = new Set<string>();
    this.walk({ t: f.t, s: f.b, dir: f.d }, max, tr, (t, s0, s1, dist) => {
      for (const { st, loop } of t.stations) {
        if (loop || st.passing || seen.has(st.name)) continue;
        const mid = (st.s0 + st.s1) / 2;
        const lo = Math.min(s0, s1), hi = Math.max(s0, s1);
        if (mid < lo || mid > hi) continue;
        const d = dist + Math.abs(mid - s0);
        if (d < 2) continue;
        seen.add(st.name);
        out.push({ name: st.name, kind: st.kind, d });
      }
      return false;
    });
    return out;
  }

  /**
   * Every station on a train's line within `max` tiles either way, by how far along the way it faces
   * its platform's middle lies: ahead of the front positive, behind it (the train's own length and
   * back down the line) negative. Forward follows the turnouts the train would take.
   */
  lineOrder(tr: Train, max = 1200): Map<RailStation, number> {
    const out = new Map<RailStation, number>();
    const f = tr.trail[0];
    if (!f) return out;
    for (const dir of [f.d, -f.d as 1 | -1]) {
      this.walk({ t: f.t, s: f.b, dir }, max, tr, (t, s0, s1, dist) => {
        for (const { st, loop } of t.stations) {
          // (a second track's platform is its station's: the cards know the station by the one in w.stations)
          const real = st.of ?? st;
          if (loop || st.passing || out.has(real)) continue;
          const mid = (st.s0 + st.s1) / 2;
          if (mid < Math.min(s0, s1) || mid > Math.max(s0, s1)) continue;
          const d = dist + Math.abs(mid - s0);
          out.set(real, dir === f.d ? d : -d);
        }
        return false;
      });
    }
    return out;
  }

  /** The next turnout ahead a train could take, within `max` tiles. */
  switchAhead(tr: Train, max = 40): { sw: Switch; d: number } | null {
    const f = tr.trail[0];
    if (!f) return null;
    let found: { sw: Switch; d: number } | null = null;
    let { t, s, dir } = { t: f.t, s: f.b, dir: f.d };
    let dist = 0;
    for (let guard = 0; guard < 8 && dist < max && !found; guard++) {
      const end = dir > 0 ? t.p.length : 0;
      let best: Switch | null = null, bestA = Math.abs(end - s);
      for (const sw of t.switches) {
        if (sw.dir !== dir) continue;
        const a = (sw.s - s) * dir;
        if (a > 1e-6 && a < bestA) { bestA = a; best = sw; }
      }
      if (best) { if (dist + bestA <= max) found = { sw: best, d: dist + bestA }; break; }
      dist += Math.abs(end - s);
      const nx = this.net.next(t, dir > 0);
      if (!nx) break;
      ({ t, s, dir } = nx);
    }
    return found;
  }

  /** The card for whichever train is under the pointer: its name, what it is made of, where it is bound and what it is doing. */
  cardAt(mx: number, my: number, camera: THREE.Camera): { key: string; html: string } | null {
    const W = window.innerWidth, H = window.innerHeight;
    let best: Train | null = null, bestD = 30;
    const v = new THREE.Vector3();
    for (const tr of this.trains) {
      for (const c of tr.cars) {
        if (!c.mesh || !c.mesh.group.visible) continue;
        v.copy(c.mesh.group.position).project(camera);
        if (v.z > 1) continue;
        const d = Math.hypot(((v.x + 1) / 2) * W - mx, ((1 - v.y) / 2) * H - my);
        if (d < bestD) { bestD = d; best = tr; }
      }
    }
    if (!best) return null;
    const tr = best as Train;
    const esc = (s: string) => s.replace(/[&<>]/g, (ch) => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;' }[ch]!));
    const d = this.describe(tr);
    // a glance only (the user, 2 Nov 2026): what it is, where it is headed, and what it is doing if that is news;
    // the line, where it came from and the rest are in its card a click away
    // (a train named for its load, "Freight, 6 wagons", isn't told twice: just what kind it is)
    const short = /wagon|coach/i.test(tr.name) ? d.what.replace(/ · \d+ (wagons|coaches)$/, '') : d.what.replace(/ passenger · /, ' · ');
    const icon = tr.era === 'steam' ? '🚂' : tr.freight ? '🚋' : '🚆';
    const doing = d.doing && d.doing !== 'Running' ? d.doing : '';
    const html = `<header class="tt"><span class="ic">${icon}</span><b>${esc(tr.name)}</b></header>`
      + `<div class="tt-what">${esc(short)}</div>`
      + (tr.to ? `<div class="tt-to">→ ${esc(tr.to)}</div>` : '')
      + (doing ? `<div class="tt-doing">${esc(doing)}</div>` : '')
      + '<div class="tt-more">Click for details</div>';
    return { key: `train${tr.id}|${tr.state}|${tr.stop?.station.name ?? ''}`, html };
  }

  /** A train in words: what it is, the line it is on, and what it is doing. */
  describe(tr: Train): { what: string; line: string; doing: string } {
    const coaches = tr.cars.filter((c) => { const r = CARS[c.id]?.role; return r === 'coach' || r === 'observation'; }).length;
    const wagons = tr.cars.filter((c) => CARS[c.id]?.role === 'wagon').length;
    const period = tr.era === 'steam' ? 'Steam' : tr.era === 'streamline' ? 'Streamliner' : 'Modern';
    const what = tr.player ? 'Your train' : tr.phantom ? tr.phantom.what : tr.crew ? `Your fleet · ${tr.crew.driver} at the regulator` : tr.special ? [SPECIALS[tr.special].what, SPECIALS[tr.special].by].filter(Boolean).join(' · ')
      : tr.freight ? `${period} freight · ${wagons} wagons` : `${period} passenger · ${coaches} coaches`;
    const doing = tr.player ? '' : tr.state === 'dwell' ? `Calling at ${tr.called}` : tr.state === 'wait' || (tr.v < 0.05 && tr.why) ? 'Waiting for the line' : tr.stop ? `Next stop ${tr.stop.station.name}` : 'Running';
    return { what, line: tr.trail[0]?.t.p.name ?? '', doing };
  }

  /** Console: one line per train. */
  list(): string[] {
    return this.trains.map((t) => `${t.id} ${t.name} (${t.era}${t.player ? ', yours' : ''}) ${t.state}${t.why ? ` [${t.why}]` : ''} v=${t.v.toFixed(2)} to ${t.to}${t.ahead ? ` · ${t.ahead.opposing ? 'facing' : 'behind'} ${t.ahead.name} ${t.ahead.d.toFixed(0)}t` : ''} · ${t.trail[0]?.t.w.name ?? '?'}`);
  }

  /** Where a train's middle is, in global tiles. */
  middle(tr: Train): { x: number; y: number; z: number } | null {
    const m = pointBehind(tr, tr.length / 2);
    if (!m) return null;
    sampleAt(m.t, m.s, tmpA);
    return { x: tmpA.x, y: tmpA.y, z: tmpA.z };
  }
}


/** What a cell makes, as words the wagon table's "from" column uses. */
export function producersOf(w: World): string[] {
  const out = new Set<string>();
  if (w.region) out.add(w.region);
  for (const g of w.works) out.add(g.kind);
  if (w.ports.some((p) => p.major)) out.add('port');
  for (const b of w.countryside) out.add(b.kind);
  for (const t of w.towns) for (const b of t.buildings) if (b.kind === 'factory' || b.kind === 'brewery' || b.kind === 'sawmill' || b.kind === 'silo' || b.kind === 'farmhouse' || b.kind === 'powerPlant') out.add(b.kind);
  return [...out];
}

// ---------------------------------------------------------------------------------------------
// the train you drive

interface RailStats {
  topSpeed: number; accel: number; brake: number; coast: number; reverseCap: number; weight: number;
  /** The cog engine: held on the rack, so the grade barely touches it. */
  rack?: boolean;
  /** A cab at each end: the rear cab drives at full speed. */
  twinCab?: boolean;
}

/** Driven from the rear of a train with one cab, the engine pushes: this share of its top speed. */
const PROPEL = 0.5;

/**
 * The player's train as a vehicle: the same controller the CPU uses, with the keys in place of the route.
 * W and S move the throttle lever (the user, 2 Nov 2026): it stays where it is left, from full ahead down
 * through stop into reverse, and the train runs at the speed it is set to; A takes the branch to the left at
 * the next turnout, D the one to the right. Its x, z are the engine's, in the frame of the island the player is
 * on, like any vehicle's.
 */
export class TrainState implements VehicleState {
  x = 0; y = 0; z = 0; heading = 0; v = 0;
  pitch = 0; roll = 0; bob = 0; lean = 0; wheelSpin = 0; steerVis = 0;
  power = 0; blocked = 0; trailerHeading = 0; sailAngle = 0; surfaceY = NaN;
  /** Trains don't crash into things; these are here so main.ts can treat every ride alike. */
  impact: Impact | null = null; scrape = 0;
  grade = 0;
  note = '';
  /** The throttle lever, −1 (full reverse) to 1 (full ahead): the share of top speed (or reverse speed) asked for. */
  lever = 0;
  /**
   * Driven from the other end (the user, 7 Nov 2026: "there isn't an option to change the front"): ahead is away
   * from the engine, and the camera rides the last car. `v` is always along the way the driver faces.
   */
  cabRear = false;
  constructor(public stats: RailStats, public train: Train, private trains: Trains, w: World) { this.readPose(w); }

  step(w: World, c: Controls, dt: number): void {
    const tr = this.train;
    if (!tr.trail.length) { this.v = 0; return; }
    const s = this.stats;
    // A and D: which branch at the next turnout (shown on the HUD from forty tiles out); A steers left (+1)
    if (c.steer !== 0) tr.prefer = c.steer > 0 ? 1 : -1;
    // W and S move the lever, which stays put: a second or two from stop to full either way
    if (c.stop) this.lever = 0;
    else if (c.throttle !== 0) this.lever = Math.max(-1, Math.min(1, this.lever + Math.sign(c.throttle) * LEVER_RATE * dt));
    const sw = this.trains.switchAhead(tr, 40);
    if (!sw) tr.prefer = 0;
    // grade from the front car
    const f = tr.trail[0];
    sampleAt(f.t, f.b, tmpA);
    const back = pointBehind(tr, Math.min(3, tr.length));
    this.grade = 0;
    if (back) {
      sampleAt(back.t, back.s, tmpB);
      const run = Math.hypot(tmpA.x - tmpB.x, tmpA.z - tmpB.z);
      if (run > 0.5) this.grade = (tmpA.y - tmpB.y) / STEP / run;
    }
    // along the way the driver faces, whichever way the trail is running
    const face = this.cabRear ? -1 : 1;
    const g = (tr.flipped ? -this.grade : this.grade) * face;
    // from the rear of a train with one cab the engine pushes, at half its speed
    let cap = this.cabRear && !s.twinCab ? s.topSpeed * PROPEL : s.topSpeed;
    // the cog engine is held on the rack: the grade barely touches it
    const cog = s.rack ? 0.1 : 1;
    if (g > 0) cap *= 1 - Math.min(0.5, 0.3 * cog * g / (1 / 6));
    let a = -G * g * s.weight * cog;
    const v = this.v;
    // the speed the lever asks for: ahead, a share of what the grade allows; astern, of reverse's own cap
    const want = this.lever >= 0 ? this.lever * cap : this.lever * s.reverseCap;
    const off = want - v;
    if (Math.abs(off) < HOLD) a = off / Math.max(dt, 1e-3);   // there: held at it, whatever the grade
    else if (off > 0) a += v < -0.05 ? s.brake : s.accel;       // faster ahead, or braking a reverse
    else a += v > 0.05 ? -s.brake : -s.accel * 0.6;            // slower, to a stop, then astern
    // the soft limit through a loop or over a turnout, and never into another train
    this.note = '';
    const front = tr.trail[0];
    if (front.t.p.kind === 'loop' && Math.abs(v) > LOOP_SPEED) { a = Math.min(a, -s.brake * 0.5); this.note = 'Easing through the loop'; }
    let nv = v + a * dt;
    if (this.lever === 0 && Math.abs(nv) < s.coast * dt && Math.abs(G * g * s.weight * cog) < s.coast) nv = 0;
    nv = Math.max(-s.reverseCap, Math.min(cap * 1.05, nv));
    // what is ahead in the direction of travel (the trail runs engine first unless flipped)
    const ve = nv * face;
    if (ve < 0 && !tr.flipped) this.trains.flip(tr);
    else if (ve > 0 && tr.flipped) this.trains.flip(tr);
    tr.ahead = null;
    const lead = tr.trail[0];
    let gap = Infinity;
    this.trains.walk({ t: lead.t, s: lead.b, dir: lead.d }, 12 + nv * nv, tr, (t, s0, s1, dist) => {
      const lo = Math.min(s0, s1), hi = Math.max(s0, s1), dir = s1 >= s0 ? 1 : -1;
      for (const o of this.trains.trains) {
        if (o === tr) continue;
        for (const p of o.trail) {
          if (p.t !== t) continue;
          const plo = Math.min(p.a, p.b), phi = Math.max(p.a, p.b);
          if (phi < lo || plo > hi) continue;
          const d = dist + Math.abs((dir > 0 ? Math.max(lo, plo) : Math.min(hi, phi)) - s0);
          if (d < gap) { gap = d; tr.ahead = { name: o.name, d, opposing: p.d !== dir, id: o.id }; }
        }
      }
      return false;
    });
    if (gap < 1.5 && Math.abs(nv) > 0) { nv = 0; this.blocked = 0.25; }
    else if (gap < 1.5 + nv * nv) nv = Math.sign(nv) * Math.min(Math.abs(nv), Math.sqrt(Math.max(0, 2 * s.brake * (gap - 1.5))));
    this.v = nv;
    tr.v = Math.abs(nv);
    const res = this.trains.advance(tr, Math.abs(nv) * dt);
    if (res !== 'ok') { this.v = 0; tr.v = 0; this.note = res === 'edge' ? 'The line runs on beyond the map' : 'End of the line'; }
    this.blocked = Math.max(0, this.blocked - dt);
    this.power = Math.min(1, Math.abs(this.v) / cap);
    this.wheelSpin += this.v * dt / 0.05;
    this.readPose(w);
    // the player's run, held so no CPU train takes it head on: while it runs, the way on to the next passing place
    this.trains.holdLine(tr, Math.abs(this.v) > 0.05 || Math.abs(this.lever) > 0.05, this.v);
  }

  /** The line ahead for the HUD, read again twice a second (Trains.lineAhead). */
  private line: { t: number; clearTo: string | null; coming: string | null; d: number } | null = null;

  /**
   * Stood still, the driver can walk to the other end of the train (the HUD's Change ends button): ahead becomes
   * the other way, at full speed with a cab there, at half pushing with the engine behind. False while it moves.
   */
  changeEnds(w: World): boolean {
    if (!this.endsReady()) return false;
    this.cabRear = !this.cabRear;
    this.lever = 0;
    this.v = 0;
    this.readPose(w);
    return true;
  }

  /** Stood still: Change ends is offered. */
  endsReady(): boolean { return Math.abs(this.v) < 0.05 && this.train.trail.length > 0; }

  /** The cab's pose (the engine's, or the last car's driven from the rear), in the frame of the island the player is on. */
  private readPose(w: World): void {
    const tr = this.train;
    const eng = this.cabRear ? tr.cars[tr.cars.length - 1] : tr.cars[0];
    if (!eng) return;
    const d = tr.flipped ? tr.length - eng.offset : eng.offset;
    const a = pointBehind(tr, Math.max(0, d - eng.bogie)), b = pointBehind(tr, d + eng.bogie);
    if (!a || !b) return;
    sampleAt(a.t, a.s, tmpA);
    sampleAt(b.t, b.s, tmpB);
    // a is the end nearer the trail's head: that is the cab's nose when the trail runs the way the cab faces
    const back = tr.flipped !== this.cabRear;
    const fx = back ? tmpB : tmpA, rx = back ? tmpA : tmpB;
    this.x = (tmpA.x + tmpB.x) / 2 - w.ox;
    this.z = (tmpA.z + tmpB.z) / 2 - w.oz;
    this.y = (tmpA.y + tmpB.y) / 2;
    this.heading = Math.atan2(fx.x - rx.x, fx.z - rx.z);
    this.pitch = -Math.atan2(fx.y - rx.y, Math.hypot(fx.x - rx.x, fx.z - rx.z) || 1);
  }

  status(): string {
    const tr = this.train;
    const parts: string[] = [];
    const L = Math.round(Math.abs(this.lever) * 100);
    parts.push(this.lever > 0 ? `Throttle ${L}%` : this.lever < 0 ? `Reverse ${L}%` : 'Throttle stop · W/S');
    if (this.cabRear) parts.push(this.stats.twinCab ? 'Rear cab' : 'Rear cab, pushing at half speed');
    const g = (tr.flipped ? -this.grade : this.grade) * (this.cabRear ? -1 : 1);
    if (Math.abs(g) > 0.02) parts.push(`${g > 0 ? '▲' : '▼'} 1 in ${Math.max(2, Math.round(1 / Math.abs(g)))}`);
    else parts.push('— level');
    const next = this.trains.stationsAhead(tr, 1500)[0];
    const sw = this.trains.switchAhead(tr, 40);
    if (sw) parts.push(`${tr.prefer === 0 ? '↑ straight on' : tr.prefer > 0 ? '↖ branch left' : '↗ branch right'} · A/D`);
    // the line ahead (the user, 3 Nov 2026): clear to the next passing place, or who is coming the other way
    const now = performance.now();
    if (!this.line || now - this.line.t > 500) this.line = { t: now, ...this.trains.lineAhead(tr) };
    const ln = this.line;
    if (ln.coming) parts.push(`${ln.coming} coming the other way, ${Math.round(ln.d)}t · K: ask it to give way`);
    else if (this.note) parts.push(this.note);
    else if (ln.clearTo) parts.push(`Line clear to ${ln.clearTo}`);
    // the next station on a line of its own, its name kept in one piece (the HUD keeps the line break)
    return next ? `${parts.join(' · ')}\n${next.name.replace(/ /g, '\u00a0')}\u00a0${Math.round(next.d)}t` : parts.join(' · ');
  }
}
