import { N, Biome, DIRS, Flag, World, idx, inB, tileMean, type Building, type Landmark } from './tiles';
import { hashCell, mulberry32 } from './rng';
import { landformName } from './landforms';
import { put } from './beachfront';
import { WOOD_KINDS } from './woods';

/**
 * Rich enclaves (0.8.0, NEXT_080, docs/phonelist.html item 16): where the money lives. Near a city, a cluster of
 * estates on big lots, each an estate house in one of ten styles on its grounds (render/buildings/k080.ts), lanes
 * winding in to each from the road and a gatehouse on the way in. Three forms, by what is there to build round:
 *
 *   the fairway   estates backing onto a town's golf course
 *   the hillside  estates up the high ground over a city, the biggest at the top
 *   the gold coast  a megalopolis's rich edge on open ground, by the water where it can be
 *
 * Placed once the county is finished (generate.ts, before the roads are joined up for the last time), on a stream of its
 * own, so nothing else moves. A 'enclave' landmark names it ("Kestrel Heights") on the map and the labels.
 */

const SALT = 0xe5c1;
/** Out of every hundred counties with a city, how many have an enclave. */
const CHANCE = 0.3;
const LOT = 3;
/** How many estates an enclave holds, at most, and the fewest worth naming. */
const MAX_ESTATES = 12, MIN_ESTATES = 5;
/** How far out from its anchor an enclave's estates spread. */
const SPREAD = 16;

export type EnclaveForm = 'fairway' | 'hillside' | 'goldCoast';
const SUFFIX: Record<EnclaveForm, string[]> = { fairway: ['Country Club Estates', 'Fairways', 'Links Estates'], hillside: ['Heights', 'Hills', 'Ridge'], goldCoast: ['Park', 'Estates', 'Shores'] };

/** Lay the county's enclave, if it has one. Returns its name, or null. */
export function placeEnclave(w: World, seedHash: number, lane: (gate: number) => void): string | null {
  if (hashCell(seedHash, w.cx, w.cz, SALT) / 4294967296 >= CHANCE) return null;
  const cities = w.towns.filter((t) => t.kind === 'city' || t.kind === 'metro' || t.kind === 'mega');
  if (!cities.length) return null;
  const rng = mulberry32(hashCell(seedHash, w.cx, w.cz, SALT + 1));
  const open = (i: number) => !w.road[i] && !w.rail[i] && !w.blocked[i] && w.townId[i] < 0 && w.water[i] < 0 && !w.lot[i] && w.portId[i] < 0
    && w.biome[i] !== Biome.Town && w.biome[i] !== Biome.Farm && w.biome[i] !== Biome.Snow
    && !(w.flags[i] & (Flag.Poi | Flag.Field | Flag.Track | Flag.Ramp | Flag.Corridor | Flag.River | Flag.Stream));
  const lotOk = (x: number, z: number) => {
    let lo = 127, hi = -128;
    for (let zz = z - 1; zz < z + LOT + 1; zz++) for (let xx = x - 1; xx < x + LOT + 1; xx++) {
      if (!inB(xx, zz)) return false;
      const i = idx(xx, zz);
      // the lot itself open and level; a tile of margin round it kept off buildings and water
      if (xx >= x && xx < x + LOT && zz >= z && zz < z + LOT) {
        if (!open(i)) return false;
        for (let q = 0; q < 4; q++) { const c = w.corners[i * 4 + q]; lo = Math.min(lo, c); hi = Math.max(hi, c); }
      } else if (w.blocked[i] || w.water[i] >= 0) return false;
    }
    return hi - lo <= 1;
  };
  const edgeDist = (x: number, z: number, t: { x0: number; z0: number; size: number }) =>
    Math.max(t.x0 - x, 0, x - (t.x0 + t.size), t.z0 - z, 0, z - (t.z0 + t.size));
  // the anchor: a golf course near a city, else high ground over one, else a megalopolis's open edge
  let form: EnclaveForm | null = null, ax = 0, az = 0;
  const golf = w.allBuildings.find((b) => !b.gone && b.kind === 'golfCourse' && cities.some((t) => edgeDist(b.x, b.z, t) <= 30));
  if (golf) { form = 'fairway'; ax = golf.x + golf.w / 2; az = golf.z + golf.d / 2; }
  if (!form) {
    let best = -Infinity;
    for (let z = 10; z < N - 10; z += 3) for (let x = 10; x < N - 10; x += 3) {
      const i = idx(x, z);
      if (!open(i) || (w.biome[i] !== Biome.Hills && w.biome[i] !== Biome.Forest && w.biome[i] !== Biome.Plains)) continue;
      const d = Math.min(...cities.map((t) => edgeDist(x, z, t)));
      if (d < 6 || d > 30) continue;
      const lift = tileMean(w, i) - Math.min(...cities.map((t) => tileMean(w, idx(Math.min(N - 1, t.x0 + (t.size >> 1)), Math.min(N - 1, t.z0 + (t.size >> 1))))));
      if (lift < 4) continue;
      const score = lift - d * 0.15 + rng();
      if (score > best) { best = score; form = 'hillside'; ax = x; az = z; }
    }
  }
  if (!form) {
    const mega = cities.find((t) => t.kind === 'mega' || t.kind === 'metro');
    if (mega) {
      let best = -Infinity;
      for (let z = 10; z < N - 10; z += 3) for (let x = 10; x < N - 10; x += 3) {
        const i = idx(x, z);
        if (!open(i)) continue;
        const d = edgeDist(x, z, mega);
        if (d < 5 || d > 26) continue;
        const score = -Math.abs(w.coastDist[i] - 6) * 0.3 - d * 0.1 + rng();
        if (score > best) { best = score; form = 'goldCoast'; ax = x; az = z; }
      }
    }
  }
  if (!form) return null;
  if (w.landmarks.some((l) => Math.hypot(l.x - ax, l.z - az) < Math.min(l.r, 40) + 8 && l.kind !== 'wood')) return null;
  // and clear of a headland park, which is a wood too but a place of its own: it would sprawl into it (scripts/woods.ts)
  if (w.landmarks.some((l) => l.kind === 'wood' && WOOD_KINDS[l.data?.[0] ?? -1] === 'headland' && Math.hypot(l.x - ax, l.z - az) < l.r + SPREAD + 2)) return null;
  // the lots: the best spots round the anchor, kept a tile apart; on a hill, the highest first
  const spots: { x: number; z: number; score: number }[] = [];
  for (let z = Math.floor(az - SPREAD); z <= az + SPREAD; z++) {
    for (let x = Math.floor(ax - SPREAD); x <= ax + SPREAD; x++) {
      if (!inB(x, z) || !inB(x + LOT, z + LOT)) continue;
      const d = Math.hypot(x + 1.5 - ax, z + 1.5 - az);
      if (d > SPREAD || (form === 'fairway' && golf && d < Math.max(golf.w, golf.d) / 2)) continue;
      if (!lotOk(x, z)) continue;
      const score = form === 'hillside' ? tileMean(w, idx(x + 1, z + 1)) * 2 - d * 0.2 : -d + rng() * 3;
      spots.push({ x, z, score });
    }
  }
  spots.sort((a, b) => b.score - a.score);
  const estates: Building[] = [];
  for (const s of spots) {
    if (estates.length >= MAX_ESTATES) break;
    if (estates.some((e) => s.x < e.x + LOT + 1 && s.x + LOT + 1 > e.x && s.z < e.z + LOT + 1 && s.z + LOT + 1 > e.z)) continue;
    if (!lotOk(s.x, s.z)) continue;
    // facing the way the road is likeliest to come from: back toward the anchor's city
    const t = cities.reduce((a, b) => (edgeDist(s.x, s.z, a) < edgeDist(s.x, s.z, b) ? a : b));
    const dx = t.x0 + t.size / 2 - (s.x + 1.5), dz = t.z0 + t.size / 2 - (s.z + 1.5);
    const facing = Math.abs(dx) > Math.abs(dz) ? (dx > 0 ? 0 : 2) : dz > 0 ? 1 : 3;
    const b = put(w, rng, 'estateHouse', s.x, s.z, LOT, LOT, facing);
    if (b) estates.push(b);
  }
  if (estates.length < MIN_ESTATES) {
    // too few to be an enclave: take them down again (they were put last, so nothing else refers to them yet)
    for (const b of estates) {
      b.gone = true;
      for (let z = b.z; z < b.z + b.d; z++) for (let x = b.x; x < b.x + b.w; x++) { const i = idx(x, z); w.blocked[i] = 0; w.flags[i] &= ~Flag.Poi; w.roof[i] = 0; }
    }
    return null;
  }
  // a lane from each estate's gate to the road, the nearest first so the later ones join the earlier ones' lanes
  const gates = estates.map((b) => {
    const [fx, fz] = DIRS[b.facing];
    return { b, x: Math.round(b.x + 1 + fx * 2), z: Math.round(b.z + 1 + fz * 2) };
  }).filter((g) => inB(g.x, g.z));
  const roadDist = (x: number, z: number) => {
    for (let r = 0; r < 40; r++) for (let dz = -r; dz <= r; dz++) for (let dx = -r; dx <= r; dx++) {
      if (Math.max(Math.abs(dx), Math.abs(dz)) !== r || !inB(x + dx, z + dz)) continue;
      if (w.road[idx(x + dx, z + dz)]) return r;
    }
    return 40;
  };
  gates.sort((a, b) => roadDist(a.x, a.z) - roadDist(b.x, b.z));
  for (const g of gates) if (!w.blocked[idx(g.x, g.z)]) lane(idx(g.x, g.z));
  // the gatehouse beside the first lane, by the road
  const first = gates[0];
  if (first) {
    for (const [dx, dz] of [[1, 0], [-1, 0], [0, 1], [0, -1], [1, 1], [-1, -1]]) {
      const x = first.x + dx, z = first.z + dz;
      if (inB(x, z) && open(idx(x, z)) && put(w, rng, 'gatehouse', x, z, 1, 1, first.b.facing)) break;
    }
  }
  const word = landformName('wood', seedHash ^ SALT, w.ox + ax, w.oz + az);
  const suffix = SUFFIX[form][Math.floor(rng() * SUFFIX[form].length)];
  let cx = 0, cz = 0;
  for (const b of estates) { cx += b.x + 1.5; cz += b.z + 1.5; }
  cx /= estates.length; cz /= estates.length;
  const r = Math.max(6, Math.max(...estates.map((b) => Math.hypot(b.x + 1.5 - cx, b.z + 1.5 - cz))) + 2);
  const l: Landmark = { kind: 'enclave', name: `${word} ${suffix}`, x: cx, z: cz, r, data: [['fairway', 'hillside', 'goldCoast'].indexOf(form)] };
  w.landmarks.push(l);
  return l.name;
}
