/**
 * The trailer's play-mode shots (scripts/film/play.mjs; the user, 11 Nov 2026: a city bought up building by building,
 * popping like popcorn into the fleet's yellow and black; the Books' charts growing day by day; the region map's Fleet
 * view full of routes). title/film.ts films only the title's world; these need a running game, so the shoot starts
 * one (pr.local('online')), stages it, holds the loop and steps it a frame at a time with pr.run(1, true).
 *
 * What lives here: the virtual clock (as film.ts: performance.now and Date.now move one frame a frame), a camera pose
 * applied after the follow camera each frame, and the popcorn (a bought building drawn on its own over the chunk,
 * bounced up and down while the chunk is drawn again in the livery under it, with a puff of paint flecks).
 */
import * as THREE from 'three';
import { STEP, type Arch, type Building, type BuildingKind, type Town, type World } from '../world/tiles';
import { KIND_SPEC } from '../world/townKinds';
import { RAIL_LIFT } from '../world/railPlan';
import { erectProblem, type ErectSpec } from '../world/erect';
import { ERECT_MAX_SIDE, erectHours } from '../../shared/erect';
import { Kit } from '../render/buildings/kit';
import { stadiumDesignOf } from '../world/stadiums';
import { ALL_VEHICLES, type VehicleDef } from '../game/vehicles';
import { applyParts, slotsFor, type Parts, type SlotId } from '../game/parts';
import { buildVehicleMesh, disposeVehicleMesh, type VehicleMesh } from '../render/vehicleMeshes';
import { drawBuilding } from '../render/townMesh';
import { propsOn } from '../render/props';

export interface PlayShootHost {
  scene: THREE.Scene;
  /** The group an island's meshes hang under (its place on the lattice). */
  groupOf(w: World): THREE.Group | null;
  islands(): { at(cx: number, cz: number): World | null; live: Map<unknown, World> | Iterable<World> } | null;
  /** A free deed on this building (estate.grant); null when given. */
  grant(w: World, b: Building): string | null;
  /** Paint every owned building now (the half-second badge gather, run at once) and queue their chunks. */
  repaint(): void;
  /** Build every chunk round a point now; how many are left. */
  warm(gx: number, gz: number): number;
  setCam(f: ((cam: THREE.PerspectiveCamera, dt: number) => void) | null): void;
  /** Planes' contrails on or off (off for the shoot: a low one streaked across the build shot). */
  contrails(on: boolean): void;
  setBand(focus: number, band: number): void;
  /** Lay steam track along points (x, z, y triples, the county's tiles) as the rail tool does; why not, or null. */
  rail(w: World, p: number[]): string | null;
  /** Take up the last track laid in a county. */
  unrail(w: World): boolean;
  /** Stand a building site from a spec (world/erect.ts), as a blueprint does, unpaid; why not, or null. */
  erect(w: World, spec: ErectSpec, big?: boolean): string | null;
  /** The ground height at a world point. */
  groundAt(x: number, z: number): number;
  /** Pedestrians kept off a rectangle of a county's tiles (local), or let back on (null). */
  keepOff(w: World, r: { x0: number; z0: number; x1: number; z1: number } | null): void;
}

type Pop = { pivot: THREE.Group; parent: THREE.Object3D; age: number; flecks: { m: THREE.Mesh; v: THREE.Vector3; spin: THREE.Vector3 }[] };

const DT = 1 / 60;
/** How long a building bounces, and how long its copy stays over the chunk (the chunk's redraw is queued). */
const POP_S = 0.5, HOLD_S = 2.4;

export class PlayShoot {
  private clock: { v: number; frame: number; epoch: number } | null = null;
  private pops: Pop[] = [];
  private fleckGeo = new THREE.BoxGeometry(1, 1, 1);
  private pose: { x: number; y: number; z: number; tx: number; ty: number; tz: number } | null = null;
  readonly log: string[] = [];
  /** The camera mode's clean shot without the camera mode: no rings, signs, mission pointers or fleet badges. */
  clean = false;
  /** The ridden vehicle keeps moving while a build tool is up (the game holds it still then): the Arrow pulling away as the buildings go down. */
  toolDrive = false;
  /** The camera's near plane while the shoot holds it (the game's 2 keeps it well back from a vehicle); null leaves it. */
  near: number | null = null;
  /** The camera's field of view (degrees) while the shoot holds it; null leaves the game's 18. */
  fov: number | null = null;

  constructor(private host: PlayShootHost) {}

  // ---- the clock ----

  /** From here performance.now() and Date.now() move a frame (1/60 s) a call to tick(). */
  clockOn(): void {
    this.host.contrails(false);
    if (this.clock) return;
    const real = performance.now.bind(performance), realDate = Date.now.bind(Date);
    const c = { v: real(), frame: real(), epoch: realDate() - real() };
    this.clock = c;
    performance.now = () => (c.v = Math.min(c.v + 0.0005, c.frame + 8));
    Date.now = () => Math.floor(c.epoch + performance.now());
  }
  tick(): void { if (this.clock) { this.clock.frame += DT * 1000; this.clock.v = this.clock.frame; } }

  private cam: THREE.PerspectiveCamera | null = null;
  /**
   * Where a world point (world units; y the ground's when left out) is on the page, in CSS pixels, as the camera last
   * posed sees it, so the shoot can move the real mouse there (the builder takes real clicks). z > 1: behind the camera.
   */
  screen(x: number, z: number, y?: number): { x: number; y: number; z: number } | null {
    const c = this.cam;
    if (!c) return null;
    c.updateMatrixWorld();
    const v = new THREE.Vector3(x, y ?? this.host.groundAt(x, z), z).project(c);
    return { x: ((v.x + 1) / 2) * innerWidth, y: ((1 - v.y) / 2) * innerHeight, z: v.z };
  }

  /**
   * A line of track in county (cx, cz) from tile (x0, z0) to (x1, z1), the one this shoot laid last taken up first: called
   * again and again with the end further on, the line grows a piece at a time (the rail tool's own carry-on start faces
   * back down the line and loops round, so the shoot lays the line whole each time instead). Why not, or null.
   */
  track(cx: number, cz: number, x0: number, z0: number, x1: number, z1: number): string | null {
    const w = this.host.islands()?.at(cx, cz);
    if (!w) return 'no county';
    // heights in steps, a little over the ground, as the rail tool gives them (world/railRoute.ts heightsOf, RAIL_LIFT from railPlan.ts)
    const pts = (ax: number, az: number, bx: number, bz: number) => [ax, az, this.host.groundAt(w.ox + ax, w.oz + az) / STEP + RAIL_LIFT, bx, bz, this.host.groundAt(w.ox + bx, w.oz + bz) / STEP + RAIL_LIFT];
    const was = this.laidTrack;
    if (was) this.host.unrail(w);
    const why = this.host.rail(w, pts(x0, z0, x1, z1));
    if (!why) { this.laidTrack = [x0, z0, x1, z1]; return null; }
    // refused: the line as it was put back
    if (was) this.host.rail(w, pts(...was));
    return why;
  }
  private laidTrack: [number, number, number, number] | null = null;

  /**
   * A site for a building of this kind on county (cx, cz)'s tiles from (x, z), facing f, sized and drawn as one already
   * standing somewhere in the live world (a stadium or a lido no fleet's plans can hold), going up under cranes from now:
   * each facing tried in turn until one has a road at its door. Why not, or null.
   */
  erectLike(cx: number, cz: number, kind: string, x: number, z: number, f = 0, style = 'newyork', design?: string): string | null {
    const isl = this.host.islands();
    const w = isl?.at(cx, cz);
    if (!isl || !w) return 'no county';
    // sized as one standing in the live world, else as the town kinds' table has it
    const all = [...(isl.live instanceof Map ? isl.live.values() : isl.live)];
    const like = all.flatMap((q) => q.allBuildings).find((b) => b.kind === kind && !b.gone && !b.erected);
    const ks = KIND_SPEC[kind as BuildingKind];
    const one = (v: number | [number, number] | undefined, d: number) => (v === undefined ? d : typeof v === 'number' ? v : Math.max(...v));
    const base = like
      ? { w: like.facing % 2 ? like.d : like.w, d: like.facing % 2 ? like.w : like.d, fl: like.floors, seed: like.seed, st: like.style, solid: like.solid }
      : ks ? { w: one(ks.w, 2), d: one(ks.d, 2), fl: one(ks.floors, 1), seed: (x * 7919 + z * 104729) >>> 0, st: style as Arch, solid: ks.solid !== false } : null;
    if (!base) return `no ${kind} to copy and none in the kinds table`;
    // the nearest lot round (x, z) that takes it, any facing with a road at its door (a stadium over a blueprint's 8 tiles a side too)
    let last = '';
    for (let r = 0; r <= 14; r++) for (let dz = -r; dz <= r; dz++) for (let dx = -r; dx <= r; dx++) {
      if (Math.max(Math.abs(dx), Math.abs(dz)) !== r) continue;
      for (const turn of [0, 1, 2, 3]) {
        const ff = (f + turn) & 3, sw = ff % 2 ? base.d : base.w, sd = ff % 2 ? base.w : base.d;
        // a stadium of one design (its seed decides which: world/stadiums.ts stadiumDesignOf), the seed stepped on until it is
        let seed = base.seed;
        if (design) for (let k = 0; k < 400 && stadiumDesignOf({ facing: ff, w: sw, d: sd, seed } as Building) !== design; k++) seed = (seed + 1) >>> 0;
        const spec: ErectSpec = { kind: kind as BuildingKind, x: Math.round(x + dx - sw / 2), z: Math.round(z + dz - sd / 2), w: sw, d: sd, f: ff, fl: base.fl, seed, ...(base.st ? { st: base.st } : {}), solid: base.solid ? 1 : 0, hrs: erectHours(sw, sd, base.fl) };
        const why = erectProblem(w, spec, () => true);
        if (why && !why.startsWith('That lot is too big')) { last = why; continue; }
        const done = this.host.erect(w, spec, sw > ERECT_MAX_SIDE || sd > ERECT_MAX_SIDE);
        if (!done) this.log.push(`${kind} at ${spec.x},${spec.z} facing ${ff}`);
        return done;
      }
    }
    return last;
  }

  /** Build every chunk round a world point now (the town zoomed out of); how many are left. */
  warm(x: number, z: number): number { return this.host.warm(x, z); }

  // ---- the camera ----

  /** Hold the camera at (x, y, z) looking at (tx, ty, tz), world units, from the next frame on; null lets it go. */
  look(p: { x: number; y: number; z: number; tx: number; ty: number; tz: number } | null): void {
    this.pose = p;
    this.host.setCam(p ? (cam, dt) => this.apply(cam, dt) : (_c, dt) => this.update(dt));
  }
  /** The same pose by orbit: round (tx, tz) at yaw (degrees), pitch (degrees) and distance. */
  orbit(tx: number, tz: number, yaw: number, pitch: number, dist: number, ty?: number): void {
    const y0 = ty ?? this.host.groundAt(tx, tz);
    const a = (yaw * Math.PI) / 180, p = (pitch * Math.PI) / 180;
    this.look({ x: tx + Math.sin(a) * Math.cos(p) * dist, y: y0 + Math.sin(p) * dist, z: tz + Math.cos(a) * Math.cos(p) * dist, tx, ty: y0, tz });
  }
  private apply(cam: THREE.PerspectiveCamera, dt: number): void {
    this.cam = cam;
    const p = this.pose;
    if (p) {
      if (this.near && cam.near !== this.near) { cam.near = this.near; cam.updateProjectionMatrix(); }
      if (this.fov && cam.fov !== this.fov) { cam.fov = this.fov; cam.updateProjectionMatrix(); }
      cam.position.set(p.x, p.y, p.z);
      cam.lookAt(p.tx, p.ty, p.tz);
      cam.updateMatrixWorld();
    }
    this.update(dt);
  }

  // ---- towns ----

  /** The towns of a county (or every live one), biggest first: name, style, buildings, middle (world tiles), size. */
  towns(cx?: number, cz?: number): { name: string; style: string; cell: [number, number]; n: number; x: number; z: number; size: number }[] {
    const isl = this.host.islands();
    if (!isl) return [];
    const worlds: World[] = cx !== undefined && cz !== undefined ? [isl.at(cx, cz)].filter((w): w is World => !!w) : [...(isl.live instanceof Map ? isl.live.values() : isl.live)];
    const out = [];
    for (const w of worlds) for (const t of w.towns) out.push({ name: t.name, style: String(t.style), cell: [w.cx, w.cz] as [number, number], n: t.buildings.filter((b) => !b.gone).length, x: w.ox + t.x0 + t.size / 2, z: w.oz + t.z0 + t.size / 2, size: t.size });
    return out.sort((a, b) => b.n - a.n);
  }

  /** A town's buildings in a popcorn order: shuffled by seed, then loosely from its middle out. */
  order(cx: number, cz: number, name: string, seed = 1): Building[] {
    const w = this.host.islands()?.at(cx, cz);
    const t = w?.towns.find((q) => q.name === name);
    if (!w || !t) return [];
    let s = seed >>> 0 || 1;
    const rnd = () => ((s = (s * 1664525 + 1013904223) >>> 0) / 4294967296);
    const mx = t.x0 + t.size / 2, mz = t.z0 + t.size / 2, R = t.size / 2;
    return t.buildings.filter((b) => !b.gone && !b.derelict)
      .map((b) => ({ b, k: Math.hypot(b.x + b.w / 2 - mx, b.z + b.d / 2 - mz) / R + rnd() * 0.9 }))
      .sort((a, b) => a.k - b.k).map((e) => e.b);
  }

  // ---- the popcorn ----

  /** Buy these buildings of county (cx, cz) now, each bouncing up in the livery: how many were bought. */
  buy(cx: number, cz: number, uids: number[]): number {
    const w = this.host.islands()?.at(cx, cz);
    if (!w) return 0;
    const bought: { b: Building; t: Town | null }[] = [];
    for (const uid of uids) {
      const b = w.allBuildings[uid];
      if (!b || b.gone) continue;
      const why = this.host.grant(w, b);
      if (why) { this.log.push(`${b.kind} ${uid}: ${why}`); continue; }
      bought.push({ b, t: w.towns.find((q) => q.buildings.includes(b)) ?? null });
    }
    if (!bought.length) return 0;
    // the paints set (so the copies are drawn in them) and the chunks queued to be drawn again
    this.host.repaint();
    const parent = this.host.groupOf(w);
    if (!parent) return bought.length;
    for (const { b, t } of bought) this.pop(w, b, t, parent);
    return bought.length;
  }

  private pop(w: World, b: Building, t: Town | null, parent: THREE.Group): void {
    const k = new Kit(w);
    try { drawBuilding(k, b, t); } catch (e) { this.log.push(`draw ${b.kind}: ${(e as Error).message}`); return; }
    const it = k.meshSteps();
    let r = it.next();
    while (!r.done) r = it.next();
    const g = r.value;
    if (!g) return;
    const bx = b.x + b.w / 2, bz = b.z + b.d / 2, by = b.level * STEP;
    const pivot = new THREE.Group();
    pivot.position.set(bx, by, bz);
    g.position.set(-bx, -by, -bz);
    pivot.add(g);
    pivot.scale.setScalar(0.001);
    parent.add(pivot);
    // a puff of flecks in the two colours, thrown up and out off the roof
    const flecks: Pop['flecks'] = [];
    const span = Math.max(1, Math.min(4, Math.max(b.w, b.d)));
    const n = Math.round(6 + span * 3);
    const paint = this.paint;
    for (let i = 0; i < n; i++) {
      const m = new THREE.Mesh(this.fleckGeo, new THREE.MeshStandardMaterial({ color: i % 3 === 2 ? paint[1] : paint[0], roughness: 0.6, flatShading: true }));
      const a = Math.random() * Math.PI * 2, out = 0.4 + Math.random() * 0.9;
      m.position.set(bx + Math.sin(a) * span * 0.3, by + 0.6 + Math.random() * 1.2 * span, bz + Math.cos(a) * span * 0.3);
      m.scale.setScalar(0.08 + Math.random() * 0.08 * span);
      m.rotation.set(Math.random() * 6, Math.random() * 6, Math.random() * 6);
      parent.add(m);
      flecks.push({ m, v: new THREE.Vector3(Math.sin(a) * out * span, 2 + Math.random() * 2.5 * Math.sqrt(span), Math.cos(a) * out * span), spin: new THREE.Vector3(Math.random() - 0.5, Math.random() - 0.5, Math.random() - 0.5).multiplyScalar(12) });
    }
    this.pops.push({ pivot, parent, age: 0, flecks });
  }

  /** Dust and chips thrown up where a piece of road, track or a pad has just gone down (world x, z), gone in under a second. */
  puff(x: number, z: number, cols: number[] = [0xe4dccb, 0xc9bda3, 0x9a9282], n = 12, size = 1): void {
    const y = this.host.groundAt(x, z);
    for (let i = 0; i < n; i++) {
      const m = new THREE.Mesh(this.fleckGeo, new THREE.MeshStandardMaterial({ color: cols[i % cols.length], roughness: 1, flatShading: true }));
      const a = Math.random() * Math.PI * 2, out = (0.6 + Math.random() * 1.1) * size;
      m.position.set(x + Math.sin(a) * 0.25, y + 0.1, z + Math.cos(a) * 0.25);
      m.scale.setScalar((0.07 + Math.random() * 0.1) * size);
      m.rotation.set(Math.random() * 6, Math.random() * 6, Math.random() * 6);
      this.host.scene.add(m);
      this.bits.push({ m, v: new THREE.Vector3(Math.sin(a) * out, (1.4 + Math.random() * 1.8) * Math.sqrt(size), Math.cos(a) * out), spin: new THREE.Vector3(Math.random() - 0.5, Math.random() - 0.5, Math.random() - 0.5).multiplyScalar(10), age: 0, life: 0.55 + Math.random() * 0.3 });
    }
  }
  private bits: { m: THREE.Mesh; v: THREE.Vector3; spin: THREE.Vector3; age: number; life: number }[] = [];

  /** The fleet's two colours for the flecks (set by the shoot with the brand). */
  set fleckPaint(p: [number, number]) { this.paint = p; }
  private paint: [number, number] = [0xffd21f, 0x1b1b1b];

  /** The popcorn on a frame: each copy squashes and stretches up and settles a hair proud of the chunk under it. */
  // ---- the workshop showcase (the trailer's "Upgrade your vehicles", the user 11 Nov 2026) ----

  private show: { m: VehicleMesh; x: number; z: number; h: number; bump: number; scale: number } | null = null;

  /**
   * A model's workshop parts in the order they go on: every slot's first tier in turn, then every slot's second, then
   * its third; slots that change nothing on the mesh left out (built and compared, as the workshop gallery does). Each
   * step is the parts so far. The respray is the given colour, the two-tone the accent.
   */
  upgrades(model: string, colour: number, accent: number): { slot: SlotId; tier: number; w: number }[] {
    const base = ALL_VEHICLES.find((v) => v.id === model);
    if (!base) return [];
    // a print to tell whether a part shows at all, and its size (parts, vertices, overall box) for how much it shows
    let size = { n: 0, v: 0, box: new THREE.Box3() };
    const print = (def: VehicleDef): string => {
      const m = buildVehicleMesh(def);
      m.holder.updateMatrixWorld(true);
      const out: string[] = [];
      size = { n: 0, v: 0, box: new THREE.Box3().setFromObject(m.holder) };
      m.holder.traverse((o) => { const q = o as THREE.Mesh; if (q.isMesh) { size.n++; size.v += q.geometry.getAttribute('position')?.count ?? 0; } });
      const box = new THREE.Box3();
      m.holder.traverse((o) => {
        const mesh = o as THREE.Mesh;
        if (!mesh.isMesh) return;
        box.setFromObject(mesh);
        const mats = (Array.isArray(mesh.material) ? mesh.material : [mesh.material]) as THREE.MeshStandardMaterial[];
        out.push(`${mesh.geometry.getAttribute('position')?.count}:${box.min.toArray().map((x) => x.toFixed(3))}:${box.max.toArray().map((x) => x.toFixed(3))}:${mats.map((x) => `${x.color?.getHexString()}${x.metalness ?? ''}`).join('/')}`);
      });
      disposeVehicleMesh(m);
      return out.sort().join('|');
    };
    const steps: { slot: SlotId; tier: number; w: number }[] = [];
    const t: Parts['t'] = {};
    let last = print(base), was0 = size;
    for (let tier = 1; tier <= 3; tier++) for (const s of slotsFor(base)) {
      const was = t[s.id];
      t[s.id] = [tier, tier];
      const now = print(applyParts(base, { t: { ...t }, spent: 0, c: colour, a: accent }));
      // (the respray always shows: its colour is in the vertex colours, which the print doesn't read)
      if (now === last && s.id !== 'paint') { if (was) t[s.id] = was; else delete t[s.id]; continue; }
      last = now;
      // how much it shows: new pieces and vertices against the whole, and how far the outline moved against its size
      const d = was0.box.getSize(new THREE.Vector3()).length() || 1;
      const moved = was0.box.min.distanceTo(size.box.min) + was0.box.max.distanceTo(size.box.max);
      const w = Math.abs(size.v - was0.v) / Math.max(1, was0.v) + Math.abs(size.n - was0.n) / Math.max(1, was0.n) + moved / d + (s.id === 'paint' ? 0.3 : 0);
      was0 = size;
      steps.push({ slot: s.id, tier, w });
    }
    return steps;
  }

  /**
   * Stand a model at (x, z) facing h, fitted with the first `k` of its upgrade steps (stock at 0), in place of the one
   * standing there; a little bounce as each part goes on. Null clears it.
   */
  showcase(model: string | null, steps: { slot: SlotId; tier: number }[] = [], k = 0, x = 0, z = 0, h = 0, colour = 0, accent = 0): void {
    if (this.show) { this.host.scene.remove(this.show.m.holder); disposeVehicleMesh(this.show.m); }
    const bump = this.show && model ? this.show.bump : 0;
    this.show = null;
    const base = model ? ALL_VEHICLES.find((v) => v.id === model) : null;
    if (!base) return;
    const t: Parts['t'] = {};
    for (const st of steps.slice(0, k)) t[st.slot] = [st.tier, st.tier];
    // (colour 0: the model's own paint, no respray)
    const def = k > 0 ? applyParts(base, { t, spent: 0, ...(colour ? { c: colour } : {}), ...(accent ? { a: accent } : {}) }) : base;
    const m = buildVehicleMesh(def);
    m.body.position.y = m.lift ?? 0;
    if (m.gear) m.gear.visible = true;
    if (m.seats) m.seats.forEach((q, i) => { q.visible = i < (m.seatDefault ?? 0); });
    m.holder.traverse((o) => { if ((o as THREE.Mesh).isMesh) o.castShadow = !o.userData.noShadow; });
    // the surface it stands on: what is drawn there (a crossing's painted lot stands a little over the terrain), found by
    // a ray down from just over the ground, overhead things (a crossing's gantry, a sign) above that left out
    const g = this.surfaceAt(x, z);
    m.root.position.set(x, g, z);
    m.root.rotation.set(0, h, 0);
    this.host.scene.add(m.holder);
    // resting on the road: bigger tyres reach below the axle the body was lifted for, so the whole model is set down
    // with its lowest point (a tyre, a track, the landing gear) on the ground (the user, 11 Nov 2026: tyres sank in)
    m.holder.updateMatrixWorld(true);
    const low = new THREE.Box3().setFromObject(m.holder).min.y;
    m.root.position.y += g - low;
    this.show = { m, x, z, h, bump, scale: m.root.scale.x };
  }
  /** Nobody walking through the stand: a square of county (cx, cz)'s tiles round (x, z) local, r tiles out; null lets them back. */
  clearStand(cx: number, cz: number, x: number, z: number, r: number | null): void {
    const w = this.host.islands()?.at(cx, cz);
    if (w) this.host.keepOff(w, r === null ? null : { x0: x - r, z0: z - r, x1: x + r, z1: z + r });
  }
  /** Every tile of a county with a tree, a rock or a cactus on it (render/props.ts propsOn): 1, else 0; N x N. */
  growth(cx: number, cz: number): Uint8Array | null {
    const w = this.host.islands()?.at(cx, cz);
    if (!w) return null;
    const N = 256, out = new Uint8Array(N * N);
    for (let z = 0; z < N; z++) for (let x = 0; x < N; x++) { const p = propsOn(w, x, z); if (p.trees || p.rocks || p.cacti) out[z * N + x] = 1; }
    return out;
  }
  private ray = new THREE.Raycaster();
  private surfaces = new Map<string, number>();
  /** The top of whatever is drawn at a world point, up to half a unit over the terrain: the road, a lot, a deck. */
  surfaceAt(x: number, z: number): number {
    const g = this.host.groundAt(x, z);
    this.ray.set(new THREE.Vector3(x, g + 0.5, z), new THREE.Vector3(0, -1, 0));
    this.ray.far = 1;
    const key = `${x},${z}`;
    const was = this.surfaces.get(key);
    if (was !== undefined) return was;
    // mesh by mesh (a sprite or a line among the scene's things throws on a ray without a camera), the shown vehicle left out
    const skip = this.show?.m.holder;
    let top = g;
    this.host.scene.traverseVisible((o) => {
      const m = o as THREE.Mesh;
      if (!m.isMesh || (m as unknown as THREE.Sprite).isSprite) return;
      for (let q: THREE.Object3D | null = o; q; q = q.parent) if (q === skip) return;
      try { for (const h of this.ray.intersectObject(m, false)) if (h.point.y > top) top = h.point.y; } catch { /* not raycastable */ }
    });
    this.surfaces.set(key, top);
    return top;
  }
  /** The bounce of a part going on (or a vehicle swapped in): 1, falling away over a few frames. */
  bounce(): void { if (this.show) this.show.bump = 1; }
  /** The standing model's size: half its longest side, its height. */
  shown(): { r: number; h: number } | null {
    if (!this.show) return null;
    this.show.m.holder.updateMatrixWorld(true);
    const b = new THREE.Box3().setFromObject(this.show.m.holder);
    return { r: Math.max(b.max.x - b.min.x, b.max.z - b.min.z) / 2, h: b.max.y - b.min.y };
  }

  update(dt: number): void {
    if (this.show) {
      const s = this.show;
      s.bump = Math.max(0, s.bump - dt * 9);
      // (on the model's own scale: buildVehicleMesh sets it, every vehicle drawn small)
      const e = s.scale * (1 + 0.07 * Math.sin(s.bump * Math.PI));
      s.m.root.scale.set(e, e, e);
    }
    if (this.bits.length) this.bits = this.bits.filter((b) => {
      b.age += dt;
      b.v.y -= 7 * dt;
      b.m.position.addScaledVector(b.v, dt);
      b.m.rotation.x += b.spin.x * dt; b.m.rotation.y += b.spin.y * dt;
      if (b.age < b.life) { b.m.scale.multiplyScalar(0.97); return true; }
      this.host.scene.remove(b.m); (b.m.material as THREE.Material).dispose();
      return false;
    });
    if (!this.pops.length) return;
    this.pops = this.pops.filter((p) => {
      p.age += dt;
      const u = Math.min(1, p.age / POP_S);
      // up fast from nothing to a third over its height, then a squash and a few wobbles: a kernel going off
      let sy: number, sxz: number;
      if (u < 0.28) { const e = 1 - (1 - u / 0.28) ** 3; sy = Math.max(0.001, e * (1 + 0.35 * e)); sxz = Math.max(0.001, e * (1 - 0.08 * e)); }
      else { const v = u - 0.28, d = Math.exp(-7 * v) * Math.cos(v * 26); sy = 1.008 + 0.35 * d; sxz = 1.008 - 0.08 * d; }
      p.pivot.scale.set(sxz, sy, sxz);
      for (const f of p.flecks) {
        f.v.y -= 9 * dt;
        f.m.position.addScaledVector(f.v, dt);
        f.m.rotation.x += f.spin.x * dt; f.m.rotation.y += f.spin.y * dt; f.m.rotation.z += f.spin.z * dt;
        const fade = Math.max(0, 1 - p.age / 1.1);
        f.m.visible = fade > 0.02;
        f.m.scale.multiplyScalar(fade > 0.02 ? 0.985 : 1);
      }
      if (p.age < HOLD_S) return true;
      this.dispose(p);
      return false;
    });
  }

  private dispose(p: Pop): void {
    p.parent.remove(p.pivot);
    p.pivot.traverse((o) => { const m = o as THREE.Mesh; if (m.isMesh) m.geometry.dispose(); });
    for (const f of p.flecks) { p.parent.remove(f.m); (f.m.material as THREE.Material).dispose(); }
  }

  /** Everything let go: the camera back to the game, the copies taken down, the clock left as it is. */
  end(): void {
    this.showcase(null);
    if ((this.near || this.fov) && this.cam) { this.cam.near = 2; this.cam.fov = 18; this.cam.updateProjectionMatrix(); }
    this.near = null;
    this.fov = null;
    for (const p of this.pops) this.dispose(p);
    this.pops = [];
    this.host.setCam(null);
    this.pose = null;
  }
}

