import * as THREE from 'three';
import { FullScreenQuad } from 'three/examples/jsm/postprocessing/Pass.js';

/**
 * The tilt-shift look: a sharp band across the middle of the frame and everything above and below
 * it melting into blur, which is what makes the world read as a model on a table.
 *
 * Built for fill rate, because this is what a big canvas pays for every pixel of:
 *   1. the scene into one multisampled half-float target (the only multisampled buffer);
 *   2. a copy of it at half resolution, blurred twice over horizontally and vertically — a quarter
 *      of the pixels per pass, and the blur is the part that never needed full resolution;
 *   3. one full-resolution pass mixing the sharp scene with the blurred copy by distance from the
 *      band, with the saturation and the vignette, tone mapped and in sRGB straight to the screen (three
 *      adds both to a ShaderMaterial drawn to the screen; a separate output pass was one more
 *      full-resolution pass and target for the same sums).
 * Before this, every one of four full-resolution blur passes rendered into a 4× multisampled
 * target, which at 1080p cost more than the whole scene.
 */

const vert = /* glsl */ `
varying vec2 vUv;
void main() {
  vUv = uv;
  gl_Position = projectionMatrix * modelViewMatrix * vec4(position, 1.0);
}`;

/** A 9-tap Gaussian along one axis, sampled with linear filtering so each tap reads two texels. */
const blurFrag = /* glsl */ `
uniform sampler2D tDiffuse;
uniform vec2 uStep;
varying vec2 vUv;
void main() {
  vec4 c = texture2D(tDiffuse, vUv) * 0.2270270270;
  c += texture2D(tDiffuse, vUv + uStep * 1.3846153846) * 0.3162162162;
  c += texture2D(tDiffuse, vUv - uStep * 1.3846153846) * 0.3162162162;
  c += texture2D(tDiffuse, vUv + uStep * 3.2307692308) * 0.0702702703;
  c += texture2D(tDiffuse, vUv - uStep * 3.2307692308) * 0.0702702703;
  gl_FragColor = c;
}`;

const copyFrag = /* glsl */ `
uniform sampler2D tDiffuse;
varying vec2 vUv;
void main() { gl_FragColor = texture2D(tDiffuse, vUv); }`;

const mixFrag = /* glsl */ `
uniform sampler2D tSharp;
uniform sampler2D tBlur;
uniform float uFocus;
uniform float uBand;
uniform float uSaturation;
uniform float uVignette;
varying vec2 vUv;
void main() {
  float d = abs(vUv.y - uFocus) - uBand;
  float s = clamp(d / max(0.5 - uBand, 0.01), 0.0, 1.0);
  s = s * s;
  vec4 c = mix(texture2D(tSharp, vUv), texture2D(tBlur, vUv), s);
  float l = dot(c.rgb, vec3(0.299, 0.587, 0.114));
  c.rgb = mix(vec3(l), c.rgb, uSaturation);
  vec2 q = vUv - 0.5;
  c.rgb *= 1.0 - dot(q, q) * uVignette;
  gl_FragColor = c;
  #include <tonemapping_fragment>
  #include <colorspace_fragment>
}`;

export interface TiltShift {
  setSize(w: number, h: number): void;
  setFocus(y: number): void;
  /** Half-height of the sharp band, as a fraction of the screen (negative blurs the whole frame). */
  setBand(b: number): void;
  /** Colour and the darkened corners: the camera mode's looks (game/photoMode.ts). LOOK_PLAYED is the game's own. */
  setLook(saturation: number, vignette: number): void;
  /** `mark`: called once the scene itself is drawn, before the blur and mix passes (main.ts renderMark). */
  render(mark?: () => void): void;
  /**
   * Where the scene itself is drawn. Shaders built for it differ from ones built for the screen (its
   * colour space and tone mapping are the output pass's, not its own), so warm-up must bind it.
   */
  readonly target: THREE.WebGLRenderTarget;
  /** Console tuning: multisamples on the scene target, and whether the targets are half-float. */
  configure(o: { samples?: number; float?: boolean; rounds?: number }): void;
}

/** The saturation and vignette the game is played with. */
export const LOOK_PLAYED = { saturation: 1.12, vignette: 0.42 } as const;

/** Blur taps are this many half-resolution texels apart: as wide a blur as the old full-res passes. */
const SPREAD = 1.1;

export function createTiltShift(renderer: THREE.WebGLRenderer, scene: THREE.Scene, camera: THREE.Camera): TiltShift {
  const opts = { type: THREE.HalfFloatType, depthBuffer: false } as const;
  const sceneRT = new THREE.WebGLRenderTarget(1, 1, { type: THREE.HalfFloatType, samples: 4 });
  /** Rounds of the separable blur (render/quality.ts: one at Low and Lowest, two passes fewer a frame). */
  let rounds = 2;
  const halfA = new THREE.WebGLRenderTarget(1, 1, opts);
  const halfB = new THREE.WebGLRenderTarget(1, 1, opts);

  const copyMat = new THREE.ShaderMaterial({ uniforms: { tDiffuse: { value: null } }, vertexShader: vert, fragmentShader: copyFrag });
  const copy = new FullScreenQuad(copyMat);
  const blurMat = new THREE.ShaderMaterial({ uniforms: { tDiffuse: { value: null }, uStep: { value: new THREE.Vector2() } }, vertexShader: vert, fragmentShader: blurFrag });
  const blur = new FullScreenQuad(blurMat);
  const mixMat = new THREE.ShaderMaterial({
    uniforms: {
      tSharp: { value: sceneRT.texture }, tBlur: { value: halfA.texture },
      uFocus: { value: 0.5 }, uBand: { value: 0.11 }, uSaturation: { value: LOOK_PLAYED.saturation }, uVignette: { value: LOOK_PLAYED.vignette },
    },
    vertexShader: vert, fragmentShader: mixFrag,
  });
  const mixQuad = new FullScreenQuad(mixMat);

  let hw = 1, hh = 1;
  const pass = (quad: FullScreenQuad, target: THREE.WebGLRenderTarget | null) => {
    renderer.setRenderTarget(target);
    quad.render(renderer);
  };

  const api: TiltShift = {
    target: sceneRT,
    setSize(w, h) {
      const pr = renderer.getPixelRatio();
      const W = Math.max(1, Math.floor(w * pr)), H = Math.max(1, Math.floor(h * pr));
      hw = Math.max(1, W >> 1);
      hh = Math.max(1, H >> 1);
      sceneRT.setSize(W, H);
      halfA.setSize(hw, hh);
      halfB.setSize(hw, hh);
    },
    setFocus(y) { mixMat.uniforms.uFocus.value = y; },
    setBand(b) { mixMat.uniforms.uBand.value = b; },
    setLook(saturation, vignette) { mixMat.uniforms.uSaturation.value = saturation; mixMat.uniforms.uVignette.value = vignette; },
    configure(o) {
      if (o.samples !== undefined && o.samples !== sceneRT.samples) { sceneRT.samples = o.samples; sceneRT.dispose(); }
      if (o.rounds !== undefined) rounds = Math.max(1, Math.min(2, o.rounds));
      if (o.float !== undefined) {
        const t = o.float ? THREE.HalfFloatType : THREE.UnsignedByteType;
        for (const rt of [sceneRT, halfA, halfB]) { rt.texture.type = t; rt.dispose(); }
      }
    },
    render(mark) {
      renderer.setRenderTarget(sceneRT);
      renderer.render(scene, camera);
      mark?.();
      // down to half resolution, then two rounds of separable blur there
      copyMat.uniforms.tDiffuse.value = sceneRT.texture;
      pass(copy, halfA);
      const step = blurMat.uniforms.uStep.value as THREE.Vector2;
      for (let k = 0; k < rounds; k++) {
        blurMat.uniforms.tDiffuse.value = halfA.texture;
        step.set(SPREAD / hw, 0);
        pass(blur, halfB);
        blurMat.uniforms.tDiffuse.value = halfB.texture;
        step.set(0, SPREAD / hh);
        pass(blur, halfA);
      }
      pass(mixQuad, null);
    },
  };
  const size = renderer.getSize(new THREE.Vector2());
  api.setSize(size.x, size.y);
  return api;
}
