import type { CellDoc, ClientMsg, ServerMsg, Welcome } from '../../shared/protocol';
import { TOWNS_PER_REPORT, type TownQuery, type TownReport, type TownsPage } from '../../shared/towns';
import type { OnlineExtra } from './online';
import { NO_FILTERS } from '../game/registerSorts';

/**
 * The world gazetteer from the game's side (docs/townregister.html, phase 4; server/gazetteer.ts). Every REPORT_S seconds
 * the towns on the islands in memory whose report has changed go to the server, a hundred at a time; and the town
 * register's World scope asks for its pages here, each answer kept until the next.
 */

const REPORT_S = 30;
/** A page asked for again after this long, so the World scope stays fresh while it is open. */
const STALE_S = 20;

export interface TownsNetHost {
  online(): boolean;
  post(m: ClientMsg): void;
  /** The towns in memory as reports (digest and shared numbers). */
  reports(): TownReport[];
}

export class TownsNet implements OnlineExtra {
  /** What was last sent of each town, so only changes go. */
  private sent = new Map<string, string>();
  private queue: TownReport[] = [];
  private wait = 5;
  private asked = '';
  private askedAt = 0;
  /** The newest page, and the player's own id (the holder filter's "yours"). */
  page: TownsPage['page'] | null = null;
  me = '';
  /** A page arrived. */
  onPage: (() => void) | null = null;
  /**
   * Whether this server keeps the gazetteer: it has answered an ask. A server from before it says nothing back, so the
   * register shows no World scope there (the user, 5 Nov 2026: it sat on "asking the server…" with no towns).
   */
  answered = false;
  private probed = false;

  constructor(private host: TownsNetHost) {}

  welcome(w: Welcome): void { this.me = w.you.id; this.sent.clear(); this.queue = []; this.page = null; this.asked = ''; this.answered = false; this.probed = false; }
  cell(_k: string, _doc: CellDoc): void { /* nothing per cell */ }
  got(m: ServerMsg): boolean {
    if (m.t !== 'towns') return false;
    this.page = m.page;
    this.answered = true;
    this.onPage?.();
    return true;
  }
  ready(): void { this.wait = 5; }

  frame(dt: number): void {
    if (!this.host.online()) return;
    // once a connection: one page, asked to learn whether this server keeps the gazetteer at all
    if (!this.probed) { this.probed = true; this.host.post({ t: 'towns', ask: { sort: 'built', f: NO_FILTERS(), at: 0 } }); }
    this.askedAt += dt;
    if ((this.wait -= dt) > 0) return;
    if (!this.queue.length) {
      this.wait = REPORT_S;
      for (const r of this.host.reports()) {
        const json = JSON.stringify(r);
        if (this.sent.get(r.d.key) === json) continue;
        this.sent.set(r.d.key, json);
        this.queue.push(r);
      }
    } else this.wait = 1;
    if (!this.queue.length) return;
    this.host.post({ t: 'towns', rep: this.queue.splice(0, TOWNS_PER_REPORT) });
  }

  /** Ask for a page of the World scope, unless the same was asked a moment ago. True when a new ask went. */
  ask(q: TownQuery): boolean {
    if (!this.host.online()) return false;
    const key = JSON.stringify(q);
    if (key === this.asked && this.askedAt < STALE_S) return false;
    this.asked = key;
    this.askedAt = 0;
    this.host.post({ t: 'towns', ask: q });
    return true;
  }

  forget(): void { /* nothing per cell */ }
  reset(): void { this.sent.clear(); this.queue = []; this.page = null; this.asked = ''; this.me = ''; this.answered = false; this.probed = false; }
}
