import { hex, mix, scale, type RGB } from '../../world/biomes';
import type { Building, StationKind } from '../../world/tiles';
import type { Rng } from '../../world/rng';
import type { Sched } from '../nightLights';
import {
  BRICK, CARS, COOL_GLOW, DARK, GLASS, GLASS_LIGHT, METAL, PATH, ROOF_GREY, STONE, WARM_GLOW, WHITE, WOOD,
  car, cur, curArch, pick, roofOver, row, styleGlass, styleRoof, styleTrim, styleWall, topOff, tree,
  type Draw, type Kit, type P3,
} from './kit';
import { clock } from './civic';
import { lorry } from './business';

/**
 * The railway's buildings: the grand terminus, the city and town stations, the country halt, the
 * goods yard and the harbour depot (see docs/trains.html, Stations).
 *
 * The lot is the station building and its forecourt. W runs along the track, D away from it, and the
 * front (+z) faces the line: the main line's centreline is 0.9 beyond the front edge and the passing
 * loop 2.0 beyond it. The rails, ballast and platform kerb are the track mesh's; these models draw the
 * buildings, the canopies over the platform strip (z from D/2 to D/2 + 0.5), and the sheds, footbridges
 * and gantries that span the tracks, clearing trains by 0.55 over the rail.
 *
 * `b.floors` is the line's period: 1 steam (brick, timber valances, semaphores, a coal stage), 2
 * streamliner (flat roofs, speed-line bands, neon names), 3 modern. A modern line, or a modernist,
 * postmodern or brutalist town, draws the terminus and the city station as a glass-and-steel concourse.
 */

type Period = 1 | 2 | 3;
/** The styles whose own crown already makes a fine top for a pavilion or a tower. */
const TALL_CROWNS = new Set(['spire', 'hipped', 'curved', 'dome', 'pitched', 'step']);
const period = (b: Building): Period => (b.floors >= 3 ? 3 : b.floors === 2 ? 2 : 1);
const modern = (b: Building): boolean =>
  period(b) === 3 || curArch === 'modernist' || curArch === 'postmodern' || curArch === 'brutalist';

const PAVE = hex(0xd3ccbb), PAVE_LINE = hex(0xbdb5a3), KERB = hex(0xe6e1d6), TAXI = hex(0xf2c14e), GOLD = hex(0xc9a24a);
const COAL = hex(0x2b2b2e), SAFETY = hex(0xf2b33b), CONCRETE = hex(0xc4c0b8), RUST = hex(0x8a5a3a), SLEEPER = hex(0x5a4a3c);
const BALLAST = hex(0x8f8a82), RAIL = hex(0x6d6f73);
const CONTAINER = [0xe2412f, 0x2bb3a3, 0xf2c14e, 0x4a6fa5, 0xf28c38, 0x8e5cc7, 0x6f9e6b, 0xb9bdc2];

/** Lamps and lit signs: on at dusk, all night. */
const LAMP: Sched = [17, 30, 2.2];
const SIGN: Sched = [16.5, 30, 1.8];
/** A concourse and a signal box are manned into the small hours. */
const HALL: Sched = [16.8, 30, 1.4];

/** Station walls: the town's own, but a steam line in a plain classic town builds in brick. */
function wallFor(r: Rng, p: Period): RGB {
  return p === 1 && curArch === 'classic' ? pick(r, BRICK) : styleWall(r);
}

/** The painted ironwork of canopies and footbridges: green or maroon for steam, cream for the streamliners, white for modern. */
function ironFor(r: Rng, p: Period): RGB {
  if (p === 1) return r() < 0.5 ? hex(0x3f5e4a) : hex(0x6e2f2f);
  return p === 2 ? hex(0xe8dcc0) : hex(0xf1f2f0);
}

const doorCol = (r: Rng): RGB => (cur.doors ? pick(r, cur.doors) : hex(0x5a3a28));

/** Draw on a back (-z) wall whose face is at local z = zFace: the frame is turned round, so `draw` gets the z to use there. */
function rear(k: Kit, zFace: number, draw: (z: number) => void): void {
  k.turned(Math.PI, () => draw(-zFace + 0.004));
}

// ---------------------------------------------------------------------------------------------
// platform furniture

function lamp(k: Kit, x: number, z: number, h = 0.46, p: Period = 1): void {
  if (p === 3) {
    k.box(x, 0, z, 0.022, h + 0.06, 0.022, METAL);
    k.glowBox(x, h + 0.06, z, 0.1, 0.022, 0.05, hex(0xc8ccd0), LAMP, COOL_GLOW);
    return;
  }
  k.box(x, 0, z, 0.026, h, 0.026, DARK);
  k.glowBox(x, h, z, 0.065, 0.075, 0.065, hex(0x8a7a50), LAMP, WARM_GLOW);
  k.hip(x, h + 0.075, z, 0.095, 0.04, 0.095, DARK);
}

/** A lamp hanging under a canopy or shed roof at height y. */
function hanging(k: Kit, x: number, y: number, z: number): void {
  k.glowBox(x, y - 0.05, z, 0.05, 0.05, 0.05, hex(0x8a7a50), LAMP, WARM_GLOW);
}

function bench(k: Kit, x: number, z: number, col: RGB = WOOD): void {
  k.box(x, 0.055, z, 0.26, 0.018, 0.08, col);
  k.box(x, 0.073, z - 0.035, 0.26, 0.06, 0.014, col);
  for (const s of [-1, 1]) k.box(x + s * 0.1, 0, z, 0.018, 0.055, 0.06, DARK);
}

/** The station's name on two posts, facing the line. */
function nameBoard(k: Kit, x: number, z: number, w: number, frame: RGB, p: Period): void {
  for (const s of [-1, 1]) k.box(x + s * (w / 2 - 0.02), 0, z, 0.02, 0.3, 0.02, frame);
  k.box(x, 0.19, z, w, 0.12, 0.018, frame);
  if (p === 1) k.box(x, 0.205, z, w - 0.04, 0.09, 0.026, WHITE);
  else k.glowBox(x, 0.205, z, w - 0.04, 0.09, 0.026, p === 2 ? hex(0xf2ead0) : WHITE, SIGN, p === 2 ? WARM_GLOW : COOL_GLOW);
  k.box(x, 0.235, z, w * 0.6, 0.028, 0.03, p === 3 ? hex(0x2f5a96) : DARK);
}

/**
 * A platform canopy from x0 to x1, its back at zb and front at zf, the underside at y: a slab and a
 * low ridge, posts along the front, and a saw-tooth timber valance on steam lines.
 */
function canopy(k: Kit, x0: number, x1: number, zb: number, zf: number, y: number, roof: RGB, post: RGB, p: Period, glass = false): void {
  const w = x1 - x0, cx = (x0 + x1) / 2, d = zf - zb, cz = (zb + zf) / 2;
  if (w < 0.2) return;
  if (glass) {
    k.box(cx, y, cz, w, 0.02, d, post, mix(GLASS_LIGHT, WHITE, 0.25));
  } else {
    k.box(cx, y, cz, w, 0.028, d, scale(roof, 0.8), roof);
    if (p !== 2) k.gable(cx, y + 0.028, cz, w, 0.07, d, roof, post);
    else k.box(cx, y + 0.028, zf - 0.02, w, 0.03, 0.04, post);
  }
  const n = Math.max(2, Math.round(w / 1.1) + 1), pz = zf - 0.14;
  for (let i = 0; i < n; i++) {
    const px = x0 + 0.08 + ((w - 0.16) * i) / (n - 1);
    k.box(px, 0, pz, 0.026, y, 0.026, post);
  }
  if (p === 1) {
    // the valance: a board with a row of little teeth under it
    k.box(cx, y - 0.035, zf, w, 0.035, 0.012, post);
    const teeth = Math.floor(w / 0.12), I: P3 = [cx, y, zf - 0.2];
    for (let i = 0; i < teeth; i++) {
      const tx = x0 + (i + 0.5) * (w / teeth);
      k.tri([tx - 0.045, y - 0.035, zf + 0.007], [tx + 0.045, y - 0.035, zf + 0.007], [tx, y - 0.08, zf + 0.007], post, I);
    }
  }
}

/** A slab of stairs rising from (ax, az) on the ground to (bx, bz) at y1, w wide, with a handrail. */
function flight(k: Kit, ax: number, az: number, bx: number, bz: number, y1: number, w: number, col: RGB, rail: RGB): void {
  const dx = bx - ax, dz = bz - az, len = Math.hypot(dx, dz);
  const px = (-dz / len) * (w / 2), pz = (dx / len) * (w / 2), t = 0.05;
  const A1: P3 = [ax + px, 0, az + pz], A2: P3 = [ax - px, 0, az - pz], B1: P3 = [bx + px, y1, bz + pz], B2: P3 = [bx - px, y1, bz - pz];
  const lo = (p: P3): P3 => [p[0], p[1] - t, p[2]];
  const up: P3 = [(ax + bx) / 2, y1 / 2 - 0.3, (az + bz) / 2], dn: P3 = [(ax + bx) / 2, y1 / 2 + 0.3, (az + bz) / 2];
  k.quad(A1, A2, B2, B1, col, up);
  k.quad(lo(A1), lo(A2), lo(B2), lo(B1), scale(col, 0.7), dn);
  const mid: P3 = [(ax + bx) / 2, y1 / 2 - t / 2, (az + bz) / 2];
  k.quad(A1, B1, lo(B1), lo(A1), scale(col, 0.85), mid);
  k.quad(A2, B2, lo(B2), lo(A2), scale(col, 0.85), mid);
  for (const s of [1, -1]) k.bar([ax + s * px, 0.13, az + s * pz], [bx + s * px, y1 + 0.13, bz + s * pz], 0.007, rail);
}

/** A footbridge at x from the platform strip over both tracks, with stairs down each side (lifts on a modern line). */
const DECK = 0.8;
function footbridge(k: Kit, x: number, F: number, p: Period, iron: RGB, stairsX: 1 | -1 = 1): void {
  const z0 = F + 0.1, z1 = F + 2.66, len = z1 - z0, zc = (z0 + z1) / 2;
  k.box(x, DECK - 0.04, zc, 0.24, 0.04, len, scale(iron, 0.8));
  if (p === 3) {
    // an enclosed glass tube with lift towers at both ends
    k.box(x, DECK, zc, 0.24, 0.2, len, mix(GLASS_LIGHT, WHITE, 0.2), WHITE);
    for (const zz of [z0, z1]) {
      k.box(x, 0, zz, 0.3, DECK + 0.24, 0.3, mix(GLASS_LIGHT, WHITE, 0.15), WHITE);
      k.glowBox(x, DECK + 0.24, zz, 0.3, 0.03, 0.3, WHITE, HALL, COOL_GLOW);
    }
    for (const zz of [F + 1.45]) k.box(x, 0, zz, 0.05, DECK - 0.04, 0.05, METAL);
    return;
  }
  // lattice sides: a solid panel with posts
  for (const s of [-1, 1]) {
    k.box(x + s * 0.11, DECK, zc, 0.014, 0.16, len, iron);
    if (p === 1) for (let i = 0; i <= 3; i++) k.box(x + s * 0.12, DECK, z0 + (len * i) / 3, 0.02, 0.18, 0.02, scale(iron, 0.8));
    else k.box(x + s * 0.12, DECK + 0.08, zc, 0.012, 0.018, len, GOLD);
  }
  if (p === 1) k.gable(x, DECK + 0.2, zc, 0.3, 0.1, len + 0.04, scale(iron, 0.75), iron, true);
  else k.box(x, DECK + 0.2, zc, 0.3, 0.025, len + 0.04, WHITE);
  if (p === 1) for (const s of [-1, 1]) for (const zz of [z0, z1]) k.box(x + s * 0.12, DECK + 0.16, zz, 0.02, 0.05, 0.02, iron);
  // piers: at each end and between the tracks
  for (const zz of [z0, F + 1.45, z1]) for (const s of [-1, 1]) k.box(x + s * 0.09, 0, zz, 0.03, DECK - 0.04, 0.03, iron);
  // stairs: down into the lot on this side, along the far platform on the other
  flight(k, x, z0 - 1.5, x, z0 + 0.02, DECK, 0.2, scale(iron, 0.9), iron);
  flight(k, x + stairsX * 1.5, z1, x + stairsX * 0.1, z1, DECK, 0.2, scale(iron, 0.9), iron);
}

/** A little signal box: a brick or rendered base, a glazed cab you can see the levers through at night, a hipped roof. */
function signalBox(k: Kit, x: number, z: number, p: Period, r: Rng, roof: RGB): void {
  const w = 0.46, d = 0.32, base = 0.3, cab = 0.2;
  const body = p === 1 ? pick(r, BRICK) : p === 2 ? hex(0xefe6d2) : CONCRETE;
  k.box(x, 0, z, w, base, d, body);
  k.box(x - 0.1, 0, z + d / 2 + 0.004, 0.1, 0.2, 0.01, doorCol(r));
  k.box(x, base, z, w + 0.04, 0.03, d + 0.04, p === 1 ? hex(0xf1ece0) : WHITE);
  const frame = p === 1 ? hex(0x7a5a3a) : p === 2 ? hex(0x2f4d3a) : hex(0x3a3f45);
  k.box(x, base + 0.03, z, w, cab, d, frame);
  for (const [px, pz, face, len] of [[x, z + d / 2, 1, w], [x, z - d / 2, 3, w], [x + w / 2, z, 0, d], [x - w / 2, z, 2, d]] as const) {
    const n = Math.max(2, Math.round(len / 0.13)), cell = len / n;
    for (let i = 0; i < n; i++) {
      const o = -len / 2 + cell * (i + 0.5);
      if (face === 1 || face === 3) k.pane(px + o, base + 0.05, pz, cell * 0.8, cab - 0.05, face, GLASS, HALL, WARM_GLOW);
      else k.pane(px, base + 0.05, pz + o, cell * 0.8, cab - 0.05, face, GLASS, HALL, WARM_GLOW);
    }
  }
  const top = base + 0.03 + cab;
  if (p === 1) k.hip(x, top, z, w + 0.14, 0.17, d + 0.14, roof);
  else k.box(x, top, z, w + 0.1, 0.035, d + 0.1, p === 2 ? WHITE : METAL);
  if (p === 1) k.box(x + w / 4, top + 0.06, z - d / 4, 0.05, 0.14, 0.05, scale(body, 0.9));
  // the name plate and the steps up to the door of the cab
  k.box(x, base - 0.07, z + d / 2 + 0.006, 0.26, 0.05, 0.01, WHITE);
  flight(k, x - w / 2 - 0.34, z - 0.06, x - w / 2 - 0.02, z - 0.06, base, 0.09, p === 1 ? WOOD : CONCRETE, DARK);
}

/** A signal beside the line: a semaphore arm on steam lines, a colour-light head after. */
function signal(k: Kit, x: number, z: number, p: Period): void {
  if (p === 1) {
    k.box(x, 0, z, 0.024, 0.78, 0.024, WHITE);
    k.cone(x, 0.78, z, 0.02, 0.05, DARK, 4);
    k.box(x + 0.09, 0.66, z + 0.02, 0.18, 0.035, 0.008, hex(0xd8342a));
    k.box(x + 0.16, 0.668, z + 0.025, 0.02, 0.02, 0.008, WHITE);
    k.glowBox(x + 0.01, 0.62, z + 0.03, 0.025, 0.025, 0.01, hex(0x802020), LAMP, hex(0xff3b30));
    k.bar([x, 0.1, z + 0.03], [x + 0.12, 0.1, z + 0.03], 0.006, DARK);
  } else {
    k.box(x, 0, z, 0.024, 0.5, 0.024, p === 2 ? DARK : METAL);
    k.box(x, 0.5, z, 0.07, 0.16, 0.04, DARK);
    k.glowBox(x, 0.6, z + 0.022, 0.03, 0.03, 0.006, hex(0x2a5a2a), [0, 30, 2], hex(0x3bff6a));
    k.box(x, 0.66, z, 0.09, 0.012, 0.06, DARK);
  }
}

// ---------------------------------------------------------------------------------------------
// the buildings

/**
 * A station house of `storeys` storeys `sh` tall (taller than a town floor, so a canopy fits between
 * the rows of windows), windows round every face, a cornice, and the style's roof; returns its top.
 */
function stationHouse(k: Kit, b: Building, r: Rng, x: number, z: number, w: number, d: number, storeys: number, sh: number,
  wall: RGB, roof: RGB, glass: RGB, roofing: 'style' | 'flat' | 'crown' | 'none' = 'style', bay = 0.3): number {
  const h = storeys * sh + 0.05;
  if (cur.plinth) {
    k.box(x, 0, z, w, sh, d, pick(r, cur.plinth));
    k.box(x, sh, z, w, h - sh, d, wall);
  } else k.box(x, 0, z, w, h, d, wall);
  k.box(x, 0, z, w + 0.02, 0.045, d + 0.02, scale(wall, 0.8));
  // a grand house (bay 0.5) has tall wide windows, too wide for the style's shutters and lintels
  const count = (len: number) => Math.max(1, bay >= 0.5 ? Math.floor(((len - 0.12) * 0.78) / 0.37) : Math.round(len / bay));
  const nx = count(w), nz = count(d);
  for (let s = 0; s < storeys; s++) {
    const y = s * sh + 0.1, wh = sh * 0.46;
    row(k, b, r, x, y, z + d / 2, w - 0.12, wh, nx, 1, glass);
    row(k, b, r, x, y, z - d / 2, w - 0.12, wh, nx, 3, glass);
    row(k, b, r, x + w / 2, y, z, d - 0.12, wh, nz, 0, glass);
    row(k, b, r, x - w / 2, y, z, d - 0.12, wh, nz, 2, glass);
    if (s > 0 && cur.course > 0.3) k.box(x, s * sh - 0.012, z, w + 0.025, 0.022, d + 0.025, styleTrim());
  }
  if (cur.massing === 'ribbed' || cur.massing === 'slab') {
    for (const sx of [-1, 1]) for (const sz of [-1, 1]) k.box(x + sx * (w / 2 - 0.02), 0, z + sz * (d / 2 - 0.02), 0.06, h + 0.01, 0.06, styleTrim());
  }
  if (roofing === 'crown') return topOff(k, r, x, h, z, w, d, wall);
  k.box(x, h - 0.03, z, w + 0.045, 0.035, d + 0.045, styleTrim());
  if (roofing === 'none') return h;
  if (roofing === 'flat' || cur.form === 'flat') return flatRoof(k, r, x, h, z, w, d, wall);
  return roofOver(k, r, x, h, z, w, d, wall, roof, cur.form);
}

/**
 * A flat roof behind a parapet, like the kit's, but with its roof beams (where the style has them)
 * spaced out, since a station's walls are long.
 */
function flatRoof(k: Kit, r: Rng, x: number, y: number, z: number, w: number, d: number, wall: RGB): number {
  const t = 0.035, ph = 0.06, cap = cur.form === 'hip' ? styleTrim() : wall;
  k.box(x, y, z, w - 2 * t, 0.006, d - 2 * t, scale(pick(r, cur.roofs), 0.96));
  for (const sz of [-1, 1]) k.box(x, y, z + sz * (d / 2 - t / 2), w, ph, t, cap);
  for (const sx of [-1, 1]) k.box(x + sx * (w / 2 - t / 2), y, z, t, ph, d - 2 * t, cap);
  if (cur.vigas !== undefined) {
    const n = Math.max(2, Math.round(w / 0.5)), beam = hex(cur.vigas);
    for (let i = 0; i < n; i++) {
      const o = -w / 2 + (w / n) * (i + 0.5);
      for (const sz of [-1, 1]) k.box(x + o, y - 0.045, z + sz * (d / 2 + 0.025), 0.022, 0.022, 0.05, beam);
    }
  }
  return y + ph;
}

/** The streamliner's touches on a house: speed-line bands along the walls and a lit fin with the name. */
function decoTouches(k: Kit, x: number, z: number, w: number, d: number, h: number, finZ: number): void {
  for (const y of [h * 0.42, h * 0.46, h - 0.08]) k.box(x, y, z, w + 0.02, 0.012, d + 0.02, GOLD);
  k.box(x, h - 0.1, finZ, 0.1, 0.5, 0.14, hex(0xf1ead8));
  k.glowBox(x, h - 0.02, finZ - 0.075, 0.06, 0.36, 0.01, hex(0xd8c8a0), SIGN, hex(0xff5a4a));
  k.glowBox(x, h - 0.02, finZ + 0.075, 0.06, 0.36, 0.01, hex(0xd8c8a0), SIGN, hex(0xff5a4a));
}

/** Forecourt paving from zb to zf across the lot, with a kerb line along its back. */
function forecourt(k: Kit, W: number, zb: number, zf: number): void {
  if (zf - zb < 0.05) return;
  k.box(0, 0, (zb + zf) / 2, W - 0.08, 0.014, zf - zb, PAVE);
  k.box(0, 0, zb + 0.04, W - 0.08, 0.03, 0.05, KERB);
}

/** Cars along x at z, starting at x0 and running `n` long in direction `dir`. */
function parked(k: Kit, r: Rng, x0: number, z: number, n: number, dir: 1 | -1, col?: RGB): void {
  for (let i = 0; i < n; i++) if (col || r() < 0.8) car(k, x0 + dir * i * 0.46, z, true, col ?? pick(r, CARS));
}

// ---------------------------------------------------------------------------------------------
// roofs over tracks

/**
 * A barrel vault over the tracks: its axis along x from x0 to x1, springing at y0 from za and zb,
 * rising `rise`; the top `glassy` share glazed, arched ribs every so often, and an underside.
 */
function vault(k: Kit, x0: number, x1: number, za: number, zb: number, y0: number, rise: number, seg: number, roof: RGB, rib: RGB, under: RGB, ribs: number, glazing = true): void {
  const zc = (za + zb) / 2, hz = (zb - za) / 2, cx = (x0 + x1) / 2;
  const P = (a: number, x: number, e = 0): P3 => [x, y0 + Math.sin(a) * (rise + e), zc - Math.cos(a) * (hz + e)];
  const axis: P3 = [cx, y0, zc];
  const glassCol = mix(GLASS_LIGHT, WHITE, 0.3);
  for (let i = 0; i < seg; i++) {
    const a0 = (i / seg) * Math.PI, a1 = ((i + 1) / seg) * Math.PI, am = (a0 + a1) / 2;
    const glazed = glazing && i >= Math.floor(seg * 0.3) && i < Math.ceil(seg * 0.7);
    k.quad(P(a0, x0), P(a0, x1), P(a1, x1), P(a1, x0), glazed ? glassCol : roof, axis);
    k.quad(P(a0, x0, -0.015), P(a0, x1, -0.015), P(a1, x1, -0.015), P(a1, x0, -0.015), under, P(am, cx, 0.5));
    for (let j = 0; j <= ribs; j++) {
      const rx = x0 + ((x1 - x0) * j) / ribs;
      k.quad(P(a0, rx - 0.03, 0.02), P(a0, rx + 0.03, 0.02), P(a1, rx + 0.03, 0.02), P(a1, rx - 0.03, 0.02), rib, axis);
    }
  }
  if (!glazing) return;
  // the glazed crown lit from below after dark
  k.glowBox(cx, y0 + rise + 0.022, zc, x1 - x0 - 0.1, 0.006, hz * 0.16, glassCol, [17.5, 30, 0.7], mix(WARM_GLOW, glassCol, 0.4));
  // the open ends: a heavy arched rib and a glazed screen high in the arch
  const chord = 0.5, a1 = Math.asin(chord), n = 6;
  for (const ex of [x0, x1]) {
    const hs = Math.max(3, Math.round(seg / 2));
    for (let i = 0; i < hs; i++) k.bar(P((i / hs) * Math.PI, ex), P(((i + 1) / hs) * Math.PI, ex), 0.03, rib);
    const c: P3 = [ex, y0 + chord * rise, zc];
    for (let i = 0; i < n; i++) {
      const p0 = P(a1 + ((Math.PI - 2 * a1) * i) / n, ex), p1 = P(a1 + ((Math.PI - 2 * a1) * (i + 1)) / n, ex);
      for (const s of [-1, 1]) k.tri(c, p0, p1, glassCol, [ex + s * 0.2, c[1], zc]);
    }
    k.bar(P(a1, ex), P(Math.PI - a1, ex), 0.018, rib);
  }
}

/**
 * A modern roof: a long shallow wave along x from x0 to x1, from za (y0) up by `rise` and down to zb
 * (y0), with skylight bands, a white soffit and a fascia round its edge. Returns the height at z.
 */
function wave(k: Kit, x0: number, x1: number, za: number, zb: number, y0: number, rise: number, seg: number, top: RGB, soffit: RGB): (z: number) => number {
  const cx = (x0 + x1) / 2, t = 0.05;
  const yAt = (z: number) => y0 + Math.sin(Math.max(0, Math.min(1, (z - za) / (zb - za))) * Math.PI) * rise;
  const P = (i: number, x: number, e = 0): P3 => { const z = za + ((zb - za) * i) / seg; return [x, yAt(z) + e, z]; };
  const sky = mix(GLASS_LIGHT, WHITE, 0.2);
  for (let i = 0; i < seg; i++) {
    const zm = za + ((zb - za) * (i + 0.5)) / seg, ym = yAt(zm);
    k.quad(P(i, x0, t), P(i, x1, t), P(i + 1, x1, t), P(i + 1, x0, t), i % 3 === 1 ? sky : top, [cx, ym - 1, zm]);
    k.quad(P(i, x0), P(i, x1), P(i + 1, x1), P(i + 1, x0), soffit, [cx, ym + 1, zm]);
    for (const [ex, s] of [[x0, -1], [x1, 1]] as const) k.quad(P(i, ex), P(i, ex, t), P(i + 1, ex, t), P(i + 1, ex), scale(top, 0.85), [ex - s, ym, zm]);
  }
  for (const [ez, s] of [[za, -1], [zb, 1]] as const) {
    const i = s < 0 ? 0 : seg;
    k.quad(P(i, x0), P(i, x1), P(i, x1, t), P(i, x0, t), scale(top, 0.85), [cx, y0, ez - s]);
  }
  return yAt;
}

// ---------------------------------------------------------------------------------------------
// the modern concourse, for the terminus and the city station

function concourse(k: Kit, W: number, D: number, b: Building, r: Rng, big: boolean): void {
  const F = D / 2;
  const bd = big ? Math.min(1.7, D * 0.34) : Math.min(1.3, D * 0.34);
  const bw = big ? Math.min(W - 1.2, W * 0.72) : Math.min(3.4, W * 0.3);
  const front = F - (big ? 0.15 : 0.05), bz = front - bd / 2, back = front - bd;
  const hh = big ? 0.95 : 0.56;
  const accent = curArch === 'postmodern' ? hex(0xe2412f) : curArch === 'brutalist' ? hex(0xf2a93b) : hex(0x2f7fb5);
  const frame = curArch === 'brutalist' ? CONCRETE : WHITE;
  const tint = mix(styleGlass(r), WHITE, 0.25);
  forecourt(k, W, -D / 2, back);

  // the glass hall
  const hx = big ? 0 : -W * 0.05;
  k.box(hx, 0, bz, bw, hh, bd, tint, frame);
  k.box(hx, 0, bz, bw + 0.02, 0.04, bd + 0.02, scale(frame, 0.85));
  const panes = (len: number) => Math.max(2, Math.round(len / 0.34));
  for (const [z, face] of [[back, 3], [front, 1]] as const) {
    const n = panes(bw), cell = bw / n;
    for (let i = 0; i < n; i++) {
      const o = hx - bw / 2 + cell * (i + 0.5);
      k.pane(o, 0.06, z, cell * 0.86, hh - 0.12, face, tint, HALL, mix(COOL_GLOW, WARM_GLOW, 0.3));
      k.box(o + cell / 2, 0, z + (face === 1 ? 0.006 : -0.006), 0.018, hh, 0.012, frame);
    }
  }
  if (curArch === 'brutalist') for (const sx of [-1, 1]) k.box(hx + sx * (bw / 2 - 0.1), 0, bz, 0.2, hh + 0.05, bd + 0.06, CONCRETE);
  // the entrance: a lit portal in the middle of the town side
  k.box(hx, 0, back - 0.02, 0.5, 0.36, 0.04, frame);
  k.glowBox(hx, 0.02, back - 0.045, 0.4, 0.3, 0.01, hex(0x9fb8c4), HALL, COOL_GLOW);
  if (big) {
    // a flat roof over the hall with the name along its edge, and a canopy over the doors
    k.box(hx, hh, bz, bw + 0.2, 0.06, bd + 0.2, frame, hex(0xcfd4d8));
    k.glowBox(hx, hh + 0.08, back - 0.06, Math.min(3, bw * 0.3), 0.12, 0.02, accent, SIGN, accent);
    k.box(hx, 0.44, back - 0.35, 1.6, 0.035, 0.7, frame);
    for (const sx of [-1, 1]) k.bar([hx + sx * 0.7, 0, back - 0.62], [hx + sx * 0.7, 0.44, back - 0.62], 0.012, METAL);
  }

  if (big) {
    // one long wave of roof over the hall, the platforms and both tracks, on tree columns
    const x0 = -W / 2 + 0.15, x1 = W / 2 - 0.15, za = front - 0.5, zb = F + 2.62;
    const yAt = wave(k, x0, x1, za, zb, 0.9, 0.7, 10, hex(0xdfe3e6), WHITE);
    const n = Math.max(2, Math.round((x1 - x0) / 2.4) + 1);
    for (let i = 0; i < n; i++) {
      const px = x0 + 0.3 + ((x1 - x0 - 0.6) * i) / (n - 1);
      for (const pz of [zb - 0.08, za + 0.12]) {
        if (pz < F && Math.abs(px - hx) < bw / 2 + 0.1) continue;
        const y = yAt(pz);
        k.cyl(px, 0, pz, 0.03, y * 0.62, METAL, 6);
        for (const s of [-1, 1]) k.bar([px, y * 0.6, pz], [px + s * 0.3, y, pz + (pz > F ? -0.12 : 0.12)], 0.012, METAL);
      }
    }
    // hanging lights under the roof over each platform face
    for (let x = x0 + 1; x < x1 - 0.5; x += 2) {
      for (const pz of [F + 0.25, F + 1.45]) k.glowBox(x, yAt(pz) - 0.05, pz, 0.5, 0.02, 0.04, WHITE, LAMP, COOL_GLOW);
    }
    // a totem with the station's mark and a clock, and a taxi rank beside the portal
    const tz = -D / 2 + 0.45;
    k.box(-0.9, 0, tz, 0.16, 1.1, 0.1, frame);
    k.glowBox(-0.9, 0.8, tz, 0.17, 0.22, 0.11, accent, SIGN, accent);
    clock(k, -0.9, 0.6, tz + 0.055, 0.06);
    for (let i = 0; i < 4; i++) car(k, 0.9 + i * 0.46, back - 0.5, true, TAXI);
    k.box(1.6, 0, back - 0.26, 1.8, 0.025, 0.08, KERB);
    for (const sx of [-1, 1]) {
      for (let i = 0; i < 3; i++) {
        const px = sx * (W * 0.22 + i * 1.1), pz = -D / 2 + 0.35;
        if (D >= 3) { k.cyl(px, 0, pz, 0.12, 0.08, CONCRETE, 6); tree(k, px, 0.06, pz, 0.8, false); }
      }
    }
    parked(k, r, -1.8, back - 0.5, 4, -1);
    for (let x = x0 + 0.8; x < x1; x += 2.6) bench(k, x, F + 0.28, METAL);
    return;
  }

  // the city station's curved roof over the hall and the platform
  const x0 = hx - bw / 2 - 1.2, x1 = Math.min(W / 2 - 2.6, hx + bw / 2 + 1.6);
  const za = back - 0.3, zb = F + 0.55;
  const yAt = wave(k, x0, x1, za, zb, 0.66, 0.2, 8, hex(0xdfe3e6), WHITE);
  for (let px = x0 + 0.15; px <= x1 - 0.1; px += 1.2) {
    for (const pz of [zb - 0.1]) k.cyl(px, 0, pz, 0.022, yAt(pz), METAL, 6);
    if (px < hx - bw / 2 || px > hx + bw / 2) k.cyl(px, 0, za + 0.1, 0.022, yAt(za + 0.1), METAL, 6);
  }
  for (let x = x0 + 0.6; x < x1; x += 1.4) k.glowBox(x, yAt(F + 0.3) - 0.04, F + 0.3, 0.4, 0.02, 0.04, WHITE, LAMP, COOL_GLOW);
  k.glowBox(hx, hh + 0.02, back - 0.03, 1.0, 0.1, 0.02, accent, SIGN, accent);
  // a clean glass footbridge over the loop, and a clad goods shed at the end
  footbridge(k, x0 - 0.5, F, 3, WHITE, 1);
  const gw = Math.min(2.2, W * 0.18), gd = Math.min(1.4, D * 0.36), gx = W / 2 - 0.2 - gw / 2, gz = F - 0.1 - gd / 2;
  k.box(gx, 0, gz, gw, 0.55, gd, hex(0xb9c2c9), hex(0x8f9aa3));
  for (let i = 0; i < 2; i++) k.box(gx - gw / 4 + (i * gw) / 2, 0, gz + gd / 2 + 0.004, gw * 0.32, 0.4, 0.01, hex(0x6d7176));
  k.box(gx, 0.55, gz, gw + 0.06, 0.03, gd + 0.06, METAL);
  k.box(gx, 0.3, gz - gd / 2 - 0.01, gw * 0.5, 0.06, 0.012, accent);
  lorry(k, gx, gz - gd / 2 - 0.4, true, WHITE);
  parked(k, r, hx - 0.4, back - 0.5, 3, -1);
  car(k, hx + 0.6, back - 0.5, true, TAXI);
  car(k, hx + 1.06, back - 0.5, true, TAXI);
  for (let x = x1 + 0.4; x < gx - gw / 2 - 0.3; x += 1.2) lamp(k, x, F + 0.35, 0.48, 3);
  bench(k, hx - 0.8, F + 0.28, METAL);
  bench(k, hx + 0.8, F + 0.28, METAL);
  lamp(k, -W / 2 + 0.3, -D / 2 + 0.3, 0.5, 3);
  if (D >= 3) for (const px of [-W / 2 + 1.2, W / 2 - 1.2]) tree(k, px, 0, -D / 2 + 0.35, 0.8, false);
  void b;
}

// ---------------------------------------------------------------------------------------------
// 1. terminus

const terminus: Draw = (k, W, D, b, r) => {
  if (modern(b)) { concourse(k, W, D, b, r, true); return; }
  const F = D / 2, p = period(b);
  const wall = wallFor(r, p), roof = styleRoof(r), glass = styleGlass(r), trim = styleTrim(), iron = ironFor(r, p);
  const bd = Math.min(1.7, D * 0.34), front = F - 0.15, bz = front - bd / 2, back = front - bd;
  const bw = Math.min(W - 1.2, W * 0.72), pw = Math.min(1.5, bw * 0.14);
  forecourt(k, W, -D / 2, back);

  // the range: a two-storey block between taller end pavilions
  const sh = 0.38;
  stationHouse(k, b, r, 0, bz, bw - 2 * pw + 0.02, bd - 0.1, 2, sh, wall, roof, glass, p === 2 ? 'flat' : 'style', 0.5);
  for (const sx of [-1, 1]) {
    const px = sx * (bw / 2 - pw / 2);
    const mansard = p !== 2 && !cur.form && !TALL_CROWNS.has(cur.crown);
    const top = stationHouse(k, b, r, px, bz, pw, bd, 3, sh, wall, roof, glass, p === 2 ? 'flat' : mansard ? 'none' : cur.form ? 'style' : 'crown', 0.5);
    if (mansard) {
      // a mansard: a steep hip with a flat-topped cresting
      k.hip(px, top, bz, pw + 0.06, 0.42, bd + 0.06, roof);
      k.cyl(px, top + 0.3, bz, 0.012, 0.25, METAL, 4);
    }
    if (p === 2) for (const y of [0.5, 0.54, 1.1]) k.box(sx * (bw / 2 - pw / 2), y, bz, pw + 0.02, 0.014, bd + 0.02, GOLD);
  }

  // the clock tower in the middle of the town side
  const tw = 0.8, td = 0.7, tz = back + 0.1, TH = p === 2 ? 1.95 : 2.15;
  k.box(0, 0, tz, tw, TH, td, wall);
  if (cur.massing === 'ribbed' || p === 2) for (const sx of [-1, 1]) k.box(sx * (tw / 2 - 0.03), 0, tz - td / 2 + 0.03, 0.08, TH + 0.04, 0.08, p === 2 ? GOLD : trim);
  for (let f = 1; f < 4; f++) row(k, b, r, 0, f * 0.38 + 0.12, tz - td / 2, tw - 0.1, 0.16, 1, 3, glass);
  rear(k, tz - td / 2, (z) => {
    k.box(0, 0, z, 0.36, 0.34, 0.02, DARK);
    k.face(0, 0.34, z + 0.006, 0.18, DARK, 8);   // arch clear of the wall (z is only 0.004 off it)
    k.glowBox(0, 0.02, z + 0.012, 0.28, 0.28, 0.006, hex(0x5a4a30), HALL, WARM_GLOW);
    k.box(0, 0.54, z, tw + 0.1, 0.04, 0.05, trim);
    clock(k, 0, TH - 0.3, z + 0.012, 0.2);
  });
  k.turned(Math.PI / 2, () => clock(k, -tz, TH - 0.3, tw / 2 + 0.004, 0.2));
  k.turned(-Math.PI / 2, () => clock(k, tz, TH - 0.3, tw / 2 + 0.004, 0.2));
  let top = TH;
  k.box(0, top, tz, tw + 0.08, 0.05, td + 0.08, trim);
  top += 0.05;
  if (p === 2) {
    for (let i = 0; i < 3; i++) { k.box(0, top, tz, tw * (0.8 - i * 0.2), 0.1, td * (0.8 - i * 0.2), i % 2 ? GOLD : wall); top += 0.1; }
    k.cyl(0, top, tz, 0.015, 0.35, METAL, 5);
    k.glowBox(0, top + 0.35, tz, 0.04, 0.04, 0.04, hex(0x882222), SIGN, hex(0xff3b30));
  } else if (TALL_CROWNS.has(cur.crown) || cur.form) {
    topOff(k, r, 0, top, tz, tw, td, wall);
  } else {
    // an open lantern and a pyramid roof
    for (const sx of [-1, 1]) for (const sz of [-1, 1]) k.box(sx * (tw / 2 - 0.08), top, tz + sz * (td / 2 - 0.08), 0.06, 0.26, 0.06, trim);
    k.box(0, top + 0.26, tz, tw - 0.04, 0.04, td - 0.04, trim);
    k.hip(0, top + 0.3, tz, tw - 0.04, 0.45, td - 0.04, roof);
    k.cyl(0, top + 0.72, tz, 0.012, 0.2, GOLD, 4);
  }

  // a porte-cochère over the entrance and the taxi rank beside it
  k.box(0, 0.42, back - 0.35, tw + 0.7, 0.04, 0.6, trim, roof);
  for (const sx of [-1, 1]) k.box(sx * (tw / 2 + 0.3), 0, back - 0.6, 0.04, 0.42, 0.04, iron);
  k.box(1.9, 0, back - 0.28, 2.0, 0.03, 0.1, KERB);
  for (let i = 0; i < 4; i++) car(k, 1.1 + i * 0.47, back - 0.5, true, TAXI);
  k.box(3.05, 0, back - 0.28, 0.02, 0.3, 0.02, DARK);
  k.glowBox(3.05, 0.3, back - 0.28, 0.16, 0.07, 0.03, TAXI, SIGN, TAXI);
  parked(k, r, -1.1, back - 0.5, 4, -1);
  if (D >= 4) {
    // a fountain on the forecourt in front of the tower
    const fz = (back - 0.9 - D / 2 + 0.7) / 2;
    k.cyl(0, 0, fz, 0.42, 0.07, hex(STONE[1]), 12, hex(0x6fb8e0));
    k.cyl(0, 0.07, fz, 0.06, 0.2, hex(STONE[0]), 6);
    k.cyl(0, 0.27, fz, 0.14, 0.03, hex(STONE[0]), 8, hex(0x9fd4ea));
  }
  if (D >= 3) {
    for (let x = -W / 2 + 1; x < W / 2 - 0.5; x += 3) {
      if (Math.abs(x) < 1.2) continue;
      tree(k, x, 0, -D / 2 + 0.35, 0.8, false);
      lamp(k, x + 1.5, -D / 2 + 0.35, 0.5, p);
    }
  }

  // the train shed over both tracks: iron ribs, glass along the crown, open glazed ends
  const x0 = -W / 2 + 0.15, x1 = W / 2 - 0.15, za = front, zb = F + 2.62, y0 = 0.9;
  const rise = Math.min(1.0, (zb - za) * 0.36);
  const shedRoof = p === 2 ? hex(0xcfcac0) : scale(ROOF_GREY, 0.8);
  const ribs = Math.max(2, Math.round((x1 - x0) / 2));
  vault(k, x0, x1, za, zb, y0, rise, 10, shedRoof, iron, scale(shedRoof, 0.75), ribs);
  for (let j = 0; j <= ribs; j++) {
    const px = x0 + ((x1 - x0) * j) / ribs;
    k.cyl(px, 0, zb, 0.035, y0, iron, 4);
    if (Math.abs(px) > bw / 2 + 0.05) k.cyl(px, 0, za, 0.035, y0, iron, 4);
  }
  for (let x = x0 + 0.8; x < x1; x += 3.2) {
    hanging(k, x, y0 - 0.1, F + 0.3);
    hanging(k, x + 1.6, y0 - 0.1, F + 2.42);
  }
  for (let x = x0 + 1.6; x < x1 - 0.5; x += 3.2) bench(k, x, F + 0.26);
  for (const sx of [-1, 1]) nameBoard(k, sx * W * 0.28, F + 0.36, 0.7, iron, p);
};

// ---------------------------------------------------------------------------------------------
// 2. city station

const cityStation: Draw = (k, W, D, b, r) => {
  if (modern(b)) { concourse(k, W, D, b, r, false); return; }
  const F = D / 2, p = period(b);
  const wall = wallFor(r, p), roof = styleRoof(r), glass = styleGlass(r), trim = styleTrim(), iron = ironFor(r, p);
  const hw = Math.min(3.4, W * 0.3), hd = Math.min(1.3, D * 0.34), hx = -W * 0.05, hz = F - 0.05 - hd / 2, back = hz - hd / 2;
  const gw = Math.min(2.2, W * 0.18), gd = Math.min(1.4, D * 0.36), gx = W / 2 - 0.2 - gw / 2, gz = F - 0.1 - gd / 2;
  forecourt(k, W, -D / 2, back);

  // the station house, with a gabled entrance bay on the town side
  const sh = 0.42, h = 2 * sh + 0.05;
  stationHouse(k, b, r, hx, hz, hw, hd, 2, sh, wall, roof, glass, p === 2 ? 'flat' : 'style', 0.5);
  const bayW = Math.min(1, hw * 0.34);
  k.box(hx, 0, back - 0.1, bayW, h + 0.06, 0.2, scale(wall, 0.95));
  if (p === 1) k.gable(hx, h + 0.06, back - 0.1, bayW + 0.06, 0.26, 0.24, roof, wall, true);
  rear(k, back - 0.2, (z) => {
    k.box(hx === 0 ? 0 : -hx, 0, z, 0.22, 0.3, 0.02, doorCol(r));
    k.glowBox(-hx, 0.31, z + 0.01, 0.22, 0.06, 0.006, GLASS, HALL, WARM_GLOW);
    clock(k, -hx, h - 0.12, z + 0.01, 0.12);
  });
  if (p === 1) for (const sx of [-1, 1]) k.box(hx + sx * hw * 0.32, h, hz, 0.1, 0.36, 0.14, scale(wall, 0.9));
  if (p === 2) decoTouches(k, hx, hz, hw, hd, h, back - 0.1);

  // the long canopy along the platform, from the far end to the goods shed
  const cRoof = p === 1 ? scale(roof, 0.9) : WHITE;
  canopy(k, -W / 2 + 0.3, gx - gw / 2 - 0.25, F - 0.08, F + 0.55, 0.48, cRoof, iron, p);
  for (let x = -W / 2 + 0.9; x < gx - gw / 2 - 0.4; x += 1.5) hanging(k, x, 0.47, F + 0.3);
  for (const x of [hx - hw / 2 - 1.5, hx + hw / 2 + 0.7]) bench(k, x, F + 0.22);
  nameBoard(k, hx + hw / 2 + 1.5, F + 0.3, 0.6, iron, p);
  nameBoard(k, -W / 2 + 0.7, F + 0.3, 0.6, iron, p);

  // the footbridge over the loop
  footbridge(k, hx - hw / 2 - 0.9, F, p, iron, -1);

  // the goods shed at the end
  const gwall = p === 1 ? pick(r, BRICK) : scale(wall, 0.92);
  k.box(gx, 0, gz, gw, 0.6, gd, gwall);
  if (p === 2) flatTopish(k, gx, 0.6, gz, gw, gd, gwall);
  else k.gable(gx, 0.6, gz, gw + 0.1, 0.3, gd + 0.1, p === 1 ? ROOF_GREY : roof, gwall);
  k.box(gx, 0, gz + gd / 2 + 0.004, gw * 0.4, 0.44, 0.012, p === 1 ? WOOD : hex(0x6d7176));
  k.box(gx, 0.46, gz + gd / 2 + 0.2, gw * 0.6, 0.03, 0.4, cRoof);
  k.box(gx, 0, gz - gd / 2 - 0.004, gw * 0.3, 0.38, 0.012, p === 1 ? WOOD : hex(0x6d7176));
  row(k, b, r, gx, 0.38, gz + gd / 2, gw - 0.2, 0.1, 4, 1, glass);
  k.box(gx, 0, gz + gd / 2 + 0.25, gw * 0.9, 0.12, 0.45, CONCRETE);
  for (let i = 0; i < 3; i++) k.box(gx - gw * 0.3 + i * 0.16, 0.12, gz + gd / 2 + 0.3, 0.12, 0.1, 0.12, WOOD);
  lorry(k, gx - 0.2, gz - gd / 2 - 0.4, true, pick(r, [0x3f7d3a, 0x2f4d7a, 0x8a3a2a]));

  // the forecourt: a couple of taxis at the door, cars along the kerb, lamps and trees
  car(k, hx + bayW / 2 + 0.3, back - 0.5, true, TAXI);
  car(k, hx + bayW / 2 + 0.76, back - 0.5, true, TAXI);
  parked(k, r, hx - bayW / 2 - 0.35, back - 0.5, 3, -1);
  for (let x = gx - gw / 2 - 0.5; x < gx + gw / 2 + 0.1; x += 0.8) lamp(k, x, F + 0.38, 0.46, p);
  if (D >= 3) {
    for (let x = -W / 2 + 0.6; x < W / 2 - 0.4; x += 2.4) {
      if (Math.abs(x - hx) < 0.9) continue;
      if (Math.abs(x - hx) < 2) lamp(k, x, -D / 2 + 0.35, 0.5, p);
      else tree(k, x, 0, -D / 2 + 0.35, 0.75, false);
    }
  }
  void trim;
};

/** A flat roof with a thin coping, for streamliner goods sheds. */
function flatTopish(k: Kit, x: number, y: number, z: number, w: number, d: number, wall: RGB): void {
  k.box(x, y, z, w + 0.04, 0.05, d + 0.04, scale(wall, 0.85), hex(0xb0aca4));
  k.box(x, y + 0.05, z + d / 2 - 0.01, w + 0.04, 0.02, 0.02, WHITE);
}

// ---------------------------------------------------------------------------------------------
// 3. town station

const townStation: Draw = (k, W, D, b, r) => {
  const F = D / 2, p = modern(b) ? 3 : period(b);
  const wall = wallFor(r, p), roof = styleRoof(r), glass = styleGlass(r), iron = ironFor(r, p);
  const hw = Math.min(2.4, W * 0.34), hd = Math.min(1.0, D * 0.36), hx = -W * 0.08, hz = F - 0.05 - hd / 2, back = hz - hd / 2;
  forecourt(k, W, -D / 2, back);
  const sh = 0.5;
  stationHouse(k, b, r, hx, hz, hw, hd, 1, sh, wall, roof, glass, p >= 2 ? 'flat' : 'style');
  rear(k, back, (z) => {
    k.box(-hx, 0, z, 0.2, 0.3, 0.02, doorCol(r));
    k.glowBox(-hx, 0.34, z + 0.004, 0.3, 0.07, 0.01, p === 1 ? WHITE : hex(0xf2ead0), SIGN, WARM_GLOW);
  });
  if (p === 1) k.box(hx + hw * 0.3, sh + 0.05, hz - hd * 0.2, 0.1, 0.4, 0.14, scale(wall, 0.9));
  if (p === 2) decoTouches(k, hx, hz, hw, hd, sh + 0.05, back + 0.07);

  // one canopy along the front of the house
  const c0 = Math.max(-W / 2 + 0.2, hx - hw / 2 - 0.7), c1 = Math.min(W / 2 - 1.0, hx + hw / 2 + 0.9);
  canopy(k, c0, c1, F - 0.06, F + 0.52, 0.47, p === 1 ? scale(roof, 0.9) : WHITE, iron, p, p === 3);
  hanging(k, (c0 + c1) / 2 - 0.6, 0.46, F + 0.3);
  hanging(k, (c0 + c1) / 2 + 0.6, 0.46, F + 0.3);
  bench(k, hx - 0.35, F + 0.22, p === 3 ? METAL : WOOD);
  bench(k, hx + 0.45, F + 0.22, p === 3 ? METAL : WOOD);
  if (W >= 5) nameBoard(k, c0 - 0.45, F + 0.3, 0.55, iron, p);

  // the signal box at the end of the platform, and the signal beyond it
  if (W >= 4.5) {
    signalBox(k, W / 2 - 0.45, F - 0.3, p, r, roof);
    signal(k, W / 2 - 0.12, F + 0.44, p);
    lamp(k, c1 + 0.3, F + 0.38, 0.46, p);
  }

  // the forecourt: a car, a bicycle rack, a lamp and tubs of flowers
  if (D >= 2) {
    car(k, hx + hw / 2 + 0.5, back - 0.45, true, pick(r, CARS));
    car(k, hx - hw / 2 - 0.3, back - 0.45, true, r() < 0.5 ? TAXI : pick(r, CARS));
    lamp(k, hx, -D / 2 + 0.3, 0.48, p);
    for (const sx of [-1, 1]) {
      k.box(hx + sx * 0.3, 0, back - 0.12, 0.12, 0.06, 0.12, p === 3 ? CONCRETE : WOOD);
      k.box(hx + sx * 0.3, 0.06, back - 0.12, 0.1, 0.04, 0.1, hex(0xd8344a), hex(0xe86a8a));
    }
    if (W >= 6) tree(k, -W / 2 + 0.4, 0, -D / 2 + 0.4, 0.8, false);
  }
};

// ---------------------------------------------------------------------------------------------
// 4. halt

const halt: Draw = (k, W, D, b, r) => {
  const F = D / 2, p = period(b);
  const wall = styleWall(r), roof = styleRoof(r), iron = ironFor(r, p);
  const sw = Math.min(1.0, W * 0.3), sd = 0.34, sx = W > 2.5 ? W * 0.08 : 0, sz = F + 0.02;
  // the path up from the lane and a little fence along the back of the platform
  k.box(sx - sw / 2 - 0.25, 0, (-D / 2 + F) / 2, 0.3, 0.012, F + D / 2, PATH);
  const fz = F - 0.2, gap0 = sx - sw / 2 - 0.42, gap1 = sx - sw / 2 - 0.08;
  for (const [a, c] of [[-W / 2 + 0.1, gap0], [gap1, W / 2 - 0.1]]) {
    if (c - a < 0.1) continue;
    for (const y of [0.07, 0.15]) k.box((a + c) / 2, y, fz, c - a, 0.02, 0.012, p === 3 ? METAL : WHITE);
    for (let x = a; x <= c + 0.001; x += 0.3) k.box(x, 0, fz, 0.02, 0.18, 0.02, p === 3 ? METAL : WHITE);
  }
  // the shelter
  if (p === 1) {
    const board = curArch === 'classic' ? hex(0x6e5a3e) : wall;
    k.box(sx, 0, sz - sd / 2 + 0.02, sw, 0.36, 0.04, board);
    for (const s of [-1, 1]) k.box(sx + s * (sw / 2 - 0.02), 0, sz, 0.04, 0.36, sd, board);
    k.box(sx, 0.36, sz, sw + 0.06, 0.02, sd + 0.06, scale(roof, 0.8));
    roofOver(k, r, sx, 0.38, sz, sw + 0.06, sd + 0.06, board, roof);
    k.box(sx, 0.32, sz + sd / 2 + 0.03, sw + 0.06, 0.04, 0.01, iron);
  } else if (p === 2) {
    const shell = hex(0xefe8d6);
    k.box(sx, 0, sz - sd / 2 + 0.02, sw, 0.36, 0.04, shell);
    for (const s of [-1, 1]) k.box(sx + s * (sw / 2 - 0.02), 0, sz, 0.04, 0.36, sd, shell);
    vault(k, sx - sw / 2 - 0.04, sx + sw / 2 + 0.04, sz - sd / 2 - 0.02, sz + sd / 2 + 0.06, 0.34, 0.07, 4, shell, iron, shell, 1, false);
    k.box(sx, 0.18, sz - sd / 2 - 0.004, sw, 0.02, 0.01, hex(0x2f7fb5));
  } else {
    k.box(sx, 0, sz - sd / 2 + 0.02, sw, 0.36, 0.02, mix(GLASS_LIGHT, WHITE, 0.3));
    for (const s of [-1, 1]) k.box(sx + s * (sw / 2 - 0.02), 0, sz, 0.025, 0.36, 0.025, METAL);
    k.box(sx, 0.36, sz, sw + 0.08, 0.03, sd + 0.06, WHITE);
    k.glowBox(sx + sw / 2 - 0.12, 0.15, sz - sd / 2 + 0.035, 0.14, 0.12, 0.01, hex(0x2f5a96), SIGN, COOL_GLOW);
  }
  bench(k, sx, sz - 0.05, p === 3 ? METAL : WOOD);
  hanging(k, sx, 0.35, sz + 0.05);
  nameBoard(k, sx - sw / 2 - 0.45 < -W / 2 + 0.2 ? sx + sw / 2 + 0.4 : sx - sw / 2 - 0.5, F + 0.32, 0.5, iron, p);
  lamp(k, W / 2 - 0.2, F + 0.36, 0.46, p);
  if (W >= 3) lamp(k, -W / 2 + 0.2, F + 0.36, 0.46, p);
  // a milk churn or a bike by the gate, and a flower tub
  k.cyl(gap1 + 0.1, 0, fz - 0.12, 0.035, 0.1, METAL, 6);
  k.box(W / 2 - 0.45, 0, F + 0.1, 0.1, 0.06, 0.1, WOOD);
  k.box(W / 2 - 0.45, 0.06, F + 0.1, 0.08, 0.04, 0.08, hex(0xf2a93b), hex(0xf2c14e));
};

// ---------------------------------------------------------------------------------------------
// 5. goods yard

const goodsYard: Draw = (k, W, D, b, r) => {
  const F = D / 2, p = period(b);
  const wall = p === 1 ? (curArch === 'classic' ? pick(r, BRICK) : styleWall(r)) : p === 2 ? scale(styleWall(r), 0.95) : hex(0xb9c2c9);
  const roof = p === 3 ? hex(0x8f9aa3) : styleRoof(r), glass = styleGlass(r);
  const crane = p === 1 ? hex(0x3f4a52) : p === 2 ? hex(0x4f6b4a) : SAFETY;

  // a gravel yard
  k.box(0, 0, 0, W - 0.08, 0.01, D - 0.08, hex(0xbdb6a6));

  // the goods shed and its loading dock under a canopy, facing the track
  const gw = Math.min(4, W * 0.3), gd = Math.min(1.8, D * 0.38), gx = -W / 2 + gw / 2 + 0.4, gfront = F - 0.45, gz = gfront - gd / 2;
  k.box(gx, 0, gz, gw, 0.7, gd, wall);
  k.box(gx, 0, gz, gw + 0.02, 0.05, gd + 0.02, scale(wall, 0.8));
  if (p === 3) k.box(gx, 0.7, gz, gw + 0.06, 0.04, gd + 0.06, METAL, roof);
  else {
    k.gable(gx, 0.7, gz, gw + 0.12, 0.34, gd + 0.12, roof, wall);
    k.box(gx, 1.0, gz, gw * 0.5, 0.06, 0.16, mix(GLASS_LIGHT, WHITE, 0.3));
  }
  const doors = Math.max(1, Math.round(gw / 1.1));
  for (let i = 0; i < doors; i++) {
    const dx = gx - gw / 2 + (gw / doors) * (i + 0.5);
    k.box(dx, 0.14, gfront + 0.004, 0.46, 0.42, 0.012, p === 1 ? WOOD : hex(0x6d7176));
    k.box(dx, 0.14, gz - gd / 2 - 0.004, 0.46, 0.42, 0.012, p === 1 ? WOOD : hex(0x6d7176));
  }
  row(k, b, r, gx + gw / 2, 0.36, gz, gd - 0.3, 0.14, 3, 0, glass);
  row(k, b, r, gx - gw / 2, 0.36, gz, gd - 0.3, 0.14, 3, 2, glass);
  k.box(gx, 0, F - 0.02, gw + 0.4, 0.14, 0.86, CONCRETE);
  k.box(gx, 0.14, F + 0.39, gw + 0.4, 0.012, 0.06, SAFETY);
  canopy(k, gx - gw / 2 - 0.1, gx + gw / 2 + 0.1, gfront - 0.02, F + 0.5, 0.56, p === 3 ? METAL : scale(roof, 0.9), p === 1 ? hex(0x3f4a52) : METAL, p === 2 ? 3 : p);
  for (let i = 0; i < 5; i++) {
    const cx = gx - gw / 2 + 0.2 + i * (gw / 5);
    if (r() < 0.7) k.box(cx, 0.14, F - 0.05, 0.14, 0.12, 0.14, WOOD);
    if (r() < 0.4) k.box(cx + 0.02, 0.26, F - 0.05, 0.1, 0.1, 0.1, scale(WOOD, 1.15));
  }
  hanging(k, gx - gw / 4, 0.55, F + 0.1);
  hanging(k, gx + gw / 4, 0.55, F + 0.1);

  // the gantry crane spanning the main line, over a stacking ground of crates and pallets
  const cx = W * 0.08, legZ0 = F + 0.22, legZ1 = F + 1.52, gy = 1.05;
  for (const lz of [legZ0, legZ1]) {
    for (const s of [-1, 1]) k.box(cx + s * 0.34, 0, lz, 0.06, gy, 0.06, crane);
    k.box(cx, gy - 0.25, lz, 0.74, 0.04, 0.04, crane);
    k.bar([cx - 0.34, 0.3, lz], [cx + 0.34, gy - 0.25, lz], 0.012, crane);
    k.box(cx, 0, lz, 0.8, 0.03, 0.12, DARK);
  }
  for (const s of [-1, 1]) k.box(cx + s * 0.34, gy, (legZ0 + legZ1) / 2 - 0.35, 0.07, 0.1, legZ1 - legZ0 + 1.5, crane);
  const trolleyZ = F + 0.9;
  k.box(cx, gy + 0.1, trolleyZ, 0.8, 0.12, 0.26, crane);
  k.box(cx + 0.2, gy - 0.1, trolleyZ, 0.16, 0.12, 0.2, p === 3 ? WHITE : hex(0x6e2f2f));
  k.box(cx, 0.55, trolleyZ, 0.01, gy - 0.55, 0.01, DARK);
  k.box(cx, 0.5, trolleyZ, 0.3, 0.05, 0.12, DARK);
  k.glowBox(cx - 0.34, gy + 0.22, trolleyZ, 0.04, 0.04, 0.04, hex(0x886622), SIGN, SAFETY);
  for (let i = 0; i < 6; i++) {
    const px = cx - 0.5 + (i % 3) * 0.5, pz = F - 0.5 - Math.floor(i / 3) * 0.45;
    const n = 1 + Math.floor(r() * 3);
    k.box(px, 0, pz, 0.34, 0.03, 0.3, hex(0xb08a5a));
    for (let j = 0; j < n; j++) k.box(px, 0.03 + j * 0.13, pz, 0.28 - j * 0.02, 0.12, 0.24 - j * 0.02, j % 2 ? scale(WOOD, 1.2) : WOOD);
  }

  // the siding stub with two parked wagons and a buffer stop
  const sz = -D / 2 + 0.75, sx0 = cx - 0.6, sx1 = W / 2 - 0.25;
  if (D >= 2.5 && sx1 - sx0 > 2) {
    k.box((sx0 + sx1) / 2, 0, sz, sx1 - sx0, 0.04, 0.5, BALLAST);
    for (let x = sx0 + 0.1; x < sx1; x += 0.36) k.box(x, 0.04, sz, 0.06, 0.015, 0.36, SLEEPER);
    for (const s of [-1, 1]) k.box((sx0 + sx1) / 2, 0.055, sz + s * 0.11, sx1 - sx0, 0.02, 0.02, RAIL);
    k.box(sx1 - 0.08, 0.04, sz, 0.1, 0.14, 0.34, hex(0x6e2f2f));
    k.box(sx1 - 0.14, 0.12, sz, 0.02, 0.05, 0.3, hex(0xe2412f));
    const wagon = (x: number, van: boolean, col: RGB) => {
      k.box(x, 0.075, sz, 0.9, 0.05, 0.3, DARK);
      for (const s of [-1, 1]) k.box(x + s * 0.28, 0.055, sz, 0.12, 0.05, 0.28, hex(0x2a2a2a));
      if (van) {
        k.box(x, 0.125, sz, 0.86, 0.3, 0.3, col);
        k.gable(x, 0.425, sz, 0.88, 0.05, 0.32, hex(0x8c8a84), col);
        k.box(x, 0.16, sz + 0.152, 0.26, 0.24, 0.01, scale(col, 0.8));
      } else {
        for (const s of [-1, 1]) k.box(x, 0.125, sz + s * 0.14, 0.86, 0.14, 0.02, col);
        for (const s of [-1, 1]) k.box(x + s * 0.42, 0.125, sz, 0.02, 0.14, 0.28, col);
        if (p === 3) k.box(x, 0.13, sz, 0.8, 0.12, 0.24, pick(r, CONTAINER));
        else k.hip(x, 0.2, sz, 0.8, 0.1, 0.24, p === 1 ? COAL : hex(0xb8a88a));
      }
    };
    wagon(sx1 - 0.75, true, p === 3 ? hex(0x2f5a96) : hex(0x8a3a2a));
    wagon(sx1 - 1.72, false, p === 1 ? hex(0x5a5048) : hex(0x6d7176));
  }

  // steam: a coal stage and a water tower; later lines: a fuel tank and a floodlight mast
  const ex = W / 2 - 1.0, ez = F - 0.45;
  if (p === 1) {
    k.box(ex, 0, ez, 1.1, 0.28, 0.5, pick(r, BRICK), scale(COAL, 1.4));
    k.hip(ex - 0.15, 0.28, ez, 0.6, 0.14, 0.34, COAL);
    for (let i = 0; i < 3; i++) k.box(ex + 0.3 + i * 0.07, 0.28, ez + 0.1, 0.06, 0.05, 0.06, hex(0x6d6f73));
    k.box(ex + 0.45, 0.28, ez + 0.12, 0.03, 0.4, 0.03, DARK);
    k.bar([ex + 0.45, 0.66, ez + 0.12], [ex + 0.45, 0.6, ez + 0.5], 0.012, DARK);
    k.box(ex + 0.45, 0.42, ez + 0.5, 0.005, 0.18, 0.005, DARK);
    const wx = W / 2 - 0.3, wz = F - 1.2;
    for (const s1 of [-1, 1]) for (const s2 of [-1, 1]) k.box(wx + s1 * 0.12, 0, wz + s2 * 0.12, 0.03, 0.6, 0.03, DARK);
    k.cyl(wx, 0.6, wz, 0.2, 0.26, hex(0x5a5f6b), 10, hex(0x4a4f5a));
    k.bar([wx, 0.7, wz + 0.2], [wx, 0.62, wz + 0.4], 0.02, DARK);
  } else {
    k.cyl(ex, 0, ez - 0.1, 0.18, 0.4, p === 3 ? WHITE : hex(0xd8d0c0), 10);
    k.box(ex + 0.5, 0, ez, 0.03, 1.3, 0.03, METAL);
    k.glowBox(ex + 0.5, 1.3, ez, 0.18, 0.05, 0.08, hex(0xd0d4d8), LAMP, COOL_GLOW);
  }

  // the yard office, a lorry at the gate
  const ox = -W / 2 + 0.5, oz = -D / 2 + 0.4;
  if (D >= 2.5) {
    k.box(ox, 0, oz, 0.5, 0.3, 0.36, p === 1 ? pick(r, BRICK) : styleWall(r));
    roofOver(k, r, ox, 0.3, oz, 0.5, 0.36, wall, roof, p === 1 ? cur.form : 'flat');
    row(k, b, r, ox, 0.1, oz + 0.18, 0.4, 0.12, 2, 1, glass);
    lorry(k, gx + 0.3, gz - gd / 2 - 0.4, true, pick(r, [0x3f7d3a, 0x2f4d7a, 0x8a3a2a, 0xe2412f]));
    // goods waiting by the siding: sacks on pallets, a timber stack, and a lorry backed up to them
    const sy = -D / 2 + 1.35;
    for (let i = 0; i < 4; i++) {
      const px = cx + 0.2 + i * 0.42;
      k.box(px, 0, sy, 0.34, 0.03, 0.3, hex(0xb08a5a));
      k.box(px, 0.03, sy, 0.3, 0.1, 0.26, hex(0xd8c8a0), hex(0xe4d6b0));
    }
    for (let j = 0; j < 3; j++) k.box(cx + 2.1, j * 0.06, sy, 0.9, 0.055, 0.3 - j * 0.04, j % 2 ? hex(0xd8b27a) : hex(0xc9a066));
    lorry(k, cx - 0.5, sy + 0.05, true, pick(r, [0x3f7d3a, 0x2f4d7a, 0xe2412f]));
    lamp(k, ox + 0.5, oz + 0.3, 0.5, p);
  }
  lamp(k, gx + gw / 2 + 0.35, F + 0.35, 0.46, p);
};

// ---------------------------------------------------------------------------------------------
// 6. harbour depot

const harbourDepot: Draw = (k, W, D, b, r) => {
  const F = D / 2, p = period(b);
  const clad = p === 1 ? pick(r, BRICK) : pick(r, [0xc9ced1, 0xb9c2c9, 0xd8d0c0, 0xa9b8c4]);
  const roof = pick(r, [0x5a6b7a, 0x6d7176, 0x8a4a3a]);
  k.box(0, 0, 0, W - 0.08, 0.012, D - 0.08, hex(0xa8a49c));

  // the transit shed, doors on both sides, a dock along the track
  const tw = Math.min(6, W * 0.55), td = Math.min(1.5, D * 0.4), tx = -W / 2 + tw / 2 + 0.3, tfront = F - 0.45, tz = tfront - td / 2;
  k.box(tx, 0, tz, tw, 0.6, td, clad);
  vault(k, tx - tw / 2 - 0.04, tx + tw / 2 + 0.04, tz - td / 2 - 0.05, tz + td / 2 + 0.05, 0.6, 0.22, 6, roof, scale(roof, 0.8), scale(roof, 0.7), 1, false);
  for (const ex of [tx - tw / 2, tx + tw / 2]) k.gable(ex, 0.6, tz, 0.02, 0.2, td, clad, clad);
  const doors = Math.max(1, Math.round(tw / 0.9));
  for (let i = 0; i < doors; i++) {
    const dx = tx - tw / 2 + (tw / doors) * (i + 0.5);
    for (const [z, s] of [[tfront, 1], [tz - td / 2, -1]] as const) k.box(dx, 0.12, z + s * 0.004, 0.4, 0.4, 0.012, hex(0x6d7176));
    k.box(dx, 0.54, tfront + 0.004, 0.46, 0.04, 0.02, SAFETY);
  }
  row(k, b, r, tx + tw / 2, 0.3, tz, td - 0.3, 0.12, 3, 0, GLASS);
  k.box(tx, 0.4, tz + td / 2 + 0.01, tw * 0.3, 0.1, 0.012, WHITE);
  k.box(tx, 0, F - 0.05, tw + 0.2, 0.12, 0.8, CONCRETE);
  k.box(tx, 0.52, F - 0.04, tw + 0.2, 0.03, 0.82, METAL);
  for (let x = tx - tw / 2 + 0.1; x <= tx + tw / 2 + 0.05; x += 1.2) k.box(x, 0.12, F + 0.3, 0.03, 0.4, 0.03, METAL);
  hanging(k, tx - tw / 4, 0.51, F + 0.15);
  hanging(k, tx + tw / 4, 0.51, F + 0.15);

  // containers stacked along the track beyond the shed
  const cx0 = tx + tw / 2 + 0.3, cx1 = W / 2 - 0.1;
  const ncol = Math.floor((cx1 - cx0) / 0.92);
  for (let i = 0; i < ncol; i++) {
    for (let j = 0; j < 2; j++) {
      const h = 1 + Math.floor(r() * (j === 0 ? 2 : 3));
      for (let lvl = 0; lvl < h; lvl++) k.box(cx0 + 0.46 + i * 0.92, lvl * 0.27, F - 0.3 - j * 0.44, 0.88, 0.26, 0.38, pick(r, CONTAINER));
    }
  }

  // the dockside crane on its portal, jib out over the quay behind
  const qx = W / 2 - 0.9, qz = -D / 2 + 0.7, red = hex(0xe2412f), frame = p === 1 ? hex(0x3f4a52) : SAFETY;
  for (const s1 of [-1, 1]) for (const s2 of [-1, 1]) k.box(qx + s1 * 0.3, 0, qz + s2 * 0.3, 0.05, 0.6, 0.05, frame);
  k.box(qx, 0.6, qz, 0.72, 0.06, 0.72, frame);
  k.cyl(qx, 0.66, qz, 0.12, 0.12, DARK, 8);
  k.box(qx, 0.78, qz + 0.05, 0.36, 0.3, 0.46, frame, DARK);
  k.box(qx, 0.86, qz + 0.29, 0.26, 0.14, 0.012, GLASS);
  k.box(qx, 0.78, qz + 0.34, 0.14, 0.34, 0.14, red);
  k.bar([qx, 0.9, qz - 0.05], [qx, 1.95, qz - 1.1], 0.035, frame);
  k.bar([qx, 1.1, qz + 0.1], [qx, 1.95, qz - 1.1], 0.012, DARK);
  k.box(qx, 0.72, qz - 1.1, 0.008, 1.23, 0.008, DARK);
  k.box(qx, 0.68, qz - 1.1, 0.12, 0.05, 0.12, DARK);
  k.glowBox(qx, 1.95, qz - 1.1, 0.05, 0.05, 0.05, hex(0x882222), SIGN, hex(0xff3b30));

  // a reach lorry with a box, a lamp mast and bollards on the quay edge
  if (D >= 2.5) lorry(k, tx, tz - td / 2 - 0.4, true, pick(r, [0x2f4d7a, 0xe2412f, 0x3f7d3a]));
  k.box(cx0 - 0.15, 0, -D / 2 + 0.4, 0.03, 1.2, 0.03, METAL);
  k.glowBox(cx0 - 0.15, 1.2, -D / 2 + 0.4, 0.16, 0.05, 0.08, hex(0xd0d4d8), LAMP, p === 1 ? WARM_GLOW : COOL_GLOW);
  // the quay edge: a timber fender along the back with bollards on it
  k.box(0, 0, -D / 2 + 0.06, W - 0.08, 0.04, 0.1, hex(0x5a4a3c));
  for (let x = -W / 2 + 0.4; x < W / 2 - 1.6; x += 1.3) k.cyl(x, 0.04, -D / 2 + 0.12, 0.04, 0.07, DARK, 6);
  void RUST; void PAVE_LINE;
};

export const STATION_DRAW: Record<StationKind, Draw> = { terminus, cityStation, townStation, halt, goodsYard, harbourDepot };
