import type { CellDoc, ClientMsg, ServerMsg, Welcome } from '../../shared/protocol';
import type { CultureReport } from '../../shared/culture';
import type { OnlineExtra } from './online';
import type { Culture } from '../game/culture';

/**
 * The world's culture book online (server/townCulture.ts, the user, 4 Nov 2026): a town's culture is every fleet's.
 * Signed in, the game asks for the whole book and sends its own parts in every town its save has written in (the
 * server keeps the higher of each, so this is safe every time); from then on each delivery's new totals go out, gathered
 * and sent at most every SEND_S seconds, and every fleet's changes come in.
 */

const SEND_S = 2;
/** Towns to a report: the server takes this many at most. */
const CHUNK = 400;

export interface CultureNetHost { online(): boolean; post(m: ClientMsg): void }

export class CultureNet implements OnlineExtra {
  private out: CultureReport['towns'] = {};
  private wait = 0;

  constructor(private host: CultureNetHost, private culture: Culture) {}

  welcome(w: Welcome): void {
    this.out = {};
    this.culture.me = w.you.id;
  }
  cell(_k: string, _doc: CellDoc): void { /* nothing per cell */ }
  got(m: ServerMsg): boolean {
    if (m.t !== 'culture') return false;
    this.culture.fromWorld(m);
    return true;
  }
  ready(): void {
    if (!this.host.online()) return;
    this.culture.onShare = (key, t) => { this.out[key] = t; };
    this.host.post({ t: 'culture' });
    // the fleet's own parts as its save has them: an older save's culture becomes its part in the world's book
    const all = Object.entries(this.culture.shareAll());
    for (let i = 0; i < all.length; i += CHUNK) this.host.post({ t: 'culture', towns: Object.fromEntries(all.slice(i, i + CHUNK)) });
  }
  frame(dt: number): void {
    if (!this.host.online() || (this.wait -= dt) > 0) return;
    this.wait = SEND_S;
    if (!Object.keys(this.out).length) return;
    this.host.post({ t: 'culture', towns: this.out });
    this.out = {};
  }
  forget(): void { /* nothing per cell */ }
  reset(): void {
    this.culture.onShare = null;
    this.culture.me = null;
    this.culture.leaveWorld();
    this.out = {};
  }
}
