/**
 * The Fleets tab of the social window (docs/social.html): one list of every other fleet, whoever runs it.
 * Chips narrow it to the players signed in, your friends, every player, the CPU firms met, or everyone; the
 * header's search box finds a name in any of them. A row is a fleet: its shield, its name, who runs it and
 * where they are (or "CPU" and its trade), its size. Picking a row fills the right column: a player's gets
 * the fleet card (net/fleetCard.ts), a firm's the Rivals detail (game/firmsWindow.ts). Under the list, who
 * carries the town you are in. Offline there are only the firms, as the old Rivals tab had.
 */
import { esc, money } from '../game/cargoHud';
import { badgeUrl } from '../render/fleetBadges';
import { lastSeen, otherPlayers } from '../game/standings';
import type { FirmsWindow } from '../game/firmsWindow';
import type { SocialTabBody } from '../game/socialWindow';
import type { BoardRow, FriendRow, Pid, Who } from '../../shared/protocol';
import type { FleetCard } from './fleetCard';

type Chip = 'online' | 'friends' | 'players' | 'firms' | 'everyone' | 'crew';
const CHIP_LABEL: Record<Chip, string> = { online: 'Online', friends: 'Friends', players: 'Players', firms: 'Firms', everyone: 'Everyone', crew: 'My fleet' };

export interface FleetsHost {
  online(): boolean;
  rows(): BoardRow[];
  me(): Pid | null;
  crewId(): string | null;
  /** Everyone the server has named this session, signed in or spoken of. */
  people(): Map<Pid, Who>;
  friends(): FriendRow[];
  cellOf(pid: Pid): string | null;
  here(): string;
  /** My shared fleet's other members (docs/sharedfleets.html). */
  crewMembers(): { id: Pid; name: string; online: boolean }[];
  /** Ask the server for its board again. */
  ask(): void;
}

/** A player's fleet as a row: their board line, or a stand-in while their game has never saved. */
interface PlayerRow { row: BoardRow; online: boolean; cell: string | null; friend: FriendRow | undefined }

export class FleetsTab implements SocialTabBody {
  private chip: Chip | null = null;
  private text = '';
  /** What is picked: a player's id, or a firm's ("f:" + id); null for your own card. */
  private pick: string | null = null;

  /** The icons of the titles a player wears this week (net/titles.ts), set by the game. */
  titleIcons: (pid: string) => string = () => '';

  constructor(private host: FleetsHost, private card: FleetCard, private firms: FirmsWindow) {
    firms.onShow = (id) => { this.pick = `f:${id}`; };
  }

  opened(): void { if (this.host.online()) this.host.ask(); }
  tick(): void { if (this.host.online()) this.host.ask(); }
  search(text: string): void { this.text = text.toLowerCase(); }
  afterRender(left: HTMLElement, right: HTMLElement): void { this.card.afterRender(left, right); }

  /** Open the tab on a fleet (a name clicked anywhere). */
  show(pid: Pid): void { this.pick = pid === this.host.me() ? null : pid; }

  press(target: HTMLElement): boolean {
    const c = target.closest('[data-fchip]') as HTMLElement | null;
    if (c) { this.chip = c.dataset.fchip as Chip; return true; }
    const p = target.closest('[data-fpick]') as HTMLElement | null;
    if (p) { this.pick = p.dataset.fpick === 'me' ? null : p.dataset.fpick!; return true; }
    if (this.card.press(target)) return true;
    return this.firms.press(target);
  }

  /** Every other player's fleet: the board's lines, and whoever is signed in without one yet. */
  private players(): PlayerRow[] {
    if (!this.host.online()) return [];
    const me = this.host.me(), crew = this.host.crewId();
    const friends = this.host.friends();
    const list = otherPlayers(this.host.rows(), me, crew).map((row) => ({ row, online: !!row.online || !!this.host.cellOf(row.id), cell: this.host.cellOf(row.id), friend: friends.find((f) => f.id === row.id) }));
    const have = new Set(list.map((p) => p.row.id));
    const mates = new Set(this.host.crewMembers().map((m) => m.id));
    for (const [id, who] of this.host.people()) {
      if (id === me || have.has(id) || mates.has(id) || !this.host.cellOf(id)) continue;
      list.push({ row: { id, name: who.brand?.name ?? who.name, by: who.name, cpu: false, worth: 0, units: 0, towns: 0, primary: who.brand?.primary ?? 0xe2412f, accent: who.brand?.accent ?? 0xffffff, logo: who.brand?.logo ?? '', online: true }, online: true, cell: this.host.cellOf(id), friend: friends.find((f) => f.id === id) });
    }
    // friends first, then those signed in, nearest first, then the richest
    const here = this.host.here().split(',').map(Number);
    const far = (c: string | null) => { if (!c) return 1e9; const [cx, cz] = c.split(',').map(Number); return Math.max(Math.abs(cx - here[0]), Math.abs(cz - here[1])); };
    return list.sort((a, b) => Number(!!b.friend) - Number(!!a.friend) || Number(b.online) - Number(a.online) || far(a.cell) - far(b.cell) || b.row.worth - a.row.worth);
  }

  private away(c: string): string {
    const here = this.host.here().split(',').map(Number);
    const [cx, cz] = c.split(',').map(Number);
    const dx = cx - here[0], dz = cz - here[1];
    const n = Math.max(Math.abs(dx), Math.abs(dz));
    if (n === 0) return 'in this county · hears you';
    const compass = ['east', 'south-east', 'south', 'south-west', 'west', 'north-west', 'north', 'north-east'][((Math.round(Math.atan2(dz, dx) / (Math.PI / 4)) % 8) + 8) % 8];
    return `${n} ${n === 1 ? 'county' : 'counties'} ${compass}`;
  }

  private playerRow(p: PlayerRow): string {
    const r = p.row;
    // where they are, unless they keep it to friends (and haven't added you) or to themselves
    const shown = r.wh !== 'hidden' && (r.wh !== 'friends' || !!p.friend?.mutual);
    const where = p.online && p.cell && shown ? ` · ${this.away(p.cell)}` : '';
    const sub = `${esc(r.by ?? 'a player')}${p.online ? ' <i class="on"></i>' : ` · ${esc(lastSeen(r))}`}${where}`;
    const line = [`${r.units} vehicle${r.units === 1 ? '' : 's'}`, r.towns ? `${r.towns} town${r.towns === 1 ? '' : 's'}` : '', r.hearts ? `<span class="hrt">♥ ${r.hearts}</span>` : '', p.friend ? (p.friend.mutual ? 'friend' : 'friend · hasn’t added you back') : ''].filter(Boolean).join(' · ');
    const motto = r.motto ? `<small class="motto">“${esc(r.motto)}”</small>` : '';
    const icons = this.titleIcons(r.id);
    return `<li class="${this.pick === r.id ? 'on' : ''}${p.online ? '' : ' quiet'}"><button type="button" class="pick" data-fpick="${esc(r.id)}"><span class="fl-shield"><img src="${badgeUrl({ logo: r.logo ?? '', primary: r.primary, accent: r.accent }, 'shield')}" alt=""></span><span class="what"><b>${esc(r.name)}</b>${icons ? ` <span class="tag-titles">${icons}</span>` : ''}<small>${sub}</small><small>${line}</small>${motto}</span></button>
      <span class="pay"><em>${r.worth ? money(r.worth) : '—'}</em><small>worth</small></span></li>`;
  }

  private chips(players: PlayerRow[], firmsN: number): string {
    const on = players.filter((p) => p.online).length, fr = players.filter((p) => p.friend).length;
    const mates = this.host.crewMembers().length;
    const list: [Chip, number][] = this.host.online()
      ? [['online', on], ['friends', fr], ['players', players.length], ['firms', firmsN], ['everyone', players.length + firmsN], ...(mates ? [['crew', mates] as [Chip, number]] : [])]
      : [['firms', firmsN]];
    const cur = this.current(players);
    return `<div class="scope fchips">${list.map(([c, n]) => `<button type="button" data-fchip="${c}" class="${cur === c ? 'on' : ''}">${CHIP_LABEL[c]} <small>${n}</small></button>`).join('')}</div>`;
  }

  /** The chip in force: the one picked, else Online (everyone, the latest on first); Firms offline; Everyone while searching. */
  private current(players: PlayerRow[]): Chip {
    if (this.text) return 'everyone';
    if (!this.host.online()) return 'firms';
    if (this.chip && (this.chip !== 'crew' || this.host.crewMembers().length)) return this.chip;
    return 'online';
  }

  html(): { left: string; right: string } {
    const players = this.players();
    const firms = this.firms.rows();
    const cur = this.current(players);
    const q = this.text;
    const match = (s: string) => !q || s.toLowerCase().includes(q);
    let rows = '';
    let n = 0;
    if (cur !== 'firms') {
      const list = players.filter((p) => (cur === 'friends' ? !!p.friend : true) && (match(p.row.name) || match(p.row.by ?? '')));
      // Online lists every player, those signed in first, then by when each was last on (the user, 5 Nov 2026:
      // it showed only who was signed in, and an empty list most of the time)
      if (cur === 'online') list.sort((a, b) => Number(b.online) - Number(a.online) || (b.row.seen ?? 0) - (a.row.seen ?? 0));
      if (cur === 'crew') {
        const mates = this.host.crewMembers().filter((m) => match(m.name));
        rows += mates.map((m) => `<li class="grp">${esc(m.name)}${m.online ? ' <i class="on"></i>' : ' · away'} · in your fleet</li>`).join('');
        n += mates.length;
      } else {
        rows += list.map((p) => this.playerRow(p)).join('');
        n += list.length;
      }
    }
    if (cur === 'firms' || cur === 'everyone') {
      const list = firms.filter((f) => match(f.name));
      if (list.length && cur === 'everyone') rows += `<li class="grp">CPU firms met · ${list.length}</li>`;
      rows += list.map((f) => `<li class="${this.pick === `f:${f.id}` ? 'on' : ''}${f.quiet ? ' quiet' : ''}">${f.html}</li>`).join('');
      n += list.length;
    }
    const empty = q ? `Nobody called “${esc(q)}” here.` : cur === 'online' ? 'No other players yet.' : cur === 'friends' ? 'No friends yet. Open a player’s card, or right-click their name anywhere, to add one.' : cur === 'firms' ? 'No rival firms met yet. They keep to their own counties: drive further afield and you will see their colours.' : 'Nobody here yet.';
    const mine = this.host.online() ? `<li class="${this.pick === null ? 'on' : ''} me"><button type="button" class="pick" data-fpick="me"><span class="what"><b>Your own card</b><small>how others see you</small></span></button></li>` : '';
    const left = `${this.chips(players, firms.length)}${mine}<ul class="fleets">${rows || `<li class="none">${empty}</li>`}</ul>${n ? `<p class="foot">${n} shown · click one for its card.</p>` : ''}`;
    let right: string;
    if (this.pick?.startsWith('f:')) right = this.firms.firmCard(this.pick.slice(2)) || '<p class="none">That firm is gone.</p>';
    else if (this.pick) right = this.card.html(this.pick);
    else right = this.host.online() ? this.card.myHtml() : '<p class="none">Pick a firm for its numbers, its fleet, its doors and the towns it is winning.</p>';
    return { left, right };
  }
}
