import type * as THREE from 'three';
import { N, CHUNK, STEP, idx, type Building, type World } from '../world/tiles';
import { FLOOR, buildingHeight } from '../world/towns';
import { mulberry32 } from '../world/rng';
import { hex, mix, scale } from '../world/biomes';
import { STYLES, pick } from './buildings/kit';
import { styleOf } from './buildingStyle';
import { builtShare } from './townMesh';
import { buildFarBlocks, type FarBlock } from './mesher';
import { farWindows } from './farLights';

/**
 * A town from afar (the user, 9 Nov 2026). A building's real model is only drawn with its chunk, within a couple of
 * hundred tiles of the camera and in its view; beyond that a town was bare lots, and its buildings rose out of the
 * ground as you came. Here every building is a plain box to its own height in its own style's wall and roof
 * colours (picked from its seed as most models pick theirs, so the box and the building mostly agree), a ridge on
 * the small ones, a thin shaft where the model is mostly tower. A block of chunks is one mesh in the ground's
 * material, hidden a chunk at a time as the real town comes in (render/stream.ts), so it adds a draw or so a block
 * in view and a dozen triangles a building.
 */

/** Lots bigger than this are grounds, not a building (a circuit, a golf course, an airfield): the ground's colour carries them. */
const MAX_AREA = 120;
/** The crowns that put a pitched roof on a tall building (kit.ts topOff), and those of them that are hipped. */
const PITCHED = new Set(['pitched', 'hipped', 'onion', 'cupola', 'curved', 'mansard', 'dutch', 'sawtooth']);
const HIPPED = new Set(['hipped', 'onion', 'cupola', 'mansard']);

/** The boxes that stand for one building: none for open ground and anything still going up. */
function blocksOf(w: World, b: Building, out: FarBlock[]): void {
  if (b.gone || !b.solid || b.w * b.d > MAX_AREA || builtShare(b) < 1) return;
  const tx = Math.min(N - 1, Math.max(0, Math.floor(b.x + b.w / 2))), tz = Math.min(N - 1, Math.max(0, Math.floor(b.z + b.d / 2)));
  const tile = idx(tx, tz);
  const ti = w.townId[tile];
  const style = STYLES[styleOf(w, b) ?? b.style ?? (ti >= 0 ? w.towns[ti]?.style : undefined) ?? 'classic'] ?? STYLES.classic;
  const r = mulberry32(b.seed);
  let wall = pick(r, style.walls);
  let roof = pick(r, style.roofs);
  const top = buildingHeight(b), storeys = b.floors * FLOOR;
  // a street building is its floors and little else; anything else is a body under whatever stands on it
  const street = b.floors >= 2 && top - storeys < 1.3;
  const body = street ? storeys : Math.max(0.28, Math.min(top * 0.5, 1.4));
  if (body < 0.2) return;
  // a tower's walls are mostly glass
  if (street && b.floors >= 12) wall = mix(wall, pick(r, style.glass), 0.55);
  const big = !street && b.w * b.d > 30;
  const m = big ? 0.18 * Math.min(b.w, b.d) : Math.min(0.16, 0.12 * Math.min(b.w, b.d));
  const x0 = b.x + m, z0 = b.z + m, x1 = b.x + b.w - m, z1 = b.z + b.d - m;
  const y0 = b.level * STEP - 0.05, y1 = b.level * STEP + body;
  const span = Math.min(x1 - x0, z1 - z0);
  // A town from afar is seen from above, so it reads by its roofs (the user, 11 Nov 2026: far towns all grey blobs).
  // A small building's roof takes the style's small-roof form; a taller one's its crown, pitched or hipped over a
  // street of four floors and more where the style tops its tall buildings so, as the models do (kit.ts topOff).
  const flat = style.form === 'flat' || style.crown === 'flat' || style.crown === 'wall' || style.crown === 'dome';
  const tallPitched = PITCHED.has(style.crown) && !(style.modernTall && b.floors > 12);
  const ridge = span > 3.2 ? 0 : body <= 0.85 ? (flat ? 0 : Math.min(0.42, span * 0.3)) : tallPitched ? Math.min(0.5, 0.12 + span * style.pitch * 0.6) : 0;
  const hip = ridge > 0 && (body <= 0.85 ? style.form === 'hip' || (style.alt === 'hip' && r() < 0.5) : HIPPED.has(style.crown));
  // a flat roof is laid in the style's roofing, as the models' decks are (kit.ts flatTop); a glass tower's is its own grey
  if (!ridge) roof = street && b.floors >= 12 ? mix(scale(wall, 0.9), roof, 0.35) : scale(roof, 0.96);
  // From afar a wall is the sum of what is on it: a street building's is a third window, a house's less, and a
  // style that rings its floors with string courses or runs piers up its corners (kit.ts tower) shows its trim
  if (b.floors < 12) wall = mix(wall, pick(r, style.glass), street ? 0.28 : 0.1);
  if (street) {
    const trim = hex(style.trim);
    if (style.massing === 'ribbed') wall = mix(wall, trim, 0.16);
    if (style.course > 0.3) wall = mix(wall, trim, 0.07 * style.course);
  }
  // a mast, a turbine, a chimney on a lot of its own is all shaft: no body under it
  const mast = !street && span <= 1.2 && top > 2;
  // its windows by night (render/farLights.ts): a street building's floors, a house's one or two, none on a shed's
  const win = street ? b.floors : b.floors >= 1 && body >= 0.28 && b.w * b.d <= 30 ? Math.min(2, b.floors) : 0;
  if (!mast) out.push({ x0, z0, x1, z1, y0, y1, ridge, hip, wall, roof, tile, win });
  // a spire, a mast, a keep: a shaft up the middle to most of the model's height
  if (!street && top - body > 1.2) {
    const s = Math.max(0.07, Math.min(0.6, span * 0.1)), cx = (x0 + x1) / 2, cz = (z0 + z1) / 2;
    out.push({ x0: cx - s, z0: cz - s, x1: cx + s, z1: cz + s, y0: mast ? y0 : y1, y1: b.level * STEP + top * 0.92, ridge: 0, wall, roof: wall, tile });
  }
}

/**
 * The distant buildings of the block of chunks over tiles (tx0, tz0)–(tx1, tz1), or null where none stand. A
 * building belongs to the chunk its middle is in, as its real model does (render/townMesh.ts inChunk).
 */
export function buildFarTown(w: World, tx0: number, tz0: number, tx1: number, tz1: number): THREE.Mesh | null {
  const across = (tx1 - tx0) / CHUNK, down = (tz1 - tz0) / CHUNK;
  const chunks: FarBlock[][] = Array.from({ length: across * down }, () => []);
  let any = false;
  for (const b of w.allBuildings) {
    const mx = b.x + b.w / 2, mz = b.z + b.d / 2;
    if (mx < tx0 || mx >= tx1 || mz < tz0 || mz >= tz1) continue;
    const list = chunks[Math.floor((mz - tz0) / CHUNK) * across + Math.floor((mx - tx0) / CHUNK)];
    blocksOf(w, b, list);
    if (list.length) any = true;
  }
  if (!any) return null;
  const mesh = buildFarBlocks(w, chunks);
  // and its windows by night, a skin of their own over the same chunks, hidden with them (mesher.ts lodShowChunks)
  const lights = mesh ? farWindows(chunks) : null;
  if (mesh && lights) { mesh.add(lights); mesh.userData.lights = lights; }
  return mesh;
}
