/**
 * Entries for the events you can take part in (docs/events.html): a rally's start, a car show's bays, a drift
 * meet's cone course. While an event near the player is taking entries, its entry is offered at its diamond like
 * any other work (Missions.nearEvent): a race against a rival on the rally's course, a car shown to the judges,
 * a pair of drifts in front of the crowd. The events' stage writes down what is open (EVENT_ENTRIES); the field
 * races on the clock everyone shares, and a player's run is their own.
 */
import type { MissionCtx } from './missions';
import type { PlaceRef } from './model';
import { rivalById } from './rivals';
import type { Template } from './templates';

export interface EventEntry {
  /** The event's id, and a number for it a mission can carry (Mission.notes.event). */
  id: string; key: number;
  /** `produce`, `xmas`: a market (0.7.0) wanting its goods brought in, from the farms or for the Christmas huts. */
  kind: 'rally' | 'show' | 'drift' | 'produce' | 'xmas';
  /** Where the entry is taken: the rally's start, the show's lot, the meet's course. */
  at: PlaceRef;
  /** A rally's finish. */
  to?: PlaceRef;
  /** The game hour entries close. */
  closes: number;
}

/** What is taking entries now, as the events' stage last wrote it down. */
export const EVENT_ENTRIES: { list: EventEntry[] } = { list: [] };

/** Entries open within `reach` tiles of the player, nearest first. */
export function openEntries(c: MissionCtx, reach = 160): EventEntry[] {
  return EVENT_ENTRIES.list
    .filter((e) => e.closes > c.hours && Math.hypot(e.at.x - c.at.x, e.at.z - c.at.z) <= reach)
    .sort((a, b) => Math.hypot(a.at.x - c.at.x, a.at.z - c.at.z) - Math.hypot(b.at.x - c.at.x, b.at.z - c.at.z));
}

export const entry = (c: MissionCtx, kind: EventEntry['kind']): EventEntry | null => openEntries(c).find((e) => e.kind === kind) ?? null;
export const hoursLeft = (c: MissionCtx, e: EventEntry): number => Math.max(0.5, e.closes - c.hours);

/** The rally: Otto (who never takes the road if a field will do) on the rally's own course, first to the finish banner. */
const rally: Template = {
  id: 'event:rally', thread: 'car', kind: 'race',
  gate(c) {
    if (c.def.kind !== 'land') return 'road cars only';
    return entry(c, 'rally') ? null : 'no rally taking entries';
  },
  bind(c) {
    const e = entry(c, 'rally');
    if (!e?.to) return null;
    const tier: 1 | 2 | 3 = c.stage < 2 ? 1 : c.stage < 4 ? 2 : 3;
    const r = rivalById('otto');
    const prize = [450, 900, 1600][tier - 1];
    return {
      title: 'Offroad Rally',
      why: `Enter the rally: from the start banner to the finish, any line across the country you like. Beat ${r.short} and the prize is $${prize}.`,
      details: `The rally field goes off on the hour, eight of them in team colours. Your run is your own: line up with ${r.name} at the banner and race him to the flag.`,
      giver: { who: 'marshal', name: 'The rally marshal', at: e.at, town: null },
      hero: { kind: 'trophy' }, caption: 'The rally trophy',
      objs: [{ t: 'race', label: 'Race to the finish banner', icon: '🏁', rival: 'otto', tier, from: e.at, to: e.to }],
      reward: [{ r: 'cash', n: prize }],
    };
  },
};

/**
 * The car show: park in a bay and let the judges look her over. They score what she is (quick, rare, a firm's
 * own), so the prize is worked out from the car being driven when the entry is offered.
 */
const show: Template = {
  id: 'event:show', thread: 'car', kind: 'job',
  gate(c) {
    if (c.def.kind !== 'land') return 'road vehicles only';
    return entry(c, 'show') ? null : 'no show taking entries';
  },
  bind(c) {
    const e = entry(c, 'show');
    if (!e) return null;
    const d = c.def;
    const score = Math.round(d.topSpeed * 60 + (d.faction ? 180 : 0) + ('convertible' in d && d.convertible ? 90 : 0) + c.parts * 40);
    const prize = Math.max(150, Math.min(1500, 100 + score));
    return {
      title: 'Show Your Car',
      why: `The car show has a bay for your ${d.name}. Park in it and wait while the judges look her over: they reckon she’s worth $${prize}.`,
      giver: { who: 'organiser', name: 'The show’s organiser', at: e.at, town: null },
      hero: { kind: 'vehicle', model: d.id }, caption: `Your ${d.name}`,
      objs: [{ t: 'reach', label: 'Reach a bay at the show', icon: '🚗', at: e.at, r: 3, stop: true, hold: 4 }],
      reward: [{ r: 'cash', n: prize }],
      hours: hoursLeft(c, e),
    };
  },
};

/** The drift meet: onto the cone course and hang the tail out each way, in front of the crowd. */
const drift: Template = {
  id: 'event:drift', thread: 'car', kind: 'job',
  gate(c) {
    if (c.def.kind !== 'land') return 'road cars only';
    if (!('drift' in c.def) || !c.def.drift) return 'needs a handbrake';
    return entry(c, 'drift') ? null : 'no meet taking entries';
  },
  bind(c) {
    const e = entry(c, 'drift');
    if (!e) return null;
    return {
      title: 'Drift Meet',
      why: 'The drift meet is open to all comers. Drive onto the cone course, then slide the tail round on the handbrake each way.',
      giver: { who: 'organiser', name: 'The meet’s organiser', at: e.at, town: null },
      hero: { kind: 'trophy' }, caption: 'The drift trophy',
      objs: [
        { t: 'reach', label: 'Reach the cone course', icon: '💨', at: e.at, r: 4, stop: true },
        { t: 'drift', label: 'Drift round to the left', icon: '↩️', dir: 'left' },
        { t: 'drift', label: 'Drift round to the right', icon: '↪️', dir: 'right' },
      ],
      reward: [{ r: 'cash', n: 350 }],
      hours: hoursLeft(c, e),
    };
  },
};

export const EVENT_TEMPLATES: Template[] = [rally, show, drift];

