import type { CellDoc, ServerMsg } from '../../shared/protocol';
import { POSTCARD, isCardId, type CardPose, type Postcard, type PostcardView } from '../../shared/postcards';
import { httpUrl, type Online, type OnlineExtra } from './online';

/**
 * Postcards in the game (docs/postcards.html, phase 2). The camera mode asks for one when a still or a
 * clip is taken online, so the clip's corner can carry its link; the World tab lists them; and a link
 * opened (`?postcard=k3x9q`) is read here, so the game can go there once the player has signed in.
 */

interface PostcardsHost {
  /** Send the camera to a postcard's spot (or its maker's vehicle), posed as it was. */
  go(v: PostcardView | Postcard): void;
  say(title: string, body: string): void;
}

const esc = (s: string): string => s.replace(/[&<>"]/g, (c) => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;' }[c]!));
/** How long a take waits for its postcard's id before going ahead with the plain address. */
const WAIT_MS = 1500;

export class Postcards implements OnlineExtra {
  /** Mine, newest first, as the server last said. */
  mine: Postcard[] = [];
  private asked = false;
  private ask = 0;
  private waiting = new Map<number, (r: { id: string | null; why?: string }) => void>();
  /** Told when the list changes (the World tab redraws). */
  onChange: () => void = () => {};

  constructor(private online: Online, private host: PostcardsHost) {}

  /** Where links point: the server signed in to, as a web address; null offline. */
  base(): string | null {
    if (!this.online.active) return null;
    const b = httpUrl(this.online.serverAddress);
    return b || null;
  }
  link(id: string): string | null { const b = this.base(); return b ? `${b}/p/${id}` : null; }

  /**
   * A postcard for a take: `id` to move or retitle one already made in this camera session, none for a
   * new one. The id back, or null (offline, refused, or no answer in time).
   */
  send(pose: CardPose | null, title: string | null, id?: string): Promise<{ id: string | null; why?: string }> {
    if (!this.base()) return Promise.resolve({ id: null });
    const ask = ++this.ask;
    this.online.post({ t: 'postcard', ask, ...(id ? { id } : {}), ...(pose ? { pose } : {}), ...(title !== null ? { title } : {}) });
    return new Promise((res) => {
      this.waiting.set(ask, res);
      setTimeout(() => { if (this.waiting.delete(ask)) res({ id: null, why: 'No answer from the server' }); }, WAIT_MS);
    });
  }

  remove(id: string): void { this.online.post({ t: 'unpost', id }); }
  /** A take's picture for its postcard: the link's preview. */
  picture(id: string, jpg: string): void { if (this.base()) this.online.post({ t: 'postcardPic', id, jpg }); }

  // ---- OnlineExtra ------------------------------------------------------------------------------------

  welcome(): void { this.mine = []; this.asked = false; }
  cell(_k: string, _doc: CellDoc): void { /* nothing of a cell's */ }
  /** Signed in: the list, so the deeds that count postcards are up to date (`onList`). */
  ready(): void { if (!this.online.guest) this.online.post({ t: 'postcards' }); }
  /** The list as it stands has come in: made, opened and ridden, for the deeds. */
  onList: (made: number, opens: number, rides: number) => void = () => {};
  frame(): void { /* nothing each frame */ }
  forget(): void { /* nothing of a cell's */ }
  reset(): void {
    this.mine = [];
    this.asked = false;
    for (const [, res] of this.waiting) res({ id: null });
    this.waiting.clear();
  }

  got(m: ServerMsg): boolean {
    if (m.t === 'postcard') {
      const res = this.waiting.get(m.ask);
      this.waiting.delete(m.ask);
      res?.({ id: m.id, why: m.why });
      // a new one or a new title: the list as it stands, if it has been looked at
      if (m.id && this.asked) this.online.post({ t: 'postcards' });
      return true;
    }
    if (m.t === 'postcards') {
      this.mine = m.rows;
      this.onList(m.rows.length, m.rows.reduce((s, c) => s + c.opens, 0), m.rows.reduce((s, c) => s + c.rides, 0));
      this.onChange();
      return true;
    }
    return false;
  }

  // ---- the World tab ----------------------------------------------------------------------------------

  opened(): void { this.asked = true; this.online.post({ t: 'postcards' }); }

  html(): string {
    if (!this.mine.length) {
      return `<div class="picks postcards"><h4>Your postcards</h4><p class="none">None yet. Press <kbd>C</kbd> for the camera: every still or clip you take gets a link that brings whoever opens it here.</p></div>`;
    }
    const rows = this.mine.slice(0, 30).map((c) => `<li><span class="pk">📮</span><span class="what"><b>${esc(c.title)}</b>`
      + `<small>${new Date(c.at).toLocaleDateString('en-GB', { day: 'numeric', month: 'short' })} · opened ${c.opens} time${c.opens === 1 ? '' : 's'}${c.rides ? ` · ${c.rides} took a car` : ''}</small></span>`
      + `<span class="acts"><button type="button" class="link" data-card="copy" data-id="${c.id}">Copy link</button>`
      + `<button type="button" class="link" data-card="go" data-id="${c.id}">Go there</button>`
      + `<button type="button" class="link" data-card="drop" data-id="${c.id}">Remove</button></span></li>`).join('');
    return `<div class="picks postcards"><h4>Your postcards <small>${this.mine.length}${this.mine.length > 30 ? ', the newest 30 shown' : ''}</small></h4><ul>${rows}</ul></div>`;
  }

  /** A press in the World tab that was a postcard's. */
  press(t: HTMLElement): boolean {
    const b = t.closest('[data-card]') as HTMLElement | null;
    if (!b) return false;
    const c = this.mine.find((q) => q.id === b.dataset.id);
    if (!c) return true;
    const act = b.dataset.card;
    if (act === 'copy') {
      const url = this.link(c.id);
      if (url) void navigator.clipboard.writeText(url).then(() => this.host.say('Link copied', url), () => this.host.say('The link', url));
    } else if (act === 'go') this.host.go(c);
    else if (act === 'drop') { this.remove(c.id); this.mine = this.mine.filter((q) => q.id !== c.id); this.host.say('Postcard removed', `${c.title}: its link no longer goes anywhere`); }
    return true;
  }
}

/** A postcard link's id, from this page's address (`/play/?postcard=k3x9q`), or null. */
export function postcardInUrl(): string | null {
  const id = new URLSearchParams(location.search).get('postcard');
  return isCardId(id) ? id : null;
}

/** A postcard as anyone may read it, from the server at `server`; null if it is gone or the server can't be reached. */
export async function readPostcard(server: string, id: string): Promise<PostcardView | null> {
  const base = httpUrl(server);
  if (!base || !isCardId(id)) return null;
  try {
    const r = await fetch(`${base}/api/postcard/${id}`, { cache: 'no-store' });
    if (!r.ok) return null;
    const v = await r.json() as PostcardView;
    return typeof v?.x === 'number' && typeof v?.z === 'number' ? v : null;
  } catch { return null; }
}

/** Report a postcard's picture (someone who opened its link): three reports hide it until the developer looks. */
export async function reportPicture(server: string, id: string): Promise<boolean> {
  const base = httpUrl(server);
  if (!base || !isCardId(id)) return false;
  try { return (await fetch(`${base}/api/postcard/${id}/report`, { method: 'POST' })).ok; } catch { return false; }
}

export { POSTCARD };
