import * as THREE from 'three';
import { lruGet, lruPut } from './lruCache';

/**
 * Advertising banners towed behind Barnstormers (0.7.0, behind NEXT_WORLD; docs/rides.html "Banners"): a tow
 * line off the tail and a long cloth on a spreader bar, its words painted on in big letters, so the fleet's
 * name (or "Visit <Town>") reads from the default camera. The cloth is laid along the path the plane's tail
 * has flown, so it swings wide round a turn and straightens after, and a ripple runs down it from the bar
 * to the free end. Each side reads the right way round (two faces, the second with its words reversed).
 *
 * The words are drawn once per text and colours on a canvas and kept (TEXTS); a banner is a few dozen
 * vertices rewritten each frame. Everything is in scene space: the caller hands in where the plane is.
 */

/** What a banner says and how: the words, the cloth and the letters, and whether it is lit after dark. */
export interface BannerLook { text: string; bg: number; fg: number; lit: boolean }

/** One plane towing a banner this frame: its key (a stable id), its look, where it is, and the ground under it. */
export interface Tow { key: string; look: BannerLook; x: number; y: number; z: number; heading: number; ground: number }

export const BANNER = {
  /** Tiles from the plane's middle to its tail, where the line is made off. */
  tail: 0.62,
  /** The tow line's length, then the cloth's length and depth, in tiles: four plane lengths, as a real one is. */
  rope: 1.4, len: 5.6, depth: 1.15,
  /** The cloth hangs this far below the line as the plane flies. */
  sag: 0.22,
  /**
   * How far the cloth leans from lying flat, in radians. A real banner flies upright, but under a camera
   * looking down from behind an upright one is edge-on whichever way the plane heads; streaming out nearly
   * level it shows its face from above at any heading, and its words read across the screen in a crossing.
   */
  lay: 0.42,
  /** Segments along the cloth, and the trail's spacing. */
  seg: 16, step: 0.07,
  /** The ripple: its height at the free end, how fast it runs, how many waves on the cloth. */
  ripple: 0.12, speed: 8, waves: 2.2,
  /** Below this clearance over the ground the banner is not flying: put away (taxiing, landed). */
  low: 1.1,
  /** A jump in a frame longer than this is the scene re-centring (or a teleport): start the trail afresh. */
  jump: 4,
};

const TEXTS = new Map<string, THREE.CanvasTexture>();
const MATS = new Map<string, THREE.MeshLambertMaterial>();
const css = (c: number) => `#${c.toString(16).padStart(6, '0')}`;

/** The cloth's picture: the words big and bold across it, a hem top and bottom, cached per text and colours. */
function bannerTexture(look: BannerLook): THREE.CanvasTexture | null {
  const key = `${look.text}|${look.bg}|${look.fg}`;
  const hit = lruGet(TEXTS, key);
  if (hit) return hit;
  if (typeof document === 'undefined') return null;
  const W = 1024, H = 200;
  const cv = document.createElement('canvas');
  cv.width = W; cv.height = H;
  const g = cv.getContext('2d');
  if (!g) return null;
  g.fillStyle = css(look.bg);
  g.fillRect(0, 0, W, H);
  g.fillStyle = css(look.fg);
  g.fillRect(0, 8, W, 10);
  g.fillRect(0, H - 18, W, 10);
  const words = look.text.toUpperCase();
  let size = 150;
  g.font = `900 ${size}px "Arial Black", "Helvetica Neue", Arial, sans-serif`;
  const room = W - 60;
  const wide = g.measureText(words).width;
  if (wide > room) size = Math.max(40, Math.floor(size * room / wide));
  g.font = `900 ${size}px "Arial Black", "Helvetica Neue", Arial, sans-serif`;
  g.textAlign = 'center';
  g.textBaseline = 'middle';
  // a dark edge round light letters (and a light one round dark) so they read against the sky either way
  const lumFg = (0.299 * ((look.fg >> 16) & 255) + 0.587 * ((look.fg >> 8) & 255) + 0.114 * (look.fg & 255)) / 255;
  g.lineWidth = Math.max(4, size / 14);
  g.strokeStyle = lumFg > 0.55 ? 'rgba(0,0,0,0.55)' : 'rgba(255,255,255,0.5)';
  g.strokeText(words, W / 2, H / 2 + size * 0.04);
  g.fillText(words, W / 2, H / 2 + size * 0.04);
  const tex = new THREE.CanvasTexture(cv);
  tex.colorSpace = THREE.SRGBColorSpace;
  tex.anisotropy = 4;
  lruPut(TEXTS, key, tex, 48, (old) => old.dispose());
  return tex;
}

function materialFor(look: BannerLook): THREE.MeshLambertMaterial {
  const key = `${look.text}|${look.bg}|${look.fg}|${look.lit ? 1 : 0}`;
  let m = lruGet(MATS, key);
  if (!m) {
    const map = bannerTexture(look);
    m = new THREE.MeshLambertMaterial({ color: map ? 0xffffff : look.bg, side: THREE.FrontSide });
    if (map) m.map = map;
    if (look.lit && map) { m.emissive = new THREE.Color(0xffffff); m.emissiveMap = map; m.emissiveIntensity = 0; }
    lruPut(MATS, key, m, 64, (old) => old.dispose());
  }
  return m;
}

interface Pt { x: number; y: number; z: number }
const UP = new THREE.Vector3(0, 1, 0), tmpV = new THREE.Vector3();

class Banner {
  readonly group = new THREE.Group();
  /** Where the tail has been, newest first, `BANNER.step` apart. */
  private trail: Pt[] = [];
  private cloth: THREE.Mesh[] = [];
  private line: THREE.Line;
  private bar: THREE.Mesh;
  private look: BannerLook | null = null;
  private pos: Float32Array;
  private phase = Math.random() * 10;
  seen = true;

  constructor(parent: THREE.Object3D) {
    const n = BANNER.seg + 1;
    this.pos = new Float32Array(n * 2 * 3);
    // two faces sharing the vertices: the near side's words run forward, the far side's backward
    for (const side of [0, 1]) {
      const geo = new THREE.BufferGeometry();
      geo.setAttribute('position', new THREE.BufferAttribute(this.pos, 3));
      const uv = new Float32Array(n * 2 * 2), idx: number[] = [];
      for (let i = 0; i < n; i++) {
        const u = side ? i / BANNER.seg : 1 - i / BANNER.seg;
        uv.set([u, 1, u, 0], i * 4);
        if (i < BANNER.seg) {
          const a = i * 2, b = a + 1, c = a + 2, d = a + 3;
          if (side) idx.push(a, b, c, b, d, c); else idx.push(a, c, b, b, c, d);
        }
      }
      geo.setAttribute('uv', new THREE.BufferAttribute(uv, 2));
      geo.setIndex(idx);
      const mesh = new THREE.Mesh(geo);
      mesh.frustumCulled = false;
      mesh.castShadow = true;
      this.cloth.push(mesh);
      this.group.add(mesh);
    }
    const lg = new THREE.BufferGeometry();
    lg.setAttribute('position', new THREE.BufferAttribute(new Float32Array(8 * 3), 3));
    this.line = new THREE.Line(lg, new THREE.LineBasicMaterial({ color: 0x2a2a2e }));
    this.line.frustumCulled = false;
    this.group.add(this.line);
    this.bar = new THREE.Mesh(new THREE.CylinderGeometry(0.018, 0.018, 1, 5), new THREE.MeshLambertMaterial({ color: 0x3a3a3e }));
    this.bar.frustumCulled = false;
    this.group.add(this.bar);
    parent.add(this.group);
  }

  dispose(): void {
    this.group.removeFromParent();
    for (const m of this.cloth) m.geometry.dispose();
    this.line.geometry.dispose();
    this.bar.geometry.dispose();
  }

  /** A point `d` tiles back along the trail from the tail (the tail itself first), and the way the trail runs there. */
  private at(d: number, out: Pt, dir: Pt): void {
    // the first gap (tail to the last point laid) is short: measure along the points actually laid
    const t = this.trail;
    let k = 0, left = d;
    while (k < t.length - 2) {
      const g = Math.hypot(t[k + 1].x - t[k].x, t[k + 1].z - t[k].z) || BANNER.step;
      if (left <= g) break;
      left -= g; k++;
    }
    const a = t[k], b = t[k + 1] ?? a;
    const g = Math.hypot(b.x - a.x, b.z - a.z) || BANNER.step;
    const ff = Math.min(1, left / g);
    out.x = a.x + (b.x - a.x) * ff; out.y = a.y + (b.y - a.y) * ff; out.z = a.z + (b.z - a.z) * ff;
    const dx = a.x - b.x, dz = a.z - b.z, l = Math.hypot(dx, dz) || 1;
    dir.x = dx / l; dir.y = 0; dir.z = dz / l;
  }

  fly(tow: Tow, dt: number, night: number): void {
    this.seen = true;
    if (this.look?.text !== tow.look.text || this.look.bg !== tow.look.bg || this.look.lit !== tow.look.lit) {
      this.look = tow.look;
      const m = materialFor(tow.look);
      for (const c of this.cloth) c.material = m;
    }
    const m = this.cloth[0].material as THREE.MeshLambertMaterial;
    if (tow.look.lit && m.emissiveMap) m.emissiveIntensity = 0.85 * night;
    // the line is made off at the tail
    const sx = Math.sin(tow.heading), sz = Math.cos(tow.heading);
    const tail: Pt = { x: tow.x - sx * BANNER.tail, y: tow.y + 0.05, z: tow.z - sz * BANNER.tail };
    const t = this.trail;
    if (tow.y - tow.ground < BANNER.low) { t.length = 0; this.group.visible = false; return; }
    if (t.length && Math.hypot(tail.x - t[0].x, tail.z - t[0].z) > BANNER.jump) t.length = 0;
    if (!t.length) {
      // a banner just picked up streams straight out behind
      const need = Math.ceil((BANNER.rope + BANNER.len) / BANNER.step) + 3;
      for (let k = 0; k < need; k++) t.push({ x: tail.x + sx * BANNER.step * k * -1, y: tail.y, z: tail.z - sz * BANNER.step * k });
    }
    // the newest point follows the tail; another is laid each step of the way flown
    t[0] = tail;
    if (Math.hypot(tail.x - t[1].x, tail.z - t[1].z) >= BANNER.step) t.unshift({ ...tail });
    const keep = Math.ceil((BANNER.rope + BANNER.len) / BANNER.step) + 3;
    if (t.length > keep) t.length = keep;
    this.group.visible = true;
    this.phase += dt * BANNER.speed;
    const p: Pt = { x: 0, y: 0, z: 0 }, dir: Pt = { x: 0, y: 0, z: 0 };
    // the tow line down to the bar, sagging a little in the middle
    const lp = this.line.geometry.attributes.position as THREE.BufferAttribute;
    for (let i = 0; i < 8; i++) {
      const d = (BANNER.rope * i) / 7;
      this.at(d, p, dir);
      const sag = Math.sin((Math.PI * i) / 7) * 0.06 + (BANNER.sag * i) / 7;
      lp.setXYZ(i, p.x, p.y - sag, p.z);
    }
    lp.needsUpdate = true;
    // the cloth: its top edge along the trail, the ripple growing toward the free end
    const n = BANNER.seg;
    for (let i = 0; i <= n; i++) {
      const d = BANNER.rope + (BANNER.len * i) / n;
      this.at(d, p, dir);
      const f = i / n;
      // the ripple lifts and drops the cloth, more toward its free end, and flutters its lean
      const wave = Math.sin(this.phase - f * BANNER.waves * Math.PI * 2) * BANNER.ripple * (0.15 + 0.85 * f);
      const lay = BANNER.lay + wave * 1.4;
      // its leading edge along the line; its other edge out to the side and a little down
      const top = p.y - BANNER.sag - f * 0.05 + wave;
      const ax = dir.z * Math.cos(lay) * BANNER.depth, az = -dir.x * Math.cos(lay) * BANNER.depth, ay = -Math.sin(lay) * BANNER.depth;
      this.pos.set([p.x, top, p.z, p.x + ax, top + ay, p.z + az], i * 6);
      if (i === 0) {
        // the spreader bar the line pulls, along the cloth's front edge
        this.bar.position.set(p.x + ax / 2, top + ay / 2, p.z + az / 2);
        this.bar.scale.set(1, BANNER.depth + 0.04, 1);
        this.bar.quaternion.setFromUnitVectors(UP, tmpV.set(ax, ay, az).normalize());
      }
    }
    for (const c of this.cloth) {
      const a = c.geometry.attributes.position as THREE.BufferAttribute;
      a.needsUpdate = true;
      c.geometry.computeVertexNormals();
      c.geometry.computeBoundingSphere();
    }
  }
}

/** Every banner in the sky: posed each frame from the planes towing one, put away when a plane stops towing. */
export class Banners {
  readonly group = new THREE.Group();
  private all = new Map<string, Banner>();

  constructor(scene: THREE.Object3D) {
    this.group.name = 'banners';
    scene.add(this.group);
  }

  update(tows: Tow[], dt: number, night: number): void {
    for (const b of this.all.values()) b.seen = false;
    for (const tow of tows) {
      let b = this.all.get(tow.key);
      if (!b) { b = new Banner(this.group); this.all.set(tow.key, b); }
      b.fly(tow, dt, night);
    }
    for (const [k, b] of this.all) if (!b.seen) { b.dispose(); this.all.delete(k); }
  }

  /** How many are flying, for the console. */
  count(): number { return [...this.all.values()].filter((b) => b.group.visible).length; }

  clear(): void { this.update([], 0, 0); }
}
