/**
 * Marks (docs/marks.html): the ways a player leaves something in the shared world that other players come
 * across, and hear back about. What both the game and the server must agree on; nothing here touches the
 * DOM or Node, and nothing here reads a World.
 *
 * - **Records**: the best hot lap at each circuit, with its ghost (the holder's line, played back to whoever
 *   tries to beat it), and the longest drift slid in each chunk of a county, painted in the holder's colours.
 *   Beaten, the old holder is told.
 * - **Signs**: a two-part message on a post, made from set words (so nothing needs a filter), which other
 *   players leave hearts on, as on works (one each, taken back at will). Loved signs are carved in stone.
 * - **Guestbooks**: drive up to another player's HQ and stop, and your fleet signs its book.
 * - **Holders**: who has held each town as territory, the hand-over told to both sides, and a GG back.
 * - **Patrons**: who paid rent at your doors, named, not just counted.
 * - **Picks**: the week's most loved work, longest new road, fastest-growing fleet and freshest records, on
 *   the title screen and the World tab.
 */

/** The constants both sides are bound by. */
export const MARKS = {
  /** Signs one player may have standing at once; a new one past it takes the oldest down. */
  signsMax: 12,
  /** Signs one county may hold. */
  signsPerCell: 80,
  /** Hearts that carve a sign in stone; it stays then. */
  carveUp: 8,
  /** Hearts kept per sign. */
  votesMax: 64,
  /** A drift shorter than this (tiles slid) isn't a record anywhere. */
  driftMin: 8,
  /** Points in a drift's painted line, at most. */
  driftPts: 48,
  /** The longest a slide can honestly be in one go, tiles: anything more is refused. */
  driftMaxTiles: 400,
  /** Ghost samples a second, and the most a lap may hold (five minutes). */
  ghostHz: 5,
  ghostMax: 1500,
  /** The quickest a lap of any circuit can be, seconds. */
  lapMin: 12,
  /**
   * How far past the track's edge a lap may go, in tiles, either side (the infield too): a wheel on the kerb. It was
   * 2.5, and a truck lapped the bullring in 12.4 s on the grass inside (the user, 28 Oct 2026); the server replays every
   * record's ghost against the circuit to the same band (server/marks.ts lapProblem).
   */
  lapBand: 0.9,
  /** Stamps a guestbook keeps; fleets it remembers as having signed. */
  guestKeep: 40,
  guestFleets: 200,
  /** Tiles from an HQ's ground a visitor counts within; seconds stopped there before the book is signed. */
  guestReach: 5,
  guestStay: 3,
  /** Hand-overs kept per town. */
  holdersKeep: 12,
  /** Votes that give an unnamed work the name a player suggested. */
  suggestVotes: 5,
  /** Suggestions a work keeps. */
  suggestMax: 4,
  /** Real milliseconds in a week of picks. */
  week: 7 * 86400e3,
} as const;

/** The guestbook's stamps. */
export const STAMPS = ['👋', '🎉', '❤️', '🚚', '⭐', '☕'] as const;

// ---- signs ---------------------------------------------------------------------------------------------

/** A sign's first part (and its second): a phrase with a gap for one word. */
export const SIGN_PHRASES = [
  '{} ahead', 'Beware of {}', 'Try {}', 'Shortcut to {}', 'Good spot for {}', 'Need {}', 'Behold, {}!', 'Could this be {}?',
  'Fast way to {}', 'If only I had {}…', 'Praise the {}', 'No {} here', '{} this way', 'Watch for {}', 'Nice {}', 'Time for {}',
  'Don’t forget {}', 'Visit {}', 'Brake for {}', 'Floor it for {}',
] as const;

/** The words that fill the gap, in groups for the picker. */
export const SIGN_WORDS: readonly (readonly [string, readonly string[]])[] = [
  ['Places', ['a town', 'the port', 'the airport', 'a dealer', 'a shop', 'the tavern', 'an HQ', 'a bridge', 'a tunnel', 'the circuit', 'the ferry', 'the coast', 'the hills', 'a farm']],
  ['Road', ['a shortcut', 'a dead end', 'a sharp bend', 'a jump', 'a toll', 'traffic', 'roadworks', 'a straight', 'a hairpin', 'mud', 'deep water', 'a cliff']],
  ['Driving', ['a drift', 'nitrous', 'the handbrake', 'speed', 'patience', 'caution', 'a tow', 'a race', 'a convoy', 'a detour']],
  ['Life', ['the police', 'rivals', 'friends', 'cargo', 'money', 'a view', 'the sunset', 'coffee', 'a nap', 'glory', 'luck', 'trouble']],
];
/** Every word, numbered in the order above. */
export const SIGN_WORD_LIST: readonly string[] = SIGN_WORDS.flatMap(([, ws]) => ws);

/** How a sign's two parts are joined. */
export const SIGN_JOINS = ['and then', 'but', 'therefore', 'or', 'so'] as const;

/** A sign's message: phrase and word, and optionally a join, a second phrase and word. */
export type SignMsg = [number, number] | [number, number, number, number, number];

/** A message as checked: in range throughout, or null. */
export function cleanSign(m: unknown): SignMsg | null {
  if (!Array.isArray(m) || (m.length !== 2 && m.length !== 5) || !m.every((v) => Number.isInteger(v) && v >= 0)) return null;
  const [p, w, j, p2, w2] = m as number[];
  if (p >= SIGN_PHRASES.length || w >= SIGN_WORD_LIST.length) return null;
  if (m.length === 2) return [p, w];
  if (j >= SIGN_JOINS.length || p2 >= SIGN_PHRASES.length || w2 >= SIGN_WORD_LIST.length) return null;
  return [p, w, j, p2, w2];
}

/** A sign's message as words. */
export function signText(m: SignMsg): string {
  const one = (p: number, w: number) => SIGN_PHRASES[p].replace('{}', SIGN_WORD_LIST[w]);
  const first = one(m[0], m[1]);
  if (m.length === 2) return first;
  const second = one(m[3], m[4]);
  return `${first}, ${SIGN_JOINS[m[2]]} ${second.charAt(0).toLowerCase()}${second.slice(1)}`;
}

/**
 * A sign as kept: its id in the cell ("s14"), who put it up, the tile, the message, when, and who has left it
 * a heart (`up`). `dn` is the thumbs-down list signs had before hearts (4 Oct 2026): kept in old documents, unused.
 */
export interface SignRow { by: string; t: number; m: SignMsg; at: number; up: string[]; dn?: string[]; carved?: 1 }

/** Whether a sign's hearts carve it in stone. */
export function signFate(hearts: number): 'carved' | null {
  return hearts >= MARKS.carveUp ? 'carved' : null;
}

// ---- records ---------------------------------------------------------------------------------------------

/** The best lap at a circuit (by its building's uid in the cell): who, how quick, in what, when, and its ghost (sent only when asked). */
export interface LapRow { by: string; s: number; m: string; at: number; g?: string }
/** The longest drift in a chunk: who, how far (tiles slid, to a tenth), when, and its line (island tiles × 4, x then z). */
export interface DriftRow { by: string; s: number; at: number; p: number[] }
/** A drift's score as shown: tiles slid, times ten. */
export const driftPoints = (s: number): number => Math.round(s * 10);

/** One ghost sample: island-local x and z (tiles) and heading (radians). */
export type GhostPt = [number, number, number];

/** A ghost as sent and kept: x and z to a sixteenth of a tile and the heading to a thousandth, as int16s, base64. */
export function encodeGhost(pts: readonly GhostPt[]): string {
  const n = Math.min(pts.length, MARKS.ghostMax);
  const a = new Int16Array(n * 3);
  for (let k = 0; k < n; k++) {
    const [x, z, h] = pts[k];
    let hh = h % (Math.PI * 2);
    if (hh > Math.PI) hh -= Math.PI * 2;
    if (hh < -Math.PI) hh += Math.PI * 2;
    a[k * 3] = Math.max(-32768, Math.min(32767, Math.round(x * 16)));
    a[k * 3 + 1] = Math.max(-32768, Math.min(32767, Math.round(z * 16)));
    a[k * 3 + 2] = Math.round(hh * 1000);
  }
  const bytes = new Uint8Array(a.buffer);
  let s = '';
  for (let k = 0; k < bytes.length; k++) s += String.fromCharCode(bytes[k]);
  return btoa(s);
}

export function decodeGhost(s: string | undefined): GhostPt[] {
  if (!s) return [];
  let bin: string;
  try { bin = atob(s); } catch { return []; }
  const n = Math.floor(bin.length / 6);
  const bytes = new Uint8Array(n * 6);
  for (let k = 0; k < bytes.length; k++) bytes[k] = bin.charCodeAt(k);
  const a = new Int16Array(bytes.buffer);
  const out: GhostPt[] = [];
  for (let k = 0; k < n; k++) out.push([a[k * 3] / 16, a[k * 3 + 1] / 16, a[k * 3 + 2] / 1000]);
  return out;
}

/** Where a ghost is `t` seconds into its lap: between the two samples either side. */
export function ghostAt(pts: readonly GhostPt[], t: number): GhostPt | null {
  if (!pts.length) return null;
  const f = t * MARKS.ghostHz;
  const k = Math.floor(f);
  if (k >= pts.length - 1) return pts[pts.length - 1];
  if (k < 0) return pts[0];
  const a = pts[k], b = pts[k + 1], u = f - k;
  let dh = b[2] - a[2];
  if (dh > Math.PI) dh -= Math.PI * 2;
  if (dh < -Math.PI) dh += Math.PI * 2;
  return [a[0] + (b[0] - a[0]) * u, a[1] + (b[1] - a[1]) * u, a[2] + dh * u];
}

// ---- guestbooks, holders, patrons ------------------------------------------------------------------------

/** An HQ's guestbook: visits in all, the fleets that have signed it, and the latest stamps [who, stamp, game hour]. */
export interface GuestRow { n: number; by: string[]; list: [string, number, number][] }

/** A town's holders as territory, oldest first: [carrier id ('p:12' for a player, a firm's id, '' nobody), game hour it began]. */
export type HolderRow = [string, number][];

// ---- picks -----------------------------------------------------------------------------------------------

export type PickKind = 'loved' | 'road' | 'growth' | 'lap' | 'drift' | 'sign' | 'guests' | 'postcard' | 'range' | 'world';
/**
 * One of the week's picks: what for, a line for it, whose, and where to go to see it (world tiles, and a work
 * key or a lot key when it is one) when there is somewhere.
 */
export interface Pick {
  kind: PickKind; title: string; detail: string; by: string; who: string; colour: number; k?: string; x?: number; z?: number;
  /** The fleet's livery and logo, for its shield (the one over its HQ). Additive: an older server sends none. */
  brand?: { primary: number; accent: number; logo: string };
  /** The vehicle a lap or a drift was made in, for its model turning on the card. */
  model?: string;
  /**
   * A story off the news wire (server/news.ts, the user, 5 Nov 2026), all additive: its id (for the Tribune's
   * already-shown list), when it happened (ms), its weight (1 a brief to 5 a front page), its desk (the kicker, and
   * what an edition holds one of), its mark, and the county it happened in ("cx,cz") with that county's name.
   */
  id?: string; t?: number; w?: number; tag?: string; icon?: string; c?: string; county?: string;
  /** Why a local story is in this reader's edition (server/news.ts local): their own fleet, their circle, their county. */
  scope?: LocalScope;
}
export type LocalScope = 'you' | 'circle' | 'county';
/**
 * One reader's local news (server /wire.json, the title's Tribune and the paper's desk): their county as named, and
 * the stories about their fleet, their circle and their county, newest first within each.
 */
export interface LocalWire { cell?: string; county?: string; stories: Pick[] }
/** The picks as told: when their week began (ms), whether it is still running, and the lines. */
export interface Picks {
  from: number; live: boolean; items: Pick[];
  /** The world this week (server/worldWeek.ts): every human fleet's figures together, as stories. Additive. */
  world?: Pick[];
  /** The news wire (server/news.ts): what happened across the world over the last week, newest first. Additive. */
  wire?: Pick[];
}

export const PICK_LABEL: Record<PickKind, string> = {
  loved: 'Most loved', road: 'Longest new road', growth: 'Fastest growing', lap: 'Lap record', drift: 'Drift record', sign: 'Best sign', guests: 'Most visited HQ',
  postcard: 'Postcard of the week', range: 'Furthest from home', world: 'The world this week',
};
export const PICK_ICON: Record<PickKind, string> = { loved: '♥', road: '🛣️', growth: '📈', lap: '⏱', drift: '↯', sign: '🪧', guests: '🏢', postcard: '📮', range: '🧭', world: '🌍' };

// ---- what happened while away ------------------------------------------------------------------------------

/** One line of news about a mark of mine, live or kept for the next sign-in. */
export type MarkNews =
  | { what: 'lapLost'; c: string; k: string; by: string; s: number; was: number }
  | { what: 'driftLost'; c: string; k: string; by: string; s: number; was: number }
  | { what: 'guest'; k: string; by: string; stamp: number }
  | { what: 'signUp'; c: string; k: string; by: string; carved?: boolean }
  | { what: 'signFell'; c: string; k: string }
  | { what: 'townLost'; town: string; by: string }
  | { what: 'townWon'; town: string; from: string }
  | { what: 'gg'; town: string; by: string; back?: boolean }
  | { what: 'named'; k: string; name: string; by: string }
  /** A postcard of mine (docs/postcards.html): opened `opens` times (a milestone), or a fleet taking a car from it (`ride`, their fleet's name). */
  | { what: 'postcard'; id: string; title: string; opens?: number; ride?: string };

/** What a game is told about marks on signing in: news since last time, and who paid rent while away. */
export interface MarksWelcome { news: MarkNews[]; payers: [string, number][]; patrons: [string, number][] }

/** News kept for the next sign-in, at most. */
export const NEWS_KEEP = 40;
