/**
 * "Put <her> to Work" walked through by click (the user, 7 Nov 2026): yellow glows and a bubble on whatever is to be
 * clicked next, as the Fleet tab's tour after the Helping Hand does: the fleet's name in the top bar (or H), the
 * HQ window's Fleet tab, her card on the board, then Work in her Mode row. Each step follows what is on screen, so
 * a player who goes another way (the dock's hover, the H key) is met wherever they are. Gone once she is working.
 */
export interface WorkGuideHost {
  /** Her unit's uid and first name while the mission is on, else null. */
  target(): { uid: number; first: string } | null;
  /** The HQ window is up, its tab, and the unit its pane shows. */
  hqOpen(): boolean;
  hqTab(): string;
  paneUid(): number | null;
  /** Something else is up in front (a card, the map, a menu): the guide stands aside. */
  covered(): boolean;
}

interface Step { id: string; sel: string; title: string; html: string }

export class WorkGuide {
  private bubble = document.createElement('div');
  private lit: HTMLElement | null = null;
  private key = '';
  private next = 0;
  /** The step on screen ('hq', 'fleet', 'card', 'work'), or '' with none: for the play reports' journey. */
  shown = '';

  constructor(private host: WorkGuideHost) {
    this.bubble.className = 'hq-tour guide-tour';
    this.bubble.hidden = true;
    document.body.append(this.bubble);
  }

  /** Four times a second: the step for what is on screen now, glowed and pointed at. */
  update(now: number): void {
    if (now < this.next) return;
    this.next = now + 250;
    const t = this.host.target();
    const s = t && !this.host.covered() ? this.step(t) : null;
    const el = s ? document.querySelector<HTMLElement>(s.sel) : null;
    if (!s || !el || !el.offsetParent) { this.clear(); return; }
    this.shown = s.id;
    if (this.lit !== el) {
      this.lit?.classList.remove('guide-glow');
      el.classList.add('guide-glow');
      this.lit = el;
    }
    if (this.key !== s.title) {
      this.key = s.title;
      this.bubble.innerHTML = `<b>${s.title}</b>${s.html}`;
    }
    this.bubble.hidden = false;
    this.place(el);
  }

  private step(t: { uid: number; first: string }): Step {
    if (!this.host.hqOpen()) {
      return { id: 'hq', sel: '#fleetname', title: 'Open your HQ', html: `Click your fleet’s name up here (or press <kbd>H</kbd>) to give ${t.first} her orders.` };
    }
    if (this.host.hqTab() !== 'fleet') {
      return { id: 'fleet', sel: '#hq [data-tab="fleet"]', title: 'The Fleet tab', html: 'Every vehicle you own and who drives it.' };
    }
    if (this.host.paneUid() !== t.uid) {
      return { id: 'card', sel: `#hq [data-zone="map"] [data-uid="${t.uid}"]`, title: `Click ${t.first}’s Tomato`, html: 'Her orders open beside the board.' };
    }
    return { id: 'work', sel: '#hq [data-umode="work"]', title: 'Press Work', html: `${t.first} goes off to find loads of her own, and pays you a cut of each: <em>Your cut</em>, just below, sets how much. <em>Follow</em> calls her back.` };
  }

  /** Beside the glowing thing: to its right if there is room, else below it, else to its left. */
  private place(el: HTMLElement): void {
    const r = el.getBoundingClientRect(), W = 260, h = this.bubble.offsetHeight || 90;
    let side: 'right' | 'below' | 'left' = r.right + 14 + W <= innerWidth - 8 ? 'right' : r.bottom + 14 + h <= innerHeight - 8 ? 'below' : 'left';
    if (side === 'left' && r.left - 14 - W < 8) side = 'below';
    this.bubble.className = `hq-tour guide-tour on ${side}`;
    const left = side === 'right' ? r.right + 14 : side === 'left' ? r.left - 14 - W : Math.min(innerWidth - W - 8, Math.max(8, r.left));
    const top = side === 'below' ? r.bottom + 12 : Math.min(innerHeight - h - 8, Math.max(8, r.top));
    this.bubble.style.left = `${Math.round(left)}px`;
    this.bubble.style.top = `${Math.round(top)}px`;
  }

  private clear(): void {
    this.shown = '';
    this.lit?.classList.remove('guide-glow');
    this.lit = null;
    this.key = '';
    if (!this.bubble.hidden) { this.bubble.hidden = true; this.bubble.classList.remove('on'); }
  }
}
