import { NOS_REFILL } from './parts';
import type { Controls, VehicleDef } from './vehicles';

/**
 * What a hired (or rival) driver does with a nitrous bottle and a handbrake once they are fitted to the
 * vehicle they drive. Only a driver who has earned it — past rookie, and not the careful sort — uses
 * either:
 *
 *   Nitrous: on a straight long enough for a whole bottle (no bend, no stop, nothing in the lane), they
 *   fire one and go flat out on it, to the same boosted top speed on the same ground the player's Shift
 *   gives; the bottle burns its full time, as the player's does with the throttle held, and only something
 *   in the way (traffic.ts) puts it out: a bend or the stop coming up is braked for, not a reason to cut
 *   it. A hired driver's bottles are the unit's own (Fleet.bottles), so twin bottles are two bursts, one
 *   after the other, refilling in NOS_REFILL seconds on the fleet's clock (the user, 15 Oct 2026: a CPU
 *   burst was a fraction of the player's, cut short as soon as a bend came in sight and held to the
 *   bare-ground top speed, so a van on tarmac went no faster on nitrous than it could without).
 *
 *   Handbrake: a sharp corner is taken at up to TUNE.entry rather than crawled round at the sharp-bend
 *   speed. As the car reaches the bend and starts to turn, the handbrake is pulled with the wheel hard
 *   over, the tail comes round, and it is let go as the nose lines up with the road out. Measured (npm run
 *   tricks): at that entry speed a car that only steers runs wide off the road; one that drifts stays on
 *   it, and takes the bend over a second quicker than the crawl.
 *
 * Pure, so the headless check (scripts/tricks.ts) drives the same decisions the traffic does.
 */

export interface Tricks { nitrous: boolean; drift: boolean }
export const NO_TRICKS: Tricks = { nitrous: false, drift: false };

/** A driver's own trick state, kept on the agent. */
export interface TrickState {
  /** Seconds left of the bottle burning, and seconds until each bottle is full again (0 = full). */
  burn: number;
  wait: number[];
  /** `wait` is the unit's own bottles (Fleet.bottles), filled on the fleet's clock: not resized or filled here. */
  shared?: boolean;
  /** Seconds the handbrake has been held on this corner; -1 when it is not. */
  pull: number;
  /** A corner has been drifted and the car has not yet straightened out of it. */
  through: boolean;
  /** Seconds left in which a sharp bend just ahead may still be drifted (the bend drops out of sight as the car turns in). */
  armed: number;
}

export const newTricks = (): TrickState => ({ burn: 0, wait: [], pull: -1, through: false, armed: 0 });

/** Entry speed (tiles a second) a drifter takes a sharp bend at (the sharp-bend crawl is 0.45), and the longest a handbrake is held on one corner. */
export const TUNE = { entry: 2.2, pullMax: 0.4 };
/** Tiles of clear straight ahead before a bottle is fired: liberally, as a working driver would (Oct 2026: was 9). */
const NOS_CLEAR = 6;

/** Tiles a bottle's burst covers from `v` up to `top`, and a little over: a straight shorter than this would waste it. */
const burstRun = (secs: number, v: number, top: number): number => Math.max(NOS_CLEAR, secs * (v + top) * 0.45 + 2);

/** Optional reads from the traffic: `top`, the boosted top speed on the ground under it; `limit`, the speed the bend or the stop ahead allows. */
interface TrickOpts { top?: number; limit?: number }

/**
 * One frame's decisions. `corner` is the sharpest bend within reach ahead (as the traffic reads it),
 * `straight` the tiles of path ahead with no bend at all, `clear` whether the road ahead is free of other
 * traffic for a bottle's run, `diff` the steering error to the aim point. Returns the speed to aim for,
 * and sets the controls' boost, handbrake and (while drifting) steer.
 */
export function applyTricks(t: TrickState, k: Tricks, def: VehicleDef, v: number, target: number,
  corner: { angle: number; dist: number } | null, straight: number, clear: boolean, diff: number, dt: number, c: Controls, o: TrickOpts = {}): number {
  // the bottles fill whether or not they are wanted (a hired driver's on the fleet's clock instead)
  const n = def.nitrous;
  if (n && !t.shared) {
    if (t.wait.length !== n.bottles) t.wait = new Array(n.bottles).fill(0);
    for (let i = 0; i < t.wait.length; i++) t.wait[i] = Math.max(0, t.wait[i] - dt);
  }
  // ---- nitrous: a straight long enough for the whole burst, and a bottle to hand
  if (n && k.nitrous && def.kind === 'land') {
    const top = o.top ?? def.topSpeed * n.mul;
    // once lit it burns its full time, as the player's does (the user, 15 Oct 2026: it was cut as soon as a bend came in sight)
    if (t.burn > 0) t.burn = Math.max(0, t.burn - dt);
    else if (clear && straight >= burstRun(n.secs, v, top) && (!corner || corner.dist > NOS_CLEAR) && v > target * 0.5 && v < top - 0.3) {
      const i = t.wait.findIndex((w) => w <= 0);
      if (i >= 0) { t.wait[i] = NOS_REFILL; t.burn = n.secs; }
    }
    if (t.burn > 0) {
      c.boost = n.mul - 1;
      // flat out on it, the throttle held as the player holds W (a downhill run goes past `top`, as the
      // player's does), but a bend or the stop ahead is still braked for
      target = Math.min(Math.max(target, top * 1.5), o.limit ?? Infinity);
    }
  } else t.burn = 0;
  // ---- the handbrake: sharp bends at a drifter's pace
  const drift = def.kind === 'land' ? def.drift : undefined;
  if (drift && k.drift) {
    // at the bend and turning in: pull it, wheel hard over, until the nose is round
    const turning = Math.abs(diff) > 0.45;
    if (corner && corner.angle > 1.1 && corner.dist < 1.2) t.armed = 0.8;
    else t.armed = Math.max(0, t.armed - dt);
    if (t.pull < 0 && !t.through && turning && v > 1.1 && t.armed > 0) t.pull = 0;
    if (t.pull >= 0) {
      t.pull += dt;
      if (Math.abs(diff) < 0.3 || t.pull > TUNE.pullMax || v < 0.6) { t.pull = -1; t.through = true; }
      else {
        c.handbrake = true;
        c.steer = Math.sign(diff);
        target = Math.max(target, v);
      }
    }
    if (t.through && !turning && (!corner || corner.dist > 1.2)) t.through = false;
  } else t.pull = -1;
  return target;
}

/** Fire a bottle now if one is full (an overtake): true if one was lit or one is already burning. */
export function fireBottle(t: TrickState, def: VehicleDef): boolean {
  const n = def.nitrous;
  if (!n || def.kind !== 'land') return false;
  if (t.burn > 0) return true;
  if (!t.shared && t.wait.length !== n.bottles) t.wait = new Array(n.bottles).fill(0);
  const i = t.wait.findIndex((w) => w <= 0);
  if (i < 0) return false;
  t.wait[i] = NOS_REFILL;
  t.burn = n.secs;
  return true;
}

/** The speed a sharp bend is taken at: a drifter's entry speed with a handbrake fitted, else the crawl. */
export const sharpSpeed = (k: Tricks, def: VehicleDef, sharp: number): number =>
  k.drift && def.kind === 'land' && def.drift ? Math.max(sharp, TUNE.entry) : sharp;

/** Tiles of path ahead of `wp` before it bends by more than a little. */
export function straightAhead(path: { x: number; z: number }[], wp: number, x: number, z: number, max = 16): number {
  let dist = 0, px = x, pz = z;
  let dir: number | null = null;
  for (let k = wp; k < path.length && dist < max; k++) {
    const q = path[k];
    const seg = Math.hypot(q.x - px, q.z - pz);
    if (seg > 0.2) {
      const a = Math.atan2(q.x - px, q.z - pz);
      if (dir === null) dir = a;
      else if (Math.abs(Math.atan2(Math.sin(a - dir), Math.cos(a - dir))) > 0.2) break;
      dist += seg;
      px = q.x; pz = q.z;
    }
  }
  return dist;
}
