import { httpUrl } from './online';
import { setTextEdits } from '../game/missions/textEdits';

/**
 * Mission text edits from the developer's page (server/missionText.ts): asked for once at start and kept,
 * so a game started offline, or before the server answers, still says what was last heard. Best effort:
 * no server, and the cards say what the code says.
 */
const KEY = 'tf-missiontext';

type Edits = { at: number; edits: { from: string; to: string }[] };

export function loadMissionText(server: string): void {
  try {
    const kept = JSON.parse(localStorage.getItem(KEY) ?? 'null') as Edits | null;
    if (kept && Array.isArray(kept.edits)) setTextEdits(kept.edits);
  } catch { /* nothing kept */ }
  const base = httpUrl(server);
  if (!base) return;
  fetch(`${base}/api/missiontext`, { cache: 'no-store' })
    .then((r) => (r.ok ? r.json() : null))
    .then((j: (Edits & { ok?: boolean }) | null) => {
      if (!j || !Array.isArray(j.edits)) return;
      setTextEdits(j.edits);
      try { localStorage.setItem(KEY, JSON.stringify({ at: j.at, edits: j.edits })); } catch { /* not kept */ }
    })
    .catch(() => { /* offline: what was kept stands */ });
}
