import { N, SEA, Biome, DIRS, Flag, World, idx, inB, tileMean, type Landmark } from './tiles';
import { hashCell, mulberry32 } from './rng';
import { landformName } from './landforms';
import { WOOD_KINDS, WOOD_SPECS } from './woods';
import { put } from './beachfront';

/**
 * The headland park (0.8.0, NEXT_080, docs/phonelist.html item 15): a big coastal city's headland kept as parkland
 * rather than built on, the way the Presidio is: cypress and eucalyptus over the high ground, a row of old officers'
 * houses round a parade lawn, an old gun battery dug into the cliff top, a lookout at the highest point, a lane in from
 * the road.
 *
 * Placed once the county is finished (generate.ts, after the woods), on a stream of its own, so nothing else moves. The
 * park's trees are a named wood of its own kind ('headland', world/woods.ts), so the props, the far ground and the
 * bulldozer read them as any other wood's.
 */

const SALT = 0x4ead;
/** Out of every hundred counties with a big city on the coast, how many keep a headland as a park. */
const CHANCE = 0.22;
/** How far from the city's edge the headland may be. */
const REACH = 44;
/** The share of the ground round a headland's middle that is sea: out on a point, not along a straight shore. */
const SEA_LO = 0.3, SEA_HI = 0.62;
/** High ground: the middle stands at least this many steps over the sea. */
const BLUFF = 3;

/** Lay the county's headland park, if it has one. Returns its name, or null. */
export function placeHeadland(w: World, seedHash: number, lane: (gate: number) => void): string | null {
  if (hashCell(seedHash, w.cx, w.cz, SALT) / 4294967296 >= CHANCE) return null;
  const cities = w.towns.filter((t) => t.kind === 'city' || t.kind === 'metro' || t.kind === 'mega');
  if (!cities.length) return null;
  const rng = mulberry32(hashCell(seedHash, w.cx, w.cz, SALT + 1));
  const open = (i: number) => !w.road[i] && !w.rail[i] && !w.blocked[i] && w.townId[i] < 0 && w.water[i] < 0 && !w.lot[i]
    && w.biome[i] !== Biome.Town && w.biome[i] !== Biome.Farm && !(w.flags[i] & (Flag.Poi | Flag.Field | Flag.Track));
  let best: { x: number; z: number; score: number } | null = null;
  for (let z = 12; z < N - 12; z += 2) {
    for (let x = 12; x < N - 12; x += 2) {
      const i = idx(x, z);
      if (!open(i) || w.coastDist[i] < 3 || w.coastDist[i] > 9) continue;
      if (tileMean(w, i) < SEA + BLUFF) continue;
      const near = cities.some((t) => {
        const dx = Math.max(t.x0 - x, 0, x - (t.x0 + t.size)), dz = Math.max(t.z0 - z, 0, z - (t.z0 + t.size));
        return Math.max(dx, dz) >= 4 && Math.max(dx, dz) <= REACH;
      });
      if (!near) continue;
      let sea = 0, all = 0, free = 0;
      for (let dz = -9; dz <= 9; dz += 3) for (let dx = -9; dx <= 9; dx += 3) {
        if (!inB(x + dx, z + dz)) continue;
        const j = idx(x + dx, z + dz);
        all++;
        if (w.water[j] >= 0 && w.coastDist[j] === 0) sea++;
        else if (open(j)) free++;
      }
      const share = sea / all;
      if (share < SEA_LO || share > SEA_HI || free < (all - sea) * 0.6) continue;
      const score = Math.abs(share - 0.45) * 10 - tileMean(w, i) * 0.3 + rng();
      if (w.landmarks.some((l) => Math.hypot(l.x - x, l.z - z) < Math.min(l.r, 40) + 14)) continue;
      if (!best || score < best.score) best = { x, z, score };
    }
  }
  if (!best) return null;
  const { x, z } = best;
  const r = 11 + Math.floor(rng() * 4);
  const l: Landmark = { kind: 'wood', name: WOOD_SPECS.headland.name(landformName('wood', seedHash ^ SALT, w.ox + x, w.oz + z)), x: x + 0.5, z: z + 0.5, r, data: [WOOD_KINDS.indexOf('headland')] };
  // the buildings first, so the park's trees keep off them
  const tiles: { x: number; z: number; d: number }[] = [];
  for (let dz = -r; dz <= r; dz++) for (let dx = -r; dx <= r; dx++) {
    if (Math.hypot(dx, dz) <= r && inB(x + dx, z + dz) && open(idx(x + dx, z + dz))) tiles.push({ x: x + dx, z: z + dz, d: Math.hypot(dx, dz) });
  }
  const flat = (tx: number, tz: number, wx: number, wz: number) => {
    let lo = 127, hi = -128;
    for (let zz = tz; zz < tz + wz; zz++) for (let xx = tx; xx < tx + wx; xx++) {
      if (!inB(xx, zz) || !open(idx(xx, zz))) return false;
      for (let q = 0; q < 4; q++) { const c = w.corners[idx(xx, zz) * 4 + q]; lo = Math.min(lo, c); hi = Math.max(hi, c); }
    }
    return hi - lo <= 1;
  };
  // the officers' row: on the flattest ground in the park's landward half, facing out to sea
  const facing = (tx: number, tz: number) => {
    let bd = 0, bs = -1;
    for (let d = 0; d < 4; d++) {
      let s = 0;
      for (let k = 2; k <= 12; k += 2) { const qx = tx + DIRS[d][0] * k, qz = tz + DIRS[d][1] * k; if (inB(qx, qz) && w.water[idx(qx, qz)] >= 0) s++; }
      if (s > bs) { bs = s; bd = d; }
    }
    return bd;
  };
  let row = null as ReturnType<typeof put>;
  for (const t of [...tiles].sort((a, b) => w.coastDist[idx(b.x, b.z)] - w.coastDist[idx(a.x, a.z)])) {
    const f = facing(t.x, t.z);
    const [wx, wz] = f % 2 ? [2, 4] : [4, 2];
    if (!flat(t.x, t.z, wx, wz)) continue;
    row = put(w, rng, 'officersRow', t.x, t.z, wx, wz, f);
    if (row) break;
  }
  if (!row) return null;
  // the gun battery on the cliff top, looking out to sea
  for (const t of [...tiles].sort((a, b) => w.coastDist[idx(a.x, a.z)] - w.coastDist[idx(b.x, b.z)] || b.d - a.d)) {
    if (w.coastDist[idx(t.x, t.z)] > 3) break;
    const f = facing(t.x, t.z);
    const [wx, wz] = f % 2 ? [2, 3] : [3, 2];
    if (flat(t.x, t.z, wx, wz) && put(w, rng, 'gunBattery', t.x, t.z, wx, wz, f)) break;
  }
  // the lookout at the highest point
  const high = [...tiles].filter((t) => open(idx(t.x, t.z))).sort((a, b) => tileMean(w, idx(b.x, b.z)) - tileMean(w, idx(a.x, a.z)))[0];
  if (high) put(w, rng, 'lookoutPoint', high.x, high.z, 1, 1, facing(high.x, high.z));
  // the lane in from the road, from the parade lawn in front of the row
  const [fx, fz] = DIRS[(row.facing + 2) % 4];
  const gx = Math.round(row.x + (row.w - 1) / 2 + fx * (Math.max(row.w, row.d) / 2 + 1)), gz = Math.round(row.z + (row.d - 1) / 2 + fz * (Math.max(row.w, row.d) / 2 + 1));
  if (inB(gx, gz) && open(idx(gx, gz))) lane(idx(gx, gz));
  w.landmarks.push(l);
  return l.name;
}
