import { esc } from './cargoHud';
import { DRESS_KINDS, type Fleet } from './fleet';
import { ARCHES, ARCH_LABEL } from './missions/passport';
import { allSeals, pageTally, rewards, sealLabel, treatOf, type SealId } from './passportRewards';
import { sights } from './sights';
import { EMBLEMS } from './treats';

/** How many treats show before the rest fold under "See more", unless more are sealed (then up to `SHOW_MAX`). */
const SHOW = 6, SHOW_MAX = 12;

/**
 * The Passport's treats, a section of the HQ window's Treats & Toppers tab (game/toppersTab.ts; the user, 6 Nov 2026:
 * one tab, so Tech is 9 again): every seal, earned or not, with the treat it gives, one row each, and the switches for
 * the treats worn about the HQ and the fleet: the HQ's style (Architect's Eye), the gold (the Gilded Fleet), the Wonder
 * Ball on every vehicle at once (one by one is the workshop's, G), and a visa's emblem round the badge. Sealed ones and
 * those nearest a seal come first; the rest fold under "See more". The world catches up within half a second
 * (main.ts gatherBuildingBadges reads the fleet's choices).
 */
export class TreatsTab {
  readonly el = document.createElement('div');
  private html = '';
  /** Every treat shown, not only the first few. */
  private open = false;
  /** A line for the window's note (the HQ window's say). */
  say: (text: string) => void = () => {};

  constructor(private fleet: Fleet) {
    this.el.className = 'hq-treats-sec';
    this.el.addEventListener('click', (e) => {
      const more = (e.target as HTMLElement).closest<HTMLButtonElement>('button[data-more]');
      if (more) { this.open = !this.open; this.render(true); return; }
      const b = (e.target as HTMLElement).closest<HTMLButtonElement>('button[data-act]');
      if (!b || b.disabled) return;
      this.act(b.dataset.act!, b.dataset.v ?? '');
      this.render(true);
    });
    this.el.addEventListener('change', (e) => {
      const s = e.target as HTMLSelectElement;
      if (s.dataset.act !== 'style') return;
      this.act('style', s.value);
      this.render(true);
    });
  }

  /** Any seal in. */
  get any(): boolean { return allSeals().some((id) => rewards.has(id)); }

  private act(what: string, v: string): void {
    const f = this.fleet;
    switch (what) {
      case 'style': {
        if (!rewards.has('arch')) return;
        f.hqStyle = v && sights.has('arch', v) ? v : null;
        this.say(f.hqStyle ? `Your HQ is being dressed ${ARCH_LABEL[f.hqStyle as keyof typeof ARCH_LABEL] ?? f.hqStyle}.` : 'Your HQ is back in its own style.');
        f.onChange();
        return;
      }
      case 'gild': {
        if (!rewards.gilded) return;
        const n = Number(v) === 2 ? 2 : Number(v) === 1 ? 1 : 0;
        f.setGild(n);
        this.say(n === 2 ? 'Every vehicle and building you own, in gold.' : n === 1 ? 'Gold trim on every vehicle and gold roofs on every building you own.' : 'The gold is put away.');
        return;
      }
      case 'ball': {
        if (!rewards.has('wonder')) return;
        let n = 0;
        for (const k of DRESS_KINDS) n += f.dressKind(k, v === 'on' ? 'wonder' : null);
        this.say(v === 'on' ? `The Wonder Ball is on all ${n} of your vehicles.` : 'The Wonder Ball is off every vehicle.');
        return;
      }
      case 'emblem': {
        const ok = !v || rewards.emblems().includes(v);
        if (!ok) return;
        f.emblem = v || null;
        this.say(v ? `The ${v} emblem frames your fleet’s badge.` : 'Your badge is plain again.');
        f.onChange();
        return;
      }
    }
  }

  render(force = false): void {
    const f = this.fleet;
    const seals = allSeals();
    const got = seals.filter((id) => rewards.has(id)).length;
    // sealed first, then the nearest a seal, then the book's order
    const share = (id: SealId) => { const [a, b] = pageTally(id); return b ? a / b : 0; };
    const order = seals.map((id, i) => ({ id, i, has: rewards.has(id), p: share(id) }))
      .sort((a, b) => Number(b.has) - Number(a.has) || b.p - a.p || a.i - b.i);
    const cap = Math.max(SHOW, Math.min(SHOW_MAX, got + 2));
    const shown = this.open ? order : order.slice(0, cap);
    const rest = order.length - shown.length;
    const more = order.length > cap ? `<button type="button" class="tr-more" data-more="treats">${this.open ? 'Show fewer ▴' : `See ${rest} more ▾`}</button>` : '';
    const html = `<h4 class="tp-fam">Passport treats <small>${got} of ${seals.length} sealed · a treat for every page of the Passport filled, kept for good</small></h4>`
      + `<ul class="tr-list tr-rows">${shown.map((s) => this.row(s.id)).join('')}</ul>${more}`
      + (rewards.emblems().length ? `<p class="tr-foot">Badge emblem: ${f.emblem && EMBLEMS[f.emblem] ? `${EMBLEMS[f.emblem].glyph} ${esc(f.emblem)}` : 'none'}</p>` : '');
    if (!force && html === this.html) return;
    this.html = html;
    this.el.innerHTML = html;
  }

  private row(id: SealId): string {
    const f = this.fleet;
    const t = treatOf(id);
    const [a, b] = pageTally(id);
    const has = rewards.has(id);
    const pct = b ? Math.min(100, Math.round((a / b) * 100)) : 0;
    let ctl = '';
    if (has && id === 'arch') {
      const styles = ARCHES.filter((s) => sights.has('arch', s));
      const opts = [`<option value="">Its own style</option>`, ...styles.map((s) => `<option value="${s}"${f.hqStyle === s ? ' selected' : ''}>${esc(ARCH_LABEL[s])}</option>`)].join('');
      ctl = f.hq ? `<label class="tr-ctl">HQ style <select data-act="style">${opts}</select></label>` : '<span class="tr-ctl tr-dim">Make an HQ first</span>';
    } else if (has && id === 'book') {
      const btn = (n: number, label: string) => `<button type="button" data-act="gild" data-v="${n}" class="${f.gild === n ? 'on' : ''}">${label}</button>`;
      ctl = `<span class="tr-ctl tr-seg">${btn(0, 'Off')}${btn(1, 'Trim')}${btn(2, 'Full gold')}</span>`;
    } else if (has && id === 'wonder') {
      ctl = `<span class="tr-ctl tr-seg"><button type="button" data-act="ball" data-v="on">On every vehicle</button><button type="button" data-act="ball" data-v="off">Off</button></span>`;
    } else if (has && id.startsWith('visa:')) {
      const g = id.slice(5), on = f.emblem === g, em = EMBLEMS[g];
      ctl = `<span class="tr-ctl tr-seg"><button type="button" data-act="emblem" data-v="${on ? '' : esc(g)}" class="${on ? 'on' : ''}">${on ? `${em?.glyph ?? ''} Worn · take off` : `${em?.glyph ?? ''} Wear round badge`}</button></span>`;
    }
    return `<li class="tr-row${has ? ' got' : ''}" title="${esc(t.blurb)}"><span class="tr-icon">${t.icon}</span>`
      + `<span class="tr-name"><b>${esc(t.name)}</b><small>${esc(sealLabel(id))} · ${a}/${b}</small></span>`
      + `<span class="tr-mid">${has ? ctl || `<small class="tr-what">${esc(t.blurb)}</small>` : `<span class="tr-bar"><i style="width:${pct}%"></i></span>`}</span>`
      + `<em>${has ? '🔏 Sealed' : `${pct}%`}</em></li>`;
  }
}
