/**
 * The HQ window's Books tab (docs/hqwindow.html, "Books"): one filter row (range, group, split), a totals
 * strip, and four figures with a table behind each: income and spend as stacked columns, net worth and
 * cash as two lines on one axis, and where the money came from and who earned it as 100% bars.
 */
import { esc, money } from './cargoHud';
import {
  Books, CAP_LABEL, CAP_LINES, IN_LABEL, IN_LINES, OUT_LABEL, OUT_LINES, WHO, WHO_LABEL, capitalOf, revenueOf, spendOf, type Row,
} from './books';
import { lines, legend, shareBar, stacked, table, type Series } from './charts';
import { DAYS_PER_YEAR } from '../render/season';

type Range = 'week' | 'year' | 'years' | 'all';
type Group = 'day' | 'year';
type Split = 'line' | 'who' | 'legal';
const RANGE_LABEL: Record<Range, string> = { week: 'Last 7 days', year: 'This year', years: 'Last 4 years', all: 'All time' };
const GROUP_LABEL: Record<Group, string> = { day: 'Day', year: 'Year' };
const SPLIT_LABEL: Record<Split, string> = { line: 'By line', who: 'You vs crew vs others', legal: 'Legal vs contraband' };
type Fig = 'inc' | 'out' | 'worth' | 'share';

export class BooksTab {
  readonly el = document.createElement('div');
  private range: Range = 'week';
  private group: Group = 'day';
  private split: Split = 'line';
  private tables = new Set<Fig>();
  private tipEl = document.createElement('div');
  private version = -1;
  private key = '';

  constructor(private books: Books, private day: () => number, private founded: () => number) {
    this.el.className = 'hq-books';
    this.tipEl.className = 'hq-tip';
    this.tipEl.hidden = true;
    this.el.addEventListener('click', (e) => {
      const b = (e.target as HTMLElement).closest<HTMLElement>('button');
      if (!b) return;
      if (b.dataset.range) this.range = b.dataset.range as Range;
      else if (b.dataset.group) this.group = b.dataset.group as Group;
      else if (b.dataset.split) this.split = b.dataset.split as Split;
      else if (b.dataset.table) { const f = b.dataset.table as Fig; if (this.tables.has(f)) this.tables.delete(f); else this.tables.add(f); }
      else return;
      this.render(true);
    });
    // one tip for every chart: the hovered column's whole breakdown
    this.el.addEventListener('pointermove', (e) => {
      const hit = (e.target as Element).closest?.('[data-tip]');
      if (!hit) { this.tipEl.hidden = true; return; }
      this.tipEl.innerHTML = hit.getAttribute('data-tip') ?? '';
      this.tipEl.hidden = false;
      const r = this.el.getBoundingClientRect();
      const x = Math.min(e.clientX - r.left + 14, r.width - this.tipEl.offsetWidth - 4);
      this.tipEl.style.left = `${Math.max(4, x)}px`;
      this.tipEl.style.top = `${e.clientY - r.top + this.el.scrollTop + 14}px`;
    });
    this.el.addEventListener('pointerleave', () => { this.tipEl.hidden = true; });
  }

  /** The days in the chosen range, oldest first. */
  private span(): [number, number] {
    const today = this.day();
    const year0 = Math.floor(today / DAYS_PER_YEAR) * DAYS_PER_YEAR;
    const first = Math.min(this.books.rows[0]?.day ?? today, today);
    switch (this.range) {
      case 'week': return [today - 6, today];
      case 'year': return [year0, today];
      case 'years': return [year0 - 3 * DAYS_PER_YEAR, today];
      default: return [Math.min(first, this.founded()), today];
    }
  }

  /** One summed row per column, with its label. */
  private columns(): { cat: string; row: Row }[] {
    const [a, b] = this.span();
    const rows = this.books.range(a, b);
    const byDay = new Map(rows.map((r) => [r.day, r]));
    const out: { cat: string; row: Row }[] = [];
    if (this.group === 'day') {
      let last: Row | undefined = this.books.rows.filter((r) => r.day < a).pop();
      for (let d = a; d <= b; d++) {
        const r = byDay.get(d) ?? Books.sum([], d);
        // a day with no row keeps the last day's closing worth and cash
        if (!byDay.has(d) && last) { r.worth = last.worth; r.cash = last.cash; }
        if (byDay.has(d)) last = r;
        out.push({ cat: `${d + 1}`, row: r });
      }
    } else {
      for (let y = Math.floor(a / DAYS_PER_YEAR); y <= Math.floor(b / DAYS_PER_YEAR); y++) {
        const these = rows.filter((r) => Math.floor(r.day / DAYS_PER_YEAR) === y);
        const r = Books.sum(these, y * DAYS_PER_YEAR);
        if (!these.length) { const prev = this.books.rows.filter((q) => q.day < y * DAYS_PER_YEAR).pop(); if (prev) { r.worth = prev.worth; r.cash = prev.cash; } }
        out.push({ cat: `Year ${y + 1}`, row: r });
      }
    }
    return out;
  }

  /** Income series for the split: 6 lines, 3 earners, or legal vs contraband. */
  private incomeSeries(cols: { row: Row }[]): Series[] {
    if (this.split === 'who') return WHO.map((w, k) => ({ label: WHO_LABEL[w], colour: k + 1, values: cols.map((c) => IN_LINES.reduce((t, l) => t + c.row.inc[l][k], 0)) }));
    if (this.split === 'legal') return [
      { label: 'Legal', colour: 1, values: cols.map((c) => revenueOf(c.row) - sum3(c.row.inc.contraband)) },
      { label: 'Contraband', colour: 7, values: cols.map((c) => sum3(c.row.inc.contraband)) },
    ];
    return IN_LINES.map((l, k) => ({ label: IN_LABEL[l], colour: k + 1, values: cols.map((c) => sum3(c.row.inc[l])) }));
  }

  render(force = false): void {
    const key = `${this.range}|${this.group}|${this.split}|${[...this.tables].join()}|${this.day()}`;
    if (!force && this.version === this.books.version && key === this.key) return;
    this.version = this.books.version;
    this.key = key;
    const cols = this.columns();
    const cats = cols.map((c) => c.cat);
    const total = Books.sum(cols.map((c) => c.row));
    const rev = revenueOf(total), spent = spendOf(total), cap = capitalOf(total);
    const pill = (attr: string, v: string, label: string, on: boolean) => `<button type="button" class="chip${on ? ' on' : ''}" data-${attr}="${v}">${esc(label)}</button>`;
    const filters = `<div class="hq-filters">
      <span class="lbl">Range</span>${(Object.keys(RANGE_LABEL) as Range[]).map((r) => pill('range', r, RANGE_LABEL[r], r === this.range)).join('')}
      <span class="lbl">Group</span>${(Object.keys(GROUP_LABEL) as Group[]).map((g) => pill('group', g, GROUP_LABEL[g], g === this.group)).join('')}
      <span class="lbl">Split</span>${(Object.keys(SPLIT_LABEL) as Split[]).map((s) => pill('split', s, SPLIT_LABEL[s], s === this.split)).join('')}</div>`;
    const strip = `<div class="hq-totals"><b class="big">${money(rev)}</b> revenue · <b>${money(spent)}</b> spent · <b class="${rev - spent >= 0 ? 'up' : 'down'}">${rev - spent >= 0 ? '+' : '−'}${money(Math.abs(rev - spent))}</b> net`
      + ` · ${money(cap - total.cap.grants)} sales &amp; refunds · ${money(total.kept)} kept by drivers${total.cap.grants ? ` · ${money(total.cap.grants)} ${CAP_LABEL.grants.toLowerCase()}` : ''}</div>`;
    const inc = this.incomeSeries(cols);
    const out: Series[] = OUT_LINES.map((l, k) => ({ label: OUT_LABEL[l], colour: k + 1, values: cols.map((c) => c.row.out[l]) }));
    const worth: Series[] = [
      { label: 'Net worth', colour: 1, values: cols.map((c) => c.row.worth) },
      { label: 'Cash', colour: 9, values: cols.map((c) => c.row.cash) },
    ];
    const fig = (f: Fig, title: string, sub: string, chart: string, tbl: string) => `<figure class="hq-fig">
      <figcaption><b>${title}</b><span>${sub}</span><button type="button" class="tbl${this.tables.has(f) ? ' on' : ''}" data-table="${f}">${this.tables.has(f) ? 'Chart' : 'Table'}</button></figcaption>
      ${this.tables.has(f) ? tbl : chart}</figure>`;
    const group = this.group === 'day' ? 'by day' : 'by year';
    const empty = !this.books.rows.length && !this.books.pre;
    const shareParts = IN_LINES.map((l, k) => ({ label: IN_LABEL[l], colour: k + 1, value: sum3(total.inc[l]) }));
    const whoParts = WHO.map((w, k) => ({ label: WHO_LABEL[w], colour: k + 1, value: IN_LINES.reduce((t, l) => t + total.inc[l][k], 0) }));
    const caps = CAP_LINES.map((l) => ({ label: CAP_LABEL[l], v: total.cap[l] })).filter((c) => c.v > 0.5);
    const html = filters + strip
      + (empty ? '<p class="none">The books open with your first dollar.</p>' : '')
      + `<div class="hq-figs">`
      + fig('inc', 'Income', group, `${stacked(cats, inc)}${legend(inc)}`, table(cats, inc))
      + fig('out', 'Spend', group, `${stacked(cats, out)}${legend(out)}`, table(cats, out))
      + fig('worth', 'Net worth and cash', 'at the close of each day', `${lines(cats, worth)}${legend(worth)}`, table(cats, worth, false))
      + fig('share', 'Where it came from', RANGE_LABEL[this.range].toLowerCase(), `${shareBar(shareParts)}<div class="tc-h">Who earned it</div>${shareBar(whoParts)}`,
        table(['Where it came from'], shareParts.map((p) => ({ label: p.label, colour: p.colour, values: [p.value] }))) + table(['Who earned it'], whoParts.map((p) => ({ label: p.label, colour: p.colour, values: [p.value] }))))
      + `</div>`
      + (caps.length ? `<p class="gsub">Not revenue: ${caps.map((c) => `${esc(c.label)} ${money(c.v)}`).join(' · ')}.</p>` : '')
      + (this.books.pre && this.range === 'all' ? `<p class="gsub">Before the books opened: ${money(this.books.pre)} earned.</p>` : '');
    this.el.innerHTML = html;
    this.el.append(this.tipEl);
  }
}

const sum3 = (v: [number, number, number]): number => v[0] + v[1] + v[2];
