        k.box(x, 0.16, z - 0.15, 0.9, 0.5, 0.9, MARBLE);
        for (const sx of [-1, -0.33, 0.33, 1]) k.cyl(x + sx * 0.4, 0.16, z + 0.45, 0.045, 0.5, MARBLE, 8);
