        k.gable(x, 0.73, z, 1.08, 0.24, 1.24, hex(0xcfc8b8), MARBLE, true);
        k.box(x, 0.16, z + 0.31, 0.32, 0.4, 0.02, hex(0x3a3024));
        k.box(x, 0.4, z + 0.33, 0.24, 0.03, 0.01, GOLD);
