        for (let i = 0; i < 8; i++) { const a = (i / 8) * TAU; k.pane(x + Math.cos(a) * 1.455, 1.65, bz + Math.sin(a) * 1.455, 0.12, 0.24, Math.abs(Math.cos(a)) > 0.7 ? (Math.cos(a) > 0 ? 0 : 2) : Math.sin(a) > 0 ? 1 : 3, GLASS, windowSched(b.kind, r), windowGlow(b.kind, r)); }
