        k.box(x, 0.012, z + 0.4, 1.2, 0.006, 1.2, hex(0x4a4c50));
        for (const sx of [-1, 1]) k.box(x + sx * 0.72, 0, z + 0.4, 0.16, 0.3, 1.2, hex(0xa8a49a));
        for (let i = 0; i < 6; i++) k.box(x - 0.5 + i * 0.2, 0.014, z + d / 2 - 0.1, 0.1, 0.006, 0.12, i % 2 ? BLACK : hex(0xf2c14e));
        const fz = bz + 0.6;
        k.face(x, 0.25, fz + 0.01, 0.24, hex(0x8a9096), 16);
        k.hoop(x, 0.25, fz + 0.02, 0.24, 0.012, hex(0x5a6066), 16);
        for (let i = 0; i < 3; i++) { const a = (i / 3) * Math.PI; k.bar([x + Math.cos(a) * 0.14, 0.25 + Math.sin(a) * 0.14, fz + 0.03], [x - Math.cos(a) * 0.14, 0.25 - Math.sin(a) * 0.14, fz + 0.03], 0.01, hex(0x5a6066)); }
        k.cyl(x + 0.32, 0.22, fz + 0.03, 0.03, 0.06, DARK, 6);
        k.glowBox(x + 0.45, h - 0.05, fz + 0.02, 0.06, 0.06, 0.03, RED_LIGHT, BEACON, RED_LIGHT);
