/** A dish on its pylon, tilted `tilt` from straight up toward local +z of `yaw`. */
function dish(k: Kit, x: number, z: number, hub: number, R: number, tilt: number, yaw: number, col: RGB, leg: RGB): void {
  k.within(x, z, yaw, () => {
    for (const [a, c] of [[-0.3, -0.3], [0.3, -0.3], [-0.3, 0.3], [0.3, 0.3]]) k.bar([a, 0, c], [a * 0.3, hub, c * 0.3], 0.03, leg);
    k.box(0, hub - 0.1, 0, 0.22, 0.16, 0.22, leg);
    const ct = Math.cos(tilt), st = Math.sin(tilt);
    const at = (rho: number, ang: number, depth: number): P3 => {
      const px = Math.cos(ang) * rho, pz = Math.sin(ang) * rho, py = depth;
      return [px, hub + 0.1 + py * ct - pz * st, py * st + pz * ct];
    };
    const D0 = R * 0.35, seg = 12, rings = [0, 0.55, 1];
    const down = at(0, 0, -R), up = at(0, 0, R * 1.5);
    for (let j = 0; j + 1 < rings.length; j++) for (let i = 0; i < seg; i++) {
      const a0 = (i / seg) * TAU, a1 = ((i + 1) / seg) * TAU, r0 = rings[j] * R, r1 = rings[j + 1] * R;
      const y0 = D0 * rings[j] * rings[j], y1 = D0 * rings[j + 1] * rings[j + 1];
      const A = at(r0, a0, y0), B = at(r0, a1, y0), C = at(r1, a1, y1), E = at(r1, a0, y1);
      k.quad(A, B, C, E, col, down);
      k.quad(A, B, C, E, col, up);
    }
    // the feed on three struts at the focus
    const focus = at(0, 0, R * 0.8);
    for (let i = 0; i < 3; i++) k.bar(at(R * 0.95, (i / 3) * TAU, D0 * 0.9), focus, 0.01, leg);
    k.box(focus[0], focus[1] - 0.04, focus[2], 0.08, 0.08, 0.08, leg);
  });
}

const siteNull: Draw = (k, W, D, b, r) => {
  const p = strongholdPlan('shSiteNull');
  const SAND = hex(0xd9c49a), SALT = hex(0xece8dc), CRACK = hex(0xc8c0ae), MINT = hex(0x8ef0c8), DGREEN = hex(0x2a3b2e);
  const SHED = hex(0xa9aeb0), SHED_D = hex(0x7e8488), CONC = hex(0xb8b4aa), TRACK = hex(0xbfa77a), WARN = hex(0xf2c14e);
  const s = windowSched(b.kind, r);
  const GREENGLOW: Sched = [17, 31, 2.4];
  k.box(0, 0, 0, W - 0.1, 0.012, D - 0.1, SAND);
  k.cyl(0.5, 0.012, -0.4, 14.2, 0.003, SALT, 24, SALT, 11.2);
  for (let i = 0; i < 18; i++) {
    const cx = (r() - 0.5) * 24, cz = (r() - 0.5) * 18, a = r() * TAU, L = 1 + r() * 2;
    strip(k, cx, cz, cx + Math.cos(a) * L, cz + Math.sin(a) * L, 0.03, CRACK, 0.0155);
  }

  // the double fence: the outer one with wire along the top and warning signs, a second just inside it
  const fence: WallLook = { face: hex(0xb4b9bc), cap: hex(0x6a7075) };
  drawWalls(k, p, fence);
  const g0 = p.gates[0], f = 0.96;
  const inner: SPlan = { ...p, rings: [p.rings[0].map(([x, z]) => [x * f, z * f] as [number, number])], gates: [{ ...g0, z: g0.z * f }] };
  drawWalls(k, inner, fence);
  perRun(k, p, (L) => k.box(0, p.wall.h + 0.05, 0, L, 0.04, 0.04, hex(0x8a8f92)));
  along(k, p, 0, 4.2, () => {
    k.box(0, 0.22, 0.03, 0.34, 0.24, 0.01, WARN);
    k.box(0, 0.4, 0.035, 0.34, 0.05, 0.01, hex(0xd8342a));
    letters(k, 'KEEP OUT', 0, 0.27, 0.04, 0.04, BLACK);
  });
  gateArmUp(k, p, 0, hex(0x6a7075), WHITE, hex(0xd8342a));
  gateArmUp(k, inner, 0, hex(0x6a7075), WHITE, hex(0xd8342a));
  // the dirt track in from the gate, across the salt to the buildings at the far end
  const track: [number, number][] = [[g0.x, 13], [g0.x, 10.4], [-10.6, 7.6], [-5, 2.2], [2, -0.6], [8.4, -4.4], [9, -5.4]];
  for (let i = 0; i + 1 < track.length; i++) {
    strip(k, track[i][0], track[i][1], track[i + 1][0], track[i + 1][1], 0.9, TRACK, 0.017);
    if (i > 0) k.cyl(track[i][0], 0.017, track[i][1], 0.45, 0.004, TRACK, 8);
  }

  for (const bl of p.blocks) {
    const { x, z, w, d, h } = bl;
    switch (bl.type) {
      case 'hangar': {
        // a huge arched hangar, its doors slid open on the craft inside
        const n = 12, z0 = z - d / 2, z1 = z + d / 2, rx = w / 2, I: P3 = [x, 0, z];
        const pt = (i: number): [number, number] => [x + Math.cos((i / n) * Math.PI) * rx, Math.sin((i / n) * Math.PI) * h];
        const LINING = hex(0x3a3e42);
        for (let i = 0; i < n; i++) {
          const [ax, ay] = pt(i), [bx, by] = pt(i + 1), am = ((i + 0.5) / n) * Math.PI;
          k.quad([ax, ay, z0], [bx, by, z0], [bx, by, z1], [ax, ay, z1], i % 2 ? SHED : SHED_D, I);
          k.quad([ax, ay, z0], [bx, by, z0], [bx, by, z1], [ax, ay, z1], LINING, [x + Math.cos(am) * rx * 3, Math.sin(am) * h * 3, z]);
          // the back wall, inside and out
          k.tri([x, 0, z0], [ax, ay, z0], [bx, by, z0], SHED_D, [x, h / 3, z0 + 0.2]);
          k.tri([x, 0, z0], [ax, ay, z0], [bx, by, z0], LINING, [x, h / 3, z0 - 0.2]);
          // the front: piers each side of the door and the head over it
          const dw = Math.cos(Math.PI / 4) * rx, dh = h * 0.68;
          const mx = (ax + bx) / 2 - x;
          const foot = Math.abs(mx) > dw ? 0 : dh;
          k.quad([ax, ay, z1], [bx, by, z1], [bx, foot, z1], [ax, foot, z1], SHED, [x, h / 2, z1 - 0.2]);
          k.quad([ax, ay, z1], [bx, by, z1], [bx, foot, z1], [ax, foot, z1], LINING, [x, h / 2, z1 + 0.2]);
        }
        k.box(x, 0, z, w - 0.1, 0.02, d - 0.1, hex(0x6a6e72));
        const dw = Math.cos(Math.PI / 4) * rx;
        for (const sx of [-1, 1]) k.box(x + sx * (dw + 0.45), 0, z1 + 0.06, 0.9, h * 0.66, 0.08, SHED_D);
        k.box(x, h * 0.68, z1 + 0.01, dw * 2, 0.08, 0.04, hex(0xd8342a));
        letters(k, 'HANGAR 18', x, h * 0.76, z1 + 0.02, 0.22, WHITE);
        // the craft: two shallow dishes rim to rim, a glass dome, lit ports round its rim and a glow under it
        const cx = x, cz = z - 0.4, cy = 0.42, R = 1.35;
        k.glowBox(cx, 0.024, cz, 1.6, 0.004, 1.6, hex(0x5ab89a), GREENGLOW, MINT);
        for (let i = 0; i < 3; i++) { const a = (i / 3) * TAU + 0.5; k.bar([cx + Math.cos(a) * 0.7, 0.02, cz + Math.sin(a) * 0.7], [cx + Math.cos(a) * 0.5, cy, cz + Math.sin(a) * 0.5], 0.025, METAL); }
        k.cone(cx, cy, cz, R, -0.2, hex(0x8a9096), 16);
        k.cone(cx, cy, cz, R, 0.26, hex(0xc8ccd0), 16);
        k.dome(cx, cy + 0.18, cz, 0.42, hex(0x9fe8d0), 12, 3);
        for (let i = 0; i < 12; i++) { const a = (i / 12) * TAU; k.glowBox(cx + Math.cos(a) * (R - 0.04), cy - 0.025, cz + Math.sin(a) * (R - 0.04), 0.09, 0.05, 0.09, MINT, GREENGLOW, MINT); }
        figure(k, x - 2.0, z1 - 0.6, WHITE, WHITE);
        figure(k, x + 1.9, z1 - 1.0, WHITE, WHITE);
        break;
      }
      case 'dome': {
        k.cyl(x, 0, z, w / 2, 0.12, CONC, 14);
        k.dome(x, 0.12, z, w / 2 - 0.08, hex(0xf2f0ea), 14, 4);
        k.box(x + w / 2 - 0.15, 0, z, 0.3, 0.4, 0.4, CONC);
        k.box(x + w / 2 + 0.01, 0, z, 0.02, 0.32, 0.24, hex(0xd8342a));
        for (let i = 0; i < 4; i++) { const a = (i / 4) * TAU + 0.4; k.glowBox(x + Math.cos(a) * 0.72, 0.35, z + Math.sin(a) * 0.72, 0.1, 0.08, 0.1, MINT, GREENGLOW, MINT); }
        // the sealed tube to the other dome (drawn once, from the back one), ribbed
        if (z < -8) {
          const z0 = z + d / 2 - 0.3, z1 = z + d / 2 + 1.1;
          k.bar([x, 0.32, z0], [x, 0.32, z1], 0.17, hex(0xe4e2dc));
          for (let i = 0; i < 4; i++) k.box(x, 0.13, z0 + 0.25 + i * 0.3, 0.4, 0.38, 0.05, hex(0xb8b4aa));
        }
        break;
      }
      case 'dish': {
        const tilt = 0.55 + ((x * 7) % 3) * 0.05;
        dish(k, x, z, h * 0.62, w / 2 - 0.05, tilt, 2.6, hex(0xeceae4), hex(0x8a9096));
        break;
      }
      case 'blockhouse': {
        k.box(x, 0, z, w, h, d, CONC);
        k.box(x, h, z, w + 0.1, 0.1, d + 0.1, hex(0x9a968c));
        k.within(x, z + d / 2 + 0.2, 0, () => k.wedge(0, 0, 0, w, h * 0.5, 0.4, CONC));
        for (const f of [1, 2, 3]) {
          const sl = { x, z, w, d };
          const n = f === 1 ? 5 : 3;
          const len = f === 1 ? w : d;
          for (let i = 0; i < n; i++) {
            const t = (i / (n - 1) - 0.5) * (len - 0.6);
            if (f === 1) k.pane(sl.x + t, h - 0.24, sl.z + sl.d / 2, 0.32, 0.07, 1, GLASS, GREENGLOW, MINT);
            else if (f === 3) k.pane(sl.x + t, h - 0.24, sl.z - sl.d / 2, 0.32, 0.07, 3, GLASS, GREENGLOW, MINT);
            else k.pane(sl.x - sl.w / 2, h - 0.24, sl.z + t, 0.32, 0.07, 2, GLASS, GREENGLOW, MINT);
          }
        }
        k.box(x + w / 2 + 0.01, 0, z, 0.02, 0.45, 0.3, hex(0x4a4e52));
        // the masts on the roof, a searchlight, a red beacon
        k.cyl(x - 0.9, h + 0.1, z - 0.4, 0.02, 1.2, METAL, 4);
        k.glowBox(x - 0.9, h + 1.3, z - 0.4, 0.05, 0.05, 0.05, RED_LIGHT, BEACON, RED_LIGHT);
        for (let i = 0; i < 4; i++) k.box(x - 0.9, h + 0.4 + i * 0.22, z - 0.4, 0.22 - i * 0.04, 0.012, 0.012, METAL);
        k.cyl(x + 0.8, h + 0.1, z, 0.12, 0.12, DARK, 8);
        k.glowBox(x + 0.8, h + 0.22, z + 0.05, 0.14, 0.1, 0.1, LAMP_DAY, NIGHT, hex(0xe6eeff));
        // two black cars and the men from them
        auto(k, x - 0.6, z + d / 2 + 0.75, Math.PI / 2, BLACK, { len: 0.42, cabin: 0.7, cabinAt: -0.03 });
        auto(k, x + 0.6, z + d / 2 + 0.75, Math.PI / 2, BLACK, { len: 0.42, cabin: 0.7, cabinAt: -0.03 });
        figure(k, x, z + d / 2 + 0.5, BLACK);
        figure(k, x + 0.2, z + d / 2 + 1.1, BLACK);
        break;
      }
      case 'ring': {
        k.hoop(x, 0.02, z, w / 2 - 0.15, 0.015, MINT, 24, 'xz');
        k.hoop(x, 0.02, z, w / 2 - 0.55, 0.01, WHITE, 20, 'xz');
        for (let i = 0; i < 16; i++) {
          const a = (i / 16) * TAU;
          k.glowBox(x + Math.cos(a) * (w / 2 - 0.15), 0.012, z + Math.sin(a) * (w / 2 - 0.15), 0.08, 0.04, 0.08, MINT, GREENGLOW, MINT);
        }
        k.cyl(x, 0.017, z, 0.4, 0.003, DGREEN, 12);
        break;
      }
      case 'saltRunway': {
        // edge lines, a dashed centre line, piano keys and numbers at either end, all painted on the salt
        for (const sz of [-1, 1]) k.box(x, 0.017, z + sz * (d / 2 - 0.08), w, 0.003, 0.06, WHITE);
        for (let i = 0; i < 12; i++) k.box(x - w / 2 + 3.2 + i * ((w - 6.4) / 11), 0.017, z, 0.7, 0.003, 0.06, WHITE);
        for (const sx of [-1, 1]) {
          for (let i = 0; i < 6; i++) k.box(x + sx * (w / 2 - 0.5), 0.017, z - d / 2 + 0.35 + i * ((d - 0.7) / 5), 0.8, 0.003, 0.1, WHITE);
          k.within(x + sx * (w / 2 - 1.6), z, sx < 0 ? -Math.PI / 2 : Math.PI / 2, () => {
            const tx = sx < 0 ? '09' : '27';
            [...tx].forEach((ch, i) => k.glyph(ch, [-0.35 + i * 0.36, 0.018, 0.3], [-0.05 + i * 0.36, 0.018, 0.3], [-0.05 + i * 0.36, 0.018, -0.3], [-0.35 + i * 0.36, 0.018, -0.3], WHITE));
          });
        }
        // a windsock at the side of the strip
        const wx = x + 5, wz = z - d / 2 - 0.5;
        k.cyl(wx, 0, wz, 0.02, 0.8, METAL, 4);
        for (let i = 0; i < 3; i++) k.box(wx + 0.12 + i * 0.12, 0.72, wz, 0.12, 0.1 - i * 0.02, 0.1 - i * 0.02, i % 2 ? WHITE : hex(0xf28c38));
        break;
      }
      case 'guardHut': {
        // a lonely hut with a lit window, a sign on its roof, a searchlight
        k.box(x, 0, z, w - 0.3, h, w - 0.3, hex(0xc8c4b8));
        k.box(x, h, z, w - 0.18, 0.05, w - 0.18, hex(0x6a7075));
        k.pane(x, 0.25, z + (w - 0.3) / 2, 0.4, 0.2, 1, GLASS, s, LAMP_GLOW);
        k.pane(x + (w - 0.3) / 2, 0.25, z, 0.3, 0.2, 0, GLASS, s, LAMP_GLOW);
        k.box(x - (w - 0.3) / 2 - 0.01, 0, z, 0.02, 0.45, 0.24, hex(0x4a4e52));
        for (const sx of [-1, 1]) k.box(x + sx * 0.4, h + 0.05, z, 0.03, 0.45, 0.03, METAL);
        k.box(x, h + 0.3, z + 0.02, 1.0, 0.3, 0.02, DGREEN);
        letters(k, 'SITE NULL', x, h + 0.42, z + 0.04, 0.1, MINT);
        letters(k, 'NO ENTRY', x, h + 0.32, z + 0.04, 0.08, WHITE);
        k.glowBox(x + 0.3, h + 0.05, z - 0.25, 0.12, 0.1, 0.12, LAMP_DAY, NIGHT, hex(0xe6eeff));
        figure(k, x + 0.6, z + 0.75, hex(0x5a6a4a), hex(0x3a4a2a));
        break;
      }
    }
  }
  // floodlight towers over the far end
  for (const [lx, lz] of [[5.6, -3.2], [-1, -7.4]] as [number, number][]) {
    k.cyl(lx, 0, lz, 0.04, 2.0, METAL, 4);
    k.box(lx, 2.0, lz, 0.4, 0.2, 0.1, DARK);
    for (let i = 0; i < 3; i++) k.glowBox(lx - 0.13 + i * 0.13, 2.04, lz + 0.06, 0.1, 0.1, 0.02, LAMP_DAY, NIGHT, hex(0xe6eeff));
  }
};

// ---- Federation House -----------------------------------------------------------------------------------------

const federation: Draw = (k, W, D, b, r) => {
  const p = strongholdPlan('shFederation');
  const BRICK = hex(0xa4553e), BRICK_D = hex(0x8a4434), STONE = hex(0xd8cfb8), ORANGE = hex(0xf2a93b), CHAR = hex(0x2a2a2e);
  const COBBLE = hex(0x8a8278), STEEL = hex(0xc0502a), CONC = hex(0xb8b4aa), CREAM = hex(0xf0e6cc), OVERALL = hex(0x3a5a8a);
  const s = windowSched(b.kind, r), g = windowGlow(b.kind, r);
  k.box(0, 0, 0, W - 0.1, 0.012, D - 0.1, hex(0x7e8078));

  // red-brick wall, piers, banners painted on its outer face
  drawWalls(k, p, { face: BRICK, cap: STONE, pierEvery: 2.4, pier: BRICK_D });
  along(k, p, 0, 3.6, (i) => {
    const off = p.wall.t / 2 + 0.006;
    k.box(0, 0.1, off, 0.9, 0.5, 0.01, i % 2 ? ORANGE : CREAM);
    k.box(0, 0.42, off + 0.003, 0.9, 0.08, 0.01, CHAR);
    k.face(0, 0.26, off + 0.01, 0.1, i % 2 ? CHAR : ORANGE, 8);
  });

  /** A banner hanging from a bracket on a face looking local +z. */
  const banner = (bx: number, top: number, bz: number, len: number, col: RGB) => {
    k.box(bx, top, bz + 0.04, 0.3, 0.025, 0.08, CHAR);
    k.box(bx, top - len, bz + 0.03, 0.26, len, 0.01, col);
    k.box(bx, top - len * 0.35, bz + 0.036, 0.26, 0.05, 0.01, CHAR);
    k.wedge(bx, top - len - 0.06, bz + 0.03, 0.26, 0.06, 0.01, col);
  };

  for (const bl of p.blocks) {
    const { x, z, w, d, h } = bl;
    switch (bl.type) {
      case 'hqWing': {
        k.box(x, 0, z, w, h, d, BRICK);
        for (const y of [0.15, 0.85]) k.box(x, y, z, w + 0.03, 0.05, d + 0.03, STONE);
        k.box(x, h, z, w + 0.1, 0.07, d + 0.1, STONE);
        k.gable(x, h + 0.07, z, w + 0.1, 0.55, d + 0.1, SLATE, BRICK);
        windows(k, b, r, bl, 1, [0.45, 1.1], 8, 0.16, 0.3, 0.4);
        windows(k, b, r, bl, 3, [0.35, 1.1], 8, 0.16, 0.3, 0.4);
        windows(k, b, r, bl, x < 0 ? 2 : 0, [0.35, 1.1], 2, 0.16, 0.3, 0.6);
        for (const cx of [x - w / 3, x + w / 3]) k.box(cx, h + 0.3, z, 0.3, 0.55, 0.3, BRICK_D);
        // the banner columns: pilasters with banners down the inner face, toward the yard
        for (let i = 0; i < 4; i++) {
          const px = x - w / 2 + 0.6 + i * ((w - 1.2) / 3);
          k.box(px, 0, z - d / 2 - 0.06, 0.24, h, 0.12, STONE);
          banner(px, h - 0.1, z - d / 2 - 0.12, 0.9, i % 2 ? ORANGE : CHAR);
        }
        break;
      }
      case 'arch': {
        // the storey over the way in, its stone trim, the crest, FEDERATION HOUSE, and the clock tower above
        k.box(x, 1.2, z, w, h - 1.2, d, BRICK);
        k.box(x, 1.2, z, w + 0.02, 0.07, d + 0.02, STONE);
        k.box(x, h, z, w + 0.1, 0.07, d + 0.1, STONE);
        k.box(x, 1.2, z + d / 2 + 0.01, 0.24, 0.2, 0.04, STONE);
        k.box(x, 1.2, z - d / 2 - 0.01, 0.24, 0.2, 0.04, STONE);
        letters(k, 'FEDERATION HOUSE', x, 1.42, z + d / 2 + 0.012, 0.17, CREAM);
        k.within(x, z, Math.PI, () => letters(k, 'UNITY IS STRENGTH', 0, 1.42, d / 2 + 0.012, 0.16, CREAM));
        const tz = z, ty = h + 0.07;
        k.box(x, ty, tz, 2.0, 1.0, 1.6, BRICK);
        for (const sx of [-1, 1]) k.box(x + sx * 0.95, ty, tz, 0.14, 1.0, 1.66, STONE);
        k.box(x, ty + 1.0, tz, 2.1, 0.07, 1.7, STONE);
        k.gable(x, ty + 1.07, tz, 2.1, 0.45, 1.7, SLATE, BRICK, true);
        // the crest: crossed hammers on an orange wheel, front and back
        for (const sz of [1, -1]) k.within(x, tz, sz > 0 ? 0 : Math.PI, () => {
          k.face(0, ty + 0.5, 0.81, 0.38, ORANGE, 16);
          k.face(0, ty + 0.5, 0.815, 0.28, CHAR, 14);
          k.face(0, ty + 0.5, 0.82, 0.24, ORANGE, 14);
          for (const a of [-1, 1]) {
            k.bar([a * -0.15, ty + 0.33, 0.83], [a * 0.12, ty + 0.64, 0.83], 0.018, CHAR);
            k.box(a * 0.12, ty + 0.62, 0.83, 0.14, 0.07, 0.03, CHAR);
          }
          k.face(0, ty + 1.24, 0.86, 0.15, CREAM, 12);
          k.spin(0, ty + 1.24, 0.87, 'z', 0, (hd) => hd.box(0, 0, 0, 0.012, 0.09, 0.004, CHAR), 'hour');
          k.spin(0, ty + 1.24, 0.875, 'z', 0, (hd) => hd.box(0, 0, 0, 0.008, 0.13, 0.004, CHAR), 'minute');
          // long banners down either side of the arch
          for (const bx of [-1.15, 1.15]) banner(bx, h - 0.02, d / 2, 0.4, ORANGE);
        });
        flag(k, x, tz, 0.9, 0, ORANGE, CHAR, ty + 1.52);
        for (const sx of [-1, 1]) k.glowBox(x + sx * 1.62, 0.7, z + d / 2 + 0.06, 0.08, 0.12, 0.08, LAMP_DAY, NIGHT, LAMP_GLOW);
        break;
      }
      case 'works': {
        // brick sheds under sawtooth roofs, their glazing to the front, roller doors onto the yard
        const wh = h * 0.68, n = 7, td = d / n;
        k.box(x, 0, z, w, wh, d, BRICK);
        k.box(x, wh - 0.06, z, w + 0.04, 0.06, d + 0.04, STONE);
        for (let i = 0; i < n; i++) {
          const tz = z - d / 2 + (i + 0.5) * td;
          k.wedge(x, wh, tz, w, h - wh, td, SLATE);
          k.pane(x, wh + 0.02, tz + td / 2, w - 0.2, h - wh - 0.06, 1, GLASS, s, g);
        }
        const yard = x < 0 ? 0 : 2, fx = x + (yard === 0 ? w / 2 + 0.012 : -w / 2 - 0.012);
        for (let i = 0; i < 3; i++) {
          const dz = z - d / 2 + 1.6 + i * ((d - 3.2) / 2);
          k.box(fx, 0, dz, 0.02, 0.55, 1.0, hex(0x6a7078));
          for (let j = 0; j < 5; j++) k.box(fx + (yard === 0 ? 0.004 : -0.004), 0.06 + j * 0.1, dz, 0.02, 0.012, 1.0, hex(0x4a5058));
          k.box(fx, 0.6, dz, 0.02, 0.1, 1.1, ORANGE);
        }
        windows(k, b, r, bl, yard, [0.3], 6, 0.2, 0.22, 0.7);
        windows(k, b, r, bl, yard === 0 ? 2 : 0, [0.3], 8, 0.2, 0.22, 0.5);
        k.within(fx + (yard === 0 ? 0.01 : -0.01), z, yard === 0 ? Math.PI / 2 : -Math.PI / 2, () => letters(k, x < 0 ? 'ENGINEERS' : 'FOUNDRY', 0, 0.68, 0, 0.16, CREAM));
        if (x < 0) {
          k.cyl(x - 0.8, 0, z - d / 2 + 0.6, 0.26, 2.6, BRICK_D, 10);
          k.cyl(x - 0.8, 2.4, z - d / 2 + 0.6, 0.3, 0.2, CHAR, 10);
        }
        break;
      }
      case 'meetingHall': {
        const bz = z - 0.1, bd = d - 0.2, front = bz + bd / 2;
        k.box(x, 0, bz, w, h * 0.8, bd, BRICK);
        k.box(x, 0, bz, w + 0.03, 0.14, bd + 0.03, STONE);
        k.box(x, h * 0.8, bz, w + 0.1, 0.07, bd + 0.1, STONE);
        k.gable(x, h * 0.8 + 0.07, bz, w + 0.1, 0.75, bd + 0.1, SLATE, BRICK);
        // tall windows with banners between them, the ventilator lantern on the ridge
        const sched: Sched = [17, 23, 1.5];
        for (let i = 0; i < 10; i++) {
          const wx = x - w / 2 + 1.0 + i * ((w - 2.0) / 9);
          if (Math.abs(wx - x) < 1.6) continue;
          k.pane(wx, 0.3, front, 0.3, 0.75, 1, GLASS, sched, LAMP_GLOW);
          k.box(wx, 1.08, front + 0.01, 0.38, 0.08, 0.03, STONE);
          if (i % 2 === 0 && i < 9) banner(wx + (w - 2.0) / 18, h * 0.8 - 0.1, front, 0.5, ORANGE);
        }
        windows(k, b, r, { x, z: bz, w, d: bd }, 3, [0.4], 10, 0.3, 0.6, 1.0);
        // the frontispiece: a pedimented bay with the doors, the crest and the motto
        k.box(x, 0, front + 0.1, 3.0, h * 0.8 + 0.2, 0.2, STONE);
        k.gable(x, h * 0.8 + 0.2, front + 0.1, 3.1, 0.6, 0.22, STONE, STONE, true);
        k.box(x, 0, front + 0.21, 1.0, 0.75, 0.02, hex(0x4a2e1e));
        k.face(x, h * 0.8 + 0.42, front + 0.215, 0.2, ORANGE, 12);
        k.face(x, h * 0.8 + 0.42, front + 0.22, 0.12, CHAR, 10);
        letters(k, 'ALL FOR ONE', x, 0.92, front + 0.215, 0.18, CHAR);
        k.cyl(x - 4, h * 0.8 + 0.6, bz, 0.25, 0.3, CREAM, 8);
        k.cone(x - 4, h * 0.8 + 0.9, bz, 0.32, 0.3, SLATE, 8);
        k.cyl(x + 4, h * 0.8 + 0.6, bz, 0.25, 0.3, CREAM, 8);
        k.cone(x + 4, h * 0.8 + 0.9, bz, 0.32, 0.3, SLATE, 8);
        break;
      }
      case 'rallyYard': {
        k.box(x, 0.014, z, w, 0.004, d, COBBLE);
        for (let i = 1; i < 8; i++) k.box(x - w / 2 + i * (w / 8), 0.019, z, 0.04, 0.002, d, hex(0x9a9286));
        for (let i = 1; i < 5; i++) k.box(x, 0.019, z - d / 2 + i * (d / 5), w, 0.002, 0.04, hex(0x9a9286));
        // banners on poles round the yard
        const poles: [number, number][] = [[-6.2, -1.0], [-2.2, -1.0], [2.2, -1.0], [6.2, -1.0], [-6.2, 2.6], [6.2, 2.6], [-6.2, 6.0], [6.2, 6.0]];
        poles.forEach(([px, pz], i) => {
          k.cyl(x + px, 0, pz, 0.03, 1.5, CHAR, 4);
          k.box(x + px, 1.46, pz, 0.4, 0.03, 0.03, CHAR);
          k.box(x + px, 0.82, pz, 0.36, 0.62, 0.012, i % 2 ? ORANGE : CREAM);
          k.box(x + px, 1.2, pz, 0.36, 0.08, 0.016, CHAR);
          k.face(x + px, 0.98, pz + 0.01, 0.09, i % 2 ? CHAR : ORANGE, 8);
        });
        // the crowd, in overalls and hi-vis, with a speaker's mark kept clear in the middle
        for (const side of [-1, 1]) for (let i = 0; i < 12; i++) {
          const fx = x + side * (1.6 + (i % 4) * 0.7 + (Math.floor(i / 4) % 2) * 0.3), fz = z + 0.4 + Math.floor(i / 4) * 0.7;
          figure(k, fx, fz, i % 3 === 0 ? ORANGE : i % 3 === 1 ? OVERALL : hex(0x6a5a4a), i % 2 ? hex(0x3a3a3a) : undefined);
        }
        for (const [lx, lz] of [[-6.2, 4.4], [6.2, 4.4], [-6.2, 0.8], [6.2, 0.8]] as [number, number][]) lamp(k, x + lx, lz, 0.75, CHAR);
        break;
      }
      case 'memorial': {
        // a stepped plinth, the bronze worker on it with his hammer raised, a wreath at his feet
        const BRONZE = hex(0x6a5a3a);
        k.box(x, 0, z, w, 0.12, d, STONE);
        k.box(x, 0.12, z, w - 0.25, 0.45, d - 0.25, STONE);
        k.box(x, 0.57, z, w - 0.15, 0.06, d - 0.15, STONE);
        k.box(x, 0.3, z + (d - 0.25) / 2 + 0.005, 0.4, 0.14, 0.01, BRONZE);
        for (const sx of [-1, 1]) k.box(x + sx * 0.06, 0.63, z + sx * 0.04, 0.07, 0.24, 0.08, BRONZE);
        k.box(x, 0.87, z, 0.2, 0.24, 0.12, BRONZE);
        k.box(x, 1.11, z, 0.09, 0.09, 0.09, BRONZE);
        k.box(x, 1.2, z, 0.12, 0.02, 0.12, BRONZE);
        k.bar([x + 0.11, 1.07, z], [x + 0.2, 1.32, z + 0.03], 0.03, BRONZE);
        k.box(x + 0.2, 1.32, z + 0.03, 0.04, 0.1, 0.04, BRONZE);
        k.box(x + 0.2, 1.42, z + 0.03, 0.14, 0.06, 0.06, BRONZE);
        k.bar([x - 0.11, 1.05, z], [x - 0.14, 0.82, z + 0.05], 0.03, BRONZE);
        k.hoop(x, 0.2, z + d / 2 + 0.02, 0.1, 0.02, hex(0xc8342a), 10);
        k.hoop(x, 0.2, z + d / 2 + 0.02, 0.07, 0.015, hex(0x3f7a3c), 8);
        break;
      }
      case 'frame': {
        // the apprentices' frame: columns, two floors of beams, a slab going in, workers up on it
        k.box(x, 0, z, w, 0.06, d, CONC);
        const cols = [x - w / 2 + 0.1, x - w / 6, x + w / 6, x + w / 2 - 0.1], rows = [z - d / 2 + 0.1, z + d / 2 - 0.1];
        for (const cx of cols) for (const cz of rows) k.box(cx, 0.06, cz, 0.09, h - 0.06, 0.09, STEEL);
        for (const y of [h * 0.48, h - 0.08]) {
          for (const cz of rows) k.box(x, y, cz, w - 0.1, 0.08, 0.07, STEEL);
          for (const cx of cols) k.box(cx, y, z, 0.07, 0.08, d - 0.1, STEEL);
        }
        k.box(x - w / 6, h * 0.48 + 0.08, z, w * 0.66, 0.04, d - 0.2, CONC);
        k.bar([cols[3], 0.08, rows[0]], [cols[2], h * 0.48, rows[0]], 0.02, STEEL);
        k.bar([cols[2], 0.08, rows[0]], [cols[3], h * 0.48, rows[0]], 0.02, STEEL);
        figure(k, x - 1.2, z + 0.3, ORANGE, hex(0xf2d24a), h * 0.48 + 0.12);
        figure(k, x - 0.2, z - 0.4, OVERALL, WHITE, h * 0.48 + 0.12);
        figure(k, x + 2.0, z + 0.6, ORANGE, hex(0xf2d24a));
        for (let i = 0; i < 4; i++) k.box(x + 2.2, 0.06 + i * 0.07, z - 0.5, 1.2, 0.06, 0.08 + (i % 2) * 0.02, STEEL);
        break;
      }
      case 'crane': {
        // a tower crane: lattice mast, the slewing deck and cab, the jib out over the frame, counterweights behind
        const top = h - 0.6, half = 0.22;
        k.box(x, 0, z, w * 0.85, 0.25, d * 0.85, CONC);
        const corners: [number, number][] = [[-half, -half], [half, -half], [half, half], [-half, half]];
        for (const [a, c] of corners) k.bar([x + a, 0.25, z + c], [x + a, top, z + c], 0.022, ORANGE);
        const nSec = 6, sh = (top - 0.25) / nSec;
        for (let i = 0; i < nSec; i++) for (let f = 0; f < 4; f++) {
          const [a0, c0] = corners[f], [a1, c1] = corners[(f + 1) % 4], y0 = 0.25 + i * sh;
          if (i % 2) k.bar([x + a0, y0, z + c0], [x + a1, y0 + sh, z + c1], 0.012, ORANGE);
          else k.bar([x + a1, y0, z + c1], [x + a0, y0 + sh, z + c0], 0.012, ORANGE);
        }
        k.box(x, top, z, 0.6, 0.18, 0.6, CHAR);
        k.box(x + 0.15, top + 0.18, z + 0.34, 0.3, 0.26, 0.26, ORANGE);
        k.pane(x + 0.15, top + 0.26, z + 0.47, 0.24, 0.14, 1, GLASS, s, g);
        const jy = top + 0.22, tip = -5.9, back = 2.0;
        for (const c of [-0.14, 0.14]) k.bar([x + 0.2, jy, z + c], [x + tip, jy, z + c], 0.016, ORANGE);
        k.bar([x + 0.2, jy + 0.26, z], [x + tip, jy + 0.06, z], 0.016, ORANGE);
        for (let i = 0; i < 8; i++) {
          const xa = x + 0.2 + (tip - 0.2) * (i / 8), xb = x + 0.2 + (tip - 0.2) * ((i + 1) / 8), ya = jy + 0.26 - 0.2 * (i / 8), yb = jy + 0.26 - 0.2 * ((i + 1) / 8);
          k.bar([xa, i % 2 ? ya : jy, z], [xb, i % 2 ? jy : yb, z], 0.01, ORANGE);
        }
        for (const c of [-0.14, 0.14]) k.bar([x - 0.2, jy, z + c], [x + back, jy, z + c], 0.016, ORANGE);
        k.box(x + back - 0.35, jy - 0.3, z, 0.5, 0.3, 0.4, CONC);
        k.bar([x, jy, z], [x, jy + 0.9, z], 0.03, ORANGE);
        k.bar([x, jy + 0.9, z], [x + tip * 0.75, jy + 0.2, z], 0.008, CHAR);
        k.bar([x, jy + 0.9, z], [x + back - 0.1, jy + 0.05, z], 0.008, CHAR);
        k.glowBox(x, jy + 0.92, z, 0.06, 0.06, 0.06, RED_LIGHT, BEACON, RED_LIGHT);
        // the trolley over the frame, the hook and a beam on its slings
        const hx = x - 5.2;
        k.box(hx, jy - 0.06, z, 0.16, 0.06, 0.3, CHAR);
        k.bar([hx, jy - 0.06, z], [hx, 2.15, z], 0.006, CHAR);
        k.box(hx, 2.05, z, 0.08, 0.1, 0.06, hex(0xf2d24a));
        k.bar([hx, 2.05, z], [hx - 0.4, 1.86, z], 0.005, CHAR);
        k.bar([hx, 2.05, z], [hx + 0.4, 1.86, z], 0.005, CHAR);
        k.box(hx, 1.8, z, 1.0, 0.06, 0.07, STEEL);
        break;
      }
      case 'canteen': {
        k.box(x, 0, z - 0.2, w, h, d - 0.4, CREAM);
        k.box(x, h, z - 0.2, w + 0.08, 0.06, d - 0.32, CHAR);
        windows(k, b, r, { x, z: z - 0.2, w, d: d - 0.4 }, 1, [0.22], 4, 0.3, 0.28, 0.4);
        k.box(x + 1.1, 0, z + (d - 0.4) / 2 - 0.2 + 0.01, 0.3, 0.5, 0.02, hex(0x4a2e1e));
        // the striped awning over tables, the sign, the stove pipe
        for (let i = 0; i < 8; i++) k.box(x - w / 2 + (i + 0.5) * (w / 8), 0.5, z + d / 2 - 0.2, w / 8, 0.03, 0.4, i % 2 ? CHAR : ORANGE);
        for (let i = 0; i < 3; i++) {
          k.box(x - 0.9 + i * 0.8, 0, z + d / 2 - 0.2, 0.3, 0.14, 0.18, WOOD);
          figure(k, x - 0.9 + i * 0.8 + 0.2, z + d / 2 - 0.2, i % 2 ? ORANGE : OVERALL);
        }
        letters(k, 'CANTEEN', x, h + 0.08, z + (d - 0.4) / 2 - 0.2 + 0.05, 0.16, ORANGE);
        k.box(x - w / 2 + 0.4, h + 0.06, z - 0.5, 0.12, 0.4, 0.12, DARK);
        break;
      }
      case 'pad': {
        helipad(k, x, z, Math.min(w, d) * 0.45, hex(0x5a5e62), ORANGE);
        break;
      }
    }
  }
  // the union's lorry by the works and its flags on the wings
  auto(k, -6.6, -1.6, 0, ORANGE, { len: 0.6, cabin: 0.3, cabinAt: 0.32, top: CHAR });
  k.box(-6.6, 0.11, -1.7, 0.2, 0.12, 0.36, CHAR);
  for (const fx of [-5, 5]) flag(k, fx, 10, 0.6, 0, ORANGE, CHAR, 2.3);
  figure(k, -0.9, 8.0, ORANGE, hex(0xf2d24a));
  figure(k, 0.9, 8.1, OVERALL);
};

