import { N, World } from './tiles';

/**
 * Scenery the player places from the builder's Scenery side (the user, 21 Oct 2026): trees, plants, rocks and
 * street furniture, one at a time, for a price, on open ground. Each is a `prop` edit in its cell's delta
 * (world/delta.ts), so it is saved, replayed over the generated island and shared online like a road; the
 * placed pieces live on `World.placed` and are drawn with the country's own instanced props (render/props.ts),
 * trees turning with the seasons like any other.
 *
 * They are decoration: nothing drives into them. Only open, dry, unbuilt, unpaved ground takes one.
 */

export type SceneryGroup = 'Trees' | 'Plants' | 'Street' | 'Park' | 'Country';
export const SCENERY_GROUPS: SceneryGroup[] = ['Trees', 'Plants', 'Street', 'Park', 'Country'];

interface SceneryDef {
  /** The id saved in the edit, and the model drawn (a kind in render/props.ts PropGeometries). */
  id: string;
  label: string;
  group: SceneryGroup;
  price: number;
  /** Scale of the model as placed. */
  s: number;
  /** A broadleaf or conifer: tinted and turned with the seasons as the country's are. */
  tree?: boolean;
  /** The kind whose year a tree follows, where its model's name isn't one (render/props.ts treeYear). */
  year?: string;
}

