export const SCENERY_BY_ID = new Map(SCENERY.map((d) => [d.id, d]));

/** One piece placed: where (tiles of its cell, to an eighth), which, turned how many eighths of a turn, and whose online. */
export interface Placed { x: number; z: number; p: string; r: number; by?: string }

/** Pieces a cell may hold, and how close two may stand. */
const SCENERY_MAX = 600;
const SCENERY_GAP = 0.22;
/** How near a click must be to a piece to take it up. */
const SCENERY_PICK = 0.45;

/** A point snapped to an eighth of a tile, as it is saved. */
export const snap8 = (v: number): number => Math.round(v * 8) / 8;

/** Why piece `id` can't stand at (x, z) of cell w, or null. */
export function sceneryProblem(w: World, x: number, z: number, id: string, r = 0): string | null {
  if (isFolly(id)) return follyProblem(w, x, z, id, r);
  if (!SCENERY_BY_ID.has(id)) return 'Pick something to place';
  const tx = Math.floor(x), tz = Math.floor(z);
  if (tx < 0 || tz < 0 || tx >= N || tz >= N) return 'Place it on this island’s own ground';
  const i = tz * N + tx;
  if (w.road[i] || w.deckAxis[i]) return 'Not on a road: pick the ground beside it';
  if (w.rail[i]) return 'Not on the railway';
  if (w.blocked[i]) return 'A building stands here';
  if (w.water[i] >= 0) return 'Not in the water';
  if (w.placed.length >= SCENERY_MAX) return `This island has all the scenery it can take (${SCENERY_MAX})`;
  if (w.placed.some((q) => Math.hypot(q.x - x, q.z - z) < SCENERY_GAP)) return 'Too close to something already placed';
  if (w.placed.some((q) => { const o = follyLot(q); return !!o && x >= o.x && x < o.x + o.w && z >= o.z && z < o.z + o.d; })) return 'A folly stands here';
  return null;
}

/** The placed piece nearest (x, z) within reach, or -1. */
export function placedNear(w: World, x: number, z: number, reach = SCENERY_PICK): number {
  let best = -1, bestD = reach;
  w.placed.forEach((q, k) => { const d = Math.hypot(q.x - x, q.z - z); if (d < bestD) { bestD = d; best = k; } });
  return best;
}

/**
 * A `prop` edit on an island: a piece placed, or (with `p` empty) the one nearest taken up. Returns the tile it
 * changed, for redrawing. Replayed edits take the same path, so a save and a live game never disagree.
 */
export function applyProp(w: World, e: { x: number; z: number; p: string; r?: number; by?: string }): number[] {
  if (!(e.x >= 0 && e.z >= 0 && e.x < N && e.z < N)) return [];
  const tile = Math.floor(e.z) * N + Math.floor(e.x);
  if (!e.p) {
    const k = placedNear(w, e.x, e.z);
    if (k < 0) return [];
    const q = w.placed[k];
    w.placed.splice(k, 1);
    return [Math.floor(q.z) * N + Math.floor(q.x)];
  }
  if (!(SCENERY_BY_ID.has(e.p) || isFolly(e.p)) || w.placed.length >= SCENERY_MAX) return [];
  w.placed.push({ x: e.x, z: e.z, p: e.p, r: ((e.r ?? 0) & 7), ...(e.by ? { by: e.by } : {}) });
  return [tile];
}

// ---- follies: a stamped building kind as scenery (game/follies.ts, the Passport's Buildings seal) ----

/** A folly's lot (x by z at facing 0), its storeys and whether the town would build it solid. */
export interface FollySize { w: number; d: number; floors: number; solid: boolean }

/** A building put up as scenery: its id is `bp` and the kind, capitalised (the server takes letters only). */
export const isFolly = (id: string): boolean => /^bp[A-Z][A-Za-z]{0,17}$/.test(id);
export const follyId = (kind: string): string => `bp${kind[0].toUpperCase()}${kind.slice(1)}`;
export const follyKind = (id: string): string => `${id[2].toLowerCase()}${id.slice(3)}`;

/** The most follies one island takes: each is drawn as a building. */
export const FOLLY_MAX = 48;

/** The sizes, from the game (game/follies.ts registers them): the world has no rosters of its own. */
let sizer: ((kind: string) => FollySize | null) | null = null;
export function setFollySizer(f: (kind: string) => FollySize | null): void { sizer = f; }

/** A folly as it stands: its kind, its lot's corner and size on the tiles (turned), its facing; null when unknown. */
export function follyLot(q: { x: number; z: number; p: string; r: number }): { kind: string; x: number; z: number; w: number; d: number; facing: number; size: FollySize } | null {
  if (!isFolly(q.p)) return null;
  const kind = follyKind(q.p);
  const size = sizer?.(kind);
  if (!size) return null;
  const facing = (q.r >> 1) & 3;
  const w = facing % 2 ? size.d : size.w, d = facing % 2 ? size.w : size.d;
  return { kind, x: q.x - w / 2, z: q.z - d / 2, w, d, facing, size };
}

/** Where a folly's middle goes for a point the cursor is on: its lot square on the tiles. */
export function follySnap(id: string, r: number, x: number, z: number): { x: number; z: number } {
  const lot = follyLot({ x: 0, z: 0, p: id, r });
  if (!lot) return { x, z };
  const fit = (v: number, n: number) => (n % 2 ? Math.floor(v) + 0.5 : Math.round(v));
  return { x: fit(x, lot.w), z: fit(z, lot.d) };
}

/** Why a folly can't stand at (x, z) turned `r`, or null: every tile of its lot open, dry, off the road, unbuilt. */
function follyProblem(w: World, x: number, z: number, id: string, r: number): string | null {
  const lot = follyLot({ x, z, p: id, r });
  if (!lot) return 'That building can’t be put up as scenery';
  const x0 = Math.floor(lot.x + 1e-6), z0 = Math.floor(lot.z + 1e-6), x1 = Math.ceil(lot.x + lot.w - 1e-6), z1 = Math.ceil(lot.z + lot.d - 1e-6);
  if (x0 < 0 || z0 < 0 || x1 > N || z1 > N) return 'Place it on this island’s own ground';
  for (let tz = z0; tz < z1; tz++) for (let tx = x0; tx < x1; tx++) {
    const i = tz * N + tx;
    if (w.road[i] || w.deckAxis[i]) return 'Not on a road: pick the ground beside it';
    if (w.rail[i]) return 'Not on the railway';
    if (w.blocked[i]) return 'A building stands here';
    if (w.water[i] >= 0) return 'Not in the water';
  }
  if (w.allBuildings.some((b) => !b.gone && b.x < x1 && b.x + b.w > x0 && b.z < z1 && b.z + b.d > z0)) return 'A building’s lot is here';
  if (w.placed.filter((q) => isFolly(q.p)).length >= FOLLY_MAX) return `This island has all the follies it can take (${FOLLY_MAX})`;
  for (const q of w.placed) {
    const o = follyLot(q);
    if (o ? o.x < x1 && o.x + o.w > x0 && o.z < z1 && o.z + o.d > z0 : q.x > x0 - 0.1 && q.x < x1 + 0.1 && q.z > z0 - 0.1 && q.z < z1 + 0.1) return 'Too close to something already placed';
  }
  return null;
}
