import * as THREE from 'three';
import { DIRS, STEP, World, idx, inB, type Building } from '../world/tiles';
import { FLOOR, buildingHeight } from '../world/towns';
import { builtShare } from './townMesh';
import { ALONE_AT, ALONE_BASE, drawAlone, letGo } from './roofTop';
import { clamp01 } from '../util/math';

/**
 * Building sites. A town's new building doesn't appear at once: for its first BUILD_HOURS game hours
 * (render/townMesh.ts leaves it out of the chunk meanwhile) its lot is a site. A hoarding goes round it,
 * tower cranes go up at its corners, and a concrete frame wrapped in scaffold netting rises in the
 * building's own shape: the massing is sampled from the finished model, so a church's tower climbs past
 * its nave and a tower block's podium tops out before the tower does. The cranes climb as it rises and
 * swing loads up from the street. When it tops out the scaffold comes away in a poof of dust, and the
 * host draws the chunk again with the real building in it.
 */

interface SiteHost {
  /** Islands in memory. */
  worlds(): World[];
  /** The game clock in hours. */
  hours(): number;
  /** A site is done: draw these tiles' chunks again, with the building in them. */
  done(w: World, tiles: number[]): void;
  /** The poof, at this loudness (0 to 1, by distance from what the camera looks at). */
  poof?(level: number): void;
  /** A site has topped out: its building stands (the paper's "built" news, docs/newspaper.html). */
  built?(w: World, b: Building): void;
  /** What the camera looks at, world units, for how loud a poof is. */
  focus?(): { x: number; z: number };
  /** 0 by day to 1 at night, for the cranes' beacons. */
  night?(): number;
}

/** Cells per tile in the massing grid. */
const RES = 4;
/** Share of the build spent clearing the lot and putting the cranes up, and topping out at the end (the building card's phases, game/inspect.ts). */
export const SETUP = 0.06, TOPPED = 0.96;
/** Seconds between scans of the islands for new sites. */
const SCAN = 0.25;
/** How much higher each crane on a site stands than the one before it (world units): over a jib and its A-frame. */
const CRANE_STEP = 0.32;
/** A crane's working cycle, real seconds. */
const CYCLE = 14;
/** Seconds of dust before the finished building takes the site's place. */
const SWAP = 0.12;

interface Rect { x0: number; z0: number; x1: number; z1: number; h: number }

interface Crane {
  root: THREE.Group;
  mast: THREE.Mesh;
  mastTex: THREE.Texture;
  head: THREE.Group;
  trolley: THREE.Group;
  cable: THREE.Mesh;
  hook: THREE.Group;
  load: THREE.Object3D;
  beacons: THREE.Mesh[];
  /** Local (site-frame) position of the mast foot. */
  x: number; z: number;
  jib: number;
  /** Where it picks up (the street in front) and puts down (over the building), as angle and reach from the mast. */
  pickA: number; pickR: number; dropA: number; dropR: number;
  /** Offset into the cycle, so cranes on one site don't move as one. */
  phase: number;
  /**
   * How much higher this crane's mast stands than the site's first: each after the first a step over the last, more
   * than a jib and its A-frame, so two jibs swinging over the same frame pass one above the other and never through
   * each other (the user, 11 Nov 2026).
   */
  lift: number;
}

interface Site {
  w: World;
  b: Building;
  group: THREE.Group;
  rects: Rect[];
  top: number;
  core: THREE.Mesh;
  net: THREE.Mesh;
  cranes: Crane[];
  /** The core height last drawn, so the geometry is only rebuilt when it has risen. */
  drawn: number;
  /** Site-frame origin: the lot's corner at its pad height, in world units. */
  ox: number; oy: number; oz: number;
}

interface Puff { m: THREE.Mesh; v: THREE.Vector3; spin: THREE.Vector3; r: number; age: number; life: number }

// ---- textures ----

/** A concrete frame: pale columns and slab edges round dark open bays, one storey and one bay a repeat. */
function frameTexture(): THREE.CanvasTexture {
  const c = document.createElement('canvas');
  c.width = c.height = 32;
  const g = c.getContext('2d')!;
  g.fillStyle = '#8c8780';
  g.fillRect(0, 0, 32, 32);
  g.fillStyle = '#e2ddd3';
  g.fillRect(0, 0, 5, 32);
  g.fillRect(0, 26, 32, 6);
  g.fillStyle = '#c9c3b8';
  g.fillRect(5, 24, 27, 2);
  const t = new THREE.CanvasTexture(c);
  t.wrapS = t.wrapT = THREE.RepeatWrapping;
  t.colorSpace = THREE.SRGBColorSpace;
  t.magFilter = THREE.NearestFilter;
  return t;
}

/** Scaffold netting: a blue-green sheet with the tubes showing through it. */
function netTexture(): THREE.CanvasTexture {
  const c = document.createElement('canvas');
  c.width = c.height = 32;
  const g = c.getContext('2d')!;
  g.fillStyle = 'rgba(40, 128, 150, 0.72)';
  g.fillRect(0, 0, 32, 32);
  g.fillStyle = 'rgba(214, 206, 180, 0.95)';
  g.fillRect(0, 0, 2, 32);
  g.fillRect(16, 0, 1, 32);
  g.fillRect(0, 0, 32, 2);
  g.fillStyle = 'rgba(240, 178, 60, 0.95)';
  g.fillRect(0, 15, 32, 1);
  const t = new THREE.CanvasTexture(c);
  t.wrapS = t.wrapT = THREE.RepeatWrapping;
  t.colorSpace = THREE.SRGBColorSpace;
  return t;
}

/** A crane's lattice: the mast and the jib are yellow triangulated steel, see-through between the bars. */
function latticeTexture(): THREE.CanvasTexture {
  const c = document.createElement('canvas');
  c.width = c.height = 16;
  const g = c.getContext('2d')!;
  g.strokeStyle = '#f2b33b';
  g.lineWidth = 2;
  g.strokeRect(1, 1, 14, 14);
  g.beginPath();
  g.moveTo(1, 15); g.lineTo(15, 1);
  g.stroke();
  const t = new THREE.CanvasTexture(c);
  t.wrapS = t.wrapT = THREE.RepeatWrapping;
  t.colorSpace = THREE.SRGBColorSpace;
  return t;
}

// ---- geometry ----

/** Boxes as one geometry, their sides mapped a bay (half a tile) by a storey so the textures tile true. */
class BoxBatch {
  pos: number[] = [];
  uv: number[] = [];
  nor: number[] = [];

  box(x0: number, y0: number, z0: number, x1: number, y1: number, z1: number, top = true): void {
    if (y1 - y0 < 1e-3) return;
    const bay = 0.5;
    // four sides, each wound to face out
    this.quad([x0, y0, z1], [x1, y0, z1], [x1, y1, z1], [x0, y1, z1], [0, 0, 1], x0 / bay, x1 / bay, y0 / FLOOR, y1 / FLOOR);
    this.quad([x1, y0, z0], [x0, y0, z0], [x0, y1, z0], [x1, y1, z0], [0, 0, -1], x1 / bay, x0 / bay, y0 / FLOOR, y1 / FLOOR);
    this.quad([x1, y0, z1], [x1, y0, z0], [x1, y1, z0], [x1, y1, z1], [1, 0, 0], z1 / bay, z0 / bay, y0 / FLOOR, y1 / FLOOR);
    this.quad([x0, y0, z0], [x0, y0, z1], [x0, y1, z1], [x0, y1, z0], [-1, 0, 0], z0 / bay, z1 / bay, y0 / FLOOR, y1 / FLOOR);
    // the top shows a slab: one flat bit of the texture's pale edge
    if (top) this.quad([x0, y1, z1], [x1, y1, z1], [x1, y1, z0], [x0, y1, z0], [0, 1, 0], 0.5, 0.5, 0.9, 0.9);
  }

  private quad(a: number[], b: number[], c: number[], d: number[], n: number[], u0: number, u1: number, v0: number, v1: number): void {
    this.pos.push(...a, ...b, ...c, ...a, ...c, ...d);
    this.uv.push(u0, v0, u1, v0, u1, v1, u0, v0, u1, v1, u0, v1);
    for (let i = 0; i < 6; i++) this.nor.push(...n);
  }

  into(geo: THREE.BufferGeometry): void {
    geo.setAttribute('position', new THREE.Float32BufferAttribute(this.pos, 3));
    geo.setAttribute('uv', new THREE.Float32BufferAttribute(this.uv, 2));
    geo.setAttribute('normal', new THREE.Float32BufferAttribute(this.nor, 3));
    geo.computeBoundingSphere();
  }
}

// ---- the massing: the finished building's shape, sampled ----

const S0 = ALONE_AT;

/**
 * The finished building's heights on a grid of RES cells a tile, read off the mesher's own model of it
 * drawn on a scratch island, merged into rectangles of about one height. In the lot's frame, world units
 * over its pad.
 */
function massing(w: World, b: Building): Rect[] {
  const g = drawAlone(w, b);
  const GW = b.w * RES, GD = b.d * RES;
  const hs = new Float32Array(GW * GD);
  const base = ALONE_BASE;
  if (g) {
    const v = new THREE.Vector3(), tri = [new THREE.Vector3(), new THREE.Vector3(), new THREE.Vector3()];
    const mark = (p: THREE.Vector3) => {
      const cx = Math.floor((p.x - S0) * RES), cz = Math.floor((p.z - S0) * RES);
      if (cx < 0 || cz < 0 || cx >= GW || cz >= GD) return;
      const h = p.y - base, k = cz * GW + cx;
      if (h > hs[k]) hs[k] = h;
    };
    g.traverse((o) => {
      const m = o as THREE.Mesh;
      if (!m.isMesh || (m as unknown as THREE.InstancedMesh).isInstancedMesh) return;
      const pos = m.geometry.getAttribute('position');
      if (!pos) return;
      const index = m.geometry.index;
      const n = index ? index.count : pos.count;
      for (let i = 0; i + 2 < n; i += 3) {
        for (let j = 0; j < 3; j++) tri[j].fromBufferAttribute(pos, index ? index.getX(i + j) : i + j).applyMatrix4(m.matrixWorld);
        // the corners, the middle and the edges' midpoints: enough to catch a roof over a cell
        for (let j = 0; j < 3; j++) { mark(tri[j]); mark(v.copy(tri[j]).add(tri[(j + 1) % 3]).multiplyScalar(0.5)); }
        mark(v.copy(tri[0]).add(tri[1]).add(tri[2]).divideScalar(3));
      }
    });
    // let it all go: fresh geometry, and a windmill's sails must drop out of the spinners' list
    letGo(g);
  }
  // nothing drawn (or a flat lot): a plain box to the building's height
  let any = false;
  for (let k = 0; k < hs.length; k++) if (hs[k] > 0.04) { any = true; break; }
  // nothing drawn: a stand-in to the building's own height, a cell in from the hoarding, so the frame still visibly
  // rises over it and the cranes have something to work on (it was a 0.3-high slab, all but hidden by the fence)
  if (!any) {
    const h = Math.max(0.4, Math.min(buildingHeight(b), 3));
    const m = GW > 2 && GD > 2 ? 1 : 0;
    for (let z = m; z < GD - m; z++) for (let x = m; x < GW - m; x++) hs[z * GW + x] = h;
  }

  // quantise, so neighbouring cells of about one height merge
  const q = (h: number) => (h < 0.04 ? 0 : Math.max(0.1, Math.round(h / 0.13) * 0.13));
  const used = new Uint8Array(GW * GD);
  const rects: Rect[] = [];
  for (let z = 0; z < GD; z++) {
    for (let x = 0; x < GW; x++) {
      const k = z * GW + x;
      const h = q(hs[k]);
      if (used[k] || h === 0) continue;
      let x1 = x + 1;
      while (x1 < GW && !used[z * GW + x1] && q(hs[z * GW + x1]) === h) x1++;
      let z1 = z + 1;
      grow: while (z1 < GD) {
        for (let xx = x; xx < x1; xx++) if (used[z1 * GW + xx] || q(hs[z1 * GW + xx]) !== h) break grow;
        z1++;
      }
      for (let zz = z; zz < z1; zz++) for (let xx = x; xx < x1; xx++) used[zz * GW + xx] = 1;
      rects.push({ x0: x / RES, z0: z / RES, x1: x1 / RES, z1: z1 / RES, h });
    }
  }
  return rects;
}

// ---- the layer ----

const ease = (t: number) => t * t * (3 - 2 * t);

export class Construction {
  readonly root = new THREE.Group();
  private sites = new Map<Building, Site>();
  private puffs: Puff[] = [];
  /** Sites done and poofing, with the seconds left before they swap for their buildings. */
  private swaps: { s: Site; t: number }[] = [];
  private scanT = 0;
  private time = 0;

  private frameTex = frameTexture();
  private netTex = netTexture();
  private latTex = latticeTexture();
  private coreMat = new THREE.MeshStandardMaterial({ map: this.frameTex, roughness: 0.95 });
  private netMat = new THREE.MeshStandardMaterial({ map: this.netTex, roughness: 1, transparent: true, depthWrite: false, side: THREE.DoubleSide });
  private padMat = new THREE.MeshStandardMaterial({ color: 0x9a7b56, roughness: 1, polygonOffset: true, polygonOffsetFactor: -2, polygonOffsetUnits: -2 });
  private fenceMat = new THREE.MeshStandardMaterial({ color: 0x2f5d8a, roughness: 0.9 });
  private yellow = new THREE.MeshStandardMaterial({ color: 0xf2b33b, roughness: 0.6 });
  private dark = new THREE.MeshStandardMaterial({ color: 0x4a4642, roughness: 0.8 });
  private cabMat = new THREE.MeshStandardMaterial({ color: 0xf2f0ea, roughness: 0.5 });
  private beaconMat = new THREE.MeshBasicMaterial({ color: 0xff3b2a });
  private loadMats = [0xa4523a, 0x8f969c, 0xc9a46a].map((c) => new THREE.MeshStandardMaterial({ color: c, roughness: 0.8 }));
  private puffGeo = new THREE.IcosahedronGeometry(1, 0);
  private unitBox = new THREE.BoxGeometry(1, 1, 1);

  constructor(private host: SiteHost) {
    this.root.name = 'construction sites';
  }

  /** How many sites are going (the console's pr.sites). */
  get count(): number { return this.sites.size; }

  update(dt: number): void {
    this.time += dt;
    const hours = this.host.hours();
    this.scanT -= dt;
    if (this.scanT <= 0) {
      this.scanT = SCAN;
      this.scan(hours);
    }
    for (const s of [...this.sites.values()]) {
      const p = builtShare(s.b, hours);
      if (p >= 1) { this.finish(s, true); continue; }
      this.pose(s, p);
    }
    this.stepSwaps(dt);
    this.stepPuffs(dt);
  }

  /** Find new sites on the islands in memory, and let go of any whose building or island has gone. */
  private scan(hours: number): void {
    const worlds = this.host.worlds();
    for (const s of [...this.sites.values()]) {
      if (s.b.gone || !worlds.includes(s.w)) this.finish(s, false);
    }
    for (const w of worlds) {
      for (const b of w.allBuildings) {
        if (b.grownAt === undefined || b.gone || this.sites.has(b)) continue;
        if (builtShare(b, hours) >= 1) continue;
        this.open(w, b);
      }
    }
  }

  clear(): void {
    for (const s of [...this.sites.values()]) this.finish(s, false);
    for (const q of this.swaps) this.drop(q.s);
    this.swaps = [];
    for (const q of this.puffs) { this.root.remove(q.m); (q.m.material as THREE.Material).dispose(); }
    this.puffs = [];
  }

  // ---- a site ----

  private open(w: World, b: Building): void {
    const rects = massing(w, b);
    const top = Math.max(0.1, ...rects.map((r) => r.h));
    const group = new THREE.Group();
    const oy = b.level * STEP;
    group.position.set(w.ox + b.x, oy, w.oz + b.z);
    this.root.add(group);

    // the lot dug over, and a hoarding round it with a gate on the street side
    const pad = new THREE.Mesh(new THREE.PlaneGeometry(b.w, b.d).rotateX(-Math.PI / 2), this.padMat);
    pad.position.set(b.w / 2, 0.015, b.d / 2);
    pad.receiveShadow = true;
    group.add(pad);
    const fh = 0.12, ft = 0.03, e = 0.03;
    const [fx, fz] = DIRS[b.facing];
    const side = (x0: number, z0: number, x1: number, z1: number, front: boolean) => {
      const len = Math.hypot(x1 - x0, z1 - z0);
      const along = (u0: number, u1: number) => {
        const m = new THREE.Mesh(this.unitBox, this.fenceMat);
        const ax = x0 + (x1 - x0) * (u0 + u1) / 2, az = z0 + (z1 - z0) * (u0 + u1) / 2;
        const l = len * (u1 - u0);
        m.scale.set(x1 !== x0 ? l : ft, fh, z1 !== z0 ? l : ft);
        m.position.set(ax, fh / 2, az);
        m.castShadow = true;
        group.add(m);
      };
      if (front && len > 0.8) { along(0, 0.5 - 0.2 / len); along(0.5 + 0.2 / len, 1); } else along(0, 1);
    };
    side(e, e, b.w - e, e, fz === -1);
    side(e, b.d - e, b.w - e, b.d - e, fz === 1);
    side(e, e, e, b.d - e, fx === -1);
    side(b.w - e, e, b.w - e, b.d - e, fx === 1);

    const core = new THREE.Mesh(new THREE.BufferGeometry(), this.coreMat);
    core.castShadow = core.receiveShadow = true;
    const net = new THREE.Mesh(new THREE.BufferGeometry(), this.netMat);
    net.renderOrder = 2;
    group.add(core, net);

    const s: Site = { w, b, group, rects, top, core, net, cranes: [], drawn: -1, ox: w.ox + b.x, oy, oz: w.oz + b.z };
    // cranes by size: one for a house, two or three for the big ones, whatever their height (a low, wide amphitheatre
    // is still a big job); none only for a one-tile lot that is all but flat
    const area = b.w * b.d;
    const n = area >= 20 ? 3 : area >= 6 || top > 2.2 ? 2 : top >= 0.35 || area >= 2 ? 1 : 0;
    // the corners with the least building on them, the back ones first (the street is at the front)
    const corners: [number, number][] = [[0, 0], [1, 0], [0, 1], [1, 1]];
    const inset = 0.16;
    const score = ([cx, cz]: [number, number]) => {
      const x = cx ? b.w - inset : inset, z = cz ? b.d - inset : inset;
      const h = this.heightAt(rects, x, z);
      const back = (cx ? 1 : -1) * fx + (cz ? 1 : -1) * fz;
      return h + back * 0.3;
    };
    corners.sort((a, c) => score(a) - score(c));
    const cx = b.w / 2, cz = b.d / 2;
    const street = { x: cx + fx * (b.w / 2 + 0.35), z: cz + fz * (b.d / 2 + 0.35) };
    for (let i = 0; i < n; i++) {
      const [ccx, ccz] = corners[i];
      const x = ccx ? b.w - inset : inset, z = ccz ? b.d - inset : inset;
      const jib = Math.max(1.1, Math.min(3.6, Math.hypot(b.w, b.d) * 0.75 + 0.4));
      // pick up at the street in front, put down over the middle of the building (or a quarter of it, for two or more)
      const tx = n > 1 ? cx + (x - cx) * 0.35 : cx, tz = n > 1 ? cz + (z - cz) * 0.35 : cz;
      const c = this.crane(group, x, z, jib, (b.seed >>> (i * 5)) % 97 / 97);
      c.pickA = Math.atan2(street.x - x, street.z - z);
      c.pickR = Math.min(jib * 0.95, Math.max(0.35, Math.hypot(street.x - x, street.z - z)));
      c.dropA = Math.atan2(tx - x, tz - z);
      c.dropR = Math.min(jib * 0.95, Math.max(0.3, Math.hypot(tx - x, tz - z)));
      c.lift = i * CRANE_STEP;
      s.cranes.push(c);
    }
    this.sites.set(b, s);
  }

  /** The finished building's height over a point of its lot (lot frame). */
  private heightAt(rects: Rect[], x: number, z: number): number {
    let h = 0;
    for (const r of rects) if (x >= r.x0 && x < r.x1 && z >= r.z0 && z < r.z1) h = Math.max(h, r.h);
    return h;
  }

  private crane(parent: THREE.Group, x: number, z: number, jib: number, phase: number): Crane {
    const root = new THREE.Group();
    root.position.set(x, 0, z);
    parent.add(root);
    const box = (mat: THREE.Material, w: number, h: number, d: number, px: number, py: number, pz: number, into: THREE.Object3D) => {
      const m = new THREE.Mesh(this.unitBox, mat);
      m.scale.set(w, h, d);
      m.position.set(px, py, pz);
      m.castShadow = true;
      into.add(m);
      return m;
    };
    // a concrete footing, and the mast: its own copy of the lattice, repeated to its height
    box(this.dark, 0.22, 0.05, 0.22, 0, 0.025, 0, root);
    const mastTex = this.latTex.clone();
    mastTex.needsUpdate = true;
    const mast = box(new THREE.MeshStandardMaterial({ map: mastTex, alphaTest: 0.5, side: THREE.DoubleSide, roughness: 0.6 }), 0.1, 1, 0.1, 0, 0.5, 0, root);
    // the slewing head: cab, jib out front, counter-jib and its weights behind, the A-frame over it all
    const head = new THREE.Group();
    root.add(head);
    box(this.yellow, 0.14, 0.05, 0.14, 0, 0.025, 0, head);
    box(this.cabMat, 0.09, 0.08, 0.1, 0.09, 0.04, 0.02, head);
    box(this.yellow, 0.06, 0.06, jib, 0, 0.09, jib / 2 + 0.05, head);
    box(this.yellow, 0.07, 0.06, jib * 0.32, 0, 0.09, -jib * 0.16 - 0.05, head);
    box(this.dark, 0.12, 0.1, 0.12, 0, 0.07, -jib * 0.3, head);
    box(this.yellow, 0.05, 0.22, 0.05, 0, 0.2, 0, head);
    const beacons: THREE.Mesh[] = [];
    const beacon = (px: number, py: number, pz: number) => {
      const m = new THREE.Mesh(this.unitBox, this.beaconMat);
      m.scale.setScalar(0.035);
      m.position.set(px, py, pz);
      head.add(m);
      beacons.push(m);
    };
    beacon(0, 0.33, 0);
    beacon(0, 0.14, jib + 0.03);
    // the trolley runs along under the jib; the hook hangs off it on a cable
    const trolley = new THREE.Group();
    trolley.position.set(0, 0.05, jib * 0.5);
    head.add(trolley);
    box(this.dark, 0.08, 0.03, 0.08, 0, 0, 0, trolley);
    const cable = box(this.dark, 0.012, 1, 0.012, 0, -0.5, 0, trolley);
    cable.castShadow = false;
    const hook = new THREE.Group();
    trolley.add(hook);
    box(this.dark, 0.04, 0.04, 0.04, 0, 0, 0, hook);
    // what it's carrying: a pallet of bricks, a bundle of beams or a skip
    const kind = Math.floor(phase * 3) % 3;
    const load = kind === 1 ? box(this.loadMats[1], 0.05, 0.05, 0.3, 0, -0.06, 0, hook) : box(this.loadMats[kind], 0.13, 0.08, 0.13, 0, -0.07, 0, hook);
    return { root, mast, mastTex, head, trolley, cable, hook, load, beacons, x, z, jib, pickA: 0, pickR: 0, dropA: 0, dropR: 0, phase: phase * CYCLE, lift: 0 };
  }

  /** Draw a site as it stands at p (0 to 1) of the way through its build. */
  private pose(s: Site, p: number): void {
    // the frame rises in the building's shape; low parts top out first
    const rise = ease(clamp01((p - SETUP) / (TOPPED - SETUP)));
    const hc = s.top * rise;
    if (Math.abs(hc - s.drawn) > 0.004 || s.drawn < 0) {
      s.drawn = hc;
      const core = new BoxBatch(), net = new BoxBatch();
      const band = FLOOR * 2.2, lift = FLOOR * 0.8, pad = 0.035;
      for (const r of s.rects) {
        const h = Math.min(r.h, hc);
        if (h <= 0.002) continue;
        core.box(r.x0, 0, r.z0, r.x1, h, r.z1);
        // still going up: netting round the top storeys, standing a little above the slab being poured
        if (r.h > hc) net.box(r.x0 - pad, Math.max(0, h - band), r.z0 - pad, r.x1 + pad, Math.min(r.h, h + lift), r.z1 + pad, false);
      }
      s.core.geometry.dispose();
      s.core.geometry = new THREE.BufferGeometry();
      core.into(s.core.geometry);
      s.net.geometry.dispose();
      s.net.geometry = new THREE.BufferGeometry();
      net.into(s.net.geometry);
    }

    const night = this.host.night?.() ?? 0;
    const blink = (this.time * 1.1) % 1 < 0.5;
    for (const c of s.cranes) {
      // the mast goes up while the lot is cleared, then climbs to keep its jib clear of the frame
      const erect = ease(clamp01(p / SETUP));
      const clear = Math.max(0.6, this.heightAt(s.rects, c.x, c.z) + 0.35);
      const H = Math.max(0.05, erect * (Math.max(clear, hc + 0.55, Math.min(s.top, 1) + 0.35) + c.lift));
      c.mast.scale.y = H;
      c.mast.position.y = H / 2;
      c.mastTex.repeat.set(1, Math.max(1, Math.round(H / 0.1)));
      c.head.position.y = H;
      c.head.visible = erect > 0.95;
      for (const bcn of c.beacons) bcn.visible = blink && (night > 0.3 || bcn === c.beacons[0]);
      if (!c.head.visible) continue;

      // the working cycle: hook down at the street, up, swing, down onto the frame, up, swing back
      const u = (((this.time + c.phase) % CYCLE) + CYCLE) % CYCLE / CYCLE;
      const working = p < TOPPED;
      let a: number, r: number, drop: number, carrying: boolean;
      const topY = hc + 0.12;
      const lowered = (y: number) => Math.max(0.12, H - y);
      if (!working) { a = c.dropA; r = c.jib * 0.3; drop = 0.35; carrying = false; }
      else if (u < 0.12) { a = c.pickA; r = c.pickR; drop = 0.3 + (lowered(0.12) - 0.3) * ease(u / 0.12); carrying = u > 0.1; }
      else if (u < 0.24) { a = c.pickA; r = c.pickR; drop = lowered(0.12) * (1 - ease((u - 0.12) / 0.12)) + 0.3 * ease((u - 0.12) / 0.12); carrying = true; }
      else if (u < 0.5) { const k = ease((u - 0.24) / 0.26); a = c.pickA + wrap(c.dropA - c.pickA) * k; r = c.pickR + (c.dropR - c.pickR) * k; drop = 0.3; carrying = true; }
      else if (u < 0.6) { a = c.dropA; r = c.dropR; drop = 0.3 + (lowered(topY) - 0.3) * ease((u - 0.5) / 0.1); carrying = true; }
      else if (u < 0.7) { a = c.dropA; r = c.dropR; drop = lowered(topY) + (0.3 - lowered(topY)) * ease((u - 0.6) / 0.1); carrying = false; }
      else { const k = ease((u - 0.7) / 0.3); a = c.dropA + wrap(c.pickA - c.dropA) * k; r = c.dropR + (c.pickR - c.dropR) * k; drop = 0.3; carrying = false; }
      c.head.rotation.y = a;
      c.trolley.position.z = Math.max(0.2, Math.min(c.jib, r));
      drop = Math.max(0.12, drop);
      c.cable.scale.y = drop;
      c.cable.position.y = -drop / 2;
      c.hook.position.y = -drop;
      c.load.visible = carrying;
    }
  }

  /** A site is over: finished (the poof, and the chunk drawn again with the building), or just gone. */
  private finish(s: Site, built: boolean): void {
    this.sites.delete(s.b);
    if (built) {
      this.host.built?.(s.w, s.b);
      // the dust first: the site and the building swap once it is thick enough to hide them
      this.poof(s);
      this.swaps.push({ s, t: SWAP });
      return;
    }
    this.drop(s);
  }

  /** Take a site's meshes down and let their geometry go. */
  private drop(s: Site): void {
    this.root.remove(s.group);
    s.core.geometry.dispose();
    s.net.geometry.dispose();
    s.group.traverse((o) => {
      const m = o as THREE.Mesh;
      if (!m.isMesh) return;
      if (m.geometry !== this.unitBox && m.geometry !== s.core.geometry && m.geometry !== s.net.geometry) m.geometry.dispose();
    });
    for (const c of s.cranes) { (c.mast.material as THREE.Material).dispose(); c.mastTex.dispose(); }
  }

  /** The swap under the dust: the site comes down and the chunk is drawn again with the building in it. */
  private stepSwaps(dt: number): void {
    if (!this.swaps.length) return;
    const worlds = this.host.worlds();
    this.swaps = this.swaps.filter((q) => {
      q.t -= dt;
      if (q.t > 0) return true;
      this.drop(q.s);
      const b = q.s.b, tiles: number[] = [];
      for (let z = b.z - 1; z <= b.z + b.d; z++) for (let x = b.x - 1; x <= b.x + b.w; x++) if (inB(x, z)) tiles.push(idx(x, z));
      if (worlds.includes(q.s.w)) this.host.done(q.s.w, tiles);
      return false;
    });
  }

  // ---- the poof ----

  /** Dust thrown off the whole of the frame as the scaffold comes away, sized to the building. */
  private poof(s: Site): void {
    const b = s.b;
    const span = Math.min(b.w, b.d);
    const r0 = Math.max(0.18, Math.min(0.9, span * 0.3));
    const cx = s.ox + b.w / 2, cz = s.oz + b.d / 2;
    const add = (x: number, y: number, z: number, r: number, dir: THREE.Vector3, speed: number, life: number, grey: number) => {
      const mat = new THREE.MeshStandardMaterial({ color: grey, roughness: 1, flatShading: true, transparent: true, depthWrite: false });
      const m = new THREE.Mesh(this.puffGeo, mat);
      m.position.set(x, y, z);
      m.scale.setScalar(0.001);
      m.rotation.set(Math.random() * 6, Math.random() * 6, Math.random() * 6);
      this.root.add(m);
      const spin = new THREE.Vector3(Math.random() - 0.5, Math.random() - 0.5, Math.random() - 0.5).multiplyScalar(3);
      this.puffs.push({ m, v: dir.multiplyScalar(speed), spin, r, age: 0, life });
    };
    // a ball over each part of the massing, up its height, and a ring thrown out along the ground
    const col = () => (Math.random() < 0.3 ? 0xdcd6ca : 0xf4f1ea);
    let n = 0;
    for (const r of s.rects) {
      const w = r.x1 - r.x0, d = r.z1 - r.z0;
      const levels = Math.max(1, Math.round(r.h / Math.max(0.35, span * 0.5)));
      for (let k = 0; k < levels && n < 60; k++, n++) {
        const x = s.ox + r.x0 + Math.random() * w, z = s.oz + r.z0 + Math.random() * d;
        const y = s.oy + (r.h * (k + 0.5)) / levels;
        const dir = new THREE.Vector3(x - cx, 0.4, z - cz).normalize();
        add(x, y, z, r0 * (0.8 + Math.random() * 0.6), dir, 0.6 + Math.random() * 0.8, 0.9 + Math.random() * 0.5, col());
      }
    }
    const ring = Math.round(8 + 3 * (b.w + b.d));
    for (let i = 0; i < ring; i++) {
      const a = (i / ring) * Math.PI * 2 + Math.random() * 0.3;
      const x = cx + Math.cos(a) * b.w * 0.5, z = cz + Math.sin(a) * b.d * 0.5;
      const dir = new THREE.Vector3(Math.cos(a), 0.12 + Math.random() * 0.3, Math.sin(a)).normalize();
      add(x, s.oy + 0.1, z, r0 * (0.6 + Math.random() * 0.5), dir, 1.2 + Math.random() * 1.4, 0.8 + Math.random() * 0.5, col());
    }
    const f = this.host.focus?.();
    const d = f ? Math.hypot(f.x - cx, f.z - cz) : 0;
    this.host.poof?.(1 / (1 + d / 12));
  }

  private stepPuffs(dt: number): void {
    if (!this.puffs.length) return;
    const drag = Math.exp(-2.6 * dt);
    this.puffs = this.puffs.filter((q) => {
      q.age += dt;
      const u = q.age / q.life;
      if (u >= 1) { this.root.remove(q.m); (q.m.material as THREE.Material).dispose(); return false; }
      q.m.position.addScaledVector(q.v, dt);
      q.m.position.y += q.r * 0.5 * dt;
      q.v.multiplyScalar(drag);
      q.m.rotation.x += q.spin.x * dt; q.m.rotation.y += q.spin.y * dt; q.m.rotation.z += q.spin.z * dt;
      // snaps out to full size (hiding the swap), then keeps swelling as it thins
      const grow = Math.min(1, q.age / 0.1);
      q.m.scale.setScalar(Math.max(0.001, q.r * (1 - (1 - grow) ** 3) * (1 + 0.8 * u)));
      (q.m.material as THREE.MeshStandardMaterial).opacity = u < 0.3 ? 1 : 1 - ((u - 0.3) / 0.7) ** 1.5;
      return true;
    });
  }
}

const wrap = (a: number) => Math.atan2(Math.sin(a), Math.cos(a));
