import * as THREE from 'three';
import { CHUNK, N, STEP, Biome, RailBit, REGION_KINDS, Under, World, heightAt, idx, inB, type RailPath, type RailEra } from '../world/tiles';
import { REGIONS } from '../world/regions';
import { ROAD_INFO } from '../world/roads';
import { hex, mix, scale, type RGB } from '../world/biomes';
import { Kit, type P3 } from './buildings/kit';
import { isBuiltRail } from '../world/railBuild';
import { BALLAST_DROP, TrackBuf, deckBottom, pathAt, pathNear, trackMaterial, type PathPoint } from './railMesh';
import { twinOffset } from './railTwin';

/**
 * What carries the track and what stands beside it, per chunk: timber trestles, stone arched
 * viaducts, steel through-trusses, the sea viaduct's concrete piers and its navigation span, tunnel
 * portals, level crossings and station signals.
 *
 * Fixed structure goes into one Kit mesh per chunk. The moving and lighting parts — crossing
 * barrier arms, crossing lamps, signal lamps and semaphore arms — are small meshes of their own,
 * registered by key so the train simulation can work them:
 *
 *   Level crossings with barriers, keyed `${w.cx},${w.cz}:${tile}` for every tile of the crossing (tile =
 *   z * 256 + x, a tile with RailBit.Track and a two-lane or four-lane road; see crossingKey):
 *     setCrossingArmed(key, armed, snap?)  arms go down (and the lamps flash) or up; they swing over
 *                                          about 1.5 s while animateRailway(dt) is called each frame,
 *                                          or jump there at once with snap = true.
 *     railCrossings.get(key)                { arms: hinge Object3Ds (rotation.z: 0 down, ARM_UP up), lamps, armed, lowered }
 *   Every crossing has planks and crossbucks; only two-lane and four-lane roads get barriers and lamps,
 *   so only those are registered (setCrossingArmed on any other key just records the state).
 *
 *   Station signals, keyed `${w.cx},${w.cz}:${stationIndex}:${end}` (end 0 beyond s0, 1 beyond s1), each
 *   standing just past the platform ramp on the building side and facing away from the platform, at
 *   the trains coming in:
 *     setSignal(key, 'red' | 'green')      lamps (and a steam line's semaphore arm: level at danger,
 *                                          raised 45° when clear) change at once. Default: green.
 *     railSignals.get(key)                 { aspect, red, green: lamp meshes, arm: hinge or null }
 *
 * State set on a key survives the chunk being dropped and rebuilt. stream.ts calls forgetRailChunk on
 * every dropped chunk so the registries only hold what is on screen.
 */

// ---------------- materials (shared, never per chunk) ----------------

const LAMP_OFF = new THREE.MeshStandardMaterial({ color: 0x2a2624, roughness: 0.5, metalness: 0.1 });
const LAMP_RED = new THREE.MeshStandardMaterial({ color: 0xff4a32, emissive: 0xff2a14, emissiveIntensity: 2.2, roughness: 0.4 });
const LAMP_GREEN = new THREE.MeshStandardMaterial({ color: 0x5dff8a, emissive: 0x20e060, emissiveIntensity: 2.0, roughness: 0.4 });

// ---------------- colours ----------------

const TIMBER = hex(0x5e4630), TIMBER_DARK = hex(0x4a3726), STONE = hex(0xa89e8a), STONE_DARK = hex(0x8a8170);
const CONCRETE = hex(0xc4bfb5), CONCRETE_DARK = hex(0xa39e94);
const TRUSS: Record<RailEra, RGB> = { steam: hex(0x4d5f55), streamline: hex(0x8e4332), modern: hex(0x9aa3ab) };
const WHITE = hex(0xf2efe6), POST = hex(0x3a3f45), PLANK = hex(0x7a5c3e), ASPHALT = hex(0x5b5f64), DIRT = hex(0xb08658), BRICK = hex(0xa8604a);
const ARM_RED = hex(0xd23a2a), SEM_RED = hex(0xc8302a), SIGNAL_HEAD = hex(0x26292d), VOID = hex(0x141210);

/** Rotation (about the hinge's z) of a barrier arm standing up. */
const ARM_UP = 1.42;
const ARM_SWING = 1.5; // seconds from up to down

// ---------------- registries ----------------

interface CrossingParts { arms: THREE.Object3D[]; lamps: THREE.Mesh[]; armed: boolean; lowered: number; owner?: object }
interface SignalParts { aspect: 'red' | 'green'; red: THREE.Mesh; green: THREE.Mesh; arm: THREE.Object3D | null; owner?: object }

const railCrossings = new Map<string, CrossingParts>();
const railSignals = new Map<string, SignalParts>();
const crossingState = new Map<string, { armed: boolean; lowered: number }>();
const signalState = new Map<string, 'red' | 'green'>();
const moving = new Set<string>();
let flashClock = 0;

const crossingKey = (w: World, tile: number): string => `${w.cx},${w.cz}:${tile}`;
const signalKey = (w: World, station: number, end: 0 | 1): string => `${w.cx},${w.cz}:${station}:${end}`;

function poseCrossing(c: CrossingParts): void {
  for (const a of c.arms) a.rotation.z = ARM_UP * (1 - c.lowered);
  const on = c.armed || c.lowered > 0.02;
  const phase = Math.floor(flashClock * 2.2) % 2;
  c.lamps.forEach((m, k) => { m.material = on && k % 2 === phase ? LAMP_RED : LAMP_OFF; });
}

/** Lower (armed) or raise a crossing's barriers and set its lamps flashing. */
export function setCrossingArmed(key: string, armed: boolean, snap = false): void {
  const c = railCrossings.get(key);
  const st = crossingState.get(key) ?? { armed: false, lowered: 0 };
  st.armed = armed;
  if (snap) st.lowered = armed ? 1 : 0;
  crossingState.set(key, st);
  if (c) {
    c.armed = armed;
    if (snap) c.lowered = st.lowered;
    poseCrossing(c);
  }
  moving.add(key);
}

/** Swing barrier arms toward where they are wanted and flash the lamps of armed crossings. */
export function animateRailway(dt: number): void {
  flashClock += dt;
  for (const key of moving) {
    const st = crossingState.get(key);
    if (!st) { moving.delete(key); continue; }
    const target = st.armed ? 1 : 0;
    const stepped = Math.abs(target - st.lowered) <= dt / ARM_SWING ? target : st.lowered + Math.sign(target - st.lowered) * (dt / ARM_SWING);
    st.lowered = stepped;
    const c = railCrossings.get(key);
    if (c) { c.lowered = stepped; c.armed = st.armed; poseCrossing(c); }
    if (!st.armed && stepped === 0) moving.delete(key);
  }
}

/** Show a station signal at danger or clear. */
export function setSignal(key: string, aspect: 'red' | 'green'): void {
  signalState.set(key, aspect);
  const s = railSignals.get(key);
  if (s) poseSignal(s, aspect);
}

function poseSignal(s: SignalParts, aspect: 'red' | 'green'): void {
  s.aspect = aspect;
  s.red.material = aspect === 'red' ? LAMP_RED : LAMP_OFF;
  s.green.material = aspect === 'green' ? LAMP_GREEN : LAMP_OFF;
  if (s.arm) s.arm.rotation.z = aspect === 'red' ? 0 : 0.75;
}

/** Drop a chunk's crossings and signals from the registries (their state is kept for a rebuild). */
export function forgetRailChunk(o: THREE.Object3D): void {
  const keys = o.userData.railKeys as { crossings: string[]; signals: string[]; owner: object } | undefined;
  if (!keys) return;
  for (const k of keys.crossings) if (railCrossings.get(k)?.owner === keys.owner) railCrossings.delete(k);
  for (const k of keys.signals) if (railSignals.get(k)?.owner === keys.owner) railSignals.delete(k);
}

// ---------------- helpers ----------------

/** A four-sided bar from a to b with no end caps: truss members and braces. */
function bar(k: Kit, a: P3, b: P3, r: number, col: RGB): void {
  const dx = b[0] - a[0], dy = b[1] - a[1], dz = b[2] - a[2];
  const len = Math.hypot(dx, dy, dz);
  if (len < 1e-5) return;
  const ux = dx / len, uy = dy / len, uz = dz / len;
  let px = -uz, py = 0, pz = ux;
  let pl = Math.hypot(px, py, pz);
  if (pl < 1e-4) { px = 1; py = 0; pz = 0; pl = 1; }
  px /= pl; py /= pl; pz /= pl;
  const qx = uy * pz - uz * py, qy = uz * px - ux * pz, qz = ux * py - uy * px;
  const c = (t: number, s1: number, s2: number): P3 => [a[0] + dx * t + (px * s1 + qx * s2) * r, a[1] + dy * t + (py * s1 + qy * s2) * r, a[2] + dz * t + (pz * s1 + qz * s2) * r];
  const mid: P3 = [a[0] + dx / 2, a[1] + dy / 2, a[2] + dz / 2];
  const v = [c(0, -1, -1), c(0, 1, -1), c(0, 1, 1), c(0, -1, 1), c(1, -1, -1), c(1, 1, -1), c(1, 1, 1), c(1, -1, 1)];
  k.quad(v[0], v[1], v[5], v[4], col, mid);
  k.quad(v[1], v[2], v[6], v[5], col, mid);
  k.quad(v[2], v[3], v[7], v[6], col, mid);
  k.quad(v[3], v[0], v[4], v[7], col, mid);
}

/** A point `o` to the left of the path at q (along the normal (-tz, tx)), at height y. */
const off = (q: PathPoint, o: number, y: number): P3 => [q.x - q.tz * o, y, q.z + q.tx * o];

/** Runs of samples [i0, i1] carried by one kind of structure. */
function runsOf(p: RailPath, u: Under): [number, number][] {
  const out: [number, number][] = [];
  const n = p.s.length;
  let i = 0;
  while (i < n) {
    if (p.under[i] !== u) { i++; continue; }
    let j = i;
    while (j + 1 < n && p.under[j + 1] === u) j++;
    out.push([i, j]);
    i = j + 1;
  }
  return out;
}

/** The rock a portal is cut from: the biome's own where it has one, else the ground's. */
function rockOf(w: World, x: number, z: number): RGB {
  const tx = Math.min(N - 1, Math.max(0, Math.floor(x))), tz = Math.min(N - 1, Math.max(0, Math.floor(z)));
  const i = idx(tx, tz);
  const k = w.regionK[i];
  if (k && w.regionW[i] > 120) {
    const pal = REGIONS[REGION_KINDS[k - 1]].palette;
    const base = pal.mountainLow ?? pal.cliffPaleBot;
    if (base !== undefined) return mix(hex(base), STONE, 0.45);
  }
  switch (w.biome[i]) {
    case Biome.Desert: case Biome.Canyon: return hex(0xc39a70);
    case Biome.Mountain: case Biome.Snow: case Biome.Ice: return hex(0x8f8b85);
    case Biome.Lava: return hex(0x5a5550);
    case Biome.Forest: case Biome.Hills: return hex(0x9a9282);
    default: return STONE;
  }
}

// ---------------- the chunk ----------------

export function buildRailBridgeChunk(w: World, cx: number, cz: number): THREE.Object3D | null {
  if (!w.rails.length) return null;
  const x0 = cx * CHUNK, z0 = cz * CHUNK;
  const inChunk = (x: number, z: number) => x >= x0 && x < x0 + CHUNK && z >= z0 && z < z0 + CHUNK;
  const k = new Kit(w);
  k.place(0, 0, 0, 0);
  const extras: THREE.Object3D[] = [];
  const owner = {};
  const keys = { crossings: [] as string[], signals: [] as string[], owner };

  for (const p of w.rails) {
    if (p.s.length < 2 || !pathNear(p, x0, z0, x0 + CHUNK, z0 + CHUNK, 8)) continue;
    for (const [i0, i1] of runsOf(p, Under.Trestle)) trestle(k, w, p, i0, i1, inChunk);
    for (const [i0, i1] of runsOf(p, Under.Viaduct)) viaduct(k, w, p, i0, i1, inChunk);
    for (const [i0, i1] of runsOf(p, Under.Truss)) {
      bankPiers(k, w, p, i0, i1, Under.Truss, inChunk);
      const L = p.s[i1] - p.s[i0];
      if (L >= 3) truss(k, p, p.s[i0], p.s[i1], Under.Truss, inChunk);
      else girders(k, p, i0, i1, inChunk);
    }
    for (const [i0, i1] of runsOf(p, Under.Sea)) sea(k, w, p, i0, i1, inChunk);
    portals(k, w, p, inChunk);
  }
  crossings(k, w, inChunk, extras, keys);
  signals(k, w, inChunk, extras, keys);

  const solid = k.meshes();
  if (!solid && !extras.length) return null;
  const g = new THREE.Group();
  if (solid) g.add(solid);
  if (extras.length) g.add(...extras);
  g.userData.railKeys = keys;
  return g;
}

// ---------------- trestles ----------------

/** Timber bents every tile: two splayed legs, a cap, a cross brace, and a second tier when tall. */
function trestle(k: Kit, w: World, p: RailPath, i0: number, i1: number, inChunk: (x: number, z: number) => boolean): void {
  const sa = p.s[i0], sb = p.s[i1];
  for (let s = Math.ceil(sa - 0.5) + 0.5; s <= sb; s += 1) {
    if (s < sa) continue;
    const q = pathAt(p, s);
    if (!inChunk(q.x, q.z)) continue;
    const top = deckBottom(Under.Trestle, q.y);
    const g = heightAt(w, q.x, q.z);
    const H = top - g;
    if (H < 0.08) continue;
    const spread = 0.2 + Math.min(0.25, H * 0.12);
    const feet: P3[] = [];
    for (const side of [-1, 1]) {
      const f = off(q, side * spread, 0);
      f[1] = heightAt(w, f[0], f[2]) - 0.05;
      feet.push(f);
      bar(k, off(q, side * 0.19, top), f, 0.028, TIMBER);
    }
    bar(k, off(q, -0.3, top - 0.03), off(q, 0.3, top - 0.03), 0.035, TIMBER_DARK);
    if (H > 0.35) {
      const lerp = (t: number, side: number): P3 => {
        const f = feet[side < 0 ? 0 : 1], o = side * (0.19 + (spread - 0.19) * t);
        return off(q, o, top + (f[1] - top) * t);
      };
      bar(k, lerp(0.05, -1), lerp(0.85, 1), 0.018, TIMBER_DARK);
      if (H > 1.0) {
        bar(k, lerp(0.5, -1), lerp(0.5, 1), 0.022, TIMBER_DARK);
        bar(k, lerp(0.5, 1), lerp(0.95, -1), 0.018, TIMBER_DARK);
      }
    }
  }
}

// ---------------- stone viaducts ----------------

const VIA_HALF = 0.31;

/**
 * What a viaduct is built of, by the line's era (the user, 11 Nov 2026: rail bridges to look better and more real):
 * a steam line's of the country's own stone, a streamline railway's of brick dressed in stone, a modern line's of
 * concrete poured in lifts. Every face is laid in courses at fixed heights, so they run on level from pier to arch,
 * and each course in blocks, every other course half a block on, each block a shade of the wall's own.
 */
interface Masonry { wall: RGB; dress: RGB; dark: RGB; course: number; block: number; tone: number; seed: number }

function masonryOf(w: World, p: RailPath, q: PathPoint): Masonry {
  const stone = mix(rockOf(w, q.x, q.z), STONE, 0.5), seed = p.id * 7919 + 13;
  if (p.era === 'streamline') return { wall: BRICK, dress: scale(stone, 1.16), dark: scale(BRICK, 0.72), course: 0.11, block: 0.36, tone: 0.09, seed };
  if (p.era === 'modern') return { wall: CONCRETE, dress: scale(CONCRETE, 1.06), dark: CONCRETE_DARK, course: 0.36, block: 2, tone: 0.025, seed };
  return { wall: stone, dress: scale(stone, 1.12), dark: scale(stone, 0.74), course: 0.14, block: 0.42, tone: 0.075, seed };
}

/** A shade of the wall for the block (c, j): a fixed hash of the two, so a chunk rebuilt looks the same. */
function blockShade(m: Masonry, c: number, j: number): RGB {
  let h = Math.imul(c * 374761393 + j * 668265263 + m.seed, 1274126177) | 0;
  h = Math.imul(h ^ (h >>> 15), 2246822519);
  const r = ((h ^ (h >>> 13)) >>> 0) / 4294967296;
  return scale(m.wall, 1 + (r - 0.5) * 2 * m.tone);
}

const lerp3 = (a: P3, b: P3, t: number): P3 => [a[0] + (b[0] - a[0]) * t, a[1] + (b[1] - a[1]) * t, a[2] + (b[2] - a[2]) * t];

/**
 * A planar wall face laid in courses: a0, b0 its foot and a1, b1 over them (a0→a1 and b0→b1 run up its two edges).
 * `u0` is how far along the structure a0 stands, so the joints of faces side by side carry on from one to the next.
 */
function coursed(k: Kit, m: Masonry, a0: P3, b0: P3, a1: P3, b1: P3, u0: number, inside: P3): void {
  const len = Math.hypot(b0[0] - a0[0], b0[2] - a0[2]);
  const lo = Math.min(a0[1], b0[1]), hi = Math.max(a1[1], b1[1]);
  if (hi - lo < 1e-3) return;
  // the point up an edge at height y, held to the edge's ends
  const up = (e0: P3, e1: P3, y: number): P3 => {
    const h = e1[1] - e0[1];
    return lerp3(e0, e1, h > 1e-6 ? Math.min(1, Math.max(0, (y - e0[1]) / h)) : 0);
  };
  const C = m.course, B = m.block, ub = u0 + len;
  for (let c = Math.floor(lo / C); c * C < hi; c++) {
    const A0 = up(a0, a1, c * C), A1 = up(a0, a1, (c + 1) * C), B0 = up(b0, b1, c * C), B1 = up(b0, b1, (c + 1) * C);
    if (A1[1] - A0[1] < 1e-4 && B1[1] - B0[1] < 1e-4) continue;
    const half = (c & 1) * 0.5;
    for (let j = Math.floor(u0 / B - half); (j + half) * B < ub; j++) {
      const s0 = Math.max(u0, (j + half) * B), s1 = Math.min(ub, (j + 1 + half) * B);
      if (s1 - s0 < 1e-4) continue;
      const t0 = len > 1e-6 ? (s0 - u0) / len : 0, t1 = len > 1e-6 ? (s1 - u0) / len : 1;
      k.quad(lerp3(A0, B0, t0), lerp3(A0, B0, t1), lerp3(A1, B1, t1), lerp3(A1, B1, t0), blockShade(m, c, j), inside);
    }
  }
}

/** A point `along` the path's tangent from q and `o` to its left, at height y. */
const at = (q: PathPoint, along: number, o: number, y: number): P3 => [q.x + q.tx * along - q.tz * o, y, q.z + q.tz * along + q.tx * o];

/**
 * The edges of a viaduct's masonry at q, left (+) and right (-) of the track: VIA_HALF either side, but out to the
 * line between the two where a twin track's viaduct stands beside it, so the pair is one bridge (render/railTwin.ts).
 */
function viaEdges(w: World, p: RailPath, q: PathPoint, u: Under): { l: number; r: number; tw: number } {
  const t = twinOffset(w, p, u, q.x, q.y, q.z, q.tx, q.tz);
  return { l: t > 0 ? t / 2 + 0.03 : VIA_HALF, r: t < 0 ? t / 2 - 0.03 : -VIA_HALF, tw: Math.sign(t) };
}

/**
 * Piers every two tiles and a round arch between each pair, with low parapets along the top over a deep cornice. The
 * arches are ringed in dressed voussoirs, the piers stand on a plinth with an impost band where the arches spring,
 * and a pier standing in water has a pointed cutwater either side. Where the deck is too low for an arch, the wall
 * runs down solid into the ground, so there is never a slot of sky under it.
 */
function viaduct(k: Kit, w: World, p: RailPath, i0: number, i1: number, inChunk: (x: number, z: number) => boolean): void {
  const sa = p.s[i0], sb = p.s[i1];
  const stops = [sa];
  for (let s = Math.ceil((sa + 0.6) / 2) * 2; s < sb - 0.6; s += 2) stops.push(s);
  stops.push(sb);
  const db = (q: PathPoint) => deckBottom(Under.Viaduct, q.y);
  const m = masonryOf(w, p, pathAt(p, (sa + sb) / 2));
  // each arch's springing line, for the imposts of the piers either side (-Infinity where the wall runs solid)
  const springs: number[] = [];
  const PIER = 0.18, END = 0.15;

  // arches (and solid walls)
  for (let j = 0; j + 1 < stops.length; j++) {
    const pa = stops[j] + (j === 0 ? END : PIER), pb = stops[j + 1] - (j + 2 === stops.length ? END : PIER);
    const span = pb - pa;
    springs.push(-Infinity);
    if (span < 0.05) continue;
    const mid = pathAt(p, (pa + pb) / 2);
    const e = viaEdges(w, p, mid, Under.Viaduct);
    const ground = (q: PathPoint) => Math.min(heightAt(w, ...xz(off(q, e.l, 0))), heightAt(w, ...xz(off(q, e.r, 0))));
    let g = Infinity, dbMin = Infinity;
    for (let t = 0; t <= 4; t++) {
      const q = pathAt(p, pa + (span * t) / 4);
      g = Math.min(g, ground(q));
      dbMin = Math.min(dbMin, db(q));
    }
    const H = dbMin - g;
    const arched = H >= 0.25 && span >= 0.5;
    const half = span / 2, rise = Math.min(half, H * 0.7);
    const spring = dbMin - 0.07 - rise;
    if (arched) springs[j] = spring;
    if (!inChunk(mid.x, mid.z)) continue;
    const SEG = arched ? 6 : Math.max(1, Math.ceil(span / 0.6));
    // the arch's curve at s, or the ground (a little under it) where the wall runs solid
    const curve = (s: number, q: PathPoint): number => {
      if (!arched) return ground(q) - 0.1;
      const u = (s - (pa + half)) / half;
      return spring + rise * Math.sqrt(Math.max(0, 1 - u * u));
    };
    let prev: { s: number; q: PathPoint; a: number; d: number } | null = null;
    for (let t = 0; t <= SEG; t++) {
      const s = pa + (span * t) / SEG;
      const q = pathAt(p, s);
      const a = curve(s, q), d = db(q);
      if (prev) {
        const inside = off(q, (e.l + e.r) / 2, (a + d) / 2);
        // the spandrel walls, on the outer sides only: a twin's side is inside the bridge
        for (const [o, side] of [[e.l, 1], [e.r, -1]] as const) {
          if (side === e.tw) continue;
          coursed(k, m, off(prev.q, o, prev.a), off(q, o, a), off(prev.q, o, prev.d), off(q, o, d), prev.s, inside);
        }
        if (arched) {
          const I: P3 = [(q.x + prev.q.x) / 2, (a + d) / 2 + 10, (q.z + prev.q.z) / 2];
          k.quad(off(prev.q, e.l, prev.a), off(q, e.l, a), off(q, e.r, a), off(prev.q, e.r, prev.a), m.dark, I);
          // the arch ring: voussoirs a little proud of the face, round the curve, alternately shaded
          const RW = m.course > 0.2 ? 0.06 : 0.075;
          const ring = (ss: number, aa: number): [number, number] => {
            const uu = (ss - (pa + half)) / half, vv = (aa - spring) / Math.max(rise, 1e-3);
            const nx = uu / half, ny = vv / Math.max(rise, 1e-3), nl = Math.hypot(nx, ny) || 1;
            return [ss + (nx / nl) * RW, aa + (ny / nl) * RW];
          };
          const [s0o, a0o] = ring(prev.s, prev.a), [s1o, a1o] = ring(s, a);
          const q0o = pathAt(p, s0o), q1o = pathAt(p, s1o);
          const col = t & 1 ? m.dress : scale(m.dress, 0.9);
          for (const [o, side] of [[e.l, 1], [e.r, -1]] as const) {
            if (side === e.tw) continue;
            const oo = o + side * 0.012;
            k.quad(off(prev.q, oo, prev.a), off(q, oo, a), off(q1o, oo, a1o), off(q0o, oo, a0o), col, off(q, o - side * 0.1, (a + a1o) / 2));
            // its soffit edge, so the ring reads as a band and not a stripe painted on
            k.quad(off(prev.q, o, prev.a), off(q, o, a), off(q, oo, a), off(prev.q, oo, prev.a), scale(col, 0.8), [(q.x + prev.q.x) / 2, a + 5, (q.z + prev.q.z) / 2]);
          }
        }
      }
      prev = { s, q, a, d };
    }
  }

  // piers (and an abutment at either end)
  for (let j = 0; j < stops.length; j++) {
    const q = pathAt(p, stops[j]);
    if (!inChunk(q.x, q.z)) continue;
    const end = j === 0 || j === stops.length - 1;
    const e = viaEdges(w, p, q, Under.Viaduct);
    const top = db(q);
    let g = Infinity;
    for (const o of [e.l, e.r]) { const f = off(q, o, 0); g = Math.min(g, heightAt(w, f[0], f[2])); }
    if (top - g < 0.05) continue;
    const H = top - g, foot = g - 0.15;
    // a pier batters out toward its foot on its outer sides
    const bat = end ? 0 : Math.min(0.1, H * 0.025);
    const L1 = e.l, R1 = e.r, L0 = e.tw > 0 ? e.l : e.l + bat, R0 = e.tw < 0 ? e.r : e.r - bat;
    const al1 = end ? END : PIER, al0 = -al1;
    const inside = at(q, 0, (L1 + R1) / 2, (foot + top) / 2);
    // the outer faces, coursed on with the spandrels'; and the faces looking along the line, into the arches
    for (const [o0, o1, side] of [[L0, L1, 1], [R0, R1, -1]] as const) {
      if (side === e.tw) continue;
      coursed(k, m, at(q, al0, o0, foot), at(q, al1, o0, foot), at(q, al0, o1, top), at(q, al1, o1, top), stops[j] + al0, inside);
    }
    // an abutment's back runs up to the deck's top, closing the end of the bridge where two banks part
    const back = j === 0 ? al0 : al1, deckTop = q.y - BALLAST_DROP;
    // (looking along the line a pier's faces are mostly behind the arches either side: one plain face each will do)
    for (const al of [al0, al1]) {
      const hi = end && al === back ? deckTop : top;
      if (end && al === back) coursed(k, m, at(q, al, R0, foot), at(q, al, L0, foot), at(q, al, R1, hi), at(q, al, L1, hi), 0, inside);
      else k.quad(at(q, al, R0, foot), at(q, al, L0, foot), at(q, al, L1, hi), at(q, al, R1, hi), m.wall, inside);
    }
    if (end) continue;
    // a plinth round its foot, and an impost band where the arches either side spring
    k.place(q.x, 0, q.z, Math.atan2(q.tx, q.tz));
    // (local x runs to the track's right, so a left offset o stands at x = -o; nothing stands out past a twin's middle)
    const band = (lo: number, ro: number, y: number, h: number, grow: number, along: number, col: RGB, top2: RGB) => {
      const l = e.tw > 0 ? lo : lo + grow, r = e.tw < 0 ? ro : ro - grow;
      k.box(-(l + r) / 2, y, 0, l - r, h, along, col, top2);
    };
    if (H > 0.6) band(L0, R0, foot, 0.3, 0.04, al1 - al0 + 0.08, m.dark, m.dress);
    const sp = Math.max(springs[j - 1] ?? -Infinity, springs[j] ?? -Infinity);
    if (Number.isFinite(sp) && sp > g + 0.3) band(L1, R1, sp - 0.05, 0.05, bat * (top - sp) / H + 0.015, al1 - al0 + 0.03, m.dress, m.dress);
    k.place(0, 0, 0, 0);
    // a cutwater either side where it stands in water: a pointed nose to the stream, capped with a sloping head
    const tx = Math.min(N - 1, Math.max(0, Math.floor(q.x))), tz = Math.min(N - 1, Math.max(0, Math.floor(q.z)));
    const wl = w.water[idx(tx, tz)];
    if (wl < 0) continue;
    const wy = wl * STEP;
    if (wy < g + 0.05) continue;
    const capY = Math.min(top - 0.3, wy + 0.3);
    if (capY < foot + 0.1) continue;
    for (const [o, side] of [[L0, 1], [R0, -1]] as const) {
      if (side === e.tw) continue;
      const nose = o + side * 0.2;
      const A0 = at(q, al0, o, foot), B0 = at(q, al1, o, foot), N0 = at(q, 0, nose, foot);
      const A1 = at(q, al0, o, capY), B1 = at(q, al1, o, capY), N1 = at(q, 0, nose, capY);
      const In = at(q, 0, o - side * 0.05, (foot + capY) / 2);
      coursed(k, m, A0, N0, A1, N1, 0, In);
      coursed(k, m, N0, B0, N1, B1, 0.5, In);
      // the head slopes up from the nose to the face of the pier
      const T: P3 = at(q, 0, o, capY + 0.18);
      k.tri(A1, N1, T, m.dress, In);
      k.tri(N1, B1, T, m.dress, In);
    }
  }
  cornice(k, w, p, i0, i1, m, inChunk);
  parapets(k, w, p, Under.Viaduct, i0, i1, 0.35, 0.09, m.dress, inChunk);
}

const xz = (q: P3): [number, number] => [q[0], q[2]];

/**
 * A deep cornice along a viaduct's outer sides, from the foot of the deck slab to the parapet, standing a little
 * proud of the walls: it hides the slab's own edge and gives the top of the bridge a line.
 */
function cornice(k: Kit, w: World, p: RailPath, i0: number, i1: number, m: Masonry, inChunk: (x: number, z: number) => boolean): void {
  const OUT = 0.39;
  for (let a = i0; a < i1; a += 4) {
    const b = Math.min(i1, a + 4);
    const A = pathAt(p, p.s[a]), B = pathAt(p, p.s[b]);
    if (!inChunk((A.x + B.x) / 2, (A.z + B.z) / 2)) continue;
    const tw = viaEdges(w, p, pathAt(p, (p.s[a] + p.s[b]) / 2), Under.Viaduct).tw;
    const lo = (q: PathPoint) => deckBottom(Under.Viaduct, q.y) - 0.04, hi = (q: PathPoint) => q.y - BALLAST_DROP - 0.03;
    for (const side of [-1, 1]) {
      if (side === tw) continue;
      const o = side * OUT, wall = side * VIA_HALF;
      const In: P3 = [(A.x + B.x) / 2, (lo(A) + hi(A)) / 2, (A.z + B.z) / 2];
      k.quad(off(A, o, lo(A)), off(B, o, lo(B)), off(B, o, hi(B)), off(A, o, hi(A)), m.dress, In);
      k.quad(off(A, wall, lo(A)), off(B, wall, lo(B)), off(B, o, lo(B)), off(A, o, lo(A)), scale(m.dress, 0.7), [In[0], lo(A) + 5, In[2]]);
      k.quad(off(A, side * 0.34, hi(A)), off(B, side * 0.34, hi(B)), off(B, o, hi(B)), off(A, o, hi(A)), m.dress, [In[0], hi(A) - 5, In[2]]);
    }
  }
}

/** Low walls along both edges of a deck, a tile at a time (only the outer one where a twin's deck is alongside). */
function parapets(k: Kit, w: World, p: RailPath, u: Under, i0: number, i1: number, half: number, h: number, col: RGB, inChunk: (x: number, z: number) => boolean): void {
  const T = 0.035;
  for (let a = i0; a < i1; a += 4) {
    const b = Math.min(i1, a + 4);
    const A = pathAt(p, p.s[a]), B = pathAt(p, p.s[b]);
    if (!inChunk((A.x + B.x) / 2, (A.z + B.z) / 2)) continue;
    const M = pathAt(p, (p.s[a] + p.s[b]) / 2);
    const tw = Math.sign(twinOffset(w, p, u, M.x, M.y, M.z, M.tx, M.tz));
    const ya = A.y - BALLAST_DROP, yb = B.y - BALLAST_DROP;
    for (const side of [-1, 1]) {
      if (side === tw) continue;
      const oi = side * (half - T), oo = side * half;
      const I: P3 = off(A, side * (half - T / 2), ya);
      const Ii: P3 = [I[0], ya + h / 2, I[2]];
      k.quad(off(A, oo, ya - 0.03), off(B, oo, yb - 0.03), off(B, oo, yb + h), off(A, oo, ya + h), col, [(A.x + B.x) / 2, ya + h / 2, (A.z + B.z) / 2]);
      k.quad(off(A, oi, ya), off(B, oi, yb), off(B, oi, yb + h), off(A, oi, ya + h), scale(col, 0.9), off(A, side * (half + 0.5), ya + h / 2));
      k.quad(off(A, oi, ya + h), off(B, oi, yb + h), off(B, oo, yb + h), off(A, oo, ya + h), scale(col, 1.08), [Ii[0], ya - 1, Ii[2]]);
    }
  }
}

// ---------------- steel ----------------

/** Concrete piers on the banks at either end of a span. */
function bankPiers(k: Kit, w: World, p: RailPath, i0: number, i1: number, u: Under, inChunk: (x: number, z: number) => boolean): void {
  for (const s of [p.s[i0], p.s[i1]]) {
    const q = pathAt(p, s);
    if (!inChunk(q.x, q.z)) continue;
    const top = deckBottom(u, q.y);
    const g = Math.min(heightAt(w, q.x, q.z), top - 0.1);
    k.place(q.x, 0, q.z, Math.atan2(q.tx, q.tz));
    k.box(0, g - 0.4, 0, 0.66, top - g + 0.4, 0.3, CONCRETE, CONCRETE);
    k.place(0, 0, 0, 0);
  }
  // a span over 12 tiles gets piers in between as well
  const L = p.s[i1] - p.s[i0];
  if (L > 12) {
    const n = Math.ceil(L / 10);
    for (let j = 1; j < n; j++) {
      const q = pathAt(p, p.s[i0] + (L * j) / n);
      if (!inChunk(q.x, q.z)) continue;
      const top = deckBottom(u, q.y), g = heightAt(w, q.x, q.z) - 0.3;
      k.place(q.x, 0, q.z, Math.atan2(q.tx, q.tz));
      for (const side of [-1, 1]) k.cyl(side * 0.2, g, 0, 0.1, top - g, CONCRETE_DARK, 6);
      k.box(0, top - 0.1, 0, 0.66, 0.1, 0.2, CONCRETE);
      k.place(0, 0, 0, 0);
    }
  }
}

const TRUSS_HALF = 0.33, TRUSS_H = 0.62;

/** A through truss over [sa, sb]: sloping end posts, verticals, diagonals and top bracing, a panel a tile. */
function truss(k: Kit, p: RailPath, sa: number, sb: number, u: Under, inChunk: (x: number, z: number) => boolean): void {
  const L = sb - sa;
  const nP = Math.max(2, Math.round(L));
  const col = TRUSS[p.era], dark = scale(col, 0.8);
  const node = (j: number) => pathAt(p, sa + (L * j) / nP);
  for (let j = 0; j < nP; j++) {
    const A = node(j), B = node(j + 1);
    const M = pathAt(p, sa + (L * (j + 0.5)) / nP);
    if (!inChunk(M.x, M.z)) continue;
    const lowA = deckBottom(u, A.y) + 0.02, lowB = deckBottom(u, B.y) + 0.02;
    const highA = j === 0 ? lowA : A.y + TRUSS_H, highB = j + 1 === nP ? lowB : B.y + TRUSS_H;
    for (const side of [-1, 1]) {
      const o = side * TRUSS_HALF;
      bar(k, off(A, o, highA), off(B, o, highB), 0.03, col);          // top chord (the end posts at either end)
      bar(k, off(A, o, lowA), off(B, o, lowB), 0.028, dark);           // bottom chord
      if (j > 0) bar(k, off(A, o, lowA), off(A, o, highA), 0.018, col); // vertical
      if (j > 0 && j + 1 < nP) {
        // diagonals lean toward the middle of the span
        if (j < nP / 2) bar(k, off(A, o, highA), off(B, o, lowB), 0.014, dark);
        else bar(k, off(A, o, lowA), off(B, o, highB), 0.014, dark);
      }
    }
    if (j > 0) bar(k, off(A, -TRUSS_HALF, highA - 0.02), off(A, TRUSS_HALF, highA - 0.02), 0.016, dark);
  }
}

/** A short span: deep plate girders either side of the deck. */
function girders(k: Kit, p: RailPath, i0: number, i1: number, inChunk: (x: number, z: number) => boolean): void {
  const col = TRUSS[p.era];
  for (let a = i0; a < i1; a += 2) {
    const b = Math.min(i1, a + 2);
    const A = pathAt(p, p.s[a]), B = pathAt(p, p.s[b]);
    if (!inChunk((A.x + B.x) / 2, (A.z + B.z) / 2)) continue;
    for (const side of [-1, 1]) {
      const o = side * 0.31;
      const la = deckBottom(Under.Truss, A.y) - 0.04, lb = deckBottom(Under.Truss, B.y) - 0.04;
      const ha = A.y + 0.1, hb = B.y + 0.1;
      k.quad(off(A, o, la), off(B, o, lb), off(B, o, hb), off(A, o, ha), col, off(A, side * 1, (la + ha) / 2));
      k.quad(off(A, o + side * 0.03, la), off(B, o + side * 0.03, lb), off(B, o + side * 0.03, hb), off(A, o + side * 0.03, ha), scale(col, 0.85), off(A, 0, (la + ha) / 2));
      k.quad(off(A, o, ha), off(B, o, hb), off(B, o + side * 0.03, hb), off(A, o + side * 0.03, ha), scale(col, 1.1), off(A, o, ha - 1));
    }
  }
}

// ---------------- the sea viaduct ----------------

function sea(k: Kit, w: World, p: RailPath, i0: number, i1: number, inChunk: (x: number, z: number) => boolean): void {
  // the navigation span stands in the middle of every sea crossing long enough to want one
  const long = p.s[i1] - p.s[i0] >= 30;
  const L2 = long ? (p.s[i0] + p.s[i1]) / 2 : -1e9;
  // piers every three tiles, clear of the navigation span
  let last = -Infinity;
  for (let i = i0; i <= i1; i++) {
    if (Math.round(p.s[i] / 0.25) % 12 !== 0 || Math.abs(p.s[i] - L2) <= 6 || p.s[i] - last < 1.5) continue;
    last = p.s[i];
    const q = pathAt(p, p.s[i]);
    if (!inChunk(q.x, q.z)) continue;
    seaPier(k, w, p, q);
  }
  // the navigation span: a through truss, with a pier at each end
  const na = Math.max(p.s[i0], L2 - 6), nb = Math.min(p.s[i1], L2 + 6);
  if (nb - na >= 6 && p.s[i0] < L2 && p.s[i1] > L2) {
    truss(k, p, na, nb, Under.Sea, inChunk);
    for (const s of [na, nb]) {
      const q = pathAt(p, s);
      if (inChunk(q.x, q.z)) seaPier(k, w, p, q);
    }
  }
  parapets(k, w, p, Under.Sea, i0, i1, 0.31, 0.06, CONCRETE_DARK, inChunk);
}

/** A sea pier: two columns under a cap; beside a twin track's deck the cap runs out to meet the twin's (render/railTwin.ts). */
function seaPier(k: Kit, w: World, p: RailPath, q: PathPoint): void {
  const top = deckBottom(Under.Sea, q.y), g = Math.min(heightAt(w, q.x, q.z), top - 0.5) - 0.2;
  const t = twinOffset(w, p, Under.Sea, q.x, q.y, q.z, q.tx, q.tz);
  const l = t > 0 ? t / 2 + 0.03 : 0.31, r = t < 0 ? t / 2 - 0.03 : -0.31;
  k.place(q.x, 0, q.z, Math.atan2(q.tx, q.tz));
  for (const side of [-1, 1]) k.cyl(side * 0.17, g, 0, 0.075, top - g, CONCRETE, 6);
  k.box(-(l + r) / 2, top - 0.09, 0, l - r, 0.09, 0.16, CONCRETE_DARK, CONCRETE);
  k.place(0, 0, 0, 0);
}

// ---------------- tunnel portals ----------------

function portals(k: Kit, w: World, p: RailPath, inChunk: (x: number, z: number) => boolean): void {
  const n = p.s.length;
  // The generator cuts a cutting up to its tunnel's mouth, so the hill stands well over the rails where the bore
  // begins. Track the player laid cuts nothing: its bore runs in under a hillside still rising, so its face stands
  // where the ground first covers the rails, and a stone hood runs back from it to where the hill is over a train.
  const built = isBuiltRail(p), over = built ? 0.3 : 0.55;
  for (let i = 0; i + 1 < n; i++) {
    const a = p.under[i] === Under.Tunnel, b = p.under[i + 1] === Under.Tunnel;
    if (a === b) continue;
    // `dir` points into the hill
    const dir = b ? 1 : -1;
    const sB = b ? p.s[i + 1] : p.s[i];
    // the face stands where the ground first rises well over the rails
    let s = sB;
    for (let d = 0; d <= 3; d += 0.125) {
      const ss = sB + dir * d;
      if (ss < 0 || ss > p.length) break;
      const q = pathAt(p, ss);
      if (heightAt(w, q.x, q.z) >= q.y + over) { s = ss - dir * 0.05; break; }
    }
    const q = pathAt(p, s);
    if (!inChunk(q.x, q.z)) continue;
    portal(k, w, q, -dir, p.era);
    if (!built) continue;
    const col = rockOf(w, q.x, q.z), light = scale(col, 1.12);
    for (let d = 0.12; d <= 5; d += 0.25) {
      const ss = s + dir * d;
      if (ss < 0 || ss > p.length) break;
      const h = pathAt(p, ss);
      if (heightAt(w, h.x, h.z) >= h.y + 1.05) break;
      k.place(h.x, h.y, h.z, Math.atan2(h.tx, h.tz));
      k.box(0, 0.88, 0, 1.0, 0.1, 0.27, col, light);
      for (const sx of [-1, 1]) k.box(sx * 0.44, -0.35, 0, 0.12, 1.23, 0.27, col, light);
    }
    k.place(0, 0, 0, 0);
  }
}

/**
 * A tunnel portal facing along the path's tangent × `out`, in the manner of the line's era (11 Nov 2026, the user: no
 * variety of tunnel entrances): a steam line's in the local stone, pillars, a round arch, keystone and coping; a
 * streamline railway's the same arch in brick with stone dressings; a modern line's a square concrete box mouth
 * under a deep header, wing walls stepping down either side.
 */
function portal(k: Kit, w: World, q: PathPoint, out: number, era: RailEra): void {
  k.place(q.x, q.y, q.z, Math.atan2(q.tx * out, q.tz * out));
  if (era === 'modern') { boxPortal(k); return; }
  const stone = rockOf(w, q.x, q.z);
  const col = era === 'streamline' ? BRICK : stone, light = era === 'streamline' ? scale(stone, 1.2) : scale(col, 1.12), dark = scale(col, 0.82);
  const base = -0.35, top = 1.0, R = 0.3, spring = 0.3, D = 0.3;
  // pillars either side of the opening
  for (const sx of [-1, 1]) k.box(sx * 0.5, base, -D / 2, 0.4, top - base, D, col, light);
  // the stone over the arch, a wedge per step round it
  const SEG = 6;
  for (let j = 0; j < SEG; j++) {
    const a0 = Math.PI - (j / SEG) * Math.PI, a1 = Math.PI - ((j + 1) / SEG) * Math.PI;
    const x0 = Math.cos(a0) * R, y0 = spring + Math.sin(a0) * R, x1 = Math.cos(a1) * R, y1 = spring + Math.sin(a1) * R;
    const I: P3 = [(x0 + x1) / 2, top + 0.5, -D / 2];
    k.quad([x0, y0, 0], [x1, y1, 0], [x1, top, 0], [x0, top, 0], col, [(x0 + x1) / 2, (y0 + top) / 2, -1]);
    k.quad([x0, y0, 0], [x1, y1, 0], [x1, y1, -D], [x0, y0, -D], dark, I);
  }
  k.quad([-R, top, 0], [R, top, 0], [R, top, -D], [-R, top, -D], light, [0, top - 1, -D / 2]);
  // coping, keystone and a string of voussoirs picked out lighter
  k.box(0, top, -D / 2 + 0.02, 1.46, 0.07, D + 0.08, light, light);
  k.box(0, spring + R - 0.04, 0.02, 0.09, 0.13, 0.05, light, light);
  for (const sx of [-1, 1]) k.box(sx * (R + 0.02), spring - 0.02, 0.012, 0.07, 0.05, 0.03, light);
  // the dark mouth
  const mouth: P3 = [0, 0.2, 0.5];
  k.quad([-R, base, -D + 0.02], [R, base, -D + 0.02], [R, spring, -D + 0.02], [-R, spring, -D + 0.02], VOID, [0, 0.2, -2]);
  for (let j = 0; j < SEG; j++) {
    const a0 = (j / SEG) * Math.PI, a1 = ((j + 1) / SEG) * Math.PI;
    k.tri([0, spring, -D + 0.02], [Math.cos(a0) * R, spring + Math.sin(a0) * R, -D + 0.02], [Math.cos(a1) * R, spring + Math.sin(a1) * R, -D + 0.02], VOID, [0, spring, -2]);
  }
  // the lining of the bore, so the hill never shows through the mouth
  k.quad([-R, base, -D], [-R, spring, -D], [-R, spring, 0], [-R, base, 0], dark, mouth);
  k.quad([R, base, -D], [R, spring, -D], [R, spring, 0], [R, base, 0], dark, mouth);
  // wing walls sloping back into the cutting sides
  for (const sx of [-1, 1]) {
    const xi = sx * 0.7, xo = sx * 1.15;
    k.quad([xi, base, 0], [xo, base, 0.45], [xo, 0.25, 0.45], [xi, top, 0], col, [sx * 0.9, 0.3, -1]);
    k.quad([xi, top, 0], [xo, 0.25, 0.45], [xo, 0.25, 0.3], [xi, top, -0.15], light, [sx * 0.9, -1, 0]);
  }
  k.place(0, 0, 0, 0);
}

/** A modern line's portal (placed by portal): a square concrete mouth, a deep header with a cast band, stepped wings. */
function boxPortal(k: Kit): void {
  const base = -0.35, W = 0.36, H = 0.72, D = 0.34;
  // the dark of the bore, and the lining just inside it
  k.quad([-W, base, -D + 0.02], [W, base, -D + 0.02], [W, H, -D + 0.02], [-W, H, -D + 0.02], VOID, [0, 0.2, -2]);
  for (const sx of [-1, 1]) k.quad([sx * W, base, -D], [sx * W, H, -D], [sx * W, H, 0], [sx * W, base, 0], CONCRETE_DARK, [0, 0.2, 0.5]);
  k.quad([-W, H, -D], [W, H, -D], [W, H, 0], [-W, H, 0], CONCRETE_DARK, [0, 0, -D / 2]);
  // the frame: side walls and the header over them, a darker cast band across its face
  for (const sx of [-1, 1]) k.box(sx * (W + 0.14), base, -D / 2, 0.28, H + 0.45 - base, D, CONCRETE, CONCRETE_DARK);
  k.box(0, H, -D / 2, W * 2 + 0.56, 0.45, D, CONCRETE, CONCRETE_DARK);
  k.box(0, H + 0.16, 0.005, W * 2 + 0.5, 0.1, 0.02, CONCRETE_DARK);
  // wing walls stepping down into the cutting either side
  for (const sx of [-1, 1]) {
    k.box(sx * (W + 0.5), base, -0.05, 0.44, 0.85 - base, 0.2, CONCRETE, CONCRETE_DARK);
    k.box(sx * (W + 0.92), base, 0.05, 0.4, 0.35 - base, 0.2, CONCRETE, CONCRETE_DARK);
  }
  k.place(0, 0, 0, 0);
}

// ---------------- level crossings ----------------

interface CrossTile { x: number; z: number; y: number; n: number; tx: number; tz: number }
const crossCache = new WeakMap<World, { rev: number; tiles: Map<number, CrossTile> }>();

/** Every crossing tile on the cell, with the track's centre and heading through it (cached per revision). */
function crossTiles(w: World): Map<number, CrossTile> {
  const c = crossCache.get(w);
  // a road laid or cleared changes the count of roads; growth bumps the revision
  const rev = w.revision * 65536 + w.roads.length;
  if (c && c.rev === rev) return c.tiles;
  const tiles = new Map<number, CrossTile>();
  for (const p of w.rails) {
    if (p.kind === 'loop') continue;
    const n = p.s.length;
    for (let i = 0; i < n; i++) {
      const x = p.xz[i * 2], z = p.xz[i * 2 + 1];
      const tx = Math.floor(x), tz = Math.floor(z);
      if (!inB(tx, tz)) continue;
      const t = idx(tx, tz);
      // no barriers under a road that flies over the line on a deck
      if (!(w.rail[t] & RailBit.Track) || !w.road[t] || w.deckAxis[t] || w.rail[t] & (RailBit.Deck | RailBit.Tunnel)) continue;
      const u = p.under[i];
      if (u !== Under.Ground && u !== Under.Embank && u !== Under.Cutting) continue;
      let e = tiles.get(t);
      if (!e) tiles.set(t, (e = { x: 0, z: 0, y: 0, n: 0, tx: 0, tz: 0 }));
      const a = Math.max(0, i - 1), b = Math.min(n - 1, i + 1);
      const dx = p.xz[b * 2] - p.xz[a * 2], dz = p.xz[b * 2 + 1] - p.xz[a * 2 + 1];
      // headings summed the same way round so they don't cancel
      const flip = e.n && dx * e.tx + dz * e.tz < 0 ? -1 : 1;
      e.x += x; e.z += z; e.y += p.y[i]; e.tx += dx * flip; e.tz += dz * flip; e.n++;
    }
  }
  for (const e of tiles.values()) {
    e.x /= e.n; e.z /= e.n; e.y /= e.n;
    const l = Math.hypot(e.tx, e.tz) || 1;
    e.tx /= l; e.tz /= l;
  }
  crossCache.set(w, { rev, tiles });
  return tiles;
}

function lampMesh(x: number, y: number, z: number, yaw: number): THREE.Mesh {
  const m = new THREE.Mesh(new THREE.BoxGeometry(0.06, 0.06, 0.025), LAMP_OFF);
  m.position.set(x, y, z);
  m.rotation.y = yaw;
  return m;
}

function crossings(
  k: Kit, w: World, inChunk: (x: number, z: number) => boolean,
  extras: THREE.Object3D[], keys: { crossings: string[]; owner: object },
): void {
  const tiles = crossTiles(w);
  if (!tiles.size) return;
  for (const [t, e] of tiles) {
    const tx = t % N, tz = (t - tx) / N;
    // a crossing is a run of such tiles along the track; the first one draws it
    const alongX = Math.abs(e.tx) >= Math.abs(e.tz);
    const [sx, sz] = alongX ? [1, 0] : [0, 1];
    if (inB(tx - sx, tz - sz) && tiles.has(idx(tx - sx, tz - sz))) continue;
    if (!inChunk(tx + 0.5, tz + 0.5)) continue;
    const run = [t];
    let roadType = w.road[t];
    for (let m = 1; m < 4 && inB(tx + sx * m, tz + sz * m) && tiles.has(idx(tx + sx * m, tz + sz * m)); m++) {
      const u = idx(tx + sx * m, tz + sz * m);
      run.push(u);
      roadType = Math.max(roadType, w.road[u]);
    }
    const last = tiles.get(run[run.length - 1])!;
    const ys = run.map((u) => tiles.get(u)!.y);
    const y = ys.reduce((a, b) => a + b, 0) / ys.length;
    // the centre of the run, on the track
    const cxr = (e.x + last.x) / 2, czr = (e.z + last.z) / 2;
    const width = ROAD_INFO[roadType]?.width ?? 0.6;
    const L = Math.min(run.length, width + 0.12);
    const yaw = Math.atan2(e.tx, e.tz); // local +z along the track, local +x across it
    const surface = roadType <= 1 ? DIRT : roadType === 2 ? BRICK : ASPHALT;
    k.place(cxr, 0, czr, yaw);
    // planks between and beside the rails, and a ramp of road up to them either side
    k.box(0, y - 0.04, 0, 0.72, 0.03, L, PLANK, PLANK);
    for (const side of [-1, 1]) {
      // the ramp runs out further the higher the rails sit over the road
      const rise = y - k.ground(side * 0.7, 0);
      const xi = side * 0.36, xo = side * (0.36 + Math.min(1.1, Math.max(0.3, rise * 2)));
      const g0 = k.ground(xo, -L / 2) + 0.045, g1 = k.ground(xo, L / 2) + 0.045;
      k.quad([xi, y - 0.006, -L / 2], [xi, y - 0.006, L / 2], [xo, g1, L / 2], [xo, g0, -L / 2], surface, [side * 0.5, -1, 0]);
    }
    for (let q = -1; q <= 1; q += 2) k.box(0, y - 0.006, q * 0.07 * L, 0.72, 0.002, 0.012, scale(PLANK, 0.8));
    const barriers = roadType >= 4;
    const lamps: THREE.Mesh[] = [];
    const arms: THREE.Object3D[] = [];
    const cy = Math.cos(yaw), sy = Math.sin(yaw);
    const world = (lx: number, lz: number): [number, number] => [cxr + lx * cy + lz * sy, czr - lx * sy + lz * cy];
    for (const side of [-1, 1]) {
      // crossbuck on the road's verge, diagonally opposite corners
      const lx = side * 0.66, lz = -side * (L / 2 + 0.12);
      const g = k.ground(lx, lz);
      k.box(lx, g, lz, 0.03, 0.62, 0.03, WHITE);
      const cyb = g + 0.52;
      k.bar([lx + side * 0.02, cyb - 0.09, lz - 0.1], [lx + side * 0.02, cyb + 0.09, lz + 0.1], 0.011, WHITE);
      k.bar([lx + side * 0.02, cyb - 0.09, lz + 0.1], [lx + side * 0.02, cyb + 0.09, lz - 0.1], 0.011, WHITE);
      if (!barriers) continue;
      // twin lamps under the cross, facing the road both ways
      for (const face of [-1, 1]) {
        for (const dz of [-0.05, 0.05]) {
          const [wx, wz] = world(lx + face * 0.025, lz + dz);
          lamps.push(lampMesh(wx, g + 0.36, wz, yaw + Math.PI / 2));
        }
      }
      k.box(lx, g + 0.33, lz, 0.03, 0.08, 0.16, POST);
      // a barrier post just behind, its arm reaching across the near half of the road
      const bx = side * 0.9, bz = lz;
      const bg = k.ground(bx, bz);
      k.box(bx, bg, bz, 0.06, 0.34, 0.06, WHITE);
      k.box(bx, bg + 0.24, bz, 0.08, 0.1, 0.08, POST);
      const len = L / 2 + 0.05;
      const [hx, hz] = world(bx, bz);
      const dirx = e.tx * side, dirz = e.tz * side; // along the track, toward the road's middle
      const hinge = new THREE.Object3D();
      const pivot = new THREE.Object3D();
      pivot.position.set(hx, bg + 0.29, hz);
      pivot.rotation.y = Math.atan2(-dirz, dirx);
      pivot.add(hinge);
      const armBuf = new TrackBuf();
      const stripes = 5;
      for (let s = 0; s < stripes; s++) {
        const a = 0.04 + (len * s) / stripes, b = 0.04 + (len * (s + 1)) / stripes;
        armBuf.obox((a + b) / 2, -0.015, 0, 1, 0, b - a, 0.028, 0.03, s % 2 ? WHITE : ARM_RED);
      }
      armBuf.obox(-0.05, -0.02, 0, 1, 0, 0.1, 0.04, 0.04, POST);
      const armMesh = armBuf.mesh(trackMaterial);
      if (armMesh) { armMesh.castShadow = true; hinge.add(armMesh); }
      arms.push(hinge);
      extras.push(pivot);
    }
    if (!barriers && !lamps.length) continue;
    const parts: CrossingParts = { arms, lamps, armed: false, lowered: 0, owner: keys.owner };
    const st = crossingState.get(crossingKey(w, t));
    if (st) { parts.armed = st.armed; parts.lowered = st.lowered; }
    poseCrossing(parts);
    extras.push(...lamps);
    for (const u of run) {
      const key = crossingKey(w, u);
      railCrossings.set(key, parts);
      keys.crossings.push(key);
      const s2 = crossingState.get(key);
      if (s2 && u !== t) { parts.armed = s2.armed; parts.lowered = s2.lowered; poseCrossing(parts); }
    }
  }
}

// ---------------- signals ----------------

function signals(
  k: Kit, w: World, inChunk: (x: number, z: number) => boolean,
  extras: THREE.Object3D[], keys: { signals: string[]; owner: object },
): void {
  w.stations.forEach((st, si) => {
    const p = w.rails[st.path];
    if (!p) return;
    for (const end of [0, 1] as const) {
      const s = end === 0 ? st.s0 - 0.95 : st.s1 + 0.95;
      if (s < 0 || s > p.length) continue;
      const q = pathAt(p, s);
      const out = end === 0 ? -1 : 1;
      const o = st.side * 0.46;
      const x = q.x - q.tz * o, z = q.z + q.tx * o;
      if (!inChunk(x, z)) continue;
      const yaw = Math.atan2(q.tx * out, q.tz * out); // local +z faces the trains coming in
      const g = Math.min(heightAt(w, x, z), q.y - 0.08);
      const cy = Math.cos(yaw), sy = Math.sin(yaw);
      const world = (lx: number, ly: number, lz: number): [number, number, number] => [x + lx * cy + lz * sy, g + ly, z - lx * sy + lz * cy];
      k.place(x, g, z, yaw);
      k.box(0, -0.05, 0, 0.1, 0.06, 0.1, hex(0x8a8580));
      let red: THREE.Mesh, green: THREE.Mesh, arm: THREE.Object3D | null = null;
      if (st.era === 'steam') {
        // a white lattice post, a finial, and a red semaphore arm reaching away from the track
        k.box(0, 0, 0, 0.04, 0.95, 0.04, WHITE);
        k.cone(0, 0.95, 0, 0.035, 0.07, POST, 4);
        k.box(0, 0.25, 0.03, 0.02, 0.5, 0.012, POST); // ladder
        const [px, py, pz] = world(0, 0.8, 0.035);
        const pivot = new THREE.Object3D();
        pivot.position.set(px, py, pz);
        // the arm's +x points away from the track: along the normal on the station's side
        const ax = -q.tz * st.side, az = q.tx * st.side;
        pivot.rotation.y = Math.atan2(-az, ax);
        const hinge = new THREE.Object3D();
        pivot.add(hinge);
        const b = new TrackBuf();
        b.obox(0.14, -0.025, 0, 1, 0, 0.24, 0.012, 0.05, SEM_RED);
        b.obox(0.2, -0.026, 0, 1, 0, 0.03, 0.013, 0.052, WHITE);
        const mesh = b.mesh(trackMaterial);
        if (mesh) { mesh.castShadow = true; hinge.add(mesh); }
        arm = hinge;
        extras.push(pivot);
        red = lampMesh(...world(0, 0.72, 0.03), yaw);
        green = lampMesh(...world(0, 0.66, 0.03), yaw);
      } else {
        // a mast with a black head, a hood over each lamp
        k.box(0, 0, 0, 0.035, 0.7, 0.035, st.era === 'modern' ? hex(0x9aa0a6) : POST);
        k.box(0, 0.62, 0, 0.09, 0.2, 0.05, SIGNAL_HEAD);
        k.box(0, 0.785, 0.035, 0.07, 0.01, 0.03, SIGNAL_HEAD);
        k.box(0, 0.715, 0.035, 0.07, 0.01, 0.03, SIGNAL_HEAD);
        red = lampMesh(...world(0, 0.75, 0.03), yaw);
        green = lampMesh(...world(0, 0.68, 0.03), yaw);
      }
      k.place(0, 0, 0, 0);
      const key = signalKey(w, si, end);
      const parts: SignalParts = { aspect: 'green', red, green, arm, owner: keys.owner };
      poseSignal(parts, signalState.get(key) ?? 'green');
      railSignals.set(key, parts);
      keys.signals.push(key);
      extras.push(red, green);
    }
  });
}
